        // ============================================
        // Stable App Data Folder
        // ============================================
        // Keeps customer settings, Quick URLs, licence state, history, and WebView2 data
        // in one stable Lex & White Studios folder so app updates do not wipe them.

        private static string GetStableAppDataFolder()
        {
            try
            {
                string userProfile = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);

                if (string.IsNullOrWhiteSpace(userProfile))
                    userProfile = Environment.GetEnvironmentVariable("USERPROFILE") ?? "";

                string folder = !string.IsNullOrWhiteSpace(userProfile)
                    ? Path.Combine(userProfile, "AppData", "Local", "LexAndWhiteStudios", "LexDeskPro")
                    : Path.Combine(
                        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                        "LexAndWhiteStudios",
                        "LexDeskPro");

                Directory.CreateDirectory(folder);
                return folder;
            }
            catch
            {
                string fallback = Path.Combine(
                    Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                    "LexAndWhiteStudios",
                    "LexDeskPro");

                Directory.CreateDirectory(fallback);
                return fallback;
            }
        }

        private static readonly string AppDataFolder = GetStableAppDataFolder();

        // ============================================================
        // V1 RELEASE HARDENING - DEVELOPER DIAGNOSTICS
        // ============================================================
        // Developer diagnostics are compiled on only for DEBUG builds.
        // A public RELEASE build keeps all customer functionality but cannot
        // enable the diagnostic hotkeys/logging merely because a debugger is attached.
        private static bool LexDeskDeveloperDiagnosticsEnabled
        {
            get
            {
#if DEBUG
                return true;
#else
                return false;
#endif
            }
        }

        // Final Polish: shared JSON settings.
        // JsonSerializerOptions becomes read-only after first use, so these configured
        // instances are safe to reuse across LexDesk save/load operations.
        private static readonly JsonSerializerOptions JsonIndentedOptions = new()
        {
            WriteIndented = true
        };

        private static readonly JsonSerializerOptions JsonCaseInsensitiveOptions = new()
        {
            PropertyNameCaseInsensitive = true
        };

        private static string AppDataPath(params string[] parts)
        {
            return Path.Combine(new[] { AppDataFolder }.Concat(parts).ToArray());
        }

        // ============================================
        // LexDesk Calendar Events
        // ============================================

        private sealed class LexDeskCalendarEvent
        {
            public string Id { get; set; } = Guid.NewGuid().ToString("N");

            public string Title { get; set; } = "";

            public DateTime StartLocal { get; set; } = DateTime.Now;

            public DateTime? EndLocal { get; set; }

            public bool AllDay { get; set; }

            public string Notes { get; set; } = "";

            public string Link { get; set; } = "";

            public bool ReminderEnabled { get; set; } = true;

            public int ReminderMinutesBefore { get; set; } = 30;
        }

        private readonly string _lexDeskCalendarEventsPath =
            AppDataPath("calendar_events.json");

        private readonly List<LexDeskCalendarEvent> _lexDeskCalendarEvents = new();

        private bool _lexDeskCalendarEventsLoaded;

        private string _lexDeskInAppReminderEventId = "";

        private readonly DispatcherTimer _lexDeskInAppReminderTimer =
    new DispatcherTimer
    {
        Interval = TimeSpan.FromSeconds(1)
    };

        private bool _lexDeskInAppReminderTimerHooked;

        private readonly HashSet<string>
            _lexDeskInAppReminderShown =
                new(StringComparer.Ordinal);

        private void LoadLexDeskCalendarEvents()
        {
            if (_lexDeskCalendarEventsLoaded)
                return;

            _lexDeskCalendarEventsLoaded = true;
            _lexDeskCalendarEvents.Clear();

            try
            {
                if (!File.Exists(_lexDeskCalendarEventsPath))
                    return;

                string json = File.ReadAllText(_lexDeskCalendarEventsPath);

                var saved =
                    JsonSerializer.Deserialize<List<LexDeskCalendarEvent>>(
                        json,
                        JsonCaseInsensitiveOptions);

                if (saved == null)
                    return;

                foreach (LexDeskCalendarEvent item in saved)
                {
                    if (item == null)
                        continue;

                    if (string.IsNullOrWhiteSpace(item.Id))
                        item.Id = Guid.NewGuid().ToString("N");

                    item.Title = (item.Title ?? "").Trim();
                    item.Notes = (item.Notes ?? "").Trim();
                    item.Link = (item.Link ?? "").Trim();

                    if (string.IsNullOrWhiteSpace(item.Title))
                        continue;

                    if (item.ReminderMinutesBefore < 0)
                        item.ReminderMinutesBefore = 0;

                    _lexDeskCalendarEvents.Add(item);
                }

                _lexDeskCalendarEvents.Sort(
                    (left, right) =>
                        left.StartLocal.CompareTo(right.StartLocal));
            }
            catch
            {
                _lexDeskCalendarEvents.Clear();
            }
        }

        private bool SaveLexDeskCalendarEvents()
        {
            try
            {
                Directory.CreateDirectory(
                    Path.GetDirectoryName(_lexDeskCalendarEventsPath)!);

                _lexDeskCalendarEvents.Sort(
                    (left, right) =>
                        left.StartLocal.CompareTo(right.StartLocal));

                string json = JsonSerializer.Serialize(
                    _lexDeskCalendarEvents,
                    JsonIndentedOptions);

                File.WriteAllText(
                    _lexDeskCalendarEventsPath,
                    json);

                return true;
            }
            catch
            {
                return false;
            }
        }

        // ============================================
        // LexDesk In-App Calendar Reminder
        // ============================================

        private void StartLexDeskInAppCalendarReminderTimer()
        {
            try
            {
                if (_lexDeskInAppReminderTimerHooked)
                    return;

                _lexDeskInAppReminderTimerHooked = true;

                _lexDeskInAppReminderTimer.Tick += (_, __) =>
                {
                    CheckLexDeskInAppCalendarReminders();
                };

                _lexDeskInAppReminderTimer.Start();
            }
            catch
            {
                // Reminder timer must never interfere with LexDesk.
            }
        }

        private void CheckLexDeskInAppCalendarReminders()
        {
            try
            {
                // Only use the LexDesk card while the user is
                // actually working inside LexDesk.
                if (!IsVisible ||
                    WindowState == WindowState.Minimized ||
                    !IsActive)
                {
                    return;
                }

                if (LexDeskInAppReminderPopup == null)
                    return;

                // Let the current reminder stay visible until
                // the customer dismisses it or opens its link.
                if (LexDeskInAppReminderPopup.IsOpen)
                {
                    return;
                }

                LoadLexDeskCalendarEvents();

                DateTime now =
                    DateTime.Now;

                LexDeskCalendarEvent? dueEvent =
                    null;

                foreach (LexDeskCalendarEvent calendarEvent
                         in _lexDeskCalendarEvents)
                {
                    if (!calendarEvent.ReminderEnabled)
                        continue;

                    if (string.IsNullOrWhiteSpace(
                            calendarEvent.Id))
                    {
                        continue;
                    }

                    if (_lexDeskInAppReminderShown.Contains(
                            calendarEvent.Id))
                    {
                        continue;
                    }

                    DateTime startLocal =
                        DateTime.SpecifyKind(
                            calendarEvent.StartLocal,
                            DateTimeKind.Local);

                    int reminderMinutes =
                        Math.Max(
                            0,
                            calendarEvent.ReminderMinutesBefore);

                    DateTime reminderTime =
                        startLocal.AddMinutes(
                            -reminderMinutes);

                    // Check one second ahead so LexDesk can cancel
                    // the Windows toast before Windows displays it.
                    if (reminderTime >
                        now.AddSeconds(1))
                    {
                        continue;
                    }

                    // Allow a little breathing room if Windows or the WPF
                    // UI thread was busy at the exact reminder second.
                    // We still reject genuinely old reminders.
                    if (reminderTime <
                        now.AddSeconds(-90))
                    {
                        continue;
                    }

                    dueEvent =
                        calendarEvent;

                    break;
                }

                if (dueEvent == null)
                    return;

                // LexDesk is active, so use our own reminder card
                // instead of displaying both LexDesk and Windows reminders.
                ShowLexDeskInAppCalendarReminder(
    dueEvent);

                // Only retire the Windows reminder and mark this event
                // as shown after our LexDesk popup successfully opened.
                if (LexDeskInAppReminderPopup != null &&
                    LexDeskInAppReminderPopup.IsOpen)
                {
                    CancelLexDeskCalendarReminder(
                        dueEvent);

                    _lexDeskInAppReminderShown.Add(
                        dueEvent.Id);
                }
            }
            catch
            {
                // Reminder checking must never affect normal browsing.
            }
        }

        private void ShowLexDeskInAppCalendarReminder(
            LexDeskCalendarEvent calendarEvent)
        {
            try
            {
                if (calendarEvent == null ||
                    LexDeskInAppReminderPopup == null)
                {
                    return;
                }

                _lexDeskInAppReminderEventId =
                    calendarEvent.Id ?? "";

                LexDeskInAppReminderTitleText.Text =
                    calendarEvent.Title;

                LexDeskInAppReminderTimeText.Text =
                    calendarEvent.AllDay
                        ? calendarEvent.StartLocal.ToString(
                            "dddd, d MMMM yyyy")
                        : calendarEvent.StartLocal.ToString(
                            "dddd, d MMMM yyyy 'at' h:mm tt");

                string notes =
                    (calendarEvent.Notes ?? "").Trim();

                LexDeskInAppReminderNotesText.Text =
                    notes;

                LexDeskInAppReminderNotesText.Visibility =
                    string.IsNullOrWhiteSpace(notes)
                        ? Visibility.Collapsed
                        : Visibility.Visible;

                string link =
                    (calendarEvent.Link ?? "").Trim();

                bool hasValidLink =
                    Uri.TryCreate(
                        link,
                        UriKind.Absolute,
                        out Uri? uri) &&
                    (uri.Scheme == Uri.UriSchemeHttp ||
                     uri.Scheme == Uri.UriSchemeHttps);

                LexDeskInAppReminderOpenLinkButton.Visibility =
                    hasValidLink
                        ? Visibility.Visible
                        : Visibility.Collapsed;

                LexDeskInAppReminderPopup.PlacementTarget =
                    LexDeskClockButton;

                LexDeskInAppReminderPopup.IsOpen = true;
            }
            catch
            {
                // An in-app reminder must never affect LexDesk.
            }
        }

        private void HideLexDeskInAppCalendarReminder()
        {
            try
            {
                _lexDeskInAppReminderEventId = "";

                if (LexDeskInAppReminderPopup != null)
                {
                    LexDeskInAppReminderPopup.IsOpen = false;
                }
            }
            catch
            {
            }
        }

        private void LexDeskInAppReminderDismiss_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            HideLexDeskInAppCalendarReminder();
        }

        private void LexDeskInAppReminderOpenLink_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            try
            {
                string eventId =
                    _lexDeskInAppReminderEventId;

                if (string.IsNullOrWhiteSpace(eventId))
                    return;

                LoadLexDeskCalendarEvents();

                LexDeskCalendarEvent? calendarEvent =
                    _lexDeskCalendarEvents
                        .FirstOrDefault(item =>
                            string.Equals(
                                item.Id,
                                eventId,
                                StringComparison.Ordinal));

                if (calendarEvent == null)
                {
                    HideLexDeskInAppCalendarReminder();
                    return;
                }

                HideLexDeskInAppCalendarReminder();

                OpenLexDeskCalendarEventLink(
                    calendarEvent);
            }
            catch
            {
                HideLexDeskInAppCalendarReminder();
            }
        }

        // ============================================
        // LexDesk Calendar Reminder Scheduling
        // ============================================

        private const string LexDeskCalendarReminderGroup =
            "LexDeskCalendar";


        private Windows.UI.Notifications.NotificationSetting?
    GetLexDeskCalendarNotificationSetting()
        {
            try
            {
                return ToastNotificationManagerCompat
                    .CreateToastNotifier()
                    .Setting;
            }
            catch
            {
                return null;
            }
        }

        private bool LexDeskCalendarNotificationsEnabled()
        {
            return GetLexDeskCalendarNotificationSetting() ==
                Windows.UI.Notifications.NotificationSetting.Enabled;
        }

        private void RefreshLexDeskCalendarNotificationStatus()
        {
            try
            {
                if (LexDeskCalendarNotificationButton == null)
                    return;

                Windows.UI.Notifications.NotificationSetting? setting =
                    GetLexDeskCalendarNotificationSetting();

                LexDeskCalendarNotificationButton.IsEnabled = true;

                switch (setting)
                {
                    case Windows.UI.Notifications.NotificationSetting.Enabled:
                        LexDeskCalendarNotificationButton.Visibility =
                            Visibility.Collapsed;

                        LexDeskCalendarNotificationButton.ToolTip = null;
                        break;

                    case Windows.UI.Notifications.NotificationSetting.DisabledForUser:
                        LexDeskCalendarNotificationButton.Visibility =
                            Visibility.Visible;

                        LexDeskCalendarNotificationButton.Content =
                            "Reminders Off - Turn On";

                        LexDeskCalendarNotificationButton.ToolTip =
                            "Windows notifications are turned off. " +
                            "Click here to turn them on.";
                        break;

                    case Windows.UI.Notifications.NotificationSetting.DisabledForApplication:
                        LexDeskCalendarNotificationButton.Visibility =
                            Visibility.Visible;

                        LexDeskCalendarNotificationButton.Content =
                            "LexDesk Reminders Off";

                        LexDeskCalendarNotificationButton.ToolTip =
                            "Notifications for LexDesk are turned off in Windows. " +
                            "Click here to turn them on.";
                        break;

                    case Windows.UI.Notifications.NotificationSetting.DisabledByGroupPolicy:
                        LexDeskCalendarNotificationButton.Visibility =
                            Visibility.Visible;

                        LexDeskCalendarNotificationButton.Content =
                            "Reminders Blocked by Windows";

                        LexDeskCalendarNotificationButton.IsEnabled = false;

                        LexDeskCalendarNotificationButton.ToolTip =
                            "Windows administrator settings are preventing notifications.";
                        break;

                    case Windows.UI.Notifications.NotificationSetting.DisabledByManifest:
                        LexDeskCalendarNotificationButton.Visibility =
                            Visibility.Visible;

                        LexDeskCalendarNotificationButton.Content =
                            "Reminders Unavailable";

                        LexDeskCalendarNotificationButton.IsEnabled = false;

                        LexDeskCalendarNotificationButton.ToolTip =
                            "LexDesk notification setup needs repair.";
                        break;

                    default:
                        LexDeskCalendarNotificationButton.Visibility =
                            Visibility.Visible;

                        LexDeskCalendarNotificationButton.Content =
                            "Reminder Status Unavailable";

                        LexDeskCalendarNotificationButton.IsEnabled = false;

                        LexDeskCalendarNotificationButton.ToolTip =
                            "LexDesk could not read the Windows notification status.";
                        break;
                }
            }
            catch
            {
                // Notification status must never affect the calendar.
            }
        }

        private void LexDeskCalendarNotificationButton_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            try
            {
                LexDeskOpenExternal(
                    "ms-settings:notifications");
            }
            catch
            {
                ShowLexDeskMessageBox(
                    "LexDesk could not open Windows notification settings.",
                    "Calendar Reminders",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

        private void WarnIfLexDeskCalendarRemindersUnavailable()
        {
            Windows.UI.Notifications.NotificationSetting? setting =
                GetLexDeskCalendarNotificationSetting();

            RefreshLexDeskCalendarNotificationStatus();

            if (setting ==
                Windows.UI.Notifications.NotificationSetting.Enabled)
            {
                return;
            }

            if (setting ==
                    Windows.UI.Notifications.NotificationSetting.DisabledForUser ||
                setting ==
                    Windows.UI.Notifications.NotificationSetting.DisabledForApplication)
            {
                MessageBoxResult answer =
                    ShowLexDeskMessageBox(
                        "Your calendar event was saved, but Windows notifications are turned off.\n\n" +
                        "LexDesk cannot display calendar reminders until notifications are enabled.\n\n" +
                        "Open Windows notification settings now?",
                        "Calendar Reminders",
                        MessageBoxButton.YesNo,
                        MessageBoxImage.Information);

                if (answer == MessageBoxResult.Yes)
                {
                    LexDeskOpenExternal(
                        "ms-settings:notifications");
                }

                return;
            }

            if (setting ==
                Windows.UI.Notifications.NotificationSetting.DisabledByGroupPolicy)
            {
                ShowLexDeskMessageBox(
                    "Your calendar event was saved, but Windows administrator settings are blocking notifications.",
                    "Calendar Reminders",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);

                return;
            }

            if (setting ==
                Windows.UI.Notifications.NotificationSetting.DisabledByManifest)
            {
                ShowLexDeskMessageBox(
                    "Your calendar event was saved, but reminders are currently unavailable in this LexDesk installation.",
                    "Calendar Reminders",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);

                return;
            }

            ShowLexDeskMessageBox(
                "Your calendar event was saved, but LexDesk could not confirm that Windows reminders are available.",
                "Calendar Reminders",
                MessageBoxButton.OK,
                MessageBoxImage.Information);
        }

        private bool ScheduleLexDeskCalendarReminder(
    LexDeskCalendarEvent calendarEvent)
        {
            try
            {
                if (calendarEvent == null)
                    return false;

                if (!calendarEvent.ReminderEnabled)
                    return true;

                if (string.IsNullOrWhiteSpace(calendarEvent.Id))
                    return false;

                DateTime localStart =
                    DateTime.SpecifyKind(
                        calendarEvent.StartLocal,
                        DateTimeKind.Local);

                // Do not schedule reminders for events
                // that are already over.
                if (localStart <= DateTime.Now)
                    return false;

                int reminderMinutes =
                    Math.Max(
                        0,
                        calendarEvent.ReminderMinutesBefore);

                DateTimeOffset deliveryTime =
                    new DateTimeOffset(localStart)
                        .AddMinutes(-reminderMinutes);

                // If the selected reminder point has already passed
                // but the event itself is still ahead, notify shortly
                // after the event is saved instead.
                if (deliveryTime <=
                    DateTimeOffset.Now.AddSeconds(2))
                {
                    deliveryTime =
                        DateTimeOffset.Now.AddSeconds(5);
                }

                string whenText =
                    calendarEvent.AllDay
                        ? $"Event date: {localStart:dddd, d MMMM yyyy}"
                        : $"Starts: {localStart:dddd, d MMMM yyyy at h:mm tt}";

                var toastBuilder =
                    new ToastContentBuilder()
                        .AddArgument(
                            "action",
                            "calendar")
                        .AddArgument(
                            "eventId",
                            calendarEvent.Id)
                        .AddText(
                            "LexDesk Calendar")
                        .AddText(
                            calendarEvent.Title)
                        .AddText(
                            whenText);

                // Only show Open Link when the saved event
                // actually contains a valid web address.
                string eventLink =
                    (calendarEvent.Link ?? "").Trim();

                if (Uri.TryCreate(
                        eventLink,
                        UriKind.Absolute,
                        out Uri? eventUri) &&
                    (eventUri.Scheme == Uri.UriSchemeHttp ||
                     eventUri.Scheme == Uri.UriSchemeHttps))
                {
                    toastBuilder.AddButton(
                        new ToastButton()
                            .SetContent("Open Link")
                            .AddArgument(
                                "action",
                                "openLink")
                            .AddArgument(
                                "eventId",
                                calendarEvent.Id));
                }

                toastBuilder.Schedule(
                    deliveryTime,
                    toast =>
                    {
                        toast.Tag =
                            calendarEvent.Id;

                        toast.Group =
                            LexDeskCalendarReminderGroup;
                    });

                return true;
            }
            catch
            {
                return false;
            }
        }

        private void CancelLexDeskCalendarReminder(
            LexDeskCalendarEvent calendarEvent)
        {
            try
            {
                if (calendarEvent == null)
                    return;

                string eventId =
                    (calendarEvent.Id ?? "").Trim();

                if (string.IsNullOrWhiteSpace(eventId))
                    return;

                var notifier =
                    ToastNotificationManagerCompat
                        .CreateToastNotifier();

                var scheduled =
                    notifier
                        .GetScheduledToastNotifications();

                foreach (var notification in scheduled)
                {
                    if (!string.Equals(
                            notification.Tag,
                            eventId,
                            StringComparison.Ordinal))
                    {
                        continue;
                    }

                    if (!string.Equals(
                            notification.Group,
                            LexDeskCalendarReminderGroup,
                            StringComparison.Ordinal))
                    {
                        continue;
                    }

                    notifier.RemoveFromSchedule(
                        notification);
                }
            }
            catch
            {
                // Reminder cancellation must never affect the calendar.
            }
        }

        private static void MigrateLegacyAppDataToStableFolder()
        {
            try
            {
                Directory.CreateDirectory(AppDataFolder);

                string userProfile = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);

                if (string.IsNullOrWhiteSpace(userProfile))
                    userProfile = Environment.GetEnvironmentVariable("USERPROFILE") ?? "";

                string realLocalAppData = !string.IsNullOrWhiteSpace(userProfile)
                    ? Path.Combine(userProfile, "AppData", "Local")
                    : Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);

                var candidateFolders = new List<string>();

                // Old non-packaged / direct local app data folder.
                candidateFolders.Add(Path.Combine(realLocalAppData, "Web Studio Browser"));

                // MSIX/private package data folders from different package identities.
                string packagesRoot = Path.Combine(realLocalAppData, "Packages");

                if (Directory.Exists(packagesRoot))
                {
                    foreach (string packageFolder in Directory.EnumerateDirectories(packagesRoot))
                    {
                        string folderName = Path.GetFileName(packageFolder);

                        bool looksLikeWebProtectPackage =
                            folderName.Contains("LexDeskPro", StringComparison.OrdinalIgnoreCase) ||
                            folderName.Contains("WebStudio", StringComparison.OrdinalIgnoreCase) ||
                            folderName.Contains("Web_Studio", StringComparison.OrdinalIgnoreCase) ||
                            folderName.StartsWith("460070a3-3b14-4c3e-9665-ddd7d1fc5c94_", StringComparison.OrdinalIgnoreCase);

                        if (!looksLikeWebProtectPackage)
                            continue;

                        candidateFolders.Add(Path.Combine(packageFolder, "LocalCache", "Local", "Web Studio Browser"));
                        candidateFolders.Add(Path.Combine(packageFolder, "LocalState", "Web Studio Browser"));
                        candidateFolders.Add(Path.Combine(packageFolder, "RoamingState", "Web Studio Browser"));
                        candidateFolders.Add(Path.Combine(packageFolder, "LocalCache", "Local", "LexAndWhiteStudios", "LexDeskPro"));
                        candidateFolders.Add(Path.Combine(packageFolder, "LocalState", "LexAndWhiteStudios", "LexDeskPro"));
                    }
                }

                int copiedCount = 0;
                var copiedFrom = new List<string>();

                foreach (string sourceFolder in candidateFolders.Distinct(StringComparer.OrdinalIgnoreCase))
                {
                    try
                    {
                        if (string.IsNullOrWhiteSpace(sourceFolder))
                            continue;

                        if (!Directory.Exists(sourceFolder))
                            continue;

                        if (string.Equals(
                                Path.GetFullPath(sourceFolder).TrimEnd('\\'),
                                Path.GetFullPath(AppDataFolder).TrimEnd('\\'),
                                StringComparison.OrdinalIgnoreCase))
                            continue;

                        foreach (string sourceFile in Directory.EnumerateFiles(sourceFolder, "*", SearchOption.AllDirectories))
                        {
                            string relative = Path.GetRelativePath(sourceFolder, sourceFile);
                            string destinationFile = Path.Combine(AppDataFolder, relative);

                            // Do not overwrite newer/current customer settings.
                            if (File.Exists(destinationFile))
                                continue;

                            Directory.CreateDirectory(Path.GetDirectoryName(destinationFile)!);
                            File.Copy(sourceFile, destinationFile, overwrite: false);
                            copiedCount++;
                        }

                        copiedFrom.Add(sourceFolder);
                    }
                    catch
                    {
                        // One bad folder must not stop the rest of migration.
                    }
                }

                // Small local diagnostic file, useful while testing only.
                if (!LexDeskDeveloperDiagnosticsEnabled)
                    return;

                try
                {
                    string reportPath = Path.Combine(AppDataFolder, "migration_report.txt");

                    var lines = new List<string>
            {
                $"Migration checked UTC: {DateTime.UtcNow:O}",
                $"Stable folder: {AppDataFolder}",
                $"Files copied: {copiedCount}",
                "",
                "Source folders found:"
            };

                    lines.AddRange(copiedFrom);

                    File.WriteAllLines(reportPath, lines);
                }
                catch { }
            }
            catch
            {
                // Migration must never stop LexDesk Pro from opening.
            }
        }

        // ============================================================
        // [[FIELDS - APP STATE]]
        // Main app fields, settings, counters, tabs, privacy modes,
        // popup modes, download guard state, and feature toggles.
        // ============================================================

        // ============================================
        // LexDesk Pro - Release Hardening Notes
        // ============================================
        //
        // V1 security/privacy principles:
        //
        // - Do not store raw licence keys locally.
        // - Do not expose licence hashes, device fingerprints, or raw PC names in UI/logs.
        // - Do not log full URLs, local file paths, download links, or private customer data.
        // - Keep dangerous URI schemes blocked before navigation.
        // - Keep unexpected camera, microphone, location, notification, and clipboard requests denied.
        // - Keep high-risk, medium-risk, and unknown downloads under Download Guard control.
        // - Keep WebView2 DevTools disabled in customer builds.
        // - Keep external app launches limited to reviewed helper paths.
        //
        // Future release checks:
        //
        // - Review signing/certificate status before public release.
        // - Review update manifest and GitHub release URLs before packaging.
        // - Review privacy/legal wording on the website before launch.
        // - Review false-positive handling for Download Guard and Scam Shield.
        // - Review server-side licence API rate limits and logging privacy.

        // ============================================================
        // [[ANNOYANCE SHIELD - FIELDS]]
        // Controls in-page popup/banner cleanup.
        // This is separate from Privacy Mode and Popup Control.
        // ============================================================

        private enum AnnoyanceShieldMode
        {
            Off,
            Balanced,
            Strict
        }

        private AnnoyanceShieldMode _annoyanceShieldMode = AnnoyanceShieldMode.Balanced;

