        private void RefreshPresetButtonsUI()
        {
            Button[] buttons =
            {
        PresetBtn1, PresetBtn2, PresetBtn3, PresetBtn4, PresetBtn5,
        PresetBtn6, PresetBtn7, PresetBtn8, PresetBtn9, PresetBtn10,
        PresetBtn11, PresetBtn12, PresetBtn13, PresetBtn14, PresetBtn15,
        PresetBtn16, PresetBtn17, PresetBtn18, PresetBtn19, PresetBtn20
    };

            for (int i = 0; i < buttons.Length && i < _presetUrls.Length; i++)
            {
                string url = _presetUrls[i];

                if (string.IsNullOrWhiteSpace(url))
                {
                    buttons[i].Content = "(empty)";
                    continue;
                }

                try
                {
                    var uri = new Uri(url);
                    string host = uri.Host.Replace("www.", "");

                    string name = host
                        .Replace(".com.au", "", StringComparison.OrdinalIgnoreCase)
                        .Replace(".com", "", StringComparison.OrdinalIgnoreCase)
                        .Replace(".net", "", StringComparison.OrdinalIgnoreCase)
                        .Replace(".org", "", StringComparison.OrdinalIgnoreCase)
                        .Replace(".co.uk", "", StringComparison.OrdinalIgnoreCase);

                    if (!string.IsNullOrWhiteSpace(name))
                        name = char.ToUpper(name[0]) + name.Substring(1);

                    buttons[i].Content = string.IsNullOrWhiteSpace(name) ? host : name;
                }
                catch
                {
                    buttons[i].Content = url;
                }
            }
        }


        // ============================================
        // Appearance theme state (Light, Dark, Warm/Sand and Neon Blue customer choices)
        // ============================================

        private enum AppTheme
        {
            Light,
            Dark,
            Sand,
            NeonBlue
        }

        private int _themeIndex = (int)AppTheme.Dark;

        private void ApplyWebViewThemePreference()
        {
            bool useDarkWebTheme =
                _themeIndex == (int)AppTheme.Dark ||
                _themeIndex == (int)AppTheme.NeonBlue;

            var scheme = useDarkWebTheme
                ? CoreWebView2PreferredColorScheme.Dark
                : CoreWebView2PreferredColorScheme.Light;

            void ApplyTo(WebView2? wv)
            {
                try
                {
                    if (wv?.CoreWebView2 != null)
                        wv.CoreWebView2.Profile.PreferredColorScheme = scheme;
                }
                catch { }
            }

            ApplyTo(Web);
            ApplyTo(Web2);
            ApplyTo(Web3);
            ApplyTo(Web4);
        }

        private void ReloadVisibleWebViewsAfterThemeChange()
        {
            void Reload(WebView2? wv)
            {
                try
                {
                    if (wv?.CoreWebView2 != null)
                        wv.CoreWebView2.Reload();
                }
                catch { }
            }

            Reload(Web);
            Reload(Web2);
            Reload(Web3);
            Reload(Web4);
        }

