        private bool _lexDeskManagedWindowFocusTimerHooked;

        // Prevents the 200 ms foreground watcher from repeatedly touching
        // managed-window z-order while nothing has actually changed.
        // Repeated SetWindowPos calls make hosted Windows apps such as
        // Calculator visibly flash/flicker.
        private IntPtr _lexDeskLastObservedForegroundWindow = IntPtr.Zero;

