    AppDataPath(
        "Debug",
        "elevated_managed_tool_result.txt");

        private void StartLexDeskManagedWindowFocusTimer()
        {
            try
            {
                if (_lexDeskManagedWindowFocusTimerHooked)
                    return;

                _lexDeskManagedWindowFocusTimerHooked = true;

                WriteLexDeskManagedWindowDebug(
                    "############################################################");

                WriteLexDeskManagedWindowDebug(
                    "DIAGNOSTIC BUILD START | Managed Sessions / Layout / Close-Minimise");

                DumpLexDeskManagedSessionState(
                    "focus timer started");

                _lexDeskManagedWindowFocusTimer.Tick += (_, __) =>
                {
                    RefreshLexDeskManagedWindowActivePage();
                };

                _lexDeskManagedWindowFocusTimer.Start();
            }
            catch
            {
                // Active-page tracking must never affect normal LexDesk use.
            }
        }

        private void RefreshLexDeskManagedWindowActivePage()
        {
            try
            {
                // Pick up new dialogs / compose windows / app popups first so they
                // immediately inherit the pane of the app that created them.
                DiscoverLexDeskManagedSessionWindows();

                IntPtr foregroundWindow =
                    GetForegroundWindow();

                if (foregroundWindow == IntPtr.Zero)
                    return;

                bool foregroundChanged =
                    foregroundWindow != _lexDeskLastObservedForegroundWindow;

                _lexDeskLastObservedForegroundWindow =
                    foregroundWindow;

                IntPtr lexDeskHwnd =
                    new WindowInteropHelper(this).Handle;

                int managedPageIndex = -1;

                if (_lexDeskManagedWindowFamilyKeys.TryGetValue(
                        foregroundWindow,
                        out string? foregroundSessionKey) &&
                    !string.IsNullOrWhiteSpace(foregroundSessionKey) &&
                    _lexDeskManagedWindowPageIndexes.TryGetValue(
                        foregroundSessionKey,
                        out int familyPageIndex) &&
                    familyPageIndex >= 0 &&
                    familyPageIndex <= 3 &&
                    _paneState[familyPageIndex] == PaneLifeState.Normal)
                {
                    managedPageIndex = familyPageIndex;
                }
                else
                {
                    // Backward-compatible fallback for a managed tool registered
                    // before the family tracker knew about it.
                    foreach (var pair in _lexDeskManagedWindows.ToList())
                    {
                        IntPtr hWnd = pair.Value;

                        if (hWnd == IntPtr.Zero || !IsWindow(hWnd))
                            continue;

                        if (hWnd != foregroundWindow)
                            continue;

                        if (_lexDeskManagedWindowPageIndexes.TryGetValue(
                                pair.Key,
                                out int pageIndex) &&
                            pageIndex >= 0 &&
                            pageIndex <= 3 &&
                            _paneState[pageIndex] == PaneLifeState.Normal)
                        {
                            managedPageIndex = pageIndex;
                        }

                        break;
                    }
                }

                if (foregroundChanged)
                {
                    WriteLexDeskManagedWindowDebug(
                        $"FOREGROUND CHANGED | {DescribeLexDeskManagedWindowForDebug(foregroundWindow)}");

                    QueueLexDeskManagedSessionStateDump(
                        "foreground changed");

                    QueueLexDeskWindowsHostedSurfaceStateDump(
                        "foreground changed");

                    // When the customer clicks back into a browser pane, Windows can
                    // put LexDesk over hosted apps such as Calculator. Reassert once,
                    // not five times per second.
                    if (foregroundWindow == lexDeskHwnd)
                    {
                        RefreshLexDeskManagedWindowZOrder();
                    }
                    else if (managedPageIndex >= 0)
                    {
                        // Activating an owned classic app can pull LexDesk forward
                        // behind it. Only lift the few hosted windows that could not
                        // be attached as owned windows. This avoids Calculator flicker.
                        RefreshLexDeskManagedAssistWindowZOrder(foregroundWindow);
                    }

                    // A security-priority overlay such as Bitdefender stays visually
                    // above the LexDesk workspace while it is open. It is NOT made
                    // globally TopMost and is ignored while minimised.
                    RefreshLexDeskPriorityOverlayZOrder();
                }

                if (managedPageIndex < 0 ||
                    managedPageIndex > 3 ||
                    _activePageIndex == managedPageIndex)
                {
                    return;
                }

                _activePageIndex = managedPageIndex;

                RefreshActivePaneStatusVisual();
                UpdatePageHostBorders();
                UpdatePageModeButtonVisuals();
                UpdateSecureSiteVisual();
            }
            catch
            {
                // Foreground / popup tracking must never affect normal LexDesk use.
            }
        }

        private void EnsureFixedWorkspaceTabs()
        {
            while (_workspaces.Count < MaxWorkspaceTabs)
            {
                int index = _workspaces.Count;
                _workspaces.Add(new BrowserWorkspace { Title = $"Tab {index + 1}" });
            }

            while (_workspaces.Count > MaxWorkspaceTabs)
                _workspaces.RemoveAt(_workspaces.Count - 1);

            _workspaceTabCount = MaxWorkspaceTabs;
        }


