        // ============================================
        // LexDesk window hotkeys
        // ============================================
        // WebView2 is a child HWND, so normal WPF PreviewKeyDown does not always
        // receive shortcuts while a webpage or video player owns keyboard focus.
        // Register these two app shortcuts with Windows while LexDesk is running.
        private const int WM_HOTKEY = 0x0312;
        private const uint MOD_CONTROL = 0x0002;
        private const uint MOD_SHIFT = 0x0004;
        private const uint VK_E = 0x45;
        private const uint VK_O = 0x4F;
        private const int LexDeskEmergencyHotkeyId = 0x4C01;
        private const int LexDeskDiagnosticsHotkeyId = 0x4C02;

        [DllImport("user32.dll", SetLastError = true)]
        private static extern bool RegisterHotKey(IntPtr hWnd, int id, uint fsModifiers, uint vk);

        [DllImport("user32.dll", SetLastError = true)]
        private static extern bool UnregisterHotKey(IntPtr hWnd, int id);

        private HwndSource? _lexDeskHotkeySource;
        private IntPtr _lexDeskHotkeyWindowHandle = IntPtr.Zero;
        private bool _lexDeskEmergencyHotkeyRegistered;
        private bool _lexDeskDiagnosticsHotkeyRegistered;

        private void RegisterLexDeskWindowHotkeys()
        {
            try
            {
                if (_lexDeskHotkeyWindowHandle != IntPtr.Zero)
                    return;

                var helper = new WindowInteropHelper(this);
                IntPtr hwnd = helper.Handle;

                if (hwnd == IntPtr.Zero)
                    return;

                _lexDeskHotkeyWindowHandle = hwnd;
                _lexDeskHotkeySource = HwndSource.FromHwnd(hwnd);
                _lexDeskHotkeySource?.AddHook(LexDeskHotkeyWndProc);

                uint modifiers = MOD_CONTROL | MOD_SHIFT;

                _lexDeskEmergencyHotkeyRegistered =
                    RegisterHotKey(hwnd, LexDeskEmergencyHotkeyId, modifiers, VK_E);

                _lexDeskDiagnosticsHotkeyRegistered =
    LexDeskDeveloperDiagnosticsEnabled &&
    RegisterHotKey(
        hwnd,
        LexDeskDiagnosticsHotkeyId,
        modifiers,
        VK_O);
            }
            catch
            {
                // Hotkeys are convenience/safety features. Registration failure must
                // never stop LexDesk from opening or browsing normally.
            }
        }

        private void UnregisterLexDeskWindowHotkeys()
        {
            try
            {
                if (_lexDeskHotkeyWindowHandle != IntPtr.Zero)
                {
                    if (_lexDeskEmergencyHotkeyRegistered)
                        UnregisterHotKey(_lexDeskHotkeyWindowHandle, LexDeskEmergencyHotkeyId);

                    if (_lexDeskDiagnosticsHotkeyRegistered)
                        UnregisterHotKey(_lexDeskHotkeyWindowHandle, LexDeskDiagnosticsHotkeyId);
                }

                _lexDeskHotkeySource?.RemoveHook(LexDeskHotkeyWndProc);
            }
            catch { }
            finally
            {
                _lexDeskEmergencyHotkeyRegistered = false;
                _lexDeskDiagnosticsHotkeyRegistered = false;
                _lexDeskHotkeySource = null;
                _lexDeskHotkeyWindowHandle = IntPtr.Zero;
            }
        }

        private IntPtr LexDeskHotkeyWndProc(
            IntPtr hwnd,
            int msg,
            IntPtr wParam,
            IntPtr lParam,
            ref bool handled)
        {
            if (msg != WM_HOTKEY)
                return IntPtr.Zero;

            int id = wParam.ToInt32();

            if (id == LexDeskEmergencyHotkeyId)
            {
                handled = true;
                Dispatcher.BeginInvoke(new Action(EmergencyExit));
                return IntPtr.Zero;
            }

            if (id == LexDeskDiagnosticsHotkeyId)
            {
                handled = true;
                Dispatcher.BeginInvoke(new Action(() => _ = ToggleSiteDiagnosticsAsync()));
                return IntPtr.Zero;
            }

            return IntPtr.Zero;
        }

