        private void ApplySmartMode(SmartMode mode)
        {
            if (!HasFullUnlock())
            {
                ShowLexDeskMessageBox(
                    "Please activate LexDesk Pro to use One-click setup.",
                    "Activation Required",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            SearchEngine targetSearch;
            DnsPreset targetDns;
            string setupName;

            switch (mode)
            {
                case SmartMode.Privacy:
                    targetSearch = SearchEngine.DuckDuckGo;
                    targetDns = DnsPreset.Cloudflare;
                    setupName = "More Private";
                    break;

                case SmartMode.Speed:
                    targetSearch = SearchEngine.Google;
                    targetDns = DnsPreset.Cloudflare;
                    setupName = "Fast";
                    break;

                case SmartMode.Secure:
                    targetSearch = SearchEngine.Google;
                    targetDns = DnsPreset.Quad9;
                    setupName = "Safer";
                    break;

                case SmartMode.Custom:
                default:
                    return;
            }

            // Apply the lookup provider first. If Windows permission is cancelled,
            // do not partially apply the rest of the One-click setup.
            if (!SetDnsPreset(targetDns, showSuccessMessage: false))
                return;

            _searchEngine = targetSearch;
            _smartMode = mode;

            SaveSearchEngine();

            UpdateSearchEngineUI();
            UpdateDnsUI();
            UpdateDnsModeUi();
            UpdateSmartModeUI();

            ShowLexDeskMessageBox(
                $"{setupName} setup applied.\n\n" +
                $"Search engine: {GetSearchEngineDisplayName(targetSearch)}\n" +
                $"Website lookup provider: {GetDnsPresetDisplayName(targetDns)}\n\n" +
                "The lookup provider has been applied to Windows. " +
                "Choose Normal under Internet Protection whenever you want LexDesk Pro to restore the DNS settings it saved before making this change.",
                "One-click setup",
                MessageBoxButton.OK,
                MessageBoxImage.Information);
        }

