        private void LoadDnsMode()
        {
            try
            {
                if (!File.Exists(_dnsModePath))
                {
                    _dnsMode = DnsApplyMode.SystemWindows;
                    return;
                }

                var txt = (File.ReadAllText(_dnsModePath) ?? "").Trim();

                if (!Enum.TryParse(txt, out DnsApplyMode mode))
                {
                    _dnsMode = DnsApplyMode.SystemWindows;
                    return;
                }

                // Private/app-only DNS is kept in the source for future development,
                // but it is not exposed in the customer UI because the current
                // WebView2 implementation could not be verified reliably.
                if (mode == DnsApplyMode.AppOnlySecureDns)
                {
                    _dnsMode = DnsApplyMode.SystemWindows;
                    SaveDnsMode();
                    return;
                }

                _dnsMode = mode;
            }
            catch
            {
                _dnsMode = DnsApplyMode.SystemWindows;
            }
        }

        private void SaveDnsMode()
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_dnsModePath)!);
                File.WriteAllText(_dnsModePath, _dnsMode.ToString());
            }
            catch { }
        }

