        private string NormalizeManualBlockedSite(string input)
        {
            input = (input ?? "").Trim();

            if (string.IsNullOrWhiteSpace(input))
                return "";

            try
            {
                if (!input.Contains("://") && input.Contains("."))
                    input = "https://" + input;

                var uri = new Uri(input);

                return uri.Host
                    .Replace("www.", "", StringComparison.OrdinalIgnoreCase)
                    .Trim()
                    .ToLowerInvariant();
            }
            catch
            {
                return input
                    .Replace("www.", "", StringComparison.OrdinalIgnoreCase)
                    .Trim()
                    .ToLowerInvariant();
            }
        }

        private bool IsDangerousUriScheme(string input, out string reason)
        {
            reason = "";

            string value = (input ?? "").Trim();

            if (string.IsNullOrWhiteSpace(value))
                return false;

            try
            {
                // Block script-like input before Uri parsing.
                if (value.StartsWith("javascript:", StringComparison.OrdinalIgnoreCase))
                {
                    reason = "JavaScript link blocked";
                    return true;
                }

                if (value.StartsWith("vbscript:", StringComparison.OrdinalIgnoreCase))
                {
                    reason = "VBScript link blocked";
                    return true;
                }

                if (value.StartsWith("data:", StringComparison.OrdinalIgnoreCase))
                {
                    reason = "Data link blocked";
                    return true;
                }

                if (!Uri.TryCreate(value, UriKind.Absolute, out var uri))
                    return false;

                string scheme = uri.Scheme?.Trim().ToLowerInvariant() ?? "";

                switch (scheme)
                {
                    case "file":
                        reason = "Local file link blocked";
                        return true;

                    case "javascript":
                        reason = "JavaScript link blocked";
                        return true;

                    case "vbscript":
                        reason = "VBScript link blocked";
                        return true;

                    case "data":
                        reason = "Data link blocked";
                        return true;

                    case "ms-msdt":
                        reason = "Windows diagnostic link blocked";
                        return true;

                    case "ms-office":
                    case "ms-word":
                    case "ms-excel":
                    case "ms-powerpoint":
                    case "onenote":
                        reason = "Office app link blocked";
                        return true;

                    case "powershell":
                        reason = "PowerShell link blocked";
                        return true;

                    case "cmd":
                        reason = "Command prompt link blocked";
                        return true;

                    default:
                        return false;
                }
            }
            catch
            {
                return false;
            }
        }

        private bool IsManualBlockedSite(string urlOrHost, out string blockedHost)
        {
            blockedHost = "";

            string host = NormalizeManualBlockedSite(urlOrHost);

            if (string.IsNullOrWhiteSpace(host))
                return false;

            foreach (var item in _manualBlockedSites)
            {
                string blocked = NormalizeManualBlockedSite(item);

                if (string.IsNullOrWhiteSpace(blocked))
                    continue;

                // Blocks exact sites:
                // example.com
                //
                // Also blocks subdomains:
                // shop.example.com
                // login.example.com
                if (host.Equals(blocked, StringComparison.OrdinalIgnoreCase) ||
                    host.EndsWith("." + blocked, StringComparison.OrdinalIgnoreCase))
                {
                    blockedHost = blocked;
                    return true;
                }
            }

            return false;
        }

        private void LoadManualBlockedSites()
        {
            try
            {
                _manualBlockedSites.Clear();

                if (!File.Exists(_manualBlockedSitesPath))
                    return;

                foreach (var line in File.ReadAllLines(_manualBlockedSitesPath))
                {
                    var host = NormalizeManualBlockedSite(line);

                    if (!string.IsNullOrWhiteSpace(host))
                        _manualBlockedSites.Add(host);
                }

                RefreshBlockedSitesEditor();
            }
            catch { }
        }

        private void SaveManualBlockedSites()
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_manualBlockedSitesPath)!);
                File.WriteAllLines(_manualBlockedSitesPath, _manualBlockedSites.OrderBy(x => x));
            }
            catch { }
        }

        private void RefreshBlockedSitesEditor()
        {
            try
            {
                if (BlockedSitesEditor == null)
                    return;

                BlockedSitesEditor.Text = string.Join(Environment.NewLine, _manualBlockedSites.OrderBy(x => x));
            }
            catch { }
        }

        private void BlockedSiteAddCurrentBtn_PreviewMouseLeftButtonUp(object sender, MouseButtonEventArgs e)
        {
