        private void BlockedSite_AddCurrent_Click(object sender, RoutedEventArgs e)
        {

            var pageUrl = GetActivePaneRealUrl();
            var host = NormalizeManualBlockedSite(GetHost(pageUrl));

            if (string.IsNullOrWhiteSpace(host))
            {
                ShowLexDeskMessageBox(
                    "No website is currently open to block.",
                    "Blocked Site List",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            _manualBlockedSites.Add(host);
            SaveManualBlockedSites();
            RefreshBlockedSitesEditor();

            ShowLexDeskMessageBox(
                $"Website added to Blocked Site List:\n\n{host}",
                "Blocked Site List",
                MessageBoxButton.OK,
                MessageBoxImage.Information);
        }

        private void BlockedSite_Save_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                _manualBlockedSites.Clear();

                var lines = (BlockedSitesEditor?.Text ?? "")
                    .Split(new[] { "\r\n", "\n" }, StringSplitOptions.RemoveEmptyEntries);

                foreach (var line in lines)
                {
                    var host = NormalizeManualBlockedSite(line);

                    if (!string.IsNullOrWhiteSpace(host))
                        _manualBlockedSites.Add(host);
                }

                SaveManualBlockedSites();
                RefreshBlockedSitesEditor();

                ShowLexDeskMessageBox(
                    "Blocked Site List saved.",
                    "Blocked Site List",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
     $"Could not save Blocked Site List:\n{SanitizeExceptionMessage(ex)}",
     "Blocked Site List",
     MessageBoxButton.OK,
     MessageBoxImage.Warning);
            }
        }

        private void BlockedSite_Remove_Click(object sender, RoutedEventArgs e)
        {
            string host = "";

            // First choice: remove the selected text from the Blocked Site List editor.
            if (BlockedSitesEditor != null)
            {
                host = NormalizeManualBlockedSite(BlockedSitesEditor.SelectedText);

                // Second choice: if no text is highlighted, remove the line where the cursor is sitting.
                if (string.IsNullOrWhiteSpace(host))
                {
                    int caret = BlockedSitesEditor.CaretIndex;
                    string text = BlockedSitesEditor.Text ?? "";

                    int lineStart = text.LastIndexOf('\n', Math.Max(0, caret - 1));
                    lineStart = lineStart < 0 ? 0 : lineStart + 1;

                    int lineEnd = text.IndexOf('\n', caret);
                    lineEnd = lineEnd < 0 ? text.Length : lineEnd;

                    if (lineEnd >= lineStart)
                    {
                        string line = text.Substring(lineStart, lineEnd - lineStart);
                        host = NormalizeManualBlockedSite(line);
                    }
                }
            }

            // Third choice: fall back to the currently open website.
            if (string.IsNullOrWhiteSpace(host))
            {
                var pageUrl = GetActivePaneRealUrl();
                host = NormalizeManualBlockedSite(GetHost(pageUrl));
            }

            if (string.IsNullOrWhiteSpace(host))
            {
                ShowLexDeskMessageBox(
                    "Select a website in the Blocked Site List to remove.",
                    "Blocked Site List",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            if (_manualBlockedSites.Remove(host))
            {
                SaveManualBlockedSites();
                RefreshBlockedSitesEditor();

                ShowLexDeskMessageBox(
                    $"Website removed from Blocked Site List:\n\n{host}",
                    "Blocked Site List",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
            else
            {
                ShowLexDeskMessageBox(
                    $"This website is not in the Blocked Site List:\n\n{host}",
                    "Blocked Site List",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

