        private static string NormalizeLicenseKey(string input)
        {
            return (input ?? "")
                .Trim()
                .ToUpperInvariant();
        }

        private static string ComputeLicenseHash(string input)
        {
            var normalized = NormalizeLicenseKey(input);
            var bytes = System.Text.Encoding.UTF8.GetBytes(normalized);
            var hash = System.Security.Cryptography.SHA256.HashData(bytes);
            return Convert.ToHexString(hash);
        }


        private sealed class LicenseValidationResult
        {
            public bool IsValid { get; set; }
            public string? Status { get; set; }
            public string? Message { get; set; }
            public string? LicenseHash { get; set; }

            public string StatusText => Message ?? Status ?? "Unable to validate license";
            public string? LicenseHashToSave => LicenseHash;
        }

        private sealed class LicenseApiResponse
        {
            public bool IsValid { get; set; }
            public string? Status { get; set; }
            public string? Message { get; set; }
            public string? LicenseHash { get; set; }
        }

        private string GetDeviceFingerprint()
        {
            try
            {
                using RegistryKey? key = Registry.LocalMachine.OpenSubKey(
                    @"SOFTWARE\Microsoft\Cryptography",
                    writable: false);

                string machineGuid =
                    (key?.GetValue("MachineGuid")?.ToString() ?? "").Trim();

                if (!string.IsNullOrWhiteSpace(machineGuid))
                {
                    string stableRaw = $"LexDeskPro|{machineGuid}";
                    byte[] stableBytes = Encoding.UTF8.GetBytes(stableRaw);
                    byte[] stableHash = System.Security.Cryptography.SHA256.HashData(stableBytes);
                    return Convert.ToHexString(stableHash);
                }
            }
            catch
            {
                // Fall back to a machine-based value if MachineGuid cannot be read.
            }

            string fallbackRaw = $"LexDeskPro|{Environment.MachineName}";
            byte[] fallbackBytes = Encoding.UTF8.GetBytes(fallbackRaw);
            byte[] fallbackHash = System.Security.Cryptography.SHA256.HashData(fallbackBytes);
            return Convert.ToHexString(fallbackHash);
        }

        private string GetPrivacySafeDeviceLabel()
        {
            try
            {
                string fingerprint = GetDeviceFingerprint();

                if (string.IsNullOrWhiteSpace(fingerprint))
                    return "LexDeskProDevice";

                string shortId = fingerprint.Length >= 8
                    ? fingerprint.Substring(0, 8)
                    : fingerprint;

                return $"LexDeskProDevice-{shortId}";
            }
            catch
            {
                return "LexDeskProDevice";
            }
        }

        private string CleanLicenseKeyInput(string input)
        {
            if (string.IsNullOrWhiteSpace(input))
                return "";

            return input
                .Trim()
                .Replace("\r", "")
                .Replace("\n", "")
                .Replace("\t", "")
                .Replace("\u00A0", "")   // non-breaking space from Excel/web pages
                .Replace(" ", "")        // normal spaces
                .Replace("–", "-")       // en dash
                .Replace("—", "-")       // em dash
                .Replace("−", "-")       // minus sign
                .ToUpperInvariant();
        }

        private async Task<LicenseValidationResult> ValidateLicenseAsync(string normalizedKey)
        {
            normalizedKey = CleanLicenseKeyInput(normalizedKey);
            try
            {
                var payload = new
                {
                    licenseKey = normalizedKey,
                    deviceFingerprint = GetDeviceFingerprint(),
                    machineName = GetPrivacySafeDeviceLabel()
                };


                string json = System.Text.Json.JsonSerializer.Serialize(payload);
                using var content = new StringContent(json, Encoding.UTF8, "application/json");

                using var request = new HttpRequestMessage(HttpMethod.Post, LicenseApiUrl);
                request.Content = content;


                using var response = await _licenseHttpClient.SendAsync(request);
                string responseJson = await response.Content.ReadAsStringAsync();

                if (response.StatusCode == System.Net.HttpStatusCode.Unauthorized)
                {
                    return new LicenseValidationResult
                    {
                        IsValid = false,
                        Status = "error",
                        Message = "License server authentication failed"
                    };
                }

                if (!response.IsSuccessStatusCode)
                {
                    return ValidateLicenseOfflineFallback(normalizedKey, "License server unavailable");
                }


                var apiResult = System.Text.Json.JsonSerializer.Deserialize<LicenseApiResponse>(
                    responseJson,
                    new System.Text.Json.JsonSerializerOptions
                    {
                        PropertyNameCaseInsensitive = true
                    });


                if (apiResult == null)
                {
                    return ValidateLicenseOfflineFallback(normalizedKey, "Invalid server response");
                }

                if (apiResult.IsValid)
                {
                    string hashToSave = !string.IsNullOrWhiteSpace(apiResult.LicenseHash)
                        ? apiResult.LicenseHash!
                        : ComputeLicenseHash(normalizedKey);

                    return new LicenseValidationResult
                    {
                        IsValid = true,
                        Status = "active",
                        Message = string.IsNullOrWhiteSpace(apiResult.Message)
        ? "LexDesk Pro activated"
        : apiResult.Message!,
                        LicenseHash = hashToSave
                    };
                }

                return new LicenseValidationResult
                {
                    IsValid = false,
                    Status = string.IsNullOrWhiteSpace(apiResult.Status)
         ? "invalid"
         : apiResult.Status!,
                    Message = string.IsNullOrWhiteSpace(apiResult.Message)
         ? "License validation failed"
         : apiResult.Message!,
                    LicenseHash = null
                };
            }
            catch
            {
                return ValidateLicenseOfflineFallback(normalizedKey, "License server unavailable");
            }
        }

        private LicenseValidationResult ValidateLicenseOfflineFallback(string normalizedKey, string fallbackReason)
        {
            return new LicenseValidationResult
            {
                IsValid = false,
                Status = "error",
                Message = "Unable to validate licence. Please connect to the internet and try again.",
                LicenseHash = null
            };
        }

        private async Task<LicenseValidationResult> DeactivateSavedLicenseAsync()
        {
            string savedHash = (LoadSavedLicenseHash() ?? "").Trim().ToUpperInvariant();

            if (savedHash.Length != 64 ||
                savedHash.Any(ch => !Uri.IsHexDigit(ch)))
            {
                return new LicenseValidationResult
                {
                    IsValid = false,
                    Status = "local_state_invalid",
                    Message = "Saved licence activation information is missing or invalid.",
                    LicenseHash = null
                };
            }

            try
            {
                var payload = new
                {
                    licenseHash = savedHash,
                    deviceFingerprint = GetDeviceFingerprint()
                };

                string json = System.Text.Json.JsonSerializer.Serialize(payload);
                using var content = new StringContent(json, Encoding.UTF8, "application/json");

                using var request = new HttpRequestMessage(HttpMethod.Post, LicenseDeactivateApiUrl);
                request.Content = content;

                using var response = await _licenseHttpClient.SendAsync(request);
                string responseJson = await response.Content.ReadAsStringAsync();

                if (!response.IsSuccessStatusCode)
                {
                    return new LicenseValidationResult
                    {
                        IsValid = false,
                        Status = "server_error",
                        Message = "Unable to release this device from the licence server.",
                        LicenseHash = savedHash
                    };
                }

                var apiResult = System.Text.Json.JsonSerializer.Deserialize<LicenseApiResponse>(
                    responseJson,
                    new System.Text.Json.JsonSerializerOptions
                    {
                        PropertyNameCaseInsensitive = true
                    });

                if (apiResult == null)
                {
                    return new LicenseValidationResult
                    {
                        IsValid = false,
                        Status = "server_error",
                        Message = "The licence server returned an invalid response.",
                        LicenseHash = savedHash
                    };
                }

                return new LicenseValidationResult
                {
                    IsValid = apiResult.IsValid,
                    Status = apiResult.Status ?? "error",
                    Message = apiResult.Message ?? "Unable to deactivate this device.",
                    LicenseHash = apiResult.LicenseHash ?? savedHash
                };
            }
            catch
            {
                return new LicenseValidationResult
                {
                    IsValid = false,
                    Status = "server_error",
                    Message = "Unable to contact the licence server. Please check your internet connection and try again.",
                    LicenseHash = savedHash
                };
            }
        }

        private void LoadLicenseState()
        {
            if (!LexDeskLicensingEnabled)
            {
                _isLicensed = true;
                _licenseStatusText = "LexDesk Pro ready";
                return;
            }

            try
            {
                _isLicensed = false;
                _licenseStatusText = "Not activated";

                if (!File.Exists(_licenseStatePath))
                    return;

                var savedHash = (File.ReadAllText(_licenseStatePath) ?? "").Trim().ToUpperInvariant();

                if (string.IsNullOrWhiteSpace(savedHash))
                    return;

                if (savedHash.Length != 64 ||
                    savedHash.Any(ch => !Uri.IsHexDigit(ch)))
                {
                    ClearLicenseState();
                    return;
                }

                // Licence privacy/security notes:
                //
                // - The raw licence key is never saved locally.
                // - Only the saved activation hash/state is stored.
                // - A successful activation saves a hash so the customer does not need
                //   to re-enter their licence key every time the app opens.
                // - Clear Saved License removes this local activation state.
                // - Future improvement: add a server-side device recheck endpoint so
                //   saved activations can be refreshed without storing the raw key.
                _isLicensed = true;
                _licenseStatusText = "Activated";
            }
            catch
            {
                _isLicensed = false;
                _licenseStatusText = "Licence check failed";
            }
        }

        private void SaveLicenseState(string hash)
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_licenseStatePath)!);
                File.WriteAllText(_licenseStatePath, hash?.Trim().ToUpperInvariant() ?? "");
            }
            catch { }
        }

        private string? LoadSavedLicenseHash()
        {
            try
            {
                if (!File.Exists(_licenseStatePath))
                    return null;

                var savedHash = (File.ReadAllText(_licenseStatePath) ?? "").Trim().ToUpperInvariant();

                return string.IsNullOrWhiteSpace(savedHash)
                    ? null
                    : savedHash;
            }
            catch
            {
                return null;
            }
        }

        private void ClearLicenseState()
        {
            // ⚠️ NOTE:
            // After clearing the saved license, immediate re-activation may occasionally fail
            // with "unable to connect" or validation errors.
            //
            // This is typically caused by temporary system/network state (DNS cache, TLS session,
            // or HttpClient timing), not a licensing bug.
            //
            // If re-activation fails:
            // → Restart the PC and try again
            //
            // Future improvement:
            // - Add retry logic for activation
            // - Add "Retry" button in UI

            try
            {
                if (File.Exists(_licenseStatePath))
                    File.Delete(_licenseStatePath);
            }
            catch { }
        }

        private string? GetPackageInstallMarkerPath()
        {
            try
            {
                // MSIX package local state path is removed on uninstall.
                string localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);

                string packagesRoot = Path.Combine(localAppData, "Packages");

                if (!Directory.Exists(packagesRoot))
                    return null;

                string? packageFolder = Directory
                    .GetDirectories(packagesRoot, "460070a3-3b14-4c3e-9665-ddd7d1fc5c94_*")
                    .FirstOrDefault();

                if (string.IsNullOrWhiteSpace(packageFolder))
                    return null;

                return Path.Combine(packageFolder, "LocalState", "install.marker");
            }
            catch
            {
                return null;
            }
        }


