        private void PromptTemporaryCompatibilityForCurrentSite()
        {
            var host = GetActiveCompatibilityHost();

            if (string.IsNullOrWhiteSpace(host))
                return;

            if (_temporaryCompatibilityHosts.Contains(host))
            {
                ShowCompatibilityListCard();
                return;
            }

            var result = ShowProtectionPopup(
                "Smart Compatibility",
                "Use Smart Compatibility?",
                $"This trusted site may need Smart Compatibility:\n\n{host}\n\n" +
                "Allow login, streaming playback and essential site functions while keeping safer ad/tracker blocking where possible, and save this site to the Compatibility List?",
                MessageBoxButton.YesNo,
                MessageBoxImage.Question);

            if (result != MessageBoxResult.Yes)
                return;

            _temporaryCompatibilityHosts.Add(host);
            SaveCompatibilityHosts();

            _compatibilityModeActive[_activePageIndex] = true;
            _compatibilityModeLabels[_activePageIndex] = "Smart Compatibility";

            RefreshActivePaneStatusVisual();
            UpdateSecureSiteVisual();
            RefreshCompatibilityButtonVisual();

            UpdateSecurityStatus("Smart Compatibility enabled", false);

            var wv = GetActiveWebView();

            try
            {
                wv?.CoreWebView2?.Reload();
            }
            catch { }
        }

        private void ShowCompatibilityListCard()
        {
            var menu = new ContextMenu
            {
                Placement = PlacementMode.MousePoint
            };

            ApplyWebPrivacyContextMenuTheme(menu);

            var title = new MenuItem
            {
                Header = "Site Compatibility List",
                IsEnabled = false
            };

            menu.Items.Add(title);
            menu.Items.Add(new Separator());

            var hosts = _temporaryCompatibilityHosts
                .Where(h => !string.IsNullOrWhiteSpace(h))
                .OrderBy(h => h, StringComparer.OrdinalIgnoreCase)
                .ToList();

            if (hosts.Count == 0)
            {
                menu.Items.Add(new MenuItem
                {
                    Header = "No compatibility sites saved",
                    IsEnabled = false
                });
            }
            else
            {
                foreach (var host in hosts)
                {
                    var item = new MenuItem
                    {
                        Header = $"Remove {host}"
                    };

                    item.Click += (_, __) =>
                    {
                        RemoveCompatibilityHost(host);
                    };

                    menu.Items.Add(item);
                }

                menu.Items.Add(new Separator());

                var clearAll = new MenuItem
                {
                    Header = "Clear all compatibility sites"
                };

                clearAll.Click += (_, __) =>
                {
                    ClearCompatibilityHosts();
                };

                menu.Items.Add(clearAll);
            }

            menu.Items.Add(new Separator());

            var close = new MenuItem
            {
                Header = "Close"
            };

            close.Click += (_, __) =>
            {
                menu.IsOpen = false;
            };

            menu.Items.Add(close);

            menu.IsOpen = true;
        }

        private void RemoveCompatibilityHost(string host)
        {
            host = NormalizeHostForCompatibility(host);

            if (string.IsNullOrWhiteSpace(host))
                return;

            _temporaryCompatibilityHosts.Remove(host);
            SaveCompatibilityHosts();

            RefreshCurrentCompatibilityState();
            RefreshActivePaneStatusVisual();
            UpdateSecureSiteVisual();
            RefreshCompatibilityButtonVisual();

            UpdateSecurityStatus("Compatibility site removed", false);

            try
            {
                GetActiveWebView()?.CoreWebView2?.Reload();
            }
            catch { }
        }

        private void ClearCompatibilityHosts()
        {
            var result = ShowProtectionPopup(
                "Site Compatibility",
                "Clear Compatibility List?",
                "Remove all saved compatibility sites?\n\nSites may use stronger protection again after removal.",
                MessageBoxButton.YesNo,
                MessageBoxImage.Question);

            if (result != MessageBoxResult.Yes)
                return;

            _temporaryCompatibilityHosts.Clear();
            SaveCompatibilityHosts();

            RefreshCurrentCompatibilityState();
            RefreshActivePaneStatusVisual();
            UpdateSecureSiteVisual();
            RefreshCompatibilityButtonVisual();

            UpdateSecurityStatus("Compatibility list cleared", false);

            try
            {
                GetActiveWebView()?.CoreWebView2?.Reload();
            }
            catch { }
        }

        private void RefreshCurrentCompatibilityState()
        {
            var pageUrl = GetActivePaneRealUrl();
            var host = GetActiveCompatibilityHost();

            bool manualCompatibility =
                !string.IsNullOrWhiteSpace(host) &&
                _temporaryCompatibilityHosts.Contains(host);

            bool builtInAiCompatibility = IsBuiltInAiCompatibilityHost(pageUrl);
            bool active = manualCompatibility || builtInAiCompatibility;

            _compatibilityModeActive[_activePageIndex] = active;
            _compatibilityModeLabels[_activePageIndex] = builtInAiCompatibility
                ? "AI Compatibility"
                : manualCompatibility
                    ? "Smart Compatibility"
                    : "";
        }

        private void RefreshCompatibilityButtonVisual()
        {
            var host = GetActiveCompatibilityHost();

            bool active = !string.IsNullOrWhiteSpace(host) &&
                          _temporaryCompatibilityHosts.Contains(host);

            var normalBg = TryFindResource("ButtonBg") as Brush ?? Brushes.Transparent;
            var normalBorder = TryFindResource("ButtonBorder") as Brush ?? Brushes.Transparent;
            var normalIcon = TryFindResource("IconBrush") as Brush ?? Brushes.Black;
            var orangeBrush = TryFindResource("StatusOrangeBrush") as Brush ?? Brushes.Orange;

            // Top-bar quick tick compatibility button.
            if (QuickCompatibilityButton != null)
            {
                QuickCompatibilityButton.Background = active
                    ? orangeBrush
                    : Brushes.Transparent;

                QuickCompatibilityButton.BorderBrush = active
                    ? orangeBrush
                    : Brushes.Transparent;

                QuickCompatibilityButton.BorderThickness = active
                    ? new Thickness(1.6)
                    : new Thickness(0);

                QuickCompatibilityButton.Foreground = active
                    ? Brushes.Black
                    : normalIcon;

                QuickCompatibilityButton.ToolTip = active
                    ? "Smart Compatibility is on for this site.\nClick to manage Compatibility List."
                    : "Smart Compatibility for this site\nUse this when a trusted site does not load correctly";
            }

            // Web Actions compatibility button/card.
            // Keep this because it already gives the Web Actions section its orange standout.
            if (SiteCompatibilityTopButton != null)
            {
                SiteCompatibilityTopButton.BorderBrush = active
                    ? orangeBrush
                    : normalBorder;

                SiteCompatibilityTopButton.BorderThickness = active
                    ? new Thickness(2.0)
                    : new Thickness(1.2);

                SiteCompatibilityTopButton.Foreground = active
                    ? Brushes.Orange
                    : normalIcon;

                SiteCompatibilityTopButton.ToolTip = active
                    ? "Smart Compatibility is on for this site. Click to manage Compatibility List."
                    : "Use Smart Compatibility for this trusted site";
            }
        }

        private void RefreshCompatibilityUiForCurrentSite()
        {
            RefreshCurrentCompatibilityState();
            RefreshCompatibilityButtonVisual();
            RefreshActivePaneStatusVisual();
            UpdateSecureSiteVisual();
        }

        private void LoadCompatibilityHosts()
        {
            try
            {
                _temporaryCompatibilityHosts.Clear();

                if (!File.Exists(_compatibilityHostsPath))
                    return;

                foreach (var line in File.ReadAllLines(_compatibilityHostsPath))
                {
                    var host = NormalizeHostForCompatibility(line);

                    if (!string.IsNullOrWhiteSpace(host))
                        _temporaryCompatibilityHosts.Add(host);
                }
            }
            catch
            {
                // Privacy-safe: ignore bad compatibility list file.
            }
        }

        private void SaveCompatibilityHosts()
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_compatibilityHostsPath)!);

                var lines = _temporaryCompatibilityHosts
                    .Where(h => !string.IsNullOrWhiteSpace(h))
                    .Select(NormalizeHostForCompatibility)
                    .Where(h => !string.IsNullOrWhiteSpace(h))
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(h => h, StringComparer.OrdinalIgnoreCase)
                    .ToArray();

                File.WriteAllLines(_compatibilityHostsPath, lines);
            }
            catch
            {
                // Privacy-safe: no popup needed for a save miss.
            }
        }

        private string NormalizeHostForCompatibility(string? hostOrUrl)
        {
            if (string.IsNullOrWhiteSpace(hostOrUrl))
                return "";

            var value = hostOrUrl.Trim();

            try
            {
                if (Uri.TryCreate(value, UriKind.Absolute, out var uri))
                    value = uri.Host;
            }
            catch
            {
                // Fall through and treat as host text.
            }

            value = value.Trim()
                .Replace("https://", "", StringComparison.OrdinalIgnoreCase)
                .Replace("http://", "", StringComparison.OrdinalIgnoreCase)
                .Trim('/');

            var slashIndex = value.IndexOf('/');
            if (slashIndex >= 0)
                value = value[..slashIndex];

            var questionIndex = value.IndexOf('?');
            if (questionIndex >= 0)
                value = value[..questionIndex];

            return value
                .Replace("www.", "", StringComparison.OrdinalIgnoreCase)
                .Trim()
                .ToLowerInvariant();
        }

        private string GetActiveCompatibilityHost()
        {
            var pageUrl = GetActivePaneRealUrl();
            return NormalizeHostForCompatibility(GetHost(pageUrl));
        }

        private void SaveSearchEngine()
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_searchEnginePath)!);
                File.WriteAllText(_searchEnginePath, _searchEngine.ToString());
            }
            catch { }
        }

        private void SaveSearchRegion()
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_searchRegionPath)!);
                File.WriteAllText(_searchRegionPath, _searchRegion.ToString());
            }
            catch { }
        }

        private bool IsNewsComAuHost(string? hostOrUrl)
        {
            try
            {
                string host = "";

                if (Uri.TryCreate(hostOrUrl ?? "", UriKind.Absolute, out var uri))
                    host = uri.Host;
                else
                    host = hostOrUrl ?? "";

                host = host
                    .Trim()
                    .Replace("www.", "", StringComparison.OrdinalIgnoreCase)
                    .ToLowerInvariant();

                return host.Equals("news.com.au", StringComparison.OrdinalIgnoreCase) ||
                       host.EndsWith(".news.com.au", StringComparison.OrdinalIgnoreCase);
            }
            catch
            {
                return false;
            }
        }

        private string GetSafeHostForDebug(string? hostOrUrl)
        {
            try
            {
                string host = "";

                if (Uri.TryCreate(hostOrUrl ?? "", UriKind.Absolute, out var uri))
                    host = uri.Host;
                else
                    host = hostOrUrl ?? "";

                host = host
                    .Trim()
                    .Replace("www.", "", StringComparison.OrdinalIgnoreCase)
                    .ToLowerInvariant();

                return string.IsNullOrWhiteSpace(host)
                    ? "[host-hidden]"
                    : host;
            }
            catch
            {
                return "[host-hidden]";
            }
        }

        private string GetSafeDebugReason(string? reason)
        {
            try
            {
                string value = (reason ?? "").Trim();

                if (string.IsNullOrWhiteSpace(value))
                    return "";

                // Keep debug reasons short and generic.
                // Do not write full alert text, page text, URLs, keys, or private data.
                value = value
                    .Replace("\r", " ")
                    .Replace("\n", " ")
                    .Replace("\t", " ");

                if (value.Length > 90)
                    value = value.Substring(0, 90) + "...";

                return SanitizeLogValue(value);
            }
            catch
            {
                return "[reason-hidden]";
            }
        }

        private string GetSafeOverlayDebugReason(string? reason)
        {
            try
            {
                string value = (reason ?? "").Trim();

                if (string.IsNullOrWhiteSpace(value))
                    return "";

                value = value
                    .Replace("\r", " ")
                    .Replace("\n", " ")
                    .Replace("\t", " ");

                // Overlay detector output is already privacy-safe:
                // tag, id/class fragments, position, z-index, opacity, pointer events, and rectangle.
                // Do not run SanitizeLogValue here because it hides words like id/key/class.
                if (value.Length > 220)
                    value = value.Substring(0, 220) + "...";

                return value;
            }
            catch
            {
                return "[overlay-reason-hidden]";
            }
        }

        private void NewsComAuDebugLog(string hostOrUrl, string layer, string action, string reason)
        {
            if (!_newsComAuDebugMode)
                return;

            if (!IsNewsComAuHost(hostOrUrl))
                return;

            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_newsComAuDebugLogPath)!);

                string host = GetSafeHostForDebug(hostOrUrl);
                string safeLayer = GetSafeDebugReason(layer);
                string safeAction = GetSafeDebugReason(action);
                string safeReason = GetSafeDebugReason(reason);

                string line =
                    $"{DateTime.Now:yyyy-MM-dd HH:mm:ss} | host={host} | layer={safeLayer} | action={safeAction} | reason={safeReason}";

                File.AppendAllText(_newsComAuDebugLogPath, line + Environment.NewLine);
                Debug.WriteLine("[news.com.au debug] " + line);
            }
            catch
            {
                // Debug logging must never affect browsing.
            }
        }

        private void NewsComAuDebugLogRawReason(string hostOrUrl, string layer, string action, string alreadySafeReason)
        {
            if (!_newsComAuDebugMode)
                return;

            if (!IsNewsComAuHost(hostOrUrl))
                return;

            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_newsComAuDebugLogPath)!);

                string host = GetSafeHostForDebug(hostOrUrl);
                string safeLayer = GetSafeDebugReason(layer);
                string safeAction = GetSafeDebugReason(action);
                string safeReason = alreadySafeReason ?? "";

                string line =
                    $"{DateTime.Now:yyyy-MM-dd HH:mm:ss} | host={host} | layer={safeLayer} | action={safeAction} | reason={safeReason}";

                File.AppendAllText(_newsComAuDebugLogPath, line + Environment.NewLine);
                Debug.WriteLine("[news.com.au debug] " + line);
            }
            catch
            {
                // Debug logging must never affect browsing.
            }
        }

        private void ToggleNewsComAuDebugMode()
        {
            if (!LexDeskDeveloperDiagnosticsEnabled)
            {
                _newsComAuDebugMode = false;
                return;
            }

            _newsComAuDebugMode = !_newsComAuDebugMode;

            string state = _newsComAuDebugMode ? "ON" : "OFF";

            UpdateSecurityStatus($"news.com.au debug mode {state}", false);

            if (_newsComAuDebugMode)
            {
                NewsComAuDebugLog(
                    "news.com.au",
                    "Debug Mode",
                    "Enabled",
                    "Developer testing started");

                ShowProtectionPopup(
                    "LexDesk Pro - Debug Mode",
                    "news.com.au Debug Mode ON",
                    "Developer-only debug mode is now ON for news.com.au.\n\n" +
                    "It writes privacy-safe local diagnostics only.\n\n" +
                    "Full URLs, page content, licence keys, device details, and private data are not logged.\n\n" +
                    "Press Ctrl + Shift + N again to turn it off.",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
            else
            {
                NewsComAuDebugLog(
                    "news.com.au",
                    "Debug Mode",
                    "Disabled",
                    "Developer testing stopped");

                ShowProtectionPopup(
                    "LexDesk Pro - Debug Mode",
                    "news.com.au Debug Mode OFF",
                    "Developer-only debug mode is now OFF.",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

        private void NewsComAuDebugLogCurrentPage(string layer, string action, string reason)
        {
            try
            {
                var wv = GetActiveWebView();

                string source = "";

                try
                {
                    source = wv?.CoreWebView2?.Source ?? "";
                }
                catch
                {
                    source = "";
                }

                if (string.IsNullOrWhiteSpace(source))
                    source = GetActivePaneRealUrl();

                NewsComAuDebugLog(source, layer, action, reason);
            }
            catch
            {
                // Debug logging must never affect browsing.
            }
        }

        private void NewsComAuDebugLogJsResult(string hostOrUrl, string jsJson)
        {
            if (!_newsComAuDebugMode)
                return;

            if (!IsNewsComAuHost(hostOrUrl))
                return;

            try
            {
                if (string.IsNullOrWhiteSpace(jsJson))
                    return;

                var items = JsonSerializer.Deserialize<List<string>>(jsJson);

                if (items == null || items.Count == 0)
                {
                    NewsComAuDebugLog(
                        hostOrUrl,
                        "Overlay Detector",
                        "No candidates",
                        "No large blocking overlays reported");
                    return;
                }

                foreach (var item in items.Take(12))
                {
                    NewsComAuDebugLogRawReason(
                        hostOrUrl,
                        "Overlay Detector",
                        "Candidate",
                        GetSafeOverlayDebugReason(item));
                }
            }
            catch
            {
                NewsComAuDebugLog(
                    hostOrUrl,
                    "Overlay Detector",
                    "Parse failed",
                    "Could not read JS overlay result");
            }
        }



        private static string GetSiteDiagnosticsJavaScript() => """
(function () {
    try {
        if (window.__wppSiteDiagnosticsInstalled)
            return 'already-installed';

        window.__wppSiteDiagnosticsInstalled = true;
        window.__wppSiteDiagnosticEvents = [];

        const bornAt = new WeakMap();
        const MAX_EVENTS = 1200;

        function push(message) {
            try {
                const stamp = new Date().toISOString();
                const pageHost = ((location && location.hostname) ? location.hostname.toLowerCase() : ((location && location.protocol) ? location.protocol.replace(':', '') : '-'));
                const line = stamp + ' | page=' + (pageHost || '-') + ' | ' + message;
                window.__wppSiteDiagnosticEvents.push(line);

                try {
                    if (window.chrome && window.chrome.webview)
                        window.chrome.webview.postMessage('WPPDIAG|' + line);
                } catch { }

                if (window.__wppSiteDiagnosticEvents.length > MAX_EVENTS)
                    window.__wppSiteDiagnosticEvents.splice(0, 200);
            } catch { }
        }

        function clip(value, max) {
            value = ((value || '') + '').replace(/\s+/g, ' ').trim();
            if (value.length > max)
                value = value.substring(0, max) + '...';
            return value;
        }

        function tokenMatch(value, words) {
            try {
                const v = (' ' + (value || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ') + ' ');
                return words.some(function (word) {
                    return v.includes(' ' + word + ' ');
                });
            } catch {
                return false;
            }
        }

        const overlayWords = ['modal', 'overlay', 'dialog', 'popup', 'backdrop', 'drawer', 'flyout', 'lightbox'];
        const adWords = ['ad', 'ads', 'advert', 'advertisement', 'sponsor', 'sponsored', 'promo', 'promotion'];
        const accountWords = ['login', 'signin', 'signup', 'register', 'account'];
        const functionalWords = ['postcode', 'postal', 'location', 'dealer', 'delivery', 'store', 'checkout', 'payment', 'booking', 'filter'];
        const galleryWords = ['gallery', 'carousel', 'slideshow', 'lightbox', 'photos', 'images', 'fullscreen', 'viewer'];

        function safeStyle(el) {
            try {
                const cs = window.getComputedStyle(el);
                const r = el.getBoundingClientRect();

                return [
                    'display=' + clip(cs.display, 20),
                    'visibility=' + clip(cs.visibility, 20),
                    'opacity=' + clip(cs.opacity, 12),
                    'pointer=' + clip(cs.pointerEvents, 20),
                    'overflow=' + clip(cs.overflow, 20),
                    'position=' + clip(cs.position, 20),
                    'z=' + clip(cs.zIndex, 16),
                    'rect=' + [
                        Math.round(r.left), Math.round(r.top),
                        Math.round(r.width), Math.round(r.height)
                    ].join(',')
                ].join(' ');
            } catch {
                return 'style=unavailable';
            }
        }

        function diagnosticControlVisible(el) {
            try {
                if (!el)
                    return false;

                const cs = window.getComputedStyle(el);
                const r = el.getBoundingClientRect();

                return cs.display !== 'none' &&
                       cs.visibility !== 'hidden' &&
                       cs.opacity !== '0' &&
                       r.width > 1 &&
                       r.height > 1;
            } catch {
                return false;
            }
        }

        function safeTextFingerprint(el) {
            try {
                if (!el || el.nodeType !== 1)
                    return [];

                // Inspect text only inside the page. Never emit the text itself.
                // The log receives labels only, preserving the diagnostics privacy promise.
                const text = (((el.innerText || el.textContent || '') + '')
                    .replace(/\s+/g, ' ')
                    .trim()
                    .toLowerCase())
                    .substring(0, 8000);

                if (!text)
                    return [];

                const labels = [];

                if (text.includes('log in') || text.includes('login') ||
                    text.includes('sign in') || text.includes('sign up') ||
                    text.includes('create account'))
                    labels.push('account-copy');

                if (text.includes('save bikes you like') ||
                    text.includes('save your searches') ||
                    text.includes('save favourite properties') ||
                    text.includes('save favorite properties') ||
                    text.includes('get alerts for new listings') ||
                    text.includes('price change updates') ||
                    text.includes('price updates') ||
                    text.includes('shortlist') ||
                    text.includes('access your free account'))
                    labels.push('marketing-like');

                if (text.includes('postcode') || text.includes('postal code') ||
                    text.includes('find dealer') || text.includes('find a dealer') ||
                    text.includes('choose dealer') || text.includes('your location'))
                    labels.push('location-copy');

                if (text.includes('gallery') || text.includes('photos') ||
                    text.includes('view images') || text.includes('fullscreen'))
                    labels.push('gallery-copy');

                return labels;
            } catch {
                return [];
            }
        }

        function classify(el) {
            try {
                if (!el || el.nodeType !== 1)
                    return 'non-element';

                const id = (el.id || '').toLowerCase();
                const cls = (el.getAttribute('class') || '').toLowerCase();
                const role = (el.getAttribute('role') || '').toLowerCase();
                const joined = id + ' ' + cls + ' ' + role;
                const kinds = [];

                if (role === 'dialog' || el.getAttribute('aria-modal') === 'true' || tokenMatch(joined, overlayWords))
                    kinds.push('overlay');

                if (tokenMatch(joined, adWords))
                    kinds.push('ad-like');

                if (tokenMatch(joined, accountWords))
                    kinds.push('account-like');

                if (tokenMatch(joined, functionalWords))
                    kinds.push('functional-like');

                if (tokenMatch(joined, galleryWords))
                    kinds.push('gallery-like');

                try {
                    const accountFields = [];

                    if (el.matches && el.matches('input[type="password"], input[type="email"]'))
                        accountFields.push(el);

                    if (el.querySelectorAll)
                        accountFields.push(...el.querySelectorAll('input[type="password"], input[type="email"]'));

                    if (accountFields.some(diagnosticControlVisible))
                        kinds.push('account-form');
                } catch { }

                try {
                    const locationFields = [];

                    if (el.matches && el.matches('input[name*="postcode" i], input[autocomplete="postal-code"]'))
                        locationFields.push(el);

                    if (el.querySelectorAll)
                        locationFields.push(...el.querySelectorAll('input[name*="postcode" i], input[autocomplete="postal-code"]'));

                    if (locationFields.some(diagnosticControlVisible))
                        kinds.push('location-form');
                } catch { }

                try {
                    for (const label of safeTextFingerprint(el))
                        kinds.push(label);
                } catch { }

                const hiddenReason =
                    el.getAttribute('data-web-protect-pro-hidden') ||
                    el.getAttribute('data-web-protect-promo-hidden') ||
                    el.getAttribute('data-web-protect-reason') ||
                    el.getAttribute('data-web-protect-promo-reason') || '';

                if (hiddenReason)
                    kinds.push('wpp-action');

                try {
                    const cs = window.getComputedStyle(el);
                    const r = el.getBoundingClientRect();
                    const viewportArea = Math.max(1, window.innerWidth * window.innerHeight);
                    const area = Math.max(0, r.width * r.height);
                    const large = area >= viewportArea * 0.18;
                    const floating = cs.position === 'fixed' || cs.position === 'sticky';

                    if (large && floating)
                        kinds.push('large-floating');
                } catch { }

                return kinds.length ? Array.from(new Set(kinds)).join(',') : 'ordinary';
            } catch {
                return 'classify-failed';
            }
        }

        function describe(el) {
            try {
                if (!el || el.nodeType !== 1)
                    return '[non-element]';

                const tag = (el.tagName || '').toLowerCase();
                const id = clip(el.id || '', 70);
                const cls = clip(el.getAttribute('class') || '', 150);
                const role = clip(el.getAttribute('role') || '', 40);
                const ariaModal = clip(el.getAttribute('aria-modal') || '', 16);
                const ariaHidden = clip(el.getAttribute('aria-hidden') || '', 16);
                const hiddenReason = clip(
                    el.getAttribute('data-web-protect-pro-hidden') ||
                    el.getAttribute('data-web-protect-promo-hidden') ||
                    el.getAttribute('data-web-protect-reason') ||
                    el.getAttribute('data-web-protect-promo-reason') || '',
                    100);

                return 'kind=' + classify(el) +
                    ' tag=' + tag +
                    ' id=' + (id || '-') +
                    ' class=' + (cls || '-') +
                    ' role=' + (role || '-') +
                    ' ariaModal=' + (ariaModal || '-') +
                    ' ariaHidden=' + (ariaHidden || '-') +
                    ' wpp=' + (hiddenReason || '-') +
                    ' ' + safeStyle(el);
            } catch {
                return '[describe-failed]';
            }
        }

        function candidateish(el) {
            try {
                if (!el || el.nodeType !== 1)
                    return false;

                if (el === document.documentElement || el === document.body)
                    return true;

                return classify(el) !== 'ordinary';
            } catch {
                return false;
            }
        }

        function scanNode(node, verb) {
            try {
                if (!node || node.nodeType !== 1)
                    return;

                if (candidateish(node))
                    push(verb + ' | ' + describe(node));

                let shown = 0;
                const descendants = node.querySelectorAll ? node.querySelectorAll(
                    '[role="dialog"], [aria-modal="true"], ' +
                    '[class*="modal" i], [class*="overlay" i], [class*="popup" i], [class*="dialog" i], ' +
                    '[class*="drawer" i], [class*="lightbox" i], [class*="gallery" i], [class*="carousel" i], ' +
                    '[class*="advert" i], [class*="sponsor" i], [class*="promo" i], ' +
                    '[id*="modal" i], [id*="overlay" i], [id*="popup" i], [id*="dialog" i], ' +
                    '[id*="advert" i], [id*="sponsor" i], [id*="promo" i], ' +
                    '[data-web-protect-pro-hidden], [data-web-protect-promo-hidden], ' +
                    '[data-web-protect-reason], [data-web-protect-promo-reason]'
                ) : [];

                for (const el of descendants) {
                    if (shown >= 20)
                        break;

                    if (candidateish(el)) {
                        push(verb + '-CHILD | ' + describe(el));
                        shown++;
                    }
                }
            } catch { }
        }

        function snapshot(label) {
            try {
                const html = document.documentElement;
                const body = document.body;

                if (html)
                    push('SNAPSHOT ' + label + ' | html ' + safeStyle(html));
                if (body)
                    push('SNAPSHOT ' + label + ' | body ' + safeStyle(body));

                const wppCount = document.querySelectorAll(
                    '[data-web-protect-pro-hidden], [data-web-protect-promo-hidden], ' +
                    '[data-web-protect-reason], [data-web-protect-promo-reason]'
                ).length;
                push('SNAPSHOT ' + label + ' | wpp-marked=' + wppCount);

                const all = Array.from(document.querySelectorAll(
                    '[role="dialog"], [aria-modal="true"], ' +
                    '[class*="modal" i], [class*="overlay" i], [class*="popup" i], [class*="dialog" i], ' +
                    '[class*="drawer" i], [class*="lightbox" i], [class*="gallery" i], [class*="carousel" i], ' +
                    '[class*="advert" i], [class*="sponsor" i], [class*="promo" i], ' +
                    '[id*="modal" i], [id*="overlay" i], [id*="popup" i], [id*="dialog" i], ' +
                    '[id*="advert" i], [id*="sponsor" i], [id*="promo" i], ' +
                    '[data-web-protect-pro-hidden], [data-web-protect-promo-hidden], ' +
                    '[data-web-protect-reason], [data-web-protect-promo-reason]'
                ));

                let shown = 0;
                for (const el of all) {
                    if (!el || shown >= 30)
                        break;

                    try {
                        const r = el.getBoundingClientRect();
                        const cs = window.getComputedStyle(el);
                        const visibleish =
                            r.width > 0 && r.height > 0 &&
                            cs.display !== 'none' &&
                            cs.visibility !== 'hidden';

                        if (visibleish || classify(el).includes('wpp-action')) {
                            push('SNAPSHOT ' + label + ' | candidate ' + describe(el));
                            shown++;
                        }
                    } catch { }
                }
            } catch { }
        }

        function installObserver() {
            try {
                const root = document.documentElement || document.body;
                if (!root) {
                    setTimeout(installObserver, 10);
                    return;
                }

                if (window.__wppSiteDiagnosticObserver)
                    return;

                document.addEventListener('click', function (ev) {
                    try {
                        const target = ev.target && ev.target.closest
                            ? ev.target.closest('button, a, [role="button"], input, select, label, [tabindex], div')
                            : ev.target;

                        push('CLICK | ' + describe(target));
                        snapshot('click+0');
                        setTimeout(function () { snapshot('click+50ms'); }, 50);
                        setTimeout(function () { snapshot('click+150ms'); }, 150);
                        setTimeout(function () { snapshot('click+400ms'); }, 400);
                        setTimeout(function () { snapshot('click+1000ms'); }, 1000);
                    } catch { }
                }, true);

                const observer = new MutationObserver(function (mutations) {
                    try {
                        for (const mutation of mutations) {
                            if (mutation.type === 'childList') {
                                for (const node of mutation.addedNodes || []) {
                                    if (node && node.nodeType === 1) {
                                        bornAt.set(node, performance.now());
                                        scanNode(node, 'ADDED');
                                    }
                                }

                                for (const node of mutation.removedNodes || []) {
                                    if (node && node.nodeType === 1) {
                                        let lifetime = -1;
                                        try {
                                            if (bornAt.has(node))
                                                lifetime = Math.max(0, performance.now() - bornAt.get(node));
                                        } catch { }

                                        if (candidateish(node)) {
                                            const flash = lifetime >= 0 && lifetime < 1500 ? ' FLASH' : '';
                                            push('REMOVED' + flash + ' lifetimeMs=' + (lifetime >= 0 ? Math.round(lifetime) : '-') + ' | ' + describe(node));
                                        }
                                    }
                                }
                            } else if (mutation.type === 'attributes') {
                                const el = mutation.target;
                                if (candidateish(el))
                                    push('ATTR ' + mutation.attributeName + ' | ' + describe(el));
                            }
                        }
                    } catch { }
                });

                observer.observe(root, {
                    subtree: true,
                    childList: true,
                    attributes: true,
                    attributeFilter: [
                        'style', 'class', 'hidden', 'aria-hidden', 'aria-modal', 'role',
                        'data-web-protect-pro-hidden', 'data-web-protect-promo-hidden',
                        'data-web-protect-reason', 'data-web-protect-promo-reason'
                    ]
                });

                window.__wppSiteDiagnosticObserver = observer;
                window.__wppSiteDiagnosticSnapshot = snapshot;
                snapshot('installed');
                push('SITE_DIAGNOSTICS installed');
            } catch { }
        }

        try {
            const originalOpen = window.open;
            if (typeof originalOpen === 'function' && !window.__wppSiteDiagnosticWindowOpenWrapped) {
                window.__wppSiteDiagnosticWindowOpenWrapped = true;
                window.open = function () {
                    try { push('WINDOW_OPEN called argc=' + arguments.length); } catch { }
                    return originalOpen.apply(this, arguments);
                };
            }
        } catch { }

        installObserver();
        return 'installed';
    } catch {
        return 'install-error';
    }
})();

""";

        private void ResetSiteDiagnosticBuffers()
        {
            lock (_siteDiagnosticSync)
            {
                _siteDiagnosticRequestCounts.Clear();
                _siteDiagnosticBlockCounts.Clear();
                _siteDiagnosticHostEvents.Clear();
                _siteDiagnosticDomEvents.Clear();
                _siteDiagnosticPageStates.Clear();
            }
        }

        private void AddSiteDiagnosticEvent(string message)
        {
            if (!_siteDiagnosticMode || string.IsNullOrWhiteSpace(message))
                return;

            lock (_siteDiagnosticSync)
            {
                _siteDiagnosticHostEvents.Add($"{DateTime.UtcNow:O} | {message}");

                if (_siteDiagnosticHostEvents.Count > SiteDiagnosticMaxHostEvents)
                    _siteDiagnosticHostEvents.RemoveRange(0, Math.Min(150, _siteDiagnosticHostEvents.Count));
            }
        }

        private void AddSiteDiagnosticDomEvent(string message)
        {
            if (!_siteDiagnosticMode || string.IsNullOrWhiteSpace(message))
                return;

            lock (_siteDiagnosticSync)
            {
                _siteDiagnosticDomEvents.Add(message);

                if (_siteDiagnosticDomEvents.Count > SiteDiagnosticMaxDomEvents)
                    _siteDiagnosticDomEvents.RemoveRange(0, Math.Min(250, _siteDiagnosticDomEvents.Count));
            }
        }

        private void CoreWebView2_SiteDiagnosticWebMessageReceived(
            object? sender,
            CoreWebView2WebMessageReceivedEventArgs e)
        {
            if (!_siteDiagnosticMode)
                return;

            try
            {
                string message = e.TryGetWebMessageAsString();

                if (!message.StartsWith("WPPDIAG|", StringComparison.Ordinal))
                    return;

                string payload = message.Substring("WPPDIAG|".Length);
                AddSiteDiagnosticDomEvent(payload);
            }
            catch
            {
                // Diagnostics must never affect browsing.
            }
        }

        private static string GetSiteDiagnosticHost(string? url)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(url))
                    return "-";

                if (Uri.TryCreate(url, UriKind.Absolute, out var uri))
                    return string.IsNullOrWhiteSpace(uri.Host) ? uri.Scheme : uri.Host.ToLowerInvariant();
            }
            catch { }

            return "-";
        }

        private static string ExtractSiteDiagnosticPageHost(string? line)
        {
            if (string.IsNullOrWhiteSpace(line))
                return "-";

            int start = line.IndexOf("page=", StringComparison.OrdinalIgnoreCase);
            if (start < 0)
                return "-";

            start += "page=".Length;
            int end = start;

            while (end < line.Length)
            {
                char ch = line[end];
                if (char.IsWhiteSpace(ch) || ch == '|')
                    break;
                end++;
            }

            return end > start
                ? line.Substring(start, end - start).Trim().ToLowerInvariant()
                : "-";
        }

        private void RecordSiteDiagnosticPageState(string? pageUrl)
        {
            if (!_siteDiagnosticMode)
                return;

            try
            {
                string host = GetSiteDiagnosticHost(pageUrl);
                if (string.IsNullOrWhiteSpace(host) || host == "-" || host == "about")
                    return;

                bool whitelisted = IsWhitelisted(host);
                bool smartCompatibility =
                    !string.IsNullOrWhiteSpace(pageUrl) && IsTemporaryCompatibilityHost(pageUrl);

                string state =
                    $"Privacy={_privacyMode} | AdBlockEnabled={_adBlockEnabled} | " +
                    $"Whitelisted={whitelisted} | SmartCompatibility={smartCompatibility} | " +
                    $"PopupMode={_popupMode} | AnnoyanceShield={_annoyanceShieldMode}";

                lock (_siteDiagnosticSync)
                {
                    _siteDiagnosticPageStates[host] = state;
                }
            }
            catch
            {
                // Diagnostics must never affect browsing.
            }
        }

        private void AddSiteDiagnosticEventForPage(string? pageUrl, string message)
        {
            string host = GetSiteDiagnosticHost(pageUrl);
            RecordSiteDiagnosticPageState(pageUrl);
            AddSiteDiagnosticEvent($"page={host} | {message}");
        }

        private void RecordSiteDiagnosticRequest(
            string pageUrl,
            string requestUrl,
            CoreWebView2WebResourceContext context)
        {
            if (!_siteDiagnosticMode)
                return;

            try
            {
                string pageHost = GetSiteDiagnosticHost(pageUrl);
                string requestHost = GetSiteDiagnosticHost(requestUrl);
                bool thirdParty = IsThirdParty(pageUrl, requestUrl);
                string key = $"page={pageHost} request={requestHost} context={context} thirdParty={thirdParty}";

                RecordSiteDiagnosticPageState(pageUrl);

                lock (_siteDiagnosticSync)
                {
                    _siteDiagnosticRequestCounts.TryGetValue(key, out int count);
                    _siteDiagnosticRequestCounts[key] = count + 1;
                }
            }
            catch { }
        }

        private void RecordSiteDiagnosticBlock(
            string pageUrl,
            string requestUrl,
            CoreWebView2WebResourceContext context)
        {
            if (!_siteDiagnosticMode)
                return;

            try
            {
                string pageHost = GetSiteDiagnosticHost(pageUrl);
                string requestHost = GetSiteDiagnosticHost(requestUrl);
                bool thirdParty = IsThirdParty(pageUrl, requestUrl);
                string key = $"page={pageHost} request={requestHost} context={context} thirdParty={thirdParty}";

                RecordSiteDiagnosticPageState(pageUrl);

                lock (_siteDiagnosticSync)
                {
                    _siteDiagnosticBlockCounts.TryGetValue(key, out int count);
                    _siteDiagnosticBlockCounts[key] = count + 1;
                }
            }
            catch { }
        }

        private string GetEarlyNuisanceGuardJavaScript()
        {
            // Stage 2N.10: intentionally tiny and conservative. This is not a second
            // full blocker. It only suppresses unmistakable automatic account-marketing
            // modals before first paint, while preserving deliberate Log in / Sign up,
            // postcode/dealer, checkout, gallery and other functional flows.
            return """
(function() {
    try {
        if (window.__wppEarlyNuisanceGuardInstalled)
            return;

        window.__wppEarlyNuisanceGuardInstalled = true;
        window.__wppEarlyAccountIntentUtc = 0;

        const marketingPhrases = [
            'save your searches', 'save your search', 'saved searches',
            'save bikes you like', 'save things you like',
            'save favourite properties', 'save favorite properties',
            'find your saved bikes easily', 'access your free account',
            'get alerts for new listings', 'alerts for new listings',
            'price change updates', 'price updates', 'shortlist',
            'sign up for free', 'join for free', 'create a free account'
        ];

        const accountWords = [
            'login', 'log in', 'sign in', 'signin', 'sign up',
            'create account', 'register', 'my account'
        ];

        const hardSafeWords = [
            'password', 'checkout', 'payment', 'pay now', 'basket', 'cart',
            'postcode', 'post code', 'postal code', 'zip code',
            'find dealer', 'find a dealer', 'choose dealer', 'select dealer',
            'delivery', 'choose store', 'select store',
            'gallery', 'photos', 'photo', 'images', 'fullscreen', 'full screen',
            'map', 'maps', 'verify', 'verification', '2fa', 'two-factor'
        ];

        function textOf(el) {
            try {
                if (!el) return '';
                return (
                    (el.innerText || el.textContent || '') + ' ' +
                    (el.getAttribute && el.getAttribute('aria-label') || '') + ' ' +
                    (el.getAttribute && el.getAttribute('title') || '')
                ).toLowerCase();
            } catch {
                return '';
            }
        }

        function hasAny(text, words) {
            return words.some(w => text.includes(w));
        }

        function visible(el) {
            try {
                if (!el || el === document.body || el === document.documentElement)
                    return false;
                const style = getComputedStyle(el);
                const r = el.getBoundingClientRect();
                return style.display !== 'none' &&
                       style.visibility !== 'hidden' &&
                       style.opacity !== '0' &&
                       r.width > 20 && r.height > 20;
            } catch {
                return false;
            }
        }

        function recentAccountIntent() {
            return (Date.now() - (window.__wppEarlyAccountIntentUtc || 0)) < 8000;
        }

        function rememberAccountIntent(event) {
            try {
                let node = event.target;
                if (node && node.closest) {
                    node = node.closest('button, a, [role="button"], input[type="submit"], input[type="button"], label') || node;
                }
                const t = textOf(node);
                if (hasAny(t, accountWords))
                    window.__wppEarlyAccountIntentUtc = Date.now();
            } catch { }
        }

        document.addEventListener('pointerdown', rememberAccountIntent, true);
        document.addEventListener('keydown', function(event) {
            if (event.key === 'Enter' || event.key === ' ')
                rememberAccountIntent(event);
        }, true);

        function hasVisiblePassword(el) {
            try {
                for (const input of el.querySelectorAll('input[type="password"], input[autocomplete="current-password"]')) {
                    if (visible(input)) return true;
                }
            } catch { }
            return false;
        }

        function hasCloseControl(el) {
            try {
                const buttons = el.querySelectorAll('button, [role="button"], a');
                const er = el.getBoundingClientRect();
                for (const b of buttons) {
                    if (!visible(b)) continue;
                    const t = textOf(b).trim();
                    const br = b.getBoundingClientRect();
                    const smallTopRight =
                        br.width <= 72 && br.height <= 72 &&
                        br.right >= er.right - 100 &&
                        br.top <= er.top + 100;
                    if (t === 'x' || t === '×' || t === 'close' || t === 'dismiss' ||
                        t.includes('close') || t.includes('dismiss') || smallTopRight)
                        return b;
                }
            } catch { }
            return null;
        }

        function looksModalLike(el) {
            try {
                if (!visible(el)) return false;

                const style = getComputedStyle(el);
                const r = el.getBoundingClientRect();
                const vw = window.innerWidth || 1;
                const vh = window.innerHeight || 1;
                const role = (el.getAttribute('role') || '').toLowerCase();
                const cls = ((el.getAttribute('class') || '') + ' ' + (el.id || '')).toLowerCase();
                const z = parseInt(style.zIndex || '0');

                const explicit = role === 'dialog' || el.getAttribute('aria-modal') === 'true';
                const named = /modal|popup|overlay|backdrop|dialog|lightbox/.test(cls);
                const fullBlocking =
                    (style.position === 'fixed' || style.position === 'absolute') &&
                    r.width > vw * 0.55 && r.height > vh * 0.40;
                const centeredCard =
                    r.width > 280 && r.width < vw * 0.88 &&
                    r.height > 120 && r.height < vh * 0.88 &&
                    r.left > vw * 0.04 && r.right < vw * 0.96 &&
                    r.top > vh * 0.03 && r.bottom < vh * 0.97 &&
                    (explicit || named || (!Number.isNaN(z) && z >= 10) || !!hasCloseControl(el));

                return explicit || named || fullBlocking || centeredCard;
            } catch {
                return false;
            }
        }

        function findOwner(start) {
            let current = start;
            let best = null;
            for (let i = 0; i < 10 && current && current !== document.body && current !== document.documentElement; i++) {
                try {
                    const id = (current.id || '').toLowerCase();

                    // realestate.co.nz and some other apps reuse a permanent modal host
                    // for later galleries/filters. Never disable the reusable host itself.
                    if (id !== 'modal-overlays' && looksModalLike(current)) {
                        // Prefer the nearest owner with a real close control. Clicking the
                        // site's own close action lets React/Ember clean up its state.
                        if (hasCloseControl(current))
                            return current;

                        best = current;
                    }
                } catch { }
                current = current.parentElement;
            }
            return best;
        }

        function isRealestateNzSavePromo(el) {
            try {
                const host = (location.hostname || '').toLowerCase();
                if (!host.includes('realestate.co.nz'))
                    return false;

                const t = textOf(el);
                if (!t)
                    return false;

                // Stage 4D.2: realestate.co.nz can inject this promotional save/login
                // modal after the page has already rendered. Match the exact nuisance
                // wording, not generic account/login UI, so deliberate login remains safe.
                const saveLead =
                    t.includes('log in to save') ||
                    t.includes('save search') ||
                    t.includes('save favourite properties') ||
                    t.includes('save favorite properties');

                const benefit =
                    t.includes('matching properties') ||
                    t.includes('real-time notifications') ||
                    t.includes('real time notifications') ||
                    t.includes('price change updates') ||
                    t.includes('price updates');

                return saveLead &&
                       benefit &&
                       t.includes('sign up') &&
                       t.includes('log in');
            } catch {
                return false;
            }
        }

        function isHighConfidenceMarketing(el) {
            const t = textOf(el);
            if (!t || !hasAny(t, marketingPhrases))
                return false;
            if (hasAny(t, hardSafeWords))
                return false;
            if (hasVisiblePassword(el))
                return false;
            return true;
        }

        function dismissOwner(owner) {
            if (!owner || owner.dataset.wppEarlyNuisanceDone === '1')
                return;

            owner.dataset.wppEarlyNuisanceDone = '1';
            owner.setAttribute('data-web-protect-pro-hidden', 'early-account-marketing');

            const close = hasCloseControl(owner);
            if (close) {
                try { close.click(); return; } catch { }
            }

            try {
                owner.style.setProperty('display', 'none', 'important');
                owner.style.setProperty('visibility', 'hidden', 'important');
                owner.style.setProperty('opacity', '0', 'important');
                owner.style.setProperty('pointer-events', 'none', 'important');
            } catch { }

            // Release a stale page lock only when this high-confidence marketing
            // modal had to be hidden directly rather than closed normally.
            try {
                setTimeout(function() {
                    const anyVisibleDialog = Array.from(document.querySelectorAll('[role="dialog"], [aria-modal="true"]'))
                        .some(x => visible(x) && x.dataset.wppEarlyNuisanceDone !== '1');
                    if (!anyVisibleDialog) {
                        document.documentElement.style.removeProperty('overflow');
                        document.body && document.body.style.removeProperty('overflow');
                        document.body && document.body.style.removeProperty('pointer-events');
                    }
                }, 0);
            } catch { }
        }

        function inspect(start) {
            try {
                if (!start || recentAccountIntent())
                    return;

                let el = start.nodeType === 1 ? start : start.parentElement;
                for (let i = 0; i < 8 && el && el !== document.body && el !== document.documentElement; i++) {
                    // Stage 4D.2: catch the known realestate.co.nz save/login nag at
                    // document-start, before it can become a full-screen click blocker.
                    if (isRealestateNzSavePromo(el)) {
    // Temporary release behaviour:
    // allow realestate.co.nz save/login dialogs so genuine login remains functional.
    return;
}

                    if (isHighConfidenceMarketing(el)) {
                        const owner = findOwner(el);
                        if (owner) {
                            dismissOwner(owner);
                            return;
                        }
                    }
                    el = el.parentElement;
                }
            } catch { }
        }

        function scanExistingNuisance() {
try {
    const host = (location.hostname || '').toLowerCase();
    if (!host.includes('realestate.co.nz'))
        return;

    // A deliberate Log in / Sign in click must always win.
    // Do not let the timed nuisance scanner close a user-requested account dialog.
    if (recentAccountIntent())
        return;

                // Keep this deliberately narrow. We are looking only for the exact
                // promotional save/login modal, never the reusable #modal-overlays host.
                const candidates = document.querySelectorAll(
                    '[role="dialog"], [aria-modal="true"], .ember-modal-wrapper, .ember-modal-dialog, body *'
                );

                for (const el of candidates) {
                    if (isRealestateNzSavePromo(el)) {
                        const owner = findOwner(el);
                        if (owner) {
                            dismissOwner(owner);
                            return;
                        }
                    }
                }
            } catch { }
        }

        function installObserver() {
            try {
                if (window.__wppEarlyNuisanceObserver)
                    return;

                const root = document.documentElement;
                if (!root)
                    return;

                // Only inspect DOM changes that look capable of being popup/modal UI.
// Large modern websites can create thousands of ordinary elements while
// loading, so sending every mutation through the nuisance scanner is wasteful.
const likelyUiSelector =
    '[role="dialog"], [aria-modal="true"], ' +
    '[class*="modal" i], [class*="popup" i], ' +
    '[class*="overlay" i], [class*="dialog" i], ' +
    '[id*="modal" i], [id*="popup" i], ' +
    '[id*="overlay" i], [id*="dialog" i]';

function findLikelyNuisanceCandidate(node) {
    try {
        let el =
            node && node.nodeType === 1
                ? node
                : node && node.parentElement;

        if (!el)
            return null;

        // The changed element itself or one of its parents belongs to
        // obvious modal/popup UI.
        if (el.matches && el.matches(likelyUiSelector))
            return el;

        if (el.closest) {
            const owner = el.closest(likelyUiSelector);
            if (owner)
                return el;
        }

        // Some frameworks add an already-built modal as one subtree.
        // Search modest subtrees only, never giant page containers.
        if (el.querySelector &&
            el.childElementCount > 0 &&
            el.childElementCount <= 80) {

            const nested = el.querySelector(likelyUiSelector);

            if (nested)
                return nested;
        }

        return null;
    }
    catch {
        return null;
    }
}

const observer = new MutationObserver(function(mutations) {
    for (const m of mutations) {
        if (m.type !== 'childList')
            continue;

        for (const node of m.addedNodes || []) {
            const candidate = findLikelyNuisanceCandidate(node);

            if (candidate)
                inspect(candidate);
        }
    }
});

observer.observe(root, {
    childList: true,
    subtree: true
});

                window.__wppEarlyNuisanceObserver = observer;

                // Defensive passes cover pages that create the modal in one large DOM
                // transaction before the observer has seen its final text content.
                scanExistingNuisance();
                setTimeout(scanExistingNuisance, 100);
                setTimeout(scanExistingNuisance, 350);
                setTimeout(scanExistingNuisance, 800);
                setTimeout(scanExistingNuisance, 1500);
                setTimeout(scanExistingNuisance, 3000);
                setTimeout(scanExistingNuisance, 6000);
            } catch { }
        }

        (function waitForDocumentRoot() {
            if (document.documentElement) {
                installObserver();
                return;
            }
            setTimeout(waitForDocumentRoot, 0);
        })();
    } catch {
        // Never let the early guard interfere with page loading.
    }
})();
""";
        }

        private string GetFirstPaintRecoveryJavaScript()
        {
            return """
(function() {
    try {
        if (window.__wppFirstPaintRecoveryInstalled)
            return;

        window.__wppFirstPaintRecoveryInstalled = true;

        let checks = 0;
        const maxChecks = 24;   // About 6 seconds.
        const checkDelay = 250;

        function pageIsBuiltEnough() {
            try {
                const body = document.body;

                if (!body)
                    return false;

                if (document.readyState === 'loading')
                    return false;

                const textLength =
                    ((body.innerText || '').trim()).length;

                const childCount =
                    body.children ? body.children.length : 0;

                // Do not interfere with a genuinely empty/loading document.
                return textLength >= 120 || childCount >= 4;
            }
            catch {
                return false;
            }
        }

        function rootIsArtificiallyHidden() {
            try {
                const root = document.documentElement;

                if (!root)
                    return false;

                const classText =
                    (root.className || '').toString().toLowerCase();

                // Deliberately narrow:
                // this is the common anti-flicker class seen in the diagnostics.
                if (!classText.includes('async-hide'))
                    return false;

                const inlineStyle =
                    root.getAttribute('style') || '';

                let opacity = '1';
                let visibility = 'visible';

                try {
                    const style = window.getComputedStyle(root);

                    opacity = style.opacity || '1';
                    visibility = style.visibility || 'visible';
                }
                catch {
                }

                const opacityValue =
                    Number.parseFloat(opacity);

                const computedHidden =
                    Number.isFinite(opacityValue) &&
                    opacityValue <= 0.01;

                const inlineHidden =
                    /opacity\s*:\s*0(?:[;\s!]|$)/i.test(inlineStyle);

                const visibilityHidden =
                    visibility === 'hidden';

                return computedHidden ||
                       inlineHidden ||
                       visibilityHidden;
            }
            catch {
                return false;
            }
        }

        function restoreFirstPaint() {
            try {
                const root = document.documentElement;

                if (!root)
                    return;

                // Remove only the recognised anti-flicker token.
                try {
                    for (const className of Array.from(root.classList)) {
                        if (className.toLowerCase() === 'async-hide')
                            root.classList.remove(className);
                    }
                }
                catch {
                }

                // Inline !important wins if the site's CSS still tries
                // to leave the finished document invisible.
                root.style.setProperty(
                    'opacity',
                    '1',
                    'important');

                root.style.setProperty(
                    'visibility',
                    'visible',
                    'important');

                window.__wppFirstPaintRecovered = true;
            }
            catch {
            }
        }

        function checkFirstPaint() {
            try {
                checks++;

                if (rootIsArtificiallyHidden() &&
                    pageIsBuiltEnough()) {

                    restoreFirstPaint();
                    return;
                }

                if (checks < maxChecks)
                    setTimeout(checkFirstPaint, checkDelay);
            }
            catch {
                // First-paint recovery must never interfere with loading.
            }
        }

        // Give the website normal first opportunity to initialise.
        setTimeout(checkFirstPaint, 500);
    }
    catch {
        // Never allow this helper to interfere with navigation.
    }
})();
""";
        }

        private async Task RegisterFirstPaintRecoveryAsync(CoreWebView2 core)
        {
            if (core == null)
                return;

            try
            {
                if (_firstPaintRecoveryScriptIds.ContainsKey(core))
                    return;

                string scriptId =
                    await core.AddScriptToExecuteOnDocumentCreatedAsync(
                        GetFirstPaintRecoveryJavaScript());

                _firstPaintRecoveryScriptIds[core] = scriptId;
            }
            catch
            {
                // Normal browsing must continue even if this helper cannot install.
            }
        }

        private async Task RegisterEarlyNuisanceGuardAsync(CoreWebView2 core)
        {
            if (core == null || _annoyanceShieldMode == AnnoyanceShieldMode.Off)
                return;

            try
            {
                if (_earlyNuisanceGuardScriptIds.ContainsKey(core))
                    return;

                string scriptId = await core.AddScriptToExecuteOnDocumentCreatedAsync(
                    GetEarlyNuisanceGuardJavaScript());

                _earlyNuisanceGuardScriptIds[core] = scriptId;
            }
            catch
            {
                // Full Annoyance Shield after navigation remains the fallback.
            }
        }

        private async Task InstallSiteDiagnosticsAsync(CoreWebView2 core)
        {
            if (!_siteDiagnosticMode || core == null)
                return;

            try
            {
                await core.ExecuteScriptAsync(GetSiteDiagnosticsJavaScript());
            }
            catch
            {
                // Diagnostics must never affect browsing.
            }
        }

        private static string SanitizeSiteDiagnosticConsoleText(string? raw)
        {
            if (string.IsNullOrWhiteSpace(raw))
                return "-";

            try
            {
                string lower = raw.ToLowerInvariant();

                // Console messages can occasionally echo credentials or callback data.
                // If a message looks sensitive, keep the fact that an error occurred but
                // do not retain its text in the diagnostic file.
                string[] sensitiveMarkers =
                {
                    "password", "passwd", "authorization", "bearer ",
                    "access_token", "refresh_token", "id_token", "sessionid",
                    "session_id", "cookie:", "set-cookie", "client_secret"
                };

                if (sensitiveMarkers.Any(lower.Contains))
                    return "[redacted-sensitive-console-entry]";

                var parts = raw
                    .Replace('\r', ' ')
                    .Replace('\n', ' ')
                    .Split(' ', StringSplitOptions.RemoveEmptyEntries);

                var safeParts = new List<string>(parts.Length);

                foreach (string originalPart in parts)
                {
                    string part = originalPart;
                    string trimmed = part.Trim('(', ')', '[', ']', '{', '}', '<', '>', '\'', '"', ',', ';');

                    if (Uri.TryCreate(trimmed, UriKind.Absolute, out var uri) &&
                        (uri.Scheme.Equals("http", StringComparison.OrdinalIgnoreCase) ||
                         uri.Scheme.Equals("https", StringComparison.OrdinalIgnoreCase)))
                    {
                        safeParts.Add($"[{uri.Scheme}://{uri.Host}]");
                        continue;
                    }

                    // Avoid retaining query strings or callback parameters embedded in an
                    // otherwise harmless console token.
                    int queryIndex = part.IndexOf('?');
                    if (queryIndex > 0)
                        part = part.Substring(0, queryIndex) + "?…";

                    safeParts.Add(part);
                }

                string safe = string.Join(" ", safeParts).Trim();

                if (safe.Length > 420)
                    safe = safe.Substring(0, 420) + "…";

                return string.IsNullOrWhiteSpace(safe) ? "-" : safe;
            }
            catch
            {
                return "[console-entry-unavailable]";
            }
        }

        private CoreWebView2? FindDiagnosticCoreForReceiver(
            object? receiver,
            Dictionary<CoreWebView2, CoreWebView2DevToolsProtocolEventReceiver> map)
        {
            if (receiver == null)
                return null;

            try
            {
                foreach (var pair in map)
                {
                    if (ReferenceEquals(pair.Value, receiver))
                        return pair.Key;
                }
            }
            catch { }

            return null;
        }

        private void CoreWebView2_SiteDiagnosticNavigationStarting(
            object? sender,
            CoreWebView2NavigationStartingEventArgs e)
        {
            if (!_siteDiagnosticMode || sender is not CoreWebView2 core)
                return;

            try
            {
                string openerUrl = core.Source ?? "";
                string targetUrl = e.Uri ?? "";

                _siteDiagnosticNavigationStartedUtc[core] = DateTime.UtcNow;

                AddSiteDiagnosticEventForPage(
                    openerUrl,
                    $"NAVIGATION starting target={GetSiteDiagnosticHost(targetUrl)} " +
                    $"userInitiated={e.IsUserInitiated} redirected={e.IsRedirected} navId={e.NavigationId}");
            }
            catch
            {
                // Diagnostics must never affect browsing.
            }
        }


        private void CoreWebView2_SiteDiagnosticDOMContentLoaded(
            object? sender,
            CoreWebView2DOMContentLoadedEventArgs e)
        {
            if (!_siteDiagnosticMode || sender is not CoreWebView2 core)
                return;

            try
            {
                long elapsedMs = -1;

                if (_siteDiagnosticNavigationStartedUtc.TryGetValue(core, out DateTime startedUtc))
                    elapsedMs = Math.Max(0, (long)(DateTime.UtcNow - startedUtc).TotalMilliseconds);

                AddSiteDiagnosticEventForPage(
                    core.Source,
                    $"DOM_CONTENT_LOADED elapsedMs={elapsedMs} navId={e.NavigationId}");
            }
            catch
            {
                // Diagnostics must never affect browsing.
            }
        }

        private async Task CaptureSiteDiagnosticPerformanceSnapshotAsync(
            CoreWebView2 core,
            string expectedHost,
            string label)
        {
            if (!_siteDiagnosticMode || core == null)
                return;

            try
            {
                string currentUrl = core.Source ?? "";
                string currentHost = GetSiteDiagnosticHost(currentUrl);

                if (!string.Equals(currentHost, expectedHost, StringComparison.OrdinalIgnoreCase))
                    return;

                string resultJson = await core.ExecuteScriptAsync("""
(function () {
    try {
        const nav = performance.getEntriesByType('navigation')[0] || null;
        const resources = performance.getEntriesByType('resource') || [];

        const pendingImages = Array.from(document.images || [])
            .filter(img => !img.complete).length;

        const slowResources = resources
            .filter(r => Number.isFinite(r.duration) && r.duration >= 2000)
            .sort((a, b) => b.duration - a.duration)
            .slice(0, 10)
            .map(r => {
                let host = '-';
                try { host = new URL(r.name).hostname || '-'; } catch { }
                return host + ':' + Math.round(r.duration) + 'ms/' + (r.initiatorType || '-');
            });

        function ms(value) {
            return Number.isFinite(value) ? Math.round(value) : -1;
        }

        return [
            'ready=' + document.readyState,
            'domInteractiveMs=' + (nav ? ms(nav.domInteractive) : -1),
            'domContentLoadedEndMs=' + (nav ? ms(nav.domContentLoadedEventEnd) : -1),
            'domCompleteMs=' + (nav ? ms(nav.domComplete) : -1),
            'loadEventEndMs=' + (nav ? ms(nav.loadEventEnd) : -1),
            'resources=' + resources.length,
            'pendingImages=' + pendingImages,
            'domNodes=' + document.getElementsByTagName('*').length,
            'slow=' + (slowResources.length ? slowResources.join(',') : '-')
        ].join(' ');
    } catch {
        return 'snapshot-unavailable';
    }
})();
""");

                string details;
                try
                {
                    details = JsonSerializer.Deserialize<string>(resultJson) ?? "snapshot-unavailable";
                }
                catch
                {
                    details = resultJson ?? "snapshot-unavailable";
                }

                AddSiteDiagnosticEventForPage(
                    currentUrl,
                    $"PERF snapshot={label} {details}");
            }
            catch
            {
                // Performance diagnostics must never affect browsing.
            }
        }

        private async Task ScheduleSiteDiagnosticPerformanceSnapshotsAsync(
            CoreWebView2 core,
            string pageUrl)
        {
            if (!_siteDiagnosticMode || core == null)
                return;

            string expectedHost = GetSiteDiagnosticHost(pageUrl);
            if (string.IsNullOrWhiteSpace(expectedHost) ||
                expectedHost == "-" ||
                expectedHost == "about")
                return;

            int[] delaysMs = { 1000, 5000, 15000, 30000 };
            string[] labels = { "+1s", "+5s", "+15s", "+30s" };

            for (int i = 0; i < delaysMs.Length; i++)
            {
                try
                {
                    int wait = i == 0 ? delaysMs[i] : delaysMs[i] - delaysMs[i - 1];
                    await Task.Delay(wait);

                    if (!_siteDiagnosticMode)
                        return;

                    await CaptureSiteDiagnosticPerformanceSnapshotAsync(
                        core,
                        expectedHost,
                        labels[i]);
                }
                catch
                {
                    return;
                }
            }
        }

        private void CoreWebView2_SiteDiagnosticLogEntryReceived(
            object? sender,
            CoreWebView2DevToolsProtocolEventReceivedEventArgs e)
        {
            if (!_siteDiagnosticMode)
                return;

            try
            {
                CoreWebView2? core = FindDiagnosticCoreForReceiver(sender, _siteDiagnosticLogReceivers);
                string pageUrl = core?.Source ?? "";

                using JsonDocument doc = JsonDocument.Parse(e.ParameterObjectAsJson);
                if (!doc.RootElement.TryGetProperty("entry", out JsonElement entry))
                    return;

                string level = entry.TryGetProperty("level", out JsonElement levelEl)
                    ? levelEl.GetString() ?? "-"
                    : "-";

                // Keep noise down. The useful evidence here is warnings/errors rather than
                // every ordinary console.log emitted by a modern website.
                if (!level.Equals("error", StringComparison.OrdinalIgnoreCase) &&
                    !level.Equals("warning", StringComparison.OrdinalIgnoreCase))
                    return;

                string source = entry.TryGetProperty("source", out JsonElement sourceEl)
                    ? sourceEl.GetString() ?? "-"
                    : "-";

                string message = entry.TryGetProperty("text", out JsonElement textEl)
                    ? textEl.GetString() ?? "-"
                    : "-";

                string eventUrl = entry.TryGetProperty("url", out JsonElement urlEl)
                    ? urlEl.GetString() ?? ""
                    : "";

                string line = entry.TryGetProperty("lineNumber", out JsonElement lineEl)
                    ? lineEl.ToString()
                    : "-";

                AddSiteDiagnosticEventForPage(
                    pageUrl,
                    $"CONSOLE level={level} source={source} eventHost={GetSiteDiagnosticHost(eventUrl)} " +
                    $"line={line} text={SanitizeSiteDiagnosticConsoleText(message)}");
            }
            catch
            {
                // Diagnostics must never affect browsing.
            }
        }

        private void CoreWebView2_SiteDiagnosticExceptionReceived(
            object? sender,
            CoreWebView2DevToolsProtocolEventReceivedEventArgs e)
        {
            if (!_siteDiagnosticMode)
                return;

            try
            {
                CoreWebView2? core = FindDiagnosticCoreForReceiver(sender, _siteDiagnosticExceptionReceivers);
                string pageUrl = core?.Source ?? "";

                using JsonDocument doc = JsonDocument.Parse(e.ParameterObjectAsJson);
                if (!doc.RootElement.TryGetProperty("exceptionDetails", out JsonElement details))
                    return;

                string text = details.TryGetProperty("text", out JsonElement textEl)
                    ? textEl.GetString() ?? "JavaScript exception"
                    : "JavaScript exception";

                if (details.TryGetProperty("exception", out JsonElement exceptionEl) &&
                    exceptionEl.TryGetProperty("description", out JsonElement descriptionEl))
                {
                    string description = descriptionEl.GetString() ?? "";
                    if (!string.IsNullOrWhiteSpace(description))
                        text = description;
                }

                string eventUrl = details.TryGetProperty("url", out JsonElement urlEl)
                    ? urlEl.GetString() ?? ""
                    : "";

                string line = details.TryGetProperty("lineNumber", out JsonElement lineEl)
                    ? lineEl.ToString()
                    : "-";

                AddSiteDiagnosticEventForPage(
                    pageUrl,
                    $"JS_EXCEPTION eventHost={GetSiteDiagnosticHost(eventUrl)} line={line} " +
                    $"text={SanitizeSiteDiagnosticConsoleText(text)}");
            }
            catch
            {
                // Diagnostics must never affect browsing.
            }
        }

        private async Task RegisterSiteDiagnosticActionHooksAsync(CoreWebView2 core)
        {
            if (!_siteDiagnosticMode || core == null)
                return;

            try
            {
                if (!_siteDiagnosticNavigationHookedCores.Contains(core))
                {
                    core.NavigationStarting += CoreWebView2_SiteDiagnosticNavigationStarting;
                    _siteDiagnosticNavigationHookedCores.Add(core);
                }

                if (!_siteDiagnosticDomContentLoadedHookedCores.Contains(core))
                {
                    core.DOMContentLoaded += CoreWebView2_SiteDiagnosticDOMContentLoaded;
                    _siteDiagnosticDomContentLoadedHookedCores.Add(core);
                }
            }
            catch { }

            try
            {
                if (!_siteDiagnosticLogReceivers.ContainsKey(core))
                {
                    await core.CallDevToolsProtocolMethodAsync("Log.enable", "{}");
                    var receiver = core.GetDevToolsProtocolEventReceiver("Log.entryAdded");
                    receiver.DevToolsProtocolEventReceived += CoreWebView2_SiteDiagnosticLogEntryReceived;
                    _siteDiagnosticLogReceivers[core] = receiver;
                }
            }
            catch
            {
                AddSiteDiagnosticEventForPage(core.Source, "DEVTOOLS Log diagnostics unavailable");
            }

            try
            {
                if (!_siteDiagnosticExceptionReceivers.ContainsKey(core))
                {
                    await core.CallDevToolsProtocolMethodAsync("Runtime.enable", "{}");
                    var receiver = core.GetDevToolsProtocolEventReceiver("Runtime.exceptionThrown");
                    receiver.DevToolsProtocolEventReceived += CoreWebView2_SiteDiagnosticExceptionReceived;
                    _siteDiagnosticExceptionReceivers[core] = receiver;
                }
            }
            catch
            {
                AddSiteDiagnosticEventForPage(core.Source, "DEVTOOLS JavaScript exception diagnostics unavailable");
            }
        }

        private async Task RegisterSiteDiagnosticsEarlyAsync(CoreWebView2 core)
        {
            if (!_siteDiagnosticMode || core == null)
                return;

            try
            {
                if (!_siteDiagnosticMessageHookedCores.Contains(core))
                {
                    core.WebMessageReceived += CoreWebView2_SiteDiagnosticWebMessageReceived;
                    _siteDiagnosticMessageHookedCores.Add(core);
                }

                if (!_siteDiagnosticScriptIds.ContainsKey(core))
                {
                    string scriptId = await core.AddScriptToExecuteOnDocumentCreatedAsync(
                        GetSiteDiagnosticsJavaScript());

                    _siteDiagnosticScriptIds[core] = scriptId;
                }
            }
            catch
            {
                // Immediate diagnostics below still work if early registration fails.
            }

            await RegisterSiteDiagnosticActionHooksAsync(core);
            await InstallSiteDiagnosticsAsync(core);
        }

        private void UnregisterSiteDiagnosticsScripts()
        {
            foreach (var pair in _siteDiagnosticScriptIds.ToArray())
            {
                try
                {
                    pair.Key.RemoveScriptToExecuteOnDocumentCreated(pair.Value);
                }
                catch { }
            }

            _siteDiagnosticScriptIds.Clear();

            foreach (var core in _siteDiagnosticMessageHookedCores.ToArray())
            {
                try
                {
                    core.WebMessageReceived -= CoreWebView2_SiteDiagnosticWebMessageReceived;
                }
                catch { }
            }

            _siteDiagnosticMessageHookedCores.Clear();

            foreach (var core in _siteDiagnosticNavigationHookedCores.ToArray())
            {
                try
                {
                    core.NavigationStarting -= CoreWebView2_SiteDiagnosticNavigationStarting;
                }
                catch { }
            }

            _siteDiagnosticNavigationHookedCores.Clear();

            foreach (var core in _siteDiagnosticDomContentLoadedHookedCores.ToArray())
            {
                try
                {
                    core.DOMContentLoaded -= CoreWebView2_SiteDiagnosticDOMContentLoaded;
                }
                catch { }
            }

            _siteDiagnosticDomContentLoadedHookedCores.Clear();
            _siteDiagnosticNavigationStartedUtc.Clear();

            foreach (var pair in _siteDiagnosticLogReceivers.ToArray())
            {
                try
                {
                    pair.Value.DevToolsProtocolEventReceived -= CoreWebView2_SiteDiagnosticLogEntryReceived;
                    _ = pair.Key.CallDevToolsProtocolMethodAsync("Log.disable", "{}");
                }
                catch { }
            }

            _siteDiagnosticLogReceivers.Clear();

            foreach (var pair in _siteDiagnosticExceptionReceivers.ToArray())
            {
                try
                {
                    pair.Value.DevToolsProtocolEventReceived -= CoreWebView2_SiteDiagnosticExceptionReceived;
                    _ = pair.Key.CallDevToolsProtocolMethodAsync("Runtime.disable", "{}");
                }
                catch { }
            }

            _siteDiagnosticExceptionReceivers.Clear();
        }

        private async Task DumpSiteDiagnosticsAsync(CoreWebView2? core)
        {
            try
            {
                var domItems = new List<string>();
                string currentSource = "";

                if (core != null)
                {
                    try
                    {
                        currentSource = core.Source ?? "";
                        RecordSiteDiagnosticPageState(currentSource);

                        string result = await core.ExecuteScriptAsync("""
(function () {
    try {
        if (window.__wppSiteDiagnosticSnapshot)
            window.__wppSiteDiagnosticSnapshot('manual-dump');

        if (window.__wppSiteDiagnosticObserver) {
            try { window.__wppSiteDiagnosticObserver.disconnect(); } catch { }
        }

        return window.__wppSiteDiagnosticEvents || [];
    } catch {
        return [];
    }
})();
""");

                        domItems = JsonSerializer.Deserialize<List<string>>(result) ?? new List<string>();
                    }
                    catch
                    {
                        // Keep the C# network/popup diagnostics even if page script dump fails.
                    }
                }

                List<string> hostEvents;
                List<string> domEvents;
                Dictionary<string, int> requestCounts;
                Dictionary<string, int> blockCounts;
                Dictionary<string, string> pageStates;

                lock (_siteDiagnosticSync)
                {
                    hostEvents = _siteDiagnosticHostEvents.ToList();
                    domEvents = _siteDiagnosticDomEvents.ToList();
                    requestCounts = new Dictionary<string, int>(
                        _siteDiagnosticRequestCounts,
                        StringComparer.OrdinalIgnoreCase);
                    blockCounts = new Dictionary<string, int>(
                        _siteDiagnosticBlockCounts,
                        StringComparer.OrdinalIgnoreCase);
                    pageStates = new Dictionary<string, string>(
                        _siteDiagnosticPageStates,
                        StringComparer.OrdinalIgnoreCase);
                }

                Directory.CreateDirectory(Path.GetDirectoryName(_siteDiagnosticLogPath)!);

                // Live WebMessage capture survives navigations. Add the current page buffer
                // as a final safety net, then de-duplicate identical lines.
                var combinedDomEvents = domEvents
                    .Concat(domItems)
                    .Distinct(StringComparer.Ordinal)
                    .TakeLast(SiteDiagnosticMaxDomEvents)
                    .ToList();

                var siteHosts = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

                foreach (string stateHost in pageStates.Keys)
                {
                    if (!string.IsNullOrWhiteSpace(stateHost) &&
                        stateHost != "-" &&
                        stateHost != "about")
                    {
                        siteHosts.Add(stateHost);
                    }
                }

                foreach (string item in combinedDomEvents)
                {
                    string pageHost = ExtractSiteDiagnosticPageHost(item);
                    if (pageHost != "-" && pageHost != "about")
                        siteHosts.Add(pageHost);
                }

                foreach (string item in hostEvents)
                {
                    string pageHost = ExtractSiteDiagnosticPageHost(item);
                    if (pageHost != "-" && pageHost != "about")
                        siteHosts.Add(pageHost);
                }

                foreach (string key in requestCounts.Keys.Concat(blockCounts.Keys))
                {
                    string pageHost = ExtractSiteDiagnosticPageHost(key);
                    if (pageHost != "-" && pageHost != "about")
                        siteHosts.Add(pageHost);
                }

                var lines = new List<string>
                {
                    $"===== Per-Site Diagnostics {DateTime.Now:yyyy-MM-dd HH:mm:ss} =====",
                    $"Sites observed: {siteHosts.Count}",
                    "Each site below has its own DOM, popup and network evidence.",
                    "Network entries record PAGE host and REQUEST host separately.",
                    "Privacy note: no page text, form values, cookies, passwords, or full URLs are recorded.",
                    ""
                };

                foreach (string siteHost in siteHosts.OrderBy(x => x, StringComparer.OrdinalIgnoreCase))
                {
                    lines.Add($"================ SITE: {siteHost} ================");

                    if (pageStates.TryGetValue(siteHost, out string? state) &&
                        !string.IsNullOrWhiteSpace(state))
                    {
                        lines.Add($"STATE | {state}");
                    }
                    else
                    {
                        lines.Add("STATE | No state snapshot was captured for this site.");
                    }

                    lines.Add("");
                    lines.Add("---- DOM / Overlay / Ad-like Events ----");

                    var siteDomEvents = combinedDomEvents
                        .Where(x => string.Equals(
                            ExtractSiteDiagnosticPageHost(x),
                            siteHost,
                            StringComparison.OrdinalIgnoreCase))
                        .TakeLast(500)
                        .ToList();

                    if (siteDomEvents.Count == 0)
                        lines.Add("(none recorded)");
                    else
                        lines.AddRange(siteDomEvents);

                    lines.Add("");
                    lines.Add("---- Browser / Popup Events ----");

                    var siteBrowserEvents = hostEvents
                        .Where(x => string.Equals(
                            ExtractSiteDiagnosticPageHost(x),
                            siteHost,
                            StringComparison.OrdinalIgnoreCase))
                        .TakeLast(250)
                        .ToList();

                    if (siteBrowserEvents.Count == 0)
                        lines.Add("(none recorded)");
                    else
                        lines.AddRange(siteBrowserEvents);

                    lines.Add("");
                    lines.Add("---- Network Request Summary ----");
                    lines.Add("Allowed~ = requests minus requests blocked by LexDesk Pro during this run.");

                    var siteRequestCounts = requestCounts
                        .Where(x => string.Equals(
                            ExtractSiteDiagnosticPageHost(x.Key),
                            siteHost,
                            StringComparison.OrdinalIgnoreCase))
                        .OrderByDescending(x => x.Value)
                        .Take(200)
                        .ToList();

                    if (siteRequestCounts.Count == 0)
                    {
                        lines.Add("(no network requests recorded)");
                    }
                    else
                    {
                        foreach (var pair in siteRequestCounts)
                        {
                            blockCounts.TryGetValue(pair.Key, out int blocked);
                            int allowedApprox = Math.Max(0, pair.Value - blocked);
                            lines.Add($"REQUESTS={pair.Value} BLOCKED={blocked} ALLOWED~={allowedApprox} | {pair.Key}");
                        }
                    }

                    foreach (var pair in blockCounts
                        .Where(x =>
                            !requestCounts.ContainsKey(x.Key) &&
                            string.Equals(
                                ExtractSiteDiagnosticPageHost(x.Key),
                                siteHost,
                                StringComparison.OrdinalIgnoreCase))
                        .OrderByDescending(x => x.Value)
                        .Take(50))
                    {
                        lines.Add($"REQUESTS=? BLOCKED={pair.Value} ALLOWED~=? | {pair.Key}");
                    }

                    lines.Add("");
                    lines.Add($"============== END SITE: {siteHost} ==============");
                    lines.Add("");
                }

                // Keep anything that could not be assigned to a page host visible rather
                // than silently dropping useful evidence from older/edge-case events.
                var unassignedDom = combinedDomEvents
                    .Where(x => ExtractSiteDiagnosticPageHost(x) == "-")
                    .TakeLast(100)
                    .ToList();

                var unassignedBrowser = hostEvents
                    .Where(x => ExtractSiteDiagnosticPageHost(x) == "-")
                    .TakeLast(100)
                    .ToList();

                if (unassignedDom.Count > 0 || unassignedBrowser.Count > 0)
                {
                    lines.Add("===== UNASSIGNED DIAGNOSTIC EVENTS =====");
                    lines.AddRange(unassignedDom);
                    lines.AddRange(unassignedBrowser);
                    lines.Add("");
                }

                lines.Add("===== End Per-Site Diagnostics =====");
                lines.Add("");

                File.WriteAllLines(_siteDiagnosticLogPath, lines);
            }
            catch
            {
                // Diagnostics must never affect browsing.
            }
        }

        private async Task ToggleSiteDiagnosticsAsync()
        {
            if (!LexDeskDeveloperDiagnosticsEnabled)
            {
                _siteDiagnosticMode = false;
                return;
            }

            CoreWebView2? activeCore = null;

            try
            {
                activeCore = GetActiveWebView()?.CoreWebView2;
            }
            catch
            {
                activeCore = null;
            }

            if (!_siteDiagnosticMode)
            {
                _siteDiagnosticMode = true;
                ResetSiteDiagnosticBuffers();

                try
                {
                    Directory.CreateDirectory(Path.GetDirectoryName(_siteDiagnosticLogPath)!);
                    File.WriteAllText(
                        _siteDiagnosticLogPath,
                        $"Per-Site Diagnostics started {DateTime.Now:yyyy-MM-dd HH:mm:ss}{Environment.NewLine}");
                }
                catch
                {
                    // Diagnostics must never affect browsing.
                }

                foreach (var view in new[] { Web, Web2, Web3, Web4 })
                {
                    try
                    {
                        if (view?.CoreWebView2 != null)
                            await RegisterSiteDiagnosticsEarlyAsync(view.CoreWebView2);
                    }
                    catch { }
                }

                AddSiteDiagnosticEventForPage(
                    activeCore?.Source,
                    "DIAGNOSTICS ON");

                UpdateSecurityStatus("Site diagnostics ON", false);

                ShowProtectionPopup(
                    "LexDesk Pro - Site Diagnostics",
                    "Per-Site Diagnostics ON",
                    "Developer-only site diagnostics are now ON.\n\n" +
                    "Stage 4C.5 records DOM ready timing, navigation completion, 1/5/15/30-second performance snapshots, " +
                    "popup decisions, blocked-request reasons, and privacy-safe JavaScript/console errors.\n\n" +
                    "No page text, form values, cookies, passwords, or full URLs are logged.\n\n" +
                    "Slow-page test: reload the problem page, use it normally, then leave it open for at least 30 seconds. " +
                    "Press Ctrl + Shift + O again to save the per-site log.",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
            else
            {
                AddSiteDiagnosticEventForPage(
                    activeCore?.Source,
                    "DIAGNOSTICS OFF");

                await DumpSiteDiagnosticsAsync(activeCore);
                UnregisterSiteDiagnosticsScripts();
                _siteDiagnosticMode = false;

                UpdateSecurityStatus("Site diagnostics OFF", false);

                ShowProtectionPopup(
                    "LexDesk Pro - Site Diagnostics",
                    "Per-Site Diagnostics OFF",
                    "The local diagnostic log has been saved to:\n\n" +
                    _siteDiagnosticLogPath,
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

