        private string GetCleanAddress(string url)
        {
            if (string.IsNullOrWhiteSpace(url))
                return "";

            try
            {
                var uri = new Uri(url);
                return uri.Host.Replace("www.", "") + "/";
            }
            catch
            {
                return url;
            }
        }

        // ============================================
        // Web History + Shared WebView Environment
        // ============================================
        private readonly List<string> _history = new();

        // History is written shortly after navigation settles instead of serialising the
        // entire list synchronously on every single completed navigation.
        private readonly DispatcherTimer _historySaveTimer = new DispatcherTimer
        {
            Interval = TimeSpan.FromMilliseconds(750)
        };
        private bool _historySaveTimerHooked = false;

        private readonly string _historyPath =
    AppDataPath("history.json");

        // Shared WebView2 environment (prevents "already initialized with different environment" errors)
        private CoreWebView2Environment? _sharedWebViewEnv;

        // ============================================
        // Bookmarks
        // ============================================

        private readonly List<BookmarkItem> _bookmarks = new();
        private readonly string _bookmarksPath =
    AppDataPath("bookmarks.json");

        private sealed record BookmarkItem(string Title, string Url, DateTime AddedUtc);


        // ============================================
        // Session State
        // ============================================

        private sealed record AppSessionState(
            string?[] PageUrls,
            int ActivePageIndex,
            int LayoutPageCount
        );

        private void LoadHistory()
        {
            try
            {
                if (!File.Exists(_historyPath)) return;

                var json = File.ReadAllText(_historyPath);
                var items = JsonSerializer.Deserialize<List<string>>(json);

                _history.Clear();

                if (items != null)
                {
                    foreach (var url in items)
                    {
                        if (!string.IsNullOrWhiteSpace(url))
                            _history.Add(url);
                    }
                }
            }
            catch { }
        }

        private string FormatHistoryLabel(string url)
        {
            if (string.IsNullOrWhiteSpace(url))
                return "";

            try
            {
                var uri = new Uri(url);
                string host = uri.Host.Replace("www.", "");
                string path = uri.AbsolutePath?.Trim('/') ?? "";

                if (string.IsNullOrWhiteSpace(path) || path == "/")
                    return host;

                string combined = $"{host} / {path}";

                if (combined.Length <= 52)
                    return combined;

                return combined.Substring(0, 49) + "...";
            }
            catch
            {
                if (url.Length <= 52)
                    return url;

                return url.Substring(0, 49) + "...";
            }
        }

        private void SaveHistory()
        {
            try
            {
                _historySaveTimer.Stop();

                Directory.CreateDirectory(Path.GetDirectoryName(_historyPath)!);

                var json = JsonSerializer.Serialize(
                    _history,
                    JsonIndentedOptions);

                File.WriteAllText(_historyPath, json);
            }
            catch { }
        }

        private void ScheduleHistorySave()
        {
            try
            {
                if (!_historySaveTimerHooked)
                {
                    _historySaveTimer.Tick += (_, __) =>
                    {
                        _historySaveTimer.Stop();
                        SaveHistory();
                    };

                    _historySaveTimerHooked = true;
                }

                _historySaveTimer.Stop();
                _historySaveTimer.Start();
            }
            catch
            {
                // Fall back to an immediate save if the UI timer is unavailable.
                SaveHistory();
            }
        }

        private void FlushPendingHistorySave()
        {
            try
            {
                if (_historySaveTimer.IsEnabled)
                {
                    _historySaveTimer.Stop();
                    SaveHistory();
                }
            }
            catch { }
        }

        private string ShortenUrl(string url)
        {
            if (string.IsNullOrWhiteSpace(url))
                return "";

            try
            {
                var uri = new Uri(url);
                string host = uri.Host.Replace("www.", "");

                if (url.Length <= 60)
                    return host;

                return host + " ...";
            }
            catch
            {
                if (url.Length <= 60)
                    return url;

                return url.Substring(0, 57) + "...";
            }
        }

        private void LoadBookmarks()
        {
            try
            {
                if (!File.Exists(_bookmarksPath)) return;

                var json = File.ReadAllText(_bookmarksPath);
                var items = System.Text.Json.JsonSerializer.Deserialize<List<BookmarkItem>>(json);
                _bookmarks.Clear();
                if (items != null) _bookmarks.AddRange(items);
            }
            catch { /* swallow or log */ }
        }

        private void SaveBookmarks()
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_bookmarksPath)!);

                var json = System.Text.Json.JsonSerializer.Serialize(
                    _bookmarks,
                    new System.Text.Json.JsonSerializerOptions { WriteIndented = true });

                File.WriteAllText(_bookmarksPath, json);
            }
            catch { /* swallow or log */ }
        }

        // ============================================
        // Web Page State / Snapshots
        // ============================================
        private enum PaneLifeState
        {
            Normal,
            Minimized,
            Closed
        }

        private sealed class BrowserWorkspace
        {
            public string Title { get; set; } = "Tab";

            // 4-web page state
            public string[] PageUrls { get; set; } = new string[4];

            public int ActivePageIndex { get; set; } = 0;
            public int LayoutPageCount { get; set; } = 1;

            public bool[] PageLocked { get; set; } = new bool[4];

            public PaneLifeState[] PaneState { get; set; } = new PaneLifeState[4];

            public int[] StudioSlotIndex { get; set; } = new int[4];

            public BrowserWorkspace()
            {
                PageUrls[0] = "lexwhite://newtab";
                PageUrls[1] = "about:blank";
                PageUrls[2] = "about:blank";
                PageUrls[3] = "about:blank";

                for (int i = 0; i < PaneState.Length; i++)
                    PaneState[i] = i == 0 ? PaneLifeState.Normal : PaneLifeState.Minimized;

                for (int i = 0; i < StudioSlotIndex.Length; i++)
                    StudioSlotIndex[i] = -1;
            }
        }

        private readonly PaneLifeState[] _paneState = new PaneLifeState[4]
        {
    PaneLifeState.Normal, PaneLifeState.Normal, PaneLifeState.Normal, PaneLifeState.Normal
        };

        private sealed class LayoutSnapshot
        {
            public PaneLifeState[] PaneState { get; init; } = new PaneLifeState[4];
            public int ActivePane { get; init; }
            public bool WasMaximizedMode { get; init; }
            public int MaximizedPane { get; init; } = -1;
            public int LayoutPageCount { get; init; }
        }

        private LayoutSnapshot? _lastSnapshot = null;

        // “Maximise pane” mode
        private bool _isPaneMaximizedMode = false;
        private int _maximizedPane = -1;

        private List<int> VisiblePanes()
        {
            var list = new List<int>(4);
            for (int i = 0; i < 4; i++)
                if (_paneState[i] == PaneLifeState.Normal)
                    list.Add(i);
            return list;
        }

        private bool IsLexDeskManagedTrackedProcessAlive(
            string key)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(key) ||
                    !_lexDeskManagedWindowIdentities.TryGetValue(
                        key,
                        out LexDeskManagedWindowIdentity? identity) ||
                    identity.MainProcessId == 0)
                {
                    return false;
                }

                using Process process =
                    Process.GetProcessById(
                        (int)identity.MainProcessId);

                return !process.HasExited;
            }
            catch
            {
                return false;
            }
        }

        // Removes dead managed-app windows and releases a pane only when the
        // complete app session has really gone away.
        private void CleanupLexDeskManagedWindowRegistrations()
        {
            try
            {
                foreach (var familyPair in
                         _lexDeskManagedWindowFamilies.ToList())
                {
                    string key = familyPair.Key;
                    HashSet<IntPtr> family = familyPair.Value;

                    foreach (IntPtr hWnd in family.ToList())
                    {
                        if (hWnd != IntPtr.Zero && IsWindow(hWnd))
                            continue;

                        WriteLexDeskManagedWindowDebug(
                            $"FAMILY WINDOW REMOVED | app={key} | " +
                            $"{DescribeLexDeskManagedWindowForDebug(hWnd)}");

                        family.Remove(hWnd);
                        _lexDeskManagedWindowFamilyKeys.Remove(hWnd);
                        _lexDeskManagedZOrderAssistWindows.Remove(hWnd);
                    }

                    if (family.Count > 0)
                    {
                        _lexDeskManagedSessionMissingWindowSinceUtc.Remove(key);

                        if (!_lexDeskManagedWindows.TryGetValue(key, out IntPtr main) ||
                            main == IntPtr.Zero ||
                            !IsWindow(main))
                        {
                            _lexDeskManagedWindows[key] = family.First();
                        }

                        continue;
                    }

                    // Do not instantly release a pane merely because an app has
                    // swapped/destroyed its current HWND. If its tracked process is
                    // still alive, keep the session briefly so popup discovery can
                    // capture the replacement window.
                    if (IsLexDeskManagedTrackedProcessAlive(key))
                    {
                        DateTime now =
                            DateTime.UtcNow;

                        if (!_lexDeskManagedSessionMissingWindowSinceUtc.TryGetValue(
                                key,
                                out DateTime missingSince))
                        {
                            _lexDeskManagedSessionMissingWindowSinceUtc[key] =
                                now;

                            WriteLexDeskManagedWindowDebug(
                                $"SESSION WINDOW GAP START | app={key} | process_alive=True");

                            continue;
                        }

                        if ((now - missingSince) <
                            LexDeskManagedReplacementWindowGrace)
                        {
                            continue;
                        }
                    }

                    _lexDeskManagedSessionMissingWindowSinceUtc.Remove(key);

                    WriteLexDeskManagedWindowDebug(
                        $"SESSION FAMILY EMPTY | app={key}");

                    ReleaseLexDeskManagedSession(key);
                }

                // Backward-compatible cleanup for managed tools that have not yet
                // created a family entry.
                foreach (var pair in _lexDeskManagedWindows.ToList())
                {
                    if (pair.Value != IntPtr.Zero && IsWindow(pair.Value))
                    {
                        EnsureLexDeskManagedFamilyContains(
                            pair.Key,
                            pair.Value);
                        continue;
                    }

                    if (IsLexDeskManagedTrackedProcessAlive(pair.Key))
                    {
                        DateTime now =
                            DateTime.UtcNow;

                        if (!_lexDeskManagedSessionMissingWindowSinceUtc.TryGetValue(
                                pair.Key,
                                out DateTime missingSince))
                        {
                            _lexDeskManagedSessionMissingWindowSinceUtc[pair.Key] =
                                now;

                            continue;
                        }

                        if ((now - missingSince) <
                            LexDeskManagedReplacementWindowGrace)
                        {
                            continue;
                        }
                    }

                    _lexDeskManagedSessionMissingWindowSinceUtc.Remove(pair.Key);
                    ReleaseLexDeskManagedSession(pair.Key);
                }

                foreach (var panePair in _lexDeskManagedPaneOwners.ToList())
                {
                    if (!LexDeskManagedSessionHasLiveWindow(panePair.Value))
                        _lexDeskManagedPaneOwners.Remove(panePair.Key);
                }
            }
            catch
            {
                // Occupancy cleanup must never affect normal browsing.
            }
        }

        private void EnsureLexDeskManagedFamilyContains(
            string key,
            IntPtr hWnd)
        {
            if (string.IsNullOrWhiteSpace(key) ||
                hWnd == IntPtr.Zero ||
                !IsWindow(hWnd))
            {
                return;
            }

            // A top-level HWND may belong to ONE LexDesk session only.
            // ApplicationFrameHost is shared by Calculator, Settings and other
            // Windows apps, so allowing the same HWND into two families makes one
            // app appear to replace/disappear when the other is activated.
            if (_lexDeskManagedWindowFamilyKeys.TryGetValue(
                    hWnd,
                    out string? existingKey) &&
                !string.Equals(
                    existingKey,
                    key,
                    StringComparison.OrdinalIgnoreCase))
            {
                WriteLexDeskManagedWindowDebug(
                    $"SESSION HWND COLLISION BLOCKED | " +
                    $"HWND=0x{hWnd.ToInt64():X} | " +
                    $"existing={existingKey} | attempted={key}");

                return;
            }

            if (!_lexDeskManagedWindowFamilies.TryGetValue(
                    key,
                    out HashSet<IntPtr>? family))
            {
                family = new HashSet<IntPtr>();
                _lexDeskManagedWindowFamilies[key] = family;
            }

            family.Add(hWnd);
            _lexDeskManagedWindowFamilyKeys[hWnd] = key;
        }

        private bool LexDeskManagedSessionHasLiveWindow(string key)
        {
            if (string.IsNullOrWhiteSpace(key))
                return false;

            if (_lexDeskManagedWindowFamilies.TryGetValue(
                    key,
                    out HashSet<IntPtr>? family) &&
                family.Any(hWnd => hWnd != IntPtr.Zero && IsWindow(hWnd)))
            {
                return true;
            }

            return _lexDeskManagedWindows.TryGetValue(key, out IntPtr main) &&
                   main != IntPtr.Zero &&
                   IsWindow(main);
        }

        private void ReleaseLexDeskManagedSession(string key)
        {
            if (string.IsNullOrWhiteSpace(key))
                return;

            WriteLexDeskManagedWindowDebug(
                $"SESSION RELEASE BEGIN | app={key} | " +
                $"{DescribeLexDeskManagedProcessForDebug(key)}");

            if (_lexDeskManagedWindowFamilies.TryGetValue(
                    key,
                    out HashSet<IntPtr>? family))
            {
                foreach (IntPtr hWnd in family.ToList())
                {
                    _lexDeskManagedWindowFamilyKeys.Remove(hWnd);
                    _lexDeskManagedZOrderAssistWindows.Remove(hWnd);
                }
            }

            _lexDeskManagedWindowFamilies.Remove(key);
            _lexDeskManagedWindows.Remove(key);
            _lexDeskManagedWindowIdentities.Remove(key);
            _lexDeskManagedNativeShellSessions.Remove(key);
            _lexDeskManagedSessionMissingWindowSinceUtc.Remove(key);

            if (_lexDeskManagedWindowPageIndexes.TryGetValue(
                    key,
                    out int pageIndex) &&
                _lexDeskManagedPaneOwners.TryGetValue(
                    pageIndex,
                    out string? ownerKey) &&
                string.Equals(ownerKey, key, StringComparison.OrdinalIgnoreCase))
            {
                _lexDeskManagedPaneOwners.Remove(pageIndex);

                WriteLexDeskManagedWindowDebug(
                    $"PANE RELEASE | app={key} | page={pageIndex}");
            }

            _lexDeskManagedWindowPageIndexes.Remove(key);

            WriteLexDeskManagedWindowDebug(
                $"SESSION RELEASE END | app={key}");

            QueueLexDeskManagedSessionStateDump(
                $"session released: {key}");

            if (string.Equals(
                    _lexDeskLastManagedWindowKey,
                    key,
                    StringComparison.OrdinalIgnoreCase))
            {
                _lexDeskLastManagedWindowKey = "";
            }
        }

        private void RegisterLexDeskManagedSessionMainWindow(
            string key,
            IntPtr hWnd,
            int pageIndex,
            string[] processNames,
            string[] titleHints,
            string[] classHints)
        {
            if (string.IsNullOrWhiteSpace(key) ||
                hWnd == IntPtr.Zero ||
                !IsWindow(hWnd))
            {
                return;
            }

            // Never steal a live window from another managed session.
            // This is especially important for shared ApplicationFrameHost windows.
            if (_lexDeskManagedWindowFamilyKeys.TryGetValue(
                    hWnd,
                    out string? existingFamilyKey) &&
                !string.Equals(
                    existingFamilyKey,
                    key,
                    StringComparison.OrdinalIgnoreCase) &&
                LexDeskManagedSessionHasLiveWindow(
                    existingFamilyKey))
            {
                WriteLexDeskManagedWindowDebug(
                    $"MAIN SESSION COLLISION BLOCKED | " +
                    $"HWND=0x{hWnd.ToInt64():X} | " +
                    $"existing={existingFamilyKey} | attempted={key}");

                return;
            }

            // If this app was already assigned, keep its existing pane. Clicking
            // the same taskbar icon must focus the app, not make it jump to the
            // next free pane.
            if (_lexDeskManagedWindowPageIndexes.TryGetValue(
                    key,
                    out int existingPage) &&
                existingPage >= 0 &&
                existingPage <= 3 &&
                LexDeskManagedSessionHasLiveWindow(key))
            {
                pageIndex = existingPage;
            }

            _lexDeskManagedWindows[key] = hWnd;
            EnsureLexDeskManagedFamilyContains(key, hWnd);
            _lexDeskManagedSessionMissingWindowSinceUtc.Remove(key);

            if (pageIndex >= 0 && pageIndex <= 3)
            {
                // Remove any stale old assignment for this same app key.
                foreach (var panePair in _lexDeskManagedPaneOwners
                             .Where(p => string.Equals(
                                 p.Value,
                                 key,
                                 StringComparison.OrdinalIgnoreCase) &&
                                 p.Key != pageIndex)
                             .ToList())
                {
                    _lexDeskManagedPaneOwners.Remove(panePair.Key);
                }

                _lexDeskManagedWindowPageIndexes[key] = pageIndex;
                _lexDeskManagedPaneOwners[pageIndex] = key;

                WriteLexDeskManagedWindowDebug(
                    $"PANE ASSIGN | app={key} | page={pageIndex + 1} | " +
                    $"{DescribeLexDeskManagedWindowForDebug(hWnd)}");
            }

            GetWindowThreadProcessId(hWnd, out uint processId);

            _lexDeskManagedWindowIdentities[key] =
                new LexDeskManagedWindowIdentity
                {
                    ProcessNames = processNames ?? Array.Empty<string>(),
                    TitleHints = titleHints ?? Array.Empty<string>(),
                    ClassHints = classHints ?? Array.Empty<string>(),
                    MainProcessName = GetLexDeskWindowProcessName(hWnd),
                    MainProcessId = processId,
                    MainClassName = GetLexDeskWindowClass(hWnd)
                };

            if (string.Equals(
                    key,
                    "Calculator",
                    StringComparison.OrdinalIgnoreCase))
            {
                _lexDeskManagedZOrderAssistWindows.Add(
                    hWnd);
            }

            QueueLexDeskManagedSessionStateDump(
                $"session registered: {key}");

            QueueLexDeskWindowsHostedSurfaceStateDump(
                $"session registered: {key}");
        }

        private bool IsLexDeskManagedPageOccupied(int pageIndex)
        {
            try
            {
                CleanupLexDeskManagedWindowRegistrations();

                if (_lexDeskManagedPaneOwners.TryGetValue(
                        pageIndex,
                        out string? ownerKey))
                {
                    if (LexDeskManagedSessionHasLiveWindow(ownerKey))
                        return true;

                    _lexDeskManagedPaneOwners.Remove(pageIndex);
                }

                // Backward compatibility for an older managed-tool registration.
                foreach (var pair in _lexDeskManagedWindowPageIndexes)
                {
                    if (pair.Value != pageIndex)
                        continue;

                    if (LexDeskManagedSessionHasLiveWindow(pair.Key))
                    {
                        _lexDeskManagedPaneOwners[pageIndex] = pair.Key;
                        return true;
                    }
                }
            }
            catch
            {
                // A failed occupancy check simply means LexDesk may reuse a pane.
            }

            return false;
        }

        private bool TryGetLexDeskExistingManagedPageIndex(
            string key,
            out int pageIndex)
        {
            pageIndex = -1;

            try
            {
                if (string.IsNullOrWhiteSpace(key))
                    return false;

                CleanupLexDeskManagedWindowRegistrations();

                if (_lexDeskManagedWindowPageIndexes.TryGetValue(
                        key.Trim(),
                        out int existingPage) &&
                    existingPage >= 2 &&
                    existingPage <= 3 &&
                    LexDeskManagedSessionHasLiveWindow(key.Trim()))
                {
                    pageIndex = existingPage;
                    return true;
                }
            }
            catch { }

            return false;
        }

        // External Windows apps use ONLY visual Pane 4 and Pane 3.
        //
        // Final LexDesk rule:
        //   4-pane layout: Pane 4 first, then Pane 3
        //   3-pane layout: Pane 3 only
        //   1/2-pane layouts: browser-only, no external app pane is available
        //
        // Panes 1 and 2 are deliberately kept for web browsing. This avoids the
        // Windows shared-host/z-order fight we saw when Settings and Calculator
        // were mixed across all four panes.
        //
        // A pane remains reserved while its managed app is open OR minimised.
        // Closing the app releases that pane. Security/antivirus software is the
        // exception and opens as a centred priority window instead of consuming
        // Pane 3 or Pane 4.
        private int GetLexDeskPreferredManagedPageIndex()
        {
            try
            {
                CleanupLexDeskManagedWindowRegistrations();

                // Maximised mode is eligible only when the maximised pane is
                // visual Pane 3 or Pane 4.
                if (_isPaneMaximizedMode &&
                    _maximizedPane >= 2 &&
                    _maximizedPane <= 3 &&
                    _paneState[_maximizedPane] == PaneLifeState.Normal)
                {
                    return IsLexDeskManagedPageOccupied(_maximizedPane)
                        ? -1
                        : _maximizedPane;
                }

                // Zero-based 3 = visual Pane 4, zero-based 2 = visual Pane 3.
                foreach (int pageIndex in new[] { 3, 2 })
                {
                    if (_paneState[pageIndex] != PaneLifeState.Normal)
                        continue;

                    if (!VisiblePanes().Contains(pageIndex))
                        continue;

                    if (!IsLexDeskManagedPageOccupied(pageIndex))
                        return pageIndex;
                }
            }
            catch
            {
                // Placement failure is treated as no free app pane.
            }

            return -1;
        }

        private void ShowLexDeskNoFreeManagedPaneMessage()
        {
            ShowLexDeskMessageBox(
                "LexDesk desktop apps use Pane 4 first, then Pane 3.\n\n" +
                "Close or finish with the app in Pane 3 or Pane 4, then try again. " +
                "If you are using a 1-pane or 2-pane layout, switch to the 3-pane or 4-pane layout first.",
                "App Panes In Use",
                MessageBoxButton.OK,
                MessageBoxImage.Information);
        }

        private void ActivateLexDeskManagedTargetPage(int pageIndex)
        {
            try
            {
                if (pageIndex < 0 ||
                    pageIndex > 3 ||
                    _paneState[pageIndex] != PaneLifeState.Normal)
                {
                    return;
                }

                _paneLastActiveUtc[pageIndex] = DateTime.UtcNow;

                if (_activePageIndex == pageIndex)
                    return;

                _activePageIndex = pageIndex;

                RefreshActivePaneStatusVisual();
                UpdatePageHostBorders();
                UpdatePageModeButtonVisuals();
                UpdateSecureSiteVisual();
            }
            catch
            {
                // Managed-app activation must never affect normal browsing.
            }
        }

        private void SaveSnapshot()
        {
            _lastSnapshot = new LayoutSnapshot
            {
                PaneState = (PaneLifeState[])_paneState.Clone(),
                ActivePane = _activePageIndex,
                WasMaximizedMode = _isPaneMaximizedMode,
                MaximizedPane = _maximizedPane,
                LayoutPageCount = _layoutPageCount
            };
        }

        private void RestoreSnapshot()
        {
            if (_lastSnapshot == null) return;

            Array.Copy(_lastSnapshot.PaneState, _paneState, 4);
            _activePageIndex = _lastSnapshot.ActivePane;

            _isPaneMaximizedMode = _lastSnapshot.WasMaximizedMode;
            _maximizedPane = _lastSnapshot.MaximizedPane;

            _layoutPageCount = _lastSnapshot.LayoutPageCount;

            ApplyLayout();
            UpdatePageModeButtonVisuals();
            UpdatePageHostBorders();
            UpdateSecureSiteVisual();
        }

        private void SaveCurrentWorkspace()
        {
            if (_activeWorkspaceTabIndex < 0 || _activeWorkspaceTabIndex >= _workspaces.Count)
                return;

            // Fixed-tab safety:
            // Before saving, make sure this tab's panes still point to this tab's own Quick URL slots.
            // This prevents Tab 2 pages being saved into Tab 1, etc.
            RepairLiveQuickUrlSlotsForTab(_activeWorkspaceTabIndex);

            var ws = _workspaces[_activeWorkspaceTabIndex];

            ws.Title = $"Tab {_activeWorkspaceTabIndex + 1}";
            ws.ActivePageIndex = _activePageIndex;
            ws.LayoutPageCount = _layoutPageCount;

            Array.Copy(_pageUrls, ws.PageUrls, 4);
            Array.Copy(_pageLocked, ws.PageLocked, 4);
            Array.Copy(_paneState, ws.PaneState, 4);
            Array.Copy(_studioSlotIndex, ws.StudioSlotIndex, 4);

            RepairWorkspaceQuickUrlSlots(ws, _activeWorkspaceTabIndex);
        }

        private void LoadWorkspace(int index)
        {
            if (index < 0 || index >= _workspaces.Count)
                return;

            _isSwitchingWorkspaceTab = true;

            var ws = _workspaces[index];

            // Fixed-tab safety:
            // Repair the workspace before copying it into the live panes.
            RepairWorkspaceQuickUrlSlots(ws, index);

            _activeWorkspaceTabIndex = index;

            // Restore this workspace exactly as the user left it.
            _activePageIndex = Math.Clamp(ws.ActivePageIndex, 0, 3);
            _layoutPageCount = Math.Clamp(ws.LayoutPageCount, 1, 4);

            Array.Copy(ws.PageUrls, _pageUrls, 4);
            Array.Copy(ws.PageLocked, _pageLocked, 4);
            Array.Copy(ws.PaneState, _paneState, 4);
            Array.Copy(ws.StudioSlotIndex, _studioSlotIndex, 4);

            // Make sure this tab still owns its correct Quick URL slots
            // without deliberately collapsing its saved layout.
            RepairLiveQuickUrlSlotsForTab(index);

            // Safety: the active page must still be one of the visible pages.
            if (_paneState[_activePageIndex] != PaneLifeState.Normal)
            {
                int firstVisiblePage = -1;

                for (int paneIndex = 0; paneIndex < 4; paneIndex++)
                {
                    if (_paneState[paneIndex] == PaneLifeState.Normal)
                    {
                        firstVisiblePage = paneIndex;
                        break;
                    }
                }

                if (firstVisiblePage >= 0)
                {
                    _activePageIndex = firstVisiblePage;
                }
                else
                {
                    _activePageIndex = 0;
                    _paneState[0] = PaneLifeState.Normal;
                    _layoutPageCount = 1;
                }
            }

            // Fixed tab safety:
            // The Startup Screen is allowed on app launch, but not when switching tabs.
            // If Page 1 is still a startup/blank placeholder, replace it with this tab's
            // correct Page 1 Quick URL before RefreshHomeOverlay1() gets a chance to show it.
            if (_isSwitchingWorkspaceTab && IsStartupPlaceholderUrl(_pageUrls[0]))
            {
                int quickUrlSlot = GetQuickUrlSlotForTabPage(index, 0);
                string quickUrl = GetQuickUrlForTabPage(index, 0);

                if (!IsStartupPlaceholderUrl(quickUrl))
                {
                    _pageUrls[0] = quickUrl;
                    _studioSlotIndex[0] = quickUrlSlot;

                    ws.PageUrls[0] = quickUrl;
                    ws.StudioSlotIndex[0] = quickUrlSlot;

                    _paneState[0] = PaneLifeState.Normal;
                    ws.PaneState[0] = PaneLifeState.Normal;

                    _layoutPageCount = Math.Max(_layoutPageCount, 1);
                    ws.LayoutPageCount = Math.Max(ws.LayoutPageCount, 1);
                }
            }

            _isPaneMaximizedMode = false;
            _maximizedPane = -1;

            ApplyLayout();

            for (int i = 0; i < 4; i++)
            {
                SetPageLocked(i, _pageLocked[i]);

                // Speed pass:
                // Do not navigate hidden/minimized pages when switching tabs.
                // Page buttons 1-4 will load those Quick URLs only when the user asks for them.
                if (_paneState[i] != PaneLifeState.Normal)
                    continue;

                string url = _pageUrls[i];

                // Speed Recovery:
                // If this pane has not been initialized yet, initialize it only now.
                _ = NavigatePaneWhenReadyAsync(i, url);
            }

            RefreshHomeOverlay1();
            UpdateWorkspaceTabVisuals();
            UpdatePageModeButtonVisuals();
            UpdatePageHostBorders();
            UpdateSecureSiteVisual();

            // Let the tab switch/navigation start, then allow normal overlay logic again.
            // Do not force RefreshHomeOverlay1() here; forcing it can bring the Startup Screen
            // back after a tab switch if Page 1 is still loading.
            _ = Dispatcher.BeginInvoke(new Action(async () =>
            {
                try
                {
                    await Task.Delay(350);
                }
                catch { }

                _isSwitchingWorkspaceTab = false;
            }), DispatcherPriority.Background);
        }

        private bool IsWorkspaceBlankOrDefault(BrowserWorkspace ws)
        {
            if (ws == null)
                return true;

            for (int i = 0; i < ws.PageUrls.Length; i++)
            {
                string url = ws.PageUrls[i] ?? "";

                bool isBlank =
                    string.IsNullOrWhiteSpace(url) ||
                    url.Equals("about:blank", StringComparison.OrdinalIgnoreCase) ||
                    url.Equals("lexwhite://newtab", StringComparison.OrdinalIgnoreCase);

                if (!isBlank)
                    return false;
            }

            return true;
        }

        private string NormalizeWorkspaceUrl(string url)
        {
            url = (url ?? "").Trim();

            if (string.IsNullOrWhiteSpace(url))
                return "";

            if (!url.Contains("://") && url.Contains("."))
                url = "https://" + url;

            return url;
        }

        private void LoadQuickUrlBlockIntoWorkspace(int workspaceIndex, bool force)
        {
            if (workspaceIndex < 0 || workspaceIndex >= _workspaces.Count)
                return;

            var ws = _workspaces[workspaceIndex];

            // Do not overwrite a tab once the user has browsed in it,
            // unless we explicitly force it.
            if (!force && !IsWorkspaceBlankOrDefault(ws))
                return;

            int startSlot = workspaceIndex * 4;

            for (int pane = 0; pane < 4; pane++)
            {
                int quickUrlSlot = startSlot + pane;

                string url = "";

                if (quickUrlSlot >= 0 && quickUrlSlot < _presetUrls.Length)
                    url = NormalizeWorkspaceUrl(_presetUrls[quickUrlSlot]);

                if (string.IsNullOrWhiteSpace(url))
                {
                    url = pane == 0 ? "lexwhite://newtab" : "about:blank";
                    ws.StudioSlotIndex[pane] = -1;
                }
                else
                {
                    ws.StudioSlotIndex[pane] = quickUrlSlot;
                }

                ws.PageUrls[pane] = url;
                ws.PageLocked[pane] = false;
            }

            ws.ActivePageIndex = 0;
            ws.LayoutPageCount = 1;

            for (int i = 0; i < ws.PaneState.Length; i++)
                ws.PaneState[i] = i == 0 ? PaneLifeState.Normal : PaneLifeState.Minimized;
        }

        private void RefreshHomeOverlay1()
        {
            if (HomeOverlay1 == null || Web == null) return;

            // During tab switching, keep the real WebView visible.
            // Otherwise the startup screen can flash briefly before the new tab's Quick URL loads.
            if (_isSwitchingWorkspaceTab)
            {
                HomeOverlay1.Visibility = Visibility.Collapsed;
                Web.Visibility = Visibility.Visible;
                return;
            }

            if (_startupOverlayLaunchInProgress)
            {
                HomeOverlay1.Visibility = Visibility.Collapsed;
                Web.Visibility = Visibility.Visible;
                return;
            }


            if (!_startupScreenEnabled)
            {
                HomeOverlay1.Visibility = Visibility.Collapsed;

                if (Web != null)
                    Web.Visibility = Visibility.Visible;

                return;
            }

            string trackedUrl = _pageUrls[0] ?? "";
            string liveUrl = "";

            try
            {
                liveUrl = Web?.CoreWebView2?.Source ?? "";
            }
            catch
            {
                liveUrl = "";
            }

            string url = trackedUrl;

            if (string.IsNullOrWhiteSpace(url))
                url = liveUrl;

            bool show =
                string.IsNullOrWhiteSpace(url) ||
                url.Equals("about:blank", StringComparison.OrdinalIgnoreCase) ||
                url.Equals("lexwhite://newtab", StringComparison.OrdinalIgnoreCase);

            HomeOverlay1.Visibility = show ? Visibility.Visible : Visibility.Collapsed;

            var web = Web;
            if (web != null)
                web.Visibility = show ? Visibility.Collapsed : Visibility.Visible;
        }

