        // ============================================================
        // LexDesk Pro - PC Health / Grandma Check
        // Read-only checks only. No administrator rights are requested here.
        // ============================================================

        private const uint WscSecurityProviderAutoUpdateSettings = 0x2;
        private const uint WscSecurityProviderAntivirus = 0x4;

        private enum LexDeskWscHealth
        {
            Good = 0,
            NotMonitored = 1,
            Poor = 2,
            Snooze = 3
        }

        [DllImport("wscapi.dll")]
        private static extern int WscGetSecurityProviderHealth(
            uint providers,
            out LexDeskWscHealth health);

        private Brush GetPcHealthBrush(bool needsAttention)
        {
            string key = needsAttention ? "StatusOrangeBrush" : "StatusGreenBrush";
            return TryFindResource(key) as Brush
                   ?? (needsAttention ? Brushes.DarkOrange : Brushes.ForestGreen);
        }

        private string GetRegisteredAntivirusNames()
        {
            try
            {
                var names = new List<string>();

                using var searcher = new ManagementObjectSearcher(
                    @"root\SecurityCenter2",
                    "SELECT displayName FROM AntiVirusProduct");

                foreach (ManagementBaseObject item in searcher.Get())
                {
                    string name = item["displayName"]?.ToString()?.Trim() ?? "";

                    if (!string.IsNullOrWhiteSpace(name) &&
                        !names.Contains(name, StringComparer.OrdinalIgnoreCase))
                    {
                        names.Add(name);
                    }
                }

                return string.Join(", ", names);
            }
            catch
            {
                return "";
            }
        }

        private bool IsWindowsRestartPending()
        {
            try
            {
                // These two markers are the reliable Windows servicing/update
                // signals LexDesk uses for the Grandma-facing "restart required"
                // status and for deciding whether maintenance should wait.
                using (RegistryKey? cbs = Registry.LocalMachine.OpenSubKey(
                    @"SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending"))
                {
                    if (cbs != null)
                        return true;
                }

                using (RegistryKey? wu = Registry.LocalMachine.OpenSubKey(
                    @"SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired"))
                {
                    if (wu != null)
                        return true;
                }

                // Do NOT use PendingFileRenameOperations as the headline restart flag.
                // Drivers and normal applications can leave entries there even after
                // a successful restart, which caused LexDesk to keep warning Grandma
                // that Windows needed another restart when it did not.
            }
            catch
            {
                // A read failure must not turn into a false restart warning.
            }

            return false;
        }

        private void LexDeskCheckMyPc_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;

            if (LexDeskCheckMyPcButton != null)
            {
                LexDeskCheckMyPcButton.IsEnabled = false;
                LexDeskCheckMyPcButton.Content = "Checking...";
            }

            int attentionCount = 0;

            try
            {
                // Virus protection
                bool antivirusNeedsAttention = true;
                string antivirusNames = GetRegisteredAntivirusNames();
                int antivirusResult = WscGetSecurityProviderHealth(
                    WscSecurityProviderAntivirus,
                    out LexDeskWscHealth antivirusHealth);

                string antivirusText;

                if (antivirusResult >= 0 && antivirusHealth == LexDeskWscHealth.Good)
                {
                    antivirusNeedsAttention = false;
                    antivirusText = string.IsNullOrWhiteSpace(antivirusNames)
                        ? "Protection is on."
                        : $"Protection is on: {antivirusNames}.";
                }
                else if (antivirusHealth == LexDeskWscHealth.Snooze)
                {
                    antivirusText = "Virus protection is paused and needs attention.";
                }
                else if (antivirusHealth == LexDeskWscHealth.NotMonitored)
                {
                    antivirusText = "Windows cannot confirm your virus protection.";
                }
                else
                {
                    antivirusText = string.IsNullOrWhiteSpace(antivirusNames)
                        ? "Virus protection needs attention."
                        : $"Virus protection needs attention: {antivirusNames}.";
                }

                if (LexDeskPcHealthAntivirusText != null)
                {
                    LexDeskPcHealthAntivirusText.Text = antivirusText;
                    LexDeskPcHealthAntivirusText.Foreground = GetPcHealthBrush(antivirusNeedsAttention);
                }

                if (antivirusNeedsAttention)
                    attentionCount++;

                // Windows Update settings
                bool updateNeedsAttention = true;
                int updateResult = WscGetSecurityProviderHealth(
                    WscSecurityProviderAutoUpdateSettings,
                    out LexDeskWscHealth updateHealth);

                string updateText;

                if (updateResult >= 0 && updateHealth == LexDeskWscHealth.Good)
                {
                    updateNeedsAttention = false;
                    updateText = "Windows Update settings look OK.";
                }
                else if (updateHealth == LexDeskWscHealth.Snooze)
                {
                    updateText = "Windows Update is paused and needs attention.";
                }
                else if (updateHealth == LexDeskWscHealth.NotMonitored)
                {
                    updateText = "Windows is not reporting update health.";
                }
                else
                {
                    updateText = "Windows Update settings need attention.";
                }

                if (LexDeskPcHealthUpdatesText != null)
                {
                    LexDeskPcHealthUpdatesText.Text = updateText;
                    LexDeskPcHealthUpdatesText.Foreground = GetPcHealthBrush(updateNeedsAttention);
                }

                if (updateNeedsAttention)
                    attentionCount++;

                // Main Windows drive free space
                bool storageNeedsAttention = false;
                string storageText = "Storage could not be checked.";

                try
                {
                    string root = Path.GetPathRoot(Environment.SystemDirectory) ?? @"C:\";
                    var drive = new DriveInfo(root);

                    if (drive.IsReady && drive.TotalSize > 0)
                    {
                        double freeGb = drive.AvailableFreeSpace / 1024d / 1024d / 1024d;
                        double totalGb = drive.TotalSize / 1024d / 1024d / 1024d;
                        double freePercent = (drive.AvailableFreeSpace * 100d) / drive.TotalSize;

                        storageNeedsAttention = freeGb < 15 || freePercent < 10;
                        storageText = $"{freeGb:0} GB free of {totalGb:0} GB.";

                        if (storageNeedsAttention)
                            storageText += " Your main drive is getting full.";
                    }
                    else
                    {
                        storageNeedsAttention = true;
                    }
                }
                catch
                {
                    storageNeedsAttention = true;
                }

                if (LexDeskPcHealthStorageText != null)
                {
                    LexDeskPcHealthStorageText.Text = storageText;
                    LexDeskPcHealthStorageText.Foreground = GetPcHealthBrush(storageNeedsAttention);
                }

                if (storageNeedsAttention)
                    attentionCount++;

                // Pending restart
                bool restartPending = IsWindowsRestartPending();

                if (LexDeskPcHealthRestartText != null)
                {
                    LexDeskPcHealthRestartText.Text = restartPending
                        ? "Windows needs a restart to finish maintenance."
                        : "No Windows restart is waiting.";
                    LexDeskPcHealthRestartText.Foreground = GetPcHealthBrush(restartPending);
                }

                if (restartPending)
                    attentionCount++;

                if (LexDeskPcHealthOverallText != null)
                {
                    LexDeskPcHealthOverallText.Text = attentionCount == 0
                        ? "Your PC looks good."
                        : attentionCount == 1
                            ? "LexDesk found 1 thing that needs attention."
                            : $"LexDesk found {attentionCount} things that need attention.";

                    LexDeskPcHealthOverallText.Foreground = GetPcHealthBrush(attentionCount > 0);
                }

                RefreshLexDeskStage3ProtectionUi();

                UpdateSecurityStatus(
                    attentionCount == 0 ? "PC health check passed" : "PC health check found items to review",
                    attentionCount > 0);
            }
            catch (Exception ex)
            {
                if (LexDeskPcHealthOverallText != null)
                {
                    LexDeskPcHealthOverallText.Text =
                        "LexDesk could not finish the PC health check.";
                    LexDeskPcHealthOverallText.Foreground = GetPcHealthBrush(true);
                }

                ShowLexDeskMessageBox(
                    $"LexDesk could not finish the PC health check.\n\n{SanitizeExceptionMessage(ex)}",
                    "PC Health",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                if (LexDeskCheckMyPcButton != null)
                {
                    LexDeskCheckMyPcButton.IsEnabled = true;
                    LexDeskCheckMyPcButton.Content = "Check My PC";
                }
            }
        }



        // ============================================================
        // LexDesk Pro - Windows Repair / Cleanup - Stage 2
        // Uses only fixed Windows maintenance commands. The main LexDesk
        // process stays unelevated; Windows asks for administrator permission
        // only when one of these maintenance operations is started.
        // ============================================================

        private enum LexDeskWindowsRepairState
        {
            NotChecked,
            Healthy,
            Repairable,
            NonRepairable,
            Unknown
        }

        private enum LexDeskSfcResult
        {
            Unknown,
            Healthy,
            Repaired,
            Unresolved,
            CouldNotRun
        }

        private sealed class LexDeskMaintenanceCommand
        {
            public string Key { get; init; } = "";
            public string StatusText { get; init; } = "";
            public string FileName { get; init; } = "";
            public string Arguments { get; init; } = "";
            public bool StopOnFailure { get; init; } = true;
        }

        private sealed class LexDeskMaintenanceBatchResult
        {
            public bool Started { get; init; }
            public bool Cancelled { get; init; }
            public string Output { get; init; } = "";
            public string LogPath { get; init; } = "";
        }

        private LexDeskWindowsRepairState _lexDeskWindowsRepairState =
            LexDeskWindowsRepairState.NotChecked;

        private bool _lexDeskMaintenanceBusy = false;

        private void SetLexDeskMaintenanceStatus(string text, bool? needsAttention = null)
        {
            if (LexDeskMaintenanceStatusText == null)
                return;

            LexDeskMaintenanceStatusText.Text = text ?? "";

            if (needsAttention.HasValue)
            {
                LexDeskMaintenanceStatusText.Foreground =
                    GetPcHealthBrush(needsAttention.Value);
            }
            else
            {
                LexDeskMaintenanceStatusText.Foreground =
                    TryFindResource("TextSecondary") as Brush ?? Brushes.Gray;
            }
        }

        private void SetLexDeskMaintenanceBusy(bool busy)
        {
            _lexDeskMaintenanceBusy = busy;

            if (LexDeskCheckWindowsButton != null)
                LexDeskCheckWindowsButton.IsEnabled = !busy;

            if (LexDeskRepairWindowsButton != null)
            {
                bool repairAvailable =
                    _lexDeskWindowsRepairState == LexDeskWindowsRepairState.Healthy ||
                    _lexDeskWindowsRepairState == LexDeskWindowsRepairState.Repairable;

                LexDeskRepairWindowsButton.IsEnabled = !busy && repairAvailable;
            }

            if (LexDeskCleanupWindowsButton != null)
                LexDeskCleanupWindowsButton.IsEnabled = !busy;

            if (LexDeskMaintenanceProgressBar != null)
            {
                LexDeskMaintenanceProgressBar.Visibility =
                    busy ? Visibility.Visible : Visibility.Collapsed;
            }
        }

        private string GetLexDeskMaintenanceFolder()
        {
            string folder = AppDataPath("PCHealth");
            Directory.CreateDirectory(folder);
            return folder;
        }

        private static string EscapeLexDeskBatchPath(string value)
        {
            // Percent signs have special meaning in .cmd files. Windows paths
            // cannot contain a quote, so percent is the only character we need
            // to neutralise for the fixed quoted file paths written below.
            return (value ?? "").Replace("%", "%%");
        }

        private async Task<LexDeskMaintenanceBatchResult> RunElevatedMaintenanceBatchAsync(
            string operationKey,
            IReadOnlyList<LexDeskMaintenanceCommand> commands)
        {
            string folder = GetLexDeskMaintenanceFolder();
            string token = Guid.NewGuid().ToString("N");

            string batchPath = Path.Combine(folder, $"{operationKey}_{token}.cmd");
            string statusPath = Path.Combine(folder, $"{operationKey}_{token}.status.txt");
            string logPath = Path.Combine(folder, $"{operationKey}_latest.log");

            string batchPathSafe = EscapeLexDeskBatchPath(batchPath);
            string statusPathSafe = EscapeLexDeskBatchPath(statusPath);
            string logPathSafe = EscapeLexDeskBatchPath(logPath);

            try
            {
                var script = new StringBuilder();
                script.AppendLine("@echo off");
                script.AppendLine("setlocal");
                script.AppendLine($"type nul > \"{logPathSafe}\"");

                foreach (LexDeskMaintenanceCommand command in commands)
                {
                    string fileName = EscapeLexDeskBatchPath(command.FileName);
                    string statusText = (command.StatusText ?? "")
                        .Replace("%", "%%")
                        .Replace("&", "and")
                        .Replace("|", " ")
                        .Replace(">", " ")
                        .Replace("<", " ");

                    script.AppendLine($"> \"{statusPathSafe}\" echo {statusText}");
                    script.AppendLine($">> \"{logPathSafe}\" echo ===LEXDESK_{command.Key}_BEGIN===");
                    script.AppendLine($"\"{fileName}\" {command.Arguments} >> \"{logPathSafe}\" 2>&1");
                    script.AppendLine("set LEXDESK_EXIT=%ERRORLEVEL%");
                    script.AppendLine($">> \"{logPathSafe}\" echo ===LEXDESK_{command.Key}_EXIT:%LEXDESK_EXIT%===");
                    script.AppendLine($">> \"{logPathSafe}\" echo ===LEXDESK_{command.Key}_END===");

                    if (command.StopOnFailure)
                    {
                        string continueLabel = $"lexdesk_continue_{command.Key}";
                        script.AppendLine($"if \"%LEXDESK_EXIT%\"==\"0\" goto :{continueLabel}");
                        script.AppendLine($"if \"%LEXDESK_EXIT%\"==\"3010\" goto :{continueLabel}");
                        script.AppendLine("goto :lexdesk_end");
                        script.AppendLine($":{continueLabel}");
                    }
                }

                script.AppendLine(":lexdesk_end");
                script.AppendLine($"> \"{statusPathSafe}\" echo Finishing Windows maintenance check...");
                script.AppendLine("exit /b 0");

                File.WriteAllText(
                    batchPath,
                    script.ToString(),
                    new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));

                var psi = new ProcessStartInfo
                {
                    FileName = "cmd.exe",
                    Arguments = $"/d /s /c \"\"{batchPathSafe}\"\"",
                    UseShellExecute = true,
                    WorkingDirectory = Environment.SystemDirectory,
                    WindowStyle = ProcessWindowStyle.Hidden
                };

                if (!IsRunningAsAdmin())
                    psi.Verb = "runas";

                Process? process;

                try
                {
                    process = Process.Start(psi);
                }
                catch (System.ComponentModel.Win32Exception ex)
                    when (ex.NativeErrorCode == 1223)
                {
                    return new LexDeskMaintenanceBatchResult
                    {
                        Started = false,
                        Cancelled = true,
                        LogPath = logPath
                    };
                }

                if (process == null)
                {
                    return new LexDeskMaintenanceBatchResult
                    {
                        Started = false,
                        Cancelled = false,
                        LogPath = logPath
                    };
                }

                string lastStatus = "";

                while (!process.HasExited)
                {
                    await Task.Delay(400);

                    try
                    {
                        if (File.Exists(statusPath))
                        {
                            string currentStatus = (await File.ReadAllTextAsync(statusPath)).Trim();

                            if (!string.IsNullOrWhiteSpace(currentStatus) &&
                                !string.Equals(currentStatus, lastStatus, StringComparison.Ordinal))
                            {
                                lastStatus = currentStatus;
                                SetLexDeskMaintenanceStatus(currentStatus);
                            }
                        }
                    }
                    catch
                    {
                        // A transient log/status read must never interrupt Windows maintenance.
                    }
                }

                await process.WaitForExitAsync();

                string output = "";

                try
                {
                    if (File.Exists(logPath))
                        output = await File.ReadAllTextAsync(logPath);
                }
                catch
                {
                    // The user-facing result can still fall back to the process markers/status.
                }

                return new LexDeskMaintenanceBatchResult
                {
                    Started = true,
                    Cancelled = false,
                    Output = output,
                    LogPath = logPath
                };
            }
            finally
            {
                try
                {
                    if (File.Exists(batchPath))
                        File.Delete(batchPath);
                }
                catch { }

                try
                {
                    if (File.Exists(statusPath))
                        File.Delete(statusPath);
                }
                catch { }
            }
        }

        private static bool TryGetLexDeskMaintenanceExitCode(
            string output,
            string key,
            out int exitCode)
        {
            exitCode = -1;

            if (string.IsNullOrWhiteSpace(output) || string.IsNullOrWhiteSpace(key))
                return false;

            string marker = $"===LEXDESK_{key}_EXIT:";
            int start = output.IndexOf(marker, StringComparison.OrdinalIgnoreCase);

            if (start < 0)
                return false;

            start += marker.Length;
            int end = output.IndexOf("===", start, StringComparison.Ordinal);

            if (end < 0)
                return false;

            string value = output.Substring(start, end - start).Trim();
            return int.TryParse(value, out exitCode);
        }

        private static string GetLexDeskMaintenanceSection(string output, string key)
        {
            if (string.IsNullOrWhiteSpace(output) || string.IsNullOrWhiteSpace(key))
                return "";

            string beginMarker = $"===LEXDESK_{key}_BEGIN===";
            string exitMarker = $"===LEXDESK_{key}_EXIT:";

            int start = output.IndexOf(beginMarker, StringComparison.OrdinalIgnoreCase);

            if (start < 0)
                return "";

            start += beginMarker.Length;
            int end = output.IndexOf(exitMarker, start, StringComparison.OrdinalIgnoreCase);

            if (end < 0)
                return "";

            return output.Substring(start, end - start).Trim();
        }

        private static bool IsLexDeskMaintenanceSuccessExit(int exitCode)
        {
            // 3010 means the Windows servicing operation succeeded but a restart
            // is required to finish applying the change. Treat it as success and
            // let LexDesk surface the restart separately.
            return exitCode == 0 || exitCode == 3010;
        }

        private static LexDeskWindowsRepairState ParseLexDeskDismHealth(
            string output,
            int exitCode)
        {
            if (!IsLexDeskMaintenanceSuccessExit(exitCode) || string.IsNullOrWhiteSpace(output))
                return LexDeskWindowsRepairState.Unknown;

            string text = output.ToLowerInvariant();

            if (text.Contains("component store cannot be repaired") ||
                text.Contains("component store is non-repairable") ||
                text.Contains("component store is not repairable"))
            {
                return LexDeskWindowsRepairState.NonRepairable;
            }

            if (text.Contains("no component store corruption detected") ||
                text.Contains("component store is healthy"))
            {
                return LexDeskWindowsRepairState.Healthy;
            }

            if (text.Contains("component store is repairable") ||
                (text.Contains("corruption detected") &&
                 !text.Contains("no component store corruption detected")))
            {
                return LexDeskWindowsRepairState.Repairable;
            }

            return LexDeskWindowsRepairState.Unknown;
        }

        private static LexDeskSfcResult ParseLexDeskSfcResult(string output, int exitCode)
        {
            if (string.IsNullOrWhiteSpace(output))
                return LexDeskSfcResult.Unknown;

            string text = output.ToLowerInvariant();

            if (text.Contains("did not find any integrity violations"))
                return LexDeskSfcResult.Healthy;

            if (text.Contains("found corrupt files and successfully repaired them"))
                return LexDeskSfcResult.Repaired;

            if (text.Contains("found corrupt files but was unable to fix some of them"))
                return LexDeskSfcResult.Unresolved;

            if (text.Contains("could not perform the requested operation"))
                return LexDeskSfcResult.CouldNotRun;

            return IsLexDeskMaintenanceSuccessExit(exitCode)
                ? LexDeskSfcResult.Unknown
                : LexDeskSfcResult.CouldNotRun;
        }

        private static bool? ParseLexDeskCleanupRecommendation(string output, int exitCode)
        {
            if (!IsLexDeskMaintenanceSuccessExit(exitCode) || string.IsNullOrWhiteSpace(output))
                return null;

            string text = output.ToLowerInvariant();

            if (text.Contains("component store cleanup recommended : yes") ||
                text.Contains("component store cleanup recommended: yes"))
            {
                return true;
            }

            if (text.Contains("component store cleanup recommended : no") ||
                text.Contains("component store cleanup recommended: no"))
            {
                return false;
            }

            return null;
        }

        private bool ShouldWaitForRestartBeforeMaintenance()
        {
            if (!IsWindowsRestartPending())
                return false;

            SetLexDeskMaintenanceStatus(
                "Windows already has a restart waiting. Restart the PC first, then run this check again.",
                true);

            ShowLexDeskMessageBox(
                "Windows already has a restart waiting.\n\n" +
                "Restart the computer first so LexDesk checks a settled Windows installation.\n\n" +
                "Nothing has been changed.",
                "Restart Windows First",
                MessageBoxButton.OK,
                MessageBoxImage.Information);

            return true;
        }

        private async void LexDeskCheckWindows_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;

            if (_lexDeskMaintenanceBusy || ShouldWaitForRestartBeforeMaintenance())
                return;

            var decision = ShowLexDeskMessageBox(
                "LexDesk will ask Windows to run two health checks.\n\n" +
                "1. A quick check for known repair-file damage.\n" +
                "2. A deeper scan for Windows component-store damage.\n\n" +
                "These checks do not delete your files or make repairs. They can take several minutes.\n\n" +
                "Windows will ask for Administrator permission. Continue?",
                "Check Windows",
                MessageBoxButton.YesNo,
                MessageBoxImage.Information);

            if (decision != MessageBoxResult.Yes)
                return;

            SetLexDeskMaintenanceBusy(true);
            SetLexDeskMaintenanceStatus("Starting Windows health checks...");

            try
            {
                string dism = Path.Combine(Environment.SystemDirectory, "Dism.exe");

                var commands = new List<LexDeskMaintenanceCommand>
                {
                    new()
                    {
                        Key = "CHECKHEALTH",
                        StatusText = "Step 1 of 2 - Quick Windows health check...",
                        FileName = dism,
                        Arguments = "/Online /Cleanup-Image /CheckHealth /English /NoRestart",
                        StopOnFailure = true
                    },
                    new()
                    {
                        Key = "SCANHEALTH",
                        StatusText = "Step 2 of 2 - Deep Windows health scan. This can take several minutes...",
                        FileName = dism,
                        Arguments = "/Online /Cleanup-Image /ScanHealth /English /NoRestart",
                        StopOnFailure = true
                    }
                };

                LexDeskMaintenanceBatchResult result =
                    await RunElevatedMaintenanceBatchAsync("windows_check", commands);

                if (result.Cancelled)
                {
                    SetLexDeskMaintenanceStatus(
                        "Administrator permission was cancelled. Nothing was changed.");
                    return;
                }

                if (!result.Started)
                {
                    _lexDeskWindowsRepairState = LexDeskWindowsRepairState.Unknown;
                    SetLexDeskMaintenanceStatus(
                        "LexDesk could not start the Windows health check.",
                        true);
                    return;
                }

                bool gotCheckExit = TryGetLexDeskMaintenanceExitCode(
                    result.Output,
                    "CHECKHEALTH",
                    out int checkExit);

                bool gotScanExit = TryGetLexDeskMaintenanceExitCode(
                    result.Output,
                    "SCANHEALTH",
                    out int scanExit);

                if (!gotCheckExit || !gotScanExit)
                {
                    _lexDeskWindowsRepairState = LexDeskWindowsRepairState.Unknown;
                    SetLexDeskMaintenanceStatus(
                        "Windows did not return a complete health-check result. Restart the PC and try again.",
                        true);
                    return;
                }

                string scanSection = GetLexDeskMaintenanceSection(result.Output, "SCANHEALTH");
                string checkSection = GetLexDeskMaintenanceSection(result.Output, "CHECKHEALTH");

                LexDeskWindowsRepairState state =
                    ParseLexDeskDismHealth(scanSection, scanExit);

                if (state == LexDeskWindowsRepairState.Unknown)
                    state = ParseLexDeskDismHealth(checkSection, checkExit);

                _lexDeskWindowsRepairState = state;

                switch (state)
                {
                    case LexDeskWindowsRepairState.Healthy:
                        SetLexDeskMaintenanceStatus(
                            "Windows repair files look healthy. Repair Windows is now available for a deeper system-file check.",
                            false);
                        UpdateSecurityStatus("Windows health check passed", false);
                        break;

                    case LexDeskWindowsRepairState.Repairable:
                        SetLexDeskMaintenanceStatus(
                            "Windows found repairable damage. Click Repair Windows and LexDesk will repair it in the correct order.",
                            true);
                        UpdateSecurityStatus("Windows repairable damage found", true);
                        break;

                    case LexDeskWindowsRepairState.NonRepairable:
                        SetLexDeskMaintenanceStatus(
                            "Windows found damage that its normal repair tool cannot fix automatically. Back up important files before using Windows Recovery options.",
                            true);
                        UpdateSecurityStatus("Windows repair needs extra help", true);
                        break;

                    default:
                        SetLexDeskMaintenanceStatus(
                            "LexDesk could not read a clear Windows health result. Nothing was changed. Restart the PC and try again.",
                            true);
                        UpdateSecurityStatus("Windows health result unclear", true);
                        break;
                }
            }
            catch (Exception ex)
            {
                _lexDeskWindowsRepairState = LexDeskWindowsRepairState.Unknown;

                SetLexDeskMaintenanceStatus(
                    "LexDesk could not finish the Windows health check.",
                    true);

                ShowLexDeskMessageBox(
                    $"LexDesk could not finish the Windows health check.\n\n{SanitizeExceptionMessage(ex)}",
                    "Check Windows",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                SetLexDeskMaintenanceBusy(false);
            }
        }

        private async void LexDeskRepairWindows_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;

            if (_lexDeskMaintenanceBusy || ShouldWaitForRestartBeforeMaintenance())
                return;

            if (_lexDeskWindowsRepairState == LexDeskWindowsRepairState.NotChecked)
            {
                ShowLexDeskMessageBox(
                    "Run Check Windows first.\n\nLexDesk will then know whether Windows needs a repair or only a system-file check.",
                    "Check Windows First",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            if (_lexDeskWindowsRepairState == LexDeskWindowsRepairState.NonRepairable ||
                _lexDeskWindowsRepairState == LexDeskWindowsRepairState.Unknown)
            {
                ShowLexDeskMessageBox(
                    "LexDesk does not have a safe automatic repair to run for the current result.\n\nRestart Windows and run Check Windows again. If the same warning returns, back up important files before using Windows Recovery options.",
                    "Windows Repair",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            bool willRestore =
                _lexDeskWindowsRepairState == LexDeskWindowsRepairState.Repairable;

            string explanation = willRestore
                ? "LexDesk will run Windows repair first, then System File Checker.\n\nWindows may use Windows Update to download healthy replacement files."
                : "The Windows repair source looks healthy. LexDesk will now run System File Checker to check the protected Windows files your PC actually uses.";

            var decision = ShowLexDeskMessageBox(
                explanation +
                "\n\nYour documents, photos and personal files are not deleted. This can take several minutes.\n\nWindows will ask for Administrator permission. Continue?",
                "Repair Windows",
                MessageBoxButton.YesNo,
                MessageBoxImage.Information);

            if (decision != MessageBoxResult.Yes)
                return;

            SetLexDeskMaintenanceBusy(true);
            SetLexDeskMaintenanceStatus("Starting Windows repair...");

            try
            {
                string dism = Path.Combine(Environment.SystemDirectory, "Dism.exe");
                string sfc = Path.Combine(Environment.SystemDirectory, "sfc.exe");
                var commands = new List<LexDeskMaintenanceCommand>();

                if (willRestore)
                {
                    commands.Add(new LexDeskMaintenanceCommand
                    {
                        Key = "RESTOREHEALTH",
                        StatusText = "Step 3 - Repairing the Windows repair source. This can take several minutes...",
                        FileName = dism,
                        Arguments = "/Online /Cleanup-Image /RestoreHealth /English /NoRestart",
                        StopOnFailure = true
                    });
                }

                commands.Add(new LexDeskMaintenanceCommand
                {
                    Key = "SFC",
                    StatusText = willRestore
                        ? "Step 4 - Checking and repairing Windows system files..."
                        : "Checking and repairing Windows system files...",
                    FileName = sfc,
                    Arguments = "/scannow",
                    StopOnFailure = true
                });

                LexDeskMaintenanceBatchResult result =
                    await RunElevatedMaintenanceBatchAsync("windows_repair", commands);

                if (result.Cancelled)
                {
                    SetLexDeskMaintenanceStatus(
                        "Administrator permission was cancelled. Nothing was changed.");
                    return;
                }

                if (!result.Started)
                {
                    SetLexDeskMaintenanceStatus(
                        "LexDesk could not start Windows repair.",
                        true);
                    return;
                }

                if (willRestore)
                {
                    bool gotRestoreExit = TryGetLexDeskMaintenanceExitCode(
                        result.Output,
                        "RESTOREHEALTH",
                        out int restoreExit);

                    string restoreSection =
                        GetLexDeskMaintenanceSection(result.Output, "RESTOREHEALTH");

                    bool restoreSucceeded =
                        gotRestoreExit &&
                        IsLexDeskMaintenanceSuccessExit(restoreExit) &&
                        (restoreSection.Contains("operation completed successfully", StringComparison.OrdinalIgnoreCase) ||
                         restoreSection.Contains("restore operation completed successfully", StringComparison.OrdinalIgnoreCase));

                    if (!restoreSucceeded)
                    {
                        SetLexDeskMaintenanceStatus(
                            "Windows repair did not complete. Restart the PC, make sure the internet is working, then run Check Windows again.",
                            true);
                        UpdateSecurityStatus("Windows repair did not complete", true);
                        return;
                    }

                    _lexDeskWindowsRepairState = LexDeskWindowsRepairState.Healthy;
                }

                bool gotSfcExit = TryGetLexDeskMaintenanceExitCode(
                    result.Output,
                    "SFC",
                    out int sfcExit);

                if (!gotSfcExit)
                {
                    SetLexDeskMaintenanceStatus(
                        "System File Checker did not return a complete result. Restart the PC and try again.",
                        true);
                    return;
                }

                string sfcSection = GetLexDeskMaintenanceSection(result.Output, "SFC");
                LexDeskSfcResult sfcResult = ParseLexDeskSfcResult(sfcSection, sfcExit);

                switch (sfcResult)
                {
                    case LexDeskSfcResult.Healthy:
                        SetLexDeskMaintenanceStatus(
                            "Windows system files are healthy. No further repair is needed.",
                            false);
                        UpdateSecurityStatus("Windows system files healthy", false);
                        break;

                    case LexDeskSfcResult.Repaired:
                        SetLexDeskMaintenanceStatus(
                            "Windows repaired damaged system files. Restart the PC before normal use, then run Check Windows again if you want to confirm everything is healthy.",
                            false);

                        if (LexDeskPcHealthRestartText != null)
                        {
                            LexDeskPcHealthRestartText.Text =
                                "Restart recommended after Windows repair.";
                            LexDeskPcHealthRestartText.Foreground = GetPcHealthBrush(true);
                        }

                        UpdateSecurityStatus("Windows system files repaired", false);
                        break;

                    case LexDeskSfcResult.Unresolved:
                        SetLexDeskMaintenanceStatus(
                            "Windows repaired some files but could not fix everything. Restart the PC and run Check Windows again. If the warning remains, Windows Recovery may be needed.",
                            true);
                        UpdateSecurityStatus("Some Windows files still need repair", true);
                        break;

                    case LexDeskSfcResult.CouldNotRun:
                        SetLexDeskMaintenanceStatus(
                            "System File Checker could not complete. Restart the PC and try again.",
                            true);
                        UpdateSecurityStatus("System File Checker could not complete", true);
                        break;

                    default:
                        SetLexDeskMaintenanceStatus(
                            "Windows finished the repair, but LexDesk could not read the final System File Checker message. Restart the PC before running another repair.",
                            true);
                        break;
                }
            }
            catch (Exception ex)
            {
                SetLexDeskMaintenanceStatus(
                    "LexDesk could not finish Windows repair.",
                    true);

                ShowLexDeskMessageBox(
                    $"LexDesk could not finish Windows repair.\n\n{SanitizeExceptionMessage(ex)}",
                    "Repair Windows",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                SetLexDeskMaintenanceBusy(false);
            }
        }

        private async void LexDeskCleanupWindows_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;

            if (_lexDeskMaintenanceBusy || ShouldWaitForRestartBeforeMaintenance())
                return;

            var checkDecision = ShowLexDeskMessageBox(
                "LexDesk will first ask Windows whether old component files need cleaning.\n\nNothing is deleted during this first check.\n\nWindows will ask for Administrator permission. Continue?",
                "Check Windows Cleanup",
                MessageBoxButton.YesNo,
                MessageBoxImage.Information);

            if (checkDecision != MessageBoxResult.Yes)
                return;

            SetLexDeskMaintenanceBusy(true);
            SetLexDeskMaintenanceStatus("Checking whether Windows cleanup is recommended...");

            try
            {
                string dism = Path.Combine(Environment.SystemDirectory, "Dism.exe");

                var analyzeCommands = new List<LexDeskMaintenanceCommand>
                {
                    new()
                    {
                        Key = "ANALYZE",
                        StatusText = "Step 5 - Checking old Windows component files...",
                        FileName = dism,
                        Arguments = "/Online /Cleanup-Image /AnalyzeComponentStore /English /NoRestart",
                        StopOnFailure = true
                    }
                };

                LexDeskMaintenanceBatchResult analyzeResult =
                    await RunElevatedMaintenanceBatchAsync("component_analysis", analyzeCommands);

                if (analyzeResult.Cancelled)
                {
                    SetLexDeskMaintenanceStatus(
                        "Administrator permission was cancelled. Nothing was changed.");
                    return;
                }

                if (!analyzeResult.Started)
                {
                    SetLexDeskMaintenanceStatus(
                        "LexDesk could not start the Windows cleanup check.",
                        true);
                    return;
                }

                bool gotAnalyzeExit = TryGetLexDeskMaintenanceExitCode(
                    analyzeResult.Output,
                    "ANALYZE",
                    out int analyzeExit);

                string analyzeSection =
                    GetLexDeskMaintenanceSection(analyzeResult.Output, "ANALYZE");

                bool? cleanupRecommended = gotAnalyzeExit
                    ? ParseLexDeskCleanupRecommendation(analyzeSection, analyzeExit)
                    : null;

                if (cleanupRecommended == false)
                {
                    SetLexDeskMaintenanceStatus(
                        "Windows says component cleanup is not needed. Leave it alone and let Windows manage it.",
                        false);
                    UpdateSecurityStatus("Windows cleanup not needed", false);
                    return;
                }

                if (cleanupRecommended != true)
                {
                    SetLexDeskMaintenanceStatus(
                        "LexDesk could not read a clear cleanup recommendation. Nothing was deleted.",
                        true);
                    return;
                }

                SetLexDeskMaintenanceBusy(false);
                SetLexDeskMaintenanceStatus(
                    "Windows recommends component cleanup. LexDesk is waiting for your approval.",
                    true);

                var cleanupDecision = ShowLexDeskMessageBox(
                    "Windows recommends cleaning old component files.\n\n" +
                    "LexDesk can now run Windows' StartComponentCleanup tool. It removes older superseded Windows component versions. Your documents and photos are not touched.\n\n" +
                    "Do not run this while you are trying to roll back a very recent Windows update.\n\n" +
                    "Continue with cleanup?",
                    "Clean Old Windows Files",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Information);

                if (cleanupDecision != MessageBoxResult.Yes)
                {
                    SetLexDeskMaintenanceStatus(
                        "Cleanup was cancelled. Nothing was deleted.");
                    return;
                }

                SetLexDeskMaintenanceBusy(true);
                SetLexDeskMaintenanceStatus("Starting safe Windows component cleanup...");

                var cleanupCommands = new List<LexDeskMaintenanceCommand>
                {
                    new()
                    {
                        Key = "CLEANUP",
                        StatusText = "Step 6 - Cleaning old Windows component files...",
                        FileName = dism,
                        Arguments = "/Online /Cleanup-Image /StartComponentCleanup /English /NoRestart",
                        StopOnFailure = true
                    }
                };

                LexDeskMaintenanceBatchResult cleanupResult =
                    await RunElevatedMaintenanceBatchAsync("component_cleanup", cleanupCommands);

                if (cleanupResult.Cancelled)
                {
                    SetLexDeskMaintenanceStatus(
                        "Administrator permission was cancelled. Nothing was cleaned.");
                    return;
                }

                if (!cleanupResult.Started)
                {
                    SetLexDeskMaintenanceStatus(
                        "LexDesk could not start Windows component cleanup.",
                        true);
                    return;
                }

                bool gotCleanupExit = TryGetLexDeskMaintenanceExitCode(
                    cleanupResult.Output,
                    "CLEANUP",
                    out int cleanupExit);

                string cleanupSection =
                    GetLexDeskMaintenanceSection(cleanupResult.Output, "CLEANUP");

                bool cleanupSucceeded =
                    gotCleanupExit &&
                    IsLexDeskMaintenanceSuccessExit(cleanupExit) &&
                    cleanupSection.Contains(
                        "operation completed successfully",
                        StringComparison.OrdinalIgnoreCase);

                if (cleanupSucceeded)
                {
                    SetLexDeskMaintenanceStatus(
                        "Windows cleanup finished successfully. Old superseded component files were removed.",
                        false);
                    UpdateSecurityStatus("Windows component cleanup complete", false);
                }
                else
                {
                    SetLexDeskMaintenanceStatus(
                        "Windows cleanup did not complete. Nothing else will be changed. Restart the PC before trying again.",
                        true);
                    UpdateSecurityStatus("Windows cleanup did not complete", true);
                }
            }
            catch (Exception ex)
            {
                SetLexDeskMaintenanceStatus(
                    "LexDesk could not finish Windows cleanup.",
                    true);

                ShowLexDeskMessageBox(
                    $"LexDesk could not finish Windows cleanup.\n\n{SanitizeExceptionMessage(ex)}",
                    "Windows Cleanup",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                SetLexDeskMaintenanceBusy(false);
            }
        }


        // ============================================================
        // LexDesk Pro - Protection / Updates / Safe Cleanup - Stage 3
        // Keeps Grandma-facing actions simple. LexDesk never forces Defender
        // on when another antivirus is registered, never alters antivirus
        // exclusions, and only removes old files from Windows temporary folders.
        // ============================================================

        private sealed class LexDeskPowerShellResult
        {
            public bool Started { get; init; }
            public bool Cancelled { get; init; }
            public int? ExitCode { get; init; }
        }

        private sealed class LexDeskTempScanResult
        {
            public int FileCount { get; init; }
            public long Bytes { get; init; }
        }

        private const int LexDeskSafeTempMinimumAgeHours = 48;

        private bool _lexDeskStage3Busy = false;
        private bool _lexDeskCanTurnOnDefender = false;
        private bool _lexDeskDefenderScanAvailable = false;
        private int _lexDeskSafeTempFileCount = 0;
        private long _lexDeskSafeTempBytes = 0;

        private void SetLexDeskStage3Status(string text, bool? needsAttention = null)
        {
            if (LexDeskStage3StatusText == null)
                return;

            LexDeskStage3StatusText.Text = text ?? "";

            if (needsAttention.HasValue)
            {
                LexDeskStage3StatusText.Foreground =
                    GetPcHealthBrush(needsAttention.Value);
            }
            else
            {
                LexDeskStage3StatusText.Foreground =
                    TryFindResource("TextSecondary") as Brush ?? Brushes.Gray;
            }
        }

        private void SetLexDeskStage3Busy(bool busy)
        {
            _lexDeskStage3Busy = busy;

            if (LexDeskTurnOnDefenderButton != null)
                LexDeskTurnOnDefenderButton.IsEnabled = !busy && _lexDeskCanTurnOnDefender;

            if (LexDeskQuickVirusScanButton != null)
                LexDeskQuickVirusScanButton.IsEnabled = !busy && _lexDeskDefenderScanAvailable;

            if (LexDeskFullVirusScanButton != null)
                LexDeskFullVirusScanButton.IsEnabled = !busy && _lexDeskDefenderScanAvailable;

            if (LexDeskCheckTemporaryFilesButton != null)
                LexDeskCheckTemporaryFilesButton.IsEnabled = !busy;

            if (LexDeskCleanTemporaryFilesButton != null)
            {
                LexDeskCleanTemporaryFilesButton.IsEnabled =
                    !busy && _lexDeskSafeTempFileCount > 0 && _lexDeskSafeTempBytes > 0;
            }

            if (LexDeskStage3ProgressBar != null)
            {
                LexDeskStage3ProgressBar.Visibility =
                    busy ? Visibility.Visible : Visibility.Collapsed;
            }
        }

        private static bool IsMicrosoftDefenderProductName(string name)
        {
            if (string.IsNullOrWhiteSpace(name))
                return false;

            return name.Contains("Microsoft Defender", StringComparison.OrdinalIgnoreCase) ||
                   name.Contains("Windows Defender", StringComparison.OrdinalIgnoreCase) ||
                   name.Contains("Microsoft Security Essentials", StringComparison.OrdinalIgnoreCase);
        }

        private List<string> GetRegisteredAntivirusNameListForActions()
        {
            var names = new List<string>();

            try
            {
                using var searcher = new ManagementObjectSearcher(
                    @"root\SecurityCenter2",
                    "SELECT displayName FROM AntiVirusProduct");

                foreach (ManagementBaseObject item in searcher.Get())
                {
                    string name = item["displayName"]?.ToString()?.Trim() ?? "";

                    if (!string.IsNullOrWhiteSpace(name) &&
                        !names.Contains(name, StringComparer.OrdinalIgnoreCase))
                    {
                        names.Add(name);
                    }
                }
            }
            catch
            {
                // Security Center information can be unavailable on managed PCs.
            }

            return names;
        }

        private string GetThirdPartyAntivirusNamesForActions()
        {
            List<string> thirdParty = GetRegisteredAntivirusNameListForActions()
                .Where(name => !IsMicrosoftDefenderProductName(name))
                .ToList();

            return string.Join(", ", thirdParty);
        }

        private bool IsWindowsAntivirusHealthy()
        {
            try
            {
                int result = WscGetSecurityProviderHealth(
                    WscSecurityProviderAntivirus,
                    out LexDeskWscHealth health);

                return result >= 0 && health == LexDeskWscHealth.Good;
            }
            catch
            {
                return false;
            }
        }

        private void RefreshLexDeskStage3ProtectionUi()
        {
            string thirdPartyNames = GetThirdPartyAntivirusNamesForActions();
            bool thirdPartyRegistered = !string.IsNullOrWhiteSpace(thirdPartyNames);
            bool antivirusHealthy = IsWindowsAntivirusHealthy();

            _lexDeskCanTurnOnDefender = !thirdPartyRegistered && !antivirusHealthy;
            _lexDeskDefenderScanAvailable = !thirdPartyRegistered && antivirusHealthy;

            if (LexDeskProtectionActionText != null)
            {
                if (thirdPartyRegistered && antivirusHealthy)
                {
                    LexDeskProtectionActionText.Text =
                        $"This PC is protected by {thirdPartyNames}. LexDesk will leave Microsoft Defender real-time protection alone so two antivirus products are not competing.";
                    LexDeskProtectionActionText.Foreground = GetPcHealthBrush(false);
                }
                else if (thirdPartyRegistered)
                {
                    LexDeskProtectionActionText.Text =
                        $"{thirdPartyNames} is registered as antivirus, but Windows says protection needs attention. Open Windows Security or the antivirus app. LexDesk will not force Defender on beside it.";
                    LexDeskProtectionActionText.Foreground = GetPcHealthBrush(true);
                }
                else if (antivirusHealthy)
                {
                    LexDeskProtectionActionText.Text =
                        "Windows virus protection is on. Microsoft Defender quick and full scans are available.";
                    LexDeskProtectionActionText.Foreground = GetPcHealthBrush(false);
                }
                else
                {
                    LexDeskProtectionActionText.Text =
                        "Windows does not report healthy antivirus protection. LexDesk can ask Windows to turn on Microsoft Defender.";
                    LexDeskProtectionActionText.Foreground = GetPcHealthBrush(true);
                }
            }

            SetLexDeskStage3Busy(_lexDeskStage3Busy);
        }

        private string GetLexDeskWindowsPowerShellPath()
        {
            try
            {
                string path = Path.Combine(
                    Environment.SystemDirectory,
                    "WindowsPowerShell",
                    "v1.0",
                    "powershell.exe");

                if (File.Exists(path))
                    return path;
            }
            catch { }

            return "powershell.exe";
        }

        private async Task<LexDeskPowerShellResult> RunLexDeskElevatedPowerShellAsync(
            string command,
            bool waitForExit)
        {
            string powerShell = GetLexDeskWindowsPowerShellPath();
            string safeCommand = (command ?? "").Replace("\"", "\\\"");

            var psi = new ProcessStartInfo
            {
                FileName = powerShell,
                Arguments = $"-NoProfile -NonInteractive -ExecutionPolicy Bypass -Command \"{safeCommand}\"",
                UseShellExecute = true,
                WindowStyle = ProcessWindowStyle.Hidden,
                WorkingDirectory = Environment.SystemDirectory
            };

            if (!IsRunningAsAdmin())
                psi.Verb = "runas";

            Process? process;

            try
            {
                process = Process.Start(psi);
            }
            catch (System.ComponentModel.Win32Exception ex)
                when (ex.NativeErrorCode == 1223)
            {
                return new LexDeskPowerShellResult
                {
                    Started = false,
                    Cancelled = true
                };
            }
            catch
            {
                return new LexDeskPowerShellResult
                {
                    Started = false,
                    Cancelled = false
                };
            }

            if (process == null)
            {
                return new LexDeskPowerShellResult
                {
                    Started = false,
                    Cancelled = false
                };
            }

            if (waitForExit)
            {
                await process.WaitForExitAsync();
                int code = process.ExitCode;
                process.Dispose();

                return new LexDeskPowerShellResult
                {
                    Started = true,
                    Cancelled = false,
                    ExitCode = code
                };
            }

            await Task.Delay(900);

            if (process.HasExited)
            {
                int code = process.ExitCode;
                process.Dispose();

                return new LexDeskPowerShellResult
                {
                    Started = true,
                    Cancelled = false,
                    ExitCode = code
                };
            }

            process.Dispose();

            return new LexDeskPowerShellResult
            {
                Started = true,
                Cancelled = false,
                ExitCode = null
            };
        }

        private async void LexDeskOpenWindowsSecurity_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;

            bool opened =
                await OpenLexDeskNativeWindowsSurfaceAsync(
                    "ms-settings:windowsdefender",
                    "Windows Security");

            if (opened)
            {
                SetLexDeskStage3Status(
                    "Windows Security is open. Use Virus & threat protection to review warnings or protection history.");
            }
        }

        private async void LexDeskTurnOnDefender_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;

            if (_lexDeskStage3Busy)
                return;

            string thirdPartyNames = GetThirdPartyAntivirusNamesForActions();

            if (!string.IsNullOrWhiteSpace(thirdPartyNames))
            {
                ShowLexDeskMessageBox(
                    $"{thirdPartyNames} is registered as antivirus on this PC.\n\n" +
                    "LexDesk will not force Microsoft Defender real-time protection on beside another antivirus product.\n\n" +
                    "Open Windows Security or the antivirus app and fix that protection first.",
                    "Antivirus Already Installed",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);

                RefreshLexDeskStage3ProtectionUi();
                return;
            }

            if (IsWindowsAntivirusHealthy())
            {
                RefreshLexDeskStage3ProtectionUi();
                SetLexDeskStage3Status("Virus protection is already on.", false);
                return;
            }

            var decision = ShowLexDeskMessageBox(
                "LexDesk will ask Windows to turn on Microsoft Defender real-time protection.\n\n" +
                "This does not change Defender exclusions or other advanced security settings.\n\n" +
                "Windows will ask for Administrator permission. Continue?",
                "Turn On Microsoft Defender",
                MessageBoxButton.YesNo,
                MessageBoxImage.Information);

            if (decision != MessageBoxResult.Yes)
                return;

            SetLexDeskStage3Busy(true);
            SetLexDeskStage3Status("Asking Windows to turn on Microsoft Defender...");

            try
            {
                LexDeskPowerShellResult result = await RunLexDeskElevatedPowerShellAsync(
                    "$ErrorActionPreference='Stop'; Set-MpPreference -DisableRealtimeMonitoring $false",
                    waitForExit: true);

                if (result.Cancelled)
                {
                    SetLexDeskStage3Status(
                        "Administrator permission was cancelled. Nothing was changed.");
                    return;
                }

                if (!result.Started || result.ExitCode.GetValueOrDefault(-1) != 0)
                {
                    SetLexDeskStage3Status(
                        "Windows did not allow LexDesk to turn on Defender automatically. Open Windows Security to finish it there.",
                        true);
                    TryStartExternalProcess("ms-settings:windowsdefender", "Windows Security");
                    return;
                }

                await Task.Delay(1500);
                RefreshLexDeskStage3ProtectionUi();

                if (IsWindowsAntivirusHealthy())
                {
                    SetLexDeskStage3Status(
                        "Microsoft Defender protection is on.",
                        false);
                    UpdateSecurityStatus("Microsoft Defender protection on", false);
                }
                else
                {
                    SetLexDeskStage3Status(
                        "Windows still reports that virus protection needs attention. Windows Security has been opened so you can finish the setting there.",
                        true);
                    TryStartExternalProcess("ms-settings:windowsdefender", "Windows Security");
                }
            }
            catch (Exception ex)
            {
                SetLexDeskStage3Status(
                    "LexDesk could not finish the Defender check.",
                    true);

                ShowLexDeskMessageBox(
                    $"LexDesk could not finish the Defender check.\n\n{SanitizeExceptionMessage(ex)}",
                    "Microsoft Defender",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                RefreshLexDeskStage3ProtectionUi();
                SetLexDeskStage3Busy(false);
            }
        }

        private async Task StartLexDeskDefenderScanAsync(string scanType, string friendlyName)
        {
            if (_lexDeskStage3Busy)
                return;

            string thirdPartyNames = GetThirdPartyAntivirusNamesForActions();

            if (!string.IsNullOrWhiteSpace(thirdPartyNames))
            {
                ShowLexDeskMessageBox(
                    $"This PC is using {thirdPartyNames}.\n\n" +
                    "Use that antivirus program for scans. LexDesk will not start a competing Microsoft Defender scan.",
                    "Use Your Antivirus",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            if (!IsWindowsAntivirusHealthy())
            {
                RefreshLexDeskStage3ProtectionUi();

                ShowLexDeskMessageBox(
                    "Windows does not report healthy virus protection yet.\n\n" +
                    "Turn on Microsoft Defender first, then run the scan.",
                    "Turn On Protection First",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            if (string.Equals(scanType, "FullScan", StringComparison.OrdinalIgnoreCase))
            {
                var fullDecision = ShowLexDeskMessageBox(
                    "A full virus scan checks the whole computer and can take a long time.\n\n" +
                    "You can keep using LexDesk while Microsoft Defender scans.\n\n" +
                    "Start the full scan?",
                    "Full Virus Scan",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Information);

                if (fullDecision != MessageBoxResult.Yes)
                    return;
            }

            SetLexDeskStage3Busy(true);
            SetLexDeskStage3Status($"Starting Microsoft Defender {friendlyName.ToLowerInvariant()}...");

            try
            {
                LexDeskPowerShellResult result = await RunLexDeskElevatedPowerShellAsync(
                    $"$ErrorActionPreference='Stop'; Start-MpScan -ScanType {scanType}",
                    waitForExit: false);

                if (result.Cancelled)
                {
                    SetLexDeskStage3Status(
                        "Administrator permission was cancelled. The scan was not started.");
                    return;
                }

                if (!result.Started ||
                    (result.ExitCode.HasValue && result.ExitCode.Value != 0))
                {
                    SetLexDeskStage3Status(
                        "Microsoft Defender could not start the scan. Open Windows Security to review protection.",
                        true);
                    TryStartExternalProcess("ms-settings:windowsdefender", "Windows Security");
                    return;
                }

                SetLexDeskStage3Status(
                    $"Microsoft Defender {friendlyName.ToLowerInvariant()} started. You can keep using LexDesk. Open Windows Security later to review scan results or protection history.",
                    false);
                UpdateSecurityStatus($"Defender {friendlyName.ToLowerInvariant()} started", false);
            }
            catch (Exception ex)
            {
                SetLexDeskStage3Status(
                    "LexDesk could not start the Microsoft Defender scan.",
                    true);

                ShowLexDeskMessageBox(
                    $"LexDesk could not start the Microsoft Defender scan.\n\n{SanitizeExceptionMessage(ex)}",
                    friendlyName,
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                SetLexDeskStage3Busy(false);
            }
        }

