        private static IEnumerable<string> EnumerateLexDeskFilesSafely(string root)
        {
            if (string.IsNullOrWhiteSpace(root) || !Directory.Exists(root))
                yield break;

            var pending = new Stack<string>();
            pending.Push(root);

            while (pending.Count > 0)
            {
                string current = pending.Pop();

                string[] files;

                try
                {
                    files = Directory.GetFiles(current);
                }
                catch
                {
                    files = Array.Empty<string>();
                }

                foreach (string file in files)
                    yield return file;

                string[] directories;

                try
                {
                    directories = Directory.GetDirectories(current);
                }
                catch
                {
                    directories = Array.Empty<string>();
                }

                foreach (string directory in directories)
                {
                    try
                    {
                        FileAttributes attributes = File.GetAttributes(directory);

                        if ((attributes & FileAttributes.ReparsePoint) != 0)
                            continue;

                        pending.Push(directory);
                    }
                    catch
                    {
                        // Skip folders Windows does not let the current user inspect.
                    }
                }
            }
        }

        private List<string> GetLexDeskSafeTempRoots()
        {
            var roots = new List<string>();

            try
            {
                string userTemp = Path.GetFullPath(Path.GetTempPath());

                if (Directory.Exists(userTemp))
                    roots.Add(userTemp.TrimEnd(Path.DirectorySeparatorChar));
            }
            catch { }

            try
            {
                string windowsFolder = Environment.GetFolderPath(Environment.SpecialFolder.Windows);
                string windowsTemp = Path.Combine(windowsFolder, "Temp");

                if (Directory.Exists(windowsTemp))
                    roots.Add(Path.GetFullPath(windowsTemp).TrimEnd(Path.DirectorySeparatorChar));
            }
            catch { }

            return roots
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private LexDeskTempScanResult ScanLexDeskSafeTemporaryFiles()
        {
            DateTime cutoffUtc = DateTime.UtcNow.AddHours(-LexDeskSafeTempMinimumAgeHours);
            long totalBytes = 0;
            int fileCount = 0;

            foreach (string root in GetLexDeskSafeTempRoots())
            {
                foreach (string file in EnumerateLexDeskFilesSafely(root))
                {
                    try
                    {
                        var info = new FileInfo(file);

                        if (!info.Exists || info.LastWriteTimeUtc > cutoffUtc)
                            continue;

                        if ((info.Attributes & FileAttributes.ReparsePoint) != 0)
                            continue;

                        totalBytes += Math.Max(0, info.Length);

                        if (fileCount < int.MaxValue)
                            fileCount++;
                    }
                    catch
                    {
                        // Locked and protected temporary files are deliberately skipped.
                    }
                }
            }

            return new LexDeskTempScanResult
            {
                FileCount = fileCount,
                Bytes = totalBytes
            };
        }

        private static string FormatLexDeskBytes(long bytes)
        {
            if (bytes < 1024)
                return $"{Math.Max(0, bytes)} bytes";

            double kb = bytes / 1024d;

            if (kb < 1024)
                return $"{kb:0.0} KB";

            double mb = kb / 1024d;

            if (mb < 1024)
                return $"{mb:0.0} MB";

            double gb = mb / 1024d;
            return $"{gb:0.00} GB";
        }

        private async void LexDeskCheckTemporaryFiles_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;

            if (_lexDeskStage3Busy)
                return;

            SetLexDeskStage3Busy(true);
            SetLexDeskStage3Status(
                "Checking old temporary files. Nothing is being deleted...");

            if (LexDeskSafeCleanupStatusText != null)
            {
                LexDeskSafeCleanupStatusText.Text = "Checking...";
                LexDeskSafeCleanupStatusText.Foreground =
                    TryFindResource("TextSecondary") as Brush ?? Brushes.Gray;
            }

            try
            {
                LexDeskTempScanResult result = await Task.Run(ScanLexDeskSafeTemporaryFiles);

                _lexDeskSafeTempFileCount = result.FileCount;
                _lexDeskSafeTempBytes = result.Bytes;

                if (LexDeskSafeCleanupStatusText != null)
                {
                    if (result.FileCount <= 0 || result.Bytes <= 0)
                    {
                        LexDeskSafeCleanupStatusText.Text =
                            "No old temporary files were found that LexDesk can safely remove.";
                        LexDeskSafeCleanupStatusText.Foreground = GetPcHealthBrush(false);
                    }
                    else
                    {
                        LexDeskSafeCleanupStatusText.Text =
                            $"Found {result.FileCount:N0} old temporary files using about {FormatLexDeskBytes(result.Bytes)}.";
                        LexDeskSafeCleanupStatusText.Foreground = GetPcHealthBrush(true);
                    }
                }

                SetLexDeskStage3Status(
                    result.FileCount > 0
                        ? "Temporary-file check finished. Nothing has been deleted yet."
                        : "Temporary-file check finished. No cleanup is needed.",
                    result.FileCount > 0 ? true : false);
            }
            catch (Exception ex)
            {
                _lexDeskSafeTempFileCount = 0;
                _lexDeskSafeTempBytes = 0;

                if (LexDeskSafeCleanupStatusText != null)
                {
                    LexDeskSafeCleanupStatusText.Text =
                        "LexDesk could not finish the temporary-file check.";
                    LexDeskSafeCleanupStatusText.Foreground = GetPcHealthBrush(true);
                }

                ShowLexDeskMessageBox(
                    $"LexDesk could not finish the temporary-file check.\n\n{SanitizeExceptionMessage(ex)}",
                    "Temporary Files",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                SetLexDeskStage3Busy(false);
            }
        }

        private static string EscapeLexDeskPowerShellSingleQuoted(string value)
        {
            return (value ?? "").Replace("'", "''");
        }

        private async Task<LexDeskPowerShellResult> RunLexDeskSafeTempCleanupAsync(
            string resultPath)
        {
            string folder = GetLexDeskMaintenanceFolder();
            string token = Guid.NewGuid().ToString("N");
            string scriptPath = Path.Combine(folder, $"safe_temp_cleanup_{token}.ps1");

            List<string> roots = GetLexDeskSafeTempRoots();

            var script = new StringBuilder();
            script.AppendLine("$ErrorActionPreference = 'SilentlyContinue'");
            script.AppendLine($"$cutoff = (Get-Date).AddHours(-{LexDeskSafeTempMinimumAgeHours})");
            script.AppendLine("$deleted = [long]0");
            script.AppendLine("$freed = [long]0");
            script.AppendLine("$roots = @(");

            foreach (string root in roots)
            {
                script.AppendLine(
                    $"    '{EscapeLexDeskPowerShellSingleQuoted(root)}'");
            }

            script.AppendLine(")");
            script.AppendLine("foreach ($root in $roots) {");
            script.AppendLine("    if (-not (Test-Path -LiteralPath $root)) { continue }");
            script.AppendLine("    Get-ChildItem -LiteralPath $root -Force -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -lt $cutoff } | ForEach-Object {");
            script.AppendLine("        try {");
            script.AppendLine("            $length = [long]$_.Length");
            script.AppendLine("            Remove-Item -LiteralPath $_.FullName -Force -ErrorAction Stop");
            script.AppendLine("            $deleted++");
            script.AppendLine("            $freed += $length");
            script.AppendLine("        } catch { }");
            script.AppendLine("    }");
            script.AppendLine("}");
            script.AppendLine($"'DELETED=' + $deleted | Set-Content -LiteralPath '{EscapeLexDeskPowerShellSingleQuoted(resultPath)}' -Encoding ASCII");
            script.AppendLine($"'FREED=' + $freed | Add-Content -LiteralPath '{EscapeLexDeskPowerShellSingleQuoted(resultPath)}' -Encoding ASCII");

            File.WriteAllText(
                scriptPath,
                script.ToString(),
                new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));

            string powerShell = GetLexDeskWindowsPowerShellPath();

            var psi = new ProcessStartInfo
            {
                FileName = powerShell,
                Arguments = $"-NoProfile -NonInteractive -ExecutionPolicy Bypass -File \"{scriptPath}\"",
                UseShellExecute = true,
                WindowStyle = ProcessWindowStyle.Hidden,
                WorkingDirectory = Environment.SystemDirectory
            };

            if (!IsRunningAsAdmin())
                psi.Verb = "runas";

            try
            {
                Process? process;

                try
                {
                    process = Process.Start(psi);
                }
                catch (System.ComponentModel.Win32Exception ex)
                    when (ex.NativeErrorCode == 1223)
                {
                    return new LexDeskPowerShellResult
                    {
                        Started = false,
                        Cancelled = true
                    };
                }

                if (process == null)
                {
                    return new LexDeskPowerShellResult
                    {
                        Started = false,
                        Cancelled = false
                    };
                }

                await process.WaitForExitAsync();
                int exitCode = process.ExitCode;
                process.Dispose();

                return new LexDeskPowerShellResult
                {
                    Started = true,
                    Cancelled = false,
                    ExitCode = exitCode
                };
            }
            finally
            {
                try
                {
                    if (File.Exists(scriptPath))
                        File.Delete(scriptPath);
                }
                catch { }
            }
        }

        private static bool TryReadLexDeskTempCleanupResult(
            string resultPath,
            out long deleted,
            out long freed)
        {
            deleted = 0;
            freed = 0;

            try
            {
                if (!File.Exists(resultPath))
                    return false;

                foreach (string line in File.ReadAllLines(resultPath))
                {
                    if (line.StartsWith("DELETED=", StringComparison.OrdinalIgnoreCase))
                    {
                        if (long.TryParse(line.Substring("DELETED=".Length).Trim(), out long parsedDeleted))
                            deleted = parsedDeleted;
                    }
                    else if (line.StartsWith("FREED=", StringComparison.OrdinalIgnoreCase))
                    {
                        if (long.TryParse(line.Substring("FREED=".Length).Trim(), out long parsedFreed))
                            freed = parsedFreed;
                    }
                }

                return true;
            }
            catch
            {
                return false;
            }
        }

        private async void LexDeskCleanTemporaryFiles_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;

            if (_lexDeskStage3Busy)
                return;

            if (_lexDeskSafeTempFileCount <= 0 || _lexDeskSafeTempBytes <= 0)
            {
                ShowLexDeskMessageBox(
                    "Run Check Temporary Files first. LexDesk will only enable cleanup after it finds old temporary files.",
                    "Check Temporary Files First",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            var decision = ShowLexDeskMessageBox(
                $"LexDesk found about {FormatLexDeskBytes(_lexDeskSafeTempBytes)} of old temporary files.\n\n" +
                $"Only temporary files older than {LexDeskSafeTempMinimumAgeHours} hours are targeted. Locked files are skipped.\n\n" +
                "LexDesk does NOT clean Documents, Pictures, Desktop, Downloads, browser data or the Recycle Bin.\n\n" +
                "Windows will ask for Administrator permission so its own Temp folder can be cleaned too. Continue?",
                "Clean Temporary Files",
                MessageBoxButton.YesNo,
                MessageBoxImage.Information);

            if (decision != MessageBoxResult.Yes)
                return;

            SetLexDeskStage3Busy(true);
            SetLexDeskStage3Status(
                "Cleaning old temporary files. Files in use by Windows or programs will be left alone...");

            string resultPath = Path.Combine(
                GetLexDeskMaintenanceFolder(),
                "safe_temp_cleanup_latest.result.txt");

            try
            {
                try
                {
                    if (File.Exists(resultPath))
                        File.Delete(resultPath);
                }
                catch { }

                LexDeskPowerShellResult result =
                    await RunLexDeskSafeTempCleanupAsync(resultPath);

                if (result.Cancelled)
                {
                    SetLexDeskStage3Status(
                        "Administrator permission was cancelled. Nothing was cleaned.");
                    return;
                }

                if (!result.Started || result.ExitCode.GetValueOrDefault(-1) != 0)
                {
                    SetLexDeskStage3Status(
                        "Windows did not finish the temporary-file cleanup. Nothing else will be changed.",
                        true);
                    return;
                }

                bool gotResult = TryReadLexDeskTempCleanupResult(
                    resultPath,
                    out long deleted,
                    out long freed);

                _lexDeskSafeTempFileCount = 0;
                _lexDeskSafeTempBytes = 0;

                if (LexDeskSafeCleanupStatusText != null)
                {
                    LexDeskSafeCleanupStatusText.Text = gotResult
                        ? $"Cleanup finished. Removed {deleted:N0} old temporary files and freed about {FormatLexDeskBytes(freed)}."
                        : "Cleanup finished. Run Check Temporary Files again if you want to confirm what remains.";
                    LexDeskSafeCleanupStatusText.Foreground = GetPcHealthBrush(false);
                }

                SetLexDeskStage3Status(
                    "Safe temporary-file cleanup finished.",
                    false);
                UpdateSecurityStatus("Temporary-file cleanup complete", false);
            }
            catch (Exception ex)
            {
                SetLexDeskStage3Status(
                    "LexDesk could not finish temporary-file cleanup.",
                    true);

                ShowLexDeskMessageBox(
                    $"LexDesk could not finish temporary-file cleanup.\n\n{SanitizeExceptionMessage(ex)}",
                    "Temporary Files",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                try
                {
                    if (File.Exists(resultPath))
                        File.Delete(resultPath);
                }
                catch { }

                SetLexDeskStage3Busy(false);
            }
        }

