        private enum LexDeskLaunchType
        {
            Shortcut,
            Exe,
            Aumid,
            Fallback
        }

        private sealed class LexDeskInstalledApp
        {
            public string Name { get; init; } = "";
            public string Target { get; init; } = "";
            public string ShortcutPath { get; init; } = "";
            public string Aumid { get; init; } = "";
            public string Arguments { get; init; } = "";
            public string WorkingDirectory { get; init; } = "";
            public LexDeskLaunchType LaunchType { get; init; } = LexDeskLaunchType.Shortcut;
        }

        private readonly Dictionary<string, DateTime> _lexDeskForcedLastLaunchUtc =
            new(StringComparer.OrdinalIgnoreCase);
        private List<LexDeskInstalledApp> _lexDeskAllApps = new();

        private readonly Dictionary<string, ImageSource?> _lexDeskAppIconCache =
        new(StringComparer.OrdinalIgnoreCase);

        // ============================================
        // LexDesk pinned taskbar apps
        // ============================================

        private const string LexDeskPinnedAppsFileName =
            "lexdesk_pinned_apps.json";

        // Keep the lower bar usable on smaller screens.
        // We can revisit this during the final responsive/DPI pass.
        private const int LexDeskMaxPinnedApps = 6;

        private readonly List<string> _lexDeskPinnedAppNames = new();

        private readonly Dictionary<string, int> _lexDeskAppUseCounts =
    new(StringComparer.OrdinalIgnoreCase);

        private const string LexDeskAppUsageFileName = "lexdesk_app_usage.txt";

        private readonly HashSet<string> _lexDeskHiddenApps =
    new(StringComparer.OrdinalIgnoreCase);

        private const string LexDeskHiddenAppsFileName = "lexdesk_hidden_apps.txt";

        private const string LexDeskAppsCacheFileName = "lexdesk_apps_cache.json";
        private static readonly TimeSpan LexDeskAppsCacheMaxAge =
    TimeSpan.FromDays(1);

        private bool _lexDeskShowHiddenApps = false;

        private bool _lexDeskHiddenAppsPanelDirty = true;

        private bool _lexDeskAppsUiBuilt = false;
        private bool _lexDeskAppsLoading = false;

        private async void ShowLexDeskAppsPanel()
        {
            try
            {
                if (SettingsDropdown != null)
                    SettingsDropdown.IsOpen = false;

                if (PrivacyDropdown != null)
                    PrivacyDropdown.IsOpen = false;

                if (StatusPopup != null)
                    StatusPopup.IsOpen = false;

                if (WebActionsDropdown != null)
                    WebActionsDropdown.IsOpen = false;

                if (MainMenuDropdown != null)
                    MainMenuDropdown.IsOpen = false;

                if (LexDeskStartPopup != null)
                    LexDeskStartPopup.IsOpen = false;

                if (SettingsOverlayHost != null)
                    SettingsOverlayHost.Visibility =
                        Visibility.Collapsed;

                if (GuideOverlay != null)
                    GuideOverlay.Visibility =
                        Visibility.Collapsed;

                if (LexDeskHomePanel != null)
                    LexDeskHomePanel.Visibility =
                        Visibility.Collapsed;

                if (LexDeskMaintenancePanel != null)
                    LexDeskMaintenancePanel.Visibility =
                        Visibility.Collapsed;

                if (PagesHost != null)
                    PagesHost.Visibility =
                        Visibility.Collapsed;

                if (LexDeskAppsPanel != null)
                    LexDeskAppsPanel.Visibility =
                        Visibility.Visible;

                // --------------------------------------------
                // SPEED:
                // If Apps has already been built, keep it.
                // Do not destroy and recreate every button.
                // --------------------------------------------
                if (_lexDeskAppsUiBuilt &&
                    _lexDeskAllApps != null &&
                    _lexDeskAllApps.Count > 0)
                {
                    RefreshLexDeskShowHiddenButtonText();

                    try
                    {
                        LexDeskAppsSearchBox?.Focus();
                    }
                    catch { }

                    UpdateSecurityStatus(
                        "Apps opened",
                        false);

                    return;
                }

                // Prevent accidental double-loads.
                if (_lexDeskAppsLoading)
                    return;

                _lexDeskAppsLoading = true;

                try
                {
                    ShowLexDeskAppsMessage(
                        "Loading apps...");

                    LoadLexDeskAppUsageCounts();
                    LoadLexDeskHiddenApps();

                    _lexDeskShowHiddenApps = false;

                    UpdateSecurityStatus(
                        "Loading apps",
                        false);

                    var apps =
                        await GetLexDeskInstalledAppsCachedAsync(
                            false);

                    _lexDeskAllApps =
                        apps ??
                        new List<LexDeskInstalledApp>();

                    if (LexDeskAppsSearchBox != null &&
                        !string.IsNullOrEmpty(
                            LexDeskAppsSearchBox.Text))
                    {
                        LexDeskAppsSearchBox.Text = "";
                    }

                    RefreshLexDeskShowHiddenButtonText();

                    PopulateLexDeskAppsList(
                        GetLexDeskVisibleApps(
                            _lexDeskAllApps));

                    PopulateLexDeskMostUsedApps();

                    _lexDeskAppsUiBuilt = true;

                    try
                    {
                        LexDeskAppsSearchBox?.Focus();
                    }
                    catch { }

                    UpdateSecurityStatus(
                        "Apps opened",
                        false);
                }
                finally
                {
                    _lexDeskAppsLoading = false;
                }
            }
            catch
            {
                _lexDeskAppsLoading = false;

                ShowLexDeskAppsMessage(
                    "Could not load apps.");
            }
        }

        private Task<List<LexDeskInstalledApp>>
    RunLexDeskAppDiscoveryStaAsync()
        {
            var completion =
                new TaskCompletionSource<
                    List<LexDeskInstalledApp>>(
                    TaskCreationOptions.RunContinuationsAsynchronously);

            var thread =
                new System.Threading.Thread(() =>
                {
                    try
                    {
                        completion.TrySetResult(
                            GetLexDeskInstalledApps());
                    }
                    catch (Exception ex)
                    {
                        completion.TrySetException(ex);
                    }
                });

            thread.IsBackground = true;

            thread.SetApartmentState(
                System.Threading.ApartmentState.STA);

            thread.Start();

            return completion.Task;
        }

        private async Task<List<LexDeskInstalledApp>> GetLexDeskInstalledAppsCachedAsync(bool forceRefresh)
        {
            try
            {
                if (!forceRefresh)
                {
                    var cached = LoadLexDeskAppsCache();

                    if (cached.Count > 0)
                        return cached;
                }

                var fresh =
    await RunLexDeskAppDiscoveryStaAsync();

                fresh ??= new List<LexDeskInstalledApp>();

                SaveLexDeskAppsCache(fresh);

                return fresh;
            }
            catch
            {
                try
                {
                    var cached = LoadLexDeskAppsCache();

                    if (cached.Count > 0)
                        return cached;
                }
                catch { }

                return new List<LexDeskInstalledApp>();
            }
        }

        private string GetLexDeskAppsCacheFilePath()
        {
            try
            {
                return Path.Combine(GetStableAppDataFolder(), LexDeskAppsCacheFileName);
            }
            catch
            {
                return Path.Combine(
                    Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                    "LexAndWhiteStudios",
                    "LexDeskPro",
                    LexDeskAppsCacheFileName);
            }
        }

        private List<LexDeskInstalledApp> LoadLexDeskAppsCache()
        {
            try
            {
                string path = GetLexDeskAppsCacheFilePath();

                if (!File.Exists(path))
                    return new List<LexDeskInstalledApp>();

                DateTime lastWriteUtc = File.GetLastWriteTimeUtc(path);

                if ((DateTime.UtcNow - lastWriteUtc) > LexDeskAppsCacheMaxAge)
                    return new List<LexDeskInstalledApp>();

                string json = File.ReadAllText(path);

                var apps = JsonSerializer.Deserialize<List<LexDeskInstalledApp>>(json);

                if (apps == null)
                    return new List<LexDeskInstalledApp>();

                return apps
                    .Where(app => app != null && !string.IsNullOrWhiteSpace(app.Name))
                    .OrderBy(app => app.Name, StringComparer.OrdinalIgnoreCase)
                    .ToList();
            }
            catch
            {
                return new List<LexDeskInstalledApp>();
            }
        }

        private void SaveLexDeskAppsCache(List<LexDeskInstalledApp> apps)
        {
            try
            {
                string path = GetLexDeskAppsCacheFilePath();

                Directory.CreateDirectory(Path.GetDirectoryName(path) ?? "");

                var cleanApps = (apps ?? new List<LexDeskInstalledApp>())
                    .Where(app => app != null && !string.IsNullOrWhiteSpace(app.Name))
                    .OrderBy(app => app.Name, StringComparer.OrdinalIgnoreCase)
                    .ToList();

                string json = JsonSerializer.Serialize(
                    cleanApps,
                    JsonIndentedOptions);

                File.WriteAllText(path, json);
            }
            catch
            {
                // Cache save must never block Apps opening.
            }
        }

        private async void LexDeskRefreshApps_Click(
    object sender,
    RoutedEventArgs e)
        {
            e.Handled = true;

            if (_lexDeskAppsLoading)
                return;

            _lexDeskAppsLoading = true;

            var refreshTimer =
                Stopwatch.StartNew();

            try
            {
                UpdateSecurityStatus(
                    "Refreshing apps...",
                    false);

                // Snapshot the existing list on the UI thread.
                var existingApps =
                    (_lexDeskAllApps ??
                     new List<LexDeskInstalledApp>())
                    .Where(app => app != null)
                    .ToList();

                // Important:
                // Manual Refresh does NOT run shell:AppsFolder.
                // That full Windows scan remains available when
                // the normal cache expires or is missing.
                var refreshedApps =
                    await Task.Run(() =>
                        GetLexDeskInstalledAppsFastRefresh(
                            existingApps));

                refreshedApps ??=
                    new List<LexDeskInstalledApp>();

                bool changed =
                    !LexDeskAppListsMatch(
                        _lexDeskAllApps,
                        refreshedApps);

                _lexDeskAllApps =
                    refreshedApps;

                if (changed)
                {
                    _lexDeskHiddenAppsPanelDirty = true;

                    if (LexDeskAppsSearchBox != null &&
                        !string.IsNullOrEmpty(
                            LexDeskAppsSearchBox.Text))
                    {
                        LexDeskAppsSearchBox.Text = "";
                    }

                    RefreshLexDeskShowHiddenButtonText();

                    PopulateLexDeskAppsList(
                        GetLexDeskVisibleApps(
                            _lexDeskAllApps));

                    PopulateLexDeskMostUsedApps();

                    _lexDeskAppsUiBuilt = true;
                }

                refreshTimer.Stop();

                UpdateSecurityStatus(
                    changed
                        ? $"Apps updated in " +
                          $"{refreshTimer.Elapsed.TotalSeconds:0.0} seconds"
                        : $"Apps already up to date - " +
                          $"{refreshTimer.Elapsed.TotalSeconds:0.0} seconds",
                    false);
            }
            catch
            {
                UpdateSecurityStatus(
                    "Could not refresh apps",
                    true);
            }
            finally
            {
                _lexDeskAppsLoading = false;
            }
        }

        // ============================================
        // LexDesk Pro - Folder Bubbles
        // Social / Personal / Docs / Music
        // ============================================

        private string _lexDeskCurrentBubbleName = "";
        private string _lexDeskCurrentBubbleFolder = "";

        private readonly string _lexDeskBubbleLabelsPath =
            AppDataPath("bubble_labels.json");

        private readonly Dictionary<string, string> _lexDeskBubbleLabels =
            new(StringComparer.OrdinalIgnoreCase)
            {
                ["Social"] = "Social",
                ["Personal"] = "Personal",
                ["Docs"] = "Docs",
                ["Music"] = "Music"
            };

        private static readonly string[] LexDeskBubbleKeys =
        {
            "Social", "Personal", "Docs", "Music"
        };

        private string GetLexDeskBubbleDisplayName(string bubbleKey)
        {
            bubbleKey = CleanLexDeskBubbleName(bubbleKey);

            if (string.IsNullOrWhiteSpace(bubbleKey))
                return "Bubble";

            return _lexDeskBubbleLabels.TryGetValue(bubbleKey, out string? value) &&
                   !string.IsNullOrWhiteSpace(value)
                ? value
                : bubbleKey;
        }

        private void LoadLexDeskBubbleLabels()
        {
            try
            {
                foreach (string key in LexDeskBubbleKeys)
                    _lexDeskBubbleLabels[key] = key;

                if (!File.Exists(_lexDeskBubbleLabelsPath))
                    return;

                string json = File.ReadAllText(_lexDeskBubbleLabelsPath);
                var saved = JsonSerializer.Deserialize<Dictionary<string, string>>(json);

                if (saved == null)
                    return;

                foreach (string key in LexDeskBubbleKeys)
                {
                    if (!saved.TryGetValue(key, out string? value))
                        continue;

                    value = (value ?? "").Trim();

                    if (value.Length > 20)
                        value = value.Substring(0, 20);

                    if (!string.IsNullOrWhiteSpace(value))
                        _lexDeskBubbleLabels[key] = value;
                }
            }
            catch
            {
                // A damaged label file must never stop LexDesk opening.
            }
        }

        private void SaveLexDeskBubbleLabels()
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_lexDeskBubbleLabelsPath)!);

                string json = JsonSerializer.Serialize(
                    _lexDeskBubbleLabels,
                    JsonIndentedOptions);

                File.WriteAllText(_lexDeskBubbleLabelsPath, json);
            }
            catch
            {
                // Renaming a shortcut is cosmetic. Never let it affect the app.
            }
        }

        private void UpdateLexDeskBubbleButtonLabels()
        {
            try
            {
                if (LexDeskBubbleSocialButton != null)
                    LexDeskBubbleSocialButton.Content = GetLexDeskBubbleDisplayName("Social");

                if (LexDeskBubblePersonalButton != null)
                    LexDeskBubblePersonalButton.Content = GetLexDeskBubbleDisplayName("Personal");

                if (LexDeskBubbleDocsButton != null)
                    LexDeskBubbleDocsButton.Content = GetLexDeskBubbleDisplayName("Docs");

                if (LexDeskBubbleMusicButton != null)
                    LexDeskBubbleMusicButton.Content = GetLexDeskBubbleDisplayName("Music");
            }
            catch
            {
                // Display labels must never affect the folder bubbles.
            }
        }

        private void RenameLexDeskBubbleShortcut(string bubbleKey)
        {
            try
            {
                bubbleKey = CleanLexDeskBubbleName(bubbleKey);

                if (string.IsNullOrWhiteSpace(bubbleKey))
                    return;

                string currentName = GetLexDeskBubbleDisplayName(bubbleKey);

                string newName = Interaction.InputBox(
                    "Choose a name for this LexDesk shortcut.\n\n" +
                    "Use up to 20 characters. Cancel or leave it blank to keep the current name.\n\n" +
                    "Renaming the shortcut does not move or rename the files inside it.",
                    "Rename LexDesk Shortcut",
                    currentName);

                newName = (newName ?? "").Trim();

                if (string.IsNullOrWhiteSpace(newName))
                    return;

                if (newName.Length > 20)
                {
                    ShowLexDeskMessageBox(
                        "Please keep the shortcut name to 20 characters or fewer so it still fits neatly on the LexDesk taskbar.",
                        "Rename LexDesk Shortcut",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                    return;
                }

                _lexDeskBubbleLabels[bubbleKey] = newName;
                SaveLexDeskBubbleLabels();
                UpdateLexDeskBubbleButtonLabels();

                if (string.Equals(
                        _lexDeskCurrentBubbleName,
                        bubbleKey,
                        StringComparison.OrdinalIgnoreCase) &&
                    LexDeskBubbleTitleText != null)
                {
                    LexDeskBubbleTitleText.Text = newName;
                }

                UpdateSecurityStatus($"{newName} shortcut renamed", false);
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro could not rename that shortcut.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "Rename LexDesk Shortcut",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

        private sealed class LexDeskBubbleItem
        {
            public string Name { get; init; } = "";
            public string Path { get; init; } = "";
            public bool IsFolder { get; init; }

            public override string ToString()
            {
                return IsFolder ? "📁 " + Name : "📄 " + Name;
            }
        }

        private void ShowLexDeskBubble(string bubbleName)
        {
            try
            {
                bubbleName = CleanLexDeskBubbleName(bubbleName);

                if (string.IsNullOrWhiteSpace(bubbleName))
                    return;

                if (SettingsDropdown != null)
                    SettingsDropdown.IsOpen = false;

                if (PrivacyDropdown != null)
                    PrivacyDropdown.IsOpen = false;

                if (StatusPopup != null)
                    StatusPopup.IsOpen = false;

                if (WebActionsDropdown != null)
                    WebActionsDropdown.IsOpen = false;

                if (MainMenuDropdown != null)
                    MainMenuDropdown.IsOpen = false;

                if (LexDeskStartPopup != null)
                    LexDeskStartPopup.IsOpen = false;

                if (LexDeskAppsPanel != null)
                    LexDeskAppsPanel.Visibility = Visibility.Collapsed;

                if (LexDeskHomePanel != null)
                    LexDeskHomePanel.Visibility = Visibility.Collapsed;

                if (LexDeskMaintenancePanel != null)
                    LexDeskMaintenancePanel.Visibility = Visibility.Collapsed;

                if (PagesHost != null)
                    PagesHost.Visibility = Visibility.Collapsed;

                _lexDeskCurrentBubbleName = bubbleName;
                _lexDeskCurrentBubbleFolder = GetLexDeskBubbleFolderPath(bubbleName);
                string displayName = GetLexDeskBubbleDisplayName(bubbleName);

                Directory.CreateDirectory(_lexDeskCurrentBubbleFolder);

                if (LexDeskBubbleTitleText != null)
                    LexDeskBubbleTitleText.Text = displayName;

                if (LexDeskBubblePathText != null)
                    LexDeskBubblePathText.Text = _lexDeskCurrentBubbleFolder;

                RefreshLexDeskBubbleItems();

                if (LexDeskBubblePanel != null)
                    LexDeskBubblePanel.Visibility = Visibility.Visible;

                UpdateSecurityStatus($"{displayName} Bubble opened", false);
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro could not open that Bubble.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "LexDesk Bubble",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

        private string CleanLexDeskBubbleName(string bubbleName)
        {
            bubbleName = (bubbleName ?? "").Trim();

            return bubbleName switch
            {
                "Social" => "Social",
                "Personal" => "Personal",
                "Docs" => "Docs",
                "Music" => "Music",
                _ => ""
            };
        }

        private string GetLexDeskBubbleFolderPath(string bubbleName)
        {
            bubbleName = CleanLexDeskBubbleName(bubbleName);

            if (string.IsNullOrWhiteSpace(bubbleName))
                bubbleName = "Bubble";

            return Path.Combine(GetStableAppDataFolder(), "Bubbles", bubbleName);
        }

        private void RefreshLexDeskBubbleItems()
        {
            try
            {
                if (LexDeskBubbleItemsList == null)
                    return;

                LexDeskBubbleItemsList.ItemsSource = null;

                if (string.IsNullOrWhiteSpace(_lexDeskCurrentBubbleFolder))
                    return;

                Directory.CreateDirectory(_lexDeskCurrentBubbleFolder);

                var items = new List<LexDeskBubbleItem>();

                foreach (string folder in Directory.EnumerateDirectories(_lexDeskCurrentBubbleFolder))
                {
                    items.Add(new LexDeskBubbleItem
                    {
                        Name = Path.GetFileName(folder),
                        Path = folder,
                        IsFolder = true
                    });
                }

                foreach (string file in Directory.EnumerateFiles(_lexDeskCurrentBubbleFolder))
                {
                    items.Add(new LexDeskBubbleItem
                    {
                        Name = Path.GetFileName(file),
                        Path = file,
                        IsFolder = false
                    });
                }

                items = items
                    .OrderByDescending(x => x.IsFolder)
                    .ThenBy(x => x.Name, StringComparer.OrdinalIgnoreCase)
                    .ToList();

                if (items.Count == 0)
                {
                    items.Add(new LexDeskBubbleItem
                    {
                        Name = "(empty — click New Folder or Open Folder)",
                        Path = "",
                        IsFolder = false
                    });
                }

                LexDeskBubbleItemsList.ItemsSource = items;
            }
            catch
            {
                // Bubble refresh must never break LexDesk.
            }
        }

        private void HideLexDeskBubble()
        {
            try
            {
                if (LexDeskBubblePanel != null)
                    LexDeskBubblePanel.Visibility = Visibility.Collapsed;

                _lexDeskCurrentBubbleName = "";
                _lexDeskCurrentBubbleFolder = "";

                if (PagesHost != null)
                    PagesHost.Visibility = Visibility.Visible;

                UpdateSecurityStatus("Browsing ready", false);
            }
            catch { }
        }

