        private void LexDeskBubbleNewFolder_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;

            try
            {
                if (string.IsNullOrWhiteSpace(_lexDeskCurrentBubbleFolder))
                    return;

                Directory.CreateDirectory(_lexDeskCurrentBubbleFolder);

                string baseName = "New Folder";
                string newFolder = Path.Combine(_lexDeskCurrentBubbleFolder, baseName);

                int index = 2;

                while (Directory.Exists(newFolder) || File.Exists(newFolder))
                {
                    newFolder = Path.Combine(_lexDeskCurrentBubbleFolder, $"{baseName} {index}");
                    index++;
                }

                Directory.CreateDirectory(newFolder);

                RefreshLexDeskBubbleItems();
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro could not create a new folder.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "LexDesk Bubble",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

