        // ============================================
        // LexDesk Pro - Bubble drag/drop + item menu
        // ============================================

        private void LexDeskBubble_DragOver(object sender, DragEventArgs e)
        {
            try
            {
                if (e.Data.GetDataPresent(DataFormats.FileDrop))
                {
                    e.Effects = DragDropEffects.Copy;
                    e.Handled = true;
                    return;
                }

                e.Effects = DragDropEffects.None;
                e.Handled = true;
            }
            catch
            {
                e.Effects = DragDropEffects.None;
                e.Handled = true;
            }
        }

        private async void LexDeskBubble_Drop(object sender, DragEventArgs e)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(_lexDeskCurrentBubbleFolder))
                    return;

                if (!e.Data.GetDataPresent(DataFormats.FileDrop))
                    return;

                string[] droppedItems = e.Data.GetData(DataFormats.FileDrop) as string[] ?? Array.Empty<string>();

                if (droppedItems.Length == 0)
                    return;

                Directory.CreateDirectory(_lexDeskCurrentBubbleFolder);

                UpdateSecurityStatus("Adding items to folder", false);

                await Task.Run(() =>
                {
                    foreach (string sourcePath in droppedItems)
                    {
                        CopyItemIntoLexDeskBubble(sourcePath, _lexDeskCurrentBubbleFolder);
                    }
                });

                RefreshLexDeskBubbleItems();

                UpdateSecurityStatus("Items added", false);
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro could not add those items.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "LexDesk Folder",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

        private void CopyItemIntoLexDeskBubble(string sourcePath, string destinationFolder)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(sourcePath) ||
                    string.IsNullOrWhiteSpace(destinationFolder))
                    return;

                if (!File.Exists(sourcePath) && !Directory.Exists(sourcePath))
                    return;

                Directory.CreateDirectory(destinationFolder);

                string name = Path.GetFileName(sourcePath);

                if (string.IsNullOrWhiteSpace(name))
                    return;

                string destinationPath = GetUniqueLexDeskBubbleDestinationPath(
                    Path.Combine(destinationFolder, name));

                if (Directory.Exists(sourcePath))
                {
                    CopyLexDeskDirectory(sourcePath, destinationPath);
                    return;
                }

                if (File.Exists(sourcePath))
                {
                    File.Copy(sourcePath, destinationPath, overwrite: false);
                }
            }
            catch
            {
                // One bad item must not stop the whole drop.
            }
        }

        private string GetUniqueLexDeskBubbleDestinationPath(string destinationPath)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(destinationPath))
                    return destinationPath;

                if (!File.Exists(destinationPath) && !Directory.Exists(destinationPath))
                    return destinationPath;

                string folder = Path.GetDirectoryName(destinationPath) ?? "";
                string nameWithoutExtension = Path.GetFileNameWithoutExtension(destinationPath);
                string extension = Path.GetExtension(destinationPath);

                if (string.IsNullOrWhiteSpace(folder))
                    return destinationPath;

                int index = 2;

                while (true)
                {
                    string candidate = Path.Combine(
                        folder,
                        $"{nameWithoutExtension} {index}{extension}");

                    if (!File.Exists(candidate) && !Directory.Exists(candidate))
                        return candidate;

                    index++;
                }
            }
            catch
            {
                return destinationPath;
            }
        }

        private void CopyLexDeskDirectory(string sourceFolder, string destinationFolder)
        {
            Directory.CreateDirectory(destinationFolder);

            foreach (string folder in Directory.EnumerateDirectories(sourceFolder, "*", SearchOption.AllDirectories))
            {
                string relative = Path.GetRelativePath(sourceFolder, folder);
                string targetFolder = Path.Combine(destinationFolder, relative);
                Directory.CreateDirectory(targetFolder);
            }

            foreach (string file in Directory.EnumerateFiles(sourceFolder, "*", SearchOption.AllDirectories))
            {
                string relative = Path.GetRelativePath(sourceFolder, file);
                string targetFile = Path.Combine(destinationFolder, relative);

                Directory.CreateDirectory(Path.GetDirectoryName(targetFile) ?? destinationFolder);
                File.Copy(file, targetFile, overwrite: false);
            }
        }

        private LexDeskBubbleItem? GetSelectedLexDeskBubbleItem()
        {
            try
            {
                if (LexDeskBubbleItemsList?.SelectedItem is LexDeskBubbleItem item &&
                    !string.IsNullOrWhiteSpace(item.Path))
                {
                    return item;
                }
            }
            catch { }

            return null;
        }

        private void LexDeskBubbleItemsList_PreviewMouseRightButtonDown(object sender, MouseButtonEventArgs e)
        {
            try
            {
                var source = e.OriginalSource as DependencyObject;

                while (source != null && source is not ListBoxItem)
                    source = VisualTreeHelper.GetParent(source);

                if (source is ListBoxItem item)
                {
                    item.IsSelected = true;
                    item.Focus();
                }
            }
            catch { }
        }

        private void OpenLexDeskBubbleItem(LexDeskBubbleItem item)
        {
            try
            {
                if (item == null || string.IsNullOrWhiteSpace(item.Path))
                    return;

                if (!File.Exists(item.Path) && !Directory.Exists(item.Path))
                    return;

                Process.Start(new ProcessStartInfo(item.Path)
                {
                    UseShellExecute = true
                });
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro could not open that item.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "LexDesk Folder",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

