        private void LexDeskBubbleRenameItem_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;

            try
            {
                var item = GetSelectedLexDeskBubbleItem();

                if (item == null)
                    return;

                if (!File.Exists(item.Path) && !Directory.Exists(item.Path))
                    return;

                string oldName = Path.GetFileName(item.Path);

                string newName = Interaction.InputBox(
                    "Enter a new name:",
                    "Rename Item",
                    oldName);

                newName = CleanLexDeskFileName(newName);

                if (string.IsNullOrWhiteSpace(newName))
                    return;

                string folder = Path.GetDirectoryName(item.Path) ?? "";

                if (string.IsNullOrWhiteSpace(folder))
                    return;

                string newPath = Path.Combine(folder, newName);

                if (File.Exists(newPath) || Directory.Exists(newPath))
                {
                    ShowLexDeskMessageBox(
                        "An item with that name already exists.",
                        "Rename Item",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);

                    return;
                }

                if (item.IsFolder)
                {
                    Directory.Move(item.Path, newPath);
                }
                else
                {
                    File.Move(item.Path, newPath);
                }

                RefreshLexDeskBubbleItems();
                UpdateSecurityStatus("Item renamed", false);
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro could not rename that item.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "LexDesk Folder",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

        private string CleanLexDeskFileName(string name)
        {
            try
            {
                name = (name ?? "").Trim();

                if (string.IsNullOrWhiteSpace(name))
                    return "";

                foreach (char c in Path.GetInvalidFileNameChars())
                {
                    name = name.Replace(c.ToString(), "");
                }

                return name.Trim();
            }
            catch
            {
                return "";
            }
        }

        private void LexDeskBubbleDeleteItem_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;

            try
            {
                var item = GetSelectedLexDeskBubbleItem();

                if (item == null)
                    return;

                if (!File.Exists(item.Path) && !Directory.Exists(item.Path))
                    return;

                var result = ShowLexDeskMessageBox(
                    "Move this item to the Recycle Bin?\n\n" + item.Name,
                    "Delete Item",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Question);

                if (result != MessageBoxResult.Yes)
                    return;

                if (item.IsFolder)
                {
                    Microsoft.VisualBasic.FileIO.FileSystem.DeleteDirectory(
                        item.Path,
                        Microsoft.VisualBasic.FileIO.UIOption.OnlyErrorDialogs,
                        Microsoft.VisualBasic.FileIO.RecycleOption.SendToRecycleBin);
                }
                else
                {
                    Microsoft.VisualBasic.FileIO.FileSystem.DeleteFile(
                        item.Path,
                        Microsoft.VisualBasic.FileIO.UIOption.OnlyErrorDialogs,
                        Microsoft.VisualBasic.FileIO.RecycleOption.SendToRecycleBin);
                }

                RefreshLexDeskBubbleItems();
                UpdateSecurityStatus("Item moved to Recycle Bin", false);
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro could not delete that item.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "LexDesk Folder",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

