        private void LexDeskToolActionButton_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;

            try
            {
                if (sender is not Button button)
                    return;

                if (button.Tag is not LexDeskToolAction action)
                    return;

                LaunchLexDeskToolTarget(action.Target);
            }
            catch { }
        }

        private async void LaunchLexDeskToolTarget(string target)
        {
            try
            {
                target = (target ?? "").Trim();

                if (string.IsNullOrWhiteSpace(target))
                    return;

                if (target.StartsWith(
                        "ms-settings:",
                        StringComparison.OrdinalIgnoreCase))
                {
                    bool opened =
                        await OpenLexDeskNativeWindowsSurfaceAsync(
                            target,
                            "Windows Settings");

                    if (opened)
                    {
                        UpdateSecurityStatus(
                            "Windows Settings opened over the LexDesk workspace",
                            false);
                    }

                    return;
                }

                Process.Start(new ProcessStartInfo(target)
                {
                    UseShellExecute = true
                });

                UpdateSecurityStatus("Windows tool opened", false);
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro could not open that Windows page.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "LexDesk Tools",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

