        // ============================================
        // LexDesk Pro - Screen & Text guided help
        // Grandma-safe wording first, Windows wording last
        // ============================================

        // Stage 15B-2: basic screen information.
        // This is read-only. It does not change Windows settings.

        private sealed class LexDeskScreenInfo
        {
            public int Width { get; init; }
            public int Height { get; init; }
            public int ScalePercent { get; init; }
            public int RefreshRate { get; init; }

            public string ResolutionText =>
                Width > 0 && Height > 0
                    ? $"{Width} × {Height}"
                    : "Could not read screen size";

            public string ScaleText =>
                ScalePercent > 0
                    ? $"{ScalePercent}%"
                    : "Could not read text/app size";

            public string RefreshText =>
                RefreshRate > 0 && RefreshRate < 1000
                    ? $"{RefreshRate} Hz"
                    : "Could not read refresh rate";
        }

        private const int LexDeskDeviceCapHorzRes = 8;
        private const int LexDeskDeviceCapVertRes = 10;
        private const int LexDeskDeviceCapLogPixelsX = 88;
        private const int LexDeskDeviceCapVRefresh = 116;

        [DllImport("user32.dll", EntryPoint = "GetDC")]
        private static extern IntPtr LexDeskGetDC(IntPtr hWnd);

        [DllImport("user32.dll", EntryPoint = "ReleaseDC")]
        private static extern int LexDeskReleaseDC(IntPtr hWnd, IntPtr hDC);

        [DllImport("gdi32.dll", EntryPoint = "GetDeviceCaps")]
        private static extern int LexDeskGetDeviceCaps(IntPtr hdc, int nIndex);

        private LexDeskScreenInfo GetLexDeskCurrentScreenInfo()
        {
            IntPtr hdc = IntPtr.Zero;

            try
            {
                hdc = LexDeskGetDC(IntPtr.Zero);

                if (hdc == IntPtr.Zero)
                    return new LexDeskScreenInfo { ScalePercent = 100 };

                int width = LexDeskGetDeviceCaps(hdc, LexDeskDeviceCapHorzRes);
                int height = LexDeskGetDeviceCaps(hdc, LexDeskDeviceCapVertRes);
                int dpiX = LexDeskGetDeviceCaps(hdc, LexDeskDeviceCapLogPixelsX);
                int refresh = LexDeskGetDeviceCaps(hdc, LexDeskDeviceCapVRefresh);

                int scalePercent = 100;

                if (dpiX > 0)
                    scalePercent = (int)Math.Round((dpiX / 96.0) * 100.0);

                return new LexDeskScreenInfo
                {
                    Width = width,
                    Height = height,
                    ScalePercent = scalePercent,
                    RefreshRate = refresh
                };
            }
            catch
            {
                return new LexDeskScreenInfo { ScalePercent = 100 };
            }
            finally
            {
                try
                {
                    if (hdc != IntPtr.Zero)
                        _ = LexDeskReleaseDC(IntPtr.Zero, hdc);
                }
                catch { }
            }
        }

        private void AddLexDeskScreenTextInfoCard()
