        private void ShowLexDeskScreenTextProblem(string problemKey)
        {
            try
            {
                if (LexDeskToolsDetailsBody == null)
                    return;

                LexDeskToolsDetailsBody.Children.Clear();

                string title = "Screen & Text";
                string intro = "";
                string guidance = "";

                var actions = new List<LexDeskToolAction>();

                switch (problemKey)
                {
                    case "too_small":
                        title = "Everything looks too small";
                        intro = "This usually means the words, buttons, or web pages are too hard to see.";
                        guidance =
                            "Best first step:\n" +
                            "Make the text bigger first. This is safer than changing the whole screen size.\n\n" +
                            "Next step:\n" +
                            "If buttons and windows are still too small, change the screen scale slowly.";

                        actions.Add(new LexDeskToolAction
                        {
                            Title = "Make Text Bigger",
                            Description = "Good first step",
                            Target = "ms-settings:easeofaccess-display"
                        });

                        actions.Add(new LexDeskToolAction
                        {
                            Title = "Change Screen Size",
                            Description = "Bigger buttons and windows",
                            Target = "ms-settings:display"
                        });
                        break;

                    case "too_big":
                        title = "Everything looks too big";
                        intro = "This usually means the screen scale is too high, so there is not enough room.";
                        guidance =
                            "Best first step:\n" +
                            "Use the screen size or scale option and move it down one step only.\n\n" +
                            "Safe rule:\n" +
                            "Do not pick random screen sizes. Use the one Windows marks as recommended.";

                        actions.Add(new LexDeskToolAction
                        {
                            Title = "Change Screen Size",
                            Description = "Fit more on screen",
                            Target = "ms-settings:display"
                        });

                        actions.Add(new LexDeskToolAction
                        {
                            Title = "Advanced Screen Info",
                            Description = "Refresh rate and monitor info",
                            Target = "ms-settings:advanced-display"
                        });
                        break;

                    case "blurry":
                        title = "Screen looks blurry";
                        intro = "This usually happens when the screen size is not set to the recommended option.";
                        guidance =
                            "Best first step:\n" +
                            "Open display settings and look for the option that says Recommended.\n\n" +
                            "Safe rule:\n" +
                            "Recommended is usually the clearest option for that monitor.";

                        actions.Add(new LexDeskToolAction
                        {
                            Title = "Use Recommended Screen Size",
                            Description = "Best for clear picture",
                            Target = "ms-settings:display"
                        });

                        actions.Add(new LexDeskToolAction
                        {
                            Title = "Advanced Display",
                            Description = "Monitor and refresh rate",
                            Target = "ms-settings:advanced-display"
                        });
                        break;

                    case "night":
                        title = "Screen is too bright at night";
                        intro = "This can make the screen feel harsh, especially at night.";
                        guidance =
                            "Best first step:\n" +
                            "Turn on Night Light. It makes the screen warmer and easier on your eyes.\n\n" +
                            "Tip:\n" +
                            "You can set it to turn on automatically in the evening.";

                        actions.Add(new LexDeskToolAction
                        {
                            Title = "Night Light",
                            Description = "Warmer screen at night",
                            Target = "ms-settings:nightlight"
                        });

                        actions.Add(new LexDeskToolAction
                        {
                            Title = "Brightness",
                            Description = "Screen brightness options",
                            Target = "ms-settings:display"
                        });
                        break;

                    case "safe":
                        title = "Use safest screen setup";
                        intro = "This helps avoid random screen settings that make things worse.";
                        guidance =
                            "Safest rule:\n" +
                            "Use the display size marked Recommended by Windows.\n\n" +
                            "For most people:\n" +
                            "Recommended screen size + slightly larger text is the safest setup.";

                        actions.Add(new LexDeskToolAction
                        {
                            Title = "Display Settings",
                            Description = "Choose Recommended",
                            Target = "ms-settings:display"
                        });

                        actions.Add(new LexDeskToolAction
                        {
                            Title = "Text Size",
                            Description = "Make words easier to read",
                            Target = "ms-settings:easeofaccess-display"
                        });
                        break;

                    default:
                        ShowLexDeskScreenTextStartPanel();
                        return;
                }

                if (LexDeskToolsDetailsTitleText != null)
                    LexDeskToolsDetailsTitleText.Text = title;

                if (LexDeskToolsDetailsIntroText != null)
                    LexDeskToolsDetailsIntroText.Text = intro;

                AddLexDeskScreenTextInfoCard();

                AddLexDeskScreenTextNote(guidance, true);

                foreach (var action in actions)
                {
                    LexDeskToolsDetailsBody.Children.Add(CreateLexDeskToolActionButton(action));
                }

                LexDeskToolsDetailsBody.Children.Add(CreateLexDeskScreenTextBackButton());
            }
            catch { }
        }

