        // ============================================================
        // LexDesk Pro - Move My Files Off OneDrive Safely
        // ============================================================
        //
        // Safety rules:
        // - Never delete the customer's cloud copy.
        // - Never unlink or uninstall OneDrive automatically.
        // - Never change known-folder locations before:
        //      1) the user confirms they can access OneDrive,
        //      2) cloud-only files have been resolved,
        //      3) an external backup has been copied and verified,
        //      4) the user has opened files from that backup,
        //      5) OneDrive folder backup has been stopped.
        // - Local restoration copies files first. It never deletes the source.
        // - Migration state is persisted so an interrupted operation can resume safely.

        private readonly string _lexDeskOneDriveMigrationStatePath =
            AppDataPath("OneDriveMigrationState.json");

        private LexDeskOneDriveMigrationState? _lexDeskOneDriveMigrationState;
        private TextBlock? _lexDeskOneDriveWizardStatusText;
        private Button? _lexDeskOneDriveBackupButton;
        private Button? _lexDeskOneDriveRestoreLocalFoldersButton;

        private const int LexDeskFileAttributeRecallOnOpen = 0x00040000;
        private const int LexDeskFileAttributeRecallOnDataAccess = 0x00400000;

        private static readonly Guid LexDeskKnownFolderDesktop =
            new Guid("B4BFCC3A-DB2C-424C-B029-7FE99A87C641");

        private static readonly Guid LexDeskKnownFolderDocuments =
            new Guid("FDD39AD0-238F-46AF-ADB4-6C85480369C7");

        private static readonly Guid LexDeskKnownFolderPictures =
            new Guid("33E28130-4E1E-4676-835A-98395C3BC3BB");

        [DllImport("shell32.dll", CharSet = CharSet.Unicode)]
        private static extern int SHSetKnownFolderPath(
            ref Guid rfid,
            uint dwFlags,
            IntPtr hToken,
            string pszPath);

        [DllImport("shell32.dll", CharSet = CharSet.Unicode)]
        private static extern int SHGetKnownFolderPath(
            ref Guid rfid,
            uint dwFlags,
            IntPtr hToken,
            out IntPtr ppszPath);

        [DllImport("shell32.dll")]
        private static extern void SHChangeNotify(
            uint wEventId,
            uint uFlags,
            IntPtr dwItem1,
            IntPtr dwItem2);

        private sealed class LexDeskOneDriveMigrationState
        {
            public int Version { get; set; } = 1;
            public bool SafetyScanComplete { get; set; }
            public bool OneDriveAccessConfirmed { get; set; }
            public bool CloudFilesLocalVerified { get; set; }
            public bool BackupVerified { get; set; }
            public bool HumanBackupCheckConfirmed { get; set; }
            public bool OneDriveFolderBackupStoppedConfirmed { get; set; }
            public bool LocalFoldersRestored { get; set; }
            public bool OneDriveUnlinkedConfirmed { get; set; }
            public bool FinalVerified { get; set; }
            public bool ManagedPolicyDetected { get; set; }

            public string OriginalDesktop { get; set; } = "";
            public string OriginalDocuments { get; set; } = "";
            public string OriginalPictures { get; set; } = "";

            public List<string> OneDriveRoots { get; set; } = new();
            public string BackupFolder { get; set; } = "";
            public long BackupFilesCopied { get; set; }
            public long BackupBytesCopied { get; set; }
            public int BackupFailures { get; set; }
            public string LastUpdatedUtc { get; set; } = "";
        }

