        private Border CreateLexDeskOneDriveStageCard(
            string stageNumber,
            string title,
            string description,
            string status,
            params object[] actions)
        {
            var border = new Border
            {
                Margin = new Thickness(6, 0, 6, 10),
                Padding = new Thickness(14),
                CornerRadius = new CornerRadius(12),
                BorderThickness = new Thickness(1.1)
            };

            border.SetResourceReference(Border.BackgroundProperty, "TopBarBg");
            border.SetResourceReference(Border.BorderBrushProperty, "CardBorder");

            var stack = new StackPanel();

            var heading = new TextBlock
            {
                Text = $"STEP {stageNumber}  •  {title}",
                FontSize = 14,
                FontWeight = FontWeights.SemiBold,
                Margin = new Thickness(0, 0, 0, 6)
            };
            heading.SetResourceReference(TextBlock.ForegroundProperty, "TextPrimary");

            var body = new TextBlock
            {
                Text = description,
                FontSize = 12,
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(0, 0, 0, 8)
            };
            body.SetResourceReference(TextBlock.ForegroundProperty, "TextSecondary");

            var statusText = new TextBlock
            {
                Text = status,
                FontSize = 12,
                FontWeight = FontWeights.SemiBold,
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(0, 0, 0, 8)
            };
            statusText.SetResourceReference(
                TextBlock.ForegroundProperty,
                "TextPrimary");

            var actionPanel = new WrapPanel
            {
                HorizontalAlignment = HorizontalAlignment.Left
            };

            foreach (object action in actions)
            {
                if (action is Button suppliedButton)
                {
                    actionPanel.Children.Add(suppliedButton);
                    continue;
                }
            }

            stack.Children.Add(heading);
            stack.Children.Add(body);
            stack.Children.Add(statusText);
            stack.Children.Add(actionPanel);
            border.Child = stack;
            return border;
        }

