        private static string GetLexDeskOneDriveStageStatus(
            bool complete,
            string completeText)
        {
            return complete
                ? "✓ " + completeText
                : "Not completed yet";
        }

        private LexDeskOneDriveMigrationState LoadLexDeskOneDriveMigrationState()
        {
            try
            {
                if (File.Exists(_lexDeskOneDriveMigrationStatePath))
                {
                    string json =
                        File.ReadAllText(_lexDeskOneDriveMigrationStatePath);

                    var state =
                        JsonSerializer.Deserialize<LexDeskOneDriveMigrationState>(
                            json,
                            JsonCaseInsensitiveOptions);

                    if (state != null)
                        return state;
                }
            }
            catch { }

            return new LexDeskOneDriveMigrationState();
        }

        private void SaveLexDeskOneDriveMigrationState()
        {
            try
            {
                _lexDeskOneDriveMigrationState ??=
                    new LexDeskOneDriveMigrationState();

                _lexDeskOneDriveMigrationState.LastUpdatedUtc =
                    DateTime.UtcNow.ToString("O");

                string? folder =
                    Path.GetDirectoryName(_lexDeskOneDriveMigrationStatePath);

                if (!string.IsNullOrWhiteSpace(folder))
                    Directory.CreateDirectory(folder);

                File.WriteAllText(
                    _lexDeskOneDriveMigrationStatePath,
                    JsonSerializer.Serialize(
                        _lexDeskOneDriveMigrationState,
                        new JsonSerializerOptions
                        {
                            WriteIndented = true
                        }));
            }
            catch { }
        }

        private void SetLexDeskOneDriveWizardStatus(
            string text,
            bool warning = false)
        {
            try
            {
                if (_lexDeskOneDriveWizardStatusText == null)
                    return;

                _lexDeskOneDriveWizardStatusText.Text = text;

                _lexDeskOneDriveWizardStatusText.SetResourceReference(
                    TextBlock.ForegroundProperty,
                    "TextSecondary");
            }
            catch
            {
                try
                {
                    if (_lexDeskOneDriveWizardStatusText != null)
                        _lexDeskOneDriveWizardStatusText.Text = text;
                }
                catch { }
            }
        }

        private void RefreshLexDeskOneDriveWizardButtonStates()
        {
            try
            {
                var state =
                    _lexDeskOneDriveMigrationState ??
                    new LexDeskOneDriveMigrationState();

                if (_lexDeskOneDriveBackupButton != null)
                {
                    _lexDeskOneDriveBackupButton.IsEnabled =
                        state.OneDriveAccessConfirmed &&
                        state.CloudFilesLocalVerified;
                }

                if (_lexDeskOneDriveRestoreLocalFoldersButton != null)
                {
                    _lexDeskOneDriveRestoreLocalFoldersButton.IsEnabled =
                        state.BackupVerified &&
                        state.HumanBackupCheckConfirmed &&
                        state.OneDriveFolderBackupStoppedConfirmed &&
                        !state.ManagedPolicyDetected;
                }
            }
            catch { }
        }

        private async void LexDeskOneDriveRunSafetyCheck_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            try
            {
                SetLexDeskOneDriveWizardStatus(
                    "Reading OneDrive and Windows folder locations. No changes are being made...");

                LexDeskOneDriveScanResult scan =
                    await Task.Run(GetLexDeskOneDriveSafetySnapshot);

                _lexDeskOneDriveMigrationState ??=
                    new LexDeskOneDriveMigrationState();

                _lexDeskOneDriveMigrationState.SafetyScanComplete = true;
                _lexDeskOneDriveMigrationState.ManagedPolicyDetected =
                    scan.ManagedPolicyDetected;

                _lexDeskOneDriveMigrationState.OriginalDesktop =
                    scan.DesktopPath;

                _lexDeskOneDriveMigrationState.OriginalDocuments =
                    scan.DocumentsPath;

                _lexDeskOneDriveMigrationState.OriginalPictures =
                    scan.PicturesPath;

                _lexDeskOneDriveMigrationState.OneDriveRoots =
                    scan.OneDriveRoots;

                SaveLexDeskOneDriveMigrationState();

                string rootsText =
                    scan.OneDriveRoots.Count == 0
                        ? "No OneDrive folder was detected."
                        : "Detected OneDrive folder(s):\n" +
                          string.Join(
                              "\n",
                              scan.OneDriveRoots.Select(
                                  path => "• " + path));

                string managedText =
                    scan.ManagedPolicyDetected
                        ? "\n\nThis PC appears to have organisation-managed OneDrive policy. " +
                          "LexDesk will allow backup checks but will not automatically change local folder mappings."
                        : "";

                ShowLexDeskMessageBox(
                    $"Desktop:\n{scan.DesktopPath}\n\n" +
                    $"Documents:\n{scan.DocumentsPath}\n\n" +
                    $"Pictures:\n{scan.PicturesPath}\n\n" +
                    rootsText +
                    managedText,
                    "OneDrive Safety Check",
                    MessageBoxButton.OK,
                    scan.ManagedPolicyDetected
                        ? MessageBoxImage.Warning
                        : MessageBoxImage.Information);

                SetLexDeskOneDriveWizardStatus(
                    scan.OneDriveRoots.Count == 0
                        ? "Safety check complete. No OneDrive folder was detected."
                        : "Safety check complete. Next, confirm that you can sign in to OneDrive and see your files.");

                ShowLexDeskOneDriveSafetyWizard();
            }
            catch (Exception ex)
            {
                SetLexDeskOneDriveWizardStatus(
                    "Safety check failed. Nothing was changed.",
                    true);

                ShowLexDeskMessageBox(
                    "LexDesk Pro could not complete the OneDrive safety check.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "OneDrive Safety",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
        }

        private LexDeskOneDriveScanResult GetLexDeskOneDriveSafetySnapshot()
        {
            var result = new LexDeskOneDriveScanResult
            {
                DesktopPath =
                    Environment.GetFolderPath(
                        Environment.SpecialFolder.DesktopDirectory),

                DocumentsPath =
                    Environment.GetFolderPath(
                        Environment.SpecialFolder.MyDocuments),

                PicturesPath =
                    Environment.GetFolderPath(
                        Environment.SpecialFolder.MyPictures),

                ManagedPolicyDetected =
                    HasLexDeskManagedOneDrivePolicy()
            };

            result.OneDriveRoots =
                GetLexDeskOneDriveRoots(
                    result.DesktopPath,
                    result.DocumentsPath,
                    result.PicturesPath);

            return result;
        }

        private List<string> GetLexDeskOneDriveRoots(
            params string[] extraPaths)
        {
            var roots =
                new HashSet<string>(
                    StringComparer.OrdinalIgnoreCase);

            void AddCandidate(
                string? candidate,
                bool requireExistingFolder = true)
            {
                try
                {
                    string normalized =
                        NormalizeLexDeskDirectoryPath(candidate);

                    if (string.IsNullOrWhiteSpace(normalized))
                        return;

                    if (!requireExistingFolder ||
                        Directory.Exists(normalized))
                    {
                        roots.Add(normalized);
                    }
                }
                catch { }
            }

            AddCandidate(
                Environment.GetEnvironmentVariable("OneDrive"));

            AddCandidate(
                Environment.GetEnvironmentVariable("OneDriveConsumer"));

            AddCandidate(
                Environment.GetEnvironmentVariable("OneDriveCommercial"));

            try
            {
                using RegistryKey? accounts =
                    Registry.CurrentUser.OpenSubKey(
                        @"Software\Microsoft\OneDrive\Accounts");

                if (accounts != null)
                {
                    foreach (string name in accounts.GetSubKeyNames())
                    {
                        try
                        {
                            using RegistryKey? account =
                                accounts.OpenSubKey(name);

                            AddCandidate(
                                account?.GetValue("UserFolder")?.ToString());
                        }
                        catch { }
                    }
                }
            }
            catch { }

            foreach (string path in extraPaths ?? Array.Empty<string>())
            {
                string derived =
                    TryDeriveLexDeskOneDriveRoot(path);

                AddCandidate(
                    derived,
                    requireExistingFolder: false);
            }

            return roots
                .OrderBy(path => path)
                .ToList();
        }

        private static string NormalizeLexDeskDirectoryPath(
            string? path)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(path))
                    return "";

                return Path
                    .GetFullPath(
                        Environment.ExpandEnvironmentVariables(
                            path.Trim()))
                    .TrimEnd(
                        Path.DirectorySeparatorChar,
                        Path.AltDirectorySeparatorChar);
            }
            catch
            {
                return "";
            }
        }

        private static string TryDeriveLexDeskOneDriveRoot(
            string? path)
        {
            try
            {
                string full =
                    NormalizeLexDeskDirectoryPath(path);

                if (string.IsNullOrWhiteSpace(full))
                    return "";

                string root =
                    Path.GetPathRoot(full) ?? "";

                string remainder =
                    full.Substring(root.Length);

                string[] parts =
                    remainder.Split(
                        new[]
                        {
                            Path.DirectorySeparatorChar,
                            Path.AltDirectorySeparatorChar
                        },
                        StringSplitOptions.RemoveEmptyEntries);

                for (int i = 0; i < parts.Length; i++)
                {
                    if (!parts[i].StartsWith(
                            "OneDrive",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    string combined = root;

                    for (int p = 0; p <= i; p++)
                        combined = Path.Combine(combined, parts[p]);

                    return NormalizeLexDeskDirectoryPath(combined);
                }
            }
            catch { }

            return "";
        }

        private bool HasLexDeskManagedOneDrivePolicy()
        {
            string[] policyNames =
            {
                "KFMSilentOptIn",
                "KFMSilentOptInWithNotification",
                "KFMBlockOptIn",
                "KFMBlockOptOut",
                "DisableFileSyncNGSC"
            };

            bool HasPolicyInHive(
                RegistryKey hive,
                string path)
            {
                try
                {
                    using RegistryKey? key =
                        hive.OpenSubKey(path);

                    if (key == null)
                        return false;

                    foreach (string name in policyNames)
                    {
                        if (key.GetValue(name) != null)
                            return true;
                    }
                }
                catch { }

                return false;
            }

            return
                HasPolicyInHive(
                    Registry.LocalMachine,
                    @"SOFTWARE\Policies\Microsoft\OneDrive") ||
                HasPolicyInHive(
                    Registry.CurrentUser,
                    @"SOFTWARE\Policies\Microsoft\OneDrive");
        }

        private void LexDeskOneDriveOpenFolder_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            try
            {
                var roots =
                    (_lexDeskOneDriveMigrationState?.OneDriveRoots?.Count ?? 0) > 0
                        ? _lexDeskOneDriveMigrationState!.OneDriveRoots
                        : GetLexDeskOneDriveRoots();

                string? root =
                    roots.FirstOrDefault(
                        Directory.Exists);

                if (string.IsNullOrWhiteSpace(root))
                {
                    ShowLexDeskMessageBox(
                        "LexDesk Pro could not find a local OneDrive folder yet.\n\n" +
                        "Open the OneDrive app or OneDrive on the web and confirm you can see your files before continuing.",
                        "OneDrive Safety",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                    return;
                }

                Process.Start(
                    new ProcessStartInfo(root)
                    {
                        UseShellExecute = true
                    });
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro could not open the OneDrive folder.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "OneDrive Safety",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

        private void LexDeskOneDriveOpenWeb_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            try
            {
                Process.Start(
                    new ProcessStartInfo(
                        "https://onedrive.live.com/")
                    {
                        UseShellExecute = true
                    });
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro could not open OneDrive on the web.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "OneDrive Safety",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

        private void LexDeskOneDriveConfirmAccess_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            if (_lexDeskOneDriveMigrationState?.SafetyScanComplete != true)
            {
                ShowLexDeskMessageBox(
                    "Run the Safety Check first.",
                    "OneDrive Safety",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            if ((_lexDeskOneDriveMigrationState.OneDriveRoots?.Count ?? 0) == 0)
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro did not detect a OneDrive folder or a Windows folder mapped into OneDrive.\n\n" +
                    "There is nothing to migrate with this guide right now.",
                    "OneDrive Safety",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            var answer =
                ShowLexDeskMessageBox(
                    "Only continue if BOTH statements are true:\n\n" +
                    "• You can sign in to OneDrive.\n" +
                    "• You can see the important files you expect to keep, including Desktop/Documents/Pictures if you used OneDrive backup.\n\n" +
                    "Can you see your files?",
                    "Confirm OneDrive Access",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Warning);

            if (answer != MessageBoxResult.Yes)
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro will not continue.\n\n" +
                    "Do not unlink, uninstall, delete, or change OneDrive folder locations until you regain access to your files.",
                    "OneDrive Safety Stop",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
                return;
            }

            _lexDeskOneDriveMigrationState.OneDriveAccessConfirmed = true;
            SaveLexDeskOneDriveMigrationState();

            SetLexDeskOneDriveWizardStatus(
                "OneDrive access confirmed. Next, scan for cloud-only files.");

            ShowLexDeskOneDriveSafetyWizard();
        }

        private async void LexDeskOneDriveScanCloudFiles_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            if (_lexDeskOneDriveMigrationState?.OneDriveAccessConfirmed != true)
            {
                ShowLexDeskMessageBox(
                    "First confirm that you can sign in to OneDrive and see your files.",
                    "OneDrive Safety",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
                return;
            }

            try
            {
                SetLexDeskOneDriveWizardStatus(
                    "Scanning OneDrive files. This may take a while on a large account...");

                var roots =
                    _lexDeskOneDriveMigrationState.OneDriveRoots ??
                    new List<string>();

                var missingRoots =
                    roots
                        .Where(path => !Directory.Exists(path))
                        .ToList();

                if (roots.Count == 0 ||
                    missingRoots.Count > 0)
                {
                    _lexDeskOneDriveMigrationState.CloudFilesLocalVerified = false;
                    SaveLexDeskOneDriveMigrationState();

                    string missingText =
                        missingRoots.Count == 0
                            ? "No OneDrive folder is available to scan."
                            : "LexDesk cannot currently access:\n" +
                              string.Join(
                                  "\n",
                                  missingRoots.Select(path => "• " + path));

                    ShowLexDeskMessageBox(
                        missingText +
                        "\n\nOpen/sign in to OneDrive until the local OneDrive folder is available, then run the safety check again. " +
                        "LexDesk will not continue while a required OneDrive folder is unavailable.",
                        "OneDrive Folder Not Available",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);
                    return;
                }

                LexDeskOneDriveScanResult result =
                    await Task.Run(
                        () => ScanLexDeskOneDriveRoots(
                            roots));

                if (result.UnreadableItemCount > 0)
                {
                    _lexDeskOneDriveMigrationState.CloudFilesLocalVerified = false;
                    SaveLexDeskOneDriveMigrationState();

                    ShowLexDeskMessageBox(
                        $"LexDesk Pro could not inspect {result.UnreadableItemCount} item(s).\n\n" +
                        "Because the safety check is incomplete, LexDesk will not allow the backup/migration stage yet.",
                        "OneDrive Scan Incomplete",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);
                }
                else if (result.CloudOnlyFileCount > 0)
                {
                    _lexDeskOneDriveMigrationState.CloudFilesLocalVerified = false;
                    SaveLexDeskOneDriveMigrationState();

                    ShowLexDeskMessageBox(
                        $"LexDesk Pro found {result.CloudOnlyFileCount:N0} file(s) that may still require OneDrive to download their content.\n\n" +
                        "Open your OneDrive folder, choose the folders/files you need, then use OneDrive's 'Always keep on this device' or download option.\n\n" +
                        "Wait until OneDrive finishes, then run this scan again.",
                        "Cloud-only Files Found",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);
                }
                else
                {
                    _lexDeskOneDriveMigrationState.CloudFilesLocalVerified = true;
                    SaveLexDeskOneDriveMigrationState();

                    ShowLexDeskMessageBox(
                        $"Scan complete.\n\n" +
                        $"Files checked: {result.TotalFileCount:N0}\n" +
                        $"Cloud-only files detected: 0\n\n" +
                        "LexDesk can now create the external safety backup.",
                        "OneDrive Files Are Local",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                }

                ShowLexDeskOneDriveSafetyWizard();
            }
            catch (Exception ex)
            {
                _lexDeskOneDriveMigrationState!.CloudFilesLocalVerified = false;
                SaveLexDeskOneDriveMigrationState();

                ShowLexDeskMessageBox(
                    "LexDesk Pro could not complete the cloud-file scan.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "OneDrive Safety",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
        }

        private LexDeskOneDriveScanResult ScanLexDeskOneDriveRoots(
            IEnumerable<string> roots)
        {
            var result = new LexDeskOneDriveScanResult();

            foreach (string root in roots
                         .Where(Directory.Exists)
                         .Distinct(StringComparer.OrdinalIgnoreCase))
            {
                result.OneDriveRoots.Add(root);

                var pending =
                    new Stack<string>();

                pending.Push(root);

                while (pending.Count > 0)
                {
                    string current =
                        pending.Pop();

                    string[] directories;

                    try
                    {
                        directories =
                            Directory.GetDirectories(current);
                    }
                    catch
                    {
                        result.UnreadableItemCount++;
                        continue;
                    }

                    foreach (string directory in directories)
                    {
                        try
                        {
                            FileAttributes attributes =
                                File.GetAttributes(directory);

                            if ((attributes & FileAttributes.ReparsePoint) != 0)
                                continue;

                            pending.Push(directory);
                        }
                        catch
                        {
                            result.UnreadableItemCount++;
                        }
                    }

                    string[] files;

                    try
                    {
                        files =
                            Directory.GetFiles(current);
                    }
                    catch
                    {
                        result.UnreadableItemCount++;
                        continue;
                    }

                    foreach (string file in files)
                    {
                        try
                        {
                            FileAttributes attributes =
                                File.GetAttributes(file);

                            bool cloudOnly =
                                (attributes & FileAttributes.Offline) != 0 ||
                                (((int)attributes &
                                  LexDeskFileAttributeRecallOnDataAccess) != 0);

                            if (cloudOnly)
                                result.CloudOnlyFileCount++;

                            var info =
                                new FileInfo(file);

                            result.TotalFileCount++;
                            result.TotalBytes +=
                                Math.Max(0, info.Length);
                        }
                        catch
                        {
                            result.UnreadableItemCount++;
                        }
                    }
                }
            }

            return result;
        }

        private async void LexDeskOneDriveCreateBackup_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            var state =
                _lexDeskOneDriveMigrationState;

            if (state == null ||
                !state.OneDriveAccessConfirmed ||
                !state.CloudFilesLocalVerified)
            {
                ShowLexDeskMessageBox(
                    "Before creating the backup, confirm OneDrive access and complete the cloud-only-file scan.",
                    "OneDrive Safety",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
                return;
            }

            string? selectedFolder =
                SelectLexDeskOneDriveBackupDestination();

            if (string.IsNullOrWhiteSpace(selectedFolder))
                return;

            string userProfile =
                Environment.GetFolderPath(
                    Environment.SpecialFolder.UserProfile);

            string selectedRoot =
                Path.GetPathRoot(
                    Path.GetFullPath(selectedFolder)) ?? "";

            string systemRoot =
                Path.GetPathRoot(
                    Path.GetFullPath(userProfile)) ?? "";

            if (string.Equals(
                    selectedRoot,
                    systemRoot,
                    StringComparison.OrdinalIgnoreCase))
            {
                ShowLexDeskMessageBox(
                    "Choose a different drive from the Windows system drive.\n\n" +
                    "The safety backup needs to be on a separate external drive so a PC or drive failure does not take both copies.",
                    "Choose an External Drive",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
                return;
            }

            var confirmExternal =
                ShowLexDeskMessageBox(
                    $"Selected location:\n{selectedFolder}\n\n" +
                    "Is this on a physically separate external drive that you can keep disconnected after the migration?",
                    "Confirm External Backup Drive",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Warning);

            if (confirmExternal != MessageBoxResult.Yes)
                return;

            string backupFolder =
                Path.Combine(
                    selectedFolder,
                    "LexDesk File Safety Backup - " +
                    DateTime.Now.ToString("yyyy-MM-dd HHmmss"));

            state.BackupFolder = backupFolder;
            state.BackupVerified = false;
            state.HumanBackupCheckConfirmed = false;
            state.BackupFilesCopied = 0;
            state.BackupBytesCopied = 0;
            state.BackupFailures = 0;

            SaveLexDeskOneDriveMigrationState();

            try
            {
                if (_lexDeskOneDriveBackupButton != null)
                    _lexDeskOneDriveBackupButton.IsEnabled = false;

                SetLexDeskOneDriveWizardStatus(
                    "Copying files to the external safety backup. Do not disconnect the drive...");

                var progress =
                    new Progress<string>(
                        message =>
                            SetLexDeskOneDriveWizardStatus(
                                message));

                LexDeskOneDriveBackupResult result =
                    await Task.Run(
                        () => CreateLexDeskOneDriveBackup(
                            backupFolder,
                            state,
                            progress));

                state.BackupFilesCopied =
                    result.FilesCopied;

                state.BackupBytesCopied =
                    result.BytesCopied;

                state.BackupFailures =
                    result.Failures;

                state.BackupVerified =
                    result.Failures == 0 &&
                    Directory.Exists(backupFolder);

                SaveLexDeskOneDriveMigrationState();

                if (!state.BackupVerified)
                {
                    string errorText =
                        result.Errors.Count == 0
                            ? "One or more files could not be copied or verified."
                            : string.Join(
                                "\n",
                                result.Errors.Take(6));

                    ShowLexDeskMessageBox(
                        $"Backup NOT verified.\n\n" +
                        $"Files copied: {result.FilesCopied:N0}\n" +
                        $"Failures: {result.Failures:N0}\n\n" +
                        errorText +
                        "\n\nLexDesk will not allow folder-location changes.",
                        "Backup Incomplete",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);
                }
                else
                {
                    ShowLexDeskMessageBox(
                        $"External backup verified.\n\n" +
                        $"Files copied: {result.FilesCopied:N0}\n" +
                        $"Data copied: {FormatLexDeskByteSize(result.BytesCopied)}\n\n" +
                        $"Backup folder:\n{backupFolder}\n\n" +
                        "Next, open this backup and manually open a few important documents and photos.",
                        "Backup Verified",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                }

                ShowLexDeskOneDriveSafetyWizard();
            }
            catch (Exception ex)
            {
                state.BackupVerified = false;
                SaveLexDeskOneDriveMigrationState();

                ShowLexDeskMessageBox(
                    "The backup did not complete safely.\n\n" +
                    SanitizeExceptionMessage(ex) +
                    "\n\nNothing has been unlinked or deleted.",
                    "Backup Stopped",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                if (_lexDeskOneDriveBackupButton != null)
                    _lexDeskOneDriveBackupButton.IsEnabled = true;
            }
        }

        private string? SelectLexDeskOneDriveBackupDestination()
        {
            try
            {
                Type? dialogType =
                    Type.GetType(
                        "Microsoft.Win32.OpenFolderDialog, PresentationFramework");

                if (dialogType != null)
                {
                    object? dialog =
                        Activator.CreateInstance(dialogType);

                    if (dialog != null)
                    {
                        dialogType
                            .GetProperty("Title")
                            ?.SetValue(
                                dialog,
                                "Choose your external backup drive or folder");

                        object? result =
                            dialogType
                                .GetMethod(
                                    "ShowDialog",
                                    Type.EmptyTypes)
                                ?.Invoke(
                                    dialog,
                                    null);

                        if (result is bool accepted &&
                            accepted)
                        {
                            string? folder =
                                dialogType
                                    .GetProperty("FolderName")
                                    ?.GetValue(dialog)
                                    ?.ToString();

                            if (!string.IsNullOrWhiteSpace(folder))
                                return folder;
                        }

                        return null;
                    }
                }
            }
            catch { }

            string fallback =
                Interaction.InputBox(
                    "Enter a folder on your external drive.\n\nExample: E:\\Backups",
                    "External Backup Location",
                    "E:\\");

            fallback =
                (fallback ?? "").Trim();

            if (string.IsNullOrWhiteSpace(fallback))
                return null;

            try
            {
                Directory.CreateDirectory(fallback);
                return Path.GetFullPath(fallback);
            }
            catch
            {
                ShowLexDeskMessageBox(
                    "That backup folder could not be opened.",
                    "External Backup",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
                return null;
            }
        }

        private LexDeskOneDriveBackupResult CreateLexDeskOneDriveBackup(
            string backupFolder,
            LexDeskOneDriveMigrationState state,
            IProgress<string>? progress)
        {
            var result =
                new LexDeskOneDriveBackupResult();

            Directory.CreateDirectory(backupFolder);

            var sources =
                GetLexDeskOneDriveBackupSources(
                    state);

            int sourceIndex = 0;

            foreach (var source in sources)
            {
                sourceIndex++;

                progress?.Report(
                    $"Backing up {source.Label} ({sourceIndex}/{sources.Count})...");

                string destination =
                    Path.Combine(
                        backupFolder,
                        source.DestinationRelativePath);

                CopyLexDeskOneDriveDirectoryForBackup(
                    source.SourcePath,
                    destination,
                    result,
                    progress);
            }

            WriteLexDeskOneDriveBackupReport(
                backupFolder,
                state,
                sources,
                result);

            return result;
        }

        private sealed class LexDeskOneDriveBackupSource
        {
            public string Label { get; set; } = "";
            public string SourcePath { get; set; } = "";
            public string DestinationRelativePath { get; set; } = "";
        }

        private List<LexDeskOneDriveBackupSource>
            GetLexDeskOneDriveBackupSources(
                LexDeskOneDriveMigrationState state)
        {
            var sources =
                new List<LexDeskOneDriveBackupSource>();

            string userProfile =
                Environment.GetFolderPath(
                    Environment.SpecialFolder.UserProfile);

            string[] profileFolders =
            {
                "Desktop",
                "Documents",
                "Downloads",
                "Favorites",
                "Links",
                "Music",
                "Pictures",
                "Saved Games",
                "Searches",
                "Videos"
            };

            foreach (string folderName in profileFolders)
            {
                string path =
                    Path.Combine(
                        userProfile,
                        folderName);

                if (!Directory.Exists(path))
                    continue;

                sources.Add(
                    new LexDeskOneDriveBackupSource
                    {
                        Label = "Local " + folderName,
                        SourcePath = path,
                        DestinationRelativePath =
                            Path.Combine(
                                "Local Profile",
                                folderName)
                    });
            }

            int oneDriveIndex = 0;

            foreach (string root in
                     (state.OneDriveRoots ??
                      new List<string>())
                     .Where(Directory.Exists)
                     .Distinct(StringComparer.OrdinalIgnoreCase))
            {
                oneDriveIndex++;

                string folderName =
                    Path.GetFileName(root);

                if (string.IsNullOrWhiteSpace(folderName))
                    folderName = "OneDrive";

                sources.Add(
                    new LexDeskOneDriveBackupSource
                    {
                        Label =
                            oneDriveIndex == 1
                                ? folderName
                                : folderName + $" ({oneDriveIndex})",

                        SourcePath = root,

                        DestinationRelativePath =
                            Path.Combine(
                                "OneDrive Copies",
                                oneDriveIndex.ToString("00") +
                                " - " +
                                SanitizeLexDeskBackupFolderName(
                                    folderName))
                    });
            }

            return sources;
        }

        private static string SanitizeLexDeskBackupFolderName(
            string name)
        {
            foreach (char invalid in
                     Path.GetInvalidFileNameChars())
            {
                name =
                    name.Replace(
                        invalid,
                        '_');
            }

            return string.IsNullOrWhiteSpace(name)
                ? "OneDrive"
                : name.Trim();
        }

        private void CopyLexDeskOneDriveDirectoryForBackup(
            string sourceRoot,
            string destinationRoot,
            LexDeskOneDriveBackupResult result,
            IProgress<string>? progress)
        {
            var pending =
                new Stack<(string Source, string Destination)>();

            pending.Push(
                (sourceRoot, destinationRoot));

            while (pending.Count > 0)
            {
                var item =
                    pending.Pop();

                try
                {
                    Directory.CreateDirectory(
                        item.Destination);
                }
                catch (Exception ex)
                {
                    result.Failures++;
                    AddLexDeskBackupError(
                        result,
                        item.Source,
                        ex);
                    continue;
                }

                string[] directories;

                try
                {
                    directories =
                        Directory.GetDirectories(
                            item.Source);
                }
                catch (Exception ex)
                {
                    result.Failures++;
                    AddLexDeskBackupError(
                        result,
                        item.Source,
                        ex);
                    directories =
                        Array.Empty<string>();
                }

                foreach (string directory in directories)
                {
                    try
                    {
                        FileAttributes attributes =
                            File.GetAttributes(directory);

                        if ((attributes &
                             FileAttributes.ReparsePoint) != 0)
                        {
                            continue;
                        }

                        pending.Push(
                            (
                                directory,
                                Path.Combine(
                                    item.Destination,
                                    Path.GetFileName(directory))
                            ));
                    }
                    catch (Exception ex)
                    {
                        result.Failures++;
                        AddLexDeskBackupError(
                            result,
                            directory,
                            ex);
                    }
                }

                string[] files;

                try
                {
                    files =
                        Directory.GetFiles(
                            item.Source);
                }
                catch (Exception ex)
                {
                    result.Failures++;
                    AddLexDeskBackupError(
                        result,
                        item.Source,
                        ex);
                    continue;
                }

                foreach (string file in files)
                {
                    try
                    {
                        FileAttributes attributes =
                            File.GetAttributes(file);

                        bool cloudOnly =
                            (attributes &
                             FileAttributes.Offline) != 0 ||
                            (((int)attributes &
                              LexDeskFileAttributeRecallOnDataAccess) != 0);

                        if (cloudOnly)
                        {
                            throw new IOException(
                                "File still appears to be cloud-only.");
                        }

                        string destination =
                            Path.Combine(
                                item.Destination,
                                Path.GetFileName(file));

                        File.Copy(
                            file,
                            destination,
                            overwrite: false);

                        var sourceInfo =
                            new FileInfo(file);

                        var destinationInfo =
                            new FileInfo(destination);

                        if (!destinationInfo.Exists ||
                            sourceInfo.Length !=
                            destinationInfo.Length)
                        {
                            throw new IOException(
                                "Copied file size did not match the source.");
                        }

                        result.FilesCopied++;
                        result.BytesCopied +=
                            Math.Max(
                                0,
                                sourceInfo.Length);

                        if (result.FilesCopied % 250 == 0)
                        {
                            progress?.Report(
                                $"Backup running... {result.FilesCopied:N0} files copied");
                        }
                    }
                    catch (Exception ex)
                    {
                        result.Failures++;
                        AddLexDeskBackupError(
                            result,
                            file,
                            ex);
                    }
                }
            }
        }

        private static void AddLexDeskBackupError(
            LexDeskOneDriveBackupResult result,
            string source,
            Exception ex)
        {
            if (result.Errors.Count >= 20)
                return;

            result.Errors.Add(
                $"{source}: {ex.Message}");
        }

        private void WriteLexDeskOneDriveBackupReport(
            string backupFolder,
            LexDeskOneDriveMigrationState state,
            IEnumerable<LexDeskOneDriveBackupSource> sources,
            LexDeskOneDriveBackupResult result)
        {
            try
            {
                var lines =
                    new List<string>
                    {
                        "LexDesk Pro - OneDrive Safety Backup Report",
                        "Created: " + DateTime.Now.ToString("F"),
                        "",
                        "IMPORTANT:",
                        "This backup report does not delete or alter the OneDrive cloud copy.",
                        "",
                        "Original Windows folder locations:",
                        "Desktop: " + state.OriginalDesktop,
                        "Documents: " + state.OriginalDocuments,
                        "Pictures: " + state.OriginalPictures,
                        "",
                        "Backup sources:"
                    };

                lines.AddRange(
                    sources.Select(
                        source =>
                            $"{source.Label}: {source.SourcePath}"));

                lines.Add("");
                lines.Add(
                    $"Files copied: {result.FilesCopied:N0}");

                lines.Add(
                    $"Bytes copied: {result.BytesCopied:N0}");

                lines.Add(
                    $"Copy/verification failures: {result.Failures:N0}");

                if (result.Errors.Count > 0)
                {
                    lines.Add("");
                    lines.Add("First reported problems:");
                    lines.AddRange(result.Errors);
                }

                File.WriteAllLines(
                    Path.Combine(
                        backupFolder,
                        "LexDesk Backup Report.txt"),
                    lines);
            }
            catch
            {
                result.Failures++;
            }
        }

        private static string FormatLexDeskByteSize(
            long bytes)
        {
            double value =
                Math.Max(
                    0,
                    bytes);

            string[] units =
            {
                "B",
                "KB",
                "MB",
                "GB",
                "TB"
            };

            int unit = 0;

            while (value >= 1024.0 &&
                   unit < units.Length - 1)
            {
                value /= 1024.0;
                unit++;
            }

            return $"{value:0.##} {units[unit]}";
        }

        private void LexDeskOneDriveOpenBackup_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            string folder =
                _lexDeskOneDriveMigrationState?.BackupFolder ??
                "";

            if (string.IsNullOrWhiteSpace(folder) ||
                !Directory.Exists(folder))
            {
                ShowLexDeskMessageBox(
                    "No verified backup folder is available yet.",
                    "OneDrive Safety",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            try
            {
                Process.Start(
                    new ProcessStartInfo(folder)
                    {
                        UseShellExecute = true
                    });
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro could not open the backup folder.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "OneDrive Safety",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
        }

        private void LexDeskOneDriveConfirmBackup_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            var state =
                _lexDeskOneDriveMigrationState;

            if (state?.BackupVerified != true ||
                string.IsNullOrWhiteSpace(state.BackupFolder) ||
                !Directory.Exists(state.BackupFolder))
            {
                ShowLexDeskMessageBox(
                    "Create and verify the external backup first.",
                    "OneDrive Safety",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
                return;
            }

            var answer =
                ShowLexDeskMessageBox(
                    "Have you opened the EXTERNAL backup folder and successfully opened several important files from it?\n\n" +
                    "Do not press Yes if you only looked at filenames.",
                    "Confirm Backup Files",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Warning);

            if (answer != MessageBoxResult.Yes)
                return;

            state.HumanBackupCheckConfirmed = true;
            SaveLexDeskOneDriveMigrationState();

            ShowLexDeskOneDriveSafetyWizard();
        }

        private void LexDeskOneDriveOpenClient_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            string[] candidates =
            {
                Path.Combine(
                    Environment.GetFolderPath(
                        Environment.SpecialFolder.LocalApplicationData),
                    "Microsoft",
                    "OneDrive",
                    "OneDrive.exe"),

                Path.Combine(
                    Environment.GetFolderPath(
                        Environment.SpecialFolder.ProgramFiles),
                    "Microsoft OneDrive",
                    "OneDrive.exe"),

                Path.Combine(
                    Environment.GetFolderPath(
                        Environment.SpecialFolder.ProgramFilesX86),
                    "Microsoft OneDrive",
                    "OneDrive.exe")
            };

            string? oneDriveExe =
                candidates
                    .FirstOrDefault(
                        File.Exists);

            if (string.IsNullOrWhiteSpace(oneDriveExe))
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro could not find the OneDrive desktop app.\n\n" +
                    "Use the OneDrive icon near the Windows clock if it is available, or open OneDrive on the web.",
                    "OneDrive",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            try
            {
                Process.Start(
                    new ProcessStartInfo(oneDriveExe)
                    {
                        UseShellExecute = true,
                        WorkingDirectory =
                            Path.GetDirectoryName(oneDriveExe) ?? ""
                    });
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro could not open OneDrive.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "OneDrive",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
        }

