        private async void LexDeskOneDriveRestoreLocalFolders_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            var state =
                _lexDeskOneDriveMigrationState;

            if (state == null ||
                !state.BackupVerified ||
                !state.HumanBackupCheckConfirmed ||
                !state.OneDriveFolderBackupStoppedConfirmed)
            {
                ShowLexDeskMessageBox(
                    "The backup safety gates are not complete yet.",
                    "OneDrive Safety",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
                return;
            }

            if (state.ManagedPolicyDetected)
            {
                ShowLexDeskMessageBox(
                    "This PC appears to have organisation-managed OneDrive folder policy.\n\n" +
                    "LexDesk Pro will not override managed folder locations. Keep the verified backup and contact the organisation's administrator.",
                    "Managed OneDrive Policy Detected",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
                return;
            }

            var answer =
                ShowLexDeskMessageBox(
                    "LexDesk Pro is ready to restore Desktop, Documents and Pictures to the normal local folders on this PC.\n\n" +
                    "Before changing each Windows folder location, LexDesk COPIES the current files into the local folder. " +
                    "It does not delete anything from OneDrive.\n\n" +
                    "Continue?",
                    "Restore Local Folders",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Warning);

            if (answer != MessageBoxResult.Yes)
                return;

            try
            {
                if (_lexDeskOneDriveRestoreLocalFoldersButton != null)
                    _lexDeskOneDriveRestoreLocalFoldersButton.IsEnabled = false;

                SetLexDeskOneDriveWizardStatus(
                    "Copying files into local Desktop, Documents and Pictures before changing Windows folder locations...");

                bool restored =
                    await Task.Run(
                        () => RestoreLexDeskOneDriveLocalKnownFolders(
                            state));

                state.LocalFoldersRestored =
                    restored;

                SaveLexDeskOneDriveMigrationState();

                if (!restored)
                {
                    ShowLexDeskMessageBox(
                        "LexDesk Pro could not verify all three local folder locations.\n\n" +
                        "Nothing was deleted. Keep OneDrive connected and keep the external backup until this is resolved.",
                        "Local Folder Restore Needs Attention",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);
                }
                else
                {
                    ShowLexDeskMessageBox(
                        "Desktop, Documents and Pictures are now using local folders on this PC.\n\n" +
                        "Your OneDrive source files and external backup were not deleted.\n\n" +
                        "Next, verify your files look correct, then unlink this PC from OneDrive.",
                        "Local Folders Restored",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                }

                ShowLexDeskOneDriveSafetyWizard();
            }
            catch (Exception ex)
            {
                state.LocalFoldersRestored = false;
                SaveLexDeskOneDriveMigrationState();

                ShowLexDeskMessageBox(
                    "LexDesk Pro stopped before it could verify the local folder restore.\n\n" +
                    SanitizeExceptionMessage(ex) +
                    "\n\nNothing was deleted from OneDrive or the external backup.",
                    "OneDrive Safety",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                if (_lexDeskOneDriveRestoreLocalFoldersButton != null)
                    _lexDeskOneDriveRestoreLocalFoldersButton.IsEnabled = true;
            }
        }

        private bool RestoreLexDeskOneDriveLocalKnownFolders(
            LexDeskOneDriveMigrationState state)
        {
            string userProfile =
                Environment.GetFolderPath(
                    Environment.SpecialFolder.UserProfile);

            var entries =
                new[]
                {
                    new
                    {
                        Name = "Desktop",
                        Id = LexDeskKnownFolderDesktop,
                        Original = state.OriginalDesktop,
                        Target = Path.Combine(
                            userProfile,
                            "Desktop")
                    },
                    new
                    {
                        Name = "Documents",
                        Id = LexDeskKnownFolderDocuments,
                        Original = state.OriginalDocuments,
                        Target = Path.Combine(
                            userProfile,
                            "Documents")
                    },
                    new
                    {
                        Name = "Pictures",
                        Id = LexDeskKnownFolderPictures,
                        Original = state.OriginalPictures,
                        Target = Path.Combine(
                            userProfile,
                            "Pictures")
                    }
                };

            foreach (var entry in entries)
            {
                Directory.CreateDirectory(
                    entry.Target);

                string source =
                    NormalizeLexDeskDirectoryPath(
                        entry.Original);

                string target =
                    NormalizeLexDeskDirectoryPath(
                        entry.Target);

                if (!string.IsNullOrWhiteSpace(source) &&
                    Directory.Exists(source) &&
                    !string.Equals(
                        source,
                        target,
                        StringComparison.OrdinalIgnoreCase))
                {
                    CopyLexDeskOneDriveDirectoryIntoLocalFolder(
                        source,
                        target);
                }

                Guid id =
                    entry.Id;

                int hr =
                    SHSetKnownFolderPath(
                        ref id,
                        0,
                        IntPtr.Zero,
                        target);

                if (hr != 0)
                    return false;
            }

            try
            {
                SHChangeNotify(
                    0x08000000,
                    0,
                    IntPtr.Zero,
                    IntPtr.Zero);
            }
            catch { }

            foreach (var entry in entries)
            {
                string actual =
                    GetLexDeskKnownFolderPath(
                        entry.Id);

                string expected =
                    NormalizeLexDeskDirectoryPath(
                        entry.Target);

                if (string.IsNullOrWhiteSpace(actual) ||
                    !string.Equals(
                        actual,
                        expected,
                        StringComparison.OrdinalIgnoreCase))
                {
                    return false;
                }

                if (IsLexDeskPathUnderAnyOneDriveRoot(
                        actual,
                        state.OneDriveRoots))
                {
                    return false;
                }
            }

            return true;
        }

        private static string GetLexDeskKnownFolderPath(
            Guid id)
        {
            IntPtr pointer =
                IntPtr.Zero;

            try
            {
                int hr =
                    SHGetKnownFolderPath(
                        ref id,
                        0,
                        IntPtr.Zero,
                        out pointer);

                if (hr != 0 ||
                    pointer == IntPtr.Zero)
                {
                    return "";
                }

                return NormalizeLexDeskDirectoryPath(
                    Marshal.PtrToStringUni(pointer));
            }
            finally
            {
                if (pointer != IntPtr.Zero)
                    Marshal.FreeCoTaskMem(pointer);
            }
        }

        private void CopyLexDeskOneDriveDirectoryIntoLocalFolder(
            string sourceRoot,
            string destinationRoot)
        {
            var pending =
                new Stack<(string Source, string Destination)>();

            pending.Push(
                (sourceRoot, destinationRoot));

            while (pending.Count > 0)
            {
                var item =
                    pending.Pop();

                Directory.CreateDirectory(
                    item.Destination);

                foreach (string directory in
                         Directory.GetDirectories(
                             item.Source))
                {
                    FileAttributes attributes =
                        File.GetAttributes(directory);

                    if ((attributes &
                         FileAttributes.ReparsePoint) != 0)
                    {
                        continue;
                    }

                    pending.Push(
                        (
                            directory,
                            Path.Combine(
                                item.Destination,
                                Path.GetFileName(directory))
                        ));
                }

                foreach (string file in
                         Directory.GetFiles(
                             item.Source))
                {
                    FileAttributes attributes =
                        File.GetAttributes(file);

                    bool cloudOnly =
                        (attributes &
                         FileAttributes.Offline) != 0 ||
                        (((int)attributes &
                          LexDeskFileAttributeRecallOnDataAccess) != 0);

                    if (cloudOnly)
                    {
                        throw new IOException(
                            "A cloud-only file was found while restoring local folders. LexDesk stopped without deleting anything.");
                    }

                    string destination =
                        Path.Combine(
                            item.Destination,
                            Path.GetFileName(file));

                    destination =
                        GetLexDeskNonDestructiveDestinationPath(
                            file,
                            destination);

                    if (string.IsNullOrWhiteSpace(destination))
                        continue;

                    File.Copy(
                        file,
                        destination,
                        overwrite: false);
                }
            }
        }

        private static string GetLexDeskNonDestructiveDestinationPath(
            string source,
            string requestedDestination)
        {
            if (!File.Exists(requestedDestination))
                return requestedDestination;

            try
            {
                var sourceInfo =
                    new FileInfo(source);

                var destinationInfo =
                    new FileInfo(requestedDestination);

                if (sourceInfo.Length ==
                    destinationInfo.Length)
                {
                    return "";
                }
            }
            catch { }

            string directory =
                Path.GetDirectoryName(
                    requestedDestination) ?? "";

            string name =
                Path.GetFileNameWithoutExtension(
                    requestedDestination);

            string extension =
                Path.GetExtension(
                    requestedDestination);

            for (int i = 1; i <= 9999; i++)
            {
                string candidate =
                    Path.Combine(
                        directory,
                        $"{name} (OneDrive copy {i}){extension}");

                if (!File.Exists(candidate))
                    return candidate;
            }

            throw new IOException(
                "LexDesk could not create a non-destructive copy name.");
        }

        private static bool IsLexDeskPathUnderAnyOneDriveRoot(
            string path,
            IEnumerable<string>? roots)
        {
            string normalizedPath =
                NormalizeLexDeskDirectoryPath(path);

            if (string.IsNullOrWhiteSpace(normalizedPath))
                return false;

            foreach (string root in
                     roots ??
                     Array.Empty<string>())
            {
                string normalizedRoot =
                    NormalizeLexDeskDirectoryPath(root);

                if (string.IsNullOrWhiteSpace(normalizedRoot))
                    continue;

                if (string.Equals(
                        normalizedPath,
                        normalizedRoot,
                        StringComparison.OrdinalIgnoreCase) ||
                    normalizedPath.StartsWith(
                        normalizedRoot +
                        Path.DirectorySeparatorChar,
                        StringComparison.OrdinalIgnoreCase))
                {
                    return true;
                }
            }

            return false;
        }

