        private void LexDeskOneDriveFinalVerification_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            var state =
                _lexDeskOneDriveMigrationState;

            if (state == null ||
                !state.BackupVerified ||
                !state.HumanBackupCheckConfirmed ||
                !state.LocalFoldersRestored ||
                !state.OneDriveUnlinkedConfirmed)
            {
                ShowLexDeskMessageBox(
                    "The required safety stages are not complete yet.\n\n" +
                    "LexDesk will not mark the migration complete until the external backup, local folders and OneDrive unlink are all confirmed.",
                    "OneDrive Safety",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
                return;
            }

            bool backupExists =
                !string.IsNullOrWhiteSpace(
                    state.BackupFolder) &&
                Directory.Exists(
                    state.BackupFolder);

            string desktop =
                GetLexDeskKnownFolderPath(
                    LexDeskKnownFolderDesktop);

            string documents =
                GetLexDeskKnownFolderPath(
                    LexDeskKnownFolderDocuments);

            string pictures =
                GetLexDeskKnownFolderPath(
                    LexDeskKnownFolderPictures);

            bool foldersLocal =
                !IsLexDeskPathUnderAnyOneDriveRoot(
                    desktop,
                    state.OneDriveRoots) &&
                !IsLexDeskPathUnderAnyOneDriveRoot(
                    documents,
                    state.OneDriveRoots) &&
                !IsLexDeskPathUnderAnyOneDriveRoot(
                    pictures,
                    state.OneDriveRoots);

            state.FinalVerified =
                backupExists &&
                foldersLocal;

            SaveLexDeskOneDriveMigrationState();

            if (!state.FinalVerified)
            {
                ShowLexDeskMessageBox(
                    "Final verification is NOT complete.\n\n" +
                    $"External backup present: {(backupExists ? "Yes" : "No")}\n" +
                    $"Desktop/Documents/Pictures local: {(foldersLocal ? "Yes" : "No")}\n\n" +
                    "Keep OneDrive data and the external backup unchanged until this is resolved.",
                    "OneDrive Safety",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            else
            {
                ShowLexDeskMessageBox(
                    "Migration verified.\n\n" +
                    "✓ External backup is still present.\n" +
                    "✓ Desktop is local.\n" +
                    "✓ Documents are local.\n" +
                    "✓ Pictures are local.\n" +
                    "✓ You confirmed this PC is unlinked from OneDrive.\n\n" +
                    "LexDesk Pro has NOT deleted your OneDrive cloud copy. Keep the external backup until you are completely satisfied with the local setup.",
                    "OneDrive Migration Complete",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }

            ShowLexDeskOneDriveSafetyWizard();
        }

