        private void LexDeskAppsSearchBox_TextChanged(object sender, TextChangedEventArgs e)
        {
            try
            {
                ApplyLexDeskAppsSearchFilter();
            }
            catch
            {
                // Search must never break the Apps panel.
            }
        }

        private void ApplyLexDeskAppsSearchFilter()
        {
            if (_lexDeskAllApps == null)
                _lexDeskAllApps = new List<LexDeskInstalledApp>();

            string query = LexDeskAppsSearchBox?.Text?.Trim() ?? "";

            var sourceApps = GetLexDeskVisibleApps(_lexDeskAllApps);

            if (string.IsNullOrWhiteSpace(query))
            {
                PopulateLexDeskAppsList(sourceApps);
                return;
            }

            var filtered = sourceApps
                .Where(app =>
                    !string.IsNullOrWhiteSpace(app.Name) &&
                    app.Name.IndexOf(query, StringComparison.OrdinalIgnoreCase) >= 0)
                .OrderByDescending(app =>
                    app.Name.StartsWith(query, StringComparison.OrdinalIgnoreCase))
                .ThenBy(app => app.Name, StringComparer.OrdinalIgnoreCase)
                .ToList();

            PopulateLexDeskAppsList(filtered);
        }

