        private void ShowLexDeskAppsMessage(string message)
        {
            try
            {
                if (LexDeskAppsListPanel == null)
                    return;

                if (LexDeskAppsSection != null)
                    LexDeskAppsSection.Visibility = Visibility.Visible;

                if (LexDeskHiddenAppsPanel != null)
                    LexDeskHiddenAppsPanel.Children.Clear();

                if (LexDeskHiddenAppsSection != null)
                    LexDeskHiddenAppsSection.Visibility = Visibility.Collapsed;

                LexDeskAppsListPanel.Children.Clear();

                LexDeskAppsListPanel.Children.Add(new TextBlock
                {
                    Text = message,
                    Foreground = TryFindResource("TextSecondary") as Brush ?? Brushes.Gray,
                    FontSize = 13,
                    Margin = new Thickness(8),
                    HorizontalAlignment = HorizontalAlignment.Center,
                    TextAlignment = TextAlignment.Center
                });
            }
            catch { }
        }

        private void PopulateLexDeskAppsList(List<LexDeskInstalledApp> apps)
        {
            try
            {
                if (LexDeskAppsListPanel == null)
                    return;

                LexDeskAppsListPanel.Children.Clear();

                if (LexDeskHiddenAppsPanel != null)
                {
                    LexDeskHiddenAppsPanel.Children.Clear();
                    _lexDeskHiddenAppsPanelDirty = true;
                }

                var safeApps = apps ?? new List<LexDeskInstalledApp>();

                var normalApps = safeApps
                    .Where(app =>
                        app != null &&
                        !string.IsNullOrWhiteSpace(app.Name) &&
                        !IsLexDeskAppHidden(app.Name))
                    .OrderBy(app => app.Name, StringComparer.OrdinalIgnoreCase)
                    .ToList();

                var hiddenApps = safeApps
                    .Where(app =>
                        app != null &&
                        !string.IsNullOrWhiteSpace(app.Name) &&
                        IsLexDeskAppHidden(app.Name))
                    .OrderBy(app => app.Name, StringComparer.OrdinalIgnoreCase)
                    .ToList();

                bool showingHidden = _lexDeskShowHiddenApps && hiddenApps.Count > 0;

                if (normalApps.Count == 0 && !showingHidden)
                {
                    if (LexDeskAppsSection != null)
                        LexDeskAppsSection.Visibility = Visibility.Visible;

                    if (LexDeskHiddenAppsSection != null)
                        LexDeskHiddenAppsSection.Visibility = Visibility.Collapsed;

                    ShowLexDeskAppsMessage("No matching apps found.");
                    return;
                }

                if (LexDeskAppsSection != null)
                    LexDeskAppsSection.Visibility = normalApps.Count > 0
                        ? Visibility.Visible
                        : Visibility.Collapsed;

                foreach (var app in normalApps)
                {
                    LexDeskAppsListPanel.Children.Add(CreateLexDeskAppButton(app, 190, 50));
                }

                if (LexDeskHiddenAppsSection != null)
                    LexDeskHiddenAppsSection.Visibility = showingHidden
                        ? Visibility.Visible
                        : Visibility.Collapsed;

                if (showingHidden && LexDeskHiddenAppsPanel != null)
                {
                    foreach (var app in hiddenApps)
                    {
                        LexDeskHiddenAppsPanel.Children.Add(
                            CreateLexDeskAppButton(app, 190, 50));
                    }

                    _lexDeskHiddenAppsPanelDirty = false;
                }
            }
            catch
            {
                ShowLexDeskAppsMessage("Could not display apps.");
            }
        }

