        private bool IsLexDeskAppPinned(string? appName)
        {
            if (string.IsNullOrWhiteSpace(appName))
                return false;

            return _lexDeskPinnedAppNames.Any(name =>
                string.Equals(
                    name,
                    appName.Trim(),
                    StringComparison.OrdinalIgnoreCase));
        }

        private void LoadLexDeskPinnedApps()
        {
            try
            {
                _lexDeskPinnedAppNames.Clear();

                string path = AppDataPath(LexDeskPinnedAppsFileName);

                if (!File.Exists(path))
                    return;

                string json = File.ReadAllText(path);

                var saved =
                    JsonSerializer.Deserialize<List<string>>(json);

                if (saved == null)
                    return;

                foreach (string savedName in saved)
                {
                    string name = (savedName ?? "").Trim();

                    if (string.IsNullOrWhiteSpace(name))
                        continue;

                    if (IsLexDeskAppPinned(name))
                        continue;

                    if (_lexDeskPinnedAppNames.Count >=
                        LexDeskMaxPinnedApps)
                    {
                        break;
                    }

                    _lexDeskPinnedAppNames.Add(name);
                }
            }
            catch
            {
                _lexDeskPinnedAppNames.Clear();
            }
        }

        private void SaveLexDeskPinnedApps()
        {
            try
            {
                string path = AppDataPath(
                    LexDeskPinnedAppsFileName);

                Directory.CreateDirectory(
                    Path.GetDirectoryName(path)!);

                string json = JsonSerializer.Serialize(
                    _lexDeskPinnedAppNames,
                    JsonIndentedOptions);

                File.WriteAllText(path, json);
            }
            catch
            {
                // Pinning is convenience only.
                // Never let a save error affect LexDesk.
            }
        }

        private async Task LoadLexDeskPinnedAppsDockAsync()
        {
            try
            {
                LoadLexDeskPinnedApps();

                if (_lexDeskPinnedAppNames.Count == 0)
                {
                    RefreshLexDeskPinnedAppsDock();
                    return;
                }

                var apps =
                    await GetLexDeskInstalledAppsCachedAsync(false);

                if (apps != null && apps.Count > 0)
                    _lexDeskAllApps = apps;

                RefreshLexDeskPinnedAppsDock();
            }
            catch
            {
                // Pinned apps must never affect startup.
            }
        }

        private void RefreshLexDeskPinnedAppsDock()
        {
            try
            {
                if (LexDeskPinnedAppsPanel == null)
                    return;

                LexDeskPinnedAppsPanel.Children.Clear();

                foreach (string pinnedName in
                         _lexDeskPinnedAppNames)
                {
                    var app = _lexDeskAllApps.FirstOrDefault(a =>
                        a != null &&
                        string.Equals(
                            a.Name,
                            pinnedName,
                            StringComparison.OrdinalIgnoreCase));

                    if (app == null)
                        continue;

                    LexDeskPinnedAppsPanel.Children.Add(
                        CreateLexDeskPinnedAppButton(app));
                }
            }
            catch
            {
                // Cosmetic taskbar failure only.
            }
        }

        private ImageSource? TryGetLexDeskPinnedAppIcon(
    LexDeskInstalledApp app)
        {
            try
            {
                if (app == null)
                    return null;

                string cacheKey =
                    !string.IsNullOrWhiteSpace(app.ShortcutPath)
                        ? app.ShortcutPath
                        : !string.IsNullOrWhiteSpace(app.Target)
                            ? app.Target
                            : !string.IsNullOrWhiteSpace(app.Aumid)
                                ? app.Aumid
                                : app.Name;

                if (!string.IsNullOrWhiteSpace(cacheKey) &&
                    _lexDeskAppIconCache.TryGetValue(
                        cacheKey,
                        out ImageSource? cachedIcon))
                {
                    return cachedIcon;
                }

                // ============================================================
                // 1. Normal shortcut / EXE icon
                // ============================================================

                string iconPath = "";

                if (!string.IsNullOrWhiteSpace(app.ShortcutPath) &&
                    File.Exists(app.ShortcutPath))
                {
                    iconPath = app.ShortcutPath;
                }
                else if (!string.IsNullOrWhiteSpace(app.Target) &&
                         File.Exists(app.Target))
                {
                    iconPath = app.Target;
                }

                if (!string.IsNullOrWhiteSpace(iconPath))
                {
                    var info =
                        new LexDeskShellFileInfo();

                    IntPtr result =
                        SHGetFileInfo(
                            iconPath,
                            0,
                            ref info,
                            (uint)Marshal.SizeOf<LexDeskShellFileInfo>(),
                            LexDeskShgfiIcon |
                            LexDeskShgfiSmallIcon);

                    if (result != IntPtr.Zero &&
                        info.hIcon != IntPtr.Zero)
                    {
                        try
                        {
                            BitmapSource source =
                                Imaging.CreateBitmapSourceFromHIcon(
                                    info.hIcon,
                                    Int32Rect.Empty,
                                    BitmapSizeOptions.FromWidthAndHeight(
                                        20,
                                        20));

                            source.Freeze();

                            if (!string.IsNullOrWhiteSpace(cacheKey))
                                _lexDeskAppIconCache[cacheKey] = source;

                            return source;
                        }
                        finally
                        {
                            DestroyIcon(info.hIcon);
                        }
                    }
                }

                // ============================================================
                // 2. AppsFolder / AUMID icon
                // ============================================================

                string aumid =
                    !string.IsNullOrWhiteSpace(app.Aumid)
                        ? app.Aumid.Trim()
                        : "";

                if (!string.IsNullOrWhiteSpace(aumid))
                {
                    ILexDeskShellItemImageFactory? imageFactory = null;

                    try
                    {
                        string parsingName =
                            aumid.StartsWith(
                                "shell:AppsFolder\\",
                                StringComparison.OrdinalIgnoreCase)
                                ? aumid
                                : "shell:AppsFolder\\" + aumid;

                        Guid iid =
                            typeof(ILexDeskShellItemImageFactory).GUID;

                        int hr =
                            SHCreateItemFromParsingName(
                                parsingName,
                                IntPtr.Zero,
                                ref iid,
                                out imageFactory);

                        if (hr >= 0 &&
                            imageFactory != null)
                        {
                            var size =
                                new LexDeskShellImageSize
                                {
                                    cx = 32,
                                    cy = 32
                                };

                            IntPtr hBitmap = IntPtr.Zero;

                            try
                            {
                                hr =
                                    imageFactory.GetImage(
                                        size,
                                        LexDeskSiigbfBiggerSizeOk |
                                        LexDeskSiigbfIconOnly,
                                        out hBitmap);

                                if (hr >= 0 &&
                                    hBitmap != IntPtr.Zero)
                                {
                                    BitmapSource source =
                                        Imaging.CreateBitmapSourceFromHBitmap(
                                            hBitmap,
                                            IntPtr.Zero,
                                            Int32Rect.Empty,
                                            BitmapSizeOptions.FromWidthAndHeight(
                                                20,
                                                20));

                                    source.Freeze();

                                    if (!string.IsNullOrWhiteSpace(cacheKey))
                                        _lexDeskAppIconCache[cacheKey] = source;

                                    return source;
                                }
                            }
                            finally
                            {
                                if (hBitmap != IntPtr.Zero)
                                    DeleteObject(hBitmap);
                            }
                        }
                    }
                    catch
                    {
                        // One stubborn AppsFolder icon must never affect Apps.
                    }
                    finally
                    {
                        try
                        {
                            if (imageFactory != null &&
                                Marshal.IsComObject(imageFactory))
                            {
                                Marshal.FinalReleaseComObject(
                                    imageFactory);
                            }
                        }
                        catch { }
                    }
                }

                // ============================================================
                // 3. No icon found - remember the miss
                // ============================================================

                if (!string.IsNullOrWhiteSpace(cacheKey))
                    _lexDeskAppIconCache[cacheKey] = null;

                return null;
            }
            catch
            {
                return null;
            }
        }

        private Button CreateLexDeskPinnedAppButton(
            LexDeskInstalledApp app)
        {
            var button = new Button
            {
                Width = 34,
                Height = 34,
                Margin = new Thickness(2, -3, 2, 0),
                Padding = new Thickness(0),
                ToolTip = app.Name,
                Tag = app
            };

            var style =
                TryFindResource("TopBarIconButtonStyle")
                as Style;

            if (style != null)
                button.Style = style;

            ImageSource? icon =
                TryGetLexDeskPinnedAppIcon(app);

            if (icon != null)
            {
                button.Content = new Image
                {
                    Source = icon,
                    Width = 20,
                    Height = 20,
                    Stretch = Stretch.Uniform,
                    SnapsToDevicePixels = true
                };
            }
            else
            {
                string fallback =
                    string.IsNullOrWhiteSpace(app.Name)
                        ? "?"
                        : app.Name.Substring(0, 1)
                            .ToUpperInvariant();

                var text = new TextBlock
                {
                    Text = fallback,
                    FontSize = 14,
                    FontWeight = FontWeights.Bold,
                    HorizontalAlignment =
                        HorizontalAlignment.Center,
                    VerticalAlignment =
                        VerticalAlignment.Center
                };

                text.SetResourceReference(
                    TextBlock.ForegroundProperty,
                    "SettingsNavAccent");

                button.Content = text;
            }

            button.Click +=
                LexDeskPinnedAppButton_Click;

            button.PreviewMouseRightButtonUp +=
     LexDeskPinnedAppButton_PreviewMouseRightButtonUp;

            return button;
        }

        private void LexDeskPinnedAppButton_PreviewMouseRightButtonUp(
    object sender,
    MouseButtonEventArgs e)
        {
            e.Handled = true;

            try
            {
                if (sender is not Button button)
                    return;

                if (button.Tag is not LexDeskInstalledApp app)
                    return;

                var popup = new Popup
                {
                    PlacementTarget = button,
                    Placement = PlacementMode.MousePoint,
                    AllowsTransparency = true,
                    PopupAnimation = PopupAnimation.Fade,
                    StaysOpen = false
                };

                var border = new Border
                {
                    Padding = new Thickness(6),
                    CornerRadius = new CornerRadius(8),
                    BorderThickness = new Thickness(1),
                    MinWidth = 210
                };

                border.SetResourceReference(
                    Border.BackgroundProperty,
                    "CardBg");

                border.SetResourceReference(
                    Border.BorderBrushProperty,
                    "CardBorder");

                var unpinButton = new Button
                {
                    Content = "Unpin from LexDesk taskbar",
                    Height = 34,
                    HorizontalContentAlignment = HorizontalAlignment.Left,
                    Padding = new Thickness(12, 0, 12, 0)
                };

                if (TryFindResource("MainMenuListButtonStyle") is Style style)
                    unpinButton.Style = style;

                unpinButton.Click += (_, args) =>
                {
                    args.Handled = true;
                    popup.IsOpen = false;

                    _lexDeskPinnedAppNames.RemoveAll(name =>
                        string.Equals(
                            name,
                            app.Name,
                            StringComparison.OrdinalIgnoreCase));

                    SaveLexDeskPinnedApps();
                    RefreshLexDeskPinnedAppsDock();

                    UpdateSecurityStatus(
                        $"{app.Name} unpinned from taskbar",
                        false);
                };

                border.Child = unpinButton;
                popup.Child = border;

                popup.IsOpen = true;
            }
            catch
            {
                // Right-click convenience must never affect LexDesk.
            }
        }

        private async void LexDeskPinnedAppButton_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            try
            {
                if (sender is not Button button)
                    return;

                if (button.Tag is not LexDeskInstalledApp app)
                    return;

                // Pinned desktop apps use the dedicated app panes only:
                // visual Pane 4 first, then visual Pane 3. Panes 1 and 2
                // stay browser-only. Security software is handled separately.
                int targetPageIndex =
                    GetLexDeskPreferredManagedPageIndex();

                if (!IsLexDeskSecurityPriorityApp(app) &&
                    targetPageIndex < 0 &&
                    !TryGetLexDeskExistingManagedPageIndex(
                        app.Name ?? "",
                        out targetPageIndex))
                {
                    ShowLexDeskNoFreeManagedPaneMessage();
                    return;
                }

                WriteLexDeskManagedWindowDebug(
                    $"PINNED APP CLICK | app={app.Name} | targetPage={targetPageIndex}");

                bool launched =
                    await LaunchLexDeskAppManagedAsync(
                        app,
                        targetPageIndex);

                if (launched)
                {
                    RecordLexDeskAppLaunch(app);
                    return;
                }

                ShowLexDeskMessageBox(
                    "LexDesk Pro could not open that app inside the selected LexDesk page.",
                    "Pinned App",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro could not open that app.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "Pinned App",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

        private void LexDeskPinnedAppUnpin_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            try
            {
                if (sender is not MenuItem item)
                    return;

                if (item.Tag is not LexDeskInstalledApp app)
                    return;

                _lexDeskPinnedAppNames.RemoveAll(name =>
                    string.Equals(
                        name,
                        app.Name,
                        StringComparison.OrdinalIgnoreCase));

                SaveLexDeskPinnedApps();
                RefreshLexDeskPinnedAppsDock();

                UpdateSecurityStatus(
                    $"{app.Name} unpinned from taskbar",
                    false);
            }
            catch { }
        }

        private void LexDeskPinUnpinAppMenuItem_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            try
            {
                if (sender is not MenuItem item)
                    return;

                if (item.Tag is not LexDeskInstalledApp app)
                    return;

                if (IsLexDeskAppPinned(app.Name))
                {
                    _lexDeskPinnedAppNames.RemoveAll(name =>
                        string.Equals(
                            name,
                            app.Name,
                            StringComparison.OrdinalIgnoreCase));

                    item.Header =
                        "Pin to LexDesk taskbar";

                    UpdateSecurityStatus(
                        $"{app.Name} unpinned from taskbar",
                        false);
                }
                else
                {
                    if (_lexDeskPinnedAppNames.Count >=
                        LexDeskMaxPinnedApps)
                    {
                        ShowLexDeskMessageBox(
                            $"LexDesk currently allows up to {LexDeskMaxPinnedApps} pinned apps so the taskbar stays usable on smaller screens.\n\nUnpin one app before adding another.",
                            "LexDesk Taskbar",
                            MessageBoxButton.OK,
                            MessageBoxImage.Information);

                        return;
                    }

                    _lexDeskPinnedAppNames.Add(app.Name);

                    item.Header =
                        "Unpin from LexDesk taskbar";

                    UpdateSecurityStatus(
                        $"{app.Name} pinned to taskbar",
                        false);
                }

                SaveLexDeskPinnedApps();
                RefreshLexDeskPinnedAppsDock();
            }
            catch { }
        }

        private Button CreateLexDeskAppButton(
    LexDeskInstalledApp app,
    double width,
    double height)
        {
            var button = new Button
            {
                Width = width,
                Height = height,
                Margin = new Thickness(6),
                Padding = new Thickness(10, 0, 10, 0),
                ToolTip = app.Name,
                Tag = app,
                HorizontalContentAlignment = HorizontalAlignment.Stretch,
                VerticalContentAlignment = VerticalAlignment.Center
            };

            var style =
                TryFindResource("TopBarButtonStyle")
                as Style;

            if (style != null)
                button.Style = style;

            var contentGrid = new Grid
            {
                HorizontalAlignment = HorizontalAlignment.Stretch,
                VerticalAlignment = VerticalAlignment.Center
            };

            contentGrid.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = new GridLength(28)
                });

            contentGrid.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = new GridLength(
                        1,
                        GridUnitType.Star)
                });

            ImageSource? icon =
                TryGetLexDeskPinnedAppIcon(app);

            if (icon != null)
            {
                var image = new Image
                {
                    Source = icon,
                    Width = 20,
                    Height = 20,
                    Stretch = Stretch.Uniform,
                    SnapsToDevicePixels = true,
                    HorizontalAlignment = HorizontalAlignment.Center,
                    VerticalAlignment = VerticalAlignment.Center
                };

                Grid.SetColumn(image, 0);
                contentGrid.Children.Add(image);
            }
            else
            {
                string fallback =
                    string.IsNullOrWhiteSpace(app.Name)
                        ? "?"
                        : app.Name.Substring(0, 1)
                            .ToUpperInvariant();

                var fallbackText = new TextBlock
                {
                    Text = fallback,
                    FontSize = 13,
                    FontWeight = FontWeights.Bold,
                    HorizontalAlignment =
                        HorizontalAlignment.Center,
                    VerticalAlignment =
                        VerticalAlignment.Center
                };

                fallbackText.SetResourceReference(
                    TextBlock.ForegroundProperty,
                    "SettingsNavAccent");

                Grid.SetColumn(fallbackText, 0);
                contentGrid.Children.Add(fallbackText);
            }

            var nameText = new TextBlock
            {
                Text = app.Name,
                TextAlignment = TextAlignment.Left,
                TextWrapping = TextWrapping.NoWrap,
                TextTrimming =
                    TextTrimming.CharacterEllipsis,
                HorizontalAlignment =
                    HorizontalAlignment.Stretch,
                VerticalAlignment =
                    VerticalAlignment.Center,
                FontWeight = FontWeights.SemiBold,
                Margin = new Thickness(6, 0, 0, 0)
            };

            Grid.SetColumn(nameText, 1);
            contentGrid.Children.Add(nameText);

            button.Content = contentGrid;

            bool isHidden =
                IsLexDeskAppHidden(app.Name);

            button.Opacity =
                isHidden ? 0.55 : 1.0;

            button.ToolTip =
                isHidden
                    ? app.Name +
                      "\nHidden from normal LexDesk Apps list"
                    : app.Name;

            button.PreviewMouseRightButtonUp +=
                LexDeskAppButton_PreviewMouseRightButtonUp;

            button.Click +=
                LexDeskInstalledAppButton_Click;

            return button;
        }

        private void LexDeskAppButton_PreviewMouseRightButtonUp(
    object sender,
    MouseButtonEventArgs e)
        {
            e.Handled = true;

            try
            {
                if (sender is not Button button)
                    return;

                if (button.Tag is not LexDeskInstalledApp app)
                    return;

                bool isPinned = IsLexDeskAppPinned(app.Name);
                bool isHidden = IsLexDeskAppHidden(app.Name);

                var popup = new Popup
                {
                    PlacementTarget = button,
                    Placement = PlacementMode.MousePoint,
                    AllowsTransparency = true,
                    PopupAnimation = PopupAnimation.Fade,
                    StaysOpen = false
                };

                var border = new Border
                {
                    Padding = new Thickness(6),
                    CornerRadius = new CornerRadius(8),
                    BorderThickness = new Thickness(1),
                    MinWidth = 210
                };

                border.SetResourceReference(
                    Border.BackgroundProperty,
                    "CardBg");

                border.SetResourceReference(
                    Border.BorderBrushProperty,
                    "CardBorder");

                var panel = new StackPanel();

                // ----------------------------
                // PIN / UNPIN
                // ----------------------------
                var pinButton = new Button
                {
                    Content = isPinned
                        ? "Unpin from LexDesk taskbar"
                        : "Pin to LexDesk taskbar",
                    Height = 34,
                    HorizontalContentAlignment = HorizontalAlignment.Left,
                    Padding = new Thickness(12, 0, 12, 0)
                };

                if (TryFindResource("MainMenuListButtonStyle") is Style pinStyle)
                    pinButton.Style = pinStyle;

                pinButton.Click += (_, args) =>
                {
                    args.Handled = true;
                    popup.IsOpen = false;

                    if (IsLexDeskAppPinned(app.Name))
                    {
                        _lexDeskPinnedAppNames.RemoveAll(name =>
                            string.Equals(
                                name,
                                app.Name,
                                StringComparison.OrdinalIgnoreCase));

                        SaveLexDeskPinnedApps();
                        RefreshLexDeskPinnedAppsDock();

                        UpdateSecurityStatus(
                            $"{app.Name} unpinned from taskbar",
                            false);

                        return;
                    }

                    if (_lexDeskPinnedAppNames.Count >= LexDeskMaxPinnedApps)
                    {
                        ShowWebPrivacyMessage(
                            "LexDesk Taskbar",
                            $"LexDesk currently allows up to {LexDeskMaxPinnedApps} pinned apps so the taskbar stays usable on smaller screens.\n\nUnpin one app before adding another.",
                            520,
                            280);

                        return;
                    }

                    _lexDeskPinnedAppNames.Add(app.Name);

                    SaveLexDeskPinnedApps();
                    RefreshLexDeskPinnedAppsDock();

                    UpdateSecurityStatus(
                        $"{app.Name} pinned to taskbar",
                        false);
                };

                panel.Children.Add(pinButton);

                // Themed divider - no Windows Separator nonsense.
                var divider = new Border
                {
                    Height = 1,
                    Margin = new Thickness(6, 4, 6, 4)
                };

                divider.SetResourceReference(
                    Border.BackgroundProperty,
                    "CardBorder");

                panel.Children.Add(divider);

                // ----------------------------
                // HIDE / SHOW
                // ----------------------------
                var hideButton = new Button
                {
                    Content = isHidden
                        ? "Show in LexDesk"
                        : "Hide from LexDesk",
                    Height = 34,
                    HorizontalContentAlignment = HorizontalAlignment.Left,
                    Padding = new Thickness(12, 0, 12, 0)
                };

                if (TryFindResource("MainMenuListButtonStyle") is Style hideStyle)
                    hideButton.Style = hideStyle;

                hideButton.Click += (_, args) =>
                {
                    args.Handled = true;
                    popup.IsOpen = false;

                    Dispatcher.BeginInvoke(new Action(() =>
                    {
                        try
                        {
                            var proxyItem = new MenuItem
                            {
                                Tag = app
                            };

                            LexDeskHideShowAppMenuItem_Click(
                                proxyItem,
                                new RoutedEventArgs(MenuItem.ClickEvent));
                        }
                        catch (Exception ex)
                        {
                            ShowLexDeskMessageBox(
                                "LexDesk could not hide or show that app.\n\n" +
                                SanitizeExceptionMessage(ex),
                                "LexDesk Apps",
                                MessageBoxButton.OK,
                                MessageBoxImage.Information);
                        }
                    }));
                };

                panel.Children.Add(hideButton);

                border.Child = panel;
                popup.Child = border;

                popup.IsOpen = true;
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk could not open the app menu.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "LexDesk Apps",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

        private void PopulateLexDeskMostUsedApps()
        {
            try
            {
                if (LexDeskMostUsedSection == null || LexDeskMostUsedPanel == null)
                    return;

                LexDeskMostUsedPanel.Children.Clear();

                var mostUsed = _lexDeskAllApps
    .Where(app =>
        app != null &&
        !string.IsNullOrWhiteSpace(app.Name) &&
        !IsLexDeskAppHidden(app.Name) &&
        _lexDeskAppUseCounts.ContainsKey(app.Name))
                    .OrderByDescending(app => _lexDeskAppUseCounts.TryGetValue(app.Name, out int count) ? count : 0)
                    .ThenBy(app => app.Name, StringComparer.OrdinalIgnoreCase)
                    .Take(8)
                    .ToList();

                if (mostUsed.Count == 0)
                {
                    LexDeskMostUsedSection.Visibility = Visibility.Collapsed;
                    return;
                }

                foreach (var app in mostUsed)
                {
                    LexDeskMostUsedPanel.Children.Add(CreateLexDeskAppButton(app, 180, 46));
                }

                LexDeskMostUsedSection.Visibility = Visibility.Visible;
            }
            catch
            {
                try
                {
                    if (LexDeskMostUsedSection != null)
                        LexDeskMostUsedSection.Visibility = Visibility.Collapsed;
                }
                catch { }
            }
        }

        private List<LexDeskInstalledApp> GetLexDeskVisibleApps(IEnumerable<LexDeskInstalledApp> apps)
        {
            try
            {
                return (apps ?? Enumerable.Empty<LexDeskInstalledApp>())
                    .Where(app =>
                        app != null &&
                        !string.IsNullOrWhiteSpace(app.Name) &&
                        (_lexDeskShowHiddenApps || !IsLexDeskAppHidden(app.Name)))
                    .OrderBy(app => app.Name, StringComparer.OrdinalIgnoreCase)
                    .ToList();
            }
            catch
            {
                return new List<LexDeskInstalledApp>();
            }
        }

        private bool IsLexDeskAppHidden(string? appName)
        {
            if (string.IsNullOrWhiteSpace(appName))
                return false;

            return _lexDeskHiddenApps.Contains(appName.Trim());
        }

        private void LexDeskShowHiddenApps_Click(
    object sender,
    RoutedEventArgs e)
        {
            e.Handled = true;

            _lexDeskShowHiddenApps =
                !_lexDeskShowHiddenApps;

            RefreshLexDeskShowHiddenButtonText();

            if (_lexDeskShowHiddenApps)
            {
                RefreshLexDeskHiddenAppsOnly();
            }
            else if (LexDeskHiddenAppsSection != null)
            {
                LexDeskHiddenAppsSection.Visibility =
                    Visibility.Collapsed;
            }

            UpdateSecurityStatus(
                _lexDeskShowHiddenApps
                    ? "Hidden apps shown"
                    : "Hidden apps hidden",
                false);
        }

        private void RefreshLexDeskShowHiddenButtonText()
        {
            try
            {
                if (LexDeskShowHiddenAppsButton == null)
                    return;

                if (_lexDeskHiddenApps.Count == 0)
                {
                    LexDeskShowHiddenAppsButton.Visibility = Visibility.Collapsed;
                    _lexDeskShowHiddenApps = false;
                    return;
                }

                LexDeskShowHiddenAppsButton.Visibility = Visibility.Visible;
                LexDeskShowHiddenAppsButton.Content = _lexDeskShowHiddenApps
                    ? "Hide hidden apps"
                    : "Show hidden apps";
            }
            catch { }
        }

        private bool LexDeskAppMatchesCurrentSearch(string appName)
        {
            string query =
                LexDeskAppsSearchBox?.Text?.Trim() ?? "";

            if (string.IsNullOrWhiteSpace(query))
                return true;

            return appName.IndexOf(
                query,
                StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private void RemoveLexDeskAppButtonFromPanel(
            Panel? panel,
            string appName)
        {
            if (panel == null)
                return;

            for (int i = panel.Children.Count - 1; i >= 0; i--)
            {
                if (panel.Children[i] is not Button button)
                    continue;

                if (button.Tag is not LexDeskInstalledApp app)
                    continue;

                if (string.Equals(
                        app.Name,
                        appName,
                        StringComparison.OrdinalIgnoreCase))
                {
                    panel.Children.RemoveAt(i);
                }
            }
        }

        private void InsertLexDeskAppButtonSorted(
            Panel? panel,
            LexDeskInstalledApp app,
            double width,
            double height)
        {
            if (panel == null || app == null)
                return;

            if (!LexDeskAppMatchesCurrentSearch(app.Name))
                return;

            RemoveLexDeskAppButtonFromPanel(
                panel,
                app.Name);

            int insertIndex = panel.Children.Count;

            for (int i = 0; i < panel.Children.Count; i++)
            {
                if (panel.Children[i] is not Button button)
                    continue;

                if (button.Tag is not LexDeskInstalledApp existing)
                    continue;

                if (string.Compare(
                        app.Name,
                        existing.Name,
                        StringComparison.OrdinalIgnoreCase) < 0)
                {
                    insertIndex = i;
                    break;
                }
            }

            panel.Children.Insert(
                insertIndex,
                CreateLexDeskAppButton(
                    app,
                    width,
                    height));
        }

        private void RefreshLexDeskHiddenAppsOnly()
        {
            try
            {
                if (LexDeskHiddenAppsSection == null ||
                    LexDeskHiddenAppsPanel == null)
                {
                    return;
                }

                if (!_lexDeskShowHiddenApps)
                {
                    LexDeskHiddenAppsSection.Visibility =
                        Visibility.Collapsed;

                    return;
                }

                if (!_lexDeskHiddenAppsPanelDirty)
                {
                    LexDeskHiddenAppsSection.Visibility =
                        LexDeskHiddenAppsPanel.Children.Count > 0
                            ? Visibility.Visible
                            : Visibility.Collapsed;

                    return;
                }

                LexDeskHiddenAppsPanel.Children.Clear();

                var hiddenApps =
                    (_lexDeskAllApps ??
                     new List<LexDeskInstalledApp>())
                    .Where(app =>
                        app != null &&
                        !string.IsNullOrWhiteSpace(app.Name) &&
                        IsLexDeskAppHidden(app.Name) &&
                        LexDeskAppMatchesCurrentSearch(app.Name))
                    .OrderBy(
                        app => app.Name,
                        StringComparer.OrdinalIgnoreCase)
                    .ToList();

                foreach (var app in hiddenApps)
                {
                    LexDeskHiddenAppsPanel.Children.Add(
                        CreateLexDeskAppButton(
                            app,
                            190,
                            50));
                }

                _lexDeskHiddenAppsPanelDirty = false;

                LexDeskHiddenAppsSection.Visibility =
                    hiddenApps.Count > 0
                        ? Visibility.Visible
                        : Visibility.Collapsed;
            }
            catch
            {
                // Hidden Apps must never affect the main Apps list.
            }
        }

        private void LexDeskHideShowAppMenuItem_Click(
    object sender,
    RoutedEventArgs e)
        {
            if (e.RoutedEvent != null)
                e.Handled = true;

            try
            {
                if (sender is not MenuItem item)
                    return;

                if (item.Tag is not LexDeskInstalledApp app)
                    return;

                string name =
                    app.Name?.Trim() ?? "";

                if (string.IsNullOrWhiteSpace(name))
                    return;

                // ========================================
                // SHOW AN APP THAT IS CURRENTLY HIDDEN
                // ========================================
                if (IsLexDeskAppHidden(name))
                {
                    _lexDeskHiddenApps.Remove(name);

                    SaveLexDeskHiddenApps();

                    _lexDeskHiddenAppsPanelDirty = true;

                    RemoveLexDeskAppButtonFromPanel(
                        LexDeskHiddenAppsPanel,
                        name);

                    InsertLexDeskAppButtonSorted(
                        LexDeskAppsListPanel,
                        app,
                        190,
                        50);

                    RefreshLexDeskShowHiddenButtonText();
                    PopulateLexDeskMostUsedApps();

                    if (_lexDeskShowHiddenApps)
                        RefreshLexDeskHiddenAppsOnly();

                    UpdateSecurityStatus(
                        $"{name} shown in LexDesk Apps",
                        false);

                    return;
                }

                // ========================================
                // HIDE A NORMAL APP
                // ========================================
                bool confirmed =
                    ShowWebPrivacyConfirmation(
                        "Hide App",
                        $"Hide this app from LexDesk Apps?\n\n{name}\n\n" +
                        "You can restore it later with Show hidden apps.",
                        "Hide App",
                        "Cancel",
                        500,
                        280);

                if (!confirmed)
                    return;

                _lexDeskHiddenApps.Add(name);

                SaveLexDeskHiddenApps();

                _lexDeskHiddenAppsPanelDirty = true;

                // Remove only this app instead of rebuilding
                // the entire Apps panel.
                RemoveLexDeskAppButtonFromPanel(
                    LexDeskAppsListPanel,
                    name);

                PopulateLexDeskMostUsedApps();

                RefreshLexDeskShowHiddenButtonText();

                if (_lexDeskShowHiddenApps)
                    RefreshLexDeskHiddenAppsOnly();

                UpdateSecurityStatus(
                    $"{name} hidden from LexDesk Apps",
                    false);
            }
            catch
            {
                // Hide/show must never break the Apps panel.
            }
        }

        private string GetLexDeskHiddenAppsFilePath()
        {
            try
            {
                return Path.Combine(GetStableAppDataFolder(), LexDeskHiddenAppsFileName);
            }
            catch
            {
                return Path.Combine(
                    Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                    "LexAndWhiteStudios",
                    "LexDeskPro",
                    LexDeskHiddenAppsFileName);
            }
        }

        private void LoadLexDeskHiddenApps()
        {
            try
            {
                _lexDeskHiddenApps.Clear();

                string path = GetLexDeskHiddenAppsFilePath();

                if (!File.Exists(path))
                    return;

                foreach (string line in File.ReadAllLines(path))
                {
                    string name = (line ?? "").Trim();

                    if (!string.IsNullOrWhiteSpace(name))
                        _lexDeskHiddenApps.Add(name);
                }
            }
            catch
            {
                _lexDeskHiddenApps.Clear();
            }
        }

        private void SaveLexDeskHiddenApps()
        {
            try
            {
                string path = GetLexDeskHiddenAppsFilePath();

                Directory.CreateDirectory(Path.GetDirectoryName(path) ?? "");

                File.WriteAllLines(
                    path,
                    _lexDeskHiddenApps
                        .Where(x => !string.IsNullOrWhiteSpace(x))
                        .OrderBy(x => x, StringComparer.OrdinalIgnoreCase));
            }
            catch
            {
                // Ignore hidden app save errors.
            }
        }

        private void RecordLexDeskAppLaunch(LexDeskInstalledApp app)
        {
            try
            {
                if (app == null || string.IsNullOrWhiteSpace(app.Name))
                    return;

                if (!_lexDeskAppUseCounts.ContainsKey(app.Name))
                    _lexDeskAppUseCounts[app.Name] = 0;

                _lexDeskAppUseCounts[app.Name]++;

                SaveLexDeskAppUsageCounts();
                PopulateLexDeskMostUsedApps();
            }
            catch
            {
                // Usage tracking must never block launching.
            }
        }

        private string GetLexDeskAppUsageFilePath()
        {
            try
            {
                return Path.Combine(GetStableAppDataFolder(), LexDeskAppUsageFileName);
            }
            catch
            {
                return Path.Combine(
                    Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                    "LexAndWhiteStudios",
                    "LexDeskPro",
                    LexDeskAppUsageFileName);
            }
        }

        private void LoadLexDeskAppUsageCounts()
        {
            try
            {
                _lexDeskAppUseCounts.Clear();

                string path = GetLexDeskAppUsageFilePath();

                if (!File.Exists(path))
                    return;

                foreach (string line in File.ReadAllLines(path))
                {
                    if (string.IsNullOrWhiteSpace(line))
                        continue;

                    string[] parts = line.Split('|');

                    if (parts.Length < 2)
                        continue;

                    string name = parts[0].Trim();

                    if (string.IsNullOrWhiteSpace(name))
                        continue;

                    if (!int.TryParse(parts[1].Trim(), out int count))
                        count = 0;

                    if (count <= 0)
                        continue;

                    _lexDeskAppUseCounts[name] = count;
                }
            }
            catch
            {
                _lexDeskAppUseCounts.Clear();
            }
        }

        private void SaveLexDeskAppUsageCounts()
        {
            try
            {
                string path = GetLexDeskAppUsageFilePath();
                Directory.CreateDirectory(Path.GetDirectoryName(path) ?? "");

                var lines = _lexDeskAppUseCounts
                    .Where(kvp => !string.IsNullOrWhiteSpace(kvp.Key) && kvp.Value > 0)
                    .OrderByDescending(kvp => kvp.Value)
                    .ThenBy(kvp => kvp.Key, StringComparer.OrdinalIgnoreCase)
                    .Select(kvp => kvp.Key.Replace("|", "") + "|" + kvp.Value)
                    .ToList();

                File.WriteAllLines(path, lines);
            }
            catch
            {
                // Ignore usage save errors.
            }
        }

        private List<LexDeskInstalledApp> GetLexDeskInstalledAppsFastRefresh(
    IEnumerable<LexDeskInstalledApp>? existingApps)
        {
            var apps = new Dictionary<string, LexDeskInstalledApp>(
                StringComparer.OrdinalIgnoreCase);

            try
            {
                // Keep packaged / Microsoft Store apps already discovered
                // by the full Windows AppsFolder scan.
                foreach (var existing in
                         existingApps ??
                         Enumerable.Empty<LexDeskInstalledApp>())
                {
                    if (existing == null ||
                        string.IsNullOrWhiteSpace(existing.Name))
                    {
                        continue;
                    }

                    if (existing.LaunchType !=
                        LexDeskLaunchType.Aumid)
                    {
                        continue;
                    }

                    string name =
                        CleanLexDeskAppName(existing.Name);

                    if (string.IsNullOrWhiteSpace(name))
                        continue;

                    if (ShouldHideLexDeskAppsFolderEntry(
                            name,
                            existing.Target))
                    {
                        continue;
                    }

                    apps[name] = existing;
                }

                // Fast scan of real Start Menu shortcuts.
                // SafeEnumerateLexDeskShortcutFiles already
                // walks child folders recursively.
                var folders = new List<string>();

                string commonStartMenu =
                    Environment.GetFolderPath(
                        Environment.SpecialFolder.CommonStartMenu);

                string userStartMenu =
                    Environment.GetFolderPath(
                        Environment.SpecialFolder.StartMenu);

                if (!string.IsNullOrWhiteSpace(commonStartMenu))
                    folders.Add(commonStartMenu);

                if (!string.IsNullOrWhiteSpace(userStartMenu))
                    folders.Add(userStartMenu);

                foreach (string folder in
                         folders.Distinct(
                             StringComparer.OrdinalIgnoreCase))
                {
                    foreach (string shortcutPath in
                             SafeEnumerateLexDeskShortcutFiles(folder))
                    {
                        string name =
                            CleanLexDeskAppName(
                                Path.GetFileNameWithoutExtension(
                                    shortcutPath));

                        if (string.IsNullOrWhiteSpace(name))
                            continue;

                        if (ShouldHideLexDeskAppShortcut(
                                name,
                                shortcutPath))
                        {
                            continue;
                        }

                        // Real Start Menu shortcut wins over
                        // an AppsFolder copy with the same name.
                        apps[name] =
                            new LexDeskInstalledApp
                            {
                                Name = name,
                                Target = shortcutPath,
                                ShortcutPath = shortcutPath,
                                LaunchType =
                                    LexDeskLaunchType.Shortcut
                            };
                    }
                }
            }
            catch
            {
                // Return whatever was found.
            }

            return apps.Values
                .OrderBy(
                    app => app.Name,
                    StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static bool LexDeskAppListsMatch(
    IEnumerable<LexDeskInstalledApp>? first,
    IEnumerable<LexDeskInstalledApp>? second)
        {
            string MakeKey(LexDeskInstalledApp app)
            {
                return
                    (app.Name ?? "") + "\u001F" +
                    (app.Target ?? "") + "\u001F" +
                    (app.ShortcutPath ?? "") + "\u001F" +
                    (app.Aumid ?? "") + "\u001F" +
                    app.LaunchType;
            }

            var firstKeys =
                (first ??
                 Enumerable.Empty<LexDeskInstalledApp>())
                .Where(app =>
                    app != null &&
                    !string.IsNullOrWhiteSpace(app.Name))
                .Select(MakeKey)
                .OrderBy(
                    value => value,
                    StringComparer.OrdinalIgnoreCase)
                .ToList();

            var secondKeys =
                (second ??
                 Enumerable.Empty<LexDeskInstalledApp>())
                .Where(app =>
                    app != null &&
                    !string.IsNullOrWhiteSpace(app.Name))
                .Select(MakeKey)
                .OrderBy(
                    value => value,
                    StringComparer.OrdinalIgnoreCase)
                .ToList();

            return firstKeys.SequenceEqual(
                secondKeys,
                StringComparer.OrdinalIgnoreCase);
        }

        private List<LexDeskInstalledApp> GetLexDeskInstalledApps()
        {
            var apps = new Dictionary<string, LexDeskInstalledApp>(
                StringComparer.OrdinalIgnoreCase);

            try
            {
                // 1) Normal Start Menu .lnk shortcuts.
                var folders = new List<string>();

                string commonStartMenu =
                    Environment.GetFolderPath(
                        Environment.SpecialFolder.CommonStartMenu);

                string userStartMenu =
                    Environment.GetFolderPath(
                        Environment.SpecialFolder.StartMenu);

                if (!string.IsNullOrWhiteSpace(commonStartMenu))
                {
                    // SafeEnumerateLexDeskShortcutFiles already scans subfolders
                    // recursively, including Programs. Do not scan Programs twice.
                    folders.Add(commonStartMenu);
                }

                if (!string.IsNullOrWhiteSpace(userStartMenu))
                {
                    folders.Add(userStartMenu);
                }

                foreach (string folder in folders.Distinct(
                             StringComparer.OrdinalIgnoreCase))
                {
                    foreach (string shortcutPath
                             in SafeEnumerateLexDeskShortcutFiles(folder))
                    {
                        string name =
                            CleanLexDeskAppName(
                                Path.GetFileNameWithoutExtension(shortcutPath));

                        if (string.IsNullOrWhiteSpace(name))
                            continue;

                        if (ShouldHideLexDeskAppShortcut(
                                name,
                                shortcutPath))
                        {
                            continue;
                        }

                        if (!apps.ContainsKey(name))
                        {
                            apps[name] = new LexDeskInstalledApp
                            {
                                Name = name,
                                Target = shortcutPath,
                                ShortcutPath = shortcutPath,
                                LaunchType = LexDeskLaunchType.Shortcut
                            };
                        }
                    }
                }

                // 2) Windows AppsFolder / AUMID apps.
                // This catches Calculator, Photos, Camera, Weather,
                // Paint, Teams, Defender, etc.
                foreach (var app in EnumerateLexDeskAppsFolderApps())
                {
                    if (app == null)
                        continue;

                    string name = CleanLexDeskAppName(app.Name);

                    if (string.IsNullOrWhiteSpace(name))
                        continue;

                    if (ShouldHideLexDeskAppsFolderEntry(
                            name,
                            app.Target))
                    {
                        continue;
                    }

                    // Prefer a real Start Menu shortcut if we already have one.
                    if (!apps.ContainsKey(name))
                    {
                        apps[name] = app;
                    }
                }
            }
            catch
            {
                // Return whatever was found.
            }

            return apps.Values
                .OrderBy(
                    a => a.Name,
                    StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private IEnumerable<LexDeskInstalledApp>
    EnumerateLexDeskAppsFolderApps()
        {
            var results =
                new List<LexDeskInstalledApp>();

            object? shell = null;
            object? folder = null;
            object? items = null;

            try
            {
                Type? shellType =
                    Type.GetTypeFromProgID(
                        "Shell.Application");

                if (shellType == null)
                    return results;

                shell =
                    Activator.CreateInstance(shellType);

                if (shell == null)
                    return results;

                dynamic dynamicShell = shell;

                folder =
                    dynamicShell.NameSpace(
                        "shell:AppsFolder");

                if (folder == null)
                    return results;

                dynamic dynamicFolder = folder;

                items = dynamicFolder.Items();

                if (items == null)
                    return results;

                dynamic dynamicItems = items;

                int count = dynamicItems.Count;

                for (int i = 0; i < count; i++)
                {
                    object? itemObject = null;

                    try
                    {
                        itemObject =
                            dynamicItems.Item(i);

                        if (itemObject == null)
                            continue;

                        dynamic item = itemObject;

                        string name =
                            item.Name as string ?? "";

                        name =
                            CleanLexDeskAppName(name);

                        if (string.IsNullOrWhiteSpace(name))
                            continue;

                        string id =
                            item.Path as string ?? "";

                        id = id.Trim();

                        if (string.IsNullOrWhiteSpace(id))
                            continue;

                        const string prefix =
                            "shell:AppsFolder\\";

                        if (id.StartsWith(
                                prefix,
                                StringComparison.OrdinalIgnoreCase))
                        {
                            id =
                                id.Substring(
                                    prefix.Length);
                        }

                        results.Add(
                            new LexDeskInstalledApp
                            {
                                Name = name,
                                Target = id,
                                Aumid = id,
                                LaunchType =
                                    LexDeskLaunchType.Aumid
                            });
                    }
                    catch
                    {
                        // One bad Windows shell item
                        // must not stop app discovery.
                    }
                    finally
                    {
                        ReleaseLexDeskComObject(
                            itemObject);
                    }
                }
            }
            catch
            {
                return results;
            }
            finally
            {
                ReleaseLexDeskComObject(items);
                ReleaseLexDeskComObject(folder);
                ReleaseLexDeskComObject(shell);
            }

            return results;
        }


        private bool ShouldHideLexDeskAppsFolderEntry(string name, string target)
        {
            if (string.IsNullOrWhiteSpace(name))
                return true;

            string lower = name.Trim().ToLowerInvariant();
            string targetLower = (target ?? "").Trim().ToLowerInvariant();

            // ============================================
            // Windows Start-style structural cleanup
            // ============================================
            //
            // shell:AppsFolder exposes considerably more than the normal
            // Windows 11 Start > All apps list. It can include website links,
            // auto-generated helper entries, individual Windows administration
            // tools, SDK utilities and secondary actions belonging to one app.
            //
            // LexDesk already discovers normal Win32 applications from their
            // real Start Menu shortcuts, so these shell-only helper entries
            // should not be added again.

            // Website/help shortcuts are not applications.
            // Classic Windows system-tool shell locations.
            //
            // Do not block every GUID-based shell path here because Program Files
            // applications can also be exposed by AppsFolder using known-folder GUIDs.
            // Only suppress Windows/System32/SysWOW64 style tool entries.
            string[] hiddenSystemShellRoots =
            {
                "{1ac14e77-02e7-4e5d-b744-2eb1ae5198b7}\\",
                "{d65231b0-b2f1-4857-a4ce-a8e7c6ea7d27}\\",
                "{f38bf404-1d43-42f2-9305-67de0b28fc23}\\"
            };

            if (hiddenSystemShellRoots.Any(root =>
                    targetLower.StartsWith(root, StringComparison.OrdinalIgnoreCase)))
            {
                return true;
            }

            // Windows-generated helper/tool entries.
            // Examples seen in AppsFolder:
            // Git Bash, command prompts, Event Viewer, Task Scheduler, etc.
            if (targetLower.StartsWith(
                    "microsoft.autogenerated.",
                    StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            // shell:AppsFolder also exposes individual classic Windows tools
            // through special shell paths such as:
            //
            // {1AC14E77-...}\cmd.exe
            // {1AC14E77-...}\services.msc
            // {1AC14E77-...}\regedit.exe
            //
            // These belong under Windows Tools rather than appearing as
            // individual Grandma-mode apps.
            if (targetLower.StartsWith("{", StringComparison.OrdinalIgnoreCase) &&
                targetLower.Contains("}\\", StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            // Shell-only Windows aliases that should not appear as separate
            // LexDesk app buttons. Windows Tools itself is intentionally kept.
            string[] hiddenShellIds =
            {
        "microsoft.windows.controlpanel",
        "microsoft.windows.mediaplayer32",
        "microsoft.windows.remotedesktop",
        "microsoft.windows.shell.rundialog"
    };

            if (hiddenShellIds.Any(id =>
                    targetLower.Equals(id, StringComparison.OrdinalIgnoreCase)))
            {
                return true;
            }

            // Power Automate publishes a troubleshooting helper as a separate
            // AppsFolder entry. Keep the actual Power Automate app only.
            if (targetLower.EndsWith(
                    "!pad.troubleshooter",
                    StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            // Adobe Express Photos publishes several action/verb entries
            // (View Photos, Edit Photos, Crop Images, Add Text, Rotate Photos).
            // Keep only the main Adobe Express Photos application.
            if (targetLower.StartsWith(
                    "adobesystemsincorporated.adobephotoshopexpress_",
                    StringComparison.OrdinalIgnoreCase) &&
                !targetLower.EndsWith(
                    "!app",
                    StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            // ============================================
            // Existing LexDesk AppsFolder filtering
            // ============================================

            string[] hiddenWords =
            {
        "get help",
        "get started",
        "tips",
        "feedback hub",

        "uninstall",
        "remove",
        "repair",
        "setup",
        "installer",
        "install",
        "updater",
        "update assistant",

        "readme",
        "documentation",
        "manual",
        "release notes",
        "license",
        "licence",
        "eula",

        ".net sdk",
        "net sdk",
        "sdk",
        "runtime",
        "redistributable",
        "shared framework",
        "targeting pack",
        "developer pack",
        "development kit",
        "asp.net core",

        "developer command prompt",
        "developer powershell",
        "native tools command",
        "cross tools command",
        "debuggable package manager",
        "database engine tuning",
        "sql server profiler",

        "reset preferences",
        "language preferences"
    };

            if (hiddenWords.Any(word =>
                    lower.Contains(word, StringComparison.OrdinalIgnoreCase)))
            {
                return true;
            }

            string[] hiddenTargetBits =
            {
        "windowsimmersivecontrolpanel",
        "microsoft.gethelp",
        "microsoft.getstarted"
    };

            if (hiddenTargetBits.Any(bit =>
                    targetLower.Contains(bit, StringComparison.OrdinalIgnoreCase)))
            {
                return true;
            }

            return false;
        }

        private string CleanLexDeskAppName(string name)
        {
            return (name ?? "")
                .Replace(" - Shortcut", "", StringComparison.OrdinalIgnoreCase)
                .Replace("Shortcut", "", StringComparison.OrdinalIgnoreCase)
                .Trim();
        }

        private IEnumerable<string> SafeEnumerateLexDeskShortcutFiles(string folder)
        {
            if (string.IsNullOrWhiteSpace(folder) || !Directory.Exists(folder))
                yield break;

            if (ShouldSkipLexDeskAppsFolder(folder))
                yield break;

            List<string> files;

            try
            {
                // Grandma mode:
                // Only Start Menu .lnk shortcuts are used.
                // Do not show .url website shortcuts.
                files = Directory
                    .EnumerateFiles(folder, "*.lnk", SearchOption.TopDirectoryOnly)
                    .ToList();
            }
            catch
            {
                files = new List<string>();
            }

            foreach (string file in files)
                yield return file;

            List<string> subFolders;

            try
            {
                subFolders = Directory
                    .EnumerateDirectories(folder, "*", SearchOption.TopDirectoryOnly)
                    .ToList();
            }
            catch
            {
                subFolders = new List<string>();
            }

            foreach (string subFolder in subFolders)
            {
                if (ShouldSkipLexDeskAppsFolder(subFolder))
                    continue;

                foreach (string child in SafeEnumerateLexDeskShortcutFiles(subFolder))
                    yield return child;
            }
        }

        private bool ShouldSkipLexDeskAppsFolder(string folder)
        {
            if (string.IsNullOrWhiteSpace(folder))
                return true;

            string name = Path.GetFileName(folder).Trim().ToLowerInvariant();
            string path = folder.Trim().ToLowerInvariant();

            string[] skipFolderNames =
            {
        "administrative tools",
        "windows tools",
        "startup",
        "maintenance",
        "windows powershell",
        "powershell",
        "system tools",
        "accessories",
        "visual studio tools",
        "microsoft sql server tools",
        "microsoft .net",
        ".net",
        "windows kits",
        "node.js"
    };

            if (skipFolderNames.Any(x =>
                    name.Contains(x, StringComparison.OrdinalIgnoreCase) ||
                    path.Contains("\\" + x + "\\", StringComparison.OrdinalIgnoreCase)))
                return true;

            return false;
        }

        private bool ShouldHideLexDeskAppShortcut(string name, string shortcutPath)
        {
            if (string.IsNullOrWhiteSpace(name))
                return true;

            string value = name.Trim();
            string lower = value.ToLowerInvariant();
            string pathLower = (shortcutPath ?? "").ToLowerInvariant();
            // Revo Uninstaller is a legitimate application.
            // Its product name happens to contain the word "uninstall".
            if (lower.Equals("revo uninstaller", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            // Legitimate installed application whose product name contains
            // "Uninstaller". Windows Start exposes this as a normal application.
            if (lower.Equals("revo uninstaller", StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            // Hide common non-app shortcuts, help links, setup tools, and repair tools.
            string[] hiddenWords =
            {
        "reset preferences",
        "uninstall",
        "remove",
        "readme",
        "documentation",
        "docs",
        "help",
        "get help",
        "get started",
        "website",
        "site",
        "manual",
        "release notes",
        "license",
        "licence",
        "eula",
        "setup",
        "install",
        "installer",
        "repair",
        "modify",
