        private async void LexDeskInstalledAppButton_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;

            try
            {
                if (sender is not Button button)
                    return;

                if (button.Tag is not LexDeskInstalledApp app)
                {
                    ShowLexDeskMessageBox(
                        "LexDesk Pro could not read that app shortcut.",
                        "LexDesk Pro",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);

                    return;
                }

                // Desktop apps use visual Pane 4 first, then Pane 3 only.
                // Panes 1 and 2 remain browser-only.
                int targetPageIndex =
                    GetLexDeskPreferredManagedPageIndex();

                if (!IsLexDeskSecurityPriorityApp(app) &&
                    targetPageIndex < 0 &&
                    !TryGetLexDeskExistingManagedPageIndex(
                        app.Name ?? "",
                        out targetPageIndex))
                {
                    ShowLexDeskNoFreeManagedPaneMessage();
                    return;
                }

                // TEMP DEBUG: start a fresh managed-app trace for this launch.
                // This does not change launch behaviour. It only records why a
                // desktop app was or was not captured into the requested pane.
                try
                {
                    string? debugFolder =
                        Path.GetDirectoryName(
                            _lexDeskManagedWindowDebugLogPath);

                    if (!string.IsNullOrWhiteSpace(debugFolder))
                        Directory.CreateDirectory(debugFolder);

                    File.WriteAllText(
                        _lexDeskManagedWindowDebugLogPath,
                        "");
                }
                catch { }

                WriteLexDeskManagedWindowDebug(
                    $"APP BUTTON | name={app.Name} | " +
                    $"launchType={app.LaunchType} | " +
                    $"target={app.Target} | " +
                    $"shortcut={app.ShortcutPath} | " +
                    $"requestedPage={targetPageIndex} | " +
                    $"activePage={_activePageIndex} | " +
                    $"layoutPageCount={_layoutPageCount}");

                for (int debugPage = 0; debugPage < 4; debugPage++)
                {
                    try
                    {
                        Border? debugHost = GetPageHost(debugPage);

                        WriteLexDeskManagedWindowDebug(
                            $"PAGE STATE | page={debugPage} | " +
                            $"state={_paneState[debugPage]} | " +
                            $"visibility={debugHost?.Visibility} | " +
                            $"isVisible={debugHost?.IsVisible} | " +
                            $"actual={debugHost?.ActualWidth:0}x{debugHost?.ActualHeight:0}");
                    }
                    catch { }
                }

                HideLexDeskAppsPanel();

                bool launched =
                    await LaunchLexDeskAppManagedAsync(
                        app,
                        targetPageIndex);

                if (launched)
                {
                    RecordLexDeskAppLaunch(app);
                    return;
                }

                ShowLexDeskMessageBox(
                    "LexDesk Pro could not open that app.",
                    "LexDesk Pro",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro could not open that app.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "LexDesk Pro",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

        private async Task<bool> LaunchLexDeskAppManagedAsync(
            LexDeskInstalledApp app,
            int pageIndex)
        {
            if (app == null)
                return false;

            // Antivirus / internet-security software takes centre stage instead
            // of consuming Pane 3 or Pane 4.
            if (IsLexDeskSecurityPriorityApp(app))
            {
                if (IsLexDeskBitdefenderApp(app))
                {
                    return await OpenLexDeskBitdefenderPriorityOverlayAsync(app);
                }

                if (IsLexDeskNativeSecurityPriorityTarget(
                        app.Target,
                        app.Name))
                {
                    return await OpenLexDeskNativeSecurityPrioritySurfaceAsync(
                        app.Target,
                        string.IsNullOrWhiteSpace(app.Name)
                            ? "Windows Security"
                            : app.Name);
                }

                return await OpenLexDeskGenericSecurityPriorityOverlayAsync(app);
            }

            if (pageIndex < 2 || pageIndex > 3 ||
                _paneState[pageIndex] != PaneLifeState.Normal)
            {
                pageIndex =
                    GetLexDeskPreferredManagedPageIndex();
            }

            string target = "";
            string arguments = "";
            string workingDirectory = "";
            string processName = "";

            try
            {
                if (TryGetLexDeskForcedLaunchOverride(
                        app,
                        out string forcedExe,
                        out string forcedWd,
                        out string forcedArgs,
                        out _,
                        out _))
                {
                    target = forcedExe;
                    arguments = forcedArgs;
                    workingDirectory = forcedWd;
                }
                else if (app.LaunchType == LexDeskLaunchType.Shortcut)
                {
                    string shortcutPath =
                        !string.IsNullOrWhiteSpace(app.ShortcutPath)
                            ? app.ShortcutPath
                            : app.Target;

                    if (TryResolveLexDeskShortcutViaWScript(
                            shortcutPath,
                            out string exe,
                            out string shortcutArgs,
                            out string shortcutWd) &&
                        File.Exists(exe))
                    {
                        target = exe;
                        arguments =
                            !string.IsNullOrWhiteSpace(app.Arguments)
                                ? app.Arguments
                                : shortcutArgs;
                        workingDirectory =
                            !string.IsNullOrWhiteSpace(app.WorkingDirectory)
                                ? app.WorkingDirectory
                                : shortcutWd;
                    }
                }
                else if (app.LaunchType == LexDeskLaunchType.Exe &&
                         !string.IsNullOrWhiteSpace(app.Target))
                {
                    target = app.Target;
                    arguments = app.Arguments ?? "";
                    workingDirectory = app.WorkingDirectory ?? "";
                }
                else if (app.LaunchType == LexDeskLaunchType.Aumid)
                {
                    string aumid =
                        !string.IsNullOrWhiteSpace(app.Aumid)
                            ? app.Aumid
                            : app.Target;

                    if (!string.IsNullOrWhiteSpace(aumid))
                    {
                        target =
                            aumid.StartsWith(
                                "shell:AppsFolder\\",
                                StringComparison.OrdinalIgnoreCase)
                                ? aumid
                                : "shell:AppsFolder\\" + aumid;
                    }
                }
                else
                {
                    target = app.Target ?? "";
                    arguments = app.Arguments ?? "";
                    workingDirectory = app.WorkingDirectory ?? "";
                }

                if (string.IsNullOrWhiteSpace(target))
                    return LaunchLexDeskApp(app);

                if (target.StartsWith(
                        "ms-settings:",
                        StringComparison.OrdinalIgnoreCase))
                {
                    return await OpenLexDeskNativeWindowsSurfaceAsync(
                        target,
                        string.IsNullOrWhiteSpace(app.Name)
                            ? "Windows Settings"
                            : app.Name.Trim());
                }

                if (target.EndsWith(
                        ".exe",
                        StringComparison.OrdinalIgnoreCase))
                {
                    processName =
                        Path.GetFileNameWithoutExtension(target);

                    if (string.IsNullOrWhiteSpace(workingDirectory))
                    {
                        workingDirectory =
                            Path.GetDirectoryName(target) ?? "";
                    }
                }

                string[] processNames =
                    string.IsNullOrWhiteSpace(processName)
                        ? Array.Empty<string>()
                        : new[] { processName };

                string[] titleHints =
                    string.IsNullOrWhiteSpace(app.Name)
                        ? Array.Empty<string>()
                        : new[] { app.Name.Trim() };

                bool launched =
                    await LexDeskOpenManagedExternalAsync(
                        target,
                        string.IsNullOrWhiteSpace(app.Name)
                            ? processName
                            : app.Name.Trim(),
                        processNames,
                        titleHints,
                        Array.Empty<string>(),
                        pageIndex,
                        arguments,
                        workingDirectory);

                if (launched &&
                    target.EndsWith(".exe", StringComparison.OrdinalIgnoreCase))
                {
                    try
                    {
                        string normalizedTarget =
                            NormalizeLexDeskFirewallProgramPath(target);

                        LexDeskFirewallBlockedProgramInfo? blocked =
                            LoadLexDeskFirewallBlockedPrograms()
                                .FirstOrDefault(item =>
                                    string.Equals(
                                        NormalizeLexDeskFirewallProgramPath(item.ProgramPath),
                                        normalizedTarget,
                                        StringComparison.OrdinalIgnoreCase));

                        if (blocked != null)
                        {
                            WriteLexDeskFirewallProgramDebug(
                                $"MANAGED LAUNCH DETECTED FOR BLOCKED APP | name={app.Name} | path={normalizedTarget} | page={pageIndex}");

                            _ = CaptureLexDeskFirewallProgramLaunchDebugAsync(
                                blocked.RuleName,
                                normalizedTarget);
                        }
                    }
                    catch { }
                }

                return launched;
            }
            catch
            {
                // If Windows refuses managed positioning, preserve the old
                // reliable launch route rather than preventing the app opening.
                return LaunchLexDeskApp(app);
            }
        }


        private bool LaunchLexDeskApp(LexDeskInstalledApp app)
        {
            if (app == null)
                return false;

            // Forced stubborn-app launch.
            // Some apps, especially security suites, only open reliably from their real EXE path.
            if (TryGetLexDeskForcedLaunchOverride(
                    app,
                    out string forcedExe,
                    out string forcedWd,
                    out string forcedArgs,
                    out int cooldownMs,
                    out string key))
            {
                if (cooldownMs > 0)
                {
                    var now = DateTime.UtcNow;

                    if (_lexDeskForcedLastLaunchUtc.TryGetValue(key, out var last))
                    {
                        if ((now - last).TotalMilliseconds < cooldownMs)
                            return true;
                    }

                    _lexDeskForcedLastLaunchUtc[key] = now;
                }

                // For forced apps, do one known-good launch only.
                // Do not run fallback chains that may flash and die.
                return TryLaunchLexDeskViaCmdStart(forcedExe, forcedArgs, forcedWd);
            }

            switch (app.LaunchType)
            {
                case LexDeskLaunchType.Shortcut:
                    return LaunchLexDeskShortcutBestEffort(app);

                case LexDeskLaunchType.Exe:
                    return LaunchLexDeskExe(app);

                case LexDeskLaunchType.Aumid:
                    return LaunchLexDeskAumid(app);

                case LexDeskLaunchType.Fallback:
                default:
                    return TryLaunchLexDeskShell(app.Target);
            }
        }

        private bool IsLexDeskBitdefenderApp(
            LexDeskInstalledApp? app)
        {
            if (app == null)
                return false;

            return
                ContainsIgnoreCase(app.Name, "Bitdefender") ||
                ContainsIgnoreCase(app.Target, "seccenter.exe") ||
                ContainsIgnoreCase(app.ShortcutPath, "Bitdefender");
        }

        private bool IsLexDeskNativeSecurityPriorityTarget(
            string? target,
            string? friendlyName)
        {
            string combined =
                ((target ?? "") + " " + (friendlyName ?? ""))
                .Trim();

            if (string.IsNullOrWhiteSpace(combined))
                return false;

            return
                ContainsIgnoreCase(combined, "windowsdefender") ||
                ContainsIgnoreCase(combined, "windows security") ||
                ContainsIgnoreCase(combined, "microsoft defender");
        }

        private bool IsLexDeskSecurityPriorityApp(
            LexDeskInstalledApp? app)
        {
            if (app == null)
                return false;

            if (IsLexDeskBitdefenderApp(app))
                return true;

            string combined =
                ((app.Name ?? "") + " " +
                 (app.Target ?? "") + " " +
                 (app.ShortcutPath ?? ""))
                .Trim();

            if (IsLexDeskNativeSecurityPriorityTarget(
                    app.Target,
                    app.Name))
            {
                return true;
            }

            string[] securityMarkers =
            {
                "antivirus",
                "anti-virus",
                "internet security",
                "security suite",
                "endpoint security",
                "norton",
                "mcafee",
                "kaspersky",
                "malwarebytes",
                "avast",
                "avg antivirus",
                "eset",
                "trend micro",
                "sophos",
                "avira",
                "webroot",
                "f-secure",
                "panda dome",
                "zonealarm",
                "comodo",
                "totalav",
                "emsisoft",
                "g data"
            };

            return securityMarkers.Any(
                marker =>
                    ContainsIgnoreCase(
                        combined,
                        marker));
        }

        private bool TryGetLexDeskForcedLaunchOverride(
            LexDeskInstalledApp app,
            out string exe,
            out string wd,
            out string args,
            out int cooldownMs,
            out string key)
        {
            exe = "";
            wd = "";
            args = "";
            cooldownMs = 0;
            key = "";

            if (app == null)
                return false;

            args = app.Arguments ?? "";

            // ----------------------------
            // Bitdefender known-good path
            // ----------------------------
            const string bitdefenderExe =
                @"C:\Program Files\Bitdefender\Bitdefender Security App\seccenter.exe";

            const string bitdefenderWd =
                @"C:\Program Files\Bitdefender\Bitdefender Security App\";

            bool bitdefenderHit =
                IsLexDeskBitdefenderApp(app);

            if (bitdefenderHit && File.Exists(bitdefenderExe))
            {
                exe = bitdefenderExe;
                wd = bitdefenderWd;
                cooldownMs = 1500;
                key = bitdefenderExe.ToLowerInvariant();
                return true;
            }

            return false;
        }

        private bool LaunchLexDeskShortcutBestEffort(LexDeskInstalledApp app)
        {
            string shortcutPath = !string.IsNullOrWhiteSpace(app.ShortcutPath)
                ? app.ShortcutPath
                : app.Target;

            if (string.IsNullOrWhiteSpace(shortcutPath))
                return false;

            // First attempt: open the Start Menu shortcut directly.
            // This is the most compatible for most normal apps.
            if (TryLaunchLexDeskShell(shortcutPath))
                return true;

            // Second attempt: resolve .lnk target EXE + args + working directory.
            if (TryResolveLexDeskShortcutViaWScript(
                    shortcutPath,
                    out string exe,
                    out string args,
                    out string wd))
            {
                if (!string.IsNullOrWhiteSpace(app.Arguments))
                    args = app.Arguments;

                if (!string.IsNullOrWhiteSpace(app.WorkingDirectory))
                    wd = app.WorkingDirectory;

                if (string.IsNullOrWhiteSpace(wd))
                {
                    try
                    {
                        wd = Path.GetDirectoryName(exe) ?? "";
                    }
                    catch
                    {
                        wd = "";
                    }
                }

                if (TryLaunchLexDeskShell(exe, args, wd))
                    return true;

                if (TryLaunchLexDeskViaCmdStart(exe, args, wd))
                    return true;
            }

            return false;
        }

        private bool LaunchLexDeskExe(LexDeskInstalledApp app)
        {
            if (string.IsNullOrWhiteSpace(app.Target))
                return false;

            string args = app.Arguments ?? "";
            string wd = app.WorkingDirectory ?? "";

            if (string.IsNullOrWhiteSpace(wd))
            {
                try
                {
                    wd = Path.GetDirectoryName(app.Target) ?? "";
                }
                catch
                {
                    wd = "";
                }
            }

            if (TryLaunchLexDeskShell(app.Target, args, wd))
                return true;

            return TryLaunchLexDeskViaCmdStart(app.Target, args, wd);
        }

        private bool LaunchLexDeskAumid(LexDeskInstalledApp app)
        {
            string aumid = !string.IsNullOrWhiteSpace(app.Aumid)
                ? app.Aumid
                : app.Target;

            if (string.IsNullOrWhiteSpace(aumid))
                return false;

            string launchTarget = aumid.StartsWith("shell:AppsFolder\\", StringComparison.OrdinalIgnoreCase)
                ? aumid
                : "shell:AppsFolder\\" + aumid;

            return TryLaunchLexDeskShell(launchTarget);
        }

        private bool TryLaunchLexDeskShell(string target, string args = "", string workingDirectory = "")
        {
            try
            {
                if (string.IsNullOrWhiteSpace(target))
                    return false;

                var psi = string.IsNullOrWhiteSpace(args)
                    ? new ProcessStartInfo(target)
                    : new ProcessStartInfo(target, args);

                psi.UseShellExecute = true;

                if (!string.IsNullOrWhiteSpace(workingDirectory) &&
                    Directory.Exists(workingDirectory))
                {
                    psi.WorkingDirectory = workingDirectory;
                }

                Process.Start(psi);
                return true;
            }
            catch
            {
                return false;
            }
        }

        private bool TryLaunchLexDeskViaCmdStart(string target, string args = "", string workingDirectory = "")
        {
            try
            {
                if (string.IsNullOrWhiteSpace(target))
                    return false;

                string command = "start \"\" " + QuoteLexDeskCmd(target);

                if (!string.IsNullOrWhiteSpace(args))
                    command += " " + args;

                var psi = new ProcessStartInfo("cmd.exe")
                {
                    Arguments = "/c " + command,
                    UseShellExecute = false,
                    CreateNoWindow = true,
                    WindowStyle = ProcessWindowStyle.Hidden
                };

                if (!string.IsNullOrWhiteSpace(workingDirectory) &&
                    Directory.Exists(workingDirectory))
                {
                    psi.WorkingDirectory = workingDirectory;
                }

                Process.Start(psi);
                return true;
            }
            catch
            {
                return false;
            }
        }

        private string QuoteLexDeskCmd(string value)
        {
            value = (value ?? "").Trim();

            if (string.IsNullOrWhiteSpace(value))
                return "\"\"";

            value = value.Replace("\"", "\\\"");

            return "\"" + value + "\"";
        }

        private bool TryResolveLexDeskShortcutViaWScript(
            string shortcutPath,
            out string exe,
            out string args,
            out string workingDirectory)
        {
            exe = "";
            args = "";
            workingDirectory = "";

            try
            {
                if (string.IsNullOrWhiteSpace(shortcutPath) ||
                    !File.Exists(shortcutPath))
                    return false;

                Type? shellType = Type.GetTypeFromProgID("WScript.Shell");

                if (shellType == null)
                    return false;

                object? shell = Activator.CreateInstance(shellType);

                if (shell == null)
                    return false;

                dynamic dynamicShell = shell;
                dynamic shortcut = dynamicShell.CreateShortcut(shortcutPath);

                exe = shortcut.TargetPath as string ?? "";
                args = shortcut.Arguments as string ?? "";
                workingDirectory = shortcut.WorkingDirectory as string ?? "";

                try { System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shortcut); } catch { }
                try { System.Runtime.InteropServices.Marshal.FinalReleaseComObject(dynamicShell); } catch { }

                return !string.IsNullOrWhiteSpace(exe);
            }
            catch
            {
                return false;
            }
        }

        private bool ContainsIgnoreCase(string? value, string search)
        {
            if (string.IsNullOrWhiteSpace(value))
                return false;

            return value.IndexOf(search, StringComparison.OrdinalIgnoreCase) >= 0;
        }

