        private readonly DispatcherTimer _lexDeskClockTimer = new DispatcherTimer();

        private DateTime _lexDeskLastPowerStatusRefreshUtc =
            DateTime.MinValue;

        private void InitLexDeskBottomBar()
        {
            try
            {
                RefreshLexDeskClock();
                RefreshLexDeskPowerStatus();

                _lexDeskLastPowerStatusRefreshUtc =
                    DateTime.UtcNow;

                // Refresh the displayed clock regularly instead of relying
                // on one DispatcherTimer tick landing on the exact minute.
                _lexDeskClockTimer.Interval =
                    TimeSpan.FromSeconds(5);

                _lexDeskClockTimer.Tick += (_, __) =>
                {
                    RefreshLexDeskClock();

                    // Battery/WMI checks are more expensive, so keep those
                    // around once per minute instead of every five seconds.
                    DateTime utcNow =
                        DateTime.UtcNow;

                    if ((utcNow -
                         _lexDeskLastPowerStatusRefreshUtc) >=
                        TimeSpan.FromSeconds(55))
                    {
                        RefreshLexDeskPowerStatus();

                        _lexDeskLastPowerStatusRefreshUtc =
                            utcNow;
                    }
                };

                _lexDeskClockTimer.Start();
            }
            catch
            {
                // Bottom dock must never stop the app from opening.
            }
        }

        private void RefreshLexDeskClock()
        {
            try
            {
                if (LexDeskClockTimeText != null)
                    LexDeskClockTimeText.Text = DateTime.Now.ToString("h:mm tt");

                if (LexDeskClockDateText != null)
                    LexDeskClockDateText.Text = DateTime.Now.ToString("d/MM/yyyy");
            }
            catch { }
        }

        private void RefreshLexDeskPowerStatus()
        {
            try
            {
                bool hasBattery = TryGetBatteryPercentage(out int batteryPercent);

                if (LexDeskBatteryButton != null)
                {
                    LexDeskBatteryButton.Visibility = hasBattery
                        ? Visibility.Visible
                        : Visibility.Collapsed;

                    if (LexDeskBatteryPercentText != null)
                    {
                        LexDeskBatteryPercentText.Text = hasBattery
                            ? $"{batteryPercent}%"
                            : "";
                    }

                    LexDeskBatteryButton.ToolTip = hasBattery
                        ? $"Battery {batteryPercent}%"
                        : "Battery not detected";
                }

                if (LexDeskBatteryMenuButton != null)
                {
                    LexDeskBatteryMenuButton.Visibility = hasBattery
                        ? Visibility.Visible
                        : Visibility.Collapsed;

                    LexDeskBatteryMenuButton.Content = hasBattery
                        ? $"Power settings - Battery {batteryPercent}%"
                        : "Power settings";
                }
            }
            catch { }
        }

        private bool TryGetBatteryPercentage(out int percentage)
        {
            percentage = 0;

            try
            {
                using var searcher = new ManagementObjectSearcher(
                    "SELECT EstimatedChargeRemaining FROM Win32_Battery");

                foreach (ManagementBaseObject battery in searcher.Get())
                {
                    object? value = battery["EstimatedChargeRemaining"];

                    if (value == null)
                        continue;

                    if (int.TryParse(value.ToString(), out percentage))
                        return true;
                }
            }
            catch
            {
                // Desktop PCs often have no battery device.
            }

            return false;
        }

