        private void LexDeskLockPc_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;

            try
            {
                CloseLexDeskPowerMenus();

                if (!LockWorkStation())
                {
                    ShowLexDeskMessageBox(
                        "LexDesk could not lock this PC.",
                        "Lock PC",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);
                }
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk could not lock this PC.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "Lock PC",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
        }

        private void LexDeskSleepPc_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;

            try
            {
                CloseLexDeskPowerMenus();

                if (!LexDeskCanPowerOffNow())
                    return;

                if (!SetSuspendState(
                        hibernate: false,
                        forceCritical: false,
                        disableWakeEvent: false))
                {
                    ShowLexDeskMessageBox(
                        "Windows could not put this PC to sleep.",
                        "Sleep",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);
                }
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk could not put this PC to sleep.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "Sleep",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
        }

        private void LexDeskSignOutPc_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;

            try
            {
                CloseLexDeskPowerMenus();

                if (!LexDeskCanPowerOffNow())
                    return;

                var decision = ShowLexDeskMessageBox(
                    "Sign out of Windows now?\n\nSave any work in other programs first. Windows will close your open apps.",
                    "Sign Out",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Warning);

                if (decision != MessageBoxResult.Yes)
                    return;

                string shutdownExe = Path.Combine(
                    Environment.SystemDirectory,
                    "shutdown.exe");

                Process.Start(new ProcessStartInfo
                {
                    FileName = shutdownExe,
                    Arguments = "/l",
                    UseShellExecute = false,
                    CreateNoWindow = true
                });
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk could not sign out of Windows.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "Sign Out",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
        }

        private bool LexDeskCanPowerOffNow()
        {
            if (!_lexDeskMaintenanceBusy && !_lexDeskStage3Busy)
                return true;

            ShowLexDeskMessageBox(
                "LexDesk is still checking, repairing, scanning or cleaning Windows.\n\n" +
                "Wait for that job to finish before sleeping, signing out, restarting, or shutting down the PC.",
                "Please Wait",
                MessageBoxButton.OK,
                MessageBoxImage.Information);

            return false;
        }

