        private void LexDeskClockButton_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                bool opening = !LexDeskCalendarPopup.IsOpen;

                if (opening)
                {
                    LoadLexDeskCalendarEvents();

                    RefreshLexDeskCalendarNotificationStatus();

                    if (LexDeskCalendar.SelectedDate == null)
                        LexDeskCalendar.SelectedDate = DateTime.Today;

                    RefreshLexDeskCalendarEventsForSelectedDate();
                }

                LexDeskCalendarPopup.IsOpen = opening;
            }
            catch
            {
                // Calendar must never interfere with LexDesk opening or browsing.
            }
        }

        private void LexDeskCalendar_SelectedDatesChanged(
    object sender,
    SelectionChangedEventArgs e)
        {
            RefreshLexDeskCalendarEventsForSelectedDate();
        }

        private void RefreshLexDeskCalendarEventsForSelectedDate()
        {
            try
            {
                if (LexDeskCalendarEventsPanel == null ||
                    LexDeskCalendar == null)
                {
                    return;
                }

                LoadLexDeskCalendarEvents();

                DateTime selectedDate =
                    (LexDeskCalendar.SelectedDate ?? DateTime.Today).Date;

                if (LexDeskCalendarSelectedDateText != null)
                {
                    LexDeskCalendarSelectedDateText.Text =
                        selectedDate.ToString("dddd, d MMMM yyyy");
                }

                LexDeskCalendarEventsPanel.Children.Clear();

                var eventsForDay =
                    _lexDeskCalendarEvents
                        .Where(item => item.StartLocal.Date == selectedDate)
                        .OrderBy(item => item.StartLocal)
                        .ToList();

                if (eventsForDay.Count == 0)
                {
                    var emptyText = new TextBlock
                    {
                        Text = "No events for this day.",
                        FontSize = 13,
                        Margin = new Thickness(2, 8, 2, 0),
                        TextWrapping = TextWrapping.Wrap
                    };

                    emptyText.SetResourceReference(
                        TextBlock.ForegroundProperty,
                        "TextSecondary");

                    LexDeskCalendarEventsPanel.Children.Add(emptyText);
                    return;
                }

                foreach (LexDeskCalendarEvent calendarEvent in eventsForDay)
                {
                    var card = new Border
                    {
                        CornerRadius = new CornerRadius(9),
                        BorderThickness = new Thickness(1),
                        Padding = new Thickness(10),
                        Margin = new Thickness(0, 0, 0, 8)
                    };

                    card.SetResourceReference(
                        Border.BackgroundProperty,
                        "ButtonBg");

                    card.SetResourceReference(
                        Border.BorderBrushProperty,
                        "CardBorder");

                    var content = new StackPanel();
                    LexDeskCalendarEvent capturedEvent = calendarEvent;

                    string timeText =
                        calendarEvent.AllDay
                            ? "All day"
                            : calendarEvent.StartLocal.ToString("h:mm tt");

                    var time = new TextBlock
                    {
                        Text = timeText,
                        FontSize = 11,
                        FontWeight = FontWeights.SemiBold
                    };

                    time.SetResourceReference(
                        TextBlock.ForegroundProperty,
                        "TextSecondary");

                    var title = new TextBlock
                    {
                        Text = calendarEvent.Title,
                        FontSize = 14,
                        FontWeight = FontWeights.SemiBold,
                        TextWrapping = TextWrapping.Wrap,
                        Margin = new Thickness(0, 3, 0, 0)
                    };

                    title.SetResourceReference(
                        TextBlock.ForegroundProperty,
                        "TextPrimary");

                    content.Children.Add(time);
                    content.Children.Add(title);

                    if (!string.IsNullOrWhiteSpace(calendarEvent.Notes))
                    {
                        var notes = new TextBlock
                        {
                            Text = calendarEvent.Notes,
                            FontSize = 11,
                            TextWrapping = TextWrapping.Wrap,
                            Margin = new Thickness(0, 4, 0, 0)
                        };

                        notes.SetResourceReference(
                            TextBlock.ForegroundProperty,
                            "TextSecondary");

                        content.Children.Add(notes);
                    }

                    if (!string.IsNullOrWhiteSpace(calendarEvent.Link))
                    {
                        var openLink = new Button
                        {
                            Content = "Open Link",
                            Height = 28,
                            MinWidth = 82,
                            HorizontalAlignment = HorizontalAlignment.Left,
                            Margin = new Thickness(0, 7, 0, 0),
                            Padding = new Thickness(8, 0, 8, 0)
                        };

                        ApplyWebPrivacyButtonTheme(openLink);

                        openLink.Click += (_, __) =>
                            OpenLexDeskCalendarEventLink(capturedEvent);

                        content.Children.Add(openLink);
                    }

                    var eventButtons = new StackPanel
                    {
                        Orientation = Orientation.Horizontal,
                        HorizontalAlignment = HorizontalAlignment.Left,
                        Margin = new Thickness(0, 8, 0, 0)
                    };

                    var editButton = new Button
                    {
                        Content = "Edit",
                        Height = 28,
                        MinWidth = 68,
                        Padding = new Thickness(8, 0, 8, 0),
                        Margin = new Thickness(0, 0, 7, 0)
                    };

                    var deleteButton = new Button
                    {
                        Content = "Delete",
                        Height = 28,
                        MinWidth = 68,
                        Padding = new Thickness(8, 0, 8, 0)
                    };

                    ApplyWebPrivacyButtonTheme(editButton);
                    ApplyWebPrivacyButtonTheme(deleteButton);

                    editButton.Click += (_, __) =>
                        EditLexDeskCalendarEvent(capturedEvent);

                    deleteButton.Click += (_, __) =>
                        DeleteLexDeskCalendarEvent(capturedEvent);

                    eventButtons.Children.Add(editButton);
                    eventButtons.Children.Add(deleteButton);

                    content.Children.Add(eventButtons);

                    card.Child = content;

                    LexDeskCalendarEventsPanel.Children.Add(card);
                }
            }
            catch
            {
                // Calendar display must never affect the main app.
            }
        }

        internal void HandleLexDeskCalendarToastActivation(
    string action,
    string eventId)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(eventId))
                    return;

                LoadLexDeskCalendarEvents();

                LexDeskCalendarEvent? calendarEvent =
                    _lexDeskCalendarEvents
                        .FirstOrDefault(item =>
                            string.Equals(
                                item.Id,
                                eventId,
                                StringComparison.Ordinal));

                if (calendarEvent == null)
                    return;

                // Bring LexDesk back into view if Windows launched
                // or restored it from a calendar notification.
                if (!IsVisible)
                    Show();

                if (WindowState == WindowState.Minimized)
                    WindowState = WindowState.Normal;

                Activate();
                Focus();

                // A notification button can request that the saved
                // event link opens directly inside LexDesk.
                if (string.Equals(
                        action,
                        "openLink",
                        StringComparison.OrdinalIgnoreCase))
                {
                    string link =
                        (calendarEvent.Link ?? "").Trim();

                    if (Uri.TryCreate(
                            link,
                            UriKind.Absolute,
                            out Uri? uri) &&
                        (uri.Scheme == Uri.UriSchemeHttp ||
                         uri.Scheme == Uri.UriSchemeHttps))
                    {
                        LexDeskCalendarPopup.IsOpen = false;

                        NavigateTo(
                            uri.AbsoluteUri);

                        return;
                    }
                }

                // Normal notification click:
                // open LexDesk's calendar on the event date.
                LexDeskCalendar.SelectedDate =
                    calendarEvent.StartLocal.Date;

                RefreshLexDeskCalendarEventsForSelectedDate();

                LexDeskCalendarPopup.IsOpen = true;
            }
            catch
            {
                // Notification activation must never interfere
                // with LexDesk startup or normal browsing.
            }
        }

        private void OpenLexDeskCalendarEventLink(
     LexDeskCalendarEvent calendarEvent)
        {
            try
            {
                string link = (calendarEvent.Link ?? "").Trim();

                if (string.IsNullOrWhiteSpace(link))
                    return;

                if (!Uri.TryCreate(link, UriKind.Absolute, out Uri? uri) ||
                    (uri.Scheme != Uri.UriSchemeHttp &&
                     uri.Scheme != Uri.UriSchemeHttps))
                {
                    ShowLexDeskMessageBox(
                        "This event does not contain a valid web link.",
                        "Calendar",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);

                    return;
                }

                // Close the calendar and open the event link
                // inside the currently active LexDesk web page.
                LexDeskCalendarPopup.IsOpen = false;

                NavigateTo(uri.AbsoluteUri);
            }
            catch
            {
                ShowLexDeskMessageBox(
                    "LexDesk could not open this event link.",
                    "Calendar",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

        private void EditLexDeskCalendarEvent(
    LexDeskCalendarEvent calendarEvent)
        {
            if (calendarEvent == null)
                return;

            LoadLexDeskCalendarEvents();

            var dialog = new Window
            {
                Title = "Edit Calendar Event",
                Owner = this,
                Width = 560,
                Height = 650,
                ResizeMode = ResizeMode.NoResize,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                ShowInTaskbar = false
            };

            ApplyWebPrivacyDialogTheme(dialog);

            var outer = new Border
            {
                Margin = new Thickness(16),
                Padding = new Thickness(20),
                CornerRadius = new CornerRadius(12),
                BorderThickness = new Thickness(1)
            };

            outer.SetResourceReference(
                Border.BackgroundProperty,
                "CardBg");

            outer.SetResourceReference(
                Border.BorderBrushProperty,
                "CardBorder");

            var panel = new StackPanel
            {
                Margin = new Thickness(0, 0, 12, 0)
            };

            TextBlock MakeLabel(string text)
            {
                var label = new TextBlock
                {
                    Text = text,
                    FontSize = 12,
                    FontWeight = FontWeights.SemiBold,
                    Margin = new Thickness(0, 0, 0, 5)
                };

                label.SetResourceReference(
                    TextBlock.ForegroundProperty,
                    "TextPrimary");

                return label;
            }

            var heading = new TextBlock
            {
                Text = "Edit Event",
                FontSize = 20,
                FontWeight = FontWeights.SemiBold,
                Margin = new Thickness(0, 0, 0, 4)
            };

            heading.SetResourceReference(
                TextBlock.ForegroundProperty,
                "TextPrimary");

            var intro = new TextBlock
            {
                Text = "Change the details for this calendar event.",
                FontSize = 12,
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(0, 0, 0, 18)
            };

            intro.SetResourceReference(
                TextBlock.ForegroundProperty,
                "TextSecondary");

            panel.Children.Add(heading);
            panel.Children.Add(intro);

            panel.Children.Add(
                MakeLabel("Event name"));

            var titleBox = new TextBox
            {
                Text = calendarEvent.Title,
                Height = 32,
                Margin = new Thickness(0, 0, 0, 12)
            };

            ApplyWebPrivacyTextBoxTheme(titleBox);
            panel.Children.Add(titleBox);

            panel.Children.Add(
                MakeLabel("Date"));

            var datePicker = new DatePicker
            {
                SelectedDate = calendarEvent.StartLocal.Date,
                Height = 32,
                Margin = new Thickness(0, 0, 0, 12)
            };

            panel.Children.Add(datePicker);

            var allDayCheck = new CheckBox
            {
                Content = "All-day event",
                IsChecked = calendarEvent.AllDay,
                Margin = new Thickness(0, 0, 0, 10)
            };

            allDayCheck.SetResourceReference(
                Control.ForegroundProperty,
                "TextPrimary");

            panel.Children.Add(allDayCheck);

            panel.Children.Add(
                MakeLabel("Time"));

            var timeBox = new TextBox
            {
                Text = calendarEvent.StartLocal.ToString("HH:mm"),
                Height = 32,
                Margin = new Thickness(0, 0, 0, 12),
                ToolTip = "Enter a time such as 09:00 or 20:15."
            };

            ApplyWebPrivacyTextBoxTheme(timeBox);
            panel.Children.Add(timeBox);

            panel.Children.Add(
                MakeLabel("Notes"));

            var notesBox = new TextBox
            {
                Text = calendarEvent.Notes,
                Height = 72,
                AcceptsReturn = true,
                TextWrapping = TextWrapping.Wrap,
                VerticalScrollBarVisibility =
                    ScrollBarVisibility.Auto,
                Margin = new Thickness(0, 0, 0, 12)
            };

            ApplyWebPrivacyTextBoxTheme(notesBox);
            panel.Children.Add(notesBox);

            panel.Children.Add(
                MakeLabel("Web link (optional)"));

            var linkBox = new TextBox
            {
                Text = calendarEvent.Link,
                Height = 32,
                Margin = new Thickness(0, 0, 0, 12)
            };

            ApplyWebPrivacyTextBoxTheme(linkBox);
            panel.Children.Add(linkBox);

            var reminderCheck = new CheckBox
            {
                Content = "Remind me before this event",
                IsChecked = calendarEvent.ReminderEnabled,
                Margin = new Thickness(0, 0, 0, 8)
            };

            reminderCheck.SetResourceReference(
                Control.ForegroundProperty,
                "TextPrimary");

            panel.Children.Add(reminderCheck);

            var reminderCombo = new ComboBox
            {
                Height = 32,
                Margin = new Thickness(0, 0, 0, 18)
            };

            void AddReminderOption(
                string text,
                int minutes)
            {
                reminderCombo.Items.Add(
                    new ComboBoxItem
                    {
                        Content = text,
                        Tag = minutes
                    });
            }

            AddReminderOption(
                "At event time",
                0);

            AddReminderOption(
                "5 minutes before",
                5);

            AddReminderOption(
                "15 minutes before",
                15);

            AddReminderOption(
                "30 minutes before",
                30);

            AddReminderOption(
                "1 hour before",
                60);

            AddReminderOption(
                "2 hours before",
                120);

            AddReminderOption(
                "1 day before",
                1440);

            AddReminderOption(
                "2 days before",
                2880);

            AddReminderOption(
                "1 week before",
                10080);

            reminderCombo.SelectedIndex = 3;

            for (int i = 0;
                 i < reminderCombo.Items.Count;
                 i++)
            {
                if (reminderCombo.Items[i]
                        is ComboBoxItem item &&
                    item.Tag is int minutes &&
                    minutes ==
                        calendarEvent.ReminderMinutesBefore)
                {
                    reminderCombo.SelectedIndex = i;
                    break;
                }
            }

            reminderCombo.IsEnabled =
                reminderCheck.IsChecked == true;

            reminderCheck.Checked += (_, __) =>
                reminderCombo.IsEnabled = true;

            reminderCheck.Unchecked += (_, __) =>
                reminderCombo.IsEnabled = false;

            panel.Children.Add(reminderCombo);

            var buttons = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                HorizontalAlignment =
                    HorizontalAlignment.Right
            };

            var cancelButton = new Button
            {
                Content = "Cancel",
                Width = 90,
                Height = 34,
                Margin = new Thickness(0, 0, 8, 0),
                IsCancel = true
            };

            var saveButton = new Button
            {
                Content = "Save Changes",
                Width = 120,
                Height = 34,
                IsDefault = true
            };

            ApplyWebPrivacyButtonTheme(cancelButton);
            ApplyWebPrivacyButtonTheme(saveButton);

            cancelButton.Click += (_, __) =>
                dialog.Close();

            saveButton.Click += (_, __) =>
            {
                string title =
                    (titleBox.Text ?? "").Trim();

                if (string.IsNullOrWhiteSpace(title))
                {
                    ShowLexDeskMessageBox(
                        "Enter a name for the event.",
                        "Calendar",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);

                    titleBox.Focus();
                    return;
                }

                if (datePicker.SelectedDate == null)
                {
                    ShowLexDeskMessageBox(
                        "Choose a date for the event.",
                        "Calendar",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);

                    return;
                }

                bool allDay =
                    allDayCheck.IsChecked == true;

                TimeSpan eventTime =
                    TimeSpan.Zero;

                if (!allDay &&
                    !TimeSpan.TryParse(
                        (timeBox.Text ?? "").Trim(),
                        out eventTime))
                {
                    ShowLexDeskMessageBox(
                        "Enter the time as hours and minutes, for example 09:00 or 20:15.",
                        "Calendar",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);

                    timeBox.Focus();
                    return;
                }

                string link =
                    (linkBox.Text ?? "").Trim();

                if (!string.IsNullOrWhiteSpace(link))
                {
                    if (!Uri.TryCreate(
                            link,
                            UriKind.Absolute,
                            out Uri? linkUri) ||
                        (linkUri.Scheme !=
                             Uri.UriSchemeHttp &&
                         linkUri.Scheme !=
                             Uri.UriSchemeHttps))
                    {
                        ShowLexDeskMessageBox(
                            "Enter a full web link beginning with http:// or https://.",
                            "Calendar",
                            MessageBoxButton.OK,
                            MessageBoxImage.Information);

                        linkBox.Focus();
                        return;
                    }

                    link =
                        linkUri.AbsoluteUri;
                }

                int reminderMinutes = 30;

                if (reminderCombo.SelectedItem
                        is ComboBoxItem selectedReminder &&
                    selectedReminder.Tag
                        is int selectedMinutes)
                {
                    reminderMinutes =
                        selectedMinutes;
                }

                DateTime eventDate =
                    datePicker.SelectedDate.Value.Date;

                DateTime startLocal =
                    allDay
                        ? eventDate
                        : eventDate.Add(eventTime);

                // Keep the old values in case saving fails.
                string oldTitle =
                    calendarEvent.Title;

                DateTime oldStartLocal =
                    calendarEvent.StartLocal;

                bool oldAllDay =
                    calendarEvent.AllDay;

                string oldNotes =
                    calendarEvent.Notes;

                string oldLink =
                    calendarEvent.Link;

                bool oldReminderEnabled =
                    calendarEvent.ReminderEnabled;

                int oldReminderMinutes =
                    calendarEvent.ReminderMinutesBefore;

                calendarEvent.Title =
                    title;

                calendarEvent.StartLocal =
                    startLocal;

                calendarEvent.AllDay =
                    allDay;

                calendarEvent.Notes =
                    (notesBox.Text ?? "").Trim();

                calendarEvent.Link =
                    link;

                calendarEvent.ReminderEnabled =
                    reminderCheck.IsChecked == true;

                calendarEvent.ReminderMinutesBefore =
                    reminderMinutes;

                if (!SaveLexDeskCalendarEvents())
                {
                    // Put everything back exactly as it was.
                    calendarEvent.Title =
                        oldTitle;

                    calendarEvent.StartLocal =
                        oldStartLocal;

                    calendarEvent.AllDay =
                        oldAllDay;

                    calendarEvent.Notes =
                        oldNotes;

                    calendarEvent.Link =
                        oldLink;

                    calendarEvent.ReminderEnabled =
                        oldReminderEnabled;

                    calendarEvent.ReminderMinutesBefore =
                        oldReminderMinutes;

                    ShowLexDeskMessageBox(
                        "LexDesk could not save the changes to this event.",
                        "Calendar",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);

                    return;
                }

                // The edited event is safely stored.

                // Editing the date, time or reminder creates a fresh
                // reminder opportunity for this event.
                _lexDeskInAppReminderShown.Remove(
                    calendarEvent.Id);

                if (string.Equals(
                        _lexDeskInAppReminderEventId,
                        calendarEvent.Id,
                        StringComparison.Ordinal))
                {
                    HideLexDeskInAppCalendarReminder();
                }

                // Remove any old Windows scheduled reminder.
                CancelLexDeskCalendarReminder(
                    calendarEvent);

                if (calendarEvent.ReminderEnabled &&
                    calendarEvent.StartLocal > DateTime.Now)
                {
                    bool reminderScheduled =
                        ScheduleLexDeskCalendarReminder(
                            calendarEvent);

                    if (calendarEvent.ReminderEnabled)
                    {
                        WarnIfLexDeskCalendarRemindersUnavailable();
                    }

                    if (!reminderScheduled)
                    {
                        ShowLexDeskMessageBox(
                            "The event changes were saved, but Windows could not schedule its reminder.\n\n" +
                            "The event is still safely stored in your LexDesk calendar.",
                            "Calendar Reminder",
                            MessageBoxButton.OK,
                            MessageBoxImage.Warning);
                    }
                }

                LexDeskCalendar.SelectedDate =
                    calendarEvent.StartLocal.Date;

                RefreshLexDeskCalendarEventsForSelectedDate();

                dialog.DialogResult = true;
                dialog.Close();
            };

            buttons.Children.Add(
                cancelButton);

            buttons.Children.Add(
                saveButton);

            panel.Children.Add(
                buttons);

            var scroll = new ScrollViewer
            {
                VerticalScrollBarVisibility =
                    ScrollBarVisibility.Auto,
                HorizontalScrollBarVisibility =
                    ScrollBarVisibility.Disabled
            };

            scroll.Content = panel;

            outer.Child = scroll;
            dialog.Content = outer;

            dialog.ShowDialog();
        }

        private void DeleteLexDeskCalendarEvent(
    LexDeskCalendarEvent calendarEvent)
        {
            try
            {
                if (calendarEvent == null)
                    return;

                MessageBoxResult answer =
                    ShowLexDeskMessageBox(
                        $"Delete \"{calendarEvent.Title}\"?\n\n" +
                        "This event will be permanently removed from your LexDesk calendar.",
                        "Delete Calendar Event",
                        MessageBoxButton.YesNo,
                        MessageBoxImage.Warning);

                if (answer != MessageBoxResult.Yes)
                    return;

                int originalIndex =
                    _lexDeskCalendarEvents.IndexOf(calendarEvent);

                if (originalIndex < 0)
                    return;

                _lexDeskCalendarEvents.RemoveAt(originalIndex);

                if (!SaveLexDeskCalendarEvents())
                {
                    _lexDeskCalendarEvents.Insert(
                        originalIndex,
                        calendarEvent);

                    ShowLexDeskMessageBox(
                        "LexDesk could not delete this calendar event.",
                        "Calendar",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);

                    return;
                }

                // The event is safely removed from storage,
                // so its Windows reminder can now be removed too.
                CancelLexDeskCalendarReminder(calendarEvent);

                RefreshLexDeskCalendarEventsForSelectedDate();
            }
            catch
            {
                ShowLexDeskMessageBox(
                    "LexDesk could not delete this calendar event.",
                    "Calendar",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
        }

        private void LexDeskCalendarAddEvent_Click(
    object sender,
    RoutedEventArgs e)
        {
            LoadLexDeskCalendarEvents();

            DateTime selectedDate =
                (LexDeskCalendar.SelectedDate ?? DateTime.Today).Date;

            var dialog = new Window
            {
                Title = "Add Calendar Event",
                Owner = this,
                Width = 560,
                Height = 650,
                ResizeMode = ResizeMode.NoResize,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                ShowInTaskbar = false
            };

            ApplyWebPrivacyDialogTheme(dialog);

            var outer = new Border
            {
                Margin = new Thickness(16),
                Padding = new Thickness(20),
                CornerRadius = new CornerRadius(12),
                BorderThickness = new Thickness(1)
            };

            outer.SetResourceReference(
                Border.BackgroundProperty,
                "CardBg");

            outer.SetResourceReference(
                Border.BorderBrushProperty,
                "CardBorder");

            var panel = new StackPanel
            {
                Margin = new Thickness(0, 0, 12, 0)
            };

            TextBlock MakeLabel(string text)
            {
                var label = new TextBlock
                {
                    Text = text,
                    FontSize = 12,
                    FontWeight = FontWeights.SemiBold,
                    Margin = new Thickness(0, 0, 0, 5)
                };

                label.SetResourceReference(
                    TextBlock.ForegroundProperty,
                    "TextPrimary");

                return label;
            }

            var heading = new TextBlock
            {
                Text = "Add Event",
                FontSize = 20,
                FontWeight = FontWeights.SemiBold,
                Margin = new Thickness(0, 0, 0, 4)
            };

            heading.SetResourceReference(
                TextBlock.ForegroundProperty,
                "TextPrimary");

            var intro = new TextBlock
            {
                Text = "Save an appointment, task or reminder to your LexDesk calendar.",
                FontSize = 12,
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(0, 0, 0, 18)
            };

            intro.SetResourceReference(
                TextBlock.ForegroundProperty,
                "TextSecondary");

            panel.Children.Add(heading);
            panel.Children.Add(intro);

            panel.Children.Add(MakeLabel("Event name"));

            var titleBox = new TextBox
            {
                Height = 32,
                Margin = new Thickness(0, 0, 0, 12)
            };

            ApplyWebPrivacyTextBoxTheme(titleBox);
            panel.Children.Add(titleBox);

            panel.Children.Add(MakeLabel("Date"));

            var datePicker = new DatePicker
            {
                SelectedDate = selectedDate,
                Height = 32,
                Margin = new Thickness(0, 0, 0, 12)
            };

            panel.Children.Add(datePicker);

            var allDayCheck = new CheckBox
            {
                Content = "All-day event",
                IsChecked = false,
                Margin = new Thickness(0, 0, 0, 10)
            };

            allDayCheck.SetResourceReference(
                Control.ForegroundProperty,
                "TextPrimary");

            panel.Children.Add(allDayCheck);

            panel.Children.Add(MakeLabel("Time"));

            var timeBox = new TextBox
            {
                Text = "09:00",
                Height = 32,
                Margin = new Thickness(0, 0, 0, 12),
                ToolTip = "Enter a time such as 09:00 or 14:30."
            };

            ApplyWebPrivacyTextBoxTheme(timeBox);
            panel.Children.Add(timeBox);

            panel.Children.Add(MakeLabel("Notes"));

            var notesBox = new TextBox
            {
                Height = 72,
                AcceptsReturn = true,
                TextWrapping = TextWrapping.Wrap,
                VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
                Margin = new Thickness(0, 0, 0, 12)
            };

            ApplyWebPrivacyTextBoxTheme(notesBox);
            panel.Children.Add(notesBox);

            panel.Children.Add(MakeLabel("Web link (optional)"));

            var linkBox = new TextBox
            {
                Height = 32,
                Margin = new Thickness(0, 0, 0, 12)
            };

            ApplyWebPrivacyTextBoxTheme(linkBox);
            panel.Children.Add(linkBox);

            var reminderCheck = new CheckBox
            {
                Content = "Remind me before this event",
                IsChecked = true,
                Margin = new Thickness(0, 0, 0, 8)
            };

            reminderCheck.SetResourceReference(
                Control.ForegroundProperty,
                "TextPrimary");

            panel.Children.Add(reminderCheck);

            var reminderCombo = new ComboBox
            {
                Height = 32,
                Margin = new Thickness(0, 0, 0, 18)
            };

            void AddReminderOption(string text, int minutes)
            {
                reminderCombo.Items.Add(
                    new ComboBoxItem
                    {
                        Content = text,
                        Tag = minutes
                    });
            }

            AddReminderOption("At event time", 0);
            AddReminderOption("5 minutes before", 5);
            AddReminderOption("15 minutes before", 15);
            AddReminderOption("30 minutes before", 30);
            AddReminderOption("1 hour before", 60);
            AddReminderOption("2 hours before", 120);
            AddReminderOption("1 day before", 1440);
            AddReminderOption("2 days before", 2880);
            AddReminderOption("1 week before", 10080);

            reminderCombo.SelectedIndex = 3;

            reminderCheck.Checked += (_, __) =>
                reminderCombo.IsEnabled = true;

            reminderCheck.Unchecked += (_, __) =>
                reminderCombo.IsEnabled = false;

            panel.Children.Add(reminderCombo);

            var buttons = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                HorizontalAlignment = HorizontalAlignment.Right
            };

            var cancelButton = new Button
            {
                Content = "Cancel",
                Width = 90,
                Height = 34,
                Margin = new Thickness(0, 0, 8, 0),
                IsCancel = true
            };

            var saveButton = new Button
            {
                Content = "Save Event",
                Width = 110,
                Height = 34,
                IsDefault = true
            };

            ApplyWebPrivacyButtonTheme(cancelButton);
            ApplyWebPrivacyButtonTheme(saveButton);

            cancelButton.Click += (_, __) =>
                dialog.Close();

            saveButton.Click += (_, __) =>
            {
                string title =
                    (titleBox.Text ?? "").Trim();

                if (string.IsNullOrWhiteSpace(title))
                {
                    ShowLexDeskMessageBox(
                        "Enter a name for the event.",
                        "Calendar",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);

                    titleBox.Focus();
                    return;
                }

                if (datePicker.SelectedDate == null)
                {
                    ShowLexDeskMessageBox(
                        "Choose a date for the event.",
                        "Calendar",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);

                    return;
                }

                bool allDay =
                    allDayCheck.IsChecked == true;

                TimeSpan eventTime = TimeSpan.Zero;

                if (!allDay &&
                    !TimeSpan.TryParse(
                        (timeBox.Text ?? "").Trim(),
                        out eventTime))
                {
                    ShowLexDeskMessageBox(
                        "Enter the time as hours and minutes, for example 09:00 or 14:30.",
                        "Calendar",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);

                    timeBox.Focus();
                    return;
                }

                string link =
                    (linkBox.Text ?? "").Trim();

                if (!string.IsNullOrWhiteSpace(link))
                {
                    if (!Uri.TryCreate(
                            link,
                            UriKind.Absolute,
                            out Uri? linkUri) ||
                        (linkUri.Scheme != Uri.UriSchemeHttp &&
                         linkUri.Scheme != Uri.UriSchemeHttps))
                    {
                        ShowLexDeskMessageBox(
                            "Enter a full web link beginning with http:// or https://.",
                            "Calendar",
                            MessageBoxButton.OK,
                            MessageBoxImage.Information);

                        linkBox.Focus();
                        return;
                    }

                    link = linkUri.AbsoluteUri;
                }

                int reminderMinutes = 30;

                if (reminderCombo.SelectedItem is ComboBoxItem selectedReminder &&
                    selectedReminder.Tag is int selectedMinutes)
                {
                    reminderMinutes = selectedMinutes;
                }

                DateTime eventDate =
                    datePicker.SelectedDate.Value.Date;

                DateTime startLocal =
                    allDay
                        ? eventDate
                        : eventDate.Add(eventTime);

                var newEvent = new LexDeskCalendarEvent
                {
                    Id = Guid.NewGuid().ToString("N"),
                    Title = title,
                    StartLocal = startLocal,
                    AllDay = allDay,
                    Notes = (notesBox.Text ?? "").Trim(),
                    Link = link,
                    ReminderEnabled =
                        reminderCheck.IsChecked == true,
                    ReminderMinutesBefore =
                        reminderMinutes
                };

                _lexDeskCalendarEvents.Add(newEvent);

                if (!SaveLexDeskCalendarEvents())
                {
                    _lexDeskCalendarEvents.Remove(newEvent);

                    ShowLexDeskMessageBox(
                        "LexDesk could not save this calendar event.",
                        "Calendar",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);

                    return;
                }

                // The event is safely stored.
                // Now ask Windows to remember its reminder.
                bool reminderScheduled =
                    ScheduleLexDeskCalendarReminder(newEvent);

                if (newEvent.ReminderEnabled &&
                    !reminderScheduled)
                {
                    ShowLexDeskMessageBox(
                        "The event was saved, but Windows could not schedule its reminder.\n\n" +
                        "The event is still safely stored in your LexDesk calendar.",
                        "Calendar Reminder",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);
                }

                if (newEvent.ReminderEnabled)
                {
                    WarnIfLexDeskCalendarRemindersUnavailable();
                }

                LexDeskCalendar.SelectedDate =
                    newEvent.StartLocal.Date;

                RefreshLexDeskCalendarEventsForSelectedDate();

                dialog.DialogResult = true;
                dialog.Close();
            };

            buttons.Children.Add(cancelButton);
            buttons.Children.Add(saveButton);

            panel.Children.Add(buttons);

            var scroll = new ScrollViewer
            {
                VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
                HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled
            };

            scroll.Content = panel;

            outer.Child = scroll;
            dialog.Content = outer;

            dialog.ShowDialog();
        }

