        // ============================================================
        // LexDesk Pro - Stage 7 Local PC Search
        // Uses the Windows Search index. Nothing typed here is sent to the web.
        // ============================================================

        private void LexDeskPcSearchBox_TextChanged(object sender, TextChangedEventArgs e)
        {
            try
            {
                if (LexDeskPcSearchPlaceholderText != null && LexDeskPcSearchBox != null)
                {
                    LexDeskPcSearchPlaceholderText.Visibility =
                        string.IsNullOrWhiteSpace(LexDeskPcSearchBox.Text)
                            ? Visibility.Visible
                            : Visibility.Collapsed;
                }
            }
            catch { }
        }

        private void LexDeskPcSearchBox_KeyDown(object sender, System.Windows.Input.KeyEventArgs e)
        {
            if (e.Key == System.Windows.Input.Key.Enter)
            {
                e.Handled = true;
                RunLexDeskPcSearch();
                return;
            }

            if (e.Key == System.Windows.Input.Key.Escape)
            {
                e.Handled = true;

                try
                {
                    LexDeskPcSearchBox?.Clear();
                }
                catch { }
            }
        }

        private void LexDeskPcSearchButton_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;
            RunLexDeskPcSearch();
        }

        private async void RunLexDeskPcSearch()
        {
            string query = "";

            try
            {
                query =
                    LexDeskPcSearchBox?.Text?.Trim() ??
                    "";
            }
            catch { }

            if (string.IsNullOrWhiteSpace(query))
            {
                UpdateSecurityStatus(
                    "Type what you want to find on this PC",
                    false);

                try
                {
                    LexDeskPcSearchBox?.Focus();
                }
                catch { }

                return;
            }

            string normalized =
                query.Trim().ToLowerInvariant();

            try
            {
                // ========================================================
                // Windows tools that are intentionally hidden from the
                // normal LexDesk Apps panel can still be found explicitly.
                // ========================================================

                if (normalized == "cmd" ||
                    normalized == "command prompt")
                {
                    await LexDeskOpenManagedExternalAsync(
                        "cmd.exe",
                        "Command Prompt",
                        new[]
                        {
                    "cmd",
                    "WindowsTerminal",
                    "OpenConsole"
                        },
                        new[]
                        {
                    "Command Prompt"
                        },
                        new[]
                        {
                    "ConsoleWindowClass",
                    "CASCADIA_HOSTING_WINDOW_CLASS"
                        });

                    return;
                }

                if (normalized == "taskmgr" ||
    normalized == "task manager")
                {
                    await LexDeskOpenManagedExternalAsync(
                        "taskmgr.exe",
                        "Task Manager",
                        new[] { "Taskmgr" },
                        new[] { "Task Manager" },
                        Array.Empty<string>());

                    return;
                }

                // ========================================================
                // Power-user Windows tools
                // Hidden from the normal Grandma-friendly Apps panel,
                // but available when the user deliberately searches for them.
                // ========================================================

                if (normalized == "powershell" ||
                    normalized == "windows powershell")
                {
                    LexDeskOpenExternal(
                        "powershell.exe");

                    UpdateSecurityStatus(
                        "Opened Windows PowerShell",
                        false);

                    return;
                }

                if (normalized == "regedit" ||
                    normalized == "registry editor")
                {
                    LexDeskOpenExternal(
                        "regedit.exe");

                    UpdateSecurityStatus(
                        "Opened Registry Editor",
                        false);

                    return;
                }

                if (normalized == "services" ||
                    normalized == "services.msc")
                {
                    LexDeskOpenExternal(
                        "services.msc");

                    UpdateSecurityStatus(
                        "Opened Windows Services",
                        false);

                    return;
                }

                if (normalized == "event viewer" ||
                    normalized == "eventvwr" ||
                    normalized == "eventvwr.msc")
                {
                    LexDeskOpenExternal(
                        "eventvwr.msc");

                    UpdateSecurityStatus(
                        "Opened Event Viewer",
                        false);

                    return;
                }

                if (normalized == "device manager" ||
                    normalized == "devmgmt" ||
                    normalized == "devmgmt.msc")
                {
                    LexDeskOpenExternal(
                        "devmgmt.msc");

                    UpdateSecurityStatus(
                        "Opened Device Manager",
                        false);

                    return;
                }

                if (normalized == "disk management" ||
                    normalized == "diskmgmt" ||
                    normalized == "diskmgmt.msc")
                {
                    LexDeskOpenExternal(
                        "diskmgmt.msc");

                    UpdateSecurityStatus(
                        "Opened Disk Management",
                        false);

                    return;
                }

                if (normalized == "system information" ||
                    normalized == "msinfo32")
                {
                    LexDeskOpenExternal(
                        "msinfo32.exe");

                    UpdateSecurityStatus(
                        "Opened System Information",
                        false);

                    return;
                }

                if (normalized == "resource monitor" ||
                    normalized == "resmon")
                {
                    LexDeskOpenExternal(
                        "resmon.exe");

                    UpdateSecurityStatus(
                        "Opened Resource Monitor",
                        false);

                    return;
                }

                if (normalized == "control panel" ||
                    normalized == "control")
                {
                    LexDeskOpenExternal(
                        "control.exe");

                    UpdateSecurityStatus(
                        "Opened Control Panel",
                        false);

                    return;
                }

                // ========================================================
                // Built-in LexDesk dock apps
                // ========================================================

                if (normalized == "explorer" ||
                    normalized == "file explorer" ||
                    normalized == "files")
                {
                    await LexDeskOpenManagedExternalAsync(
                        "explorer.exe",
                        "File Explorer",
                        new[] { "explorer" },
                        Array.Empty<string>(),
                        new[] { "CabinetWClass" });

                    return;
                }

                if (normalized == "notepad")
                {
                    await LexDeskOpenManagedExternalAsync(
                        "notepad.exe",
                        "Notepad",
                        new[] { "notepad" },
                        new[] { "Notepad" },
                        Array.Empty<string>());

                    return;
                }

                if (normalized == "calculator" ||
                    normalized == "calc")
                {
                    await LexDeskOpenManagedExternalAsync(
                        "calc.exe",
                        "Calculator",
                        new[]
                        {
                    "CalculatorApp",
                    "Calculator"
                        },
                        new[] { "Calculator" },
                        Array.Empty<string>());

                    return;
                }

                if (normalized == "settings" ||
                    normalized == "windows settings")
                {
                    await LexDeskOpenManagedExternalAsync(
                        "ms-settings:",
                        "Windows Settings",
                        new[]
                        {
                    "SystemSettings",
                    "ApplicationFrameHost"
                        },
                        new[] { "Settings" },
                        Array.Empty<string>());

                    return;
                }

                if (normalized == "downloads" ||
                    normalized == "download")
                {
                    string downloads =
                        Path.Combine(
                            Environment.GetFolderPath(
                                Environment.SpecialFolder.UserProfile),
                            "Downloads");

                    if (Directory.Exists(downloads))
                    {
                        await LexDeskOpenManagedExternalAsync(
                            downloads,
                            "Downloads",
                            new[] { "explorer" },
                            new[] { "Downloads" },
                            new[] { "CabinetWClass" });

                        return;
                    }
                }

                // Bitdefender has historically required its
                // known-good executable launch route.
                if (normalized == "bitdefender")
                {
                    var bitdefenderApp =
                        new LexDeskInstalledApp
                        {
                            Name = "Bitdefender"
                        };

                    if (await LaunchLexDeskAppManagedAsync(
                            bitdefenderApp,
                            GetLexDeskPreferredManagedPageIndex()))
                    {
                        UpdateSecurityStatus(
                            "Opened Bitdefender",
                            false);

                        return;
                    }
                }

                // ========================================================
                // Installed applications already known to LexDesk
                // ========================================================

                var apps =
    await GetLexDeskInstalledAppsCachedAsync(
        false);

                var appMatches =
                    (apps ??
                     new List<LexDeskInstalledApp>())
                    .Where(app =>
                        app != null &&
                        !string.IsNullOrWhiteSpace(app.Name) &&
                        app.Name.IndexOf(
                            query,
                            StringComparison.OrdinalIgnoreCase) >= 0)
                    .OrderByDescending(app =>
                        app.Name.Equals(
                            query,
                            StringComparison.OrdinalIgnoreCase))
                    .ThenByDescending(app =>
                        app.Name.StartsWith(
                            query,
                            StringComparison.OrdinalIgnoreCase))
                    .ThenBy(app =>
                        app.Name.Length)
                    .ThenBy(app =>
                        app.Name,
                        StringComparer.OrdinalIgnoreCase)
                    .ToList();

                LexDeskInstalledApp? appToLaunch =
                    null;

                // 1. Exact app name always wins.
                appToLaunch =
                    appMatches.FirstOrDefault(app =>
                        app.Name.Equals(
                            query,
                            StringComparison.OrdinalIgnoreCase));

                // 2. Prefer a known forced-launch app.
                // This catches stubborn apps such as Bitdefender.
                if (appToLaunch == null)
                {
                    foreach (LexDeskInstalledApp candidate
                             in appMatches)
                    {
                        if (TryGetLexDeskForcedLaunchOverride(
                                candidate,
                                out _,
                                out _,
                                out _,
                                out _,
                                out _))
                        {
                            appToLaunch =
                                candidate;

                            break;
                        }
                    }
                }

                // 3. One ordinary result is safe to launch.
                if (appToLaunch == null &&
                    appMatches.Count == 1)
                {
                    appToLaunch =
                        appMatches[0];
                }

                if (appToLaunch != null)
                {
                    bool launched =
                        await LaunchLexDeskAppManagedAsync(
                            appToLaunch,
                            GetLexDeskPreferredManagedPageIndex());

                    if (launched)
                    {
                        RecordLexDeskAppLaunch(
                            appToLaunch);

                        UpdateSecurityStatus(
                            $"Opened {appToLaunch.Name}",
                            false);

                        return;
                    }
                }

                // ========================================================
                // Files / folders / documents
                // Uses the local Windows Search index.
                // ========================================================

                string encodedQuery =
                    Uri.EscapeDataString(query);

                string target =
                    $"search-ms:query={encodedQuery}" +
                    "&displayname=LexDesk%20PC%20Search";

                // Force each new query through the managed-window finder.
                // Windows itself may reuse the existing Search Results HWND.
                _lexDeskManagedWindows.Remove(
                    "PC Search");

                await LexDeskOpenManagedExternalAsync(
                    target,
                    "PC Search",
                    new[] { "explorer" },
                    new[]
                    {
                "Search Results",
                "Search"
                    },
                    new[] { "CabinetWClass" });
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk could not search this PC.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "Search This PC",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

        // ============================================================
        // LexDesk Pro - Managed Windows Workspace
        // Positions selected Windows apps inside LexDesk's centre area.
        // ============================================================

        private delegate bool LexDeskEnumWindowsProc(
            IntPtr hWnd,
            IntPtr lParam);

        [DllImport("user32.dll")]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool EnumWindows(
            LexDeskEnumWindowsProc lpEnumFunc,
            IntPtr lParam);

        [DllImport("user32.dll")]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool IsWindowVisible(
            IntPtr hWnd);

        [DllImport("user32.dll")]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool IsWindow(
            IntPtr hWnd);

        [DllImport("user32.dll")]
        private static extern uint GetWindowThreadProcessId(
            IntPtr hWnd,
            out uint lpdwProcessId);

        [DllImport("user32.dll", CharSet = CharSet.Unicode)]
        private static extern int GetWindowText(
            IntPtr hWnd,
            StringBuilder lpString,
            int nMaxCount);

        [DllImport("user32.dll", CharSet = CharSet.Unicode)]
        private static extern int GetClassName(
            IntPtr hWnd,
            StringBuilder lpClassName,
            int nMaxCount);

        [DllImport("user32.dll")]
        private static extern IntPtr GetForegroundWindow();

        [DllImport("user32.dll")]
