        [StructLayout(LayoutKind.Sequential)]
        private struct LexDeskWindowRect
        {
            public int Left;
            public int Top;
            public int Right;
            public int Bottom;
        }

        private const int GWLP_HWNDPARENT = -8;
        private const uint GW_OWNER = 4;

        private const uint SWP_NOSIZE = 0x0001;
        private const uint SWP_NOMOVE = 0x0002;
        private const uint SWP_NOZORDER = 0x0004;
        private const uint SWP_NOACTIVATE = 0x0010;

        private static readonly IntPtr LexDeskHwndTopmost =
            new IntPtr(-1);

        private static readonly IntPtr LexDeskHwndNotTopmost =
            new IntPtr(-2);
        private const uint SWP_SHOWWINDOW = 0x0040;

        private const int LexDeskSwRestore = 9;
        private const int LexDeskSwMinimizeWindow = 6;
        private const uint LexDeskWmClose = 0x0010;

        private const int LexDeskSwMinimize = 6;

        private HashSet<IntPtr> GetLexDeskVisibleTopLevelWindows()
        {
            var windows = new HashSet<IntPtr>();

            try
            {
                EnumWindows((hWnd, _) =>
                {
                    try
                    {
                        if (hWnd != IntPtr.Zero &&
                            IsWindowVisible(hWnd))
                        {
                            windows.Add(hWnd);
                        }
                    }
                    catch { }

                    return true;
                }, IntPtr.Zero);
            }
            catch { }

            return windows;
        }

        private void WriteLexDeskElevatedManagedToolResult(
    string text)
        {
            try
            {
                string? folder =
                    Path.GetDirectoryName(
                        _lexDeskElevatedManagedToolResultPath);

                if (!string.IsNullOrWhiteSpace(folder))
                    Directory.CreateDirectory(folder);

                File.WriteAllText(
                    _lexDeskElevatedManagedToolResultPath,
                    text ?? "ERROR|Unknown elevated managed-tool result");
            }
            catch
            {
                // Helper reporting must never crash LexDesk.
            }
        }

        private bool TryRunElevatedManagedToolHelperFromCommandLine()
        {
            string[] args =
                Environment.GetCommandLineArgs();

            int helperIndex =
                Array.FindIndex(
                    args,
                    a => string.Equals(
                        a,
                        "--managed-tool-helper",
                        StringComparison.OrdinalIgnoreCase));

            if (helperIndex < 0)
                return false;

            try
            {
                if (!IsRunningAsAdmin())
                {
                    WriteLexDeskElevatedManagedToolResult(
                        "ERROR|Windows administrator permission was not granted.");

                    return true;
                }

                if (helperIndex + 5 >= args.Length)
                {
                    WriteLexDeskElevatedManagedToolResult(
                        "ERROR|Managed-tool helper arguments were incomplete.");

                    return true;
                }

                string toolKey =
                    args[helperIndex + 1];

                if (!int.TryParse(
                        args[helperIndex + 2],
                        out int left) ||
                    !int.TryParse(
                        args[helperIndex + 3],
                        out int top) ||
                    !int.TryParse(
                        args[helperIndex + 4],
                        out int width) ||
                    !int.TryParse(
                        args[helperIndex + 5],
                        out int height))
                {
                    WriteLexDeskElevatedManagedToolResult(
                        "ERROR|Managed-tool window bounds were invalid.");

                    return true;
                }

                if (width < 250 ||
                    height < 200)
                {
                    WriteLexDeskElevatedManagedToolResult(
                        "ERROR|Managed-tool window bounds were too small.");

                    return true;
                }

                string target;
                string[] expectedProcessNames;
                string[] titleHints;
                string[] classHints;

                switch (toolKey.Trim().ToLowerInvariant())
                {
                    case "regedit":

                        target =
                            "regedit.exe";

                        expectedProcessNames =
                            new[]
                            {
                        "regedit"
                            };

                        titleHints =
                            new[]
                            {
                        "Registry Editor"
                            };

                        classHints =
                            new[]
                            {
                        "RegEdit_RegEdit"
                            };

                        break;

                    case "eventviewer":

                        target =
                            "eventvwr.msc";

                        expectedProcessNames =
                            Array.Empty<string>();

                        titleHints =
                            new[]
                            {
            "Event Viewer"
                            };

                        classHints =
                            new[]
                            {
            "MMCMainFrame"
                            };

                        break;

                    case "diskmanagement":

                        target =
                            "diskmgmt.msc";

                        expectedProcessNames =
                            Array.Empty<string>();

                        titleHints =
                            new[]
                            {
            "Disk Management"
                            };

                        classHints =
                            new[]
                            {
            "MMCMainFrame"
                            };

                        break;

                    case "taskscheduler":

                        target =
                            "taskschd.msc";

                        expectedProcessNames =
                            Array.Empty<string>();

                        titleHints =
                            new[]
                            {
            "Task Scheduler"
                            };

                        classHints =
                            new[]
                            {
            "MMCMainFrame"
                            };

                        break;

                    case "advancedfirewall":

                        target =
                            "wf.msc";

                        expectedProcessNames =
                            Array.Empty<string>();

                        titleHints =
                            new[]
                            {
            "Windows Defender Firewall with Advanced Security",
            "Firewall with Advanced Security",
            "Advanced Security"
                            };

                        classHints =
                            new[]
                            {
            "MMCMainFrame"
                            };

                        break;

                    default:

                        WriteLexDeskElevatedManagedToolResult(
                            "ERROR|The requested elevated Windows tool is not allowed.");

                        return true;
                }

                HashSet<IntPtr> windowsBeforeLaunch =
                    GetLexDeskVisibleTopLevelWindows();

                Process.Start(
                    new ProcessStartInfo(target)
                    {
                        UseShellExecute = true
                    });

                for (int attempt = 0;
                     attempt < 50;
                     attempt++)
                {
                    System.Threading.Thread.Sleep(
                        attempt == 0
                            ? 250
                            : 100);

                    IntPtr hWnd =
                        FindLexDeskManagedWindow(
                            windowsBeforeLaunch,
                            expectedProcessNames,
                            titleHints,
                            classHints);

                    if (hWnd == IntPtr.Zero)
                        continue;

                    ShowWindow(
                        hWnd,
                        LexDeskSwRestore);

                    bool positioned =
                        MoveWindow(
                            hWnd,
                            left,
                            top,
                            width,
                            height,
                            true);

                    if (!positioned)
                    {
                        positioned =
                            SetWindowPos(
                                hWnd,
                                IntPtr.Zero,
                                left,
                                top,
                                width,
                                height,
                                SWP_NOZORDER |
                                SWP_NOACTIVATE |
                                SWP_SHOWWINDOW);
                    }

                    if (!positioned)
                        continue;

                    SetForegroundWindow(
                        hWnd);

                    WriteLexDeskElevatedManagedToolResult(
                        $"OK|{hWnd.ToInt64()}");

                    return true;
                }

                WriteLexDeskElevatedManagedToolResult(
                    "ERROR|LexDesk could not find or position the elevated Windows tool.");

                return true;
            }
            catch (Exception ex)
            {
                string safeMessage =
                    (ex.Message ??
                     "Elevated managed-tool helper failed")
                    .Replace("\r", " ")
                    .Replace("\n", " ")
                    .Trim();

                WriteLexDeskElevatedManagedToolResult(
                    "ERROR|" + safeMessage);

                return true;
            }
        }

        private async Task<IntPtr> RunLexDeskElevatedManagedToolAsync(
    string toolKey,
    string friendlyName,
    int pageIndex)
        {
            if (_lexDeskManagedLaunchesInProgress.Contains(
                    friendlyName))
            {
                return IntPtr.Zero;
            }

            _lexDeskManagedLaunchesInProgress.Add(
                friendlyName);

            try
            {
                if (!TryGetLexDeskManagedPaneScreenBounds(
                        pageIndex,
                        out int left,
                        out int top,
                        out int width,
                        out int height))
                {
                    UpdateSecurityStatus(
                        $"{friendlyName} could not find the selected Page area",
                        true);

                    return IntPtr.Zero;
                }

                try
                {
                    if (File.Exists(
                            _lexDeskElevatedManagedToolResultPath))
                    {
                        File.Delete(
                            _lexDeskElevatedManagedToolResultPath);
                    }
                }
                catch { }

                string exePath =
                    Process.GetCurrentProcess()
                        .MainModule?
                        .FileName ?? "";

                if (string.IsNullOrWhiteSpace(
                        exePath))
                {
                    UpdateSecurityStatus(
                        $"LexDesk could not start {friendlyName}",
                        true);

                    return IntPtr.Zero;
                }

                string arguments =
                    $"--managed-tool-helper " +
                    $"{toolKey} " +
                    $"{left} " +
                    $"{top} " +
                    $"{width} " +
                    $"{height}";

                ProcessStartInfo psi =
                    new()
                    {
                        FileName =
                            exePath,

                        Arguments =
                            arguments,

                        UseShellExecute =
                            true,

                        Verb =
                            "runas"
                    };

                Process? helper;

                try
                {
                    helper =
                        Process.Start(
                            psi);
                }
                catch (System.ComponentModel.Win32Exception)
                {
                    UpdateSecurityStatus(
                        "Administrator permission was cancelled",
                        false);

                    return IntPtr.Zero;
                }

                if (helper == null)
                {
                    UpdateSecurityStatus(
                        $"Windows could not start {friendlyName}",
                        true);

                    return IntPtr.Zero;
                }

                using (helper)
                {
                    await helper.WaitForExitAsync();
                }

                if (!File.Exists(
                        _lexDeskElevatedManagedToolResultPath))
                {
                    UpdateSecurityStatus(
                        $"{friendlyName} did not return a result",
                        true);

                    return IntPtr.Zero;
                }

                string result =
                    (File.ReadAllText(
                        _lexDeskElevatedManagedToolResultPath) ??
                     "")
                    .Trim();

                try
                {
                    File.Delete(
                        _lexDeskElevatedManagedToolResultPath);
                }
                catch { }

                if (!result.StartsWith(
                        "OK|",
                        StringComparison.OrdinalIgnoreCase))
                {
                    string message =
                        result.StartsWith(
                            "ERROR|",
                            StringComparison.OrdinalIgnoreCase)
                            ? result.Substring(
                                "ERROR|".Length)
                            : "The elevated Windows tool could not be positioned.";

                    UpdateSecurityStatus(
                        message,
                        true);

                    return IntPtr.Zero;
                }

                string hwndText =
                    result.Substring(
                        "OK|".Length);

                if (!long.TryParse(
                        hwndText,
                        out long hwndValue))
                {
                    return IntPtr.Zero;
                }

                IntPtr hWnd =
                    new IntPtr(
                        hwndValue);

                if (hWnd == IntPtr.Zero ||
                    !IsWindow(hWnd))
                {
                    return IntPtr.Zero;
                }

                RegisterLexDeskManagedSessionMainWindow(
                    friendlyName,
                    hWnd,
                    pageIndex,
                    Array.Empty<string>(),
                    new[] { friendlyName },
                    new[] { GetLexDeskWindowClass(hWnd) });

                _lexDeskLastManagedWindowKey =
                    friendlyName;

                UpdateSecurityStatus(
                    $"{friendlyName} opened in LexDesk workspace",
                    false);

                return hWnd;
            }
            catch (Exception ex)
            {
                UpdateSecurityStatus(
                    $"Could not open {friendlyName}: " +
                    SanitizeExceptionMessage(ex),
                    true);

                return IntPtr.Zero;
            }
            finally
            {
                _lexDeskManagedLaunchesInProgress.Remove(
                    friendlyName);
            }
        }

        private string GetLexDeskWindowTitle(
            IntPtr hWnd)
        {
            try
            {
                var text = new StringBuilder(512);

                GetWindowText(
                    hWnd,
                    text,
                    text.Capacity);

                return text.ToString().Trim();
            }
            catch
            {
                return "";
            }
        }

        private string GetLexDeskWindowClass(
            IntPtr hWnd)
        {
            try
            {
                var text = new StringBuilder(256);

                GetClassName(
                    hWnd,
                    text,
                    text.Capacity);

                return text.ToString().Trim();
            }
            catch
            {
                return "";
            }
        }

        private string GetLexDeskWindowProcessName(
            IntPtr hWnd)
        {
            try
            {
                GetWindowThreadProcessId(
                    hWnd,
                    out uint processId);

                if (processId == 0)
                    return "";

                using var process =
                    Process.GetProcessById(
                        (int)processId);

                return process.ProcessName ?? "";
            }
            catch
            {
                return "";
            }
        }

        private string DescribeLexDeskManagedWindowForDebug(
            IntPtr hWnd)
        {
            try
            {
                if (hWnd == IntPtr.Zero)
                    return "HWND=0x0";

                bool alive =
                    IsWindow(hWnd);

                if (!alive)
                    return $"HWND=0x{hWnd.ToInt64():X} | alive=False";

                bool visible =
                    IsWindowVisible(hWnd);

                bool iconic =
                    IsIconic(hWnd);

                GetWindowThreadProcessId(
                    hWnd,
                    out uint processId);

                string processName =
                    GetLexDeskWindowProcessName(hWnd);

                string className =
                    GetLexDeskWindowClass(hWnd);

                string title =
                    GetLexDeskWindowTitle(hWnd);

                IntPtr owner =
                    GetWindow(
                        hWnd,
                        GW_OWNER);

                string rectText =
                    "rect=unknown";

                if (GetWindowRect(
                        hWnd,
                        out LexDeskWindowRect rect))
                {
                    int width =
                        Math.Max(
                            0,
                            rect.Right -
                            rect.Left);

                    int height =
                        Math.Max(
                            0,
                            rect.Bottom -
                            rect.Top);

                    rectText =
                        $"rect={rect.Left},{rect.Top},{width},{height}";
                }

                return
                    $"HWND=0x{hWnd.ToInt64():X} | " +
                    $"alive=True | visible={visible} | iconic={iconic} | " +
                    $"PID={processId} | PROCESS={processName} | " +
                    $"CLASS={className} | TITLE={title} | " +
                    $"{rectText} | OWNER=0x{owner.ToInt64():X}";
            }
            catch (Exception ex)
            {
                return
                    $"HWND=0x{hWnd.ToInt64():X} | " +
                    $"describe_failed={ex.GetType().Name}";
            }
        }

        private string DescribeLexDeskManagedProcessForDebug(
            string key)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(key) ||
                    !_lexDeskManagedWindowIdentities.TryGetValue(
                        key,
                        out LexDeskManagedWindowIdentity? identity) ||
                    identity.MainProcessId == 0)
                {
                    return "process=unknown";
                }

                try
                {
                    using Process process =
                        Process.GetProcessById(
                            (int)identity.MainProcessId);

                    return
                        $"process_alive={!process.HasExited} | " +
                        $"tracked_pid={identity.MainProcessId} | " +
                        $"tracked_process={process.ProcessName}";
                }
                catch
                {
                    return
                        $"process_alive=False | " +
                        $"tracked_pid={identity.MainProcessId}";
                }
            }
            catch
            {
                return "process=unknown";
            }
        }

        private void DumpLexDeskManagedSessionState(
            string reason)
        {
            if (!LexDeskDeveloperDiagnosticsEnabled)
                return;

            try
            {
                List<int> visiblePanes =
                    VisiblePanes();

                IntPtr foreground =
                    GetForegroundWindow();

                WriteLexDeskManagedWindowDebug(
                    "============================================================");

                WriteLexDeskManagedWindowDebug(
                    $"STATE SNAPSHOT | reason={reason}");

                WriteLexDeskManagedWindowDebug(
                    $"LAYOUT | visible=[{string.Join(",", visiblePanes.Select(i => i + 1))}] | " +
                    $"count={visiblePanes.Count} | layoutPageCount={_layoutPageCount} | " +
                    $"active={_activePageIndex + 1} | " +
                    $"maxMode={_isPaneMaximizedMode} | " +
                    $"maxPane={(_maximizedPane >= 0 ? (_maximizedPane + 1).ToString() : "none")} | " +
                    $"PagesHostVisibility={PagesHost?.Visibility} | " +
                    $"PagesHostIsVisible={PagesHost?.IsVisible} | " +
                    $"PagesHostSize={PagesHost?.ActualWidth:0}x{PagesHost?.ActualHeight:0}");

                WriteLexDeskManagedWindowDebug(
                    $"FOREGROUND | {DescribeLexDeskManagedWindowForDebug(foreground)}");

                string paneOwners =
                    _lexDeskManagedPaneOwners.Count == 0
                        ? "(none)"
                        : string.Join(
                            " | ",
                            _lexDeskManagedPaneOwners
                                .OrderBy(pair => pair.Key)
                                .Select(pair =>
                                    $"P{pair.Key + 1}={pair.Value}"));

                WriteLexDeskManagedWindowDebug(
                    $"PANE OWNERS | {paneOwners}");

                var allKeys =
                    _lexDeskManagedWindows.Keys
                        .Concat(
                            _lexDeskManagedWindowPageIndexes.Keys)
                        .Concat(
                            _lexDeskManagedWindowFamilies.Keys)
                        .Distinct(
                            StringComparer.OrdinalIgnoreCase)
                        .OrderBy(key => key)
                        .ToList();

                if (allKeys.Count == 0)
                {
                    WriteLexDeskManagedWindowDebug(
                        "SESSIONS | (none)");

                    return;
                }

                foreach (string key in allKeys)
                {
                    int pageIndex =
                        _lexDeskManagedWindowPageIndexes.TryGetValue(
                            key,
                            out int savedPageIndex)
                            ? savedPageIndex
                            : -1;

                    IntPtr mainHwnd =
                        _lexDeskManagedWindows.TryGetValue(
                            key,
                            out IntPtr savedMain)
                            ? savedMain
                            : IntPtr.Zero;

                    int familyCount =
                        _lexDeskManagedWindowFamilies.TryGetValue(
                            key,
                            out HashSet<IntPtr>? family)
                            ? family.Count
                            : 0;

                    bool nativeShell =
                        _lexDeskManagedNativeShellSessions.Contains(
                            key);

                    bool liveSession =
                        LexDeskManagedSessionHasLiveWindow(
                            key);

                    string desiredBounds =
                        "desired=unavailable";

                    if (pageIndex >= 0 &&
                        pageIndex <= 3 &&
                        TryGetLexDeskManagedPaneScreenBounds(
                            pageIndex,
                            out int left,
                            out int top,
                            out int width,
                            out int height))
                    {
                        desiredBounds =
                            $"desired={left},{top},{width},{height}";
                    }

                    WriteLexDeskManagedWindowDebug(
                        $"SESSION | app={key} | " +
                        $"page={(pageIndex >= 0 ? (pageIndex + 1).ToString() : "none")} | " +
                        $"live={liveSession} | nativeShell={nativeShell} | " +
                        $"familyCount={familyCount} | {desiredBounds} | " +
                        $"{DescribeLexDeskManagedProcessForDebug(key)}");

                    WriteLexDeskManagedWindowDebug(
                        $"  MAIN | {DescribeLexDeskManagedWindowForDebug(mainHwnd)}");

                    if (family != null)
                    {
                        foreach (IntPtr familyHwnd in
                                 family
                                     .Where(hWnd => hWnd != mainHwnd)
                                     .ToList())
                        {
                            WriteLexDeskManagedWindowDebug(
                                $"  FAMILY | {DescribeLexDeskManagedWindowForDebug(familyHwnd)}");
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                WriteLexDeskManagedWindowDebug(
                    "STATE SNAPSHOT FAILED | " +
                    ex.GetType().Name +
                    " | " +
                    ex.Message);
            }
        }

        private void QueueLexDeskManagedSessionStateDump(
            string reason)
        {
            if (!LexDeskDeveloperDiagnosticsEnabled)
                return;

            try
            {
                Dispatcher.BeginInvoke(
                    new Action(
                        () =>
                            DumpLexDeskManagedSessionState(
                                reason)),
                    DispatcherPriority.ContextIdle);
            }
            catch
            {
                // Diagnostics must never affect LexDesk.
            }
        }

        private bool IsLexDeskWindowDwmCloaked(
            IntPtr hWnd)
        {
            try
            {
                if (hWnd == IntPtr.Zero ||
                    !IsWindow(hWnd))
                {
                    return false;
                }

                int cloaked = 0;

                int result =
                    DwmGetWindowAttribute(
                        hWnd,
                        LexDeskDwmaCloaked,
                        out cloaked,
                        sizeof(int));

                return result == 0 &&
                       cloaked != 0;
            }
            catch
            {
                return false;
            }
        }

        private string DescribeLexDeskDwmStateForDebug(
            IntPtr hWnd)
        {
            try
            {
                if (hWnd == IntPtr.Zero ||
                    !IsWindow(hWnd))
                {
                    return "dwm_cloaked=unknown";
                }

                int cloaked = 0;

                int result =
                    DwmGetWindowAttribute(
                        hWnd,
                        LexDeskDwmaCloaked,
                        out cloaked,
                        sizeof(int));

                return
                    result == 0
                        ? $"dwm_cloaked={cloaked}"
                        : $"dwm_cloaked_error={result}";
            }
            catch (Exception ex)
            {
                return $"dwm_cloaked_error={ex.GetType().Name}";
            }
        }

        private int GetLexDeskTopLevelZOrderRankForDebug(
            IntPtr target)
        {
            if (target == IntPtr.Zero ||
                !IsWindow(target))
            {
                return -1;
            }

            int rank = 0;
            int found = -1;

            try
            {
                EnumWindows((hWnd, _) =>
                {
                    if (hWnd == target)
                    {
                        found = rank;
                        return false;
                    }

                    rank++;
                    return true;
                }, IntPtr.Zero);
            }
            catch
            {
                return -1;
            }

            return found;
        }

        private string DescribeLexDeskNativeWindowForDebug(
            IntPtr hWnd)
        {
            try
            {
                string basic =
                    DescribeLexDeskManagedWindowForDebug(
                        hWnd);

                int zRank =
                    GetLexDeskTopLevelZOrderRankForDebug(
                        hWnd);

                bool inAssist =
                    _lexDeskManagedZOrderAssistWindows.Contains(
                        hWnd);

                string familyKey =
                    _lexDeskManagedWindowFamilyKeys.TryGetValue(
                        hWnd,
                        out string? key)
                            ? key
                            : "(none)";

                return
                    basic +
                    $" | zRank={zRank}" +
                    $" | assist={inAssist}" +
                    $" | family={familyKey}" +
                    $" | {DescribeLexDeskDwmStateForDebug(hWnd)}";
            }
            catch
            {
                return DescribeLexDeskManagedWindowForDebug(hWnd);
            }
        }

        private void DumpLexDeskWindowsHostedSurfaceState(
            string reason)
        {
            if (!LexDeskDeveloperDiagnosticsEnabled)
                return;

            try
            {
                WriteLexDeskManagedWindowDebug(
                    "---------------- WINDOWS HOSTED SURFACE SNAPSHOT ----------------");

                WriteLexDeskManagedWindowDebug(
                    $"HOSTED SNAPSHOT | reason={reason}");

                IntPtr lexDeskHwnd =
                    new WindowInteropHelper(this).Handle;

                WriteLexDeskManagedWindowDebug(
                    $"LEXDESK HOST | {DescribeLexDeskNativeWindowForDebug(lexDeskHwnd)}");

                IntPtr foreground =
                    GetForegroundWindow();

                WriteLexDeskManagedWindowDebug(
                    $"HOSTED FOREGROUND | {DescribeLexDeskNativeWindowForDebug(foreground)}");

                EnumWindows((hWnd, _) =>
                {
                    try
                    {
                        if (hWnd == IntPtr.Zero ||
                            !IsWindow(hWnd))
                        {
                            return true;
                        }

                        string processName =
                            GetLexDeskWindowProcessName(hWnd);

                        string title =
                            GetLexDeskWindowTitle(hWnd);

                        bool relevantProcess =
                            processName.Equals(
                                "ApplicationFrameHost",
                                StringComparison.OrdinalIgnoreCase) ||
                            processName.Equals(
                                "SystemSettings",
                                StringComparison.OrdinalIgnoreCase) ||
                            processName.Equals(
                                "CalculatorApp",
                                StringComparison.OrdinalIgnoreCase) ||
                            processName.Equals(
                                "Calculator",
                                StringComparison.OrdinalIgnoreCase) ||
                            processName.Equals(
                                "SecHealthUI",
                                StringComparison.OrdinalIgnoreCase);

                        bool relevantTitle =
                            title.Contains(
                                "Settings",
                                StringComparison.OrdinalIgnoreCase) ||
                            title.Contains(
                                "Calculator",
                                StringComparison.OrdinalIgnoreCase) ||
                            title.Contains(
                                "Windows Security",
                                StringComparison.OrdinalIgnoreCase);

                        if (!relevantProcess &&
                            !relevantTitle)
                        {
                            return true;
                        }

                        WriteLexDeskManagedWindowDebug(
                            $"HOSTED WINDOW | {DescribeLexDeskNativeWindowForDebug(hWnd)}");
                    }
                    catch { }

                    return true;
                }, IntPtr.Zero);

                foreach (var pair in
                         _lexDeskManagedWindows
                             .OrderBy(pair => pair.Key)
                             .ToList())
                {
                    bool nativeShell =
                        _lexDeskManagedNativeShellSessions.Contains(
                            pair.Key);

                    int page =
                        _lexDeskManagedWindowPageIndexes.TryGetValue(
                            pair.Key,
                            out int pageIndex)
                            ? pageIndex + 1
                            : 0;

                    WriteLexDeskManagedWindowDebug(
                        $"TRACKED MAIN | app={pair.Key} | " +
                        $"nativeShell={nativeShell} | " +
                        $"page={(page > 0 ? page.ToString() : "none")} | " +
                        $"{DescribeLexDeskNativeWindowForDebug(pair.Value)}");
                }
            }
            catch (Exception ex)
            {
                WriteLexDeskManagedWindowDebug(
                    $"HOSTED SNAPSHOT FAILED | {ex.GetType().Name} | {ex.Message}");
            }
        }

        private void QueueLexDeskWindowsHostedSurfaceStateDump(
            string reason)
        {
            if (!LexDeskDeveloperDiagnosticsEnabled)
                return;

            try
            {
                Dispatcher.BeginInvoke(
                    new Action(
                        () =>
                            DumpLexDeskWindowsHostedSurfaceState(
                                reason)),
                    DispatcherPriority.ContextIdle);
            }
            catch
            {
                // Diagnostics must never affect LexDesk.
            }
        }

        private void WriteLexDeskManagedWindowDebug(
    string message)
        {
            if (!LexDeskDeveloperDiagnosticsEnabled)
                return;

            try
            {
                string? folder =
                    Path.GetDirectoryName(
                        _lexDeskManagedWindowDebugLogPath);

                if (!string.IsNullOrWhiteSpace(folder))
                    Directory.CreateDirectory(folder);

                string line =
                    $"[{DateTime.Now:HH:mm:ss.fff}] {message}";

                Debug.WriteLine(line);

                File.AppendAllText(
                    _lexDeskManagedWindowDebugLogPath,
                    line + Environment.NewLine);
            }
            catch
            {
                // Diagnostics must never affect LexDesk.
            }
        }

        private void DumpLexDeskManagedWindowCandidates(
            string label,
            HashSet<IntPtr> windowsBeforeLaunch,
            string[] expectedProcessNames,
            string[] titleHints,
            string[] classHints)
        {
            if (!LexDeskDeveloperDiagnosticsEnabled)
                return;

            try
            {
                IntPtr foreground =
                    GetForegroundWindow();

                WriteLexDeskManagedWindowDebug(
                    $"========== {label} ==========");

                EnumWindows((hWnd, _) =>
                {
                    try
                    {
                        if (hWnd == IntPtr.Zero ||
                            !IsWindowVisible(hWnd))
                        {
                            return true;
                        }

                        GetWindowThreadProcessId(
                            hWnd,
                            out uint processId);

                        string processName =
                            GetLexDeskWindowProcessName(
                                hWnd);

                        string title =
                            GetLexDeskWindowTitle(
                                hWnd);

                        string className =
                            GetLexDeskWindowClass(
                                hWnd);

                        bool processMatch =
                            expectedProcessNames.Any(
                                expected =>
                                    !string.IsNullOrWhiteSpace(expected) &&
                                    processName.Equals(
                                        expected,
                                        StringComparison.OrdinalIgnoreCase));

                        bool titleMatch =
                            titleHints.Any(
                                hint =>
                                    !string.IsNullOrWhiteSpace(hint) &&
                                    title.Contains(
                                        hint,
                                        StringComparison.OrdinalIgnoreCase));

                        bool classMatch =
                            classHints.Any(
                                hint =>
                                    !string.IsNullOrWhiteSpace(hint) &&
                                    className.Equals(
                                        hint,
                                        StringComparison.OrdinalIgnoreCase));

                        bool isNew =
                            !windowsBeforeLaunch.Contains(
                                hWnd);

                        bool isForeground =
                            hWnd == foreground;

                        // During managed-app debugging also log every newly
                        // created or foreground window, even if our expected
                        // process/title hints failed to match it. That tells us
                        // which real HWND/process Windows handed the app to.
                        if (!processMatch &&
                            !titleMatch &&
                            !classMatch &&
                            !isNew &&
                            !isForeground)
                        {
                            return true;
                        }

                        string cleanTitle =
                            (title ?? "")
                            .Replace("\r", " ")
                            .Replace("\n", " ");

                        WriteLexDeskManagedWindowDebug(
                            $"HWND=0x{hWnd.ToInt64():X} | " +
                            $"PID={processId} | " +
                            $"PROCESS={processName} | " +
                            $"CLASS={className} | " +
                            $"TITLE={cleanTitle} | " +
                            $"NEW={isNew} | " +
                            $"FOREGROUND={isForeground} | " +
                            $"PROCESS_MATCH={processMatch} | " +
                            $"CLASS_MATCH={classMatch} | " +
                            $"TITLE_MATCH={titleMatch}");
                    }
                    catch { }

                    return true;

                }, IntPtr.Zero);
            }
            catch { }
        }


        private IntPtr FindLexDeskManagedWindow(
    HashSet<IntPtr> windowsBeforeLaunch,
    string[] expectedProcessNames,
    string[] titleHints,
    string[] classHints)
        {
            IntPtr bestWindow = IntPtr.Zero;
            int bestScore = int.MinValue;

            IntPtr foreground =
                GetForegroundWindow();

            int lexDeskProcessId =
                Environment.ProcessId;

            try
            {
                EnumWindows((hWnd, _) =>
                {
                    try
                    {
                        if (hWnd == IntPtr.Zero ||
                            !IsWindowVisible(hWnd))
                        {
                            return true;
                        }

                        GetWindowThreadProcessId(
                            hWnd,
                            out uint processId);

                        if (processId == 0 ||
                            processId == lexDeskProcessId)
                        {
                            return true;
                        }

                        string processName =
                            GetLexDeskWindowProcessName(
                                hWnd);

                        string title =
                            GetLexDeskWindowTitle(
                                hWnd);

                        string className =
                            GetLexDeskWindowClass(
                                hWnd);

                        // Office briefly creates an MsoSplash window and destroys it
                        // before the real application window exists. Never register that
                        // transient splash as the managed app (Excel was doing exactly this).
                        bool transientLaunchWindow =
                            className.Equals(
                                "MsoSplash",
                                StringComparison.OrdinalIgnoreCase) ||
                            title.StartsWith(
                                "Opening - ",
                                StringComparison.OrdinalIgnoreCase);

                        if (transientLaunchWindow)
                        {
                            WriteLexDeskManagedWindowDebug(
                                $"TRANSIENT WINDOW SKIPPED | HWND=0x{hWnd.ToInt64():X} | " +
                                $"PROCESS={processName} | CLASS={className} | TITLE={title}");

                            return true;
                        }

                        // Never treat the Windows desktop,
                        // taskbar or shell worker windows as
                        // a LexDesk-managed application.
                        if (className.Equals(
                                "Shell_TrayWnd",
                                StringComparison.OrdinalIgnoreCase) ||
                            className.Equals(
                                "Shell_SecondaryTrayWnd",
                                StringComparison.OrdinalIgnoreCase) ||
                            className.Equals(
                                "Progman",
                                StringComparison.OrdinalIgnoreCase) ||
                            className.Equals(
                                "WorkerW",
                                StringComparison.OrdinalIgnoreCase))
                        {
                            return true;
                        }

                        bool processMatch =
                            expectedProcessNames.Any(
                                expected =>
                                    !string.IsNullOrWhiteSpace(expected) &&
                                    processName.Equals(
                                        expected,
                                        StringComparison.OrdinalIgnoreCase));

                        bool titleMatch =
                            titleHints.Any(
                                hint =>
                                    !string.IsNullOrWhiteSpace(hint) &&
                                    title.Contains(
                                        hint,
                                        StringComparison.OrdinalIgnoreCase));

                        bool classMatch =
                            classHints.Any(
                                hint =>
                                    !string.IsNullOrWhiteSpace(hint) &&
                                    className.Equals(
                                        hint,
                                        StringComparison.OrdinalIgnoreCase));

                        bool isNew =
                            !windowsBeforeLaunch.Contains(
                                hWnd);

                        bool isForeground =
                            hWnd == foreground;

                        // It still has to resemble the app
                        // we are looking for.
                        if (!processMatch &&
                            !titleMatch &&
                            !classMatch)
                        {
                            return true;
                        }

                        // Critical:
                        // Do not grab an old background window
                        // merely because it shares explorer.exe
                        // or another Windows host process.
                        //
                        // Prefer a genuinely NEW window.
                        // An existing window is accepted only if
                        // Windows itself has just foregrounded it.
                        if (!isNew &&
                            !isForeground)
                        {
                            return true;
                        }

                        int score = 0;

                        if (isNew)
                            score += 200;

                        if (isForeground)
                            score += 150;

                        if (classMatch)
                            score += 120;

                        if (titleMatch)
                            score += 100;

                        if (processMatch)
                            score += 60;

                        if (!string.IsNullOrWhiteSpace(title))
                            score += 10;

                        if (score > bestScore)
                        {
                            bestScore = score;
                            bestWindow = hWnd;
                        }
                    }
                    catch
                    {
                        // One weird Windows window should not
                        // stop managed workspace detection.
                    }

                    return true;

                }, IntPtr.Zero);
            }
            catch { }

            return bestWindow;
        }

        private bool TryGetLexDeskWorkspaceScreenBounds(
            out int left,
            out int top,
            out int width,
            out int height)
        {
            left = 0;
            top = 0;
            width = 0;
            height = 0;

            try
            {
                if (MainContentHost == null ||
                    MainContentHost.ActualWidth <= 0 ||
                    MainContentHost.ActualHeight <= 0)
                {
                    return false;
                }

                Point topLeft =
                    MainContentHost.PointToScreen(
                        new Point(0, 0));

                Point bottomRight =
                    MainContentHost.PointToScreen(
                        new Point(
                            MainContentHost.ActualWidth,
                            MainContentHost.ActualHeight));

                // Small breathing room around managed windows.
                const int inset = 0;

                left =
                    (int)Math.Round(topLeft.X) +
                    inset;

                top =
                    (int)Math.Round(topLeft.Y) +
                    inset;

                width =
                    (int)Math.Round(
                        bottomRight.X -
                        topLeft.X) -
                    (inset * 2);

                height =
                    (int)Math.Round(
                        bottomRight.Y -
                        topLeft.Y) -
                    (inset * 2);

                return width >= 300 &&
                       height >= 250;
            }
            catch
            {
                return false;
            }
        }

        private bool TryGetLexDeskPageScreenBounds(
    int pageIndex,
    out int left,
    out int top,
    out int width,
    out int height)
        {
            left = 0;
            top = 0;
            width = 0;
            height = 0;

            try
            {
                Border? host =
                    GetPageHost(pageIndex);

                if (host == null ||
                    host.Visibility != Visibility.Visible ||
                    host.ActualWidth < 100 ||
                    host.ActualHeight < 100)
                {
                    return false;
                }

                Point topLeft =
                    host.PointToScreen(
                        new Point(0, 0));

                Point bottomRight =
                    host.PointToScreen(
                        new Point(
                            host.ActualWidth,
                            host.ActualHeight));

                const int inset = 3;

                left =
                    (int)Math.Round(topLeft.X) +
                    inset;

                top =
                    (int)Math.Round(topLeft.Y) +
                    inset;

                width =
                    (int)Math.Round(
                        bottomRight.X -
                        topLeft.X) -
                    (inset * 2);

                height =
                    (int)Math.Round(
                        bottomRight.Y -
                        topLeft.Y) -
                    (inset * 2);

                return width >= 250 &&
                       height >= 200;
            }
            catch
            {
                return false;
            }
        }

        private bool TryGetLexDeskManagedPaneScreenBounds(
            int pageIndex,
            out int left,
            out int top,
            out int width,
            out int height)
        {
            left = 0;
            top = 0;
            width = 0;
            height = 0;

            try
            {
                if (pageIndex < 0 ||
                    pageIndex > 3 ||
                    _paneState[pageIndex] != PaneLifeState.Normal)
                {
                    return false;
                }

                // When the browser pane is visible, use its exact WPF rectangle.
                if (TryGetLexDeskPageScreenBounds(
                        pageIndex,
                        out left,
                        out top,
                        out width,
                        out height))
                {
                    return true;
                }

                // Tools / Maintenance can hide PagesHost. Derive the same pane
                // rectangle from LexDesk's central workspace instead of letting
                // Windows choose an arbitrary desktop size/position.
                if (!TryGetLexDeskWorkspaceScreenBounds(
                        out int workspaceLeft,
                        out int workspaceTop,
                        out int workspaceWidth,
                        out int workspaceHeight))
                {
                    return false;
                }

                if (_isPaneMaximizedMode &&
                    _maximizedPane >= 0 &&
                    _maximizedPane <= 3)
                {
                    if (pageIndex != _maximizedPane)
                        return false;

                    left = workspaceLeft;
                    top = workspaceTop;
                    width = workspaceWidth;
                    height = workspaceHeight;
                    return width >= 250 && height >= 200;
                }

                List<int> visiblePages =
                    VisiblePanes();

                int slot =
                    visiblePages.IndexOf(pageIndex);

                if (slot < 0)
                    return false;

                int count =
                    visiblePages.Count;

                const int halfGap = 2;

                if (count == 1)
                {
                    left = workspaceLeft;
                    top = workspaceTop;
                    width = workspaceWidth;
                    height = workspaceHeight;
                }
                else if (count == 2)
                {
                    int halfWidth = workspaceWidth / 2;

                    if (slot == 0)
                    {
                        left = workspaceLeft;
                        top = workspaceTop;
                        width = Math.Max(0, halfWidth - halfGap);
                        height = workspaceHeight;
                    }
                    else
                    {
                        left = workspaceLeft + halfWidth + halfGap;
                        top = workspaceTop;
                        width = Math.Max(0, workspaceWidth - halfWidth - halfGap);
                        height = workspaceHeight;
                    }
                }
                else if (count == 3)
                {
                    int halfWidth = workspaceWidth / 2;
                    int halfHeight = workspaceHeight / 2;

                    if (slot == 0)
                    {
                        left = workspaceLeft;
                        top = workspaceTop;
                        width = Math.Max(0, halfWidth - halfGap);
                        height = workspaceHeight;
                    }
                    else if (slot == 1)
                    {
                        left = workspaceLeft + halfWidth + halfGap;
                        top = workspaceTop;
                        width = Math.Max(0, workspaceWidth - halfWidth - halfGap);
                        height = Math.Max(0, halfHeight - halfGap);
                    }
                    else
                    {
                        left = workspaceLeft + halfWidth + halfGap;
                        top = workspaceTop + halfHeight + halfGap;
                        width = Math.Max(0, workspaceWidth - halfWidth - halfGap);
                        height = Math.Max(0, workspaceHeight - halfHeight - halfGap);
                    }
                }
                else
                {
                    int halfWidth = workspaceWidth / 2;
                    int halfHeight = workspaceHeight / 2;
                    bool right = slot == 1 || slot == 3;
                    bool bottom = slot >= 2;

                    left = right
                        ? workspaceLeft + halfWidth + halfGap
                        : workspaceLeft;

                    top = bottom
                        ? workspaceTop + halfHeight + halfGap
                        : workspaceTop;

                    width = right
                        ? Math.Max(0, workspaceWidth - halfWidth - halfGap)
                        : Math.Max(0, halfWidth - halfGap);

                    height = bottom
                        ? Math.Max(0, workspaceHeight - halfHeight - halfGap)
                        : Math.Max(0, halfHeight - halfGap);
                }

                return width >= 250 &&
                       height >= 200;
            }
            catch
            {
                return false;
            }
        }

        private bool PositionLexDeskPriorityOverlayWindow(
            IntPtr hWnd,
            string friendlyName)
        {
            try
            {
                if (hWnd == IntPtr.Zero ||
                    !IsWindow(hWnd))
                {
                    return false;
                }

                if (!TryGetLexDeskWorkspaceScreenBounds(
                        out int workspaceLeft,
                        out int workspaceTop,
                        out int workspaceWidth,
                        out int workspaceHeight))
                {
                    return false;
                }

                ShowWindow(
                    hWnd,
                    LexDeskSwRestore);

                if (!GetWindowRect(
                        hWnd,
                        out LexDeskWindowRect rect))
                {
                    return false;
                }

                int windowWidth =
                    Math.Max(
                        1,
                        rect.Right -
                        rect.Left);

                int windowHeight =
                    Math.Max(
                        1,
                        rect.Bottom -
                        rect.Top);

                // Preserve the application's own preferred dimensions. We only
                // calculate a centred position inside the LexDesk workspace.
                int left =
                    workspaceLeft +
                    ((workspaceWidth - windowWidth) / 2);

                int top =
                    workspaceTop +
                    ((workspaceHeight - windowHeight) / 2);

                bool positioned =
                    SetWindowPos(
                        hWnd,
                        IntPtr.Zero, // HWND_TOP, but not HWND_TOPMOST
                        left,
                        top,
                        0,
                        0,
                        SWP_NOSIZE |
                        SWP_SHOWWINDOW);

                WriteLexDeskManagedWindowDebug(
                    $"PRIORITY OVERLAY POSITION | app={friendlyName} | " +
                    $"result={positioned} | left={left} | top={top} | " +
                    $"size={windowWidth}x{windowHeight} | " +
                    $"HWND=0x{hWnd.ToInt64():X}");

                return positioned;
            }
            catch (Exception ex)
            {
                WriteLexDeskManagedWindowDebug(
                    $"PRIORITY OVERLAY POSITION FAILED | app={friendlyName} | " +
                    $"{ex.GetType().Name} | {ex.Message}");

                return false;
            }
        }

        private void RefreshLexDeskPriorityOverlayZOrder()
        {
            try
            {
                foreach (var pair in
                         _lexDeskPriorityOverlayWindows.ToList())
                {
                    IntPtr hWnd =
                        pair.Value;

                    if (hWnd == IntPtr.Zero ||
                        !IsWindow(hWnd))
                    {
                        _lexDeskPriorityOverlayWindows.Remove(
                            pair.Key);

                        _lexDeskManagedZOrderAssistWindows.Remove(
                            hWnd);

                        continue;
                    }

                    // A user-minimised security window stays minimised.
                    if (IsIconic(hWnd))
                        continue;

                    SetWindowPos(
                        hWnd,
                        IntPtr.Zero, // HWND_TOP, never HWND_TOPMOST
                        0,
                        0,
                        0,
                        0,
                        SWP_NOMOVE |
                        SWP_NOSIZE |
                        SWP_NOACTIVATE |
                        SWP_SHOWWINDOW);
                }
            }
            catch
            {
                // Security overlay priority must never affect normal browsing.
            }
        }

        private IntPtr FindLexDeskNativeSecurityPriorityWindow()
        {
            IntPtr bestHwnd =
                IntPtr.Zero;

            int bestScore =
                int.MinValue;

            try
            {
                IntPtr foreground =
                    GetForegroundWindow();

                EnumWindows((hWnd, _) =>
                {
                    try
                    {
                        if (hWnd == IntPtr.Zero ||
                            !IsWindow(hWnd) ||
                            !IsWindowVisible(hWnd))
                        {
                            return true;
                        }

                        string processName =
                            GetLexDeskWindowProcessName(hWnd);

                        string title =
                            GetLexDeskWindowTitle(hWnd);

                        bool securityTitle =
                            title.Contains(
                                "Windows Security",
                                StringComparison.OrdinalIgnoreCase);

                        bool securityProcess =
                            processName.Equals(
                                "SecHealthUI",
                                StringComparison.OrdinalIgnoreCase);

                        if (!securityTitle &&
                            !securityProcess)
                        {
                            return true;
                        }

                        int score = 0;

                        if (securityTitle)
                            score += 1000;

                        if (securityProcess)
                            score += 900;

                        if (hWnd == foreground)
                            score += 250;

                        if (!IsLexDeskWindowDwmCloaked(hWnd))
                            score += 100;

                        if (score > bestScore)
                        {
                            bestScore = score;
                            bestHwnd = hWnd;
                        }
                    }
                    catch { }

                    return true;
                }, IntPtr.Zero);
            }
            catch
            {
                return IntPtr.Zero;
            }

            return bestHwnd;
        }

        private async Task<bool> OpenLexDeskNativeSecurityPrioritySurfaceAsync(
            string target,
            string friendlyName)
        {
            target =
                (target ?? "").Trim();

            friendlyName =
                string.IsNullOrWhiteSpace(friendlyName)
                    ? "Windows Security"
                    : friendlyName.Trim();

            if (string.IsNullOrWhiteSpace(target))
                target = "ms-settings:windowsdefender";

            try
            {
                if (_lexDeskPriorityOverlayWindows.TryGetValue(
                        friendlyName,
                        out IntPtr existingHwnd) &&
                    existingHwnd != IntPtr.Zero &&
                    IsWindow(existingHwnd))
                {
                    ShowWindow(
                        existingHwnd,
                        LexDeskSwRestore);

                    PositionLexDeskPriorityOverlayWindow(
                        existingHwnd,
                        friendlyName);

                    SetForegroundWindow(
                        existingHwnd);

                    return true;
                }

                Process.Start(
                    new ProcessStartInfo(target)
                    {
                        UseShellExecute = true
                    });

                IntPtr hWnd =
                    IntPtr.Zero;

                for (int attempt = 0;
                     attempt < 80;
                     attempt++)
                {
                    await Task.Delay(
                        attempt == 0
                            ? 300
                            : 100);

                    hWnd =
                        FindLexDeskNativeSecurityPriorityWindow();

                    if (hWnd != IntPtr.Zero)
                        break;
                }

                if (hWnd == IntPtr.Zero ||
                    !IsWindow(hWnd))
                {
                    // Windows still opened its own security UI. Leave it native
                    // rather than risking the system-window capture problems we
                    // deliberately retired earlier.
                    return true;
                }

                // Security UI stays natively owned by Windows. We only centre it
                // and keep it above LexDesk while it is open.
                ShowWindow(
                    hWnd,
                    LexDeskSwRestore);

                PositionLexDeskPriorityOverlayWindow(
                    hWnd,
                    friendlyName);

                _lexDeskPriorityOverlayWindows[friendlyName] =
                    hWnd;

                SetForegroundWindow(
                    hWnd);

                RefreshLexDeskPriorityOverlayZOrder();

                WriteLexDeskManagedWindowDebug(
                    $"NATIVE SECURITY PRIORITY REGISTERED | " +
                    $"app={friendlyName} | HWND=0x{hWnd.ToInt64():X}");

                return true;
            }
            catch (Exception ex)
            {
                WriteLexDeskManagedWindowDebug(
                    $"NATIVE SECURITY PRIORITY FAILED | " +
                    $"app={friendlyName} | {ex.GetType().Name} | {ex.Message}");

                return TryStartExternalProcess(
                    target,
                    friendlyName);
            }
        }

        private async Task<bool> OpenLexDeskGenericSecurityPriorityOverlayAsync(
            LexDeskInstalledApp app)
        {
            if (app == null)
                return false;

            string friendlyName =
                string.IsNullOrWhiteSpace(app.Name)
                    ? "Security software"
                    : app.Name.Trim();

            try
            {
                if (_lexDeskPriorityOverlayWindows.TryGetValue(
                        friendlyName,
                        out IntPtr existingHwnd) &&
                    existingHwnd != IntPtr.Zero &&
                    IsWindow(existingHwnd))
                {
                    ShowWindow(
                        existingHwnd,
                        LexDeskSwRestore);

                    PositionLexDeskPriorityOverlayWindow(
                        existingHwnd,
                        friendlyName);

                    SetForegroundWindow(
                        existingHwnd);

                    return true;
                }

                HashSet<IntPtr> windowsBeforeLaunch =
                    GetLexDeskVisibleTopLevelWindows();

                var expectedProcessNames =
                    new List<string>();

                try
                {
                    if (TryGetLexDeskForcedLaunchOverride(
                            app,
                            out string forcedExe,
                            out _,
                            out _,
                            out _,
                            out _) &&
                        !string.IsNullOrWhiteSpace(forcedExe))
                    {
                        string process =
                            Path.GetFileNameWithoutExtension(
                                forcedExe);

                        if (!string.IsNullOrWhiteSpace(process))
                            expectedProcessNames.Add(process);
                    }
                    else if (!string.IsNullOrWhiteSpace(app.Target) &&
                             app.Target.EndsWith(
                                 ".exe",
                                 StringComparison.OrdinalIgnoreCase))
                    {
                        string process =
                            Path.GetFileNameWithoutExtension(
                                app.Target);

                        if (!string.IsNullOrWhiteSpace(process))
                            expectedProcessNames.Add(process);
                    }
                    else if (!string.IsNullOrWhiteSpace(app.ShortcutPath) &&
                             TryResolveLexDeskShortcutViaWScript(
                                 app.ShortcutPath,
                                 out string resolvedExe,
                                 out _,
                                 out _) &&
                             !string.IsNullOrWhiteSpace(resolvedExe))
                    {
                        string process =
                            Path.GetFileNameWithoutExtension(
                                resolvedExe);

                        if (!string.IsNullOrWhiteSpace(process))
                            expectedProcessNames.Add(process);
                    }
                }
                catch { }

                bool launched =
                    LaunchLexDeskApp(app);

                if (!launched)
                    return false;

                string[] titleHints =
                    string.IsNullOrWhiteSpace(app.Name)
                        ? Array.Empty<string>()
                        : new[] { app.Name.Trim() };

                for (int attempt = 0;
                     attempt < 120;
                     attempt++)
                {
                    await Task.Delay(
                        attempt == 0
                            ? 300
                            : 100);

                    IntPtr hWnd =
                        FindLexDeskManagedWindow(
                            windowsBeforeLaunch,
                            expectedProcessNames.ToArray(),
                            titleHints,
                            Array.Empty<string>());

                    if (hWnd == IntPtr.Zero ||
                        !IsWindow(hWnd))
                    {
                        continue;
                    }

                    ShowWindow(
                        hWnd,
                        LexDeskSwRestore);

                    if (!PositionLexDeskPriorityOverlayWindow(
                            hWnd,
                            friendlyName))
                    {
                        continue;
                    }

                    _lexDeskPriorityOverlayWindows[friendlyName] =
                        hWnd;

                    SetForegroundWindow(
                        hWnd);

                    RefreshLexDeskPriorityOverlayZOrder();

                    WriteLexDeskManagedWindowDebug(
                        $"GENERIC SECURITY PRIORITY REGISTERED | " +
                        $"app={friendlyName} | HWND=0x{hWnd.ToInt64():X}");

                    return true;
                }

                // It launched, but Windows did not expose a safe window match.
                // Leave the security product open normally rather than guessing.
                WriteLexDeskManagedWindowDebug(
                    $"GENERIC SECURITY PRIORITY CAPTURE SKIPPED | app={friendlyName}");

                return true;
            }
            catch (Exception ex)
            {
                WriteLexDeskManagedWindowDebug(
                    $"GENERIC SECURITY PRIORITY FAILED | " +
                    $"app={friendlyName} | {ex.GetType().Name} | {ex.Message}");

                return LaunchLexDeskApp(app);
            }
        }

        private async Task<bool> OpenLexDeskBitdefenderPriorityOverlayAsync(
            LexDeskInstalledApp app)
        {
            const string friendlyName =
                LexDeskBitdefenderPriorityKey;

            try
            {
                if (_lexDeskPriorityOverlayWindows.TryGetValue(
                        friendlyName,
                        out IntPtr existingHwnd))
                {
                    if (existingHwnd != IntPtr.Zero &&
                        IsWindow(existingHwnd))
                    {
                        ShowWindow(
                            existingHwnd,
                            LexDeskSwRestore);

                        PositionLexDeskPriorityOverlayWindow(
                            existingHwnd,
                            friendlyName);

                        SetForegroundWindow(
                            existingHwnd);

                        UpdateSecurityStatus(
                            "Bitdefender is already open",
                            false);

                        return true;
                    }

                    _lexDeskPriorityOverlayWindows.Remove(
                        friendlyName);
                }

                if (!TryGetLexDeskForcedLaunchOverride(
                        app,
                        out string target,
                        out string workingDirectory,
                        out string launchArguments,
                        out int cooldownMs,
                        out string launchKey) ||
                    string.IsNullOrWhiteSpace(target))
                {
                    return LaunchLexDeskApp(app);
                }

                // Keep the known-good Bitdefender launch path and its existing
                // anti-double-click cooldown.
                if (cooldownMs > 0)
                {
                    DateTime now =
                        DateTime.UtcNow;

                    if (_lexDeskForcedLastLaunchUtc.TryGetValue(
                            launchKey,
                            out DateTime last) &&
                        (now - last).TotalMilliseconds < cooldownMs)
                    {
                        return true;
                    }

                    _lexDeskForcedLastLaunchUtc[launchKey] =
                        now;
                }

                HashSet<IntPtr> windowsBeforeLaunch =
                    GetLexDeskVisibleTopLevelWindows();

                WriteLexDeskManagedWindowDebug(
                    "BEGIN PRIORITY SECURITY OVERLAY | app=Bitdefender");

                bool launched =
                    TryLaunchLexDeskViaCmdStart(
                        target,
                        launchArguments,
                        workingDirectory);

                if (!launched)
                {
                    UpdateSecurityStatus(
                        "LexDesk could not start Bitdefender",
                        true);

                    return false;
                }

                string[] expectedProcessNames =
                {
                    "seccenter"
                };

                string[] titleHints =
                {
                    "Bitdefender"
                };

                string[] classHints =
                    Array.Empty<string>();

                // Bitdefender can take several seconds to surface its real window.
                for (int attempt = 0;
                     attempt < 120;
                     attempt++)
                {
                    await Task.Delay(
                        attempt == 0
                            ? 250
                            : 100);

                    IntPtr hWnd =
                        FindLexDeskManagedWindow(
                            windowsBeforeLaunch,
                            expectedProcessNames,
                            titleHints,
                            classHints);

                    if (hWnd == IntPtr.Zero)
                        continue;

                    await Task.Delay(180);

                    if (!IsWindow(hWnd))
                        continue;

                    // Bitdefender remains an ordinary owned Windows window. We do
                    // not resize it and we do not reserve or overwrite a browser pane.
                    AttachLexDeskManagedWindowToWorkspace(
                        hWnd);

                    if (!PositionLexDeskPriorityOverlayWindow(
                            hWnd,
                            friendlyName))
                    {
                        continue;
                    }

                    _lexDeskPriorityOverlayWindows[friendlyName] =
                        hWnd;

                    SetForegroundWindow(
                        hWnd);

                    RefreshLexDeskPriorityOverlayZOrder();

                    UpdateSecurityStatus(
                        "Opened Bitdefender as the security priority window",
                        false);

                    WriteLexDeskManagedWindowDebug(
                        $"PRIORITY SECURITY OVERLAY REGISTERED | " +
                        $"app=Bitdefender | HWND=0x{hWnd.ToInt64():X}");

                    return true;
                }

                WriteLexDeskManagedWindowDebug(
                    "PRIORITY SECURITY OVERLAY CAPTURE FAILED | app=Bitdefender");

                UpdateSecurityStatus(
                    "Bitdefender opened, but LexDesk could not centre its window",
                    false);

                // The antivirus may still have opened normally. Do not launch it
                // a second time merely because Windows refused window discovery.
                return true;
            }
            catch (Exception ex)
            {
                WriteLexDeskManagedWindowDebug(
                    "PRIORITY SECURITY OVERLAY EXCEPTION | " +
                    ex.GetType().Name +
                    " | " +
                    ex.Message);

                return LaunchLexDeskApp(app);
            }
        }

        private bool PositionLexDeskManagedWindow(
    IntPtr hWnd,
    int pageIndex = -1)
        {
            try
            {
                if (hWnd == IntPtr.Zero ||
                    !IsWindow(hWnd))
                {
                    WriteLexDeskManagedWindowDebug(
                        "POSITION FAILED: invalid HWND");

                    return false;
                }

                bool boundsFound;

                int left;
                int top;
                int width;
                int height;

                if (pageIndex >= 0 &&
                    pageIndex <= 3)
                {
                    boundsFound =
                        TryGetLexDeskManagedPaneScreenBounds(
                            pageIndex,
                            out left,
                            out top,
                            out width,
                            out height);
                }
                else
                {
                    boundsFound =
                        TryGetLexDeskWorkspaceScreenBounds(
                            out left,
                            out top,
                            out width,
                            out height);
                }

                WriteLexDeskManagedWindowDebug(
                    $"POSITION | page={pageIndex} | " +
                    $"boundsFound={boundsFound} | " +
                    $"left={left} | top={top} | " +
                    $"width={width} | height={height}");

                if (!boundsFound)
                    return false;

                ShowWindow(
                    hWnd,
                    LexDeskSwRestore);

                Marshal.GetLastWin32Error();

                bool moved =
    MoveWindow(
        hWnd,
        left,
        top,
        width,
        height,
        true);

                int moveError =
                    Marshal.GetLastWin32Error();

                WriteLexDeskManagedWindowDebug(
                    $"MOVEWINDOW | result={moved} | " +
                    $"error={moveError} | " +
                    $"HWND=0x{hWnd.ToInt64():X}");

                if (moved)
                {
                    WriteLexDeskManagedWindowDebug(
                        $"POSITION AFTER MOVE | {DescribeLexDeskManagedWindowForDebug(hWnd)}");

                    return true;
                }

                // Some classic MMC windows do not cooperate with MoveWindow.
                // Try the lower-level positioning path before giving up.
                bool positioned =
                    SetWindowPos(
                        hWnd,
                        IntPtr.Zero,
                        left,
                        top,
                        width,
                        height,
                        SWP_NOZORDER |
                        SWP_NOACTIVATE |
                        SWP_SHOWWINDOW);

                int positionError =
                    Marshal.GetLastWin32Error();

                WriteLexDeskManagedWindowDebug(
                    $"SETWINDOWPOS | result={positioned} | " +
                    $"error={positionError} | " +
                    $"HWND=0x{hWnd.ToInt64():X}");

                WriteLexDeskManagedWindowDebug(
                    $"POSITION AFTER SETWINDOWPOS | {DescribeLexDeskManagedWindowForDebug(hWnd)}");

                return positioned;
            }
            catch (Exception ex)
            {
                WriteLexDeskManagedWindowDebug(
                    "POSITION EXCEPTION: " +
                    ex.GetType().Name +
                    " | " +
                    ex.Message);

                return false;
            }
        }

        // Keeps a managed app above LexDesk without making it globally TopMost.
        // Returns true when Windows accepted the owner relationship.
        private bool AttachLexDeskManagedWindowToWorkspace(IntPtr hWnd)
        {
            try
            {
                if (hWnd == IntPtr.Zero || !IsWindow(hWnd))
                    return false;

                IntPtr ownerHwnd =
                    new WindowInteropHelper(this).Handle;

                if (ownerHwnd == IntPtr.Zero || ownerHwnd == hWnd)
                    return false;

                Marshal.GetLastWin32Error();
                SetWindowLongPtr(
                    hWnd,
                    GWLP_HWNDPARENT,
                    ownerHwnd);

                int error = Marshal.GetLastWin32Error();
                bool attached =
                    GetWindow(hWnd, GW_OWNER) == ownerHwnd;

                if (attached)
                    _lexDeskManagedZOrderAssistWindows.Remove(hWnd);
                else
                    _lexDeskManagedZOrderAssistWindows.Add(hWnd);

                WriteLexDeskManagedWindowDebug(
                    $"OWNER ATTACH | HWND=0x{hWnd.ToInt64():X} | " +
                    $"OWNER=0x{ownerHwnd.ToInt64():X} | error={error}");

                return attached;
            }
            catch (Exception ex)
            {
                _lexDeskManagedZOrderAssistWindows.Add(hWnd);

                WriteLexDeskManagedWindowDebug(
                    "OWNER ATTACH FAILED | " + ex.Message);

                return false;
            }
        }

        private bool AttachLexDeskManagedPopupToMainWindow(
            IntPtr popupHwnd,
            IntPtr mainHwnd)
        {
            try
            {
                if (popupHwnd == IntPtr.Zero ||
                    mainHwnd == IntPtr.Zero ||
                    popupHwnd == mainHwnd ||
                    !IsWindow(popupHwnd) ||
                    !IsWindow(mainHwnd))
                {
                    return false;
                }

                Marshal.GetLastWin32Error();
                SetWindowLongPtr(
                    popupHwnd,
                    GWLP_HWNDPARENT,
                    mainHwnd);

                int error = Marshal.GetLastWin32Error();
                bool attached =
                    GetWindow(popupHwnd, GW_OWNER) == mainHwnd;

                if (attached)
                    _lexDeskManagedZOrderAssistWindows.Remove(popupHwnd);
                else
                    _lexDeskManagedZOrderAssistWindows.Add(popupHwnd);

                WriteLexDeskManagedWindowDebug(
                    $"POPUP OWNER ATTACH | HWND=0x{popupHwnd.ToInt64():X} | " +
                    $"PARENT=0x{mainHwnd.ToInt64():X} | error={error}");

                return attached;
            }
            catch
            {
                _lexDeskManagedZOrderAssistWindows.Add(popupHwnd);
                return false;
            }
        }

        private bool PositionLexDeskManagedSecondaryWindow(
            IntPtr hWnd,
            int pageIndex)
        {
            try
            {
                if (hWnd == IntPtr.Zero ||
                    !IsWindow(hWnd) ||
                    pageIndex < 0 ||
                    pageIndex > 3)
                {
                    return false;
                }

                if (!TryGetLexDeskManagedPaneScreenBounds(
                        pageIndex,
                        out int left,
                        out int top,
                        out int paneWidth,
                        out int paneHeight))
                {
                    return false;
                }

                int currentWidth = paneWidth;
                int currentHeight = paneHeight;

                if (GetWindowRect(hWnd, out LexDeskWindowRect rect))
                {
                    currentWidth = Math.Max(1, rect.Right - rect.Left);
                    currentHeight = Math.Max(1, rect.Bottom - rect.Top);
                }

                string className = GetLexDeskWindowClass(hWnd);

                bool dialogSized =
                    className.Equals("#32770", StringComparison.OrdinalIgnoreCase) ||
                    (currentWidth <= Math.Min(760, paneWidth - 40) &&
                     currentHeight <= Math.Min(560, paneHeight - 40));

                if (!dialogSized)
                {
                    return PositionLexDeskManagedWindow(hWnd, pageIndex);
                }

                int width = Math.Min(currentWidth, Math.Max(260, paneWidth - 30));
                int height = Math.Min(currentHeight, Math.Max(180, paneHeight - 30));
                int x = left + Math.Max(0, (paneWidth - width) / 2);
                int y = top + Math.Max(0, (paneHeight - height) / 2);

                ShowWindow(hWnd, LexDeskSwRestore);

                bool moved = MoveWindow(
                    hWnd,
                    x,
                    y,
                    width,
                    height,
                    true);

                WriteLexDeskManagedWindowDebug(
                    $"POPUP POSITION | page={pageIndex} | " +
                    $"result={moved} | HWND=0x{hWnd.ToInt64():X} | " +
                    $"x={x} | y={y} | width={width} | height={height}");

                return moved;
            }
            catch
            {
                return false;
            }
        }

        private void RegisterLexDeskManagedSecondaryWindow(
            string key,
            IntPtr hWnd)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(key) ||
                    hWnd == IntPtr.Zero ||
                    !IsWindow(hWnd) ||
                    _lexDeskManagedWindowFamilyKeys.ContainsKey(hWnd))
                {
                    return;
                }

                if (!_lexDeskManagedWindowPageIndexes.TryGetValue(
                        key,
                        out int pageIndex) ||
                    pageIndex < 0 ||
                    pageIndex > 3)
                {
                    return;
                }

                IntPtr mainHwnd =
                    _lexDeskManagedWindows.TryGetValue(key, out IntPtr main)
                        ? main
                        : IntPtr.Zero;

                EnsureLexDeskManagedFamilyContains(key, hWnd);

                bool nativeOwnership =
                    _lexDeskManagedNativeShellSessions.Contains(key);

                if (!nativeOwnership)
                {
                    if (mainHwnd != IntPtr.Zero &&
                        IsWindow(mainHwnd) &&
                        mainHwnd != hWnd)
                    {
                        AttachLexDeskManagedPopupToMainWindow(
                            hWnd,
                            mainHwnd);
                    }
                    else
                    {
                        AttachLexDeskManagedWindowToWorkspace(hWnd);
                    }
                }
                else
                {
                    // Native-shell child/top-level windows keep their Windows
                    // ownership but still need to remain above LexDesk.
                    _lexDeskManagedZOrderAssistWindows.Add(hWnd);
                }

                PositionLexDeskManagedSecondaryWindow(
                    hWnd,
                    pageIndex);

                WriteLexDeskManagedWindowDebug(
                    $"POPUP CAPTURE | app={key} | page={pageIndex} | " +
                    $"HWND=0x{hWnd.ToInt64():X} | " +
                    $"PROCESS={GetLexDeskWindowProcessName(hWnd)} | " +
                    $"CLASS={GetLexDeskWindowClass(hWnd)} | " +
                    $"TITLE={GetLexDeskWindowTitle(hWnd)}");
            }
            catch
            {
                // Popup capture is convenience only.
            }
        }

        private bool IsLexDeskShellOrTransientWindow(
            IntPtr hWnd,
            string className,
            string title)
        {
            if (hWnd == IntPtr.Zero || !IsWindowVisible(hWnd))
                return true;

            if (className.Equals("Shell_TrayWnd", StringComparison.OrdinalIgnoreCase) ||
                className.Equals("Shell_SecondaryTrayWnd", StringComparison.OrdinalIgnoreCase) ||
                className.Equals("Progman", StringComparison.OrdinalIgnoreCase) ||
                className.Equals("WorkerW", StringComparison.OrdinalIgnoreCase) ||
                className.Equals("MsoSplash", StringComparison.OrdinalIgnoreCase) ||
                title.StartsWith("Opening - ", StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            // Menus, tooltips and render-helper windows often have no title. Do
            // not drag those around the screen. Real app popups/dialogs normally
            // have a title or a dialog-class name.
            if (string.IsNullOrWhiteSpace(title) &&
                !className.Contains("Dialog", StringComparison.OrdinalIgnoreCase) &&
                !className.Equals("#32770", StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            if (GetWindowRect(hWnd, out LexDeskWindowRect rect))
            {
                int width = Math.Max(0, rect.Right - rect.Left);
                int height = Math.Max(0, rect.Bottom - rect.Top);

                if (width < 120 || height < 80)
                    return true;
            }

            return false;
        }

        private int ScoreLexDeskManagedWindowForSession(
            string key,
            IntPtr hWnd,
            uint processId,
            string processName,
            string className,
            string title,
            IntPtr ownerHwnd)
        {
            // Calculator and Windows Settings are hosted through shared Windows
            // infrastructure. Their old frame shells can remain alive and even
            // visible to Win32 while DWM keeps them cloaked. Treating those old
            // frames as app popups creates duplicate/blank/blue windows.
            //
            // For these two sessions LexDesk manages only the explicitly chosen
            // main window. Windows keeps ownership of their internal surfaces.
            if (string.Equals(
                    key,
                    "Calculator",
                    StringComparison.OrdinalIgnoreCase) ||
                string.Equals(
                    key,
                    "Windows Settings",
                    StringComparison.OrdinalIgnoreCase))
            {
                if (hWnd != IntPtr.Zero &&
                    IsWindow(hWnd))
                {
                    WriteLexDeskManagedWindowDebug(
                        $"SHARED HOST SECONDARY IGNORED | app={key} | " +
                        $"HWND=0x{hWnd.ToInt64():X} | " +
                        $"PROCESS={processName} | CLASS={className} | TITLE={title}");
                }

                return int.MinValue;
            }
            if (!_lexDeskManagedWindows.TryGetValue(
                    key,
                    out IntPtr mainHwnd) ||
                mainHwnd == IntPtr.Zero ||
                !IsWindow(mainHwnd))
            {
                return int.MinValue;
            }

            int score = 0;

            // Strongest signal: Windows says this top-level window is owned by
            // another window already in the managed family.
            if (ownerHwnd != IntPtr.Zero &&
                _lexDeskManagedWindowFamilyKeys.TryGetValue(
                    ownerHwnd,
                    out string? ownerKey) &&
                string.Equals(ownerKey, key, StringComparison.OrdinalIgnoreCase))
            {
                score += 1000;
            }

            if (!_lexDeskManagedWindowIdentities.TryGetValue(
                    key,
                    out LexDeskManagedWindowIdentity? identity))
            {
                return score > 0 ? score : int.MinValue;
            }

            bool genericHostProcess =
                processName.Equals("ApplicationFrameHost", StringComparison.OrdinalIgnoreCase) ||
                processName.Equals("explorer", StringComparison.OrdinalIgnoreCase) ||
                processName.Equals("RuntimeBroker", StringComparison.OrdinalIgnoreCase) ||
                processName.Equals("dllhost", StringComparison.OrdinalIgnoreCase);

            // An unowned top-level ApplicationFrameHost window is another app
            // frame, not a popup. Never pull it into an existing session.
            if (processName.Equals(
                    "ApplicationFrameHost",
                    StringComparison.OrdinalIgnoreCase) &&
                ownerHwnd == IntPtr.Zero)
            {
                return int.MinValue;
            }

            if (processId != 0 &&
                identity.MainProcessId != 0 &&
                processId == identity.MainProcessId)
            {
                score += genericHostProcess ? 120 : 650;
            }

            bool processNameMatches =
                !string.IsNullOrWhiteSpace(processName) &&
                (processName.Equals(
                     identity.MainProcessName,
                     StringComparison.OrdinalIgnoreCase) ||
                 identity.ProcessNames.Any(expected =>
                     !string.IsNullOrWhiteSpace(expected) &&
                     processName.Equals(expected, StringComparison.OrdinalIgnoreCase)));

            if (processNameMatches && !genericHostProcess)
                score += 500;

            bool titleMatches =
                !string.IsNullOrWhiteSpace(title) &&
                (title.Contains(key, StringComparison.OrdinalIgnoreCase) ||
                 identity.TitleHints.Any(hint =>
                     !string.IsNullOrWhiteSpace(hint) &&
                     title.Contains(hint, StringComparison.OrdinalIgnoreCase)));

            if (titleMatches)
                score += 240;

            bool classMatches =
                !string.IsNullOrWhiteSpace(className) &&
                (className.Equals(
                     identity.MainClassName,
                     StringComparison.OrdinalIgnoreCase) ||
                 identity.ClassHints.Any(hint =>
                     !string.IsNullOrWhiteSpace(hint) &&
                     className.Equals(hint, StringComparison.OrdinalIgnoreCase)));

            if (classMatches)
                score += genericHostProcess ? 60 : 140;

            // explorer.exe owns the Windows shell and ApplicationFrameHost can
            // simultaneously host Calculator, Settings and other apps. Never group
            // one of those by process name alone.
            if (genericHostProcess &&
                score < 240 &&
                ownerHwnd == IntPtr.Zero)
            {
                return int.MinValue;
            }

            return score >= 240 ? score : int.MinValue;
        }

        private void DiscoverLexDeskManagedSessionWindows()
        {
            try
            {
                CleanupLexDeskManagedWindowRegistrations();

                if (_lexDeskManagedWindows.Count == 0)
                    return;

                int lexDeskProcessId = Environment.ProcessId;

                EnumWindows((hWnd, _) =>
                {
                    try
                    {
                        if (hWnd == IntPtr.Zero ||
                            _lexDeskManagedWindowFamilyKeys.ContainsKey(hWnd) ||
                            !IsWindowVisible(hWnd) ||
                            IsLexDeskWindowDwmCloaked(hWnd))
                        {
                            return true;
                        }

                        GetWindowThreadProcessId(hWnd, out uint processId);

                        if (processId == 0 || processId == lexDeskProcessId)
                            return true;

                        string processName = GetLexDeskWindowProcessName(hWnd);
                        string className = GetLexDeskWindowClass(hWnd);
                        string title = GetLexDeskWindowTitle(hWnd);

                        if (IsLexDeskShellOrTransientWindow(
                                hWnd,
                                className,
                                title))
                        {
                            return true;
                        }

                        IntPtr ownerHwnd = GetWindow(hWnd, GW_OWNER);

                        string bestKey = "";
                        int bestScore = int.MinValue;

                        foreach (string key in _lexDeskManagedWindows.Keys.ToList())
                        {
                            int score = ScoreLexDeskManagedWindowForSession(
                                key,
                                hWnd,
                                processId,
                                processName,
                                className,
                                title,
                                ownerHwnd);

                            if (score > bestScore)
                            {
                                bestScore = score;
                                bestKey = key;
                            }
                        }

                        if (!string.IsNullOrWhiteSpace(bestKey) &&
                            bestScore != int.MinValue)
                        {
                            RegisterLexDeskManagedSecondaryWindow(
                                bestKey,
                                hWnd);
                        }
                    }
                    catch { }

                    return true;
                }, IntPtr.Zero);
            }
            catch
            {
                // Popup discovery must never affect LexDesk.
            }
        }

        private bool RaiseLexDeskAssistWindowAboveWorkspace(
            IntPtr hWnd,
            string reason)
        {
            try
            {
                if (hWnd == IntPtr.Zero ||
                    !IsWindow(hWnd) ||
                    IsIconic(hWnd) ||
                    IsLexDeskWindowDwmCloaked(hWnd))
                {
                    return false;
                }

                // HWND_TOP was not moving shared ApplicationFrameHost windows
                // (Calculator / Settings) above LexDesk. Momentarily enter the
                // topmost band, then immediately return to the normal band.
                // SWP_NOACTIVATE means focus is not stolen from the user's click.
                bool raised =
                    SetWindowPos(
                        hWnd,
                        LexDeskHwndTopmost,
                        0,
                        0,
                        0,
                        0,
                        SWP_NOMOVE |
                        SWP_NOSIZE |
                        SWP_NOACTIVATE |
                        SWP_SHOWWINDOW);

                int raisedError =
                    raised
                        ? 0
                        : Marshal.GetLastWin32Error();

                bool normalised =
                    SetWindowPos(
                        hWnd,
                        LexDeskHwndNotTopmost,
                        0,
                        0,
                        0,
                        0,
                        SWP_NOMOVE |
                        SWP_NOSIZE |
                        SWP_NOACTIVATE |
                        SWP_SHOWWINDOW);

                int normalisedError =
                    normalised
                        ? 0
                        : Marshal.GetLastWin32Error();

                WriteLexDeskManagedWindowDebug(
                    $"ASSIST ZORDER BOUNCE | reason={reason} | " +
                    $"raised={raised} err1={raisedError} | " +
                    $"normalised={normalised} err2={normalisedError} | " +
                    $"{DescribeLexDeskNativeWindowForDebug(hWnd)}");

                return raised && normalised;
            }
            catch (Exception ex)
            {
                WriteLexDeskManagedWindowDebug(
                    $"ASSIST ZORDER BOUNCE FAILED | reason={reason} | " +
                    $"{ex.GetType().Name} | {ex.Message}");

                return false;
            }
        }

        // Full z-order refresh. Used only when LexDesk itself comes to the front or
        // immediately after a new managed app is registered.
        private void RefreshLexDeskManagedWindowZOrder()
        {
            try
            {
                CleanupLexDeskManagedWindowRegistrations();

                DumpLexDeskWindowsHostedSurfaceState(
                    "BEFORE full managed z-order refresh");

                IntPtr foregroundWindow = GetForegroundWindow();

                foreach (int pageIndex in Enumerable.Range(0, 4))
                {
                    if (!_lexDeskManagedPaneOwners.TryGetValue(
                            pageIndex,
                            out string? key) ||
                        !_lexDeskManagedWindowFamilies.TryGetValue(
                            key,
                            out HashSet<IntPtr>? family))
                    {
                        continue;
                    }

                    // Windows shell surfaces keep their native Windows ownership.
                    // We may still raise them above LexDesk here using z-order only;
                    // no owner change, move, resize or activation is performed.
                    bool nativeShellSession =
                        _lexDeskManagedNativeShellSessions.Contains(key);

                    // Main first, then secondary windows so dialogs/compose windows
                    // remain above their parent app.
                    IntPtr mainHwnd =
                        _lexDeskManagedWindows.TryGetValue(key, out IntPtr main)
                            ? main
                            : IntPtr.Zero;

                    if (mainHwnd != IntPtr.Zero && IsWindow(mainHwnd))
                    {
                        if (nativeShellSession)
                        {
                            _lexDeskManagedZOrderAssistWindows.Add(mainHwnd);
                        }

                        if (_lexDeskManagedZOrderAssistWindows.Contains(mainHwnd))
                        {
                            RaiseLexDeskAssistWindowAboveWorkspace(
                                mainHwnd,
                                $"full refresh: {key}");
                        }
                        else
                        {
                            SetWindowPos(
                                mainHwnd,
                                IntPtr.Zero,
                                0, 0, 0, 0,
                                SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE);
                        }
                    }

                    foreach (IntPtr hWnd in family.ToList())
                    {
                        if (hWnd == mainHwnd ||
                            hWnd == IntPtr.Zero ||
                            !IsWindow(hWnd))
                        {
                            continue;
                        }

                        if (nativeShellSession)
                        {
                            _lexDeskManagedZOrderAssistWindows.Add(hWnd);
                        }

                        if (_lexDeskManagedZOrderAssistWindows.Contains(hWnd))
                        {
                            RaiseLexDeskAssistWindowAboveWorkspace(
                                hWnd,
                                $"full refresh secondary: {key}");
                        }
                        else
                        {
                            SetWindowPos(
                                hWnd,
                                IntPtr.Zero,
                                0, 0, 0, 0,
                                SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE);
                        }
                    }
                }

                if (foregroundWindow != IntPtr.Zero &&
                    IsWindow(foregroundWindow) &&
                    _lexDeskManagedWindowFamilyKeys.ContainsKey(foregroundWindow))
                {
                    if (_lexDeskManagedZOrderAssistWindows.Contains(
                            foregroundWindow))
                    {
                        RaiseLexDeskAssistWindowAboveWorkspace(
                            foregroundWindow,
                            "full refresh foreground");
                    }
                    else
                    {
                        SetWindowPos(
                            foregroundWindow,
                            IntPtr.Zero,
                            0, 0, 0, 0,
                            SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE);
                    }
                }

                // Security software deliberately wins the final LexDesk z-order pass.
                RefreshLexDeskPriorityOverlayZOrder();

                QueueLexDeskWindowsHostedSurfaceStateDump(
                    "AFTER full managed z-order refresh");
            }
            catch
            {
                // Z-order maintenance must never affect normal LexDesk use.
            }
        }

        // Lightweight helper for unowned managed windows. This includes windows
        // such as Calculator that reject an owner relationship AND native Windows
        // surfaces such as Settings that LexDesk deliberately never re-parents.
        // It runs only when focus really changes, avoiding the old flashing loop.
        private void RefreshLexDeskManagedAssistWindowZOrder(IntPtr foregroundWindow)
        {
            try
            {
                DumpLexDeskWindowsHostedSurfaceState(
                    "BEFORE assist z-order refresh");

                foreach (IntPtr hWnd in _lexDeskManagedZOrderAssistWindows.ToList())
                {
                    if (hWnd == IntPtr.Zero || !IsWindow(hWnd))
                    {
                        _lexDeskManagedZOrderAssistWindows.Remove(hWnd);
                        continue;
                    }

                    if (hWnd == foregroundWindow)
                        continue;

                    RaiseLexDeskAssistWindowAboveWorkspace(
                        hWnd,
                        "assist refresh background");
                }

                if (foregroundWindow != IntPtr.Zero &&
                    _lexDeskManagedZOrderAssistWindows.Contains(foregroundWindow) &&
                    IsWindow(foregroundWindow))
                {
                    RaiseLexDeskAssistWindowAboveWorkspace(
                        foregroundWindow,
                        "assist refresh foreground");
                }

                QueueLexDeskWindowsHostedSurfaceStateDump(
                    "AFTER assist z-order refresh");
            }
            catch
            {
                // Hosted-window assistance must never affect normal LexDesk use.
            }
        }

        private void MinimizeLexDeskManagedWindows()
        {
            try
            {
                foreach (var pair in
                         _lexDeskManagedWindows.ToList())
                {
                    IntPtr hWnd = pair.Value;

                    if (hWnd == IntPtr.Zero ||
                        !IsWindow(hWnd))
                    {
                        _lexDeskManagedWindows.Remove(
                            pair.Key);
                        _lexDeskManagedWindowPageIndexes.Remove(
                            pair.Key);

                        continue;
                    }

                    WriteLexDeskManagedWindowDebug(
                        $"MANAGED WINDOW MINIMISE | app={pair.Key} | " +
                        $"{DescribeLexDeskManagedWindowForDebug(hWnd)}");

                    ShowWindow(
                        hWnd,
                        LexDeskSwMinimize);

                    WriteLexDeskManagedWindowDebug(
                        $"MANAGED WINDOW AFTER MINIMISE | app={pair.Key} | " +
                        $"{DescribeLexDeskManagedWindowForDebug(hWnd)}");
                }
            }
            catch
            {
                // Managed windows must never affect LexDesk itself.
            }
        }

        private void RestoreLexDeskLastManagedWindow()
        {
            try
            {
                if (string.IsNullOrWhiteSpace(
                        _lexDeskLastManagedWindowKey))
                {
                    return;
                }

                if (!_lexDeskManagedWindows.TryGetValue(
                        _lexDeskLastManagedWindowKey,
                        out IntPtr hWnd))
                {
                    return;
                }

                if (hWnd == IntPtr.Zero ||
                    !IsWindow(hWnd))
                {
                    _lexDeskManagedWindows.Remove(
                        _lexDeskLastManagedWindowKey);
                    _lexDeskManagedWindowPageIndexes.Remove(
                        _lexDeskLastManagedWindowKey);

                    return;
                }

                ShowWindow(
                    hWnd,
                    LexDeskSwRestore);

                int pageIndex =
                    _lexDeskManagedWindowPageIndexes.TryGetValue(
                        _lexDeskLastManagedWindowKey,
                        out int savedPageIndex)
                        ? savedPageIndex
                        : -1;

                PositionLexDeskManagedWindow(
                    hWnd,
                    pageIndex);

                SetForegroundWindow(
                    hWnd);
            }
            catch
            {
                // Restore convenience must never affect LexDesk.
            }
        }

        private bool TryReuseLexDeskManagedWindow(
    string windowKey,
    string friendlyName,
    string[] expectedProcessNames,
    string[] titleHints,
    string[] classHints,
    int pageIndex = -1,
    bool preserveNativeWindowOwnership = false)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(windowKey))
                    return false;

                // Only reuse a window that LexDesk itself
                // previously found and registered.
                //
                // Do NOT search all Windows processes here.
                // explorer.exe also owns parts of the Windows shell,
                // and Settings can use shared host processes.
                if (!_lexDeskManagedWindows.TryGetValue(
                        windowKey,
                        out IntPtr hWnd))
                {
                    return false;
                }

                if (hWnd == IntPtr.Zero ||
                    !IsWindow(hWnd))
                {
                    _lexDeskManagedWindows.Remove(
                        windowKey);
                    _lexDeskManagedWindowPageIndexes.Remove(
                        windowKey);

                    return false;
                }

                WriteLexDeskManagedWindowDebug(
                    $"REUSE/RESTORE REQUEST | app={windowKey} | " +
                    $"{DescribeLexDeskManagedWindowForDebug(hWnd)}");

                ShowWindow(
                    hWnd,
                    LexDeskSwRestore);

                if (_lexDeskManagedWindowPageIndexes.TryGetValue(
                        windowKey,
                        out int savedPageIndex) &&
                    savedPageIndex >= 0 &&
                    savedPageIndex <= 3)
                {
                    pageIndex = savedPageIndex;
                }

                bool nativeOwnership =
                    preserveNativeWindowOwnership ||
                    _lexDeskManagedNativeShellSessions.Contains(windowKey);

                if (!nativeOwnership)
                {
                    AttachLexDeskManagedWindowToWorkspace(hWnd);
                }
                else
                {
                    // Keep Windows Settings / shell surfaces natively owned by
                    // Windows, but include them in LexDesk's lightweight z-order
                    // assistance so another pane app cannot disappear them behind
                    // the LexDesk browser window.
                    _lexDeskManagedZOrderAssistWindows.Add(hWnd);
                }

                PositionLexDeskManagedWindow(
                    hWnd,
                    pageIndex);

                SetForegroundWindow(
                    hWnd);

                _lexDeskLastManagedWindowKey =
                    windowKey;

                UpdateSecurityStatus(
                    $"{friendlyName} already open",
                    false);

                return true;
            }
            catch
            {
                _lexDeskManagedWindows.Remove(
                    windowKey);
                _lexDeskManagedWindowPageIndexes.Remove(
                    windowKey);

                return false;
            }
        }

        private async Task<bool> LexDeskOpenManagedExternalAsync(
    string target,
    string friendlyName,
    string[] expectedProcessNames,
    string[] titleHints,
    string[] classHints,
    int pageIndex = -1,
    string launchArguments = "",
    string workingDirectory = "",
    bool preserveNativeWindowOwnership = false)
        {
            if (IsLexDeskNativeSecurityPriorityTarget(
                    target,
                    friendlyName))
            {
                return await OpenLexDeskNativeSecurityPrioritySurfaceAsync(
                    target,
                    friendlyName);
            }

            // Some older LexDesk buttons and Search PC paths still call this
            // generic method directly for ms-settings:. Never allow Settings
            // through the shared ApplicationFrameHost capture path.
            if (!string.IsNullOrWhiteSpace(target) &&
                target.Trim().StartsWith(
                    "ms-settings:",
                    StringComparison.OrdinalIgnoreCase))
            {
                return await OpenLexDeskNativeWindowsSurfaceAsync(
                    target.Trim(),
                    string.IsNullOrWhiteSpace(friendlyName)
                        ? "Windows Settings"
                        : friendlyName.Trim());
            }
            if (string.IsNullOrWhiteSpace(target))
                return false;

            CleanupLexDeskManagedWindowRegistrations();

            // Reopening / clicking an already-managed app must keep it in the pane
            // it already owns. Only brand-new app sessions consume the next free pane.
            if (_lexDeskManagedWindowPageIndexes.TryGetValue(
                    friendlyName,
                    out int existingAssignedPage) &&
                existingAssignedPage >= 2 &&
                existingAssignedPage <= 3 &&
                LexDeskManagedSessionHasLiveWindow(friendlyName))
            {
                pageIndex = existingAssignedPage;
            }
            else if (pageIndex < 2 ||
                     pageIndex > 3 ||
                     _paneState[pageIndex] != PaneLifeState.Normal ||
                     IsLexDeskManagedPageOccupied(pageIndex))
            {
                pageIndex =
                    GetLexDeskPreferredManagedPageIndex();
            }

            if (pageIndex < 2 ||
                pageIndex > 3)
            {
                ShowLexDeskNoFreeManagedPaneMessage();
                return false;
            }

            if (preserveNativeWindowOwnership)
            {
                _lexDeskManagedNativeShellSessions.Add(friendlyName);
            }

            // The blue border follows the page that will host the app.
            ActivateLexDeskManagedTargetPage(pageIndex);

            // Prevent two launches while Windows is still
            // creating the first application's window.
            if (_lexDeskManagedLaunchesInProgress.Contains(
                    friendlyName))
            {
                return false;
            }

            // Before launching anything, see whether the
            // application is already open.
            if (TryReuseLexDeskManagedWindow(
        friendlyName,
        friendlyName,
        expectedProcessNames,
        titleHints,
        classHints,
        pageIndex,
        preserveNativeWindowOwnership))
            {
                if (_lexDeskManagedWindows.TryGetValue(
                        friendlyName,
                        out IntPtr reusedHwnd) &&
                    reusedHwnd != IntPtr.Zero &&
                    IsWindow(reusedHwnd))
                {
                    RegisterLexDeskManagedSessionMainWindow(
                        friendlyName,
                        reusedHwnd,
                        pageIndex,
                        expectedProcessNames,
                        titleHints,
                        classHints);
                }

                RefreshLexDeskManagedWindowZOrder();
                return true;
            }

            _lexDeskManagedLaunchesInProgress.Add(
                friendlyName);

            try
            {
                var windowsBeforeLaunch =
    GetLexDeskVisibleTopLevelWindows();

                // TEMP DEBUG: trace every managed app launch, not only Event Viewer.
                bool debugThisLaunch = true;

                if (debugThisLaunch)
                {
                    try
                    {
                        Directory.CreateDirectory(
                            Path.GetDirectoryName(
                                _lexDeskManagedWindowDebugLogPath)!);
                    }
                    catch { }

                    WriteLexDeskManagedWindowDebug(
                        $"BEGIN MANAGED WINDOW TEST | app={friendlyName} | " +
                        $"target={target} | page={pageIndex} | " +
                        $"args={launchArguments} | wd={workingDirectory}");

                    if (TryGetLexDeskManagedPaneScreenBounds(
                            pageIndex,
                            out int debugLeft,
                            out int debugTop,
                            out int debugWidth,
                            out int debugHeight))
                    {
                        WriteLexDeskManagedWindowDebug(
                            $"TARGET BOUNDS | page={pageIndex} | " +
                            $"left={debugLeft} | top={debugTop} | " +
                            $"width={debugWidth} | height={debugHeight}");
                    }
                    else
                    {
                        WriteLexDeskManagedWindowDebug(
                            $"TARGET BOUNDS FAILED | page={pageIndex}");
                    }

                    DumpLexDeskManagedWindowCandidates(
                        "BEFORE PROCESS.START",
                        windowsBeforeLaunch,
                        expectedProcessNames,
                        titleHints,
                        classHints);
                }

                var launchInfo =
                    new ProcessStartInfo(target)
                    {
                        UseShellExecute = true
                    };

                if (!string.IsNullOrWhiteSpace(launchArguments))
                    launchInfo.Arguments = launchArguments;

                if (!string.IsNullOrWhiteSpace(workingDirectory) &&
                    Directory.Exists(workingDirectory))
                {
                    launchInfo.WorkingDirectory = workingDirectory;
                }

                Process? launchedProcess = null;
                bool launchedByKnownGoodRoute = false;

                // Bitdefender deliberately rejects a normal direct Process.Start
                // of seccenter.exe on some installs. LexDesk already had a
                // known-good cmd /c start route for this stubborn app, so keep
                // that launch behaviour and let the existing managed-window
                // capture code position the Bitdefender window in its pane.
                bool useKnownGoodBitdefenderLaunch =
                    target.Equals(
                        @"C:\Program Files\Bitdefender\Bitdefender Security App\seccenter.exe",
                        StringComparison.OrdinalIgnoreCase);

                if (useKnownGoodBitdefenderLaunch)
                {
                    launchedByKnownGoodRoute =
                        TryLaunchLexDeskViaCmdStart(
                            target,
                            launchArguments,
                            workingDirectory);

                    if (!launchedByKnownGoodRoute)
                    {
                        UpdateSecurityStatus(
                            "LexDesk could not start Bitdefender using its known-good launch route",
                            true);

                        return false;
                    }
                }
                else
                {
                    launchedProcess =
                        Process.Start(launchInfo);
                }

                if (debugThisLaunch)
                {
                    string launchedPid =
                        launchedByKnownGoodRoute
                            ? "<cmd-start>"
                            : "<null>";

                    try
                    {
                        if (launchedProcess != null)
                            launchedPid =
                                launchedProcess.Id.ToString();
                    }
                    catch { }

                    WriteLexDeskManagedWindowDebug(
                        $"Process.Start returned PID={launchedPid}");
                }

                int captureAttemptLimit =
                    useKnownGoodBitdefenderLaunch
                        ? 120
                        : 40;

                for (int attempt = 0;
                     attempt < captureAttemptLimit;
                     attempt++)
                {
                    await Task.Delay(
                        attempt == 0
                            ? 200
                            : 100);

                    if (debugThisLaunch &&
    (attempt == 0 ||
     attempt == 2 ||
     attempt == 5 ||
     attempt == 10 ||
     attempt == 20 ||
     attempt == captureAttemptLimit - 1))
                    {
                        DumpLexDeskManagedWindowCandidates(
                            $"SEARCH ATTEMPT {attempt}",
                            windowsBeforeLaunch,
                            expectedProcessNames,
                            titleHints,
                            classHints);
                    }

                    IntPtr hWnd =
                        FindLexDeskManagedWindow(
                            windowsBeforeLaunch,
                            expectedProcessNames,
                            titleHints,
                            classHints);

                    if (hWnd == IntPtr.Zero)
                        continue;

                    if (debugThisLaunch)
                    {
                        WriteLexDeskManagedWindowDebug(
                            $"SELECTED HWND=0x{hWnd.ToInt64():X} | " +
                            $"PROCESS={GetLexDeskWindowProcessName(hWnd)} | " +
                            $"CLASS={GetLexDeskWindowClass(hWnd)} | " +
                            $"TITLE={GetLexDeskWindowTitle(hWnd)}");
                    }

                    await Task.Delay(120);

                    // Normal desktop apps can be owned by LexDesk so they stay over
                    // their reserved pane. Windows Settings / shell-integrated surfaces
                    // keep their native Windows ownership; LexDesk only moves/resizes them.
                    if (!preserveNativeWindowOwnership)
                    {
                        AttachLexDeskManagedWindowToWorkspace(hWnd);
                    }
                    else
                    {
                        // Do NOT re-parent Windows Settings / Windows Security.
                        // They stay native Windows windows, but LexDesk still keeps
                        // them above its own workspace while they occupy a pane.
                        _lexDeskManagedZOrderAssistWindows.Add(hWnd);
                    }

                    bool positioned =
                    PositionLexDeskManagedWindow(
                        hWnd,
                        pageIndex);

                    if (!positioned)
                        continue;

                    await Task.Delay(180);

                    // Splash/launcher windows can vanish between the first and second
                    // positioning pass. Never register a dead HWND as the real app.
                    if (!IsWindow(hWnd))
                    {
                        if (debugThisLaunch)
                        {
                            WriteLexDeskManagedWindowDebug(
                                $"WINDOW VANISHED BEFORE REGISTER | HWND=0x{hWnd.ToInt64():X}");
                        }

                        continue;
                    }

                    PositionLexDeskManagedWindow(
                        hWnd,
                        pageIndex);

                    RegisterLexDeskManagedSessionMainWindow(
                        friendlyName,
                        hWnd,
                        pageIndex,
                        expectedProcessNames,
                        titleHints,
                        classHints);

                    _lexDeskLastManagedWindowKey =
                        friendlyName;

                    if (debugThisLaunch)
                    {
                        WriteLexDeskManagedWindowDebug(
                            $"REGISTERED HWND=0x{hWnd.ToInt64():X}");
                    }

                    SetForegroundWindow(
                        hWnd);

                    // One deliberate refresh after launch keeps any already-open
                    // hosted apps (Calculator / Settings) visible in their panes.
                    RefreshLexDeskManagedWindowZOrder();

                    UpdateSecurityStatus(
                        $"{friendlyName} opened in LexDesk workspace",
                        false);

                    return true;
                }

                if (debugThisLaunch)
                {
                    DumpLexDeskManagedWindowCandidates(
                        "FINAL - NO WINDOW CAPTURED",
                        windowsBeforeLaunch,
                        expectedProcessNames,
                        titleHints,
                        classHints);

                    WriteLexDeskManagedWindowDebug(
                        $"CAPTURE FAILED | app={friendlyName} | page={pageIndex} | " +
                        $"processStarted={launchedByKnownGoodRoute || launchedProcess != null}");
                }

                UpdateSecurityStatus(
                    $"{friendlyName} opened outside managed pane - debug log written",
                    true);

                return launchedByKnownGoodRoute || launchedProcess != null;
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    $"LexDesk Pro could not open {friendlyName}.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "LexDesk Pro",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);

                return false;
            }
            finally
            {
                _lexDeskManagedLaunchesInProgress.Remove(
                    friendlyName);

                if (!LexDeskManagedSessionHasLiveWindow(friendlyName))
                {
                    _lexDeskManagedNativeShellSessions.Remove(
                        friendlyName);
                }
            }
        }

        private IntPtr FindLexDeskNativeWindowsSettingsWindow()
        {
            IntPtr bestHwnd =
                IntPtr.Zero;

            int bestScore =
                int.MinValue;

            try
            {
                IntPtr foreground =
                    GetForegroundWindow();

                EnumWindows((hWnd, _) =>
                {
                    try
                    {
                        if (hWnd == IntPtr.Zero ||
                            !IsWindow(hWnd))
                        {
                            return true;
                        }

                        string processName =
                            GetLexDeskWindowProcessName(hWnd);

                        string title =
                            GetLexDeskWindowTitle(hWnd);

                        string className =
                            GetLexDeskWindowClass(hWnd);

                        bool settingsTitle =
                            title.Contains(
                                "Settings",
                                StringComparison.OrdinalIgnoreCase) ||
                            title.Contains(
                                "Windows Security",
                                StringComparison.OrdinalIgnoreCase);

                        if (!settingsTitle)
                            return true;

                        bool validProcess =
                            processName.Equals(
                                "ApplicationFrameHost",
                                StringComparison.OrdinalIgnoreCase) ||
                            processName.Equals(
                                "SystemSettings",
                                StringComparison.OrdinalIgnoreCase) ||
                            processName.Equals(
                                "SecHealthUI",
                                StringComparison.OrdinalIgnoreCase);

                        if (!validProcess)
                            return true;

                        int score = 0;

                        // Prefer the visible ApplicationFrameHost frame because it
                        // carries the Windows chrome and is what the user sees.
                        if (processName.Equals(
                                "ApplicationFrameHost",
                                StringComparison.OrdinalIgnoreCase))
                        {
                            score += 1000;
                        }
                        else if (processName.Equals(
                                     "SystemSettings",
                                     StringComparison.OrdinalIgnoreCase))
                        {
                            score += 800;
                        }
                        else
                        {
                            score += 700;
                        }

                        if (IsWindowVisible(hWnd))
                            score += 200;

                        if (hWnd == foreground)
                            score += 100;

                        if (className.Equals(
                                "ApplicationFrameWindow",
                                StringComparison.OrdinalIgnoreCase))
                        {
                            score += 100;
                        }

                        // Never let the dedicated Settings finder steal a HWND
                        // already registered to another live app session.
                        if (_lexDeskManagedWindowFamilyKeys.TryGetValue(
                                hWnd,
                                out string? existingKey) &&
                            !string.Equals(
                                existingKey,
                                "Windows Settings",
                                StringComparison.OrdinalIgnoreCase) &&
                            LexDeskManagedSessionHasLiveWindow(
                                existingKey))
                        {
                            return true;
                        }

                        if (score > bestScore)
                        {
                            bestScore = score;
                            bestHwnd = hWnd;
                        }
                    }
                    catch { }

                    return true;
                }, IntPtr.Zero);
            }
            catch
            {
                return IntPtr.Zero;
            }

            return bestHwnd;
        }

        private async Task<bool> OpenLexDeskNativeWindowsSurfaceAsync(
            string target,
            string friendlyName)
        {
            target =
                (target ?? "").Trim();

            friendlyName =
                string.IsNullOrWhiteSpace(friendlyName)
                    ? "Windows Settings"
                    : friendlyName.Trim();

            if (string.IsNullOrWhiteSpace(target))
                return false;

            // Antivirus / Windows Security keeps the higher-priority centre-stage
            // behaviour already established for LexDesk.
            if (IsLexDeskNativeSecurityPriorityTarget(
                    target,
                    friendlyName))
            {
                return await OpenLexDeskNativeSecurityPrioritySurfaceAsync(
                    target,
                    friendlyName);
            }

            WriteLexDeskManagedWindowDebug(
                $"WINDOWS UTILITY REQUEST | friendly={friendlyName} | target={target}");

            try
            {
                // Always launch the requested URI so an already-open Settings app
                // navigates to the exact page the customer asked for.
                Process.Start(
                    new ProcessStartInfo(target)
                    {
                        UseShellExecute = true
                    });
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro could not open Windows Settings.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "LexDesk Pro",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);

                return false;
            }

            IntPtr hWnd =
                IntPtr.Zero;

            // Windows may reuse an existing Settings frame rather than create a
            // new HWND. Give it a moment to navigate, then find the real frame.
            for (int attempt = 0;
                 attempt < 50;
                 attempt++)
            {
                await Task.Delay(
                    attempt == 0
                        ? 250
                        : 100);

                hWnd =
                    FindLexDeskNativeWindowsSettingsWindow();

                if (hWnd != IntPtr.Zero &&
                    IsWindow(hWnd))
                {
                    break;
                }
            }

            if (hWnd == IntPtr.Zero ||
                !IsWindow(hWnd))
            {
                // Settings itself may still have opened successfully. Do not turn
                // that into an error or try to launch it a second time.
                UpdateSecurityStatus(
                    $"{friendlyName} opened in Windows",
                    false);

                return true;
            }

            // IMPORTANT:
            // Keep Settings fully native. No pane reservation, no owner change,
            // no shared-host family registration. We only restore, centre and
            // bring the requested utility page forward.
            ShowWindow(
                hWnd,
                LexDeskSwRestore);

            PositionLexDeskPriorityOverlayWindow(
                hWnd,
                friendlyName);

            SetForegroundWindow(
                hWnd);

            UpdateSecurityStatus(
                $"{friendlyName} opened",
                false);

            WriteLexDeskManagedWindowDebug(
                $"WINDOWS UTILITY CENTRED | " +
                $"friendly={friendlyName} | " +
                $"{DescribeLexDeskManagedWindowForDebug(hWnd)}");

            return true;
        }

        private async void LexDeskOpenExternal(string target)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(target))
                    return;

                string trimmedTarget =
                    target.Trim();

                if (trimmedTarget.StartsWith(
                        "ms-settings:",
                        StringComparison.OrdinalIgnoreCase))
                {
                    await OpenLexDeskNativeWindowsSurfaceAsync(
                        trimmedTarget,
                        "Windows Settings");

                    return;
                }

                int pageIndex =
                    GetLexDeskPreferredManagedPageIndex();

                string friendlyName = "Windows App";
                string[] processNames = Array.Empty<string>();
                string[] titleHints = Array.Empty<string>();
                string[] classHints = Array.Empty<string>();

                string fileName = "";

                try
                {
                    fileName =
                        Path.GetFileName(trimmedTarget) ?? "";
                }
                catch
                {
                    fileName = "";
                }

                if (Directory.Exists(trimmedTarget))
                {
                    string folderName =
                        Path.GetFileName(
                            trimmedTarget.TrimEnd(
                                Path.DirectorySeparatorChar,
                                Path.AltDirectorySeparatorChar));

                    friendlyName =
                        string.IsNullOrWhiteSpace(folderName)
                            ? "File Explorer"
                            : folderName;

                    processNames = new[] { "explorer" };
                    titleHints =
                        string.IsNullOrWhiteSpace(folderName)
                            ? Array.Empty<string>()
                            : new[] { folderName };
                    classHints = new[] { "CabinetWClass" };
                }
                else
                {
                    switch (fileName.ToLowerInvariant())
                    {
                        case "explorer.exe":
                            friendlyName = "File Explorer";
                            processNames = new[] { "explorer" };
                            classHints = new[] { "CabinetWClass" };
                            break;

                        case "powershell.exe":
                            friendlyName = "PowerShell";
                            processNames =
                                new[]
                                {
                                    "powershell",
                                    "WindowsTerminal",
                                    "OpenConsole"
                                };
                            titleHints =
                                new[]
                                {
                                    "PowerShell",
                                    "Windows PowerShell"
                                };
                            classHints =
                                new[]
                                {
                                    "ConsoleWindowClass",
                                    "CASCADIA_HOSTING_WINDOW_CLASS"
                                };
                            break;

                        case "regedit.exe":
                            friendlyName = "Registry Editor";
                            processNames = new[] { "regedit" };
                            titleHints = new[] { "Registry Editor" };
                            break;

                        case "services.msc":
                            friendlyName = "Windows Services";
                            processNames = new[] { "mmc" };
                            titleHints = new[] { "Services" };
                            classHints = new[] { "MMCMainFrame" };
                            break;

                        case "eventvwr.msc":
                            friendlyName = "Event Viewer";
                            processNames = new[] { "mmc" };
                            titleHints = new[] { "Event Viewer" };
                            classHints = new[] { "MMCMainFrame" };
                            break;

                        case "devmgmt.msc":
                            friendlyName = "Device Manager";
                            processNames = new[] { "mmc" };
                            titleHints = new[] { "Device Manager" };
                            classHints = new[] { "MMCMainFrame" };
                            break;

                        case "diskmgmt.msc":
                            friendlyName = "Disk Management";
                            processNames = new[] { "mmc" };
                            titleHints = new[] { "Disk Management" };
                            classHints = new[] { "MMCMainFrame" };
                            break;

                        case "msinfo32.exe":
                            friendlyName = "System Information";
                            processNames = new[] { "msinfo32" };
                            titleHints = new[] { "System Information" };
                            break;

                        case "resmon.exe":
                            friendlyName = "Resource Monitor";
                            processNames = new[] { "resmon", "perfmon" };
                            titleHints = new[] { "Resource Monitor" };
                            break;

                        case "control.exe":
                            friendlyName = "Control Panel";
                            processNames = new[] { "explorer", "control" };
                            titleHints = new[] { "Control Panel" };
                            classHints = new[] { "CabinetWClass" };
                            break;

                        default:
                            if (fileName.EndsWith(
                                    ".msc",
                                    StringComparison.OrdinalIgnoreCase))
                            {
                                friendlyName =
                                    Path.GetFileNameWithoutExtension(fileName);
                                processNames = new[] { "mmc" };
                                classHints = new[] { "MMCMainFrame" };
                            }
                            else if (fileName.EndsWith(
                                         ".exe",
                                         StringComparison.OrdinalIgnoreCase))
                            {
                                friendlyName =
                                    Path.GetFileNameWithoutExtension(fileName);
                                processNames = new[] { friendlyName };
                            }
                            else
                            {
                                friendlyName =
                                    string.IsNullOrWhiteSpace(fileName)
                                        ? "Windows App"
                                        : fileName;
                            }
                            break;
                    }
                }

                await LexDeskOpenManagedExternalAsync(
                    trimmedTarget,
                    friendlyName,
                    processNames,
                    titleHints,
                    classHints,
                    pageIndex);
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro could not open that item inside the workspace.\n\n" +
                    SanitizeExceptionMessage(ex),
                    "LexDesk Pro",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

