        private LexDeskProblemKind _lexDeskActiveProblem = LexDeskProblemKind.None;
        private bool _lexDeskProblemBusy;
        private bool _lexDeskProblemSafeFixAvailable;
        private string _lexDeskProblemSettingsTarget = "";
        private LexDeskSoundSafeFixKind _lexDeskSoundSafeFixKind = LexDeskSoundSafeFixKind.None;

        private enum LexDeskProblemDetailTone
        {
            Normal,
            Good,
            Attention,
            Critical
        }

        private void SetLexDeskProblemSolverStatus(
            string text,
            bool? needsAttention = null,
            string? title = null)
        {
            if (LexDeskProblemSolverTitleText != null && !string.IsNullOrWhiteSpace(title))
                LexDeskProblemSolverTitleText.Text = title;

            if (LexDeskProblemSolverStatusText == null)
                return;

            LexDeskProblemSolverStatusText.Text = text ?? "";

            if (needsAttention.HasValue)
            {
                LexDeskProblemSolverStatusText.Foreground =
                    GetPcHealthBrush(needsAttention.Value);
            }
            else
            {
                LexDeskProblemSolverStatusText.Foreground =
                    TryFindResource("TextSecondary") as Brush ?? Brushes.Gray;
            }
        }

        private Brush GetLexDeskProblemDetailBrush(LexDeskProblemDetailTone tone)
        {
            string key = tone switch
            {
                LexDeskProblemDetailTone.Good => "StatusGreenBrush",
                LexDeskProblemDetailTone.Attention => "StatusOrangeBrush",
                LexDeskProblemDetailTone.Critical => "StatusRedBrush",
                _ => "TextSecondary"
            };

            return TryFindResource(key) as Brush ??
                   (tone switch
                   {
                       LexDeskProblemDetailTone.Good => Brushes.ForestGreen,
                       LexDeskProblemDetailTone.Attention => Brushes.DarkOrange,
                       LexDeskProblemDetailTone.Critical => Brushes.IndianRed,
                       _ => Brushes.Gray
                   });
        }

        private void ClearLexDeskProblemDetails()
        {
            if (LexDeskProblemSolverDetailPanel == null)
                return;

            LexDeskProblemSolverDetailPanel.Children.Clear();
            LexDeskProblemSolverDetailPanel.Visibility = Visibility.Collapsed;
        }

        private void AddLexDeskProblemDetail(
            string text,
            LexDeskProblemDetailTone tone = LexDeskProblemDetailTone.Normal,
            bool bold = false)
        {
            if (LexDeskProblemSolverDetailPanel == null || string.IsNullOrWhiteSpace(text))
                return;

            var line = new TextBlock
            {
                Text = text,
                FontSize = 12,
                TextWrapping = TextWrapping.Wrap,
                Foreground = GetLexDeskProblemDetailBrush(tone),
                FontWeight = bold ? FontWeights.SemiBold : FontWeights.Normal,
                Margin = new Thickness(0, 0, 0, 3)
            };

            LexDeskProblemSolverDetailPanel.Children.Add(line);
            LexDeskProblemSolverDetailPanel.Visibility = Visibility.Visible;
        }

        private void SetLexDeskProblemSolverBusy(bool busy)
        {
            _lexDeskProblemBusy = busy;

            if (LexDeskProblemSlowPcButton != null)
                LexDeskProblemSlowPcButton.IsEnabled = !busy;

            if (LexDeskProblemInternetButton != null)
                LexDeskProblemInternetButton.IsEnabled = !busy;

            if (LexDeskProblemSoundButton != null)
                LexDeskProblemSoundButton.IsEnabled = !busy;

            if (LexDeskProblemPrinterButton != null)
                LexDeskProblemPrinterButton.IsEnabled = !busy;

            if (LexDeskProblemSafeFixButton != null)
                LexDeskProblemSafeFixButton.IsEnabled =
                    !busy && _lexDeskProblemSafeFixAvailable;

            if (LexDeskProblemOpenSettingsButton != null)
                LexDeskProblemOpenSettingsButton.IsEnabled =
                    !busy && !string.IsNullOrWhiteSpace(_lexDeskProblemSettingsTarget);

            if (LexDeskProblemCheckAgainButton != null)
                LexDeskProblemCheckAgainButton.IsEnabled =
                    !busy && _lexDeskActiveProblem != LexDeskProblemKind.None;

            if (LexDeskProblemSolverProgressBar != null)
            {
                LexDeskProblemSolverProgressBar.Visibility =
                    busy ? Visibility.Visible : Visibility.Collapsed;
            }
        }

        private void ConfigureLexDeskProblemActions(
            string safeFixText,
            bool safeFixAvailable,
            string settingsText,
            string settingsTarget)
        {
            _lexDeskProblemSafeFixAvailable = safeFixAvailable;
            _lexDeskProblemSettingsTarget = settingsTarget ?? "";

            if (LexDeskProblemSafeFixButton != null)
            {
                LexDeskProblemSafeFixButton.Content =
                    string.IsNullOrWhiteSpace(safeFixText) ? "Safe Fix" : safeFixText;
            }

            if (LexDeskProblemOpenSettingsButton != null)
            {
                LexDeskProblemOpenSettingsButton.Content =
                    string.IsNullOrWhiteSpace(settingsText) ? "Open Settings" : settingsText;
            }

            SetLexDeskProblemSolverBusy(_lexDeskProblemBusy);
        }

        private static int CountRegistryRunItems(RegistryKey root, string subKeyPath)
        {
            try
            {
                using RegistryKey? key = root.OpenSubKey(subKeyPath, writable: false);
                return key?.GetValueNames().Length ?? 0;
            }
            catch
            {
                return 0;
            }
        }

        private static int CountStartupFolderItems(string folder)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(folder) || !Directory.Exists(folder))
                    return 0;

                return Directory.EnumerateFileSystemEntries(folder).Count();
            }
            catch
            {
                return 0;
            }
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct LexDeskFileTime
        {
            public uint LowDateTime;
            public uint HighDateTime;
        }

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool GetSystemTimes(
            out LexDeskFileTime idleTime,
            out LexDeskFileTime kernelTime,
            out LexDeskFileTime userTime);

        private static ulong LexDeskFileTimeToUInt64(LexDeskFileTime value)
        {
            return ((ulong)value.HighDateTime << 32) | value.LowDateTime;
        }

        private static int SampleLexDeskCpuPercent()
        {
            try
            {
                if (GetSystemTimes(out LexDeskFileTime idle1, out LexDeskFileTime kernel1, out LexDeskFileTime user1))
                {
                    // A short average is much more useful than one instant WMI reading.
                    System.Threading.Thread.Sleep(1500);

                    if (GetSystemTimes(out LexDeskFileTime idle2, out LexDeskFileTime kernel2, out LexDeskFileTime user2))
                    {
                        ulong idleDelta = LexDeskFileTimeToUInt64(idle2) - LexDeskFileTimeToUInt64(idle1);
                        ulong kernelDelta = LexDeskFileTimeToUInt64(kernel2) - LexDeskFileTimeToUInt64(kernel1);
                        ulong userDelta = LexDeskFileTimeToUInt64(user2) - LexDeskFileTimeToUInt64(user1);
                        ulong totalDelta = kernelDelta + userDelta;

                        if (totalDelta > 0 && idleDelta <= totalDelta)
                        {
                            double busy = (totalDelta - idleDelta) * 100.0 / totalDelta;
                            return (int)Math.Round(Math.Clamp(busy, 0, 100));
                        }
                    }
                }
            }
            catch { }

            // Fallback for unusual Windows builds where GetSystemTimes is unavailable.
            try
            {
                using var cpuSearch = new ManagementObjectSearcher(
                    "SELECT LoadPercentage FROM Win32_Processor");

                var values = new List<int>();

                foreach (ManagementBaseObject item in cpuSearch.Get())
                {
                    if (item["LoadPercentage"] != null &&
                        int.TryParse(item["LoadPercentage"].ToString(), out int load))
                    {
                        values.Add(Math.Clamp(load, 0, 100));
                    }
                }

                if (values.Count > 0)
                    return (int)Math.Round(values.Average());
            }
            catch { }

            return -1;
        }

        private static bool LexDeskContainsAny(string text, params string[] terms)
        {
            if (string.IsNullOrWhiteSpace(text))
                return false;

            foreach (string term in terms)
            {
                if (!string.IsNullOrWhiteSpace(term) &&
                    text.Contains(term, StringComparison.OrdinalIgnoreCase))
                {
                    return true;
                }
            }

            return false;
        }

        private static LexDeskStartupAdviceItem CreateLexDeskStartupAdvice(
            string name,
            string command)
        {
            string safeName = string.IsNullOrWhiteSpace(name) ? "Startup item" : name.Trim();
            string combined = (safeName + " " + (command ?? "")).ToLowerInvariant();

            if (LexDeskContainsAny(
                    combined,
                    "lexdesk", "defender", "securityhealth", "antivirus", "anti-virus",
                    "bitdefender", "norton", "mcafee", "malwarebytes", "eset", "avast", "avg"))
            {
                return new LexDeskStartupAdviceItem
                {
                    Name = safeName,
                    Advice = "Keep",
                    Reason = "Security or LexDesk protection. Usually leave this starting with Windows.",
                    RecommendedKeep = true
                };
            }

            if (LexDeskContainsAny(
                    combined,
                    "realtek", "touchpad", "synaptics", "hotkey", "bluetooth",
                    "audio", "intel graphics", "nvidia", "amd software", "logitech"))
            {
                return new LexDeskStartupAdviceItem
                {
                    Name = safeName,
                    Advice = "Usually keep",
                    Reason = "Hardware, sound, graphics or device helper. Leave it on unless you know it is unnecessary.",
                    RecommendedKeep = true
                };
            }

            if (LexDeskContainsAny(
                    combined,
                    "onedrive", "dropbox", "google drive", "googledrive", "icloud"))
            {
                return new LexDeskStartupAdviceItem
                {
                    Name = safeName,
                    Advice = "Your choice",
                    Reason = "File syncing. Keep it on if you want files to sync automatically."
                };
            }

            if (LexDeskContainsAny(
                    combined,
                    "steam", "epic", "discord", "spotify", "teams", "zoom", "skype", "chatgpt", "openai",
                    "launcher", "creative cloud", "adobe updater", "update helper", "game"))
            {
                return new LexDeskStartupAdviceItem
                {
                    Name = safeName,
                    Advice = "Optional",
                    Reason = "Usually does not need to start with Windows unless you use it straight away.",
                    WorthReviewing = true
                };
            }

            return new LexDeskStartupAdviceItem
            {
                Name = safeName,
                Advice = "Review",
                Reason = "LexDesk is not certain what this item does. Do not disable it unless you recognise it."
            };
        }

        // ============================================================
        // Stage 6.1 - Enabled Startup Apps
        // Windows keeps enabled/disabled state in Explorer\StartupApproved.
        // Count only entries Windows currently marks as enabled.
        // ============================================================

        private static bool IsLexDeskStartupApprovedEnabled(object? rawValue)
        {
            try
            {
                if (rawValue is not byte[] bytes || bytes.Length == 0)
                    return false;

                // Known enabled states used by modern Windows.
                // 02 = enabled, 06 = enabled variant, 08 = enabled / protected.
                return bytes[0] == 0x02 ||
                       bytes[0] == 0x06 ||
                       bytes[0] == 0x08;
            }
            catch
            {
                return false;
            }
        }

        private static string ReadLexDeskRunCommand(
            RegistryKey root,
            string runSubKeyPath,
            string valueName)
        {
            try
            {
                using RegistryKey? runKey =
                    root.OpenSubKey(runSubKeyPath, writable: false);

                return runKey?.GetValue(valueName)?.ToString() ?? "";
            }
            catch
            {
                return "";
            }
        }

        private static void AddLexDeskApprovedRunItems(
            List<LexDeskStartupAdviceItem> items,
            RegistryKey approvedRoot,
            string approvedSubKeyPath,
            RegistryKey runRoot,
            string runSubKeyPath)
        {
            try
            {
                using RegistryKey? approvedKey =
                    approvedRoot.OpenSubKey(approvedSubKeyPath, writable: false);

                if (approvedKey == null)
                    return;

                foreach (string valueName in approvedKey.GetValueNames())
                {
                    object? approvedValue = approvedKey.GetValue(valueName);

                    if (!IsLexDeskStartupApprovedEnabled(approvedValue))
                        continue;

                    string command =
                        ReadLexDeskRunCommand(runRoot, runSubKeyPath, valueName);

                    // Some packaged apps have an approved startup registration
                    // without a normal Run command. The display name is still useful.
                    if (string.IsNullOrWhiteSpace(command))
                        command = valueName;

                    items.Add(CreateLexDeskStartupAdvice(valueName, command));
                }
            }
            catch
            {
                // One unreadable startup location must not break the speed check.
            }
        }

        private static void AddLexDeskApprovedStartupFolderItems(
            List<LexDeskStartupAdviceItem> items,
            RegistryKey approvedRoot,
            string approvedSubKeyPath,
            string startupFolder)
        {
            try
            {
                using RegistryKey? approvedKey =
                    approvedRoot.OpenSubKey(approvedSubKeyPath, writable: false);

                if (approvedKey == null)
                    return;

                foreach (string valueName in approvedKey.GetValueNames())
                {
                    object? approvedValue = approvedKey.GetValue(valueName);

                    if (!IsLexDeskStartupApprovedEnabled(approvedValue))
                        continue;

                    string command = valueName;

                    if (!string.IsNullOrWhiteSpace(startupFolder))
                    {
                        try
                        {
                            string candidate = Path.Combine(startupFolder, valueName);

                            if (File.Exists(candidate) || Directory.Exists(candidate))
                                command = candidate;
                        }
                        catch { }
                    }

                    string displayName = Path.GetFileNameWithoutExtension(valueName);

                    if (string.IsNullOrWhiteSpace(displayName))
                        displayName = valueName;

                    items.Add(CreateLexDeskStartupAdvice(displayName, command));
                }
            }
            catch
            {
                // A missing Startup folder is normal on many PCs.
            }
        }

        private static List<LexDeskStartupAdviceItem> GatherLexDeskStartupAdvice()
        {
            var items = new List<LexDeskStartupAdviceItem>();

            const string startupApprovedBase =
                @"SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved";

            // Current-user Run items.
            AddLexDeskApprovedRunItems(
                items,
                Registry.CurrentUser,
                startupApprovedBase + @"\Run",
                Registry.CurrentUser,
                @"Software\Microsoft\Windows\CurrentVersion\Run");

            // 64-bit machine-wide Run items.
            AddLexDeskApprovedRunItems(
                items,
                Registry.LocalMachine,
                startupApprovedBase + @"\Run",
                Registry.LocalMachine,
                @"SOFTWARE\Microsoft\Windows\CurrentVersion\Run");

            // 32-bit machine-wide Run items.
            AddLexDeskApprovedRunItems(
                items,
                Registry.LocalMachine,
                startupApprovedBase + @"\Run32",
                Registry.LocalMachine,
                @"SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run");

            // Personal Startup folder.
            AddLexDeskApprovedStartupFolderItems(
                items,
                Registry.CurrentUser,
                startupApprovedBase + @"\StartupFolder",
                Environment.GetFolderPath(Environment.SpecialFolder.Startup));

            // All-users Startup folder.
            AddLexDeskApprovedStartupFolderItems(
                items,
                Registry.LocalMachine,
                startupApprovedBase + @"\StartupFolder",
                Environment.GetFolderPath(Environment.SpecialFolder.CommonStartup));

            return items
                .Where(x => !string.IsNullOrWhiteSpace(x.Name))
                .GroupBy(x => x.Name, StringComparer.OrdinalIgnoreCase)
                .Select(g => g.First())
                .OrderByDescending(x => x.WorthReviewing)
                .ThenByDescending(x => x.RecommendedKeep)
                .ThenBy(x => x.Name, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private LexDeskSlowPcCheck GatherLexDeskSlowPcCheck()
        {
            int cpuPercent = SampleLexDeskCpuPercent();
            ulong totalMemory = 0;
            ulong freeMemory = 0;

            try
            {
                using var osSearch = new ManagementObjectSearcher(
                    "SELECT TotalVisibleMemorySize, FreePhysicalMemory FROM Win32_OperatingSystem");

                foreach (ManagementBaseObject item in osSearch.Get())
                {
                    if (ulong.TryParse(item["TotalVisibleMemorySize"]?.ToString(), out ulong totalKb))
                        totalMemory = totalKb * 1024UL;

                    if (ulong.TryParse(item["FreePhysicalMemory"]?.ToString(), out ulong freeKb))
                        freeMemory = freeKb * 1024UL;

                    break;
                }
            }
            catch { }

            long driveTotal = 0;
            long driveFree = 0;

            try
            {
                string windowsRoot =
                    Path.GetPathRoot(Environment.GetFolderPath(Environment.SpecialFolder.Windows)) ?? "C:\\";

                var drive = new DriveInfo(windowsRoot);

                if (drive.IsReady)
                {
                    driveTotal = drive.TotalSize;
                    driveFree = drive.AvailableFreeSpace;
                }
            }
            catch { }

            List<LexDeskStartupAdviceItem> startupItems = GatherLexDeskStartupAdvice();

            return new LexDeskSlowPcCheck
            {
                CpuPercent = cpuPercent,
                TotalMemoryBytes = totalMemory,
                FreeMemoryBytes = freeMemory,
                DriveTotalBytes = driveTotal,
                DriveFreeBytes = driveFree,
                StartupItemCount = startupItems.Count,
                RestartPending = IsWindowsRestartPending(),
                StartupItems = startupItems
            };
        }

        private async Task<LexDeskInternetCheck> GatherLexDeskInternetCheckAsync()
        {
            bool networkAvailable = NetworkInterface.GetIsNetworkAvailable();
            string adapterName = "";
            string gateway = "";

            try
            {
                NetworkInterface? adapter =
                    NetworkInterface.GetAllNetworkInterfaces()
                        .Where(n =>
                            n.OperationalStatus == OperationalStatus.Up &&
                            n.NetworkInterfaceType != NetworkInterfaceType.Loopback &&
                            n.NetworkInterfaceType != NetworkInterfaceType.Tunnel)
                        .OrderByDescending(n =>
                            n.GetIPProperties().GatewayAddresses.Any(g =>
                                g.Address != null &&
                                !g.Address.Equals(System.Net.IPAddress.Any) &&
                                !g.Address.Equals(System.Net.IPAddress.IPv6Any)))
                        .FirstOrDefault();

                if (adapter != null)
                {
                    adapterName = adapter.Name ?? "";

                    gateway =
                        adapter.GetIPProperties()
                            .GatewayAddresses
                            .Select(g => g.Address?.ToString() ?? "")
                            .FirstOrDefault(v =>
                                !string.IsNullOrWhiteSpace(v) &&
                                v != "0.0.0.0" &&
                                v != "::") ?? "";
                }
            }
            catch { }

            bool dnsWorked = false;

            if (networkAvailable)
            {
                try
                {
                    System.Net.IPAddress[] addresses =
                        await System.Net.Dns.GetHostAddressesAsync("www.microsoft.com")
                            .WaitAsync(TimeSpan.FromSeconds(5));

                    dnsWorked = addresses.Length > 0;
                }
                catch
                {
                    dnsWorked = false;
                }
            }

            bool httpsWorked = false;
            string httpsNote = "";

            if (networkAvailable && dnsWorked)
            {
                try
                {
                    using var client = new HttpClient
                    {
                        Timeout = TimeSpan.FromSeconds(7)
                    };

                    using var request = new HttpRequestMessage(
                        HttpMethod.Get,
                        "https://www.microsoft.com/");

                    using HttpResponseMessage response =
                        await client.SendAsync(
                            request,
                            HttpCompletionOption.ResponseHeadersRead);

                    httpsWorked = (int)response.StatusCode >= 200 &&
                                  (int)response.StatusCode < 500;

                    if (!httpsWorked)
                        httpsNote = $"Web test returned {(int)response.StatusCode}.";
                }
                catch (Exception ex)
                {
                    httpsWorked = false;
                    httpsNote = SanitizeExceptionMessage(ex);
                }
            }

            return new LexDeskInternetCheck
            {
                NetworkAvailable = networkAvailable,
                AdapterName = adapterName,
                Gateway = gateway,
                DnsWorked = dnsWorked,
                HttpsWorked = httpsWorked,
                HttpsNote = httpsNote
            };
        }

        private static string GetWmiServiceState(string serviceName)
        {
            try
            {
                string safeName = (serviceName ?? "").Replace("'", "''");

                using var searcher = new ManagementObjectSearcher(
                    $"SELECT State FROM Win32_Service WHERE Name='{safeName}'");

                foreach (ManagementBaseObject item in searcher.Get())
                    return item["State"]?.ToString() ?? "";
            }
            catch { }

            return "";
        }

        private enum LexDeskAudioDataFlow
        {
            Render = 0,
            Capture = 1,
            All = 2
        }

        private enum LexDeskAudioRole
        {
            Console = 0,
            Multimedia = 1,
            Communications = 2
        }

        [ComImport]
        [Guid("BCDE0395-E52F-467C-8E3D-C4579291692E")]
        private class LexDeskMmDeviceEnumeratorComObject
