        [StructLayout(LayoutKind.Sequential)]
        private struct LexDeskPropertyKey
        {
            public Guid FormatId;
            public uint PropertyId;
        }

        [StructLayout(LayoutKind.Explicit)]
        private struct LexDeskPropVariant
        {
            [FieldOffset(0)] public ushort VariantType;
            [FieldOffset(8)] public IntPtr PointerValue;
        }

        [DllImport("ole32.dll")]
        private static extern int PropVariantClear(ref LexDeskPropVariant value);

        private static readonly Guid LexDeskAudioEndpointVolumeIid =
            new("5CDF2C82-841E-4546-9722-0CF74078229A");

        private static readonly LexDeskPropertyKey LexDeskDeviceFriendlyNameKey = new()
        {
            FormatId = new Guid("A45C254E-DF1C-4EFD-8020-67D146A850E0"),
            PropertyId = 14
        };

        private static void ReleaseLexDeskComObject(object? value)
        {
            try
            {
                if (value != null && Marshal.IsComObject(value))
                    Marshal.ReleaseComObject(value);
            }
            catch { }
        }

        private bool TryGetLexDeskDefaultAudioOutput(
            out string friendlyName,
            out int volumePercent,
            out bool muted)
        {
            friendlyName = "";
            volumePercent = -1;
            muted = false;

            ILexDeskMmDeviceEnumerator? enumerator = null;
            ILexDeskMmDevice? device = null;
            ILexDeskPropertyStore? propertyStore = null;
            ILexDeskAudioEndpointVolume? endpointVolume = null;
            object? activated = null;

            try
            {
                enumerator =
                    (ILexDeskMmDeviceEnumerator)new LexDeskMmDeviceEnumeratorComObject();

                int hr = enumerator.GetDefaultAudioEndpoint(
                    LexDeskAudioDataFlow.Render,
                    LexDeskAudioRole.Multimedia,
                    out device);

                if (hr != 0 || device == null)
                    return false;

                try
                {
                    if (device.OpenPropertyStore(0, out propertyStore) == 0 && propertyStore != null)
                    {
                        LexDeskPropertyKey key = LexDeskDeviceFriendlyNameKey;

                        if (propertyStore.GetValue(ref key, out LexDeskPropVariant value) == 0)
                        {
                            try
                            {
                                // VT_LPWSTR = 31
                                if (value.VariantType == 31 && value.PointerValue != IntPtr.Zero)
                                    friendlyName = Marshal.PtrToStringUni(value.PointerValue) ?? "";
                            }
                            finally
                            {
                                _ = PropVariantClear(ref value);
                            }
                        }
                    }
                }
                catch { }

                Guid iid = LexDeskAudioEndpointVolumeIid;
                hr = device.Activate(ref iid, 0x17, IntPtr.Zero, out activated); // CLSCTX_ALL

                if (hr != 0 || activated is not ILexDeskAudioEndpointVolume volume)
                    return false;

                endpointVolume = volume;

                if (endpointVolume.GetMasterVolumeLevelScalar(out float scalar) == 0)
                {
                    volumePercent =
                        (int)Math.Round(Math.Clamp(scalar, 0f, 1f) * 100.0);
                }

                if (endpointVolume.GetMute(out bool currentMute) == 0)
                    muted = currentMute;

                return true;
            }
            catch
            {
                return false;
            }
            finally
            {
                ReleaseLexDeskComObject(endpointVolume);
                ReleaseLexDeskComObject(propertyStore);
                ReleaseLexDeskComObject(device);
                ReleaseLexDeskComObject(enumerator);
            }
        }

        private bool TrySetLexDeskDefaultAudioOutput(bool? mute, int? volumePercent)
        {
            ILexDeskMmDeviceEnumerator? enumerator = null;
            ILexDeskMmDevice? device = null;
            ILexDeskAudioEndpointVolume? endpointVolume = null;
            object? activated = null;

            try
            {
                enumerator =
                    (ILexDeskMmDeviceEnumerator)new LexDeskMmDeviceEnumeratorComObject();

                int hr = enumerator.GetDefaultAudioEndpoint(
                    LexDeskAudioDataFlow.Render,
                    LexDeskAudioRole.Multimedia,
                    out device);

                if (hr != 0 || device == null)
                    return false;

                Guid iid = LexDeskAudioEndpointVolumeIid;
                hr = device.Activate(ref iid, 0x17, IntPtr.Zero, out activated);

                if (hr != 0 || activated is not ILexDeskAudioEndpointVolume volume)
                    return false;

                endpointVolume = volume;
                Guid context = Guid.Empty;

                if (volumePercent.HasValue)
                {
                    float scalar = Math.Clamp(volumePercent.Value / 100f, 0f, 1f);

                    if (endpointVolume.SetMasterVolumeLevelScalar(scalar, ref context) != 0)
                        return false;
                }

                if (mute.HasValue)
                {
                    if (endpointVolume.SetMute(mute.Value, ref context) != 0)
                        return false;
                }

                return true;
            }
            catch
            {
                return false;
            }
            finally
            {
                ReleaseLexDeskComObject(endpointVolume);
                ReleaseLexDeskComObject(device);
                ReleaseLexDeskComObject(enumerator);
            }
        }

        private LexDeskSoundCheck GatherLexDeskSoundCheck()
        {
            string audioState = GetWmiServiceState("Audiosrv");
            string endpointState = GetWmiServiceState("AudioEndpointBuilder");

            var names = new List<string>();

            try
            {
                using var searcher = new ManagementObjectSearcher(
                    "SELECT Name, Status FROM Win32_SoundDevice");

                foreach (ManagementBaseObject item in searcher.Get())
                {
                    string name = item["Name"]?.ToString() ?? "";

                    if (!string.IsNullOrWhiteSpace(name))
                        names.Add(name.Trim());
                }
            }
            catch { }

            bool defaultOutputAvailable =
                TryGetLexDeskDefaultAudioOutput(
                    out string defaultOutputName,
                    out int volumePercent,
                    out bool muted);

            return new LexDeskSoundCheck
            {
                WindowsAudioRunning =
                    string.Equals(audioState, "Running", StringComparison.OrdinalIgnoreCase),
                EndpointBuilderRunning =
                    string.Equals(endpointState, "Running", StringComparison.OrdinalIgnoreCase),
                SoundDeviceCount = names.Count,
                DeviceNames = string.Join(", ", names.Take(3)),
                DefaultOutputAvailable = defaultOutputAvailable,
                DefaultOutputName = defaultOutputName,
                VolumePercent = volumePercent,
                IsMuted = muted
            };
        }

        private LexDeskPrinterCheck GatherLexDeskPrinterCheck()
        {
            bool spoolerRunning =
                string.Equals(
                    GetWmiServiceState("Spooler"),
                    "Running",
                    StringComparison.OrdinalIgnoreCase);

            int printerCount = 0;
            int offlineCount = 0;
            string defaultPrinter = "";

            try
            {
                using var searcher = new ManagementObjectSearcher(
                    "SELECT Name, Default, WorkOffline FROM Win32_Printer");

                foreach (ManagementBaseObject item in searcher.Get())
                {
                    printerCount++;

                    bool isDefault = false;
                    bool workOffline = false;

                    try
                    {
                        if (item["Default"] != null)
                            isDefault = Convert.ToBoolean(item["Default"]);
                    }
                    catch { }

                    try
                    {
                        if (item["WorkOffline"] != null)
                            workOffline = Convert.ToBoolean(item["WorkOffline"]);
                    }
                    catch { }

                    if (workOffline)
                        offlineCount++;

                    if (isDefault)
                        defaultPrinter = item["Name"]?.ToString() ?? "";
                }
            }
            catch { }

            int queueJobs = 0;

            try
            {
                using var jobs = new ManagementObjectSearcher(
                    "SELECT Name FROM Win32_PrintJob");

                foreach (ManagementBaseObject _ in jobs.Get())
                    queueJobs++;
            }
            catch { }

            return new LexDeskPrinterCheck
            {
                SpoolerRunning = spoolerRunning,
                PrinterCount = printerCount,
                OfflinePrinterCount = offlineCount,
                QueueJobCount = queueJobs,
                DefaultPrinter = defaultPrinter
            };
        }

        private async Task RunLexDeskProblemCheckAsync(LexDeskProblemKind problem)
        {
            if (_lexDeskProblemBusy)
                return;

            _lexDeskActiveProblem = problem;
            _lexDeskProblemSafeFixAvailable = false;
            _lexDeskProblemSettingsTarget = "";
            _lexDeskSoundSafeFixKind = LexDeskSoundSafeFixKind.None;
            ClearLexDeskProblemDetails();
            SetLexDeskProblemSolverBusy(true);

            try
            {
                switch (problem)
                {
                    case LexDeskProblemKind.SlowPc:
                        {
                            SetLexDeskProblemSolverStatus(
                                "LexDesk is taking a short processor average, then checking memory, storage, startup apps and restart status...",
                                null,
                                "Checking why the PC feels slow");

                            LexDeskSlowPcCheck result =
                                await Task.Run(GatherLexDeskSlowPcCheck);

                            double memoryUsedPercent =
                                result.TotalMemoryBytes > 0
                                    ? (result.TotalMemoryBytes - result.FreeMemoryBytes) * 100.0 / result.TotalMemoryBytes
                                    : -1;

                            double diskFreePercent =
                                result.DriveTotalBytes > 0
                                    ? result.DriveFreeBytes * 100.0 / result.DriveTotalBytes
                                    : -1;

                            int attentionCount = 0;
                            int criticalCount = 0;

                            LexDeskProblemDetailTone CpuTone()
                            {
                                if (result.CpuPercent < 0) return LexDeskProblemDetailTone.Normal;
                                if (result.CpuPercent >= 90) { criticalCount++; return LexDeskProblemDetailTone.Critical; }
                                if (result.CpuPercent >= 70) { attentionCount++; return LexDeskProblemDetailTone.Attention; }
                                return LexDeskProblemDetailTone.Good;
                            }

                            LexDeskProblemDetailTone MemoryTone()
                            {
                                if (memoryUsedPercent < 0) return LexDeskProblemDetailTone.Normal;
                                if (memoryUsedPercent >= 92) { criticalCount++; return LexDeskProblemDetailTone.Critical; }
                                if (memoryUsedPercent >= 82) { attentionCount++; return LexDeskProblemDetailTone.Attention; }
                                return LexDeskProblemDetailTone.Good;
                            }

                            LexDeskProblemDetailTone DiskTone()
                            {
                                if (diskFreePercent < 0) return LexDeskProblemDetailTone.Normal;

                                double freeGb = result.DriveFreeBytes / 1024d / 1024d / 1024d;

                                if (diskFreePercent < 8 || freeGb < 10)
                                {
                                    criticalCount++;
                                    return LexDeskProblemDetailTone.Critical;
                                }

                                if (diskFreePercent < 15 || freeGb < 25)
                                {
                                    attentionCount++;
                                    return LexDeskProblemDetailTone.Attention;
                                }

                                return LexDeskProblemDetailTone.Good;
                            }

                            if (result.CpuPercent >= 0)
                            {
                                AddLexDeskProblemDetail(
                                    $"Processor use (short average): {result.CpuPercent}%.",
                                    CpuTone());
                            }

                            if (result.TotalMemoryBytes > 0)
                            {
                                AddLexDeskProblemDetail(
                                    $"Memory in use: {memoryUsedPercent:0}%  •  " +
                                    $"{FormatLexDeskBytes((long)result.FreeMemoryBytes)} available of " +
                                    $"{FormatLexDeskBytes((long)result.TotalMemoryBytes)}.",
                                    MemoryTone());
                            }

                            if (result.DriveTotalBytes > 0)
                            {
                                AddLexDeskProblemDetail(
                                    $"Windows drive free space: {FormatLexDeskBytes(result.DriveFreeBytes)} " +
                                    $"of {FormatLexDeskBytes(result.DriveTotalBytes)} ({diskFreePercent:0}% free).",
                                    DiskTone());
                            }

                            bool startupWorthReviewing =
                                result.StartupItems.Any(x => x.WorthReviewing);

                            if (startupWorthReviewing)
                                attentionCount++;

                            AddLexDeskProblemDetail(
                                result.StartupItemCount == 1
                                    ? "Enabled startup apps: 1."
                                    : $"Enabled startup apps: {result.StartupItemCount}.",
                                startupWorthReviewing
                                    ? LexDeskProblemDetailTone.Attention
                                    : LexDeskProblemDetailTone.Good);

                            if (result.RestartPending)
                            {
                                attentionCount++;
                                AddLexDeskProblemDetail(
                                    "Windows has a genuine update/servicing restart waiting.",
                                    LexDeskProblemDetailTone.Attention);
                            }
                            else
                            {
                                AddLexDeskProblemDetail(
                                    "Windows is not waiting for a maintenance restart.",
                                    LexDeskProblemDetailTone.Good);
                            }

                            if (result.StartupItems.Count > 0)
                            {
                                AddLexDeskProblemDetail(
                                    "Enabled startup adviser — LexDesk will not disable anything:",
                                    LexDeskProblemDetailTone.Normal,
                                    true);

                                var adviserItems = result.StartupItems
                                    .OrderByDescending(x => x.WorthReviewing)
                                    .ThenByDescending(x => x.RecommendedKeep)
                                    .ThenBy(x => x.Name, StringComparer.OrdinalIgnoreCase)
                                    .Take(8)
                                    .ToList();

                                foreach (LexDeskStartupAdviceItem item in adviserItems)
                                {
                                    LexDeskProblemDetailTone tone =
                                        item.WorthReviewing
                                            ? LexDeskProblemDetailTone.Attention
                                            : item.RecommendedKeep
                                                ? LexDeskProblemDetailTone.Good
                                                : LexDeskProblemDetailTone.Normal;

                                    AddLexDeskProblemDetail(
                                        $"{item.Name} — {item.Advice}. {item.Reason}",
                                        tone);
                                }

                                if (result.StartupItems.Count > adviserItems.Count)
                                {
                                    AddLexDeskProblemDetail(
                                        $"And {result.StartupItems.Count - adviserItems.Count} more. " +
                                        "Open Startup Apps to review the full Windows list.",
                                        LexDeskProblemDetailTone.Normal);
                                }
                            }

                            bool needsAttention = attentionCount > 0 || criticalCount > 0;

                            string summary;
                            string title;

                            if (criticalCount > 0)
                            {
                                title = "LexDesk found something that needs attention";
                                summary =
                                    "One of the main speed checks is under heavy pressure. " +
                                    "Start with the orange/red items below. LexDesk will not disable programs by itself.";
                            }
                            else if (needsAttention)
                            {
                                title = attentionCount == 1
                                    ? "One thing is worth reviewing"
                                    : "A few things are worth reviewing";
                                summary =
                                    "The PC is generally working, but the orange item(s) below are worth checking. " +
                                    "Startup Apps and temporary files are safe places to begin.";
                            }
                            else
                            {
                                title = "The basic speed checks look healthy";
                                summary =
                                    "Processor, memory, storage and restart checks look reasonable right now. " +
                                    "If the PC still feels slow, open Startup Apps and review programs you recognise.";
                            }

                            SetLexDeskProblemSolverStatus(summary, needsAttention, title);

                            ConfigureLexDeskProblemActions(
                                "Check Temp Files",
                                true,
                                "Startup Apps",
                                "ms-settings:startupapps");

                            break;
                        }

                    case LexDeskProblemKind.Internet:
                        {
                            SetLexDeskProblemSolverStatus(
                                "Checking the Windows network connection, gateway, name lookup and a normal secure website connection...",
                                null,
                                "Checking the internet connection");

                            LexDeskInternetCheck result =
                                await GatherLexDeskInternetCheckAsync();

                            var lines = new List<string>();

                            if (!result.NetworkAvailable)
                            {
                                lines.Add("Windows does not currently see an active network connection.");
                                lines.Add("Check Wi-Fi, Ethernet cable, modem/router power, or Airplane mode first.");

                                SetLexDeskProblemSolverStatus(
                                    string.Join("\n", lines),
                                    true,
                                    "Windows cannot see a network connection");

                                ConfigureLexDeskProblemActions(
                                    "Flush DNS",
                                    false,
                                    "Network Settings",
                                    "ms-settings:network-status");

                                break;
                            }

                            lines.Add(
                                string.IsNullOrWhiteSpace(result.AdapterName)
                                    ? "Windows sees an active network connection."
                                    : $"Active connection: {result.AdapterName}.");

                            if (!string.IsNullOrWhiteSpace(result.Gateway))
                                lines.Add($"Router/gateway found: {result.Gateway}.");

                            lines.Add(
                                result.DnsWorked
                                    ? "Website-name lookup is working."
                                    : "Website-name lookup is not working correctly.");

                            lines.Add(
                                result.HttpsWorked
                                    ? "A normal secure web connection is working."
                                    : "LexDesk could not confirm a normal secure web connection.");

                            bool needsAttention = !result.DnsWorked || !result.HttpsWorked;

                            if (!result.DnsWorked)
                            {
                                lines.Add("");
                                lines.Add(
                                    "A safe first repair is to clear Windows' saved DNS lookups. " +
                                    "This does not remove Wi-Fi passwords or reset the whole network.");
                            }
                            else if (!result.HttpsWorked)
                            {
                                lines.Add("");
                                lines.Add(
                                    "The PC is connected and DNS works, so the problem may be the router, ISP, VPN, security software, or the website itself.");
                            }
                            else
                            {
                                lines.Add("");
                                lines.Add(
                                    "Windows networking looks healthy at the moment. " +
                                    "If one website is failing, the problem may be limited to that site.");
                            }

                            SetLexDeskProblemSolverStatus(
                                string.Join("\n", lines),
                                needsAttention,
                                needsAttention ? "LexDesk found where the connection is failing" : "The internet checks look OK");

                            ConfigureLexDeskProblemActions(
                                "Flush DNS",
                                !result.DnsWorked,
                                "Network Settings",
                                "ms-settings:network-status");

                            break;
                        }

                    case LexDeskProblemKind.Sound:
                        {
                            SetLexDeskProblemSolverStatus(
                                "Checking Windows Audio, sound hardware, the selected output, volume and mute...",
                                null,
                                "Checking Windows sound");

                            LexDeskSoundCheck result =
                                await Task.Run(GatherLexDeskSoundCheck);

                            bool servicesNeedStart =
                                !result.WindowsAudioRunning ||
                                !result.EndpointBuilderRunning;

                            bool noHardware = result.SoundDeviceCount == 0;
                            bool noDefaultOutput =
                                !servicesNeedStart &&
                                result.SoundDeviceCount > 0 &&
                                !result.DefaultOutputAvailable;

                            bool veryLowVolume =
                                result.DefaultOutputAvailable &&
                                result.VolumePercent >= 0 &&
                                result.VolumePercent <= 2;

                            bool lowVolume =
                                result.DefaultOutputAvailable &&
                                result.VolumePercent > 2 &&
                                result.VolumePercent < 10;

                            AddLexDeskProblemDetail(
                                result.WindowsAudioRunning
                                    ? "Windows Audio service is running."
                                    : "Windows Audio service is not running.",
                                result.WindowsAudioRunning
                                    ? LexDeskProblemDetailTone.Good
                                    : LexDeskProblemDetailTone.Critical);

                            AddLexDeskProblemDetail(
                                result.EndpointBuilderRunning
                                    ? "Windows Audio Endpoint service is running."
                                    : "Windows Audio Endpoint service is not running.",
                                result.EndpointBuilderRunning
                                    ? LexDeskProblemDetailTone.Good
                                    : LexDeskProblemDetailTone.Critical);

                            if (result.SoundDeviceCount > 0)
                            {
                                AddLexDeskProblemDetail(
                                    $"Windows can see {result.SoundDeviceCount} sound device" +
                                    (result.SoundDeviceCount == 1 ? "." : "s."),
                                    LexDeskProblemDetailTone.Good);

                                if (!string.IsNullOrWhiteSpace(result.DeviceNames))
                                {
                                    AddLexDeskProblemDetail(
                                        $"Detected hardware: {result.DeviceNames}.",
                                        LexDeskProblemDetailTone.Normal);
                                }
                            }
                            else
                            {
                                AddLexDeskProblemDetail(
                                    "Windows is not reporting a sound device.",
                                    LexDeskProblemDetailTone.Critical);
                            }

                            if (result.DefaultOutputAvailable)
                            {
                                AddLexDeskProblemDetail(
                                    string.IsNullOrWhiteSpace(result.DefaultOutputName)
                                        ? "Windows has a default sound output selected."
                                        : $"Selected output: {result.DefaultOutputName}.",
                                    LexDeskProblemDetailTone.Good);

                                if (result.VolumePercent >= 0)
                                {
                                    AddLexDeskProblemDetail(
                                        $"Master volume: {result.VolumePercent}%.",
                                        veryLowVolume
                                            ? LexDeskProblemDetailTone.Critical
                                            : lowVolume
                                                ? LexDeskProblemDetailTone.Attention
                                                : LexDeskProblemDetailTone.Good);
                                }

                                AddLexDeskProblemDetail(
                                    result.IsMuted
                                        ? "Sound is muted."
                                        : "Sound is not muted.",
                                    result.IsMuted
                                        ? LexDeskProblemDetailTone.Attention
                                        : LexDeskProblemDetailTone.Good);
                            }
                            else if (!servicesNeedStart && result.SoundDeviceCount > 0)
                            {
                                AddLexDeskProblemDetail(
                                    "Windows has sound hardware, but LexDesk could not read a default playback output.",
                                    LexDeskProblemDetailTone.Attention);
                            }

                            bool needsAttention =
                                servicesNeedStart ||
                                noHardware ||
                                noDefaultOutput ||
                                result.IsMuted ||
                                veryLowVolume ||
                                lowVolume;

                            string safeFixText = "Start Audio";
                            bool safeFixAvailable = false;
                            _lexDeskSoundSafeFixKind = LexDeskSoundSafeFixKind.None;

                            if (servicesNeedStart)
                            {
                                _lexDeskSoundSafeFixKind = LexDeskSoundSafeFixKind.StartServices;
                                safeFixText = "Start Audio";
                                safeFixAvailable = true;
                            }
                            else if (result.DefaultOutputAvailable && result.IsMuted)
                            {
                                _lexDeskSoundSafeFixKind = LexDeskSoundSafeFixKind.Unmute;
                                safeFixText = "Turn Sound On";
                                safeFixAvailable = true;
                            }
                            else if (veryLowVolume)
                            {
                                _lexDeskSoundSafeFixKind = LexDeskSoundSafeFixKind.RaiseVolume;
                                safeFixText = "Set Volume to 25%";
                                safeFixAvailable = true;
                            }

                            string summary;
                            string title;

                            if (servicesNeedStart)
                            {
                                title = "Windows Audio needs to be started";
                                summary =
                                    "LexDesk can ask Windows to start its normal audio services. " +
                                    "This does not remove devices or drivers.";
                            }
                            else if (noHardware)
                            {
                                title = "Windows cannot see a sound device";
                                summary =
                                    "Check the speaker/headset connection, Bluetooth connection or audio driver in Sound Settings.";
                            }
                            else if (result.IsMuted)
                            {
                                title = "The sound is muted";
                                summary = "LexDesk can safely unmute the selected Windows output.";
                            }
                            else if (veryLowVolume)
                            {
                                title = "The volume is effectively off";
                                summary = "LexDesk can set the master volume to a gentle 25%.";
                            }
                            else if (lowVolume)
                            {
                                title = "The volume is very low";
                                summary = "The sound system looks healthy, but the current volume may be too low to hear.";
                            }
                            else if (noDefaultOutput)
                            {
                                title = "Check the selected sound output";
                                summary = "Windows sees audio hardware, but the active playback output needs checking in Sound Settings.";
                            }
                            else
                            {
                                title = "The sound checks look healthy";
                                summary =
                                    "Windows Audio, the selected output, volume and mute state all look reasonable. " +
                                    "If sound is still missing, check the app's own volume and the speaker/headset itself.";
                            }

                            SetLexDeskProblemSolverStatus(summary, needsAttention, title);

                            ConfigureLexDeskProblemActions(
                                safeFixText,
                                safeFixAvailable,
                                "Sound Settings",
                                "ms-settings:sound");

                            break;
                        }

                    case LexDeskProblemKind.Printer:
                        {
                            SetLexDeskProblemSolverStatus(
                                "Checking the Windows print service, installed printers, offline state and print queue...",
                                null,
                                "Checking Windows printing");

                            LexDeskPrinterCheck result =
                                await Task.Run(GatherLexDeskPrinterCheck);

                            var lines = new List<string>
                        {
                            result.SpoolerRunning
                                ? "Windows Print Spooler is running."
                                : "Windows Print Spooler is not running.",
                            $"Printers installed in Windows: {result.PrinterCount}."
                        };

                            if (!string.IsNullOrWhiteSpace(result.DefaultPrinter))
                                lines.Add($"Default printer: {result.DefaultPrinter}.");

                            if (result.OfflinePrinterCount > 0)
                            {
                                lines.Add(
                                    $"{result.OfflinePrinterCount} printer" +
                                    (result.OfflinePrinterCount == 1 ? " is" : "s are") +
                                    " marked offline.");
                            }

                            if (result.QueueJobCount > 0)
                            {
                                lines.Add(
                                    $"Print jobs waiting: {result.QueueJobCount}.");
                            }
                            else
                            {
                                lines.Add("No print jobs are currently waiting.");
                            }

                            bool needsAttention =
                                !result.SpoolerRunning ||
                                result.PrinterCount == 0 ||
                                result.OfflinePrinterCount > 0;

                            if (!result.SpoolerRunning)
                            {
                                lines.Add("");
                                lines.Add(
                                    "LexDesk can restart the Windows print service. " +
                                    "It will not delete the print queue.");
                            }
                            else if (result.PrinterCount == 0)
                            {
                                lines.Add("");
                                lines.Add(
                                    "Windows does not currently have a printer installed. " +
                                    "Open Printers & scanners to add or reconnect one.");
                            }
                            else
                            {
                                lines.Add("");
                                lines.Add(
                                    "If printing is still stuck, restarting the Windows print service is a safe first step. " +
                                    "LexDesk will not clear your queued jobs.");
                            }

                            SetLexDeskProblemSolverStatus(
                                string.Join("\n", lines),
                                needsAttention,
                                needsAttention ? "LexDesk found a printing problem to check" : "The basic printer checks look OK");

                            ConfigureLexDeskProblemActions(
                                "Restart Print Service",
                                result.PrinterCount > 0,
                                "Printers & Scanners",
                                "ms-settings:printers");

                            break;
                        }
                }
            }
            catch (Exception ex)
            {
                SetLexDeskProblemSolverStatus(
                    "LexDesk could not finish this check.\n\n" +
                    SanitizeExceptionMessage(ex),
                    true,
                    "The check could not finish");
            }
            finally
            {
                SetLexDeskProblemSolverBusy(false);
            }
        }

