        private async void LexDeskProblemSafeFix_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;

            if (_lexDeskProblemBusy || !_lexDeskProblemSafeFixAvailable)
                return;

            switch (_lexDeskActiveProblem)
            {
                case LexDeskProblemKind.SlowPc:
                    {
                        SetLexDeskProblemSolverStatus(
                            "LexDesk is opening the safe temporary-file check above. " +
                            "Nothing is deleted until you review the result and choose cleanup.",
                            null,
                            "Checking safe temporary files");

                        LexDeskCheckTemporaryFiles_Click(
                            sender,
                            new RoutedEventArgs(
                                Button.ClickEvent,
                                sender));
                        break;
                    }

                case LexDeskProblemKind.Internet:
                    {
                        var decision = ShowLexDeskMessageBox(
                            "LexDesk can clear Windows' saved DNS lookups.\n\n" +
                            "This is a small network repair. It does not forget Wi-Fi passwords, " +
                            "change your router, or reset the whole network.\n\n" +
                            "Windows may ask for Administrator permission. Continue?",
                            "Flush DNS",
                            MessageBoxButton.YesNo,
                            MessageBoxImage.Information);

                        if (decision != MessageBoxResult.Yes)
                            return;

                        SetLexDeskProblemSolverBusy(true);
                        SetLexDeskProblemSolverStatus(
                            "Clearing Windows' saved DNS lookups...",
                            null,
                            "Running the safe network fix");

                        try
                        {
                            string ipconfig =
                                Path.Combine(Environment.SystemDirectory, "ipconfig.exe");

                            var commands = new List<LexDeskMaintenanceCommand>
                        {
                            new()
                            {
                                Key = "FLUSHDNS",
                                StatusText = "Clearing saved DNS lookups...",
                                FileName = ipconfig,
                                Arguments = "/flushdns",
                                StopOnFailure = true
                            }
                        };

                            LexDeskMaintenanceBatchResult result =
                                await RunElevatedMaintenanceBatchAsync(
                                    "network_flushdns",
                                    commands);

                            if (result.Cancelled)
                            {
                                SetLexDeskProblemSolverStatus(
                                    "Administrator permission was cancelled. Nothing was changed.",
                                    null,
                                    "DNS was not changed");
                                return;
                            }

                            int exitCode = -1;
                            bool gotExit =
                                TryGetLexDeskMaintenanceExitCode(
                                    result.Output,
                                    "FLUSHDNS",
                                    out exitCode);

                            if (result.Started &&
                                gotExit &&
                                IsLexDeskMaintenanceSuccessExit(exitCode))
                            {
                                SetLexDeskProblemSolverStatus(
                                    "Windows' saved DNS lookups were cleared. Try the internet again, then use Check Again if needed.",
                                    false,
                                    "Safe network fix finished");

                                _lexDeskProblemSafeFixAvailable = false;
                            }
                            else
                            {
                                SetLexDeskProblemSolverStatus(
                                    "Windows could not clear the DNS cache. Open Network Settings and check the connection.",
                                    true,
                                    "The DNS fix did not finish");
                            }
                        }
                        finally
                        {
                            SetLexDeskProblemSolverBusy(false);
                        }

                        break;
                    }

                case LexDeskProblemKind.Sound:
                    {
                        if (_lexDeskSoundSafeFixKind == LexDeskSoundSafeFixKind.None)
                            return;

                        if (_lexDeskSoundSafeFixKind == LexDeskSoundSafeFixKind.Unmute)
                        {
                            var decision = ShowLexDeskMessageBox(
                                "LexDesk can turn mute off for the selected Windows sound output.\n\n" +
                                "This does not change drivers or remove devices. Continue?",
                                "Turn Sound On",
                                MessageBoxButton.YesNo,
                                MessageBoxImage.Information);

                            if (decision != MessageBoxResult.Yes)
                                return;

                            SetLexDeskProblemSolverBusy(true);

                            try
                            {
                                bool changed = await Task.Run(() =>
                                    TrySetLexDeskDefaultAudioOutput(false, null));

                                SetLexDeskProblemSolverStatus(
                                    changed
                                        ? "Mute has been turned off. LexDesk will check the sound again."
                                        : "LexDesk could not change the mute setting. Open Sound Settings to check the selected output.",
                                    changed ? false : true,
                                    changed ? "Sound turned on" : "Mute could not be changed");
                            }
                            finally
                            {
                                SetLexDeskProblemSolverBusy(false);
                            }

                            await RunLexDeskProblemCheckAsync(LexDeskProblemKind.Sound);
                            break;
                        }

                        if (_lexDeskSoundSafeFixKind == LexDeskSoundSafeFixKind.RaiseVolume)
                        {
                            var decision = ShowLexDeskMessageBox(
                                "The selected Windows output is at almost zero volume.\n\n" +
                                "LexDesk can set it to 25%, which is a gentle starting level. Continue?",
                                "Set Volume to 25%",
                                MessageBoxButton.YesNo,
                                MessageBoxImage.Information);

                            if (decision != MessageBoxResult.Yes)
                                return;

                            SetLexDeskProblemSolverBusy(true);

                            try
                            {
                                bool changed = await Task.Run(() =>
                                    TrySetLexDeskDefaultAudioOutput(false, 25));

                                SetLexDeskProblemSolverStatus(
                                    changed
                                        ? "Windows master volume was set to 25% and mute was turned off. LexDesk will check again."
                                        : "LexDesk could not change the volume. Open Sound Settings to adjust the selected output.",
                                    changed ? false : true,
                                    changed ? "Volume adjusted safely" : "Volume could not be changed");
                            }
                            finally
                            {
                                SetLexDeskProblemSolverBusy(false);
                            }

                            await RunLexDeskProblemCheckAsync(LexDeskProblemKind.Sound);
                            break;
                        }

                        var startDecision = ShowLexDeskMessageBox(
                            "LexDesk can ask Windows to start its normal audio services.\n\n" +
                            "This does not remove audio devices, drivers or settings. " +
                            "Windows may ask for Administrator permission.\n\nContinue?",
                            "Start Windows Audio",
                            MessageBoxButton.YesNo,
                            MessageBoxImage.Information);

                        if (startDecision != MessageBoxResult.Yes)
                            return;

                        SetLexDeskProblemSolverBusy(true);
                        SetLexDeskProblemSolverStatus(
                            "Starting the Windows audio services...",
                            null,
                            "Running the safe sound fix");

                        try
                        {
                            string sc = Path.Combine(Environment.SystemDirectory, "sc.exe");

                            var commands = new List<LexDeskMaintenanceCommand>
                        {
                            new()
                            {
                                Key = "AUDIOENDPOINT",
                                StatusText = "Starting the Windows audio endpoint service...",
                                FileName = sc,
                                Arguments = "start AudioEndpointBuilder",
                                StopOnFailure = false
                            },
                            new()
                            {
                                Key = "AUDIOSRV",
                                StatusText = "Starting Windows Audio...",
                                FileName = sc,
                                Arguments = "start Audiosrv",
                                StopOnFailure = false
                            }
                        };

                            LexDeskMaintenanceBatchResult result =
                                await RunElevatedMaintenanceBatchAsync(
                                    "audio_start",
                                    commands);

                            if (result.Cancelled)
                            {
                                SetLexDeskProblemSolverStatus(
                                    "Administrator permission was cancelled. Nothing was changed.",
                                    null,
                                    "Audio was not changed");
                                return;
                            }
                        }
                        finally
                        {
                            SetLexDeskProblemSolverBusy(false);
                        }

                        await Task.Delay(800);
                        await RunLexDeskProblemCheckAsync(LexDeskProblemKind.Sound);
                        break;
                    }

                case LexDeskProblemKind.Printer:
                    {
                        var decision = ShowLexDeskMessageBox(
                            "LexDesk can restart the normal Windows print service.\n\n" +
                            "This does NOT delete your queued print jobs or remove printers. " +
                            "Printing may pause for a few seconds.\n\n" +
                            "Windows may ask for Administrator permission. Continue?",
                            "Restart Print Service",
                            MessageBoxButton.YesNo,
                            MessageBoxImage.Information);

                        if (decision != MessageBoxResult.Yes)
                            return;

                        SetLexDeskProblemSolverBusy(true);
                        SetLexDeskProblemSolverStatus(
                            "Restarting the Windows print service...",
                            null,
                            "Running the safe printer fix");

                        try
                        {
                            string sc = Path.Combine(Environment.SystemDirectory, "sc.exe");

                            var commands = new List<LexDeskMaintenanceCommand>
                        {
                            new()
                            {
                                Key = "SPOOLERSTOP",
                                StatusText = "Stopping the Windows print service...",
                                FileName = sc,
                                Arguments = "stop Spooler",
                                StopOnFailure = false
                            },
                            new()
                            {
                                Key = "SPOOLERSTART",
                                StatusText = "Starting the Windows print service...",
                                FileName = sc,
                                Arguments = "start Spooler",
                                StopOnFailure = false
                            }
                        };

                            LexDeskMaintenanceBatchResult result =
                                await RunElevatedMaintenanceBatchAsync(
                                    "printer_spooler_restart",
                                    commands);

                            if (result.Cancelled)
                            {
                                SetLexDeskProblemSolverStatus(
                                    "Administrator permission was cancelled. Nothing was changed.",
                                    null,
                                    "Print service was not changed");
                                return;
                            }

                            await Task.Delay(800);
                            LexDeskPrinterCheck check =
                                await Task.Run(GatherLexDeskPrinterCheck);

                            SetLexDeskProblemSolverStatus(
                                check.SpoolerRunning
                                    ? "The Windows print service is running. Try the print job again. LexDesk did not delete your queued jobs."
                                    : "The Windows print service did not start. Open Printers & scanners to check the printer and Windows warning.",
                                check.SpoolerRunning ? false : true,
                                check.SpoolerRunning ? "Print service restarted" : "Print service still needs attention");
                        }
                        finally
                        {
                            SetLexDeskProblemSolverBusy(false);
                        }

                        break;
                    }
            }
        }

        // ============================================
        // Constructor
        // ============================================

        public MainWindow()
        {
            // One-shot elevated managed-window helper.
            // Normal LexDesk remains non-admin.
            if (TryRunElevatedManagedToolHelperFromCommandLine())
            {
                Environment.Exit(0);
                return;
            }

            // One-shot elevated helper. The normal browser process remains non-admin;
            // this short-lived helper only applies or restores Windows DNS after UAC.
            if (TryRunElevatedDnsHelperFromCommandLine())
            {
                Environment.Exit(0);
                return;
            }

            InitializeComponent();

            StartLexDeskManagedWindowFocusTimer();

            Activated += (_, __) =>
            {
                RefreshLexDeskCalendarNotificationStatus();
                RefreshLexDeskClock();

                RestoreLexDeskPage2BrowserIfManagedToolClosed();

                // Managed apps remain visible over their assigned panes when the
                // customer clicks back into LexDesk or another browser pane.
                RefreshLexDeskManagedWindowZOrder();
            };

            Loaded += (_, __) =>
            {
                App.TryDeliverPendingCalendarToast(this);

                StartLexDeskInAppCalendarReminderTimer();
            };

            // LexDesk Pro uses its own clean data folder.
            // Do not migrate another product's customer data into LexDesk Pro.
            // MigrateLegacyAppDataToStableFolder();

            BuildAddressBarContextMenu();

            PreviewKeyDown += MainWindow_PreviewKeyDown;

            SourceInitialized += (_, __) => RegisterLexDeskWindowHotkeys();
            Closed += (_, __) => UnregisterLexDeskWindowHotkeys();

            Closed += (_, __) =>
            {
                try
                {
                    _lexDeskInAppReminderTimer.Stop();
                    _lexDeskManagedWindowFocusTimer.Stop();
                }
                catch
                {
                }
            };

            PrivacyDropdown.Closed += (_, __) =>
            {
                if (SettingsOverlayHost?.Visibility == Visibility.Visible)
                    return;

                if (GuideOverlay?.Visibility == Visibility.Visible)
                    return;

                if (StartupScreenOverlayHost?.Visibility == Visibility.Visible)
                    return;

                if (PagesHost != null)
                    PagesHost.Visibility = Visibility.Visible;
            };

            ApplySafeStartupWindowSize();

            ApplyResponsiveToolbarSize();
            ApplyResponsiveTopBarScale();

            SizeChanged += (_, __) =>
            {
                ApplyResponsiveToolbarSize();
                ApplyResponsiveTopBarScale();
                UpdateDynamicAddressBarWidth();
            };

            EnsureFixedWorkspaceTabs();

            RebuildWorkspaceTabs();
            UpdateWorkspaceTabVisuals();
            ApplyResponsiveTopBarScale();
            UpdateDynamicAddressBarWidth();


            for (int i = 0; i < _studioSlotIndex.Length; i++)
                _studioSlotIndex[i] = -1;

            HomeTopButton.MouseRightButtonUp += (_, __) =>

            {
                try
                {
                    string defaultUrl = _homeUrl;
                    var current = GetActivePaneRealUrl();
                    if (!string.IsNullOrWhiteSpace(current) && (current.StartsWith("http://") || current.StartsWith("https://")))
                        defaultUrl = current;

                    var url = Interaction.InputBox(
                        "Set Home URL (include https://)",
                        "Home URL",
                        defaultUrl ?? "");

                    url = (url ?? "").Trim();
                    if (string.IsNullOrWhiteSpace(url)) return;

                    if (!url.Contains("://") && url.Contains("."))
                        url = "https://" + url;

                    _homeUrl = url;
                    SaveHomeUrl();

                    ShowLexDeskMessageBox("Home URL saved.", "Home", MessageBoxButton.OK, MessageBoxImage.Information);
                }
                catch { }
            };




            // Load the customer's saved appearance before building the browser UI.
            AppTheme startupTheme = LoadAppearanceThemeSetting();
            _themeIndex = (int)startupTheme;
            ApplyTheme(startupTheme);
            UpdateThemesButtonLabel(startupTheme);
            UpdateAppearanceThemeButtons();

            UpdateWorkspaceTabVisuals();

            InitAddressBarTimers();
            UpdateSecurityStatus("Secure", false);

            // LexDesk Pro lower taskbar: clock, battery and tray state.
            InitLexDeskBottomBar();

            // User-owned names for the four LexDesk folder shortcuts.
            // The internal folders stay Social/Personal/Docs/Music so renaming
            // a button can never move or lose the user's files.
            LoadLexDeskBubbleLabels();
            UpdateLexDeskBubbleButtonLabels();

            // default page slots
            _pageUrls[0] = "lexwhite://newtab";
            _pageUrls[1] = "about:blank";
            _pageUrls[2] = "about:blank";
            _pageUrls[3] = "about:blank";

            Loaded += async (_, __) =>
            {
                try
                {
                    // ============================================
                    // LIGHTWEIGHT SETTINGS LOAD (fast file reads only)
                    // ============================================

                    // --- Core data (must load first)
                    LoadPresetUrls();
                    LoadStartupScreenSetting();
                    LoadToolbarPreferences();
                    LoadSitePermissionSettings();
                    LoadMemorySaverSettings();
                    LoadSiteZoomSettings();
                    InitializeMemorySaver();

                    LoadHomeUrl();
                    LoadWhitelist();
                    LoadManualBlockedSites();
                    LoadPrivacyMode();
                    LoadDnsPreset();
                    LoadSearchEngine();
                    LoadSearchRegion();
                    LoadDnsMode();
                    LoadPopupMode();
                    LoadPopupWhitelist();
                    LoadTrustedDownloadHosts();
                    LoadCompatibilityHosts();
                    LoadPrivacyRelayLocation();
                    LoadPrivacyRelayStartupAwareness();
                    RefreshPrivacyNetworkVisuals();

                    // Keep activation across updates/reinstalls.
                    // Users can remove activation manually with Clear Saved License.
                    LoadLicenseState();

                    LoadAutoStartSetting();
                    ApplyAutoStartSetting();

                    LoadCleanSearchSetting();
                    LoadProtectionWarningStyle();

                    // Restore the customer's LexDesk taskbar pins.
                    _ = LoadLexDeskPinnedAppsDockAsync();

                    if (!HasFullUnlock())
                    {
                        _privacyMode = PrivacyMode.Balanced;
                        SavePrivacyMode();

                        // Free/default startup stays in Normal Internet Protection.
                        // LexDesk Pro must not silently change Windows DNS.
                        _dnsMode = DnsApplyMode.SystemWindows;
                        _dnsPreset = DnsPreset.Cloudflare;
                        SaveDnsMode();
                        SaveDnsPreset();
                    }


                    // --- Session
                    // Session restore remains disabled while workspace tabs control pane state.
                    // Old session restore can reload stale URLs into panes.

                    // Tab 1 maps to Quick URLs 1–4.
                    // Do this after session restore so old saved session URLs do not override it.
                    LoadQuickUrlBlockIntoWorkspace(0, force: true);
                    Array.Copy(_workspaces[0].PageUrls, _pageUrls, 4);
                    _activeWorkspaceTabIndex = 0;
                    _activePageIndex = 0;
                    _layoutPageCount = 1;

                    if (_startupScreenEnabled)
                    {
                        _pageUrls[0] = "lexwhite://newtab";
                    }
                    else
                    {
                        string quickUrl1 = NormalizeWorkspaceUrl(_presetUrls.Length > 0 ? _presetUrls[0] : "");

                        if (!string.IsNullOrWhiteSpace(quickUrl1))
                            _pageUrls[0] = quickUrl1;
                    }

                    // --- UI construction (depends on data)
                    BuildPresetButtonMenus();
                    RefreshPresetButtonsUI();

                    // --- UI updates
                    UpdateDnsModeUi();
                    UpdateDnsUI();
                    UpdateSearchEngineUI();
                    UpdateSearchRegionUI();
                    UpdateSmartModeUI();
                    UpdatePopupModeUI();
                    UpdateLicenseUi();
                    UpdatePrivacyButtonLabel();
                    UpdatePrivacyDropdownVisuals();
                    RefreshCompatibilityButtonVisual();
                    UpdateAutoStartButtonLabel();
                    UpdateStartupScreenButtonLabel();
                    UpdateCleanSearchButtonLabel();
                    UpdateProtectionWarningStyleButtons();
                    ApplyToolbarPreferences();


                    // --- System-level DNS is deliberately NOT re-applied at startup.
                    // Windows keeps an applied DNS setting itself. Re-applying it here could
                    // unexpectedly overwrite a customer's network setting after a restart.

                    // --- Optional / extras
                    LoadBookmarks();
                    LoadHistory();

                    LoadHomeOverlayImagePath();
                    RefreshHomeOverlayImage1();

                    // --- Layout baseline ---
                    for (int i = 0; i < 4; i++)
                        _paneState[i] = PaneLifeState.Normal;

                    if (_layoutPageCount < 1 || _layoutPageCount > 4)
                        _layoutPageCount = 1;

                    if (_activePageIndex < 0 || _activePageIndex > 3)
                        _activePageIndex = 0;

                    for (int i = _layoutPageCount; i < 4; i++)
                        _paneState[i] = PaneLifeState.Minimized;

                    ApplyLayout();
                    UpdatePageModeButtonVisuals();
                    UpdatePageHostBorders();
                    RefreshHomeOverlay1();

                    // 🚀 SHOW HOME IMMEDIATELY
                    // _activePageIndex = 0;
                    //_studioSlotIndex[_activePageIndex] = 0;
                    //NavigateTo(_homeUrl);
                    //RefreshHomeOverlay1();
                    //UpdateSecureSiteVisual();

                    // --- HEAVIER INIT AFTER FIRST PAINT ---
                    // Warm WebView AFTER first paint, then navigate cleanly
                    await Dispatcher.InvokeAsync(async () =>
                    {
                        await EnsureWebViewAsync();

                        _activePageIndex = 0;
                        _studioSlotIndex[_activePageIndex] = 0;

                        if (_startupScreenEnabled)
                        {
                            _pageUrls[0] = "lexwhite://newtab";
                            RefreshHomeOverlay1();
                        }
                        else
                        {
                            string quickUrl1 = NormalizeWorkspaceUrl(_presetUrls.Length > 0 ? _presetUrls[0] : "");

                            if (!string.IsNullOrWhiteSpace(quickUrl1))
                            {
                                _pageUrls[0] = quickUrl1;
                                NavigateTo(quickUrl1);
                            }
                            else
                            {
                                _pageUrls[0] = "lexwhite://newtab";
                                RefreshHomeOverlay1();
                            }
                        }

                        UpdateSecureSiteVisual();

                        _ = EnsureAdBlockListAsync(); // background
                    }, DispatcherPriority.ApplicationIdle);
                }
                catch (Exception ex)
                {
                    ShowLexDeskMessageBox(
    $"Startup failed:\n\n{SanitizeExceptionMessage(ex)}",
    "Startup Error",
    MessageBoxButton.OK,
    MessageBoxImage.Error);
                }
            };

        }

        // ============================================
        // Window control buttons (Top left capsule)
        // ============================================

        protected override void OnStateChanged(
            EventArgs e)
        {
            base.OnStateChanged(e);

            try
            {
                if (WindowState ==
                    WindowState.Minimized)
                {
                    MinimizeLexDeskManagedWindows();
                }
                else
                {
                    Dispatcher.BeginInvoke(
                        new Action(
                            RestoreLexDeskLastManagedWindow),
                        DispatcherPriority.ApplicationIdle);
                }
            }
            catch
            {
                // Window state changes must never affect LexDesk.
            }
        }

