        private void RequestLexDeskManagedWindowsCloseOnShutdown()
        {
            try
            {
                var closeTargets =
                    new HashSet<IntPtr>();

                IntPtr lexDeskHwnd =
                    new WindowInteropHelper(this).Handle;

                foreach (var pair in
                         _lexDeskManagedWindows.ToList())
                {
                    IntPtr hWnd =
                        pair.Value;

                    if (hWnd == IntPtr.Zero ||
                        hWnd == lexDeskHwnd ||
                        !IsWindow(hWnd))
                    {
                        continue;
                    }

                    string processName =
                        GetLexDeskWindowProcessName(hWnd);

                    string className =
                        GetLexDeskWindowClass(hWnd);

                    // Never send WM_CLOSE to the Windows desktop/taskbar shell.
                    if (processName.Equals(
                            "explorer",
                            StringComparison.OrdinalIgnoreCase) &&
                        (className.Equals(
                             "Shell_TrayWnd",
                             StringComparison.OrdinalIgnoreCase) ||
                         className.Equals(
                             "Progman",
                             StringComparison.OrdinalIgnoreCase) ||
                         className.Equals(
                             "WorkerW",
                             StringComparison.OrdinalIgnoreCase)))
                    {
                        continue;
                    }

                    closeTargets.Add(
                        hWnd);
                }

                foreach (var pair in
                         _lexDeskPriorityOverlayWindows.ToList())
                {
                    IntPtr hWnd =
                        pair.Value;

                    if (hWnd != IntPtr.Zero &&
                        hWnd != lexDeskHwnd &&
                        IsWindow(hWnd))
                    {
                        closeTargets.Add(
                            hWnd);
                    }
                }

                foreach (IntPtr hWnd in closeTargets)
                {
                    WriteLexDeskManagedWindowDebug(
                        $"SHUTDOWN WM_CLOSE | " +
                        $"{DescribeLexDeskManagedWindowForDebug(hWnd)}");

                    PostMessage(
                        hWnd,
                        LexDeskWmClose,
                        IntPtr.Zero,
                        IntPtr.Zero);
                }
            }
            catch
            {
                // LexDesk shutdown must never be blocked by an external app.
            }
        }

        protected override void OnClosed(EventArgs e)
        {
            try
            {
                WriteLexDeskManagedWindowDebug(
                    "============================================================");

                WriteLexDeskManagedWindowDebug(
                    "LEXDESK ONCLOSED BEGIN | requesting graceful close for managed app windows");

                DumpLexDeskManagedSessionState(
                    "LexDesk OnClosed before close requests");

                RequestLexDeskManagedWindowsCloseOnShutdown();

                WriteLexDeskManagedWindowDebug(
                    "LEXDESK ONCLOSED END | WM_CLOSE requests sent");
            }
            catch { }

            try
            {
                FlushPendingHistorySave();
            }
            catch { }

            base.OnClosed(e);
        }

