        private void ApplyResponsiveToolbarSize()
        {
            double width = ActualWidth > 0
                ? ActualWidth
                : SystemParameters.WorkArea.Width;

            // Defaults: normal desktop/laptop size.
            double topBarIconSize = 16;
            double topBarButtonWidth = 28;
            double topBarButtonHeight = 24;
            double topBarCompactButtonWidth = 24;
            double topBarFontSize = 12;
            double topBarGap = 4;
            double addressBarHeight = 26;

            // Compact: 1280–1366 wide screens, like Val's 1366 x 768.
            if (width <= 1366)
            {
                topBarIconSize = 13;
                topBarButtonWidth = 23;
                topBarButtonHeight = 21;
                topBarCompactButtonWidth = 21;
                topBarFontSize = 10.5;
                topBarGap = 2;
                addressBarHeight = 24;
            }
            // Small-normal: slightly wider laptops.
            else if (width <= 1600)
            {
                topBarIconSize = 14;
                topBarButtonWidth = 25;
                topBarButtonHeight = 22;
                topBarCompactButtonWidth = 23;
                topBarFontSize = 11;
                topBarGap = 3;
                addressBarHeight = 25;
            }
            // Normal: your 1920 x 1200 screen.
            else if (width <= 2200)
            {
                topBarIconSize = 16;
                topBarButtonWidth = 28;
                topBarButtonHeight = 24;
                topBarCompactButtonWidth = 25;
                topBarFontSize = 12;
                topBarGap = 4;
                addressBarHeight = 26;
            }
            // Spacious: large monitors.
            else
            {
                topBarIconSize = 18;
                topBarButtonWidth = 30;
                topBarButtonHeight = 26;
                topBarCompactButtonWidth = 27;
                topBarFontSize = 13;
                topBarGap = 5;
                addressBarHeight = 28;
            }

            Resources["TopBarIconSize"] = topBarIconSize;
            Resources["TopBarButtonWidth"] = topBarButtonWidth;
            Resources["TopBarButtonHeight"] = topBarButtonHeight;
            Resources["TopBarCompactButtonWidth"] = topBarCompactButtonWidth;
            Resources["TopBarFontSize"] = topBarFontSize;
            Resources["TopBarGap"] = new Thickness(topBarGap, 0, topBarGap, 0);
            Resources["TopBarLeftGap"] = new Thickness(topBarGap, 0, 0, 0);
            Resources["AddressBarHeight"] = addressBarHeight;
        }

        private void ApplyResponsiveTopBarScale()
        {
            try
            {
                double width = ActualWidth;
                double height = ActualHeight;

                if (width <= 0)
                    width = SystemParameters.WorkArea.Width;

                if (height <= 0)
                    height = SystemParameters.WorkArea.Height;

                bool compact =
                    width <= 1400 ||
                    SystemParameters.PrimaryScreenWidth <= 1400 ||
                    SystemParameters.PrimaryScreenHeight <= 800;

                double iconButtonSize = compact ? 24 : 30;
                double iconSize = compact ? 14 : 18;
                double smallIconSize = compact ? 12 : 16;
                double tabWidth = compact ? 86 : 118;
                double addressMinWidth = compact ? 180 : 320;
                double addressMaxWidth = compact ? 360 : 560;

                Thickness compactButtonMargin = compact
                    ? new Thickness(1, 0, 1, 0)
                    : new Thickness(3, 0, 3, 0);

                Thickness compactButtonPadding = compact
                    ? new Thickness(2)
                    : new Thickness(5);

                // Top toolbar buttons/icons
                foreach (var button in FindVisualChildren<Button>(this))
                {
                    string name = button.Name ?? "";

                    bool isTopBarButton =
                        name.Contains("Top", StringComparison.OrdinalIgnoreCase) ||
                        name.Contains("Toolbar", StringComparison.OrdinalIgnoreCase) ||
                        name.Contains("Tab", StringComparison.OrdinalIgnoreCase) ||
                        name.Contains("Privacy", StringComparison.OrdinalIgnoreCase) ||
                        name.Contains("Theme", StringComparison.OrdinalIgnoreCase) ||
                        name.Contains("Guide", StringComparison.OrdinalIgnoreCase) ||
                        name.Contains("Menu", StringComparison.OrdinalIgnoreCase) ||
                        name.Contains("Home", StringComparison.OrdinalIgnoreCase) ||
                        name.Contains("Back", StringComparison.OrdinalIgnoreCase) ||
                        name.Contains("Forward", StringComparison.OrdinalIgnoreCase) ||
                        name.Contains("Refresh", StringComparison.OrdinalIgnoreCase) ||
                        name.Contains("Snapback", StringComparison.OrdinalIgnoreCase) ||
                        name.Contains("Emergency", StringComparison.OrdinalIgnoreCase) ||
                        name.Contains("QuickCompatibility", StringComparison.OrdinalIgnoreCase);

                    if (!isTopBarButton)
                        continue;

                    // Avoid resizing large content buttons/cards inside overlays.
                    if (button.ActualHeight > 60 || button.ActualWidth > 180)
                        continue;

                    // Avoid resizing buttons inside the main overlay panels.
                    if (IsInsideOverlayPanel(button))
                        continue;

                    button.MinWidth = iconButtonSize;
                    button.Width = double.NaN;
                    button.Height = iconButtonSize;
                    button.Padding = compactButtonPadding;
                    button.Margin = compactButtonMargin;

                    if (button.Content is FrameworkElement contentElement)
                    {
                        if (contentElement.Width > 0 && contentElement.Width <= 32)
                            contentElement.Width = iconSize;

                        if (contentElement.Height > 0 && contentElement.Height <= 32)
                            contentElement.Height = iconSize;
                    }
                }

                // Address bar compact behaviour
                if (AddressBox != null)
                {
                    AddressBox.MinWidth = addressMinWidth;
                    AddressBox.MaxWidth = addressMaxWidth;
                    AddressBox.FontSize = compact ? 11 : 13;
                    AddressBox.Padding = compact
                        ? new Thickness(8, 2, 8, 2)
                        : new Thickness(12, 4, 12, 4);
                }

                // Workspace / tab buttons compact behaviour
                if (WorkspaceTabsPanel != null)
                {
                    WorkspaceTabsPanel.Margin = new Thickness(0);

                    foreach (var child in WorkspaceTabsPanel.Children)
                    {
                        if (child is Button tabButton)
                        {
                            tabButton.Width = compact ? 46 : 48;
                            tabButton.MinWidth = compact ? 46 : 48;
                            tabButton.MaxWidth = compact ? 46 : 48;
                            tabButton.Height = 22;
                            tabButton.FontSize = 10;
                            tabButton.Padding = new Thickness(0);
                            tabButton.Margin = compact
                                ? new Thickness(1, 0, 0, 0)
                                : new Thickness(2, 0, 0, 0);
                        }
                    }
                }


            }
            catch
            {
                // Responsive polish should never break app startup.
            }
        }

        private void ApplyResponsiveOverlayScale()
        {
            double actualWidth = ActualWidth > 0
                ? ActualWidth
                : SystemParameters.WorkArea.Width;

            double actualHeight = ActualHeight > 0
                ? ActualHeight
                : SystemParameters.WorkArea.Height;

            // Smaller margins help older laptop screens like 1366 x 768.
            double usableWidth = Math.Max(760, actualWidth - 40);
            double usableHeight = Math.Max(520, actualHeight - 40);

            // ============================================
            // Settings overlay
            // ============================================

            double settingsDesignWidth = 1280;
            double settingsDesignHeight = 820;

            double settingsScale = Math.Min(1.0,
                Math.Min(usableWidth / settingsDesignWidth, usableHeight / settingsDesignHeight));

            // Allow Settings to shrink a little more on 1366 x 768 laptops.
            settingsScale = Math.Max(0.70, settingsScale);

            if (SettingsOverlayContentHost != null)
            {
                SettingsOverlayContentHost.LayoutTransform = new ScaleTransform(settingsScale, settingsScale);

                // Prevent the scaled Settings content from pushing outside the visible screen.
                SettingsOverlayContentHost.MaxWidth = usableWidth / settingsScale;
            }



            // ============================================
            // Privacy popup
            // ============================================

            double privacyDesignWidth = 640;
            double privacyDesignHeight = 760;

            double privacyScale = Math.Min(1.0,
                Math.Min(usableWidth / privacyDesignWidth, usableHeight / privacyDesignHeight));

            privacyScale = Math.Max(0.76, privacyScale);

            if (PrivacyPopupCard != null)
            {
                PrivacyPopupCard.LayoutTransform = new ScaleTransform(privacyScale, privacyScale);
                PrivacyPopupCard.MaxHeight = Math.Max(420, usableHeight / privacyScale);
            }

            // ============================================
            // Guide overlay
            // ============================================

            double guideDesignWidth = 980;
            double guideDesignHeight = 760;

            double guideScale = Math.Min(1.0,
                Math.Min(usableWidth / guideDesignWidth, usableHeight / guideDesignHeight));

            guideScale = Math.Max(0.76, guideScale);

            if (GuideOverlayCard != null)
            {
                GuideOverlayCard.LayoutTransform = new ScaleTransform(guideScale, guideScale);

                // Keep Guide card above the Windows taskbar / screen edge.
                GuideOverlayCard.MaxHeight = Math.Max(420, usableHeight / guideScale);
            }
        }

        private void LoadProtectionWarningStyle()
        {
            try
            {
                if (!File.Exists(_protectionWarningStylePath))
                    return;

                var txt = (File.ReadAllText(_protectionWarningStylePath) ?? "").Trim();

                if (Enum.TryParse(txt, out ProtectionWarningStyle style))
                    _protectionWarningStyle = style;
            }
            catch { }
        }

        private void SaveProtectionWarningStyle()
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_protectionWarningStylePath)!);
                File.WriteAllText(_protectionWarningStylePath, _protectionWarningStyle.ToString());
            }
            catch { }
        }

        private bool UseSimpleProtectionWarnings()
        {
            return _protectionWarningStyle == ProtectionWarningStyle.Simple;
        }

        private string BuildProtectionPopupMessage(
    string heading,
    string detailedMessage,
    MessageBoxButton buttons)
        {
            if (!UseSimpleProtectionWarnings())
                return detailedMessage;

            if (buttons == MessageBoxButton.YesNo)
            {
                return
                    $"{heading}\n\n" +
                    "Choose Yes to continue.\n" +
                    "Choose No to leave it blocked or unchanged.";
            }

            return
                "LexDesk Pro has completed this action.\n\n" +
                "For more information, switch Protection Warnings back to Detailed in Settings.";
        }

        private string BuildDownloadGuardDecisionMessage(
            string detailedMessage,
            bool allowTrustSite)
        {
            if (!UseSimpleProtectionWarnings())
                return detailedMessage;

            string trustSiteText = allowTrustSite
                ? "\nTrust Site should only be used for websites you know and trust."
                : "";

            return
                "Download Guard stopped this download.\n\n" +
                "Choose Allow Once only if you trust this file and website." +
                trustSiteText + "\n\n" +
                "After allowing it, LexDesk Pro will try to start the download automatically.\n\n" +
                "If it does not start, click the website's download button again.\n\n" +
                "For more information, switch Protection Warnings back to Detailed in Settings.";
        }

        private void UpdateProtectionWarningStyleButtons()
        {
            bool simple = UseSimpleProtectionWarnings();

            SetActiveSettingsButtonVisual(WarningDetailedButton, !simple);
            SetActiveSettingsButtonVisual(WarningSimpleButton, simple);

            if (WarningStyleStatusText != null)
            {
                WarningStyleStatusText.Text = simple
                    ? "Simple warnings are on"
                    : "Detailed warnings are on";
            }
        }

