        private void ShowStandaloneSettingsPage(
    FrameworkElement pageToShow,
    string title,
    string description,
    Button selectedButton)
        {
            try
            {
                FrameworkElement[] settingsPages =
{
    PrivacySettingsPage,
    BrowserSettingsPage,
    AppActivationPage,
    PageSettingsPage,
    ToolbarSettingsPage,
    HelpInformationPage
};

                foreach (FrameworkElement page in settingsPages)
                {
                    page.Visibility = ReferenceEquals(page, pageToShow)
                        ? Visibility.Visible
                        : Visibility.Collapsed;
                }

                if (SettingsPageTitleText != null)
                    SettingsPageTitleText.Text = title;

                if (SettingsPageDescriptionText != null)
                    SettingsPageDescriptionText.Text = description;

                SetSettingsNavigationSelection(selectedButton);

                Dispatcher.BeginInvoke(
                    new Action(() =>
                    {
                        try
                        {
                            SettingsPageScrollViewer?.ScrollToTop();
                        }
                        catch
                        {
                            // Page positioning must never affect Settings.
                        }
                    }),
                    DispatcherPriority.Loaded);
            }
            catch
            {
                // Settings page switching must never affect the app.
            }
        }

        private void ShowSettingsSection(
            FrameworkElement? target,
            string title,
            string description,
            Button selectedButton)
        {
            try
            {
                if (PrivacySettingsPage != null)
                    PrivacySettingsPage.Visibility = Visibility.Collapsed;

                if (BrowserSettingsPage != null)
                    BrowserSettingsPage.Visibility = Visibility.Visible;

                if (AppActivationPage != null)
                    AppActivationPage.Visibility = Visibility.Collapsed;

                if (PageSettingsPage != null)
                    PageSettingsPage.Visibility = Visibility.Collapsed;

                if (ToolbarSettingsPage != null)
                    ToolbarSettingsPage.Visibility = Visibility.Collapsed;

                if (HelpInformationPage != null)
                    HelpInformationPage.Visibility = Visibility.Collapsed;

                if (SettingsPageTitleText != null)
                    SettingsPageTitleText.Text = title;

                if (SettingsPageDescriptionText != null)
                    SettingsPageDescriptionText.Text = description;

                SetSettingsNavigationSelection(selectedButton);

                Dispatcher.BeginInvoke(
                    new Action(() =>
                    {
                        try
                        {
                            if (target == null)
                            {
                                SettingsPageScrollViewer?.ScrollToTop();
                                return;
                            }

                            target.BringIntoView();
                        }
                        catch
                        {
                            // Settings navigation must never affect the app.
                        }
                    }),
                    DispatcherPriority.Loaded);
            }
            catch
            {
                // Settings navigation must never affect the app.
            }
        }

        private void SetSettingsNavigationSelection(
            Button selectedButton)
        {
            try
            {
                Button[] navigationButtons =
{
    SettingsNavPrivacyButton,
    SettingsNavBrowserButton,
    SettingsNavPageButton,
    SettingsNavToolbarButton,
    SettingsNavActivationButton,
    SettingsNavHelpButton
};

                foreach (Button button in navigationButtons)
                {
                    button.Tag = ReferenceEquals(button, selectedButton)
                        ? "Selected"
                        : null;
                }
            }
            catch
            {
                // Visual selection must never affect Settings.
            }
        }

        private void SettingsOverlayCloseButton_Click(object sender, RoutedEventArgs e)
        {
            if (SettingsOverlayHost != null)
                SettingsOverlayHost.Visibility = Visibility.Collapsed;

