        private void ShowDnsQuickSetupMenu()
        {
            var dialog = new Window
            {
                Title = "DNS Quick Setup",
                Width = 340,
                Height = 320,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                ResizeMode = ResizeMode.NoResize,
                Owner = this
            };

            ApplyWebPrivacyDialogTheme(dialog);

            var root = new Grid
            {
                Margin = new Thickness(16)
            };

            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            var intro = new TextBlock
            {
                Text = "Choose a recommended DNS setup:",
                Margin = new Thickness(0, 0, 0, 12),
                FontSize = 14,
                FontWeight = FontWeights.SemiBold,
                TextWrapping = TextWrapping.Wrap
            };
            Grid.SetRow(intro, 0);

            var buttonsPanel = new StackPanel
            {
                Orientation = Orientation.Vertical
            };
            Grid.SetRow(buttonsPanel, 1);

            Button MakeButton(string text, Action onClick)
            {
                var btn = new Button
                {
                    Content = text,
                    Height = 38,
                    Margin = new Thickness(0, 0, 0, 8),
                    Padding = new Thickness(10, 6, 10, 6)
                };
                ApplyWebPrivacyButtonTheme(btn);

                btn.Click += (_, __) =>
                {
                    onClick();
                    dialog.DialogResult = true;
                    dialog.Close();
                };

                return btn;
            }

            buttonsPanel.Children.Add(MakeButton("⚡ Speed (Cloudflare + Google)", () =>
            {
                _smartMode = SmartMode.Custom;
                SetDnsPreset(DnsPreset.Cloudflare);
                SetSearchEngine(SearchEngine.Google);
                UpdateSmartModeUI();
                UpdateSecurityStatus("Speed setup applied", false);
            }));

            buttonsPanel.Children.Add(MakeButton("🔒 Privacy (Quad9 + Duck Duck Go)", () =>
            {
                _smartMode = SmartMode.Custom;
                SetDnsPreset(DnsPreset.Quad9);
                SetSearchEngine(SearchEngine.DuckDuckGo);
                UpdateSmartModeUI();
                UpdateSecurityStatus("Privacy setup applied", false);
            }));

            buttonsPanel.Children.Add(MakeButton("🛡 Security (Quad9 + Brave)", () =>
            {
                _smartMode = SmartMode.Custom;
                SetDnsPreset(DnsPreset.Quad9);
                SetSearchEngine(SearchEngine.Brave);
                UpdateSmartModeUI();
                UpdateSecurityStatus("Security setup applied", false);
            }));

            buttonsPanel.Children.Add(MakeButton("⭐ Balanced (Cloudflare + Google)", () =>
            {
                _smartMode = SmartMode.Custom;
                SetDnsPreset(DnsPreset.Cloudflare);
                SetSearchEngine(SearchEngine.Google);
                UpdateSmartModeUI();
                UpdateSecurityStatus("Balanced setup applied", false);
            }));

            buttonsPanel.Children.Add(MakeButton("🖥 System Default (ISP)", () =>
            {
                _smartMode = SmartMode.Custom;
                SetDnsPreset(DnsPreset.SystemDefault);
                UpdateSmartModeUI();
                UpdateSecurityStatus("System DNS applied", false);
            }));

            var closeButton = new Button
            {
                Content = "Close",
                Width = 90,
                Height = 34,
                HorizontalAlignment = HorizontalAlignment.Right,
                IsCancel = true
            };
            ApplyWebPrivacyButtonTheme(closeButton);
            closeButton.Click += (_, __) => dialog.Close();
            Grid.SetRow(closeButton, 2);

            root.Children.Add(intro);
            root.Children.Add(buttonsPanel);
            root.Children.Add(closeButton);

            dialog.Content = root;
            dialog.ShowDialog();
        }


