        private void UpdateDnsModeUi()
        {
            if (DnsModeStatusText != null)
            {
                DnsModeStatusText.Text = _dnsMode switch
                {
                    DnsApplyMode.SystemWindows =>
                        "Current: Normal - using your normal Windows internet settings",

                    DnsApplyMode.AdultContentFilter =>
                        "Current: Adult Content blocking is on for this computer",

                    DnsApplyMode.WindowsIpv4 =>
                        $"Current: {GetDnsPresetDisplayName(_dnsPreset)} is helping Windows find websites",

                    DnsApplyMode.AppOnlySecureDns =>
                        "Current: Experimental Private DNS (not shown in this version)",

                    _ =>
                        "Current: Normal - using your normal Windows internet settings"
                };
            }

            RefreshDnsModeButtonVisuals();
        }

        private void RefreshDnsModeButtonVisuals()
        {
            try
            {
                void SetDnsButton(Button? button, bool selected)
                {
                    if (button == null)
                        return;

                    button.BorderThickness = selected
                        ? new Thickness(2.4)
                        : new Thickness(1.2);

                    button.FontWeight = selected
                        ? FontWeights.Bold
                        : FontWeights.Normal;

                    button.SetResourceReference(
                        Control.BorderBrushProperty,
                        selected ? "SelectedButtonBorder" : "ButtonBorder");

                    button.SetResourceReference(
                        Control.BackgroundProperty,
                        selected ? "ButtonPressedBg" : "ButtonBg");
                }

                SetDnsButton(DnsModeSystemBtn, _dnsMode == DnsApplyMode.SystemWindows);
                SetDnsButton(DnsModeAdultBtn, _dnsMode == DnsApplyMode.AdultContentFilter);
            }
            catch
            {
                // DNS visual refresh must never affect DNS settings.
            }
        }

        private void SetActiveSettingsButtonVisual(Button? button, bool selected)
        {
            if (button == null)
                return;

            button.BorderThickness = selected
                ? new Thickness(2.4)
                : new Thickness(1.2);

            button.FontWeight = selected
                ? FontWeights.Bold
                : FontWeights.Normal;

            // Keep the choice button attached to the live theme resources.
            // Previously Search Region could retain Dark brushes after switching to Light.
            button.SetResourceReference(
                Control.BorderBrushProperty,
                selected ? "SelectedButtonBorder" : "ButtonBorder");

            button.SetResourceReference(
                Control.BackgroundProperty,
                selected ? "ButtonPressedBg" : "ButtonBg");
        }

