        private void DnsMode_System_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                bool backupExists = File.Exists(_windowsDnsBackupPath);

                if (backupExists)
                {
                    var restoreConfirm = ShowLexDeskMessageBox(
    "Normal will restore the Windows DNS settings that LexDesk Pro saved before it made a computer-wide DNS change.\n\nContinue?",
    "Normal Internet Protection",
    MessageBoxButton.YesNo,
    MessageBoxImage.Question);

                    if (restoreConfirm != MessageBoxResult.Yes)
                        return;

                    if (!RestoreWindowsDnsWithPermission(out string restoreError))
                    {
                        ShowLexDeskMessageBox(
                            "LexDesk Pro could not restore the saved Windows DNS settings.\n\n" + restoreError,
                            "Normal Internet Protection",
                            MessageBoxButton.OK,
                            MessageBoxImage.Warning);
                        return;
                    }

                    DeleteWindowsDnsBackupSafe();
                }
                else if (_dnsMode == DnsApplyMode.WindowsIpv4 || _dnsMode == DnsApplyMode.AdultContentFilter)
                {
                    // Do not guess at a customer's original DNS if an old/legacy session
                    // says LexDesk Pro changed Windows but the safety backup is missing.
                    ShowLexDeskMessageBox(
    "LexDesk Pro cannot find the internet settings it saved earlier, so it will not guess what your old settings were.\n\n" +
    "If you are unsure what to do, please contact support.",
    "Normal Internet Protection",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);
                    return;
                }

                _dnsMode = DnsApplyMode.SystemWindows;
                SaveDnsMode();
                UpdateDnsModeUi();

                var confirm = ShowLexDeskMessageBox(
    "Block Adult Content adds extra protection for this whole computer.\n\n" +
    "Windows will ask for permission before the setting is changed.\n\nTurn it on?",
                    "Normal Internet Protection",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    $"DNS change failed:\n{SanitizeExceptionMessage(ex)}",
                    "DNS",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
        }

