        private void DnsMode_Adult_Click(object sender, RoutedEventArgs e)
        {
            if (!HasFullUnlock())
            {
                ShowLexDeskMessageBox(
                    "Please activate LexDesk Pro to use Block Adult Content.",
                    "Activation Required",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            try
            {
                var confirm = ShowLexDeskMessageBox(
                    "Block Adult Content uses Cloudflare Family protection and changes Windows DNS for the whole computer.\n\n" +
                    "Windows will ask for administrator permission. LexDesk Pro will handle the change for you.\n\nContinue?",
                    "Block Adult Content",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Question);

                if (confirm != MessageBoxResult.Yes)
                    return;

                if (!EnsureOriginalWindowsDnsBackup(out bool backupCreatedThisAttempt))
                {
                    ShowLexDeskMessageBox(
                        "LexDesk Pro could not safely save your current internet settings, so Block Adult Content was not turned on.",
                        "Block Adult Content",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);
                    return;
                }

                if (!ApplyDnsPresetWithPermission(DnsPreset.CloudflareFamily, out string error))
                {
                    if (backupCreatedThisAttempt)
                        DeleteWindowsDnsBackupSafe();

                    ShowLexDeskMessageBox(
                        "Block Adult Content was not turned on.\n\n" + error,
                        "Block Adult Content",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                    return;
                }

                // Keep _dnsPreset unchanged. The customer's normal provider choice
                // remains remembered underneath the temporary family filter.
                _dnsMode = DnsApplyMode.AdultContentFilter;
                SaveDnsMode();
                UpdateDnsModeUi();
                UpdateDnsUI();

                ShowLexDeskMessageBox(
    "Block Adult Content is now on for this computer.\n\n" +
    "Many known dangerous and adult websites will now be blocked.\n\n" +
    "Choose Normal to turn this off and put your saved internet settings back.",
    "Block Adult Content",
    MessageBoxButton.OK,
    MessageBoxImage.Information);
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    $"Adult Content Filter could not be enabled:\n{SanitizeExceptionMessage(ex)}",
                    "Block Adult Content",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
        }

