        private bool SetDnsPreset(DnsPreset preset, bool showSuccessMessage = true)
        {
            if (!HasFullUnlock())
            {
                ShowLexDeskMessageBox(
                    "Please activate LexDesk Pro to change the Windows website lookup provider.",
                    "Activation Required",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return false;
            }

            string providerName = GetDnsPresetDisplayName(preset);

            var confirm = ShowLexDeskMessageBox(
                $"Use {providerName} as the Windows website lookup provider?\n\n" +
                "This changes DNS for the whole computer. Windows will ask for administrator permission.\n\n" +
                "LexDesk Pro will save your current DNS first so Normal can restore it later.",
                "Website lookup provider",
                MessageBoxButton.YesNo,
                MessageBoxImage.Question);

            if (confirm != MessageBoxResult.Yes)
                return false;

            if (!EnsureOriginalWindowsDnsBackup(out bool backupCreatedThisAttempt))
            {
                ShowLexDeskMessageBox(
                    "LexDesk Pro could not safely save your current Windows DNS settings, so no DNS change was made.",
                    "Website lookup provider",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
                return false;
            }

            if (!ApplyDnsPresetWithPermission(preset, out string error))
            {
                if (backupCreatedThisAttempt)
                    DeleteWindowsDnsBackupSafe();

                ShowLexDeskMessageBox(
                    "Windows DNS was not changed.\n\n" + error,
                    "Website lookup provider",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return false;
            }

            _dnsPreset = preset;
            SaveDnsPreset();

            _dnsMode = DnsApplyMode.WindowsIpv4;
            SaveDnsMode();

            UpdateDnsUI();
            UpdateDnsModeUi();

            if (showSuccessMessage)
            {
                ShowLexDeskMessageBox(
                    $"{providerName} is now active for Windows website lookups.\n\n" +
                    "Choose Normal under Internet Protection whenever you want LexDesk Pro to restore your saved Windows DNS settings.",
                    "Website lookup provider",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }

            return true;
        }

        private bool IsRunningAsAdmin()
        {
            try
            {
                var identity = System.Security.Principal.WindowsIdentity.GetCurrent();
                var principal = new System.Security.Principal.WindowsPrincipal(identity);
                return principal.IsInRole(System.Security.Principal.WindowsBuiltInRole.Administrator);
            }
            catch
            {
                return false;
            }
        }

        private void RelaunchElevatedAndExit()
        {
            try
            {
                SaveSessionState();

                var psi = new ProcessStartInfo
                {
                    FileName = Process.GetCurrentProcess().MainModule!.FileName!,
                    UseShellExecute = true,
                    Verb = "runas"
                };

                Process.Start(psi);
                Application.Current.Shutdown();
            }
            catch
            {
                ShowLexDeskMessageBox(
                    "Elevation cancelled.",
                    "DNS",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

