        private void PrivacyButton_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;

            if (HomeOverlay1 != null)
                HomeOverlay1.Visibility = Visibility.Collapsed;

            if (SettingsDropdown != null)
                SettingsDropdown.IsOpen = false;

            if (PrivacyDropdown != null)
                PrivacyDropdown.IsOpen = false;

            if (StatusPopup != null)
                StatusPopup.IsOpen = false;

            if (WebActionsDropdown != null)
                WebActionsDropdown.IsOpen = false;

            if (GuideOverlay != null)
                GuideOverlay.Visibility = Visibility.Collapsed;

            if (StartupScreenOverlayHost != null)
                StartupScreenOverlayHost.Visibility = Visibility.Collapsed;

            if (PagesHost != null)
                PagesHost.Visibility = Visibility.Collapsed;

            if (SettingsOverlayHost == null)
                return;

            ApplyResponsiveOverlayScale();
            ApplyResponsiveTopBarScale();

            SettingsOverlayHost.Visibility = Visibility.Visible;

            ShowStandaloneSettingsPage(
                pageToShow: PrivacySettingsPage,
                title: "Privacy & Safety",
                description:
                    "Choose how LexDesk Pro protects you and what to do if a website needs extra help.",
                selectedButton: SettingsNavPrivacyButton);

            RefreshPrivacyNetworkVisuals();
            UpdatePrivacyDropdownVisuals();
            ApplyPrivacyRelayControlVisibility();
            UpdateProtectionWarningStyleButtons();
        }

