        private async void UpdateAppButton_Click(object sender, RoutedEventArgs e)
        {
            if (!LexDeskUpdatesEnabled)
            {
                _isLatestUpdate = true;
                _latestDownloadUrl = "";

                if (UpdateAppButton != null)
                    UpdateAppButton.IsEnabled = false;

                if (UpdateStatusText != null)
                    UpdateStatusText.Text = "Updates not available yet";

                ShowLexDeskMessageBox(
                    "LexDesk Pro updates are not available yet.\n\n" +
                    "This early LexDesk Pro build will not download or install updates.",
                    "LexDesk Pro Updates",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);

                return;
            }

            try
            {
                // Always refresh update info first so we never use an old/stale download URL.
                await CheckForUpdatesAsync(false);

                if (_isLatestUpdate)
                {
                    ShowLexDeskMessageBox(
                        "LexDesk Pro is already up to date.",
                        "App Updates",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                    return;
                }

                if (string.IsNullOrWhiteSpace(_latestDownloadUrl))
                {
                    ShowLexDeskMessageBox(
                        "No update download link is available.",
                        "Update App",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                    return;
                }

                var confirm = ShowLexDeskMessageBox(
                    "LexDesk Pro will now download and open the update installer.\n\n" +
                    "After the installer opens, LexDesk Pro will close.\n\n" +
                    "Please follow the Windows installer prompts, then reopen LexDesk Pro to complete the update.",
                    "Update LexDesk Pro",
                    MessageBoxButton.OKCancel,
                    MessageBoxImage.Information);

                if (confirm != MessageBoxResult.OK)
                    return;

                UpdateAppButton.IsEnabled = false;
                UpdateAppButton.Content = "Downloading...";

                string fileName = Path.GetFileName(new Uri(_latestDownloadUrl).LocalPath);
                if (string.IsNullOrWhiteSpace(fileName))
                    fileName = "LexDeskProUpdate.msix";

                string downloadPath = Path.Combine(Path.GetTempPath(), fileName);

                using (var http = new HttpClient())
                {
                    var data = await http.GetByteArrayAsync(_latestDownloadUrl);
                    await File.WriteAllBytesAsync(downloadPath, data);
                }

                UpdateAppButton.Content = "Launching Installer...";

                if (!TryStartExternalProcess(downloadPath, "the update installer"))
                    return;

                ShowLexDeskMessageBox(
                    "The update installer has been opened.\n\n" +
                    "LexDesk Pro will now close so the update can complete cleanly.",
                    "Update Ready",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);

                Application.Current.Shutdown();
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
    "Could not download or launch the update.\n\n" +
    SanitizeExceptionMessage(ex),
    "Update App",
    MessageBoxButton.OK,
    MessageBoxImage.Warning);
            }
            finally
            {
                if (UpdateAppButton != null)
                {
                    UpdateAppButton.Content = "Update App";
                    UpdateAppButton.IsEnabled = !_isLatestUpdate;
                }
            }
        }

