        private void ContactSupportButton_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                string? userMessage = ShowSupportInputDialog();
                if (string.IsNullOrWhiteSpace(userMessage))
                    return;

                string subject = "[LexDesk Pro Support] - User Request";

                string body =
                    "User Message:\r\n" +
                    "----------------------------------\r\n" +
                    $"{userMessage}\r\n\r\n" +
                    "----------------------------------\r\n\r\n" +
                    "App Information:\r\n" +
                    $"Version: {GetAppVersion()}\r\n" +
                    $"Date: {DateTime.Now:yyyy-MM-dd}\r\n" +
                    $"Time: {DateTime.Now:HH:mm}\r\n\r\n" +
                    "----------------------------------\r\n" +
                    "Sent from LexDesk Pro";

                string encodedSubject = Uri.EscapeDataString(subject);
                string encodedBody = Uri.EscapeDataString(body);

                string mailto = $"mailto:support@lexandwhitestudios.com?subject={encodedSubject}&body={encodedBody}";

                Process.Start(new ProcessStartInfo
                {
                    FileName = mailto,
                    UseShellExecute = true
                });
            }

            catch
            {
                ShowLexDeskMessageBox(
                    "Could not open your email app.\n\n" +
                    "Please email:\n" +
                    "support@lexandwhitestudios.com",
                    "Contact Support",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

