        private void OpenPaymentTestLink(string url, string friendlyName)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(url))
                {
                    ShowLexDeskMessageBox(
                        $"{friendlyName} is not connected yet.",
                        "Payment Method",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                    return;
                }

                if (url.Contains("REPLACE", StringComparison.OrdinalIgnoreCase) ||
                    url.Contains("PUT_", StringComparison.OrdinalIgnoreCase))
                {
                    ShowLexDeskMessageBox(
                        $"{friendlyName} still has a test placeholder link.\n\n" +
                        "Add the real test URL when it is ready.",
                        "Payment Method",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                    return;
                }

                TryStartExternalProcess(url, friendlyName);
                UpdateSecurityStatus($"{friendlyName} opened", false);
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    $"Could not open {friendlyName}.\n\n{SanitizeExceptionMessage(ex)}",
                    "Payment Method",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
        }

