        private void SetRecommendedToolbarPreferences()
        {
            _showWorkspaceTabs = true;
            _showHomeButton = true;
            _showBackToWindowsButton = true;
            _showFavouritesButton = true;
            _showEmergencyExitButton = true;
            _showToolsButton = true;
            _showCompatibilityButton = true;
            _showPrintButton = false;
            _showHistoryButton = false;
            _showCyclePagesButton = false;
            _showSettingsButton = false;
            _showAiButton = false;

            _aiChatGptEnabled = true;
            _aiClaudeEnabled = true;
            _aiGeminiEnabled = true;
            _aiPerplexityEnabled = true;
            _aiCopilotEnabled = false;
            _aiGrokEnabled = false;
            _aiDeepSeekEnabled = false;
        }

        private void LoadToolbarPreferences()
        {
            SetRecommendedToolbarPreferences();

            try
            {
                if (!File.Exists(_toolbarPreferencesPath))
                    return;

                string json = File.ReadAllText(_toolbarPreferencesPath);
                var preferences = JsonSerializer.Deserialize<ToolbarPreferences>(json);

                if (preferences == null)
                    return;

                _showWorkspaceTabs = preferences.ShowWorkspaceTabs;
                _showHomeButton = preferences.ShowHomeButton;
                _showBackToWindowsButton = preferences.ShowBackToWindowsButton;
                _showFavouritesButton = preferences.ShowFavouritesButton;
                _showEmergencyExitButton = preferences.ShowEmergencyExitButton;
                _showToolsButton = preferences.ShowToolsButton;
                _showCompatibilityButton = preferences.ShowCompatibilityButton;
                _showPrintButton = preferences.ShowPrintButton;
                _showHistoryButton = preferences.ShowHistoryButton;
                _showCyclePagesButton = preferences.ShowCyclePagesButton;
                _showSettingsButton = preferences.ShowSettingsButton;
                _showAiButton = preferences.ShowAiButton;

                _aiChatGptEnabled = preferences.AiChatGptEnabled;
                _aiClaudeEnabled = preferences.AiClaudeEnabled;
                _aiGeminiEnabled = preferences.AiGeminiEnabled;
                _aiPerplexityEnabled = preferences.AiPerplexityEnabled;
                _aiCopilotEnabled = preferences.AiCopilotEnabled;
                _aiGrokEnabled = preferences.AiGrokEnabled;
                _aiDeepSeekEnabled = preferences.AiDeepSeekEnabled;
            }
            catch
            {
                SetRecommendedToolbarPreferences();
            }
        }

        private void SaveToolbarPreferences()
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_toolbarPreferencesPath)!);

                var preferences = new ToolbarPreferences
                {
                    ShowWorkspaceTabs = _showWorkspaceTabs,
                    ShowHomeButton = _showHomeButton,
                    ShowBackToWindowsButton = _showBackToWindowsButton,
                    ShowFavouritesButton = _showFavouritesButton,
                    ShowEmergencyExitButton = _showEmergencyExitButton,
                    ShowToolsButton = _showToolsButton,
                    ShowCompatibilityButton = _showCompatibilityButton,
                    ShowPrintButton = _showPrintButton,
                    ShowHistoryButton = _showHistoryButton,
                    ShowCyclePagesButton = _showCyclePagesButton,
                    ShowSettingsButton = _showSettingsButton,
                    ShowAiButton = _showAiButton,
                    AiChatGptEnabled = _aiChatGptEnabled,
                    AiClaudeEnabled = _aiClaudeEnabled,
                    AiGeminiEnabled = _aiGeminiEnabled,
                    AiPerplexityEnabled = _aiPerplexityEnabled,
                    AiCopilotEnabled = _aiCopilotEnabled,
                    AiGrokEnabled = _aiGrokEnabled,
                    AiDeepSeekEnabled = _aiDeepSeekEnabled
                };

                string json = JsonSerializer.Serialize(
                    preferences,
                    JsonIndentedOptions);

                File.WriteAllText(_toolbarPreferencesPath, json);
            }
            catch
            {
                // Toolbar choices must never affect browsing.
            }
        }

