                            AiGrokToggle.IsChecked = _aiGrokEnabled;

                        if (AiDeepSeekToggle != null)
                            AiDeepSeekToggle.IsChecked = _aiDeepSeekEnabled;
                    }
                    finally
                    {
                        _toolbarPreferencesLoading = false;
                    }
                }

                ApplyResponsiveToolbarSize();
                ApplyResponsiveTopBarScale();

                Dispatcher.BeginInvoke(
                    new Action(UpdateDynamicAddressBarWidth),
                    DispatcherPriority.Loaded);
            }
            catch
            {
                // Toolbar visibility must never affect the rest of the app.
            }
        }

        private void UpdateDynamicAddressBarWidth()
        {
            try
            {
                if (CenterToolbarHost == null ||
                    CenterToolbarPanel == null ||
                    AddressBarHost == null)
                    return;

                double availableWidth = CenterToolbarHost.ActualWidth;

                if (availableWidth <= 0)
                    return;

                // The outer address host controls the size.
                // The TextBox itself must never force the toolbar wider.
                if (AddressBox != null)
                    AddressBox.MinWidth = 0;

                // On small screens the address bar gives up space first.
                AddressBarHost.MinWidth = 80;

                double leftUsedWidth = 0;
                double rightUsedWidth = 0;

                bool passedAddressBar = false;

                foreach (UIElement child in CenterToolbarPanel.Children)
                {
                    if (ReferenceEquals(child, AddressBarHost))
                    {
                        passedAddressBar = true;
                        continue;
                    }

                    if (child.Visibility != Visibility.Visible)
                        continue;

                    if (child is not FrameworkElement element)
                        continue;

                    double childWidth =
                        Math.Max(
                            element.ActualWidth,
                            element.DesiredSize.Width);

                    Thickness margin = element.Margin;

                    childWidth += margin.Left + margin.Right;

                    if (!passedAddressBar)
                        leftUsedWidth += childWidth;
                    else
                        rightUsedWidth += childWidth;
                }

                const double sideGap = 10;
                const double preferredMaxWidth = 560;
                const double minimumWidth = 80;

                // First work out how much room actually remains after all
                // navigation and Page controls have claimed their space.
                double availableForAddress =
                    availableWidth -
                    leftUsedWidth -
                    rightUsedWidth -
                    (sideGap * 2);

                double targetWidth =
                    Math.Clamp(
                        availableForAddress,
                        minimumWidth,
                        preferredMaxWidth);

                // Ideally the address bar sits in the visual centre.
                double idealLeft =
                    (availableWidth - targetWidth) / 2.0;

                // But it must never overlap the navigation controls on the left.
                double minimumLeft =
                    leftUsedWidth + sideGap;

                // And it must always leave room for Page 1-4 and their controls
                // on the right.
                double maximumLeft =
                    availableWidth -
                    rightUsedWidth -
                    sideGap -
                    targetWidth;

                if (maximumLeft < minimumLeft)
                    maximumLeft = minimumLeft;

                double actualLeft =
                    Math.Clamp(
                        idealLeft,
                        minimumLeft,
                        maximumLeft);

                // StackPanel already places the address bar after the left controls.
                // This margin supplies only the extra space required to centre it.
                double extraLeftMargin =
                    Math.Max(
                        0,
                        actualLeft - leftUsedWidth);

                AddressBarHost.Margin =
                    new Thickness(
                        extraLeftMargin,
                        0,
                        0,
                        0);

                AddressBarHost.Width = targetWidth;
            }
            catch
            {
                // Toolbar resizing must never affect browsing.
            }
        }

        private void ToolbarPreferenceToggle_Changed(
            object sender,
            RoutedEventArgs e)
        {
            if (_toolbarPreferencesLoading)
                return;

            if (sender is not ToggleButton toggle ||
                toggle.Tag is not string preferenceName)
                return;

            bool isEnabled = toggle.IsChecked == true;

            switch (preferenceName)
            {
                case "WorkspaceTabs":
                    _showWorkspaceTabs = isEnabled;
                    break;

                case "Home":
                    _showHomeButton = isEnabled;
                    break;

                case "BackToWindows":
                    _showBackToWindowsButton = isEnabled;
                    break;

                case "Favourites":
                    _showFavouritesButton = isEnabled;
                    break;

                case "EmergencyExit":
                    _showEmergencyExitButton = isEnabled;
                    break;

                case "Tools":
                    _showToolsButton = isEnabled;
                    break;

                case "Compatibility":
                    _showCompatibilityButton = isEnabled;
                    break;

                case "Print":
                    _showPrintButton = isEnabled;
                    break;

                case "History":
                    _showHistoryButton = isEnabled;
                    break;

                case "CyclePages":
                    _showCyclePagesButton = isEnabled;
                    break;

                case "Settings":
                    _showSettingsButton = isEnabled;
                    break;

                case "AI":
                    _showAiButton = isEnabled;
                    break;

                case "AIChatGPT":
                    _aiChatGptEnabled = isEnabled;
                    break;

                case "AIClaude":
                    _aiClaudeEnabled = isEnabled;
                    break;

                case "AIGemini":
                    _aiGeminiEnabled = isEnabled;
                    break;

                case "AIPerplexity":
                    _aiPerplexityEnabled = isEnabled;
                    break;

                case "AICopilot":
                    _aiCopilotEnabled = isEnabled;
                    break;

                case "AIGrok":
                    _aiGrokEnabled = isEnabled;
                    break;

                case "AIDeepSeek":
                    _aiDeepSeekEnabled = isEnabled;
                    break;

                default:
                    return;
            }

            SaveToolbarPreferences();
            ApplyToolbarPreferences(syncToggleControls: false);
        }

