        }

        private void LoadAutoStartSetting()
        {
            try
            {
                _autoStartEnabled = false;

                if (File.Exists(_autoStartPath))
                {
                    var txt = (File.ReadAllText(_autoStartPath) ?? "").Trim();
                    if (bool.TryParse(txt, out bool parsedAutoStart))
                        _autoStartEnabled = parsedAutoStart;
                }
            }
            catch
            {
                _autoStartEnabled = false;
            }
        }

        private void SaveAutoStartSetting()
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_autoStartPath)!);
                File.WriteAllText(_autoStartPath, _autoStartEnabled.ToString());
            }
            catch { }
        }

        private void ApplyAutoStartSetting()
        {
            try
            {
                using var key = Registry.CurrentUser.OpenSubKey(
                    @"Software\Microsoft\Windows\CurrentVersion\Run", true);

                if (key == null)
                    return;

                const string appName = "LexDesk Pro";
                string exePath = Process.GetCurrentProcess().MainModule!.FileName!;

                // Stage 3A brand migration: keep startup behaviour intact while removing
                // legacy display-name entries so Windows does not show or launch duplicates.
                string[] legacyAppNames = { "Web Studio Browser" };

                if (_autoStartEnabled)
                {
                    key.SetValue(appName, $"\"{exePath}\"");

                    foreach (string legacyName in legacyAppNames)
                    {
                        if (key.GetValue(legacyName) != null)
                            key.DeleteValue(legacyName, false);
                    }
                }
                else
                {
                    if (key.GetValue(appName) != null)
                        key.DeleteValue(appName, false);

                    foreach (string legacyName in legacyAppNames)
                    {
                        if (key.GetValue(legacyName) != null)
                            key.DeleteValue(legacyName, false);
                    }
                }
            }
            catch { }
        }

        private void UpdateAutoStartButtonLabel()
        {
            if (AutoStartButton != null)
                AutoStartButton.Content = _autoStartEnabled ? "Auto Start: On" : "Auto Start: Off";

            if (LexDeskStartWithWindowsButton != null)
            {
                LexDeskStartWithWindowsButton.Content = _autoStartEnabled
                    ? "Start LexDesk with Windows: On"
                    : "Start LexDesk with Windows: Off";
            }
        }

        private void AutoStartButton_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                _autoStartEnabled = !_autoStartEnabled;

                SaveAutoStartSetting();
                ApplyAutoStartSetting();
                UpdateAutoStartButtonLabel();

                ShowLexDeskMessageBox(
                    _autoStartEnabled
                        ? "LexDesk Pro will now open automatically after you sign in to Windows.\n\nWindows still starts normally underneath, so the normal desktop remains available if you minimise LexDesk."
                        : "LexDesk Pro will no longer open automatically after you sign in to Windows.",
                    "Start LexDesk with Windows",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
    $"Auto Start could not be changed:\n{SanitizeExceptionMessage(ex)}",
    "Auto Start",
    MessageBoxButton.OK,
    MessageBoxImage.Warning);
            }
        }

