        [DllImport("dwmapi.dll")]
        private static extern int DwmSetWindowAttribute(
    IntPtr hwnd,
    int dwAttribute,
    ref int pvAttribute,
    int cbAttribute);

        [DllImport("dwmapi.dll")]
        private static extern int DwmGetWindowAttribute(
            IntPtr hwnd,
            int dwAttribute,
            out int pvAttribute,
            int cbAttribute);

        private const int LexDeskDwmaCloaked = 14;

        private void ApplyWebPrivacyDialogTheme(Window dialog)
        {
            if (dialog == null)
                return;

            // Copy the current MainWindow theme resources into this separate dialog.
            // Separate WPF Windows do not automatically inherit MainWindow.Resources.
            string[] themeKeys =
            {
        "AppBg",
        "CardBg",
        "CardBorder",
        "ButtonBg",
        "ButtonBorder",
        "ButtonHoverBg",
        "ButtonPressedBg",
        "TextPrimary",
        "TextSecondary",
        "InputBg",
        "InputBorder",
        "SelectedButtonBorder",
        "IconBrush",
        "IconBrushMuted"
    };

            foreach (string key in themeKeys)
            {
                object value = TryFindResource(key);

                if (value != null)
                    dialog.Resources[key] = value;
            }

            dialog.Background =
                dialog.Resources["AppBg"] as Brush ?? Brushes.White;

            dialog.Foreground =
                dialog.Resources["TextPrimary"] as Brush ?? Brushes.Black;

            // Match the Windows title bar to LexDesk Pro's Light/Dark appearance.
            dialog.SourceInitialized += (_, __) =>
            {
                try
                {
                    IntPtr hwnd = new WindowInteropHelper(dialog).Handle;

                    int useDark =
                        (_themeIndex == (int)AppTheme.Dark ||
                         _themeIndex == (int)AppTheme.NeonBlue)
                            ? 1
                            : 0;

                    // Windows 11 / newer Windows 10.
                    int result = DwmSetWindowAttribute(
                        hwnd,
                        20,
                        ref useDark,
                        sizeof(int));

                    // Fallback for some older Windows 10 builds.
                    if (result != 0)
                    {
                        _ = DwmSetWindowAttribute(
                            hwnd,
                            19,
                            ref useDark,
                            sizeof(int));
                    }
                }
                catch
                {
                    // Theme decoration must never stop a dialog opening.
                }
            };
        }

        private MessageBoxResult ShowLexDeskMessageBox(
            string message,
            string title,
            MessageBoxButton buttons,
            MessageBoxImage icon)
        {
            // Some checks complete on worker tasks. Always create WPF UI on the
            // LexDesk dispatcher so themed popups remain safe.
            if (!Dispatcher.CheckAccess())
            {
                return Dispatcher.Invoke(
                    () => ShowLexDeskMessageBox(
                        message,
                        title,
                        buttons,
                        icon));
            }

            MessageBoxResult result =
                MessageBoxResult.None;

            string safeTitle =
                string.IsNullOrWhiteSpace(title)
                    ? "LexDesk Pro"
                    : title.Trim();

            string safeMessage =
                message ?? "";

            int visualLines =
                Math.Max(
                    1,
                    safeMessage.Count(c => c == '\n') + 1);

            int wrappedLines =
                Math.Max(
                    visualLines,
                    (int)Math.Ceiling(
                        Math.Max(1, safeMessage.Length) / 72.0));

            double dialogHeight =
                Math.Clamp(
                    190 + (wrappedLines * 20),
                    230,
                    Math.Min(
                        720,
                        SystemParameters.WorkArea.Height * 0.82));

            var dialog = new Window
            {
                Title = safeTitle,
                Width = 610,
                Height = dialogHeight,
                MinWidth = 480,
                MinHeight = 220,
                MaxWidth = Math.Max(
                    520,
                    SystemParameters.WorkArea.Width * 0.80),
                MaxHeight = Math.Max(
                    300,
                    SystemParameters.WorkArea.Height * 0.86),
                ResizeMode = ResizeMode.NoResize,
                WindowStartupLocation =
                    IsLoaded
                        ? WindowStartupLocation.CenterOwner
                        : WindowStartupLocation.CenterScreen,
                ShowInTaskbar = false
            };

            if (IsLoaded)
            {
                try
                {
                    dialog.Owner = this;
                }
                catch
                {
                    // A popup must still open if Windows is between owner states.
                }
            }

            ApplyWebPrivacyDialogTheme(dialog);

            var outer = new Border
            {
                Margin = new Thickness(16),
                Padding = new Thickness(20),
                CornerRadius = new CornerRadius(14),
                BorderThickness = new Thickness(1.2)
            };

            outer.SetResourceReference(
                Border.BackgroundProperty,
                "CardBg");

            outer.SetResourceReference(
                Border.BorderBrushProperty,
                "CardBorder");

            var root = new Grid();

            root.RowDefinitions.Add(
                new RowDefinition
                {
                    Height =
                        new GridLength(
                            1,
                            GridUnitType.Star)
                });

            root.RowDefinitions.Add(
                new RowDefinition
                {
                    Height = GridLength.Auto
                });

            var contentGrid = new Grid();

            contentGrid.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = GridLength.Auto
                });

            contentGrid.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width =
                        new GridLength(
                            1,
                            GridUnitType.Star)
                });

            string iconText =
                icon switch
                {
                    MessageBoxImage.Warning => "!",
                    MessageBoxImage.Error => "×",
                    MessageBoxImage.Question => "?",
                    _ => "i"
                };

            var iconBorder = new Border
            {
                Width = 34,
                Height = 34,
                CornerRadius = new CornerRadius(17),
                BorderThickness = new Thickness(1.4),
                Margin = new Thickness(0, 1, 14, 0),
                VerticalAlignment = VerticalAlignment.Top
            };

            iconBorder.SetResourceReference(
                Border.BorderBrushProperty,
                "ButtonBorder");

            iconBorder.SetResourceReference(
                Border.BackgroundProperty,
                "ButtonBg");

            var iconBlock = new TextBlock
            {
                Text = iconText,
                FontSize = 18,
                FontWeight = FontWeights.SemiBold,
                HorizontalAlignment =
                    HorizontalAlignment.Center,
                VerticalAlignment =
                    VerticalAlignment.Center,
                TextAlignment = TextAlignment.Center
            };

            iconBlock.SetResourceReference(
                TextBlock.ForegroundProperty,
                "TextPrimary");

            iconBorder.Child = iconBlock;

            Grid.SetColumn(
                iconBorder,
                0);

            var messageBlock = new TextBlock
            {
                Text = safeMessage,
                TextWrapping = TextWrapping.Wrap,
                FontSize = 13,
                LineHeight = 20,
                VerticalAlignment =
                    VerticalAlignment.Top
            };

            messageBlock.SetResourceReference(
                TextBlock.ForegroundProperty,
                "TextPrimary");

            var scroll = new ScrollViewer
            {
                Content = messageBlock,
                VerticalScrollBarVisibility =
                    ScrollBarVisibility.Auto,
                HorizontalScrollBarVisibility =
                    ScrollBarVisibility.Disabled,
                Padding = new Thickness(0, 0, 8, 0)
            };

            Grid.SetColumn(
                scroll,
                1);

            contentGrid.Children.Add(iconBorder);
            contentGrid.Children.Add(scroll);

            Grid.SetRow(
                contentGrid,
                0);

            var buttonPanel = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                HorizontalAlignment =
                    HorizontalAlignment.Right,
                Margin = new Thickness(0, 18, 0, 0)
            };

            Button MakeButton(
                string label,
                MessageBoxResult buttonResult,
                bool isDefault,
                bool isCancel)
            {
                var button = new Button
                {
                    Content = label,
                    MinWidth = 94,
                    Height = 34,
                    Margin = new Thickness(8, 0, 0, 0),
                    Padding = new Thickness(12, 4, 12, 4),
                    IsDefault = isDefault,
                    IsCancel = isCancel
                };

                ApplyWebPrivacyButtonTheme(button);

                button.Click += (_, __) =>
                {
                    result = buttonResult;
                    dialog.Close();
                };

                return button;
            }

            switch (buttons)
            {
                case MessageBoxButton.OKCancel:
                    buttonPanel.Children.Add(
                        MakeButton(
                            "OK",
                            MessageBoxResult.OK,
                            isDefault: true,
                            isCancel: false));

                    buttonPanel.Children.Add(
                        MakeButton(
                            "Cancel",
                            MessageBoxResult.Cancel,
                            isDefault: false,
                            isCancel: true));
                    break;

                case MessageBoxButton.YesNo:
                    buttonPanel.Children.Add(
                        MakeButton(
                            "Yes",
                            MessageBoxResult.Yes,
                            isDefault: true,
                            isCancel: false));

                    buttonPanel.Children.Add(
                        MakeButton(
                            "No",
                            MessageBoxResult.No,
                            isDefault: false,
                            isCancel: true));
                    break;

                case MessageBoxButton.YesNoCancel:
                    buttonPanel.Children.Add(
                        MakeButton(
                            "Yes",
                            MessageBoxResult.Yes,
                            isDefault: true,
                            isCancel: false));

                    buttonPanel.Children.Add(
                        MakeButton(
                            "No",
                            MessageBoxResult.No,
                            isDefault: false,
                            isCancel: false));

                    buttonPanel.Children.Add(
                        MakeButton(
                            "Cancel",
                            MessageBoxResult.Cancel,
                            isDefault: false,
                            isCancel: true));
                    break;

                case MessageBoxButton.OK:
                default:
                    buttonPanel.Children.Add(
                        MakeButton(
                            "OK",
                            MessageBoxResult.OK,
                            isDefault: true,
                            isCancel: true));
                    break;
            }

            Grid.SetRow(
                buttonPanel,
                1);

            root.Children.Add(contentGrid);
            root.Children.Add(buttonPanel);

            outer.Child = root;
            dialog.Content = outer;

            dialog.Closing += (_, __) =>
            {
                if (result != MessageBoxResult.None)
                    return;

                result =
                    buttons switch
                    {
                        MessageBoxButton.OK =>
                            MessageBoxResult.OK,

                        MessageBoxButton.YesNo =>
                            MessageBoxResult.No,

                        _ =>
                            MessageBoxResult.Cancel
                    };
            };

            dialog.ShowDialog();

            return result;
        }

        private void ApplyWebPrivacyContextMenuTheme(ContextMenu menu)
        {
            if (menu == null)
                return;

            Brush background =
                TryFindResource("CardBg") as Brush ?? Brushes.White;

            Brush foreground =
                TryFindResource("TextPrimary") as Brush ?? Brushes.Black;

            Brush border =
                TryFindResource("CardBorder") as Brush ?? Brushes.Gray;

            Brush hover =
                TryFindResource("ButtonHoverBg") as Brush ?? Brushes.LightGray;

            menu.Background = background;
            menu.Foreground = foreground;
            menu.BorderBrush = border;
            menu.BorderThickness = new Thickness(1);
            menu.Padding = new Thickness(4);

            // The stock WPF MenuItem template still consults Windows system
            // colours. Override those resources inside this menu so Light/Dark
            // follows LexDesk Pro instead.
            menu.Resources[SystemColors.MenuBrushKey] = background;
            menu.Resources[SystemColors.MenuTextBrushKey] = foreground;
            menu.Resources[SystemColors.HighlightBrushKey] = hover;
            menu.Resources[SystemColors.HighlightTextBrushKey] = foreground;

            var menuItemStyle = new Style(typeof(MenuItem));

            menuItemStyle.Setters.Add(
                new Setter(Control.ForegroundProperty, foreground));

            menuItemStyle.Setters.Add(
                new Setter(Control.BackgroundProperty, Brushes.Transparent));

            menuItemStyle.Setters.Add(
                new Setter(Control.PaddingProperty, new Thickness(10, 5, 10, 5)));

            // Submenus are rendered inside their own WPF Popup.
            // Give every MenuItem the same theme resources so nested
            // Open / Delete menus do not fall back to Windows colours.
            menu.Resources[SystemColors.MenuBrushKey] = background;
            menu.Resources[SystemColors.MenuTextBrushKey] = foreground;
            menu.Resources[SystemColors.HighlightBrushKey] = hover;
            menu.Resources[SystemColors.HighlightTextBrushKey] = foreground;

            // Nested WPF MenuItem submenus are rendered in a separate Popup.
            // They can lose the ContextMenu's local resources, so also provide
            // the current LexDesk Pro menu colours at application level.
            if (Application.Current != null)
            {
                Application.Current.Resources[SystemColors.MenuBrushKey] = background;
                Application.Current.Resources[SystemColors.MenuTextBrushKey] = foreground;
                Application.Current.Resources[SystemColors.HighlightBrushKey] = hover;
                Application.Current.Resources[SystemColors.HighlightTextBrushKey] = foreground;
            }


            menu.Resources[typeof(MenuItem)] = menuItemStyle;
        }

        private void ApplyWebPrivacyButtonTheme(Button button)
        {
            if (button == null) return;

            if (TryFindResource("TopBarButtonStyle") is Style style)
                button.Style = style;

            // Dialog buttons still need keyboard focus/default behaviour.
            button.Focusable = true;
            button.SetResourceReference(Control.ForegroundProperty, "TextPrimary");
        }

        private void ApplyWebPrivacyTextBoxTheme(TextBox box)
        {
            if (box == null) return;
            box.SetResourceReference(Control.BackgroundProperty, "InputBg");
            box.SetResourceReference(Control.ForegroundProperty, "TextPrimary");
            box.SetResourceReference(Control.BorderBrushProperty, "ButtonBorder");
            box.CaretBrush = TryFindResource("TextPrimary") as Brush ?? Brushes.Black;
        }

        private void ShowWebPrivacyMessage(
    string title,
    string message,
    double width = 560,
    double height = 320)
        {
            var dialog = new Window
            {
                Title = title,
                Owner = this,
                Width = width,
                Height = height,
                ResizeMode = ResizeMode.NoResize,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                ShowInTaskbar = false
            };

            ApplyWebPrivacyDialogTheme(dialog);

            var outer = new Border
            {
                Margin = new Thickness(16),
                Padding = new Thickness(20),
                CornerRadius = new CornerRadius(12),
                BorderThickness = new Thickness(1)
            };

            outer.SetResourceReference(
                Border.BackgroundProperty,
                "CardBg");

            outer.SetResourceReference(
                Border.BorderBrushProperty,
                "CardBorder");

            var root = new Grid();

            root.RowDefinitions.Add(
                new RowDefinition
                {
                    Height = new GridLength(1, GridUnitType.Star)
                });

            root.RowDefinitions.Add(
                new RowDefinition
                {
                    Height = GridLength.Auto
                });

            var text = new TextBlock
            {
                Text = message,
                TextWrapping = TextWrapping.Wrap,
                FontSize = 13,
                LineHeight = 20
            };

            text.SetResourceReference(
                TextBlock.ForegroundProperty,
                "TextPrimary");

            var scroll = new ScrollViewer
            {
                Content = text,
                VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
                HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled
            };

            Grid.SetRow(scroll, 0);

            var okButton = new Button
            {
                Content = "OK",
                Width = 90,
                Height = 34,
                HorizontalAlignment = HorizontalAlignment.Right,
                Margin = new Thickness(0, 16, 0, 0),
                IsDefault = true,
                IsCancel = true
            };

            ApplyWebPrivacyButtonTheme(okButton);

            okButton.Click += (_, __) => dialog.Close();

            Grid.SetRow(okButton, 1);

            root.Children.Add(scroll);
            root.Children.Add(okButton);

            outer.Child = root;
            dialog.Content = outer;

            dialog.ShowDialog();
        }

