            };

            text.SetResourceReference(
                TextBlock.ForegroundProperty,
                "TextPrimary");

            var scroll = new ScrollViewer
            {
                Content = text,
                VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
                HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled
            };

            Grid.SetRow(scroll, 0);

            var buttons = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                HorizontalAlignment = HorizontalAlignment.Right,
                Margin = new Thickness(0, 16, 0, 0)
            };

            var cancelButton = new Button
            {
                Content = cancelText,
                Width = 100,
                Height = 34,
                Margin = new Thickness(0, 0, 10, 0),
                IsCancel = true
            };

            ApplyWebPrivacyButtonTheme(cancelButton);

            cancelButton.Click += (_, __) =>
            {
                confirmed = false;
                dialog.Close();
            };

            var confirmButton = new Button
            {
                Content = confirmText,
                Width = 110,
                Height = 34,
                IsDefault = true
            };

            ApplyWebPrivacyButtonTheme(confirmButton);

            confirmButton.Click += (_, __) =>
            {
                confirmed = true;
                dialog.Close();
            };

            buttons.Children.Add(cancelButton);
            buttons.Children.Add(confirmButton);

            Grid.SetRow(buttons, 1);

            root.Children.Add(scroll);
            root.Children.Add(buttons);

            outer.Child = root;
            dialog.Content = outer;

            dialog.ShowDialog();

            return confirmed;
        }

        private string? ShowSupportInputDialog()
        {
            var dialog = new Window
            {
                Title = "Contact Support",
                Width = 520,
                Height = 360,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                ResizeMode = ResizeMode.NoResize,
                Owner = this
            };

            ApplyWebPrivacyDialogTheme(dialog);

            var root = new Grid
            {
                Margin = new Thickness(16)
            };
            root.SetResourceReference(Panel.BackgroundProperty, "CardBg");

            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            var intro = new TextBlock
            {
                Text = "Describe the issue or question for support:",
                Margin = new Thickness(0, 0, 0, 10),
                TextWrapping = TextWrapping.Wrap,
                FontSize = 14
            };
            intro.SetResourceReference(TextBlock.ForegroundProperty, "TextPrimary");
            Grid.SetRow(intro, 0);

            var inputBox = new TextBox
            {
                AcceptsReturn = true,
                VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
                TextWrapping = TextWrapping.Wrap,
                FontSize = 14,
                MinHeight = 180,
                Padding = new Thickness(8)
            };
            ApplyWebPrivacyTextBoxTheme(inputBox);
            Grid.SetRow(inputBox, 1);

            var buttonsPanel = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                HorizontalAlignment = HorizontalAlignment.Right,
                Margin = new Thickness(0, 12, 0, 0)
            };
            Grid.SetRow(buttonsPanel, 2);

            var cancelButton = new Button
            {
                Content = "Cancel",
                Width = 90,
                Height = 34,
                Margin = new Thickness(0, 0, 10, 0)
            };

            var sendButton = new Button
            {
                Content = "Continue",
                Width = 90,
                Height = 34,
                IsDefault = true
            };

            ApplyWebPrivacyButtonTheme(cancelButton);
            ApplyWebPrivacyButtonTheme(sendButton);

            cancelButton.Click += (_, __) =>
            {
                dialog.DialogResult = false;
                dialog.Close();
            };

            sendButton.Click += (_, __) =>
            {
                dialog.DialogResult = true;
                dialog.Close();
            };

            buttonsPanel.Children.Add(cancelButton);
            buttonsPanel.Children.Add(sendButton);

            root.Children.Add(intro);
            root.Children.Add(inputBox);
            root.Children.Add(buttonsPanel);

            dialog.Content = root;

            bool? result = dialog.ShowDialog();
            if (result == true)
                return inputBox.Text?.Trim();

            return null;
        }

        private void BackupKnownFile(string sourcePath, string backupFileName)
        {
            try
            {
                Directory.CreateDirectory(_backupFolderPath);

                string backupPath = Path.Combine(_backupFolderPath, backupFileName);

                if (File.Exists(sourcePath))
                    File.Copy(sourcePath, backupPath, true);
                else if (File.Exists(backupPath))
                    File.Delete(backupPath);
            }
            catch { }
        }

        private void RestoreKnownFile(string backupFileName, string destinationPath)
        {
            try
            {
                string backupPath = Path.Combine(_backupFolderPath, backupFileName);

                if (File.Exists(backupPath))
                {
                    Directory.CreateDirectory(Path.GetDirectoryName(destinationPath)!);
                    File.Copy(backupPath, destinationPath, true);
                }
            }
            catch { }
        }

        private void DeleteIfExists(string path)
        {
            try
            {
                if (File.Exists(path))
                    File.Delete(path);
            }
            catch { }
        }

        private void RestartAppAndExit()
        {
            try
            {
                SaveSessionState();

                var psi = new ProcessStartInfo
                {
                    FileName = Process.GetCurrentProcess().MainModule!.FileName!,
                    UseShellExecute = true
                };

                Process.Start(psi);
                Application.Current.Shutdown();
            }
            catch
            {
                ShowLexDeskMessageBox(
                    "Please close and reopen LexDesk Pro manually.",
                    "Restart Required",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

