        private void Whitelist_Remove_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                if (WhitelistEditor == null)
                    return;

                string selectedText = WhitelistEditor.SelectedText?.Trim() ?? "";
                string currentLine = "";

                if (string.IsNullOrWhiteSpace(selectedText))
                {
                    int caret = WhitelistEditor.CaretIndex;
                    string fullText = WhitelistEditor.Text ?? "";
                    var lines = fullText.Split(new[] { "\r\n", "\n" }, StringSplitOptions.None);

                    int running = 0;
                    foreach (var line in lines)
                    {
                        int lineStart = running;
                        int lineEnd = running + line.Length;

                        if (caret >= lineStart && caret <= lineEnd)
                        {
                            currentLine = line.Trim();
                            break;
                        }

                        running = lineEnd + Environment.NewLine.Length;
                    }
                }
                else
                {
                    currentLine = selectedText;
                }

                if (string.IsNullOrWhiteSpace(currentLine))
                {
                    ShowLexDeskMessageBox(
    "Select an Allow List entry, or place the cursor on the line you want to remove.",
    "Allow List",
    MessageBoxButton.OK,
    MessageBoxImage.Information);
                    return;
                }

                if (_adBlockWhitelist.Remove(currentLine))
                {
                    SaveWhitelist();

                    if (WhitelistEditor != null)
                        WhitelistEditor.Text = string.Join(Environment.NewLine, _adBlockWhitelist);

                    ShowLexDeskMessageBox(
    $"{currentLine} removed from the Allow List.",
    "Allow List",
    MessageBoxButton.OK,
    MessageBoxImage.Information);
                }
                else
                {
                    ShowLexDeskMessageBox(
     "That site was not found in the Allow List.",
     "Allow List",
     MessageBoxButton.OK,
     MessageBoxImage.Information);
                }
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
$"Could not remove site:\n{SanitizeExceptionMessage(ex)}",
"Allow List",
MessageBoxButton.OK,
MessageBoxImage.Warning);
            }
        }

        private async void LicenseActivateButton_Click(object sender, RoutedEventArgs e)
        {
            if (!LexDeskLicensingEnabled)
            {
                _isLicensed = true;
                _licenseStatusText = "LexDesk Pro ready";
                UpdateLicenseUi();

                ShowLexDeskMessageBox(
                    "LexDesk Pro is ready to use.\n\nThis build does not require activation.",
                    "LexDesk Pro",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);

                return;
            }

            try
            {
                var rawKey = LicenseKeyBox?.Text ?? "";
                var normalized = NormalizeLicenseKey(rawKey);

                if (string.IsNullOrWhiteSpace(normalized))
                {
                    ShowLexDeskMessageBox(
                        "Please enter a license key.",
                        "License Key",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                    return;
                }

                LicenseActivateButton.IsEnabled = false;
                LicenseActivateButton.Content = "Checking...";

                var result = await ValidateLicenseAsync(normalized);

                if (result.IsValid)
                {
                    _isLicensed = true;
                    _licenseStatusText = result.StatusText;

                    if (!string.IsNullOrWhiteSpace(result.LicenseHashToSave))
                        SaveLicenseState(result.LicenseHashToSave);

                    UpdateLicenseUi();

                    ShowLexDeskMessageBox(
    result.StatusText,
    "License Key",
    MessageBoxButton.OK,
    MessageBoxImage.Information);
                }
                else
                {
                    _isLicensed = false;
                    _licenseStatusText = result.StatusText;
                    UpdateLicenseUi();

                    ShowLexDeskMessageBox(
                        result.StatusText,
                        "License Key",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);
                }
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
    $"License activation failed:\n{SanitizeExceptionMessage(ex)}",
    "License Key",
    MessageBoxButton.OK,
    MessageBoxImage.Warning);
            }
            finally
            {
                if (LicenseKeyBox != null)
                    LicenseKeyBox.Text = "";

                UpdateLicenseUi();
            }
        }

        private async void LicenseClearButton_Click(object sender, RoutedEventArgs e)
        {
            if (!LexDeskLicensingEnabled)
            {
                _isLicensed = true;
                _licenseStatusText = "LexDesk Pro ready";
                UpdateLicenseUi();
                return;
            }

            var result = ShowLexDeskMessageBox(
                "Deactivate LexDesk Pro on this PC and free its licence device slot?\n\nAn internet connection is required.",
                "License Key",
                MessageBoxButton.YesNo,
                MessageBoxImage.Question);

            if (result != MessageBoxResult.Yes)
                return;

            if (LicenseClearButton != null)
                LicenseClearButton.IsEnabled = false;

            try
            {
                LicenseValidationResult deactivation = await DeactivateSavedLicenseAsync();

                string status = (deactivation.Status ?? "").Trim().ToLowerInvariant();
                bool serverReleased = deactivation.IsValid && status == "deactivated";
                bool noServerRegistration = status == "device_not_found" || status == "invalid";

                if (!serverReleased && !noServerRegistration)
                {
                    _licenseStatusText = "Activated";
                    UpdateLicenseUi();

                    ShowLexDeskMessageBox(
                        (deactivation.Message ?? "Unable to deactivate this device.") +
                        "\n\nYour saved licence has not been removed.",
                        "License Key",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);
                    return;
                }

                _isLicensed = false;
                _licenseStatusText = "Not activated";
                ClearLicenseState();
                UpdateLicenseUi();

                ShowLexDeskMessageBox(
                    serverReleased
                        ? "LexDesk Pro has been deactivated on this PC and the licence device slot has been released."
                        : "No server device registration remained. The saved licence has been removed from this PC.",
                    "License Key",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
            catch
            {
                _licenseStatusText = "Activated";
                UpdateLicenseUi();

                ShowLexDeskMessageBox(
                    "Unable to deactivate this device.\n\nYour saved licence has not been removed.",
                    "License Key",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                UpdateLicenseUi();
            }
        }

