        private void FactoryResetButton_Click(object sender, RoutedEventArgs e)
        {

            if (!HasFullUnlock())
            {
                ShowLexDeskMessageBox(
                    "Please activate LexDesk Pro to use this feature.",
                    "Activation Required",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            try
            {
                var result = ShowLexDeskMessageBox(
                    "Factory reset LexDesk Pro?\n\nThis will clear your saved settings, quick URLs, bookmarks, and session, then restart the app.\n\nActivation will be kept.",
                    "Factory Reset",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Warning);

                if (result != MessageBoxResult.Yes)
                    return;

                DeleteIfExists(_presetUrlsPath);
                DeleteIfExists(_homeUrlPath);
                DeleteIfExists(_whitelistPath);
                DeleteIfExists(_privacyPath);
                DeleteIfExists(_dnsModePath);
                DeleteIfExists(_dnsPresetPath);
                DeleteIfExists(_searchEnginePath);
                DeleteIfExists(_searchRegionPath);
                DeleteIfExists(_popupModePath);
                DeleteIfExists(_popupWhitelistPath);

                // Keep activation during Factory Reset.
                // Users can still remove activation manually with Clear Saved License.
                DeleteIfExists(_sessionPath);
                DeleteIfExists(_bookmarksPath);
                DeleteIfExists(_toolbarPreferencesPath);
                DeleteIfExists(_appearanceThemePath);
                DeleteIfExists(_sitePermissionsPath);
                DeleteIfExists(_memorySaverPath);
                DeleteIfExists(_siteZoomPath);

                ShowLexDeskMessageBox(
                    "Factory reset complete.\n\nLexDesk Pro will now restart.",
                    "Factory Reset",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);

                RestartAppAndExit();
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
     $"Factory reset failed:\n{SanitizeExceptionMessage(ex)}",
     "Factory Reset",
     MessageBoxButton.OK,
     MessageBoxImage.Warning);
            }
        }

