        private AppTheme LoadAppearanceThemeSetting()
        {
            try
            {
                if (!File.Exists(_appearanceThemePath))
                    return AppTheme.Light;

                string txt = (File.ReadAllText(_appearanceThemePath) ?? "").Trim();

                if (Enum.TryParse(txt, true, out AppTheme savedTheme) &&
    Enum.IsDefined(typeof(AppTheme), savedTheme))
                {
                    return savedTheme;
                }
            }
            catch
            {
                // Appearance loading must never stop the browser.
            }

            return AppTheme.Light;
        }

        private void SaveAppearanceThemeSetting()
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_appearanceThemePath)!);

                AppTheme theme =
    Enum.IsDefined(typeof(AppTheme), _themeIndex)
        ? (AppTheme)_themeIndex
        : AppTheme.Light;

                File.WriteAllText(_appearanceThemePath, theme.ToString());
            }
            catch
            {
                // Appearance saving must never affect browsing.
            }
        }

        private void SetAppearanceTheme(AppTheme theme, bool reloadVisiblePages = true)
        {
            if (theme != AppTheme.Light &&
    theme != AppTheme.Dark &&
    theme != AppTheme.Sand &&
    theme != AppTheme.NeonBlue)
            {
                theme = AppTheme.Light;
            }

            _themeIndex = (int)theme;

            ApplyTheme(theme);
            UpdateThemesButtonLabel(theme);
            UpdateAppearanceThemeButtons();
            SaveAppearanceThemeSetting();

            UpdatePageHostBorders();
            UpdatePageModeButtonVisuals();
            UpdateWorkspaceTabVisuals();

            ApplyWebViewThemePreference();

            if (reloadVisiblePages)
                ReloadVisibleWebViewsAfterThemeChange();

            UpdateDnsModeUi();
            UpdateDnsUI();
            UpdateSearchEngineUI();
            UpdateSmartModeUI();
            UpdatePopupModeUI();
            UpdateLicenseUi();
            UpdatePrivacyButtonLabel();
            UpdatePrivacyDropdownVisuals();
            UpdateAutoStartButtonLabel();
            UpdateStartupScreenButtonLabel();
            UpdateCleanSearchButtonLabel();
            UpdateProtectionWarningStyleButtons();
            RefreshCompatibilityButtonVisual();
        }

        private void UpdateAppearanceThemeButtons()
        {
            try
            {
                bool light = _themeIndex == (int)AppTheme.Light;
                bool dark = _themeIndex == (int)AppTheme.Dark;
                bool sand = _themeIndex == (int)AppTheme.Sand;
                bool neonBlue = _themeIndex == (int)AppTheme.NeonBlue;

                Brush normalBg =
                    TryFindResource("ButtonBg") as Brush
                    ?? Brushes.Transparent;

                Brush selectedBg =
                    TryFindResource("ButtonPressedBg") as Brush
                    ?? Brushes.LightGray;

                Brush normalBorder =
                    TryFindResource("ButtonBorder") as Brush
                    ?? Brushes.Gray;

                Brush selectedBorder =
                    TryFindResource("SelectedButtonBorder") as Brush
                    ?? Brushes.DodgerBlue;

                if (AppearanceLightButton != null)
                {
                    AppearanceLightButton.Background = light ? selectedBg : normalBg;
                    AppearanceLightButton.BorderBrush = light ? selectedBorder : normalBorder;
                    AppearanceLightButton.BorderThickness = light
                        ? new Thickness(1.6)
                        : new Thickness(1);
                    AppearanceLightButton.FontWeight = light
                        ? FontWeights.SemiBold
                        : FontWeights.Normal;
                }

                if (AppearanceDarkButton != null)
                {
                    AppearanceDarkButton.Background = dark ? selectedBg : normalBg;
                    AppearanceDarkButton.BorderBrush = dark ? selectedBorder : normalBorder;
                    AppearanceDarkButton.BorderThickness = dark
                        ? new Thickness(1.6)
                        : new Thickness(1);
                    AppearanceDarkButton.FontWeight = dark
                        ? FontWeights.SemiBold
                        : FontWeights.Normal;
                }

                if (AppearanceSandButton != null)
                {
                    AppearanceSandButton.Background = sand ? selectedBg : normalBg;
                    AppearanceSandButton.BorderBrush = sand ? selectedBorder : normalBorder;
                    AppearanceSandButton.BorderThickness = sand
                        ? new Thickness(1.6)
                        : new Thickness(1);
                    AppearanceSandButton.FontWeight = sand
                        ? FontWeights.SemiBold
                        : FontWeights.Normal;
                }

                if (AppearanceNeonBlueButton != null)
                {
                    AppearanceNeonBlueButton.Background = neonBlue ? selectedBg : normalBg;
                    AppearanceNeonBlueButton.BorderBrush = neonBlue ? selectedBorder : normalBorder;
                    AppearanceNeonBlueButton.BorderThickness = neonBlue
                        ? new Thickness(1.6)
                        : new Thickness(1);
                    AppearanceNeonBlueButton.FontWeight = neonBlue
                        ? FontWeights.SemiBold
                        : FontWeights.Normal;
                }

                if (AppearanceCurrentText != null)
                {
                    AppearanceCurrentText.Text = light
                        ? "Current: Light"
                        : dark
                            ? "Current: Dark"
                            : sand
                                ? "Current: Sand"
                                : "Current: Neon Blue";
                }
            }
            catch
            {
                // Appearance button highlighting must never affect the app.
            }
        }

