        private void StudioButton_Click(object sender, RoutedEventArgs e)
        {
            if (GuardLocked()) return;

            int pane = _activePageIndex;
            int maxSlots = HasFullUnlock() ? 20 : 6;

            if (maxSlots > _presetUrls.Length)
                maxSlots = _presetUrls.Length;

            // Start from Quick URL 1 on first use for this web page.
            int lastSlot = _studioSlotIndex[pane];

            if (lastSlot < -1 || lastSlot >= maxSlots)
                lastSlot = -1;

            int nextSlot = lastSlot + 1;

            if (nextSlot >= maxSlots)
                nextSlot = 0;

            int selectedSlot = -1;

            // Look forward through Quick URLs, skipping empty ones.
            for (int attempts = 0; attempts < maxSlots; attempts++)
            {
                if (!string.IsNullOrWhiteSpace(_presetUrls[nextSlot]))
                {
                    selectedSlot = nextSlot;
                    break;
                }

                nextSlot++;

                if (nextSlot >= maxSlots)
                    nextSlot = 0;
            }

            if (selectedSlot < 0)
            {
                UpdateSecurityStatus("No Quick URLs saved", true);
                ShowLexDeskMessageBox(
                    "No Quick URLs are saved yet.\n\nOpen Settings and set Quick URL 1 first.",
                    "Cycle Web Pages",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            _studioSlotIndex[pane] = selectedSlot;

            LoadQuickUrlSlotIntoActivePane(selectedSlot);

            if (studioButton != null)
                studioButton.ToolTip = $"Cycle Web Pages: Quick URL {selectedSlot + 1}";
        }

        private void StudioButton_PreviewMouseRightButtonUp(object sender, MouseButtonEventArgs e)
        {
            e.Handled = true;
            ShowQuickUrlMenuFromStudioButton();
        }

        private void ShowQuickUrlMenuFromStudioButton()
        {
            var menu = new ContextMenu
            {
                PlacementTarget = studioButton,
                Placement = PlacementMode.Bottom,
                StaysOpen = false
            };

            ApplyWebPrivacyContextMenuTheme(menu);

            int maxSlots = HasFullUnlock() ? 20 : 6;

            if (maxSlots > _presetUrls.Length)
                maxSlots = _presetUrls.Length;

            bool hasAnySaved = false;

            var title = new MenuItem
            {
                Header = "Quick URLs",
                IsEnabled = false
            };

            menu.Items.Add(title);
            menu.Items.Add(new Separator());

            for (int i = 0; i < maxSlots; i++)
            {
                string url = _presetUrls[i];

                if (string.IsNullOrWhiteSpace(url))
                    continue;

                hasAnySaved = true;

                int slot = i;
                string label = BuildQuickUrlMenuLabel(slot, url);

                var item = new MenuItem
                {
                    Header = label,
                    ToolTip = url
                };

                item.Click += (_, __) =>
                {
                    _studioSlotIndex[_activePageIndex] = slot;
                    LoadQuickUrlSlotIntoActivePane(slot);

                    if (studioButton != null)
                        studioButton.ToolTip = $"Page Cycle: Quick URL {slot + 1}";
                };

                menu.Items.Add(item);
            }

            if (!hasAnySaved)
            {
                menu.Items.Add(new MenuItem
                {
                    Header = "No Quick URLs saved",
                    IsEnabled = false
                });

                menu.Items.Add(new Separator());

                var settings = new MenuItem
                {
                    Header = "Open Settings"
                };

                settings.Click += (_, __) =>
                {
                    SettingsButton_Click(this, new RoutedEventArgs());
                };

                menu.Items.Add(settings);
            }

            menu.IsOpen = true;
        }

        private string BuildQuickUrlMenuLabel(int slot, string url)
        {
            string fallback = $"Quick URL {slot + 1}";

            try
            {
                if (string.IsNullOrWhiteSpace(url))
                    return $"{fallback} — empty";

                var uri = new Uri(url);

                string host = uri.Host
                    .Replace("www.", "", StringComparison.OrdinalIgnoreCase)
                    .Trim();

                if (string.IsNullOrWhiteSpace(host))
                    return $"{fallback} — {url}";

                string name = host
                    .Replace(".com.au", "", StringComparison.OrdinalIgnoreCase)
                    .Replace(".com", "", StringComparison.OrdinalIgnoreCase)
                    .Replace(".net", "", StringComparison.OrdinalIgnoreCase)
                    .Replace(".org", "", StringComparison.OrdinalIgnoreCase)
                    .Replace(".co.uk", "", StringComparison.OrdinalIgnoreCase);

                if (!string.IsNullOrWhiteSpace(name))
                    name = char.ToUpper(name[0]) + name.Substring(1);

                return $"{fallback} — {(string.IsNullOrWhiteSpace(name) ? host : name)}";
            }
            catch
            {
                return $"{fallback} — {url}";
            }
        }

        private string GetQuickUrlMenuLabel(int slot)
        {
            if (slot < 0 || slot >= _presetUrls.Length)
                return "(invalid)";

            string url = _presetUrls[slot];

            if (string.IsNullOrWhiteSpace(url))
                return "(empty)";

            try
            {
                var uri = new Uri(NormalizeWorkspaceUrl(url));
                string host = uri.Host.Replace("www.", "");

                string name = host
                    .Replace(".com.au", "", StringComparison.OrdinalIgnoreCase)
                    .Replace(".com", "", StringComparison.OrdinalIgnoreCase)
                    .Replace(".net", "", StringComparison.OrdinalIgnoreCase)
                    .Replace(".org", "", StringComparison.OrdinalIgnoreCase)
                    .Replace(".co.uk", "", StringComparison.OrdinalIgnoreCase);

                if (!string.IsNullOrWhiteSpace(name))
                    name = char.ToUpper(name[0]) + name.Substring(1);

                return string.IsNullOrWhiteSpace(name) ? host : name;
            }
            catch
            {
                return url;
            }
        }

        private bool CanUseQuickUrlSlot(int slot, string action)
        {
            if (slot < 0 || slot >= _presetUrls.Length)
                return false;

            if (!HasFullUnlock() && slot >= 6)
            {
                ShowLexDeskMessageBox(
                    $"Please activate LexDesk Pro to use Quick URLs 7–20.",
                    "Activation Required",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);

                return false;
            }

            return true;
        }

        private void OpenQuickUrlSlotFromMenu(int slot)
        {
            if (!CanUseQuickUrlSlot(slot, "Opening"))
                return;

            string url = _presetUrls[slot];

            if (string.IsNullOrWhiteSpace(url))
            {
                ShowLexDeskMessageBox(
                    $"Quick URL {slot + 1} is empty.",
                    "Quick URL",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);

                return;
            }

            CloseSettingsOverlayForNavigation();

            if (PrivacyDropdown != null)
                PrivacyDropdown.IsOpen = false;

            if (StatusPopup != null)
                StatusPopup.IsOpen = false;

            if (WebActionsDropdown != null)
                WebActionsDropdown.IsOpen = false;

            _studioSlotIndex[_activePageIndex] = slot;

            LoadQuickUrlSlotIntoActivePane(slot);

            if (studioButton != null)
                studioButton.ToolTip = $"Cycle Web Pages: Quick URL {slot + 1}";
        }

        private void SetQuickUrlSlotFromMenu(int slot)
        {
            if (!CanUseQuickUrlSlot(slot, "Editing"))
                return;

            string defaultUrl = _presetUrls[slot];

            if (string.IsNullOrWhiteSpace(defaultUrl))
                defaultUrl = GetActivePaneRealUrl();

            string url = ShowQuickUrlInputDialog(
                $"Quick URL {slot + 1}",
                defaultUrl ?? "");

            url = (url ?? "").Trim();

            if (string.IsNullOrWhiteSpace(url))
                return;

            url = NormalizeWorkspaceUrl(url);

            _presetUrls[slot] = url;

            SavePresetUrls();
            RefreshPresetButtonsUI();
            SyncQuickUrlSlotToWorkspace(slot);

            UpdateSecurityStatus($"Quick URL {slot + 1} saved", false);
        }

        private string ShowQuickUrlInputDialog(
            string title,
            string currentValue)
        {
            string result = currentValue ?? "";

            var dialog = new Window
            {
                Title = "Set Quick URL",
                Owner = this,
                Width = 560,
                Height = 230,
                ResizeMode = ResizeMode.NoResize,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                ShowInTaskbar = false
            };

            ApplyWebPrivacyDialogTheme(dialog);

            var outer = new Border
            {
                Margin = new Thickness(16),
                Padding = new Thickness(20),
                CornerRadius = new CornerRadius(12),
                BorderThickness = new Thickness(1)
            };

            outer.SetResourceReference(
                Border.BackgroundProperty,
                "CardBg");

            outer.SetResourceReference(
                Border.BorderBrushProperty,
                "CardBorder");

            var root = new Grid();

            root.RowDefinitions.Add(
                new RowDefinition { Height = GridLength.Auto });

            root.RowDefinitions.Add(
                new RowDefinition { Height = GridLength.Auto });

            root.RowDefinitions.Add(
                new RowDefinition { Height = GridLength.Auto });

            var heading = new TextBlock
            {
                Text = title,
                FontSize = 16,
                FontWeight = FontWeights.SemiBold,
                Margin = new Thickness(0, 0, 0, 6)
            };

            heading.SetResourceReference(
                TextBlock.ForegroundProperty,
                "TextPrimary");

            Grid.SetRow(heading, 0);

            var description = new TextBlock
            {
                Text = "Enter the website address you want saved in this shortcut.",
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(0, 0, 0, 12)
            };

            description.SetResourceReference(
                TextBlock.ForegroundProperty,
                "TextSecondary");

            Grid.SetRow(description, 1);

            var bottom = new Grid();

            bottom.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = new GridLength(1, GridUnitType.Star)
                });

            bottom.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = GridLength.Auto
                });

            bottom.ColumnDefinitions.Add(
                new ColumnDefinition
                {
                    Width = GridLength.Auto
                });

            var input = new TextBox
            {
                Text = currentValue ?? "",
                Height = 34,
                Margin = new Thickness(0, 0, 10, 0),
                VerticalContentAlignment = VerticalAlignment.Center,
                Padding = new Thickness(8, 3, 8, 3)
            };

            ApplyWebPrivacyTextBoxTheme(input);

            Grid.SetColumn(input, 0);

            var cancel = new Button
            {
                Content = "Cancel",
                Width = 82,
                Height = 34,
                Margin = new Thickness(0, 0, 8, 0),
                IsCancel = true
            };

            ApplyWebPrivacyButtonTheme(cancel);

            Grid.SetColumn(cancel, 1);

            var save = new Button
            {
                Content = "Save",
                Width = 82,
                Height = 34,
                IsDefault = true
            };

            ApplyWebPrivacyButtonTheme(save);

            save.Click += (_, __) =>
            {
                result = input.Text ?? "";
                dialog.DialogResult = true;
            };

            Grid.SetColumn(save, 2);

            bottom.Children.Add(input);
            bottom.Children.Add(cancel);
            bottom.Children.Add(save);

            Grid.SetRow(bottom, 2);

            root.Children.Add(heading);
            root.Children.Add(description);
            root.Children.Add(bottom);

            outer.Child = root;
            dialog.Content = outer;

            dialog.Loaded += (_, __) =>
            {
                input.Focus();
                input.SelectAll();
            };

            bool? accepted = dialog.ShowDialog();

            return accepted == true
                ? result.Trim()
                : "";
        }

        private void ClearQuickUrlSlotFromMenu(int slot)
        {
            if (!CanUseQuickUrlSlot(slot, "Clearing"))
                return;

            var result = ShowLexDeskMessageBox(
                $"Clear Quick URL {slot + 1}?",
                "Clear Quick URL",
                MessageBoxButton.YesNo,
                MessageBoxImage.Question);

            if (result != MessageBoxResult.Yes)
                return;

            _presetUrls[slot] = "";

            SavePresetUrls();
            RefreshPresetButtonsUI();
            SyncQuickUrlSlotToWorkspace(slot);

            UpdateSecurityStatus($"Quick URL {slot + 1} cleared", false);
        }

        private void SyncQuickUrlSlotToWorkspace(int slot)
        {
            int workspaceIndex = slot / 4;
            int paneIndex = slot % 4;

            if (workspaceIndex < 0 || workspaceIndex >= _workspaces.Count)
                return;

            if (paneIndex < 0 || paneIndex >= 4)
                return;

            string url = NormalizeWorkspaceUrl(_presetUrls[slot]);

            if (string.IsNullOrWhiteSpace(url))
                url = paneIndex == 0 ? "lexwhite://newtab" : "about:blank";

            _workspaces[workspaceIndex].PageUrls[paneIndex] = url;

            if (workspaceIndex == _activeWorkspaceTabIndex)
                _pageUrls[paneIndex] = url;
        }

        private int GetCurrentQuickUrlSlot(int paneIndex)
        {
            var current = _pageUrls[paneIndex];

            if (string.IsNullOrWhiteSpace(current))
                return 1;

            try
            {
                var currentUri = new Uri(current);
                string currentHost = currentUri.Host.Replace("www.", "");

                for (int i = 0; i < _presetUrls.Count(); i++)
                {
                    var preset = _presetUrls[i];

                    if (string.IsNullOrWhiteSpace(preset))
                        continue;

                    var presetUri = new Uri(preset);
                    string presetHost = presetUri.Host.Replace("www.", "");

                    if (string.Equals(currentHost, presetHost, StringComparison.OrdinalIgnoreCase))
                        return i + 1;
                }
            }
            catch
            {
                // fallback if URL parsing fails
            }

            return 1;
        }

