        private void WebAction_ViewBookmarks_Click(object sender, RoutedEventArgs e)
        {
            if (_bookmarks.Count == 0)
            {
                ShowWebPrivacyMessage(
                    "Favourites",
                    "No favourites saved yet.",
                    500,
                    240);

                return;
            }

            var menu = new ContextMenu
            {
                PlacementTarget = sender as UIElement ?? MainMenuButton,
                Placement = PlacementMode.Bottom,
                StaysOpen = false,
                MinWidth = 440
            };

            ApplyWebPrivacyContextMenuTheme(menu);

            var heading = new MenuItem
            {
                Header = "Favourites",
                IsEnabled = false
            };

            menu.Items.Add(heading);
            menu.Items.Add(new Separator());

            var visibleBookmarks = _isLicensed
                ? _bookmarks.OrderByDescending(b => b.AddedUtc)
                : _bookmarks.OrderByDescending(b => b.AddedUtc).Take(6);

            foreach (var bm in visibleBookmarks.ToList())
            {
                var row = new Grid
                {
                    Width = 410,
                    Margin = new Thickness(0)
                };

                row.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width = new GridLength(1, GridUnitType.Star)
                    });

                row.ColumnDefinitions.Add(
                    new ColumnDefinition
                    {
                        Width = GridLength.Auto
                    });

                string displayTitle =
                    string.IsNullOrWhiteSpace(bm.Title)
                        ? bm.Url
                        : bm.Title;

                var titleText = new TextBlock
                {
                    Text = displayTitle,
                    VerticalAlignment = VerticalAlignment.Center,
                    TextTrimming = TextTrimming.CharacterEllipsis,
                    Margin = new Thickness(2, 0, 12, 0),
                    ToolTip = bm.Url
                };

                titleText.SetResourceReference(
                    TextBlock.ForegroundProperty,
                    "TextPrimary");

                Grid.SetColumn(titleText, 0);

                var deleteButton = new Button
                {
                    Content = "Delete",
                    Width = 66,
                    Height = 26,
                    Padding = new Thickness(6, 1, 6, 1),
                    Margin = new Thickness(4, 0, 0, 0),
                    ToolTip = "Delete this favourite"
                };

                ApplyWebPrivacyButtonTheme(deleteButton);

                Grid.SetColumn(deleteButton, 1);

                row.Children.Add(titleText);
                row.Children.Add(deleteButton);

                var favouriteItem = new MenuItem
                {
                    Header = row,
                    ToolTip = bm.Url
                };

                favouriteItem.Click += (_, __) =>
                {
                    try
                    {
                        var wv = GetActiveWebView();

                        if (wv?.CoreWebView2 != null)
                            wv.CoreWebView2.Navigate(bm.Url);
                    }
                    catch
                    {
                    }
                };

                deleteButton.Click += (_, deleteArgs) =>
                {
                    deleteArgs.Handled = true;

                    try
                    {
                        _bookmarks.Remove(bm);
                        SaveBookmarks();

                        menu.IsOpen = false;

                        UpdateSecurityStatus(
                            "Favourite deleted",
                            false);
                    }
                    catch
                    {
                    }
                };

                menu.Items.Add(favouriteItem);
            }

            Dispatcher.BeginInvoke(
                new Action(() =>
                {
                    menu.IsOpen = true;
                }),
                DispatcherPriority.Background);
        }

        private void WebAction_Print_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var wv = GetActiveWebView();
                if (wv?.CoreWebView2 == null)
                {
                    ShowLexDeskMessageBox("No active page to print.", "Print", MessageBoxButton.OK, MessageBoxImage.Information);
                    return;
                }

                // Requirement: tell user if no printers installed
                if (!HasAnyPrintersInstalled())
                {
                    ShowLexDeskMessageBox(
    "No printer is installed or available right now.",
    "Print",
    MessageBoxButton.OK,
    MessageBoxImage.Information);
                    return;
                }

                // Use built-in WebView2 print UI (avoids System.Drawing + PrintSettings constructor issues)
                wv.CoreWebView2.ShowPrintUI();
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox($"Print failed:\n{SanitizeExceptionMessage(ex)}", "Print", MessageBoxButton.OK, MessageBoxImage.Warning);
            }
        }

        private async void WebAction_CapturePage_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var wv = GetActiveWebView();

                if (wv?.CoreWebView2 == null)
                {
                    ShowLexDeskMessageBox(
                        "No active page to capture.",
                        "Screenshot",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                    return;
                }

                using var stream = new MemoryStream();

                await wv.CoreWebView2.CapturePreviewAsync(
                    CoreWebView2CapturePreviewImageFormat.Png,
                    stream);

                byte[] bytes = stream.ToArray();

                var dialog = new SaveFileDialog
                {
                    Title = "Save Visible Page Screenshot",
                    Filter = "PNG image (*.png)|*.png",
                    FileName = $"LexDeskPro_Visible_{DateTime.Now:yyyyMMdd_HHmmss}.png",
                    InitialDirectory = Environment.GetFolderPath(Environment.SpecialFolder.MyPictures)
                };

                if (dialog.ShowDialog(this) == true)
                {
                    File.WriteAllBytes(dialog.FileName, bytes);

                    // Keep clipboard support as a convenience, but saving the file is the
                    // primary, Grandma-friendly action so the user always knows where it went.
                    try
                    {
                        using var imageStream = new MemoryStream(bytes);
                        var image = new BitmapImage();
                        image.BeginInit();
                        image.CacheOption = BitmapCacheOption.OnLoad;
                        image.StreamSource = imageStream;
                        image.EndInit();
                        image.Freeze();
                        Clipboard.SetImage(image);
                    }
                    catch { }

                    UpdateSecurityStatus($"Screenshot saved: {Path.GetFileName(dialog.FileName)}", false);
                }
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    $"Screenshot failed:\n{SanitizeExceptionMessage(ex)}",
                    "Screenshot",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                if (WebActionsDropdown != null)
                    WebActionsDropdown.IsOpen = false;
            }
        }

        private void WebAction_CaptureArea_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var uri = new Uri(
                    "ms-screenclip://capture/image"
                    + "?rectangle"
                    + "&enabledModes=SnippingAllModes"
                    + "&auto-save"
                    + "&api-version=1.2"
                    + "&user-agent=LexDeskPro"
                    + "&redirect-uri=lexwhite-webprivacypro://capture-response");

                Process.Start(new ProcessStartInfo
                {
                    FileName = uri.ToString(),
                    UseShellExecute = true
                });

                bool launched = true;

                if (!launched)
                {
                    ShowLexDeskMessageBox(
                        "Windows Snipping Tool could not be opened.",
                        "Capture / Crop Area",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);

                    return;
                }

                UpdateSecurityStatus(
                    "Windows Snipping Tool opened.",
                    false);
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    $"Could not open Windows Snipping Tool:\n{SanitizeExceptionMessage(ex)}",
                    "Capture / Crop Area",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                if (WebActionsDropdown != null)
                    WebActionsDropdown.IsOpen = false;
            }
        }

