        private bool SetClipboardTextReliable(string text)
        {
            if (string.IsNullOrEmpty(text))
                return false;

            for (int attempt = 0; attempt < 3; attempt++)
            {
                try
                {
                    var data = new DataObject();

                    // UnicodeText is the important format for Word and other Windows apps.
                    data.SetData(DataFormats.UnicodeText, text);

                    // Also provide standard Text for older/simple applications.
                    data.SetData(DataFormats.Text, text);

                    // true = flush the data to the Windows clipboard so it remains
                    // available after focus moves away from LexDesk Pro.
                    Clipboard.SetDataObject(data, true);

                    return true;
                }
                catch (COMException)
                {
                    // Windows clipboard can occasionally be temporarily locked
                    // by another application. Give it a tiny retry window.
                    if (attempt < 2)
                        System.Threading.Thread.Sleep(40);
                }
                catch
                {
                    return false;
                }
            }

            return false;
        }

