        private async void WebAction_CopySelection_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var wv = GetActiveWebView();

                if (wv?.CoreWebView2 == null)
                    return;

                string json = await wv.CoreWebView2.ExecuteScriptAsync(@"
(function() {
    try {
        const el = document.activeElement;

        if (el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA')) {
            const start = Number.isInteger(el.selectionStart) ? el.selectionStart : 0;
            const end = Number.isInteger(el.selectionEnd) ? el.selectionEnd : start;

            if (end > start)
                return el.value.substring(start, end);
        }

        const selection = window.getSelection();
        return selection ? selection.toString() : '';
    } catch {
        return '';
    }
})();");

                string text = JsonSerializer.Deserialize<string>(json) ?? "";

                if (string.IsNullOrEmpty(text))
                {
                    UpdateSecurityStatus("Nothing selected to copy", false);
                    return;
                }

                if (!SetClipboardTextReliable(text))
                {
                    UpdateSecurityStatus("Could not place selected text on the clipboard", true);
                    return;
                }

                UpdateSecurityStatus("Selected text copied to clipboard", false);
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    $"Copy failed:\n{SanitizeExceptionMessage(ex)}",
                    "Copy",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                if (WebActionsDropdown != null)
                    WebActionsDropdown.IsOpen = false;
            }
        }

        private async void WebAction_CutSelection_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var wv = GetActiveWebView();

                if (wv?.CoreWebView2 == null)
                    return;

                string json = await wv.CoreWebView2.ExecuteScriptAsync(@"
(function() {
    try {
        const el = document.activeElement;

        // ------------------------------------------------------------
        // Editable INPUT / TEXTAREA
        // Real cut: copy selected text, then remove it.
        // ------------------------------------------------------------
        if (el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA')) {
            const start = Number.isInteger(el.selectionStart)
                ? el.selectionStart
                : 0;

            const end = Number.isInteger(el.selectionEnd)
                ? el.selectionEnd
                : start;

            if (end <= start)
                return { text: '', removed: false };

            const text = el.value.substring(start, end);

            el.setRangeText('', start, end, 'start');
            el.dispatchEvent(new Event('input', { bubbles: true }));
            el.dispatchEvent(new Event('change', { bubbles: true }));

            return {
                text: text,
                removed: true
            };
        }

        // ------------------------------------------------------------
        // contenteditable
        // Real cut where the webpage genuinely allows editing.
        // ------------------------------------------------------------
        if (el && el.isContentEditable) {
            const selection = window.getSelection();

            if (!selection ||
                selection.rangeCount === 0 ||
                selection.isCollapsed) {
                return { text: '', removed: false };
            }

            const text = selection.toString();

            if (!text)
                return { text: '', removed: false };

            selection.getRangeAt(0).deleteContents();

            el.dispatchEvent(
                new Event('input', { bubbles: true })
            );

            return {
                text: text,
                removed: true
            };
        }

        // ------------------------------------------------------------
        // Normal webpage text
        //
        // A normal webpage is read-only, so its text cannot genuinely
        // be cut. Copy the highlighted text to the Windows clipboard
        // instead so it can still be pasted into Word or another app.
        // ------------------------------------------------------------
        const selection = window.getSelection();

        if (!selection ||
            selection.rangeCount === 0 ||
            selection.isCollapsed) {
            return { text: '', removed: false };
        }

        const text = selection.toString();

        return {
            text: text || '',
            removed: false
        };
    }
    catch {
        return {
            text: '',
            removed: false
        };
    }
})();");

                using var doc = JsonDocument.Parse(json);

                string text = "";

                bool removed = false;

                if (doc.RootElement.TryGetProperty("text", out var textElement))
                    text = textElement.GetString() ?? "";

                if (doc.RootElement.TryGetProperty("removed", out var removedElement))
                    removed = removedElement.GetBoolean();

                if (string.IsNullOrWhiteSpace(text))
                {
                    UpdateSecurityStatus("Select some text first", false);
                    return;
                }

                if (!SetClipboardTextReliable(text))
                {
                    UpdateSecurityStatus(
                        "Could not place selected text on the clipboard",
                        true);

                    return;
                }

                if (removed)
                {
                    UpdateSecurityStatus(
                        "Selected text cut to clipboard",
                        false);
                }
                else
                {
                    UpdateSecurityStatus(
                        "Webpage text copied to clipboard",
                        false);
                }
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    $"Cut failed:\n{SanitizeExceptionMessage(ex)}",
                    "Cut",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                if (WebActionsDropdown != null)
                    WebActionsDropdown.IsOpen = false;
            }
        }

        private async void WebAction_PasteText_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                if (!Clipboard.ContainsText())
                {
                    UpdateSecurityStatus("Clipboard does not contain text", false);
                    return;
                }

                var wv = GetActiveWebView();

                if (wv?.CoreWebView2 == null)
                    return;

                string clipboardText = Clipboard.GetText();
                string jsonText = JsonSerializer.Serialize(clipboardText);

                string script = $@"
(function() {{
    try {{
        const text = {jsonText};
        const el = document.activeElement;

        if (!el)
            return false;

        if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') {{
            const start = Number.isInteger(el.selectionStart) ? el.selectionStart : el.value.length;
            const end = Number.isInteger(el.selectionEnd) ? el.selectionEnd : start;
            el.setRangeText(text, start, end, 'end');
            el.dispatchEvent(new Event('input', {{ bubbles: true }}));
            return true;
        }}

        if (el.isContentEditable) {{
            const selection = window.getSelection();

            if (!selection || selection.rangeCount === 0)
                return false;

            const range = selection.getRangeAt(0);
            range.deleteContents();

            const node = document.createTextNode(text);
            range.insertNode(node);
            range.setStartAfter(node);
            range.collapse(true);

            selection.removeAllRanges();
            selection.addRange(range);
            el.dispatchEvent(new Event('input', {{ bubbles: true }}));
            return true;
        }}

        return false;
    }} catch {{
        return false;
    }}
}})();";

                string result = await wv.CoreWebView2.ExecuteScriptAsync(script);
                bool pasted = string.Equals(result, "true", StringComparison.OrdinalIgnoreCase);

                UpdateSecurityStatus(
                    pasted ? "Text pasted" : "Click in an editable field before pasting",
                    false);
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    $"Paste failed:\n{SanitizeExceptionMessage(ex)}",
                    "Paste",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                if (WebActionsDropdown != null)
                    WebActionsDropdown.IsOpen = false;
            }
        }

