        private void WorkspaceTabButton_Click(object sender, RoutedEventArgs e)
        {
            if (sender is not Button button)
                return;

            if (!TryGetWorkspaceTabIndex(button, out int index))
                return;

            if (index < 0 || index >= MaxWorkspaceTabs)
                return;

            if (index == _activeWorkspaceTabIndex)
            {
                UpdateWorkspaceTabVisuals();
                return;
            }

            SaveCurrentWorkspace();

            // Val's Tab idea:
            // Tabs are always visible, but dormant until clicked.
            // Fresh/default tabs get their correct Quick URL block before loading.
            LoadQuickUrlBlockIntoWorkspace(index, force: false);

            LoadWorkspace(index);

            // LoadWorkspace restores this tab's saved pages, layout and active page.
            // Do not force Page 1 or reload pages that the user already has open.
            UpdateSecurityStatus($"Tab {index + 1}", false);
        }

        private void WorkspaceTabButton_PreviewMouseRightButtonUp(object sender, MouseButtonEventArgs e)
        {
            e.Handled = true;

            if (sender is not Button button)
                return;

            if (!TryGetWorkspaceTabIndex(button, out int index))
                return;

            var menu = new ContextMenu();
            ApplyWebPrivacyContextMenuTheme(menu);

            var closePagesItem = new MenuItem
            {
                Header = $"Close extra Web Pages in Tab {index + 1}"
            };

            closePagesItem.Click += (_, __) =>
            {
                CloseExtraWebPagesInTab(index);
            };

            menu.Items.Add(closePagesItem);

            var resetItem = new MenuItem
            {
                Header = $"Reset Tab {index + 1} to Page 1"
            };

            resetItem.Click += (_, __) =>
            {
                ResetWorkspaceTabToPageOne(index);
            };

            menu.Items.Add(resetItem);

            menu.Items.Add(new Separator());

            var close = new MenuItem
            {
                Header = "Cancel"
            };

            close.Click += (_, __) =>
            {
                menu.IsOpen = false;
            };

            menu.Items.Add(close);

            button.ContextMenu = menu;
            menu.PlacementTarget = button;
            menu.Placement = PlacementMode.Bottom;
            menu.IsOpen = true;
        }

        private void CloseExtraWebPagesInTab(int tabIndex)
        {
            if (tabIndex < 0 || tabIndex >= _workspaces.Count)
                return;

            // Save current tab first so we do not lose any live state accidentally.
            SaveCurrentWorkspace();

            var ws = _workspaces[tabIndex];

            RepairWorkspaceQuickUrlSlots(ws, tabIndex);

            ws.ActivePageIndex = 0;
            ws.LayoutPageCount = 1;

            for (int paneIndex = 0; paneIndex < 4; paneIndex++)
            {
                ws.PaneState[paneIndex] = paneIndex == 0
                    ? PaneLifeState.Normal
                    : PaneLifeState.Minimized;

                ws.PageLocked[paneIndex] = false;
            }

            // If this is the tab currently on screen, apply it immediately.
            if (tabIndex == _activeWorkspaceTabIndex)
            {
                _activePageIndex = 0;
                _layoutPageCount = 1;

                Array.Copy(ws.PageUrls, _pageUrls, 4);
                Array.Copy(ws.PageLocked, _pageLocked, 4);
                Array.Copy(ws.PaneState, _paneState, 4);
                Array.Copy(ws.StudioSlotIndex, _studioSlotIndex, 4);

                RepairLiveQuickUrlSlotsForTab(tabIndex);

                ApplyLayout();

                LoadQuickUrlForTabPage(tabIndex, 0, force: true);

                RefreshActivePaneStatusVisual();
                UpdatePageModeButtonVisuals();
                UpdatePageHostBorders();
                UpdateSecureSiteVisual();
            }

            UpdateSecurityStatus($"Tab {tabIndex + 1}: extra Web Pages closed", false);
        }

        private void ResetWorkspaceTabToPageOne(int tabIndex)
        {
            if (tabIndex < 0 || tabIndex >= _workspaces.Count)
                return;

            SaveCurrentWorkspace();

            var result = ShowLexDeskMessageBox(
                $"Reset Tab {tabIndex + 1}?\n\nThis will close the extra Web Pages in this tab and return it to Page 1.",
                "Reset Tab",
                MessageBoxButton.YesNo,
                MessageBoxImage.Question);

            if (result != MessageBoxResult.Yes)
                return;

            LoadQuickUrlBlockIntoWorkspace(tabIndex, force: true);

            var ws = _workspaces[tabIndex];

            ws.ActivePageIndex = 0;
            ws.LayoutPageCount = 1;

            for (int paneIndex = 0; paneIndex < 4; paneIndex++)
            {
                ws.PaneState[paneIndex] = paneIndex == 0
                    ? PaneLifeState.Normal
                    : PaneLifeState.Minimized;

                ws.PageLocked[paneIndex] = false;
            }

            if (tabIndex == _activeWorkspaceTabIndex)
            {
                LoadWorkspace(tabIndex);
                LoadQuickUrlForTabPage(tabIndex, 0, force: true);
            }

            UpdateSecurityStatus($"Tab {tabIndex + 1} reset", false);
        }


        private bool TryGetWorkspaceTabIndex(Button button, out int index)
        {
            index = -1;

            if (button.Tag is int intTag)
            {
                index = intTag;
                return true;
            }

            if (button.Tag is string stringTag && int.TryParse(stringTag, out int parsedTag))
            {
                index = parsedTag;
                return true;
            }

            return false;
        }


        private void RebuildWorkspaceTabs()
        {
            if (WorkspaceTabsPanel == null)
                return;

            WorkspaceTabsPanel.Children.Clear();

            _workspaceTabCount = MaxWorkspaceTabs;

            for (int i = 0; i < MaxWorkspaceTabs; i++)
            {
                var button = new Button
                {
                    Content = $"{i + 1}",
                    Width = 34,
                    MinWidth = 34,
                    MaxWidth = 34,
                    Height = 22,
                    Tag = i,
                    ToolTip =
$"Tab {i + 1}\n" +
$"Quick URLs {(i * 4) + 1}–{(i * 4) + 4}\n" +
"Left click: Open this tab",
                    Style = (Style)FindResource("TopBarIconButtonStyle"),
                    Padding = new Thickness(0),
                    FontSize = 11,
                    FontWeight = FontWeights.SemiBold,
                    Margin = i == 0 ? new Thickness(0) : new Thickness(2, 0, 0, 0)
                };

                button.Click += WorkspaceTabButton_Click;
                button.PreviewMouseRightButtonUp += WorkspaceTabButton_PreviewMouseRightButtonUp;

                WorkspaceTabsPanel.Children.Add(button);
            }

            UpdateWorkspaceTabVisuals();
        }

        private void NewWorkspaceTabButton_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;

            if (_workspaceTabCount >= MaxWorkspaceTabs)
            {
                UpdateSecurityStatus("Maximum tabs reached", true);

                ShowLexDeskMessageBox(
                    "Maximum tabs reached.\n\nLexDesk Pro currently supports up to 5 tabs.",
                    "Tabs",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);

                return;
            }

            SaveCurrentWorkspace();

            int newIndex = _workspaceTabCount;

            _workspaces.Add(new BrowserWorkspace { Title = $"Tab {newIndex + 1}" });
            _workspaceTabCount = _workspaces.Count;

            // Tab 1 = Quick URLs 1-4
            // Tab 2 = Quick URLs 5-8
            // Tab 3 = Quick URLs 9-12
            // Tab 4 = Quick URLs 13-16
            // Tab 5 = Quick URLs 17-20
            LoadQuickUrlBlockIntoWorkspace(newIndex, force: true);

            RebuildWorkspaceTabs();

            LoadWorkspace(newIndex);

            UpdateWorkspaceTabVisuals();
            UpdatePageModeButtonVisuals();
            UpdatePageHostBorders();
            UpdateSecureSiteVisual();

            UpdateSecurityStatus($"Tab {newIndex + 1} created", false);
        }

        private void UpdateWorkspaceTabVisuals()
        {
            if (WorkspaceTabsPanel == null)
                return;

            var activeBg = TryFindResource("ButtonPressedBg") as Brush ?? Brushes.LightGray;
            var defaultBg = Brushes.Transparent;

            var activeBorder = TryFindResource("SelectedButtonBorder") as Brush ?? Brushes.DodgerBlue;
            var defaultBorder = Brushes.Transparent;

            var defaultText = TryFindResource("IconBrush") as Brush ?? Brushes.White;
            var activeText = defaultText; // keep tab text monochrome and theme-aware

            foreach (var child in WorkspaceTabsPanel.Children)
            {
                if (child is not Button button)
                    continue;

                int index = button.Tag is int i ? i : -1;
                bool isActive = index == _activeWorkspaceTabIndex;

                button.Background = isActive ? activeBg : defaultBg;
                button.BorderBrush = isActive ? activeBorder : defaultBorder;
                button.BorderThickness = isActive ? new Thickness(1.6) : new Thickness(0);
                button.Foreground = isActive ? activeText : defaultText;
                button.FontWeight = isActive ? FontWeights.SemiBold : FontWeights.Normal;
            }
        }

