        private void WebAction_FindOnPage_Click(object sender, RoutedEventArgs e)
        {
            ShowFindOnPageWindow();
            if (WebActionsDropdown != null) WebActionsDropdown.IsOpen = false;
        }

        private void ShowFindOnPageWindow()
        {
            if (GetActiveWebView()?.CoreWebView2 == null)
            {
                ShowLexDeskMessageBox("Open a normal webpage first.", "Find on Page", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            if (_findWindow != null && _findWindow.IsVisible)
            {
                _findWindow.Activate();
                _findTextBox?.Focus();
                return;
            }

            var window = new Window
            {
                Title = "Find on Page",
                Owner = this,
                Width = 470,
                Height = 128,
                ResizeMode = ResizeMode.NoResize,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                ShowInTaskbar = false,
                Background = TryFindResource("CardBg") as Brush ?? Brushes.White,
                Foreground = TryFindResource("TextPrimary") as Brush ?? Brushes.Black
            };

            var grid = new Grid { Margin = new Thickness(14) };
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            grid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            var box = new TextBox { MinWidth = 260, Height = 30, Margin = new Thickness(0, 0, 8, 0), Padding = new Thickness(7, 2, 7, 2), VerticalContentAlignment = VerticalAlignment.Center };
            var previous = new Button { Content = "↑", Width = 42, Height = 30, Margin = new Thickness(0, 0, 6, 0), ToolTip = "Previous match" };
            var next = new Button { Content = "↓", Width = 42, Height = 30, Margin = new Thickness(0, 0, 6, 0), ToolTip = "Next match" };
            var close = new Button { Content = "×", Width = 42, Height = 30, ToolTip = "Close" };
            ApplyWebPrivacyTextBoxTheme(box);
            ApplyWebPrivacyButtonTheme(previous);
            ApplyWebPrivacyButtonTheme(next);
            ApplyWebPrivacyButtonTheme(close);
            var result = new TextBlock { Margin = new Thickness(2, 8, 0, 0), Foreground = TryFindResource("TextSecondary") as Brush ?? Brushes.Gray };

            Grid.SetColumn(box, 0); Grid.SetColumn(previous, 1); Grid.SetColumn(next, 2); Grid.SetColumn(close, 3);
            Grid.SetRow(result, 1); Grid.SetColumnSpan(result, 4);
            grid.Children.Add(box); grid.Children.Add(previous); grid.Children.Add(next); grid.Children.Add(close); grid.Children.Add(result);
            window.Content = grid;

            _findWindow = window;
            _findTextBox = box;
            _findResultText = result;

            box.TextChanged += async (_, __) => await RunFindOnPageAsync(box.Text, false, true);
            box.KeyDown += async (_, keyArgs) =>
            {
                if (keyArgs.Key == Key.Enter)
                {
                    keyArgs.Handled = true;
                    await RunFindOnPageAsync(box.Text, Keyboard.Modifiers.HasFlag(ModifierKeys.Shift), false);
                }
            };
            previous.Click += async (_, __) => await RunFindOnPageAsync(box.Text, true, false);
            next.Click += async (_, __) => await RunFindOnPageAsync(box.Text, false, false);
            close.Click += (_, __) => window.Close();
            window.PreviewKeyDown += (_, keyArgs) => { if (keyArgs.Key == Key.Escape) window.Close(); };
            window.Closed += (_, __) => { _findWindow = null; _findTextBox = null; _findResultText = null; };
            window.Show();
            box.Focus();
        }

        private async Task RunFindOnPageAsync(string term, bool backwards, bool resetSelection)
        {
            try
            {
                var wv = GetActiveWebView();
                if (wv?.CoreWebView2 == null || _findResultText == null) return;
                term = (term ?? "").Trim();
                if (term.Length == 0) { _findResultText.Text = "Type something to find on this page."; return; }

                string jsTerm = JsonSerializer.Serialize(term);
                string script = $@"
(() => {{
  const term = {jsTerm};
  const text = (document.body && document.body.innerText) ? document.body.innerText : '';
  const escaped = term.replace(/[.*+?^${{}}()|[\]\\]/g, '\\$&');
  let count = 0;
  try {{ count = (text.match(new RegExp(escaped, 'gi')) || []).length; }} catch {{ }}
  if ({(resetSelection ? "true" : "false")}) {{
    try {{ const s = window.getSelection(); if (s) s.removeAllRanges(); }} catch {{ }}
  }}
  let found = false;
  try {{ found = window.find(term, false, {(backwards ? "true" : "false")}, true, false, false, false); }} catch {{ }}
  if (!found && count > 0) {{
    try {{ const s = window.getSelection(); if (s) s.removeAllRanges(); window.scrollTo(0, {(backwards ? "document.body.scrollHeight" : "0")}); }} catch {{ }}
    try {{ found = window.find(term, false, {(backwards ? "true" : "false")}, true, false, false, false); }} catch {{ }}
  }}
  return {{ count, found }};
}})();";
                string json = await wv.CoreWebView2.ExecuteScriptAsync(script);
                using var doc = JsonDocument.Parse(json);
                int count = doc.RootElement.TryGetProperty("count", out var countEl) ? countEl.GetInt32() : 0;
                bool found = doc.RootElement.TryGetProperty("found", out var foundEl) && foundEl.GetBoolean();
                _findResultText.Text = count == 0 ? "No matches." : $"{count} match{(count == 1 ? "" : "es")}. {(found ? "Current match selected." : "")}";
            }
            catch
            {
                if (_findResultText != null) _findResultText.Text = "Find is not available on this page.";
            }
        }

        private async void WebAction_ReadingView_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var wv = GetActiveWebView();
                if (wv?.CoreWebView2 == null) return;

                string result = await wv.CoreWebView2.ExecuteScriptAsync(@"
(() => {
  const existing = document.querySelector('wpp-reading-view-host');
  if (existing) { existing.remove(); return 'off'; }

  const candidates = Array.from(document.querySelectorAll('article, main, [role=main]'))
    .filter(x => (x.innerText || '').trim().length > 500)
    .sort((a,b) => (b.innerText || '').length - (a.innerText || '').length);

  const source = candidates[0];
  if (!source) return 'none';

  const clone = source.cloneNode(true);

  // Remove controls, scripts and page furniture that do not belong in a clean reading view.
  clone.querySelectorAll('script,style,noscript,iframe,form,button,nav,aside,[role=navigation],[aria-hidden=true],svg,canvas,video,audio').forEach(x => x.remove());

  // Strip the website's styling hooks. The old reader kept classes from the source page,
  // which could create dark cards, invisible text and other odd layouts inside the reader.
  clone.querySelectorAll('*').forEach(el => {
    el.removeAttribute('class');
    el.removeAttribute('style');
    el.removeAttribute('id');
    Array.from(el.attributes || []).forEach(attr => {
      const n = (attr.name || '').toLowerCase();
      if (n.startsWith('on') || n === 'hidden') el.removeAttribute(attr.name);
    });
  });

  const textLength = (clone.innerText || '').trim().length;
  if (textLength < 500) return 'none';

  const host = document.createElement('wpp-reading-view-host');
  host.style.cssText = 'all:initial!important;position:fixed!important;inset:0!important;z-index:2147483647!important;display:block!important;';
  const shadow = host.attachShadow({mode:'open'});

  const style = document.createElement('style');
style.textContent = `
    :host {
        all: initial;

        --reader-overlay: #f4f5f7;
        --reader-card: #ffffff;
        --reader-text: #202124;
        --reader-secondary: #4b4f54;
        --reader-caption: #666666;
        --reader-border: #d8dadd;
        --reader-quote: #9aa0a6;
        --reader-link: #0b57d0;
        --reader-button-bg: #ffffff;
        --reader-button-border: #c9cdd2;
        --reader-shadow: rgba(0,0,0,.14);
    }

    @media (prefers-color-scheme: dark) {
        :host {
            --reader-overlay: #202124;
            --reader-card: #303134;
            --reader-text: #f1f1f1;
            --reader-secondary: #b7b7b7;
            --reader-caption: #b7b7b7;
            --reader-border: #494949;
            --reader-quote: #8a8d91;
            --reader-link: #8ab4f8;
            --reader-button-bg: #292a2d;
            --reader-button-border: #3c4043;
            --reader-shadow: rgba(0,0,0,.38);
        }
    }

    .overlay {
        position: fixed;
        inset: 0;
        overflow: auto;
        background: var(--reader-overlay);
        color: var(--reader-text);
        padding: 32px 20px 56px;
        font-family: Segoe UI, Arial, sans-serif;
    }

    .shell {
        max-width: 900px;
        margin: 0 auto;
        background: var(--reader-card);
        color: var(--reader-text);
        padding: 36px 48px 54px;
        border-radius: 14px;
        box-shadow: 0 8px 30px var(--reader-shadow);
    }

    .bar {
        position: sticky;
        top: 0;
        z-index: 2;
        display: flex;
        justify-content: flex-end;
        margin: -8px -8px 18px 0;
    }

    .close {
        border: 1px solid var(--reader-button-border);
        background: var(--reader-button-bg);
        color: var(--reader-text);
        border-radius: 8px;
        padding: 8px 12px;
        font: 600 13px Segoe UI, Arial, sans-serif;
        cursor: pointer;
    }

    .close:hover {
        filter: brightness(1.08);
    }

    .reader {
        font: 18px/1.72 Segoe UI, Arial, sans-serif;
        color: var(--reader-text);
    }

    .reader h1 {
        font-size: 34px;
        line-height: 1.2;
        margin: 0 0 18px;
    }

    .reader h2 {
        font-size: 26px;
        line-height: 1.3;
        margin: 30px 0 12px;
    }

    .reader h3 {
        font-size: 22px;
        line-height: 1.35;
        margin: 24px 0 10px;
    }

    .reader h4,
    .reader h5,
    .reader h6 {
        font-size: 19px;
        margin: 20px 0 8px;
    }

    .reader p {
        margin: 0 0 18px;
    }

    .reader ul,
    .reader ol {
        margin: 0 0 18px 28px;
        padding: 0;
    }

    .reader li {
        margin: 0 0 8px;
    }

    .reader blockquote {
        margin: 20px 0;
        padding: 4px 0 4px 18px;
        border-left: 4px solid var(--reader-quote);
        color: var(--reader-secondary);
    }

    .reader img {
        display: block;
        max-width: 100%;
        height: auto;
        margin: 22px auto;
        border-radius: 8px;
    }

    .reader figure {
        margin: 24px 0;
    }

    .reader figcaption {
        color: var(--reader-caption);
        font-size: 14px;
        line-height: 1.45;
        margin-top: 6px;
    }

    .reader a {
        color: var(--reader-link);
        text-decoration: underline;
    }

    .reader table {
        width: 100%;
        border-collapse: collapse;
        margin: 20px 0;
        font-size: 16px;
    }

    .reader th,
    .reader td {
        border: 1px solid var(--reader-border);
        padding: 8px;
        text-align: left;
        vertical-align: top;
    }

    .reader pre,
    .reader code {
        white-space: pre-wrap;
        word-break: break-word;
        font-family: Consolas, monospace;
    }

    @media (max-width: 700px) {
        .overlay {
            padding: 12px;
        }

        .shell {
            padding: 24px 20px 40px;
        }

        .reader {
            font-size: 17px;
        }

        .reader h1 {
            font-size: 29px;
        }
    }
