        private async void WebAction_CaptureFullPage_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var wv = GetActiveWebView();
                if (wv?.CoreWebView2 == null) return;
                string json = await wv.CoreWebView2.CallDevToolsProtocolMethodAsync("Page.captureScreenshot", "{\"format\":\"png\",\"captureBeyondViewport\":true,\"fromSurface\":true}");
                using var doc = JsonDocument.Parse(json);
                if (!doc.RootElement.TryGetProperty("data", out var dataEl)) throw new InvalidOperationException("No screenshot data was returned.");
                byte[] bytes = Convert.FromBase64String(dataEl.GetString() ?? "");
                var dialog = new SaveFileDialog { Title = "Save Full Page Screenshot", Filter = "PNG image (*.png)|*.png", FileName = $"LexDeskPro_{DateTime.Now:yyyyMMdd_HHmmss}.png" };
                if (dialog.ShowDialog(this) == true)
                {
                    File.WriteAllBytes(dialog.FileName, bytes);
                    UpdateSecurityStatus("Full page screenshot saved", false);
                }
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox($"Full page screenshot failed.\n\n{SanitizeExceptionMessage(ex)}", "Screenshot", MessageBoxButton.OK, MessageBoxImage.Warning);
            }
            finally { if (WebActionsDropdown != null) WebActionsDropdown.IsOpen = false; }
        }

