        private void RememberRecentlyClosedPage(int paneIndex)
        {
            try
            {
                string url = GetWebView(paneIndex)?.CoreWebView2?.Source ?? _pageUrls[paneIndex] ?? "";
                if (!Uri.TryCreate(url, UriKind.Absolute, out var uri) || (uri.Scheme != Uri.UriSchemeHttp && uri.Scheme != Uri.UriSchemeHttps)) return;
                _recentlyClosedPages.Push(new ClosedPageEntry { Url = url, PaneIndex = paneIndex });
                while (_recentlyClosedPages.Count > 20)
                {
                    var keep = _recentlyClosedPages.Reverse().Take(20).Reverse().ToList();
                    _recentlyClosedPages.Clear();
                    foreach (var item in keep) _recentlyClosedPages.Push(item);
                }
            }
            catch { }
        }

        private void RestoreRecentlyClosedPage()
        {
            if (_recentlyClosedPages.Count == 0)
            {
                UpdateSecurityStatus("No recently closed page", false);
                return;
            }
            var entry = _recentlyClosedPages.Pop();
            int paneIndex = entry.PaneIndex >= 0 && entry.PaneIndex < 4 ? entry.PaneIndex : _activePageIndex;
            _pageLocked[paneIndex] = false;
            _paneState[paneIndex] = PaneLifeState.Normal;
            _pageUrls[paneIndex] = entry.Url;
            _activePageIndex = paneIndex;
            _layoutPageCount = Math.Max(1, VisiblePanes().Count);
            ApplyLayout();
            _ = NavigatePaneWhenReadyAsync(paneIndex, entry.Url);
            UpdatePageModeButtonVisuals();
            UpdatePageHostBorders();
            UpdateSecureSiteVisual();
            UpdateSecurityStatus("Recently closed page restored", false);
        }

        private static string PermissionKey(CoreWebView2PermissionKind kind) => kind switch
        {
            CoreWebView2PermissionKind.Camera => "Camera",
            CoreWebView2PermissionKind.Microphone => "Microphone",
            CoreWebView2PermissionKind.Geolocation => "Location",
            CoreWebView2PermissionKind.Notifications => "Notifications",
            CoreWebView2PermissionKind.ClipboardRead => "ClipboardRead",
            _ => kind.ToString()
        };

        private bool IsSitePermissionAllowed(string host, CoreWebView2PermissionKind kind)
        {
            host = (host ?? "").Replace("www.", "", StringComparison.OrdinalIgnoreCase).Trim().ToLowerInvariant();
            return host.Length > 0 && _sitePermissionAllows.TryGetValue(host, out var allowed) && allowed.Contains(PermissionKey(kind));
        }

        private void LoadSitePermissionSettings()
        {
            try
            {
                _sitePermissionAllows.Clear();
                if (!File.Exists(_sitePermissionsPath)) return;
                var store = JsonSerializer.Deserialize<SitePermissionStore>(File.ReadAllText(_sitePermissionsPath));
                if (store?.Sites == null) return;
                foreach (var pair in store.Sites)
                    _sitePermissionAllows[pair.Key] = new HashSet<string>(pair.Value ?? new List<string>(), StringComparer.OrdinalIgnoreCase);
            }
            catch { _sitePermissionAllows.Clear(); }
        }

        private void SaveSitePermissionSettings()
        {
            try
            {
                var store = new SitePermissionStore();
                foreach (var pair in _sitePermissionAllows)
                    store.Sites[pair.Key] = pair.Value.OrderBy(x => x).ToList();
                Directory.CreateDirectory(Path.GetDirectoryName(_sitePermissionsPath)!);
                File.WriteAllText(_sitePermissionsPath, JsonSerializer.Serialize(store, JsonIndentedOptions));
            }
            catch { }
        }

        private void ShowSitePermissionsWindow()
        {
            string host = GetHostFromUrl(GetSafeCurrentPageUrlForUserAction()).Replace("www.", "", StringComparison.OrdinalIgnoreCase).Trim().ToLowerInvariant();
            if (string.IsNullOrWhiteSpace(host))
            {
                ShowLexDeskMessageBox("Open a normal website first.", "Site Permissions", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }
            _sitePermissionAllows.TryGetValue(host, out var existing);
            existing ??= new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            var window = new Window { Title = $"Site Permissions - {host}", Owner = this, Width = 470, Height = 430, ResizeMode = ResizeMode.NoResize, WindowStartupLocation = WindowStartupLocation.CenterOwner, ShowInTaskbar = false };
            ApplyWebPrivacyDialogTheme(window);
            var panel = new StackPanel { Margin = new Thickness(22) };
            panel.Children.Add(new TextBlock { Text = host, FontSize = 17, FontWeight = FontWeights.SemiBold, Margin = new Thickness(0, 0, 0, 6) });
            panel.Children.Add(new TextBlock { Text = "Allow only permissions you expect to use on this website. Changes are stored only for this site.", TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 0, 0, 16), Foreground = TryFindResource("TextSecondary") as Brush ?? Brushes.Gray });
            CheckBox Make(string label, string key)
            {
                var box = new CheckBox { Content = label, Tag = key, IsChecked = existing.Contains(key), Margin = new Thickness(0, 0, 0, 12), FontSize = 14 };
                box.SetResourceReference(Control.ForegroundProperty, "TextPrimary");
                return box;
            }
            var boxes = new[] { Make("Camera", "Camera"), Make("Microphone", "Microphone"), Make("Location", "Location"), Make("Notifications", "Notifications"), Make("Read clipboard", "ClipboardRead") };
            foreach (var box in boxes) panel.Children.Add(box);
            var buttons = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 12, 0, 0) };
            var reset = new Button { Content = "Reset", Width = 90, Height = 32, Margin = new Thickness(0, 0, 8, 0) };
            var cancel = new Button { Content = "Cancel", Width = 90, Height = 32, Margin = new Thickness(0, 0, 8, 0) };
            var save = new Button { Content = "Save", Width = 90, Height = 32 };
            ApplyWebPrivacyButtonTheme(reset);
            ApplyWebPrivacyButtonTheme(cancel);
            ApplyWebPrivacyButtonTheme(save);
            buttons.Children.Add(reset); buttons.Children.Add(cancel); buttons.Children.Add(save); panel.Children.Add(buttons); window.Content = panel;
            reset.Click += (_, __) => { foreach (var box in boxes) box.IsChecked = false; };
            cancel.Click += (_, __) => window.Close();
            save.Click += (_, __) =>
            {
                var chosen = new HashSet<string>(boxes.Where(x => x.IsChecked == true).Select(x => x.Tag?.ToString() ?? "").Where(x => x.Length > 0), StringComparer.OrdinalIgnoreCase);
                if (chosen.Count == 0) _sitePermissionAllows.Remove(host); else _sitePermissionAllows[host] = chosen;
                SaveSitePermissionSettings();
                UpdateSecurityStatus("Site permissions saved", false);
                window.Close();
            };
            window.ShowDialog();
        }

        private void LoadMemorySaverSettings()
        {
            try
            {
                if (File.Exists(_memorySaverPath))
                {
                    var saved = JsonSerializer.Deserialize<MemorySaverSettings>(File.ReadAllText(_memorySaverPath));
                    if (saved != null)
                    {
                        _memorySaverEnabled = saved.Enabled;
                        _memorySaverMinutes = saved.Minutes is 15 or 30 or 60 ? saved.Minutes : 15;
                    }
                }
            }
            catch { _memorySaverEnabled = true; _memorySaverMinutes = 15; }
            UpdateMemorySaverButton();
        }

        private void SaveMemorySaverSettings()
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_memorySaverPath)!);
                File.WriteAllText(_memorySaverPath, JsonSerializer.Serialize(new MemorySaverSettings { Enabled = _memorySaverEnabled, Minutes = _memorySaverMinutes }, JsonIndentedOptions));
            }
            catch { }
        }

        private void InitializeMemorySaver()
        {
            _memorySaverTimer?.Stop();
            _memorySaverTimer = new DispatcherTimer { Interval = TimeSpan.FromMinutes(1) };
            _memorySaverTimer.Tick += async (_, __) => await RunMemorySaverPassAsync();
            _memorySaverTimer.Start();
        }

        private async Task RunMemorySaverPassAsync()
        {
            if (!_memorySaverEnabled) return;
            for (int i = 0; i < 4; i++)
            {
                if (i == _activePageIndex) continue;
                var host = GetPageHost(i);
                var wv = GetWebView(i);
                if (host == null || wv?.CoreWebView2 == null) continue;
                if (host.Visibility == Visibility.Visible) continue;
                if ((DateTime.UtcNow - _paneLastActiveUtc[i]).TotalMinutes < _memorySaverMinutes) continue;
                if (_paneSuspendedByMemorySaver[i]) continue;
                try
                {
                    bool suspended = await wv.CoreWebView2.TrySuspendAsync();
                    _paneSuspendedByMemorySaver[i] = suspended;
                }
                catch { }
            }
        }

        private void ResumePaneFromMemorySaver(int paneIndex)
        {
            if (paneIndex < 0 || paneIndex > 3) return;
            try
            {
                var wv = GetWebView(paneIndex);
                if (_paneSuspendedByMemorySaver[paneIndex] && wv?.CoreWebView2 != null)
                {
                    wv.CoreWebView2.Resume();
                    _paneSuspendedByMemorySaver[paneIndex] = false;
                }
            }
            catch { _paneSuspendedByMemorySaver[paneIndex] = false; }
        }

        private void LoadSiteZoomSettings()
        {
            try
            {
                _siteZoomLevels.Clear();
                if (!File.Exists(_siteZoomPath)) return;
                var saved = JsonSerializer.Deserialize<Dictionary<string, double>>(File.ReadAllText(_siteZoomPath));
                if (saved == null) return;
                foreach (var pair in saved)
                    if (!string.IsNullOrWhiteSpace(pair.Key) && pair.Value >= 0.25 && pair.Value <= 3.0)
                        _siteZoomLevels[pair.Key] = pair.Value;
            }
            catch { _siteZoomLevels.Clear(); }
        }

        private void SaveSiteZoomSettings()
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_siteZoomPath)!);
                File.WriteAllText(_siteZoomPath, JsonSerializer.Serialize(_siteZoomLevels, JsonIndentedOptions));
            }
            catch { }
        }

        private static string GetZoomHost(WebView2? wv)
        {
            try
            {
                string source = wv?.CoreWebView2?.Source ?? "";
                if (Uri.TryCreate(source, UriKind.Absolute, out var uri))
                    return uri.Host.Replace("www.", "", StringComparison.OrdinalIgnoreCase).ToLowerInvariant();
            }
            catch { }
            return "";
        }

        private void SaveCurrentSiteZoom(WebView2? wv)
        {
            string host = GetZoomHost(wv);
            if (host.Length == 0 || wv == null) return;
            if (Math.Abs(wv.ZoomFactor - 1.0) < 0.001) _siteZoomLevels.Remove(host);
            else _siteZoomLevels[host] = wv.ZoomFactor;
            SaveSiteZoomSettings();
        }

        private void ApplySavedZoomForPane(WebView2? wv)
        {
            if (wv == null) return;
            string host = GetZoomHost(wv);
            wv.ZoomFactor = host.Length > 0 && _siteZoomLevels.TryGetValue(host, out double factor) ? factor : 1.0;
        }

        private void UpdateMemorySaverButton()
        {
            if (MemorySaverButton != null)
                MemorySaverButton.Content = _memorySaverEnabled ? $"Memory Saver: On ({_memorySaverMinutes} minutes)" : "Memory Saver: Off";
        }

        private void MemorySaverButton_Click(object sender, RoutedEventArgs e)
        {
            if (!_memorySaverEnabled) { _memorySaverEnabled = true; _memorySaverMinutes = 15; }
            else if (_memorySaverMinutes == 15) _memorySaverMinutes = 30;
            else if (_memorySaverMinutes == 30) _memorySaverMinutes = 60;
            else { _memorySaverEnabled = false; _memorySaverMinutes = 15; }
            SaveMemorySaverSettings();
            UpdateMemorySaverButton();
            UpdateSecurityStatus(_memorySaverEnabled ? $"Memory Saver {_memorySaverMinutes} min" : "Memory Saver off", false);
        }

        private void WebAction_ZoomIn_Click(object sender, RoutedEventArgs e)
        {
            var wv = GetActiveWebView();
            if (wv?.CoreWebView2 == null) return;

            wv.ZoomFactor = Math.Min(3.0, wv.ZoomFactor + 0.10);
            SaveCurrentSiteZoom(wv);
            UpdateSecurityStatus($"Page zoom {Math.Round(wv.ZoomFactor * 100)}%", false);
        }

        private void WebAction_ZoomOut_Click(object sender, RoutedEventArgs e)
        {
            var wv = GetActiveWebView();
            if (wv?.CoreWebView2 == null) return;

            wv.ZoomFactor = Math.Max(0.25, wv.ZoomFactor - 0.10);
            SaveCurrentSiteZoom(wv);
            UpdateSecurityStatus($"Page zoom {Math.Round(wv.ZoomFactor * 100)}%", false);
        }

        private void WebAction_ZoomReset_Click(object sender, RoutedEventArgs e)
        {
            var wv = GetActiveWebView();
            if (wv?.CoreWebView2 == null) return;

            wv.ZoomFactor = 1.0;
            SaveCurrentSiteZoom(wv);
            UpdateSecurityStatus("Page zoom 100%", false);
        }

        private void OpenFolderInExplorer(string folderPath, string friendlyName)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(folderPath))
                    return;

                Directory.CreateDirectory(folderPath);

                var psi = new ProcessStartInfo
                {
                    FileName = "explorer.exe",
                    Arguments = $"\"{folderPath}\"",
                    UseShellExecute = true
                };

                Process.Start(psi);
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    $"Could not open {friendlyName}:\n{SanitizeExceptionMessage(ex)}",
                    "LexDesk Pro",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
        }
        private void WebAction_Downloads_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                string downloadsFolder = Path.Combine(
                    Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
                    "Downloads");

                Directory.CreateDirectory(downloadsFolder);
                Directory.CreateDirectory(_quarantineFolderPath);

                var menu = new ContextMenu
                {
                    PlacementTarget = sender as UIElement,
                    Placement = PlacementMode.Bottom,
                    MinWidth = 260
                };

                ApplyWebPrivacyContextMenuTheme(menu);

                var title = new MenuItem
                {
                    Header = "Downloads / Quarantine",
                    IsEnabled = false
                };

                menu.Items.Add(title);
                menu.Items.Add(new Separator());

                var openDownloads = new MenuItem
                {
                    Header = "Open Downloads folder"
                };

                openDownloads.Click += (_, __) =>
                {
                    OpenFolderInExplorer(downloadsFolder, "Downloads folder");
                };

                menu.Items.Add(openDownloads);

                var openQuarantine = new MenuItem
                {
                    Header = "Open Quarantine folder"
                };

                openQuarantine.Click += (_, __) =>
                {
                    OpenFolderInExplorer(_quarantineFolderPath, "Quarantine folder");
                };

                menu.Items.Add(openQuarantine);

                menu.Items.Add(new Separator());

                var scanHelp = new MenuItem
                {
                    Header = "How to scan a file",
                    IsEnabled = true
                };

                scanHelp.Click += (_, __) =>
                {
                    ShowProtectionPopup(
    "LexDesk Pro - Downloads / Quarantine",
    "How to scan a downloaded file",
    "To scan a file:\n\n" +
    "1. Open Downloads or Quarantine.\n" +
    "2. Select the file.\n" +
    "3. Right-click the file.\n" +
    "4. Choose your installed security app's scan option if it appears.\n\n" +
    "If no scan option appears, open your security app directly and scan the file from there.\n\n" +
    "Note: Microsoft Defender may not appear in the right-click menu if another security app is installed.",
    MessageBoxButton.OK,
    MessageBoxImage.Information);
                };

                menu.Items.Add(scanHelp);

                menu.Items.Add(new Separator());

                var close = new MenuItem
                {
                    Header = "Close"
                };

                close.Click += (_, __) =>
                {
                    menu.IsOpen = false;
                };

                menu.Items.Add(close);

                menu.IsOpen = true;
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    $"Could not open Downloads / Quarantine:\n{SanitizeExceptionMessage(ex)}",
                    "Downloads / Quarantine",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
        }

        private async void WebAction_Bookmark_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var wv = GetActiveWebView();
                if (wv?.CoreWebView2 == null) return;

                var url = GetActivePaneRealUrl();

                if (string.IsNullOrWhiteSpace(url) ||
                    !(url.StartsWith("http://", StringComparison.OrdinalIgnoreCase) ||
                      url.StartsWith("https://", StringComparison.OrdinalIgnoreCase)))
                {
                    ShowWebPrivacyMessage(
                        "Bookmark",
                        "Nothing to bookmark on this page.",
                        500,
                        240);

                    return;
                }

                string title = wv.CoreWebView2.DocumentTitle ?? url;

                if (!HasFullUnlock() && _bookmarks.Count >= 6)
                {
                    ShowWebPrivacyMessage(
                        "Activation Required",
                        "Please activate LexDesk Pro to access all saved favourites.",
                        520,
                        260);

                    return;
                }

                _bookmarks.Insert(
                    0,
                    new BookmarkItem(
                        title,
                        url,
                        DateTime.UtcNow));

                if (_bookmarks.Count > 200)
                    _bookmarks.RemoveRange(
                        200,
                        _bookmarks.Count - 200);

                SaveBookmarks();

                ShowWebPrivacyMessage(
                    "Favourite Saved",
                    $"Saved to Favourites:\n\n{title}",
                    540,
                    280);
            }
            catch (Exception ex)
            {
                ShowWebPrivacyMessage(
                    "Favourite",
                    $"Favourite could not be saved.\n\n{SanitizeExceptionMessage(ex)}",
                    560,
                    300);
            }
        }

        private void WebAction_History_Click(object sender, RoutedEventArgs e)
        {
            var historyItems = _history
                .Where(u => !string.IsNullOrWhiteSpace(u))
                .Reverse()
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(25)
                .ToList();

            if (historyItems.Count == 0)
            {
                ShowWebPrivacyMessage(
                    "History",
                    "No history yet.",
                    480,
                    240);

                return;
            }

            var menu = new ContextMenu
            {
                MinWidth = 500,
                StaysOpen = false
            };

            ApplyWebPrivacyContextMenuTheme(menu);

            var heading = new MenuItem
            {
                Header = "History",
                IsEnabled = false,
                FontWeight = FontWeights.SemiBold
            };

            menu.Items.Add(heading);
            menu.Items.Add(new Separator());

            for (int i = 0; i < historyItems.Count; i++)
            {
                string url = historyItems[i];
                string shortLabel = $"{i + 1}. {FormatHistoryLabel(url)}";

                var rowGrid = new Grid
                {
                    Width = 470
                };

                rowGrid.ColumnDefinitions.Add(
                    new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

                rowGrid.ColumnDefinitions.Add(
                    new ColumnDefinition { Width = GridLength.Auto });

                var titleText = new TextBlock
                {
                    Text = shortLabel,
                    VerticalAlignment = VerticalAlignment.Center,
                    TextTrimming = TextTrimming.CharacterEllipsis,
                    Margin = new Thickness(0, 0, 12, 0)
                };

                Grid.SetColumn(titleText, 0);
                rowGrid.Children.Add(titleText);

                var buttonPanel = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    VerticalAlignment = VerticalAlignment.Center
                };

                var copyButton = new Button
                {
                    Content = "Copy",
                    Width = 62,
                    Height = 26,
                    Margin = new Thickness(0, 0, 6, 0),
                    Style = FindResource("TopBarButtonStyle") as Style
                };

                copyButton.Click += (_, buttonArgs) =>
                {
                    buttonArgs.Handled = true;

                    SetClipboardTextReliable(url);
                    UpdateSecurityStatus("History link copied", false);

                    menu.IsOpen = false;
                };

                var deleteButton = new Button
                {
                    Content = "Delete",
                    Width = 66,
                    Height = 26,
                    Style = FindResource("TopBarButtonStyle") as Style
                };

                deleteButton.Click += (_, buttonArgs) =>
                {
                    buttonArgs.Handled = true;

                    _history.Remove(url);
                    SaveHistory();

                    menu.IsOpen = false;
                    UpdateSecurityStatus("History item deleted", false);
                };

                buttonPanel.Children.Add(copyButton);
                buttonPanel.Children.Add(deleteButton);

                Grid.SetColumn(buttonPanel, 1);
                rowGrid.Children.Add(buttonPanel);

                var historyItem = new MenuItem
                {
                    Header = rowGrid,
                    ToolTip = url,
                    StaysOpenOnClick = false
                };

                historyItem.Click += (_, __) =>
                {
                    var wv = GetActiveWebView();

                    if (wv?.CoreWebView2 != null)
                        wv.CoreWebView2.Navigate(url);

                    menu.IsOpen = false;
                };

                menu.Items.Add(historyItem);
            }

            menu.Items.Add(new Separator());

            var clearAll = new MenuItem
            {
                Header = "Clear All History"
            };

            clearAll.Click += (_, __) =>
            {
                menu.IsOpen = false;

                bool confirmed = ShowWebPrivacyConfirmation(
                    "History",
                    "Clear all saved history?",
                    "Clear History",
                    "Cancel",
                    500,
                    280);

                if (!confirmed)
                    return;

                _history.Clear();
                SaveHistory();

                ShowWebPrivacyMessage(
                    "History",
                    "Saved browsing history has been cleared.",
                    500,
                    250);

                UpdateSecurityStatus("History cleared", false);
            };

            menu.Items.Add(clearAll);

            menu.PlacementTarget = sender as UIElement ?? MainMenuButton;
            menu.IsOpen = true;
        }

