        // ============================================
        // Privacy-Safe Logging Helper
        // ============================================
        //
        // Logs should never expose full customer URLs, license keys,
        // local file paths, download links, email links, or private data.
        //
        // Use this helper before writing customer-controlled values
        // to Console.WriteLine or future log files.
        private string SanitizeLogValue(string value)
        {
            try
            {
                string text = (value ?? "").Trim();

                if (string.IsNullOrWhiteSpace(text))
                    return "";

                if (text.Length > 180)
                    text = text.Substring(0, 180) + "...";

                // Hide obvious query strings/fragments from URLs.
                if (Uri.TryCreate(text, UriKind.Absolute, out var uri))
                {
                    string host = uri.Host;

                    if (string.IsNullOrWhiteSpace(host))
                        return "[uri-hidden]";

                    return $"{uri.Scheme}://{host}/...";
                }

                // Hide local Windows paths.
                if (text.Contains(@":\") || text.StartsWith(@"\\"))
                    return "[local-path-hidden]";

                // Hide likely license/key/token style values.
                if (text.Length >= 20 &&
                    (text.Contains("-") || text.Any(char.IsDigit)) &&
                    text.Any(char.IsLetter))
                {
                    return "[key-hidden]";
                }

                return text;
            }
            catch
            {
                return "[value-hidden]";
            }
        }

        private string SanitizeExceptionMessage(Exception ex)
        {
            if (ex == null)
                return "Unknown error";

            string message = ex.Message ?? "Unknown error";

            try
            {
                string userProfile = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
                string localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
                string tempPath = Path.GetTempPath();

                if (!string.IsNullOrWhiteSpace(userProfile))
                    message = message.Replace(userProfile, "[UserProfile]", StringComparison.OrdinalIgnoreCase);

                if (!string.IsNullOrWhiteSpace(localAppData))
                    message = message.Replace(localAppData, "[LocalAppData]", StringComparison.OrdinalIgnoreCase);

                if (!string.IsNullOrWhiteSpace(tempPath))
                    message = message.Replace(tempPath, "[Temp]", StringComparison.OrdinalIgnoreCase);

                message = message.Replace(Environment.MachineName, "[Device]", StringComparison.OrdinalIgnoreCase);
                message = message.Replace(Environment.UserName, "[User]", StringComparison.OrdinalIgnoreCase);

                message = message.Replace("\r", " ").Replace("\n", " ").Replace("\t", " ");

                if (message.Length > 220)
                    message = message.Substring(0, 220) + "...";
            }
            catch
            {
                return "Error details hidden for privacy.";
            }

            return string.IsNullOrWhiteSpace(message)
                ? "Error details hidden for privacy."
                : message;
        }


        // ============================================
        // Safe External Launch Helper
        // ============================================
        //
        // Use this helper for normal external launches such as:
        // - opening the Quarantine folder
        // - opening the update installer
        // - opening mailto/email links
        //
        // Do NOT blindly convert every Process.Start call to this helper.
        //
        // Leave these special launch paths separate unless reviewed carefully:
        // - Microsoft Defender scan / PowerShell launch
        // - Run as administrator relaunch
        // - App restart after update/settings changes
        //
        // Those flows require special arguments, verbs, timing, or security behaviour.
        // Changing them without review can break scanning, elevation, or restart handling.



        private bool TryStartExternalProcess(string fileName, string friendlyName, string? arguments = null, string? verb = null)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(fileName))
                    return false;

                var psi = new ProcessStartInfo
                {
                    FileName = fileName,
                    UseShellExecute = true
                };

                if (!string.IsNullOrWhiteSpace(arguments))
                    psi.Arguments = arguments;

                if (!string.IsNullOrWhiteSpace(verb))
                    psi.Verb = verb;

                Process.Start(psi);
                return true;
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
    $"Could not open {friendlyName}.\n\n{SanitizeExceptionMessage(ex)}",
    "LexDesk Pro",
    MessageBoxButton.OK,
    MessageBoxImage.Warning);

                return false;
            }
        }

        private bool HasMailtoHandler()
        {
            try
            {
                using var key = Registry.ClassesRoot.OpenSubKey(@"mailto\shell\open\command");
                string command = key?.GetValue(null)?.ToString() ?? "";

                return !string.IsNullOrWhiteSpace(command);
            }
            catch
            {
                return false;
            }
        }

        private bool TryOpenMailClient(string mailto)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(mailto))
                    return false;

                // Avoid Windows showing ugly "no app installed" errors.
                if (!HasMailtoHandler())
                    return false;

                Process.Start(new ProcessStartInfo
                {
                    FileName = mailto,
                    UseShellExecute = true
                });

                return true;
            }
            catch
            {
                return false;
            }
        }

