        private void OpenExternalShareUrl(string shareUrl)
        {
            try
            {
                if (IsDangerousUriScheme(shareUrl, out _))
                    return;

                Process.Start(new ProcessStartInfo
                {
                    FileName = shareUrl,
                    UseShellExecute = true
                });
            }
            catch
            {
                try
                {
                    Clipboard.SetText(GetShareUrl());
                }
                catch { }

                ShowLexDeskMessageBox(
                    "The link was copied.\n\nPaste it into your preferred app.",
                    "Share",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
        }

