        private void MainWindow_PreviewKeyDown(object sender, KeyEventArgs e)
        {
            if (LexDeskDeveloperDiagnosticsEnabled &&
     Keyboard.Modifiers == (ModifierKeys.Control | ModifierKeys.Shift) &&
     e.Key == Key.N)
            {
                e.Handled = true;
                ToggleNewsComAuDebugMode();
                return;
            }

            if (Keyboard.Modifiers == ModifierKeys.Control && e.Key == Key.F)
            {
                e.Handled = true;
                ShowFindOnPageWindow();
                return;
            }

            if (Keyboard.Modifiers == (ModifierKeys.Control | ModifierKeys.Shift) && e.Key == Key.T)
            {
                e.Handled = true;
                RestoreRecentlyClosedPage();
                return;
            }

            if (Keyboard.Modifiers == ModifierKeys.Control &&
                (e.Key == Key.Add || e.Key == Key.OemPlus))
            {
                e.Handled = true;
                WebAction_ZoomIn_Click(this, new RoutedEventArgs());
                return;
            }

            if (Keyboard.Modifiers == ModifierKeys.Control &&
                (e.Key == Key.Subtract || e.Key == Key.OemMinus))
            {
                e.Handled = true;
                WebAction_ZoomOut_Click(this, new RoutedEventArgs());
                return;
            }

            if (Keyboard.Modifiers == ModifierKeys.Control &&
                (e.Key == Key.D0 || e.Key == Key.NumPad0))
            {
                e.Handled = true;
                WebAction_ZoomReset_Click(this, new RoutedEventArgs());
                return;
            }

        }

        private void EmergencyExit()
        {
            try
            {
                // Close app popups / overlays first.
                if (SettingsOverlayHost != null)
                    SettingsOverlayHost.Visibility = Visibility.Collapsed;

                if (GuideOverlay != null)
                    GuideOverlay.Visibility = Visibility.Collapsed;

                if (StartupScreenOverlayHost != null)
                    StartupScreenOverlayHost.Visibility = Visibility.Collapsed;

                if (SettingsDropdown != null)
                    SettingsDropdown.IsOpen = false;

                if (PrivacyDropdown != null)
                    PrivacyDropdown.IsOpen = false;

                if (StatusPopup != null)
                    StatusPopup.IsOpen = false;

                if (WebActionsDropdown != null)
                    WebActionsDropdown.IsOpen = false;

                if (PagesHost != null)
                    PagesHost.Visibility = Visibility.Visible;

                // Stop all web pages loading.
                for (int i = 0; i < 4; i++)
                {
                    try
                    {
                        var pane = GetWebView(i);
                        pane?.CoreWebView2?.Stop();
                    }
                    catch { }
                }

                // Reset active web page to a safe blank/start state.
                _pageUrls[_activePageIndex] = "lexwhite://newtab";

                var activeWebView = GetActiveWebView();

                try
                {
                    if (activeWebView?.CoreWebView2 != null)
                        activeWebView.CoreWebView2.Navigate("about:blank");
                }
                catch { }

                if (AddressBox != null)
                {
                    AddressBox.Text = "";
                    NormalizeAddressBoxView();
                }

                if (_activePageIndex == 0)
                    RefreshHomeOverlay1();

                _downloadAllowOnce.Clear();

                UpdateSecureSiteVisual();
                UpdateSecurityStatus("Emergency Exit activated", true);

                ShowProtectionPopup(
    "LexDesk Pro - Emergency Exit",
    "Emergency Exit activated",
    "LexDesk Pro stopped loading, closed open panels, and returned the active Web Page to a safe start screen.",
    MessageBoxButton.OK,
    MessageBoxImage.Information);
            }
            catch (Exception ex)
            {
                ShowProtectionPopup(
"LexDesk Pro - Emergency Exit",
"Emergency Exit failed",
$"Emergency Exit failed:\n{SanitizeExceptionMessage(ex)}",
MessageBoxButton.OK,
MessageBoxImage.Warning);
            }
        }

        private void EmergencyExitTopButton_Click(object sender, RoutedEventArgs e)
        {
            e.Handled = true;
            EmergencyExit();
        }

        private async void SecureFileReceiveCheckButton_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var dlg = new Microsoft.Win32.OpenFileDialog
                {
                    Title = "Secure File Receive - Check File",
                    CheckFileExists = true,
                    Multiselect = false,
                    Filter = "All files|*.*"
                };

                if (dlg.ShowDialog() != true)
                    return;

                string filePath = dlg.FileName;
                string fileName = Path.GetFileName(filePath);
                string extension = Path.GetExtension(fileName).ToLowerInvariant();

                FileRiskLevel risk = GetFileRiskLevel(extension);
                string riskLabel = GetFileRiskLabel(risk);
                string reason = GetFileRiskReason(extension, risk);

                string action = risk switch
                {
                    FileRiskLevel.High =>
                        "Recommendation: Do not open this file unless you fully trust the sender and expected this exact file.",

                    FileRiskLevel.Medium =>
                        "Recommendation: Be careful. Scan this file before opening, especially if it came from email, chat, or file sharing.",

                    _ =>
                        "Recommendation: Lower risk, but still scan first if the source is unknown."
                };

                UpdateSecurityStatus($"Checked file: {riskLabel}", risk != FileRiskLevel.Low);

                var result = ShowProtectionPopup(
    "LexDesk Pro - Secure File Receive",
    $"Secure File Receive: {riskLabel}",
    $"File: {fileName}\n" +
    $"Type: {(string.IsNullOrWhiteSpace(extension) ? "Unknown" : extension)}\n\n" +
    $"Risk: {riskLabel}\n\n" +
    $"Reason: {reason}\n\n" +
    $"{action}\n\n" +
    (risk == FileRiskLevel.Low
        ? "This file was checked only. It was not moved."
        : "Choose Yes to copy this file to the LexDesk Pro quarantine folder.\nChoose No to leave it where it is."),
    risk == FileRiskLevel.Low ? MessageBoxButton.OK : MessageBoxButton.YesNo,
    risk == FileRiskLevel.Low ? MessageBoxImage.Information : MessageBoxImage.Warning);


                if (risk != FileRiskLevel.Low && result == MessageBoxResult.Yes)
                {
                    string quarantinedPath = CopyFileToQuarantine(filePath);

                    ShowProtectionPopup(
                        "LexDesk Pro - Secure File Receive",
                        "File copied to quarantine",
                        $"The file was copied to quarantine.\n\n" +
                        $"Quarantine location:\n{quarantinedPath}\n\n" +
                        $"LexDesk Pro will now ask Microsoft Defender to scan the quarantined copy.\n\n" +
                        $"Windows Defender may take several minutes to scan quarantined files. You can keep using LexDesk Pro while it scans.\n\n" +
                        $"A result popup will appear when Defender returns a result.\n\n" +
                        $"Original file was not deleted.",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);

                    string defenderResult = await ScanFileWithDefenderAsync(quarantinedPath);

                    ShowProtectionPopup(
                        "LexDesk Pro - Secure File Receive",
                        "Defender scan completed",
                        $"The file was copied to quarantine.\n\n" +
                        $"Quarantine location:\n{quarantinedPath}\n\n" +
                        $"Defender scan result:\n{defenderResult}\n\n" +
                        $"Original file was not deleted.\n\n" +
                        $"If Defender reported a warning, failed scan, or another scan already in progress, leave the file in quarantine until you can review it.",
                        MessageBoxButton.OK,
                        defenderResult == "Clean" ? MessageBoxImage.Information : MessageBoxImage.Warning);
                }

            }
            catch (Exception ex)
            {
                ShowProtectionPopup(
"LexDesk Pro - Secure File Receive",
"Secure File Receive check failed",
$"Secure File Receive check failed:\n{SanitizeExceptionMessage(ex)}",
MessageBoxButton.OK,
MessageBoxImage.Warning);
            }
        }

        private async Task<string> ScanFileWithDefenderAsync(string filePath)
        {
            try
            {
                if (!File.Exists(filePath))
                    return "Scan failed: file does not exist.";

                string escapedPath = filePath.Replace("'", "''");

                var psi = new ProcessStartInfo
                {
                    FileName = "powershell.exe",
                    Arguments = $"-NoProfile -ExecutionPolicy Bypass -Command \"Start-MpScan -ScanPath '{escapedPath}' -ScanType CustomScan\"",
                    RedirectStandardOutput = true,
                    RedirectStandardError = true,
                    UseShellExecute = false,
                    CreateNoWindow = true
                };

                using var process = new Process
                {
                    StartInfo = psi,
                    EnableRaisingEvents = true
                };

                process.Start();

                var waitTask = process.WaitForExitAsync();
                var timeoutTask = Task.Delay(TimeSpan.FromMinutes(5));

                var completedTask = await Task.WhenAny(waitTask, timeoutTask);

                if (completedTask == timeoutTask)
                {
                    try
                    {
                        if (!process.HasExited)
                            process.Kill(entireProcessTree: true);
                    }
                    catch { }

                    return "Scan still pending. Microsoft Defender did not return a final result within 5 minutes. The file remains in quarantine. Leave it there until you can review it in Windows Security.";
                }

                string output = await process.StandardOutput.ReadToEndAsync();
                string error = await process.StandardError.ReadToEndAsync();

                string combined = (output + "\n" + error).Trim();

                if (combined.Contains("already in progress", StringComparison.OrdinalIgnoreCase))
                    return "Microsoft Defender is already scanning this device. The file has been copied to quarantine, but LexDesk Pro could not start a separate scan right now. Please wait a moment, then scan again or open Windows Security to review protection history.";

                if (process.ExitCode == 0)
                    return "Clean";

                if (!string.IsNullOrWhiteSpace(combined))
                    return $"Scan failed: {combined}";

                return $"Scan failed. Defender returned exit code {process.ExitCode}.";
            }
            catch (Exception ex)
            {
                return $"Scan failed: {SanitizeExceptionMessage(ex)}";
            }
        }

        private void OpenQuarantineFolderButton_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                Directory.CreateDirectory(_quarantineFolderPath);

                if (!Directory.Exists(_quarantineFolderPath))
                {
                    ShowWebPrivacyMessage(
                        "LexDesk Pro - Quarantine",
                        "LexDesk Pro could not create the Quarantine folder yet.\n\n" +
                        "Please try again after restarting the app.",
                        540,
                        280);

                    return;
                }

                bool confirmed = ShowWebPrivacyConfirmation(
                    "LexDesk Pro - Quarantine",
                    "Open the Quarantine folder?\n\n" +

                    "To scan a quarantined file:\n\n" +
                    "1. Open the Quarantine folder.\n" +
                    "2. Select the file.\n" +
                    "3. Right-click the file.\n" +
                    "4. Choose your installed security app's scan option if it appears.\n\n" +

                    "If no scan option appears, open your security app directly and scan the file from there.\n\n" +

                    "Note: Microsoft Defender may not appear in the right-click menu if another security app is installed.",
                    "Open Folder",
                    "Cancel",
                    620,
                    480);

                if (!confirmed)
                    return;

                var psi = new ProcessStartInfo
                {
                    FileName = "explorer.exe",
                    Arguments = $"\"{_quarantineFolderPath}\"",
                    UseShellExecute = true
                };

                Process.Start(psi);
            }
            catch (Exception ex)
            {
                ShowWebPrivacyMessage(
                    "LexDesk Pro - Quarantine",
                    $"Could not open the Quarantine folder.\n\n" +
                    $"{SanitizeExceptionMessage(ex)}",
                    560,
                    300);
            }
        }


        // ============================================
        // WebView Initialization
        // ============================================

        private async Task EnsureWebViewAsync()
        {
            try
            {
                if (_webViewInitDone)
                    return;

                if (Web == null)
                {
                    _webViewInitDone = true;
                    return;
                }

                // Speed Recovery:
                // Warm only Web Page 1 at startup.
                // Pages 2-4 are initialized on demand when the user opens them.
                await InitWebViewPaneAsync(Web, 0);

                _webViewInitDone = true;

                await RunPrivacyRelayStartupConfirmationIfNeededAsync();
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
     "LexDesk Pro could not start the browser engine.\n\nPlease restart the app and try again.\n\n" +
     SanitizeExceptionMessage(ex),
     "LexDesk Pro",
     MessageBoxButton.OK,
     MessageBoxImage.Error);
            }
        }

        private async Task EnsureSharedWebViewEnvironmentAsync()
        {
            if (_sharedWebViewEnv != null)
                return;

            var userData = AppDataPath("WebView2");

            Directory.CreateDirectory(userData);

            CoreWebView2EnvironmentOptions? opts = null;

            string browserArgs = BuildWebView2EnvironmentArguments();

            if (!string.IsNullOrWhiteSpace(browserArgs))
                opts = new CoreWebView2EnvironmentOptions(browserArgs);

            _sharedWebViewEnv = await CoreWebView2Environment.CreateAsync(null, userData, opts);
        }

        private async Task InitWebViewPaneAsync(WebView2? wv, int paneIndex)
        {
            if (wv == null)
                return;

            if (paneIndex < 0 || paneIndex >= _webViewPaneInitDone.Length)
                return;

            if (_webViewPaneInitDone[paneIndex])
                return;

            await _webViewPaneInitGate.WaitAsync();

            try
            {
                if (_webViewPaneInitDone[paneIndex])
                    return;

                await EnsureSharedWebViewEnvironmentAsync();

                if (wv.CoreWebView2 == null)
                    await wv.EnsureCoreWebView2Async(_sharedWebViewEnv);

                var core = wv.CoreWebView2;
                if (core == null)
                    return;

                try
                {
                    bool useDarkWebTheme =
                        _themeIndex == (int)AppTheme.Dark ||
                        _themeIndex == (int)AppTheme.NeonBlue;

                    core.Profile.PreferredColorScheme =
                        useDarkWebTheme
                            ? CoreWebView2PreferredColorScheme.Dark
                            : CoreWebView2PreferredColorScheme.Light;
                }
                catch { }

                ApplyWebView2SecuritySettings(wv);

                if (wv.CoreWebView2 != null)
                {
                    await RegisterFirstPaintRecoveryAsync(wv.CoreWebView2);

                    // TEMPORARY DUCATI SPEED TEST ONLY.
                    // Disable the document-wide Early Nuisance Guard observer
                    // to test whether heavy DOM mutation scanning slows complex sites.
                    await RegisterEarlyNuisanceGuardAsync(wv.CoreWebView2);
                }

                EnableAdBlockOn(wv);
                HookAddressUpdates(wv);
                HookNewWindow(wv);
                HookHistory(wv);
                HookDownloadGuard(wv);
                HookDangerousNavigationGuard(wv);
                HookPermissionShield(wv);
                HookScriptDialogShield(wv);
                HookScamShield(wv);

                if (wv.CoreWebView2 != null)
                {
                    wv.CoreWebView2.SourceChanged += (_, __) =>
                    {
                        // Speed Recovery:
                        // Only refresh current-site UI for the active visible pane.
                        if (paneIndex != _activePageIndex)
                            return;

                        Dispatcher.BeginInvoke(new Action(() =>
                        {
                            RefreshCompatibilityUiForCurrentSite();

                            try
                            {
                                string source = wv.CoreWebView2?.Source ?? "";

                                NewsComAuDebugLog(
                                    source,
                                    "Navigation",
                                    "SourceChanged",
                                    "WebView source changed");
                            }
                            catch
                            {
                                // Debug logging must never affect browsing.
                            }
                        }), DispatcherPriority.Background);
                    };

                    // Speed Recovery:
                    // When lazy navigation completes, reveal the WebView again.
                    // This prevents the previous tab/page from flashing during workspace switches.
                    wv.CoreWebView2.NavigationCompleted += (_, __) =>
                    {
                        Dispatcher.BeginInvoke(new Action(() =>
                        {
                            ApplySavedZoomForPane(wv);
                            MarkPaneNavigationFinished(paneIndex);
                        }), DispatcherPriority.Background);
                    };
                }

                HookPaneActivation(wv, paneIndex);

                wv.Tag = "inited";
                _webViewPaneInitDone[paneIndex] = true;
            }
            finally
            {
                _webViewPaneInitGate.Release();
            }
        }

        private async Task NavigatePaneWhenReadyAsync(int paneIndex, string targetUrl)
        {
            try
            {
                if (paneIndex < 0 || paneIndex > 3)
                    return;

                int token = ++_paneNavigationTokens[paneIndex];

                string url = (targetUrl ?? "").Trim();

                if (string.IsNullOrWhiteSpace(url) ||
                    url.Equals("lexwhite://newtab", StringComparison.OrdinalIgnoreCase))
                {
                    url = "about:blank";
                }

                MarkPaneNavigationStarting(paneIndex, url);

                var wv = GetWebView(paneIndex);

                if (wv == null)
                {
                    MarkPaneNavigationFinished(paneIndex);
                    return;
                }

                await InitWebViewPaneAsync(wv, paneIndex);

                if (token != _paneNavigationTokens[paneIndex])
                    return;

                if (wv.CoreWebView2 == null)
                {
                    MarkPaneNavigationFinished(paneIndex);
                    return;
                }

                SetPaneWebViewVisible(paneIndex, true);

                string current = "";

                try
                {
                    current = wv.CoreWebView2.Source ?? "";
                }
                catch
                {
                    current = "";
                }

                // Speed Recovery:
                // Only workspace switches need the brief about:blank visual clear that prevents
                // stale content from the previous tab flashing. Normal address-bar/Quick URL
                // navigation can go directly to the target with no artificial 60 ms pause.
                bool currentIsRealPage =
                    !string.IsNullOrWhiteSpace(current) &&
                    !current.Equals("about:blank", StringComparison.OrdinalIgnoreCase) &&
                    !current.Equals("lexwhite://newtab", StringComparison.OrdinalIgnoreCase);

                bool targetIsRealPage =
                    !string.IsNullOrWhiteSpace(url) &&
                    !url.Equals("about:blank", StringComparison.OrdinalIgnoreCase) &&
                    !url.Equals("lexwhite://newtab", StringComparison.OrdinalIgnoreCase);

                if (_isSwitchingWorkspaceTab &&
                    currentIsRealPage &&
                    targetIsRealPage &&
                    !current.Equals(url, StringComparison.OrdinalIgnoreCase))
                {
                    try
                    {
                        wv.CoreWebView2.Navigate("about:blank");
                    }
                    catch { }

                    // Tiny pause lets WebView visually clear before the real URL starts.
                    await Task.Delay(60);

                    if (token != _paneNavigationTokens[paneIndex])
                        return;
                }

                wv.CoreWebView2.Navigate(url);

                MarkPaneNavigationFinished(paneIndex);
            }
            catch
            {
                MarkPaneNavigationFinished(paneIndex);

                // Navigation must never crash the browser.
            }
        }

        private void SetPaneWebViewVisible(int paneIndex, bool visible)
        {
            try
            {
                var wv = GetWebView(paneIndex);

                if (wv == null)
                    return;

                // Keep WebView visible. Hiding WebView2 can leave blank panes
                // during lazy tab/page switching.
                wv.Visibility = Visibility.Visible;
                wv.IsHitTestVisible = true;
            }
            catch
            {
                // Visual polish must never break browsing.
            }
        }

        private void MarkPaneNavigationStarting(int paneIndex, string targetUrl)
        {
            if (paneIndex < 0 || paneIndex > 3)
                return;

            _panePendingNavigationTargets[paneIndex] = (targetUrl ?? "").Trim();

            // Do not hide WebView2. We keep it visible and use about:blank
            // in NavigatePaneWhenReadyAsync to clear stale content safely.
            SetPaneWebViewVisible(paneIndex, true);
        }

        private void MarkPaneNavigationFinished(int paneIndex)
        {
            if (paneIndex < 0 || paneIndex > 3)
                return;

            _panePendingNavigationTargets[paneIndex] = "";

            SetPaneWebViewVisible(paneIndex, true);
        }

        private void ApplyWebView2SecuritySettings(WebView2 wv)
        {
            try
            {
                if (wv?.CoreWebView2?.Settings == null)
                    return;

                var settings = wv.CoreWebView2.Settings;

                // Keep normal website compatibility.
                settings.IsScriptEnabled = true;
                settings.IsWebMessageEnabled = true;

                // V1 security hardening.
                settings.AreDevToolsEnabled = false;
                settings.AreDefaultContextMenusEnabled = true;
                settings.IsStatusBarEnabled = false;

                // Keep normal browsing usable.
                settings.AreDefaultScriptDialogsEnabled = true;
                settings.IsZoomControlEnabled = true;
                settings.IsBuiltInErrorPageEnabled = true;

                // Customer usability:
                // Let trusted websites remember login names / email fields where WebView2 supports it.
                // Do not enable password saving for V1.
                try
                {
                    var settingsType = settings.GetType();

                    settingsType
                        .GetProperty("IsGeneralAutofillEnabled")
                        ?.SetValue(settings, true);

                    settingsType
                        .GetProperty("IsPasswordAutosaveEnabled")
                        ?.SetValue(settings, false);
                }
                catch
                {
                    // Autofill support depends on the installed WebView2 runtime/SDK.
                    // Never let this break browser startup.
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"WebView2 security settings error: {SanitizeExceptionMessage(ex)}");
            }
        }

        private void HookDownloadGuard(WebView2 wv)
        {
            if (wv?.CoreWebView2 == null) return;

            wv.CoreWebView2.DownloadStarting += CoreWebView2_DownloadStarting;
        }

