        private MessageBoxResult ShowProtectionPopup(
        string title,
        string heading,
        string message,
        MessageBoxButton buttons = MessageBoxButton.OK,
        MessageBoxImage icon = MessageBoxImage.Warning)
        {
            var dialog = new Window
            {
                Title = title,
                Width = 520,
                SizeToContent = SizeToContent.Height,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                ResizeMode = ResizeMode.NoResize,
                Owner = this,
                Background = (Brush)(TryFindResource("TopBarBg") ?? Brushes.White),
                ShowInTaskbar = false
            };

            var root = new Border
            {
                CornerRadius = new CornerRadius(18),
                Padding = new Thickness(20),
                Background = (Brush)(TryFindResource("TopBarBg") ?? Brushes.White),
                BorderBrush = (Brush)(TryFindResource("DividerBrush") ?? Brushes.LightGray),
                BorderThickness = new Thickness(1.2)
            };

            var stack = new StackPanel
            {
                Orientation = Orientation.Vertical
            };

            var titleText = new TextBlock
            {
                Text = heading,
                FontSize = 18,
                FontWeight = FontWeights.SemiBold,
                Foreground = (Brush)(TryFindResource("TextPrimary") ?? Brushes.Black),
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(0, 0, 0, 10)
            };

            var bodyText = new TextBlock
            {
                Text = BuildProtectionPopupMessage(heading, message, buttons),
                FontSize = UseSimpleProtectionWarnings() ? 14 : 13,
                LineHeight = UseSimpleProtectionWarnings() ? 21 : 20,
                Foreground = (Brush)(TryFindResource("TextSecondary") ?? Brushes.DimGray),
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(0, 0, 0, 18)
            };

            var buttonRow = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                HorizontalAlignment = HorizontalAlignment.Right
            };

            MessageBoxResult result = MessageBoxResult.None;

            Button MakeButton(string text, MessageBoxResult value, bool primary = false)
            {
                var btn = new Button
                {
                    Content = text,
                    MinWidth = 96,
                    Height = 34,
                    Margin = new Thickness(8, 0, 0, 0),
                    Padding = new Thickness(14, 4, 14, 4),
                    FontWeight = primary ? FontWeights.SemiBold : FontWeights.Normal
                };

                btn.Click += (_, __) =>
                {
                    result = value;
                    dialog.DialogResult = true;
                    dialog.Close();
                };

                return btn;
            }

            if (buttons == MessageBoxButton.YesNo)
            {
                buttonRow.Children.Add(MakeButton("No", MessageBoxResult.No));
                buttonRow.Children.Add(MakeButton("Yes", MessageBoxResult.Yes, true));
            }
            else
            {
                buttonRow.Children.Add(MakeButton("OK", MessageBoxResult.OK, true));
            }

            stack.Children.Add(titleText);
            stack.Children.Add(bodyText);
            stack.Children.Add(buttonRow);

            root.Child = stack;
            dialog.Content = root;

            dialog.ShowDialog();

            return result == MessageBoxResult.None ? MessageBoxResult.OK : result;
        }

