        private string GetActivePageHostForDownloadGuard()
        {
            try
            {
                string pageUrl = GetActivePaneRealUrl();

                if (!string.IsNullOrWhiteSpace(pageUrl) &&
                    Uri.TryCreate(pageUrl, UriKind.Absolute, out var uri))
                {
                    return uri.Host
                        .Replace("www.", "", StringComparison.OrdinalIgnoreCase)
                        .Trim()
                        .ToLowerInvariant();
                }
            }
            catch { }

            return "";
        }

        private void AddDownloadAllowOnceHost(string host)
        {
            try
            {
                host = (host ?? "")
                    .Replace("www.", "", StringComparison.OrdinalIgnoreCase)
                    .Trim()
                    .ToLowerInvariant();

                if (!string.IsNullOrWhiteSpace(host))
                    _downloadAllowOnceHosts.Add(host);
            }
            catch { }
        }

        private bool IsDownloadAllowOnceHost(string sourceUri)
        {
            try
            {
                string sourceHost = GetDownloadHost(sourceUri);

                if (!string.IsNullOrWhiteSpace(sourceHost) &&
                    _downloadAllowOnceHosts.Remove(sourceHost))
                {
                    return true;
                }

                string pageHost = GetActivePageHostForDownloadGuard();

                if (!string.IsNullOrWhiteSpace(pageHost) &&
                    _downloadAllowOnceHosts.Remove(pageHost))
                {
                    return true;
                }
            }
            catch { }

            return false;
        }

        private string BuildDownloadAllowKey(string extension, string sourceUri)
        {
            string host = "";

            try
            {
                if (!string.IsNullOrWhiteSpace(sourceUri) &&
                    Uri.TryCreate(sourceUri, UriKind.Absolute, out var uri))
                {
                    host = uri.Host.Replace("www.", "").ToLowerInvariant();
                }
            }
            catch
            {
                host = "";
            }

            extension = (extension ?? "").Trim().ToLowerInvariant();

            return $"{host}|{extension}";
        }

        private string GetDownloadHost(string sourceUri)
        {
            try
            {
                if (!string.IsNullOrWhiteSpace(sourceUri) &&
                    Uri.TryCreate(sourceUri, UriKind.Absolute, out var uri))
                {
                    return uri.Host.Replace("www.", "").ToLowerInvariant();
                }
            }
            catch { }

            return "";
        }

        private void TrustDownloadHost(string sourceUri)
        {
            string host = GetDownloadHost(sourceUri);

            if (string.IsNullOrWhiteSpace(host))
                return;

            _trustedDownloadHosts.Add(host);
            SaveTrustedDownloadHosts();

            UpdateSecurityStatus("Download site trusted", false);
        }

        private void TryRestartAllowedDownload(string sourceUri)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(sourceUri))
                    return;

                if (!Uri.TryCreate(sourceUri, UriKind.Absolute, out var uri))
                    return;

                if (!uri.Scheme.Equals("https", StringComparison.OrdinalIgnoreCase) &&
                    !uri.Scheme.Equals("http", StringComparison.OrdinalIgnoreCase))
                    return;

                var webView = GetActiveWebView();

                if (webView?.CoreWebView2 == null)
                    return;

                Dispatcher.BeginInvoke(new Action(() =>
                {
                    try
                    {
                        webView.CoreWebView2.Navigate(sourceUri);
                    }
                    catch
                    {
                        // If automatic restart fails, the user can click the download button again.
                    }
                }), DispatcherPriority.ApplicationIdle);
            }
            catch
            {
                // Download restart should never affect browsing.
            }
        }

        private void CoreWebView2_DownloadStarting(
       object? sender,
       CoreWebView2DownloadStartingEventArgs e)
        {
            try
            {
                string fileName = Path.GetFileName(e.ResultFilePath ?? "");
                string extension = Path.GetExtension(fileName).ToLowerInvariant();

                string sourceUri = "";

                try
                {
                    sourceUri = e.DownloadOperation?.Uri ?? "";
                }
                catch
                {
                    sourceUri = "";
                }

                string allowKey = BuildDownloadAllowKey(extension, sourceUri);

                string sourceHost = GetDownloadHost(sourceUri);

                if (string.IsNullOrWhiteSpace(sourceHost))
                    sourceHost = "unknown site";

                if (_downloadAllowOnce.Remove(allowKey) || IsDownloadAllowOnceHost(sourceUri))
                {
                    UpdateSecurityStatus("Download allowed once", false);
                    return;
                }

                if (_downloadPromptActive.Contains(allowKey))
                {
                    e.Cancel = true;
                    return;
                }

                if (IsHighRiskDownloadExtension(extension))
                {
                    e.Cancel = true;
                    _downloadPromptActive.Add(allowKey);

                    Dispatcher.BeginInvoke(new Action(() =>
                    {
                        try
                        {
                            UpdateSecurityStatus("Download blocked", true);

                            var choice = ShowDownloadGuardDecisionPopup(
                                "LexDesk Pro - Download Guard",
                                "High-risk download blocked",
                                $"File: {fileName}\n" +
                                $"Type: {extension}\n\n" +
                                $"Source site:\n{sourceHost}\n\n" +
                                "This file type can change your computer or run commands.\n\n" +
                                "Choose Allow Once only if you trust this file and website.\n" +
                                "After choosing Allow Once, LexDesk Pro will try to start the download automatically.\n\n" +
                                "If it does not start, click the website's download button again.\n\n" +
                                "Choose Trust Site only if you trust this website for future downloads.\n\n" +
                                "High-risk files will still require approval, even from trusted sites.",
                                allowTrustSite: true);

                            if (choice == DownloadGuardChoice.AllowOnce)
                            {
                                _downloadAllowOnce.Add(allowKey);
                                AddDownloadAllowOnceHost(GetDownloadHost(sourceUri));
                                AddDownloadAllowOnceHost(GetActivePageHostForDownloadGuard());

                                ShowProtectionPopup(
                                    "LexDesk Pro - Download Guard",
                                    "Download allowed once",
                                    "LexDesk Pro will try to start the download now.\n\n" +
                                    "If the download does not start, click the website's download button again.\n\n" +
                                    "After it downloads, you can use Downloads / Quarantine from Tools if you want to scan the file.",
                                    MessageBoxButton.OK,
                                    MessageBoxImage.Information);

                                TryRestartAllowedDownload(sourceUri);
                            }
                            else if (choice == DownloadGuardChoice.TrustSite)
                            {
                                TrustDownloadHost(sourceUri);
                                _downloadAllowOnce.Add(allowKey);
                                AddDownloadAllowOnceHost(GetDownloadHost(sourceUri));
                                AddDownloadAllowOnceHost(GetActivePageHostForDownloadGuard());

                                ShowProtectionPopup(
                                    "LexDesk Pro - Download Guard",
                                    "Download site trusted",
                                    "This website has been added to your trusted download sites.\n\n" +
                                    "LexDesk Pro will try to start this download now.\n\n" +
                                    "If the download does not start, click the website's download button again.\n\n" +
                                    "After it downloads, you can use Downloads / Quarantine from Tools if you want to scan the file.",
                                    MessageBoxButton.OK,
                                    MessageBoxImage.Information);

                                TryRestartAllowedDownload(sourceUri);
                            }
                            else
                            {
                                UpdateSecurityStatus("Download blocked", true);
                            }
                        }
                        finally
                        {
                            _downloadPromptActive.Remove(allowKey);
                        }
                    }), DispatcherPriority.Background);

                    return;
                }

                if (IsMediumRiskDownloadExtension(extension))
                {
                    e.Cancel = true;
                    _downloadPromptActive.Add(allowKey);

                    Dispatcher.BeginInvoke(new Action(() =>
                    {
                        try
                        {
                            UpdateSecurityStatus("Download warning", true);

                            bool isTrustedHost = _trustedDownloadHosts.Contains(GetDownloadHost(sourceUri));

                            if (isTrustedHost)
                            {
                                _downloadAllowOnce.Add(allowKey);
                                AddDownloadAllowOnceHost(GetDownloadHost(sourceUri));
                                AddDownloadAllowOnceHost(GetActivePageHostForDownloadGuard());

                                ShowProtectionPopup(
                                    "LexDesk Pro - Download Guard",
                                    "Trusted download site",
                                    "This website is on your trusted download list.\n\n" +
                                    "LexDesk Pro will try to start this download now.\n\n" +
                                    "If the download does not start, click the website's download button again.\n\n" +
                                    "After it downloads, you can use Downloads / Quarantine from Tools if you want to scan the file.",
                                    MessageBoxButton.OK,
                                    MessageBoxImage.Information);

                                TryRestartAllowedDownload(sourceUri);
                            }
                            else
                            {
                                var choice = ShowDownloadGuardDecisionPopup(
                                    "LexDesk Pro - Download Guard",
                                    "Medium-risk download stopped",
                                    $"File: {fileName}\n" +
                                    $"Type: {extension}\n\n" +
                                    $"Source site:\n{sourceHost}\n\n" +
                                    "Compressed files and Office macro files can hide unsafe installers or scripts.\n\n" +
                                    "Choose Allow Once only if you trust this file and website.\n" +
                                    "After choosing Allow Once, LexDesk Pro will try to start the download automatically.\n\n" +
                                    "If it does not start, click the website's download button again.\n\n" +
                                    "Choose Trust Site only if you trust this website for future downloads.\n\n" +
                                    "Trusted sites still stay under LexDesk Pro control.",
                                    allowTrustSite: true);

                                if (choice == DownloadGuardChoice.AllowOnce)
                                {
                                    _downloadAllowOnce.Add(allowKey);
                                    AddDownloadAllowOnceHost(GetDownloadHost(sourceUri));
                                    AddDownloadAllowOnceHost(GetActivePageHostForDownloadGuard());

                                    ShowProtectionPopup(
                                        "LexDesk Pro - Download Guard",
                                        "Download allowed once",
                                        "LexDesk Pro will try to start the download now.\n\n" +
                                        "If the download does not start, click the website's download button again.\n\n" +
                                        "After it downloads, you can use Downloads / Quarantine from Tools if you want to scan the file.",
                                        MessageBoxButton.OK,
                                        MessageBoxImage.Information);

                                    TryRestartAllowedDownload(sourceUri);
                                }
                                else if (choice == DownloadGuardChoice.TrustSite)
                                {
                                    TrustDownloadHost(sourceUri);
                                    _downloadAllowOnce.Add(allowKey);
                                    AddDownloadAllowOnceHost(GetDownloadHost(sourceUri));
                                    AddDownloadAllowOnceHost(GetActivePageHostForDownloadGuard());

                                    ShowProtectionPopup(
                                        "LexDesk Pro - Download Guard",
                                        "Download site trusted",
                                        "This website has been added to your trusted download sites.\n\n" +
                                        "LexDesk Pro will try to start this download now.\n\n" +
                                        "If the download does not start, click the website's download button again.\n\n" +
                                        "After it downloads, you can use Downloads / Quarantine from Tools if you want to scan the file.",
                                        MessageBoxButton.OK,
                                        MessageBoxImage.Information);

                                    TryRestartAllowedDownload(sourceUri);
                                }
                                else
                                {
                                    UpdateSecurityStatus("Download blocked", true);
                                }
                            }
                        }
                        finally
                        {
                            _downloadPromptActive.Remove(allowKey);
                        }
                    }), DispatcherPriority.Background);

                    return;
                }

                if (IsUnknownDownloadExtension(extension))
                {
                    e.Cancel = true;
                    _downloadPromptActive.Add(allowKey);

                    Dispatcher.BeginInvoke(new Action(() =>
                    {
                        try
                        {
                            UpdateSecurityStatus("Download warning", true);

                            var choice = ShowDownloadGuardDecisionPopup(
    "LexDesk Pro - Download Guard",
    "Unknown download type stopped",
    $"File: {fileName}\n" +
    $"Type: {(string.IsNullOrWhiteSpace(extension) ? "No file extension" : extension)}\n\n" +
    $"Source site:\n{sourceHost}\n\n" +
    "This download has an unknown or unclear file type.\n\n" +
    "Unknown file types are harder to judge and may not be safe to open.\n\n" +
    "Choose Allow Once only if you trust this file and website.\n" +
    "After choosing Allow Once, LexDesk Pro will try to start the download automatically.\n\n" +
    "If it does not start, click the website's download button again.",
    allowTrustSite: false);

                            if (choice == DownloadGuardChoice.AllowOnce)
                            {
                                _downloadAllowOnce.Add(allowKey);
                                AddDownloadAllowOnceHost(GetDownloadHost(sourceUri));
                                AddDownloadAllowOnceHost(GetActivePageHostForDownloadGuard());

                                ShowProtectionPopup(
                                    "LexDesk Pro - Download Guard",
                                    "Download allowed once",
                                    "LexDesk Pro will try to start the download now.\n\n" +
                                    "If the download does not start, click the website's download button again.\n\n" +
                                    "After it downloads, you can use Downloads / Quarantine from Tools if you want to scan the file.",
                                    MessageBoxButton.OK,
                                    MessageBoxImage.Information);

                                TryRestartAllowedDownload(sourceUri);
                            }
                            else
                            {
                                UpdateSecurityStatus("Download blocked", true);
                            }
                        }
                        finally
                        {
                            _downloadPromptActive.Remove(allowKey);
                        }
                    }), DispatcherPriority.Background);

                    return;
                }

            }
            catch (Exception ex)
            {
                Console.WriteLine($"Download Guard error: {SanitizeExceptionMessage(ex)}");
            }
        }

        internal enum FileRiskLevel
        {
            Low,
            Medium,
            High
        }

        // ============================================
        // Download Guard Risk Helpers
        // ============================================
        //
        // High-risk:
        // File types that can run programs, change Windows,
        // launch scripts, or directly affect the system.
        //
        // Medium-risk:
        // File types that can hide installers, scripts,
        // macro content, or bundled unsafe files.
        //
        // Unknown:
        // File types with no extension or unclear extensions.
        // These are stopped because the user cannot easily judge
        // what kind of file they are downloading.

        private bool IsHighRiskDownloadExtension(string extension)
        {
            if (string.IsNullOrWhiteSpace(extension))
                return false;

            string[] highRiskExtensions =
            {
        ".exe",
        ".msi",
        ".bat",
        ".cmd",
        ".ps1",
        ".vbs",
        ".scr",
        ".jar",
        ".reg",
        ".iso"
    };

            return highRiskExtensions.Contains(extension);
        }

        private bool LooksLikeDirectDownloadUrl(string url)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(url))
                    return false;

                if (!Uri.TryCreate(url, UriKind.Absolute, out var uri))
                    return false;

                if (!uri.Scheme.Equals("https", StringComparison.OrdinalIgnoreCase) &&
                    !uri.Scheme.Equals("http", StringComparison.OrdinalIgnoreCase))
                    return false;

                string path = uri.AbsolutePath ?? "";
                string ext = Path.GetExtension(path).ToLowerInvariant();

                return IsHighRiskDownloadExtension(ext) ||
                       IsMediumRiskDownloadExtension(ext) ||
                       IsUnknownDownloadExtension(ext);
            }
            catch
            {
                return false;
            }
        }

        private bool IsMediumRiskDownloadExtension(string extension)
        {
            if (string.IsNullOrWhiteSpace(extension))
                return false;

            string[] mediumRiskExtensions =
            {
        ".zip",
        ".rar",
        ".7z",
        ".docm",
        ".xlsm"
    };

            return mediumRiskExtensions.Contains(extension);
        }

        private bool IsUnknownDownloadExtension(string extension)
        {
            string ext = (extension ?? "").Trim().ToLowerInvariant();

            // No extension is suspicious because the user cannot easily see what type of file it is.
            if (string.IsNullOrWhiteSpace(ext))
                return true;

            // Common low-risk file types.
            // These can still be scanned later by Windows/security software, but Download Guard
            // does not need to stop them by default.
            string[] commonLowRiskExtensions =
            {
    ".txt", ".pdf", ".jpg", ".jpeg", ".png", ".gif", ".webp",
    ".mp3", ".mp4", ".mov", ".avi",
    ".csv", ".json", ".xml",
    ".html", ".htm",
    ".css", ".js",
    ".ico", ".svg"
};

            if (commonLowRiskExtensions.Contains(ext))
                return false;

            // High and medium risk are handled by their own checks first.
            if (IsHighRiskDownloadExtension(ext) || IsMediumRiskDownloadExtension(ext))
                return false;

            // Anything else is unknown enough to ask the user.
            return true;
        }

        private FileRiskLevel GetFileRiskLevel(string extension)
        {
            extension = (extension ?? "").Trim().ToLowerInvariant();

            if (IsHighRiskDownloadExtension(extension))
                return FileRiskLevel.High;

            if (IsMediumRiskDownloadExtension(extension))
                return FileRiskLevel.Medium;

            return FileRiskLevel.Low;
        }

        private string GetFileRiskLabel(FileRiskLevel risk)
        {
            return risk switch
            {
                FileRiskLevel.High => "High risk",
                FileRiskLevel.Medium => "Medium risk",
                _ => "Low risk"
            };
        }

        private string GetFileRiskReason(string extension, FileRiskLevel risk)
        {
            extension = (extension ?? "").Trim().ToLowerInvariant();

            return risk switch
            {
                FileRiskLevel.High =>
                    "This file type can run programs, scripts, installers, or system-level commands.",

                FileRiskLevel.Medium =>
                    "This file type may contain hidden installers, scripts, macros, or compressed unsafe content.",

                _ =>
                    "This file type is generally lower risk, but should still only be opened if you trust the source."
            };
        }

        private string CopyFileToQuarantine(string sourceFilePath)
        {
            Directory.CreateDirectory(_quarantineFolderPath);

            string fileName = Path.GetFileName(sourceFilePath);
            string baseName = Path.GetFileNameWithoutExtension(fileName);
            string extension = Path.GetExtension(fileName);

            string safeName = $"{baseName}_{DateTime.Now:yyyyMMdd_HHmmss}{extension}";
            string destinationPath = Path.Combine(_quarantineFolderPath, safeName);

            File.Copy(sourceFilePath, destinationPath, overwrite: false);

            return destinationPath;
        }

        private void HookDangerousNavigationGuard(WebView2 wv)
        {
            if (wv?.CoreWebView2 == null) return;

            wv.CoreWebView2.NavigationStarting += CoreWebView2_DangerousNavigationStarting;
        }

        // ============================================================
        // [[SCRIPT DIALOG SHIELD - METHODS]]
        // Handles website JavaScript alert/confirm/prompt dialogs.
        // Used for nuisance site messages that are not normal HTML popups.
        // ============================================================

        private void HookScriptDialogShield(WebView2 wv)
        {
            if (wv?.CoreWebView2 == null)
                return;

            wv.CoreWebView2.ScriptDialogOpening -= CoreWebView2_ScriptDialogOpening;
            wv.CoreWebView2.ScriptDialogOpening += CoreWebView2_ScriptDialogOpening;
        }

        private void CoreWebView2_ScriptDialogOpening(object? sender, CoreWebView2ScriptDialogOpeningEventArgs e)
        {
            try
            {
                string uri = e.Uri ?? "";
                string message = e.Message ?? "";

                bool isNewsComAu = IsNewsComAuHost(uri);

                bool isNewsComAuNuisance =
                    isNewsComAu &&
                    message.Contains("Oops", StringComparison.OrdinalIgnoreCase) &&
                    message.Contains("Error", StringComparison.OrdinalIgnoreCase) &&
                    (
                        message.Contains("isTrusted", StringComparison.OrdinalIgnoreCase) ||
                        message.Contains("trusted", StringComparison.OrdinalIgnoreCase)
                    );

                if (isNewsComAu)
                {
                    NewsComAuDebugLog(
                        uri,
                        "Script Dialog Shield",
                        isNewsComAuNuisance ? "Suppressed" : "Observed",
                        isNewsComAuNuisance
                            ? "Matched Oops/Error/isTrusted nuisance dialog"
                            : "Script dialog opened but did not match nuisance rule");
                }

                if (isNewsComAuNuisance)
                {
                    e.Accept();
                    return;
                }
            }
            catch
            {
                // Silent by design. Never break browsing.
            }
        }

        private void HookScamShield(WebView2 wv)
        {
            if (wv?.CoreWebView2 == null) return;

            wv.CoreWebView2.NavigationCompleted += CoreWebView2_ScamShieldNavigationCompleted;
        }

        // ============================================================
        // [[ANNOYANCE SHIELD / SMART OVERLAY CONTROL - METHODS]]
        // Hides high-confidence marketing overlays while preserving functional
        // dialogs such as login, payment, postcode/location, dealer, delivery,
        // gallery, map, and booking flows. Generic hides are reversible.
        // ============================================================

        private async Task ApplyAnnoyanceShieldAsync(CoreWebView2 core)
        {
            if (core == null)
                return;

            if (_annoyanceShieldMode == AnnoyanceShieldMode.Off)
                return;

            NewsComAuDebugLog(
    core.Source ?? "",
    "Annoyance Shield",
    "ApplyAnnoyanceShieldAsync called",
    $"Mode: {_annoyanceShieldMode}");

            string mode = _annoyanceShieldMode == AnnoyanceShieldMode.Strict
                ? "strict"
                : "balanced";

            string script = $@"
(function() {{
    try {{
        const mode = '{mode}';

        const accountWords = [
            'login', 'log in', 'sign in', 'signin', 'sign up',
            'create account', 'register', 'my account'
        ];

        const functionalWords = [
            'postcode', 'post code', 'postal code', 'zip code', 'location',
            'your location', 'find dealer', 'find a dealer', 'local dealer',
            'select dealer', 'choose dealer', 'pricing', 'local price',
            'availability', 'delivery', 'deliver to', 'choose store',
            'select store', 'nearest store', 'region', 'suburb'
        ];

        const userIntentWords = [
            ...accountWords,
            'postcode', 'post code', 'postal code', 'location',
            'find dealer', 'find a dealer', 'dealer', 'pricing', 'price',
            'availability', 'delivery', 'store', 'buy', 'checkout',
            'book', 'reserve', 'continue', 'next',
            'gallery', 'photo', 'photos', 'image', 'images',
            'view photo', 'view photos', 'view image', 'view images',
            'expand', 'fullscreen', 'full screen', 'map'
        ];

        const hardSafeWords = [
            'password', 'checkout', 'payment', 'pay now', 'cart', 'basket',
            'booking', 'book now', 'gallery', 'photos', 'photo',
            'images', 'map', 'maps', 'verify', 'verification',
            'security', '2fa', 'two-factor'
        ];

        const strongMarketingWords = [
            'try google chrome', 'get google chrome', 'switch to chrome',
            'download chrome', 'install chrome',
            'newsletter', 'sign up for our newsletter',
            'sign up for free', 'join for free', 'create a free account',
            'save items you like', 'save bikes you like', 'save things you like',
            'save favourite properties', 'save favorite properties',
            'save your searches', 'save your search', 'save searches', 'saved searches',
            'find your saved bikes easily', 'access your free account',
            'get alerts for new listings', 'alerts for new listings',
            'price updates', 'price change updates', 'shortlist', 'get updates',
            'enable notifications', 'turn on notifications',
            'install our app', 'download our app', 'open in app',
            'limited offer', 'special offer', 'exclusive offer',
            'advertisement', 'sponsored', 'promo', 'promotion',
            'join our community', 'take our survey'
        ];

        const softMarketingWords = [
            'subscribe', 'offers', 'deals', 'discount', 'save',
            'updates', 'notifications', 'marketing', 'recommended for you'
        ];

        function textOf(el) {{
            if (!el) return '';

            return (
                (el.innerText || el.textContent || '') + ' ' +
                (el.getAttribute && el.getAttribute('aria-label') || '') + ' ' +
                (el.getAttribute && el.getAttribute('title') || '') + ' ' +
                (el.getAttribute && el.getAttribute('class') || '') + ' ' +
                (el.getAttribute && el.getAttribute('id') || '')
            ).toLowerCase();
        }}

        function hasAny(text, words) {{
            return words.some(w => text.includes(w));
        }}

        function isActuallyVisibleControl(el) {{
            try {{
                if (!el)
                    return false;

                const style = window.getComputedStyle(el);
                if (!style)
                    return false;

                const rect = el.getBoundingClientRect();

                return style.display !== 'none' &&
                       style.visibility !== 'hidden' &&
                       style.opacity !== '0' &&
                       rect.width > 1 &&
                       rect.height > 1;
            }} catch {{
                return false;
            }}
        }}

        function hasFunctionalLocationFields(el, text) {{
            try {{
                const fields = Array.from(el.querySelectorAll(
                    'input[autocomplete=""postal-code""], ' +
                    'input[name*=""postcode"" i], input[id*=""postcode"" i], ' +
                    'input[placeholder*=""postcode"" i], ' +
                    'input[name*=""postal"" i], input[id*=""postal"" i], ' +
                    'input[placeholder*=""postal"" i], ' +
                    'input[name*=""zip"" i], input[id*=""zip"" i], ' +
                    'input[placeholder*=""zip"" i], ' +
                    'input[name*=""location"" i], input[id*=""location"" i], ' +
                    'input[placeholder*=""location"" i], ' +
                    'input[name*=""suburb"" i], input[id*=""suburb"" i], ' +
                    'select[name*=""state"" i], select[id*=""state"" i], select[name*=""region"" i]'
                ));

                if (fields.some(isActuallyVisibleControl))
                    return true;

                const usefulInputs = Array.from(el.querySelectorAll('input, select'))
                    .some(isActuallyVisibleControl);

                return usefulInputs && hasAny(text, functionalWords);
            }} catch {{
                return false;
            }}
        }}

        function hasRealAccountFields(el, text) {{
            try {{
                const passwordFields = Array.from(el.querySelectorAll(
                    'input[type=""password""], input[autocomplete=""current-password""]'
                ));

                if (passwordFields.some(isActuallyVisibleControl))
                    return true;

                const identityFields = Array.from(el.querySelectorAll(
                    'input[type=""email""], input[autocomplete=""username""], input[name*=""user"" i]'
                ));

                const hasVisibleIdentityField = identityFields.some(isActuallyVisibleControl);

                if (!hasVisibleIdentityField || !hasAny(text, accountWords))
                    return false;

                // Email-only newsletter/marketing forms are not a genuine login flow.
                if (hasAny(text, [
                    'newsletter', 'offers', 'discount', 'marketing updates',
                    'save bikes you like', 'save your searches', 'save favourite properties',
                    'save favorite properties', 'price change updates', 'price updates',
                    'access your free account'
                ]))
                    return false;

                return true;
            }} catch {{
                return false;
            }}
        }}

        if (!window.__wppUserFlowTrackerInstalled) {{
            window.__wppUserFlowTrackerInstalled = true;
            window.__wppLastIntentUtc = 0;
            window.__wppLastIntentText = '';
            window.__wppLastIntentKind = '';

            const rememberUserIntent = function(event) {{
                try {{
                    let rawNode = event.target;
                    let node = rawNode;

                    if (node && node.closest) {{
                        node = node.closest(
                            'button, a, [role=""button""], input[type=""submit""], ' +
                            'input[type=""button""], label'
                        ) || node;
                    }}

                    const actionText = textOf(node);

                    // Record the *kind* of action instead of treating every recent click
                    // as permission for every modal. This prevents an unrelated click on a
                    // filter/price control from protecting a later automatic sign-up nag.
                    let intentKind = '';
                    let mediaIntent = false;

                    try {{
                        const mediaNode = rawNode && rawNode.closest
                            ? rawNode.closest(
                                'img, picture, video, canvas, ' +
                                '[data-gallery], [data-lightbox], [data-fancybox], ' +
                                '[class*=""gallery"" i], [class*=""photo"" i], [class*=""image"" i], ' +
                                '[class*=""carousel"" i], [class*=""lightbox"" i], ' +
                                '[class*=""slideshow"" i], [class*=""map"" i]'
                              )
                            : null;

                        mediaIntent = !!mediaNode;
                    }} catch {{ }}

                    if (mediaIntent) {{
    intentKind = 'media';
}} else if (hasAny(actionText, accountWords)) {{
    intentKind = 'account';
}} else if (
    host.includes('realestate.co.nz') &&
    hasAny(actionText, [
        'save',
        'favourite',
        'favorite',
        'shortlist'
    ])
) {{
    // On realestate.co.nz, an explicit Save/Favourite click is a genuine
    // account action. Allow the site's login modal to open normally.
    intentKind = 'account';
}} else if (hasAny(actionText, [
                        'postcode', 'post code', 'postal code', 'zip code',
                        'your location', 'find dealer', 'find a dealer', 'local dealer',
                        'select dealer', 'choose dealer', 'local price', 'view price',
                        'pricing', 'availability', 'delivery', 'deliver to',
                        'choose store', 'select store', 'nearest store', 'suburb', 'region'
                    ])) {{
                        intentKind = 'location';
                    }} else if (hasAny(actionText, [
                        'checkout', 'payment', 'pay now', 'cart', 'basket',
                        'book', 'booking', 'reserve', 'buy now'
                    ])) {{
                        intentKind = 'commerce';
                    }} else if (hasAny(actionText, [
                        'filter', 'filters', 'refine', 'sort'
                    ])) {{
                        intentKind = 'filter';
                    }}

                    if (intentKind) {{
                        window.__wppLastIntentUtc = Date.now();
                        window.__wppLastIntentKind = intentKind;
                        window.__wppLastIntentText = mediaIntent
                            ? ('media: ' + actionText).substring(0, 180)
                            : actionText.substring(0, 180);
                    }}
                }} catch {{ }}
            }};

            document.addEventListener('pointerdown', rememberUserIntent, true);
            document.addEventListener('keydown', function(event) {{
                if (event.key === 'Enter' || event.key === ' ') {{
                    rememberUserIntent(event);
                }}
            }}, true);
        }}

        function recentIntentKind() {{
            if ((Date.now() - (window.__wppLastIntentUtc || 0)) >= 5000)
                return '';

            return window.__wppLastIntentKind || '';
        }}

        function recentIntentMatchesOverlay(el, text) {{
            const kind = recentIntentKind();
            if (!kind)
                return false;

            if (kind === 'media')
                return true;

            if (kind === 'account')
                return hasAny(text, accountWords) || hasRealAccountFields(el, text);

            if (kind === 'location')
                return hasFunctionalLocationFields(el, text) || hasAny(text, functionalWords);

            if (kind === 'commerce')
                return hasAny(text, [
                    'checkout', 'payment', 'pay now', 'cart', 'basket',
                    'booking', 'book now', 'reserve', 'order'
                ]);

            if (kind === 'filter')
                return hasAny(text, ['filter', 'filters', 'refine', 'sort']);

            return false;
        }}

        function isProtectedUserFlow(el, text) {{
            if (hasAny(text, hardSafeWords))
                return true;

            if (hasFunctionalLocationFields(el, text))
                return true;

            if (recentIntentMatchesOverlay(el, text))
                return true;

