            // Ad Slot Cleanup is Strict-only for now.
            // Some news sites dislike cosmetic ad-slot removal in Balanced mode.
            if (mode === 'strict') {{
                runAdSlotCleanup();
            }}
        }}

        runAnnoyanceShield();

