            window.__webProtectAnnoyanceObserver = new MutationObserver(function(mutations) {{
                // Stage 2N.10: inspect newly inserted elements and text nodes, including
                // their ancestor chain. We still avoid rescanning the whole page.
                for (const mutation of mutations) {{
                    if (mutation.type === 'childList') {{
                        for (const node of mutation.addedNodes || []) {{
                            inspectAddedTree(node);
                        }}
                    }} else if (mutation.type === 'characterData') {{
                        inspectAddedTree(mutation.target);
