                    try {{
                        const candidates = document.querySelectorAll(overlayCandidateSelector);
                        runSiteSpecificRules(candidates);
                        runPromoModalCleanup();
                        runGoogleChromePromoCleanup();

                        if (mode === 'strict')
                            runAdSlotCleanup();
