                }}, 350);
            }});

            window.__webProtectAnnoyanceObserver.observe(document.documentElement, {{
                childList: true,
                subtree: true,
                characterData: true
            }});
        }}
    }} catch (e) {{
        // Silent by design. Never break the website.
    }}
}})();
