(function() {
    try {
        const results = [];
        const vw = window.innerWidth || 1;
        const vh = window.innerHeight || 1;

        const items = Array.from(document.querySelectorAll('body *'));

        for (const el of items) {
            if (!el || !el.getBoundingClientRect)
                continue;

            const style = window.getComputedStyle(el);
            const rect = el.getBoundingClientRect();

            if (!rect || rect.width < 40 || rect.height < 40)
                continue;

            const pos = (style.position || '').toLowerCase();
            const pointerEvents = (style.pointerEvents || '').toLowerCase();
            const visibility = (style.visibility || '').toLowerCase();
            const display = (style.display || '').toLowerCase();

            if (display === 'none' || visibility === 'hidden')
                continue;

            const zRaw = style.zIndex || '0';
            const z = parseInt(zRaw);
            const opacity = parseFloat(style.opacity || '1');

            const fixedOrSticky =
                pos === 'fixed' ||
                pos === 'sticky' ||
                pos === 'absolute';

            const large =
                rect.width > vw * 0.45 &&
                rect.height > vh * 0.20;

            const blocksClicks =
                pointerEvents !== 'none';

            const highLayer =
                !isNaN(z) && z >= 10;

            const nearTop =
                rect.top <= vh * 0.20;

            const coversMiddle =
                rect.top < vh * 0.75 &&
                rect.bottom > vh * 0.25;

            if (fixedOrSticky && large && blocksClicks && (highLayer || coversMiddle || nearTop)) {
                const tag = (el.tagName || '').toLowerCase();
                const id = el.id ? ('#' + el.id.substring(0, 24)) : '';
                const cls = el.className && typeof el.className === 'string'
                    ? ('.' + el.className.trim().split(/\s+/).slice(0, 3).join('.')).substring(0, 48)
                    : '';

                results.push(
                    'tag=' + tag +
                    ' id=' + id +
                    ' class=' + cls +
                    ' pos=' + pos +
                    ' z=' + zRaw +
                    ' opacity=' + opacity +
                    ' pointer=' + pointerEvents +
                    ' rect=' + Math.round(rect.width) + 'x' + Math.round(rect.height) +
                    '@' + Math.round(rect.left) + ',' + Math.round(rect.top)
                );
            }

            if (results.length >= 12)
                break;
        }

        return results;
    } catch (e) {
        return ['overlay-scan-error'];
    }
})();
");

