        // ============================================================
        // [[COOKIE CONSENT HELPER - METHODS]]
        // Automatically chooses the least-tracking cookie option when safe.
        // Never clicks Accept All. Does nothing if unsure.
        // ============================================================

        private async Task ApplyCookieConsentHelperAsync(CoreWebView2 core)
        {
            if (core == null)
                return;

            if (_cookieConsentHelperMode == CookieConsentHelperMode.Off)
                return;

            string source = core.Source ?? "";

            // Avoid important flows where an automatic click could interrupt the user.
            if (source.Contains("/checkout", StringComparison.OrdinalIgnoreCase) ||
                source.Contains("/payment", StringComparison.OrdinalIgnoreCase) ||
                source.Contains("/login", StringComparison.OrdinalIgnoreCase) ||
                source.Contains("/signin", StringComparison.OrdinalIgnoreCase) ||
                source.Contains("/sign-in", StringComparison.OrdinalIgnoreCase) ||
                source.Contains("/account", StringComparison.OrdinalIgnoreCase) ||
                source.Contains("/cart", StringComparison.OrdinalIgnoreCase) ||
                source.Contains("/basket", StringComparison.OrdinalIgnoreCase) ||
                source.Contains("/booking", StringComparison.OrdinalIgnoreCase) ||
                source.Contains("/book-now", StringComparison.OrdinalIgnoreCase))
            {
                return;
            }

            string script = @"
(function () {
    try {
        const rejectWords = [
            'reject non-essential',
            'reject non essential',
            'reject optional',
            'reject all',
            'decline all',
            'deny all',
            'essential only',
            'necessary only',
            'only necessary',
            'use necessary cookies only',
            'use essential cookies only'
        ];

        const manageWords = [
            'manage choices',
            'manage options',
            'cookie settings',
            'privacy settings',
            'storage preferences',
            'customise',
            'customize',
            'preferences'
        ];

        const saveWords = [
            'save choices',
            'save settings',
            'confirm choices',
            'confirm my choices',
            'save preferences',
            'save'
        ];

        const acceptAllWords = [
            'accept all',
            'allow all',
            'agree to all',
            'enable all',
            'accept cookies',
            'i accept'
        ];

        const optionalWords = [
            'targeted advertising',
            'personalisation',
            'personalization',
            'analytics',
            'marketing',
            'advertising',
            'performance',
            'social media',
            'measurement',
            'statistics'
        ];

        function visible(el) {
            if (!el) return false;

            const s = window.getComputedStyle(el);
            const r = el.getBoundingClientRect();

            return s.display !== 'none' &&
                   s.visibility !== 'hidden' &&
                   s.opacity !== '0' &&
                   r.width > 20 &&
                   r.height > 10;
        }

        function textOf(el) {
            if (!el) return '';

            return (
                (el.innerText || '') + ' ' +
                (el.textContent || '') + ' ' +
                (el.value || '') + ' ' +
                (el.getAttribute('aria-label') || '') + ' ' +
                (el.getAttribute('title') || '') + ' ' +
                (el.getAttribute('id') || '') + ' ' +
                (el.getAttribute('class') || '')
            ).trim().toLowerCase();
        }

        function hasAny(text, words) {
            return words.some(w => text.includes(w));
        }

        function isAcceptAll(text) {
            return hasAny(text, acceptAllWords);
        }

        function getButtons() {
            return Array.from(document.querySelectorAll(
                'button, input[type=button], input[type=submit], a[role=button], [role=button]'
            ));
        }

        function clickButton(words) {
            const buttons = getButtons();

            for (const btn of buttons) {
                try {
                    if (!visible(btn)) continue;

                    const t = textOf(btn);
                    if (!t) continue;

                    // Privacy rule: never click Accept All style buttons.
                    if (isAcceptAll(t)) continue;

                    if (hasAny(t, words)) {
                        btn.click();
                        return true;
                    }
                } catch { }
            }

            return false;
        }

        function turnOffOptionalToggles() {
            const inputs = Array.from(document.querySelectorAll(
                'input[type=checkbox], input[type=radio], [role=switch]'
            ));

            for (const input of inputs) {
                try {
                    const nearby =
                        textOf(input) + ' ' +
                        textOf(input.closest('label')) + ' ' +
                        textOf(input.parentElement) + ' ' +
                        textOf(input.parentElement ? input.parentElement.parentElement : null);

                    if (!hasAny(nearby, optionalWords))
                        continue;

                    const checked =
                        input.checked === true ||
                        input.getAttribute('aria-checked') === 'true';

                    if (checked)
                        input.click();
                } catch { }
            }
        }

        function runOnce() {
            // Best case: direct least-tracking button is visible.
            if (clickButton(rejectWords))
                return 'cookie-helper:least-option-clicked';

            // Second case: open manage/settings, then try again.
            if (clickButton(manageWords)) {
                setTimeout(function () {
                    try {
                        turnOffOptionalToggles();

                        if (!clickButton(rejectWords))
                            clickButton(saveWords);
                    } catch { }
                }, 450);

                return 'cookie-helper:manage-opened';
            }

            // Third case: toggles are already visible.
            turnOffOptionalToggles();

            if (clickButton(saveWords))
                return 'cookie-helper:saved-minimal';

            return 'cookie-helper:no-safe-choice';
        }

        const first = runOnce();

        // Some cookie banners appear late after page load.
        setTimeout(runOnce, 750);
        setTimeout(runOnce, 1800);

        return first;
    } catch {
        return 'cookie-helper:error-silent';
    }
})();
";

            try
            {
                await core.ExecuteScriptAsync(script);
            }
            catch
            {
                // Never break page loading.
            }
        }

        // ============================================================
        // [[REALESTATE.CO.NZ PROMO MODAL KNOCKOUT]]
        // Removes the realestate.co.nz "Log in to save" promotional modal.
        // Does not click Sign up or Log in.
        // ============================================================

        private async Task ApplyRealestateNzModalKnockoutAsync(CoreWebView2 core)
        {
            if (core == null)
                return;

            string source = core.Source ?? "";

            if (!source.Contains("realestate.co.nz", StringComparison.OrdinalIgnoreCase))
                return;

            string script = @"
(function () {
    try {
        if (!location.hostname.toLowerCase().includes('realestate.co.nz'))
            return 'realestate-nz:not-host';

        function cleanText(value) {
            return ((value || '') + '')
                .replace(/\s+/g, ' ')
                .trim()
                .toLowerCase();
        }

        function textOf(el) {
            if (!el) return '';
            return cleanText(
                (el.innerText || '') + ' ' +
                (el.textContent || '') + ' ' +
                (el.getAttribute('aria-label') || '') + ' ' +
                (el.getAttribute('class') || '') + ' ' +
                (el.getAttribute('id') || '')
            );
        }

        function hasTargetText(el) {
            const text = textOf(el);

            return text.includes('log in to save') &&
                   text.includes('matching properties') &&
                   text.includes('sign up') &&
                   text.includes('log in');
        }

        function hideHard(el) {
            try {
                if (!el) return false;

                el.setAttribute('data-web-protect-pro-hidden', 'realestate-nz-login-save-modal');

                el.style.setProperty('display', 'none', 'important');
                el.style.setProperty('visibility', 'hidden', 'important');
                el.style.setProperty('opacity', '0', 'important');
                el.style.setProperty('pointer-events', 'none', 'important');
                el.style.setProperty('z-index', '-1', 'important');

                try { el.remove(); } catch { }

                return true;
            } catch {
                return false;
            }
        }

        function unlockPage() {
            try {
                document.documentElement.style.setProperty('overflow', 'auto', 'important');
                document.documentElement.style.setProperty('pointer-events', 'auto', 'important');

                if (document.body) {
                    document.body.style.setProperty('overflow', 'auto', 'important');
                    document.body.style.setProperty('pointer-events', 'auto', 'important');
                }
            } catch { }
        }

        function killOnce() {
            let removed = 0;

            try {
                const selectors = [
                    '#modal-overlays .ember-modal-wrapper',
                    '.ember-modal-wrapper.emd-wrapper-target-attach',
                    '.ember-modal-wrapper',
                    '.ember-modal-overlay.translucent',
                    '.ember-modal-dialog',
                    '#modal-overlays'
                ];

                for (const selector of selectors) {
                    const items = Array.from(document.querySelectorAll(selector));

                    for (const el of items) {
                        try {
                            if (!hasTargetText(el))
                                continue;

                            if (hideHard(el))
                                removed++;
                        } catch { }
                    }
                }

                // Fallback: find exact text anywhere and climb to the Ember wrapper.
                if (removed === 0) {
                    const nodes = Array.from(document.querySelectorAll('body *'));

                    for (const el of nodes) {
                        try {
                            if (!hasTargetText(el))
                                continue;

                            let current = el;

                            for (let i = 0; i < 12 && current && current !== document.body; i++) {
                                const cls = (current.getAttribute('class') || '').toLowerCase();
                                const id = (current.getAttribute('id') || '').toLowerCase();
                                const style = window.getComputedStyle(current);
                                const rect = current.getBoundingClientRect();

                                const isTargetShell =
                                    id === 'modal-overlays' ||
                                    cls.includes('ember-modal-wrapper') ||
                                    cls.includes('ember-modal-overlay') ||
                                    cls.includes('ember-modal-dialog') ||
                                    (
                                        style.position === 'fixed' &&
                                        rect.width > window.innerWidth * 0.65 &&
                                        rect.height > window.innerHeight * 0.65
                                    );

                                if (isTargetShell) {
                                    if (hideHard(current))
                                        removed++;

                                    break;
                                }

                                current = current.parentElement;
                            }
                        } catch { }
                    }
                }

                if (removed > 0)
                    unlockPage();

                return removed;
            } catch {
                return removed;
            }
        }

        const first = killOnce();

        // realestate.co.nz can inject this late or recreate it.
        const delays = [100, 300, 700, 1200, 2000, 3500, 5500, 8000, 11000];

        for (const delay of delays) {
            setTimeout(killOnce, delay);
        }

        try {
            const obs = new MutationObserver(function () {
                killOnce();
            });

            obs.observe(document.documentElement || document.body, {
                childList: true,
                subtree: true
            });

            setTimeout(function () {
                try { obs.disconnect(); } catch { }
            }, 12000);
        } catch { }

        return 'realestate-nz:knockout-installed:' + first;
    } catch {
        return 'realestate-nz:error-silent';
    }
})();
";

            try
            {
                await core.ExecuteScriptAsync(script);
            }
            catch
            {
                // Never break browsing.
            }
        }

        private async void CoreWebView2_ScamShieldNavigationCompleted(
    object? sender,
    CoreWebView2NavigationCompletedEventArgs e)
        {
            try
            {
                if (sender is not CoreWebView2 core)
                    return;

                string currentUrl = core.Source ?? "";

                if (_siteDiagnosticMode)
                {
                    long elapsedMs = -1;

                    if (_siteDiagnosticNavigationStartedUtc.TryGetValue(core, out DateTime startedUtc))
                    {
                        elapsedMs = Math.Max(0, (long)(DateTime.UtcNow - startedUtc).TotalMilliseconds);
                        _siteDiagnosticNavigationStartedUtc.Remove(core);
                    }

                    AddSiteDiagnosticEventForPage(
                        currentUrl,
                        $"NAVIGATION completed success={e.IsSuccess} webError={e.WebErrorStatus} elapsedMs={elapsedMs}");

                    if (e.IsSuccess)
                    {
                        await RegisterSiteDiagnosticsEarlyAsync(core);
                        _ = ScheduleSiteDiagnosticPerformanceSnapshotsAsync(core, currentUrl);
                    }
                }

                if (!e.IsSuccess)
                    return;

                if (string.IsNullOrWhiteSpace(currentUrl))
                    return;

                if (_scamShieldWarnedUrls.Contains(currentUrl))
                    return;

                string pageTextJson = await core.ExecuteScriptAsync(@"
            (function() {
                try {
                    const text = (document.body && document.body.innerText)
                        ? document.body.innerText
                        : '';
                    return text.substring(0, 12000);
                } catch {
                    return '';
                }
            })();
        ");

                string pageText = "";

                try
                {
                    pageText = JsonSerializer.Deserialize<string>(pageTextJson) ?? "";
                }
                catch
                {
                    pageText = pageTextJson ?? "";
                }

                if (IsScamLikePage(pageText, currentUrl, out string reason))
                {
                    _scamShieldWarnedUrls.Add(currentUrl);

                    _ = Dispatcher.BeginInvoke(new Action(() =>
                    {
                        UpdateSecurityStatus("Possible scam page detected", true);

                        ShowProtectionPopup(
    "LexDesk Pro - Scam Shield",
    "Possible scam page detected",
    $"Reason: {reason}\n\n" +
    $"Page:\n{currentUrl}\n\n" +
    $"This may be a fake support, fake virus, or scare-warning page. Do not call phone numbers or install downloads unless you fully trust the website.",
    MessageBoxButton.OK,
    MessageBoxImage.Warning);
                    }), DispatcherPriority.Background);
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Scam Shield error: {SanitizeExceptionMessage(ex)}");
            }

            // [[ANNOYANCE SHIELD / COOKIE HELPER - APPLY AFTER PAGE LOAD]]
            try
            {
                if (sender is CoreWebView2 core && ShouldRunPageHelpers(core))
                {
                    // Small delay lets the page settle first and avoids fighting the page during first paint.
                    await Task.Delay(350);

                    await ApplyAnnoyanceShieldAsync(core);
                    await ApplyCookieConsentHelperAsync(core);

                    // realestate.co.nz is handled inside Annoyance Shield's targeted
                    // promo cleanup. Do not run the older standalone knockout here: it can
                    // remove the reusable #modal-overlays host and break later photo galleries.
                }
            }
            catch
            {
                // Silent by design.
                // Page helpers should never break browsing.
            }

        }

        private bool IsScamLikePage(string pageText, string url, out string reason)
        {
            reason = "";

            string text = ((pageText ?? "") + " " + (url ?? "")).ToLowerInvariant();

            if (string.IsNullOrWhiteSpace(text))
                return false;

            string[] strongScamPhrases =
            {
        "your computer is infected",
        "your pc is infected",
        "virus detected",
        "trojan detected",
        "call microsoft support",
        "microsoft support number",
        "do not close this page",
        "your computer has been blocked",
        "your pc has been blocked",
        "windows defender security warning",
        "security alert",
        "install update now",
        "critical security warning"
    };

            string[] supportingScamWords =
            {
        "call now",
        "toll free",
        "support agent",
        "remote access",
        "anydesk",
        "teamviewer",
        "ultraviewer",
        "bank account locked",
        "subscription expired",
        "renew immediately"
    };

            int strongHits = 0;
            int supportHits = 0;

            foreach (string phrase in strongScamPhrases)
            {
                if (text.Contains(phrase))
                    strongHits++;
            }

            foreach (string phrase in supportingScamWords)
            {
                if (text.Contains(phrase))
                    supportHits++;
            }

            if (strongHits >= 2)
            {
                reason = "Multiple fake security/support warning phrases were detected.";
                return true;
            }

            if (strongHits >= 1 && supportHits >= 1)
            {
                reason = "Fake security wording appeared together with support/contact pressure.";
                return true;
            }

            return false;
        }

        private void HookPermissionShield(WebView2 wv)
        {
            if (wv?.CoreWebView2 == null) return;

            wv.CoreWebView2.PermissionRequested += CoreWebView2_PermissionRequested;
        }

        private void CoreWebView2_PermissionRequested(
         object? sender,
         CoreWebView2PermissionRequestedEventArgs e)
        {
            try
            {
                string uri = e.Uri ?? "";
                string host = "";

                try
                {
                    if (Uri.TryCreate(uri, UriKind.Absolute, out var parsed))
                        host = parsed.Host.Replace("www.", "");
                }
                catch
                {
                    host = "";
                }

                string siteLabel = string.IsNullOrWhiteSpace(host) ? uri : host;

                string permissionLabel = e.PermissionKind switch
                {
                    CoreWebView2PermissionKind.Camera => "camera",
                    CoreWebView2PermissionKind.Microphone => "microphone",
                    CoreWebView2PermissionKind.Geolocation => "location",
                    CoreWebView2PermissionKind.Notifications => "notifications",
                    CoreWebView2PermissionKind.ClipboardRead => "clipboard read",
                    _ => e.PermissionKind.ToString()
                };

                if (IsSitePermissionAllowed(host, e.PermissionKind))
                {
                    e.State = CoreWebView2PermissionState.Allow;
                    e.Handled = true;
                    Dispatcher.BeginInvoke(new Action(() =>
                        UpdateSecurityStatus($"{permissionLabel} allowed for this site", false)),
                        DispatcherPriority.Background);
                    return;
                }

                bool shouldBlock =
                    e.PermissionKind == CoreWebView2PermissionKind.Camera ||
                    e.PermissionKind == CoreWebView2PermissionKind.Microphone ||
                    e.PermissionKind == CoreWebView2PermissionKind.Geolocation ||
                    e.PermissionKind == CoreWebView2PermissionKind.Notifications ||
                    e.PermissionKind == CoreWebView2PermissionKind.ClipboardRead;

                if (!shouldBlock)
                    return;

                e.State = CoreWebView2PermissionState.Deny;
                e.Handled = true;

                Dispatcher.BeginInvoke(new Action(() =>
                {
                    UpdateSecurityStatus("Permission blocked", true);

                    ShowProtectionPopup(
                        "LexDesk Pro - Permission Shield",
                        "Permission request blocked",
                        $"LexDesk Pro blocked a {permissionLabel} permission request.\n\n" +
                        $"Website: {siteLabel}\n\n" +
                        "Websites do not need this permission unless you clearly choose to use that feature.\n\n" +
                        "Blocking unexpected permission requests helps reduce fake alerts, tracking, scams, and unwanted access.",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                }), DispatcherPriority.Background);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Permission Shield error: {SanitizeExceptionMessage(ex)}");
            }
        }

        private void CoreWebView2_DangerousNavigationStarting(
    object? sender,
    CoreWebView2NavigationStartingEventArgs e)
        {
            try
            {
                string uriText = e.Uri ?? "";

                if (string.IsNullOrWhiteSpace(uriText))
                    return;

                if (IsDangerousUriScheme(uriText, out string dangerousReason))
                {
                    e.Cancel = true;

                    NewsComAuDebugLog(
    uriText,
    "Link Shield",
    "Blocked",
    dangerousReason);

                    Dispatcher.BeginInvoke(new Action(() =>
                    {
                        UpdateSecurityStatus("Dangerous link blocked", true);

                        ShowProtectionPopup(
                            "LexDesk Pro - Link Shield",
                            "Dangerous link blocked",
                            $"{dangerousReason}\n\n" +
                            $"Address:\n{uriText}\n\n" +
                            "This type of link can be abused by scam pages, browser hijackers, or malicious scripts.",
                            MessageBoxButton.OK,
                            MessageBoxImage.Warning);
                    }), DispatcherPriority.Background);

                    return;
                }

                if (IsManualBlockedSite(uriText, out string manualBlockedHost))
                {
                    e.Cancel = true;

                    Dispatcher.BeginInvoke(new Action(() =>
                    {
                        UpdateSecurityStatus("Website blocked", true);

                        ShowProtectionPopup(
                            "LexDesk Pro - Blocked Site List",
                            "Website blocked",
                            $"LexDesk Pro blocked this website.\n\n" +
                            $"This site is on your Blocked Site List.\n\n" +
                            $"Website:\n{manualBlockedHost}",
                            MessageBoxButton.OK,
                            MessageBoxImage.Warning);
                    }), DispatcherPriority.Background);

                    return;
                }

                if (IsRedirectStorm(uriText))
                {
                    e.Cancel = true;

                    string host = GetHostFromUrl(uriText).Replace("www.", "").ToLowerInvariant();

                    NewsComAuDebugLog(
    uriText,
    "Redirect Shield",
    "Blocked",
    "Redirect storm detected");

                    Dispatcher.BeginInvoke(new Action(() =>
                    {
                        UpdateSecurityStatus("Redirect storm blocked", true);

                        if (_redirectStormWarnedHosts.Add(host))
                        {
                            ShowProtectionPopup(
    "LexDesk Pro - Redirect Shield",
    "Suspicious redirects blocked",
    $"Website: {host}\n\n" +
    $"This site redirected too many times in a short period. Scam pages and browser hijackers often use this behaviour.",
    MessageBoxButton.OK,
    MessageBoxImage.Warning);
                        }
                    }), DispatcherPriority.Background);

                    return;
                }

                if (IsDangerousNavigation(uriText, out string reason))
                {
                    e.Cancel = true;

                    NewsComAuDebugLog(
    uriText,
    "Site Shield",
    "Blocked",
    reason);

                    Dispatcher.BeginInvoke(new Action(() =>
                    {
                        UpdateSecurityStatus("Unsafe navigation blocked", true);

                        ShowProtectionPopup(
    "LexDesk Pro - Site Shield",
    "Unsafe website action blocked",
    $"Reason: {reason}\n\n" +
    $"Address:\n{uriText}\n\n" +
    $"This type of link can be used by scam pages, browser hijackers, or malicious scripts.",
    MessageBoxButton.OK,
    MessageBoxImage.Warning);
                    }), DispatcherPriority.Background);
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Dangerous Navigation Guard error: {SanitizeExceptionMessage(ex)}");
            }
        }

        private bool IsDangerousNavigation(string uriText, out string reason)
        {
            reason = "";

            if (string.IsNullOrWhiteSpace(uriText))
                return false;

            string trimmed = uriText.Trim();

            string lower = trimmed.ToLowerInvariant();

            string[] blockedPrefixes =
            {
        "javascript:",
        "data:",
        "file:",
        "cmd:",
        "powershell:",
        "wscript:",
        "mshta:",
        "ms-settings:",
        "shell:",
        "vbscript:"
    };

            foreach (string prefix in blockedPrefixes)
            {
                if (lower.StartsWith(prefix))
                {
                    reason = $"Blocked risky link type: {prefix}";
                    return true;
                }
            }

            // Let normal web downloads pass through to Download Guard.
            // Site Shield should block dangerous schemes, not ordinary http/https downloads.
            try
            {
                if (Uri.TryCreate(trimmed, UriKind.Absolute, out var uri))
                {
                    bool isWebDownload =
                        uri.Scheme.Equals("http", StringComparison.OrdinalIgnoreCase) ||
                        uri.Scheme.Equals("https", StringComparison.OrdinalIgnoreCase);

                    if (isWebDownload)
                        return false;
                }
            }
            catch
            {
                // If parsing fails, do not block here.
                // Download Guard still handles actual downloads.
            }

            return false;
        }

        private void HookNewWindow(WebView2 wv)
        {
            if (wv?.CoreWebView2 == null) return;

            wv.CoreWebView2.NewWindowRequested += (s, e) =>
            {
                var popupUrl = e.Uri ?? "";
                var openerUrl = "";

                try
                {
                    openerUrl = wv.CoreWebView2.Source ?? "";
                }
                catch { }

                AddSiteDiagnosticEventForPage(
                    openerUrl,
                    $"NEW_WINDOW requested popup={GetSiteDiagnosticHost(popupUrl)} userInitiated={e.IsUserInitiated}");

                // Trusted government/login/print popups sometimes start as about:blank.
                // Let WebView2 open the real new window for those trusted cases.
                if (ShouldLetTrustedSiteOpenRealWindow(openerUrl, popupUrl, e.IsUserInitiated))
                {
                    e.Handled = false;
                    AddSiteDiagnosticEventForPage(openerUrl, "NEW_WINDOW decision=allow-real-window reason=trusted-site");
                    UpdateSecurityStatus("Trusted site window opened", false);
                    return;
                }

                e.Handled = true;

                if (string.IsNullOrWhiteSpace(popupUrl))
                {
                    AddSiteDiagnosticEventForPage(openerUrl, "NEW_WINDOW decision=block reason=blank-popup");
                    UpdateSecurityStatus("Blank popup blocked", true);
                    return;
                }

                if (LooksLikeDirectDownloadUrl(popupUrl))
                {
                    AddSiteDiagnosticEventForPage(openerUrl, "NEW_WINDOW decision=allow-in-pane reason=direct-download");
                    try
                    {
                        wv.CoreWebView2.Navigate(popupUrl);
                        UpdateSecurityStatus("Download link opened", false);
                    }
                    catch
                    {
                        NavigateTo(popupUrl);
                    }

                    return;
                }

                if (IsPopupStorm(openerUrl, popupUrl))
                {
                    AddSiteDiagnosticEventForPage(openerUrl, "NEW_WINDOW decision=block reason=popup-storm");
                    UpdateSecurityStatus("Popup storm blocked", true);

                    string openerHost = GetHostFromUrl(openerUrl).Replace("www.", "").ToLowerInvariant();
                    string popupHost = GetHostFromUrl(popupUrl).Replace("www.", "").ToLowerInvariant();
                    string warningHost = string.IsNullOrWhiteSpace(openerHost) ? popupHost : openerHost;

                    if (_popupStormWarnedHosts.Add(warningHost))
                    {
                        Dispatcher.BeginInvoke(new Action(() =>
                        {
                            ShowProtectionPopup(
     "LexDesk Pro - Popup Storm Shield",
     "Repeated popups blocked",
     $"Website: {warningHost}\n\n" +
     $"This site tried to open several popups quickly. Scam pages and browser hijackers often use this behaviour.",
     MessageBoxButton.OK,
     MessageBoxImage.Warning);
                        }), DispatcherPriority.Background);
                    }

                    return;
                }

                bool popupAllowed = ShouldAllowPopup(popupUrl, openerUrl, e.IsUserInitiated);
                bool allowedByTemporaryUserChoice = false;

                // Stage 4C.4 - Temporary Trusted Interaction.
                // Block All should still stop automatic popups, but a genuine user click
                // gets one narrow escape hatch. Allow Once permits only this exact
                // NewWindowRequested action. It does not change Privacy Mode, Popup
                // Control, tracker blocking or any saved site permission.
                if (!popupAllowed &&
                    e.IsUserInitiated &&
                    _popupMode == PopupMode.BlockAll)
                {
                    AddSiteDiagnosticEventForPage(
                        openerUrl,
                        $"NEW_WINDOW prompt reason=user-initiated-block-all popup={GetSiteDiagnosticHost(popupUrl)}");

                    var userChoice = ShowUserInitiatedPopupDecisionPopup(
                        openerUrl,
                        popupUrl,
                        allowPermanentSitePermission: HasFullUnlock());

                    if (userChoice == UserInitiatedPopupChoice.AllowOnce)
                    {
                        popupAllowed = true;
                        allowedByTemporaryUserChoice = true;

                        AddSiteDiagnosticEventForPage(
                            openerUrl,
                            "NEW_WINDOW decision=allow-once reason=user-initiated");
                    }
                    else if (userChoice == UserInitiatedPopupChoice.AlwaysAllowSite)
                    {
                        string permissionHost = GetHostFromUrl(openerUrl)
                            .Replace("www.", "")
                            .Trim()
                            .ToLowerInvariant();

                        if (string.IsNullOrWhiteSpace(permissionHost))
                        {
                            permissionHost = GetHostFromUrl(popupUrl)
                                .Replace("www.", "")
                                .Trim()
                                .ToLowerInvariant();
                        }

                        if (!string.IsNullOrWhiteSpace(permissionHost))
                        {
                            _popupWhitelist.Add(permissionHost);
                            SavePopupWhitelist();
                            popupAllowed = true;

                            AddSiteDiagnosticEventForPage(
                                openerUrl,
                                $"NEW_WINDOW decision=allow-and-save-popup-site host={permissionHost}");

                            UpdateSecurityStatus("Popup permission saved for this site", false);
                        }
                    }
                    else
                    {
                        AddSiteDiagnosticEventForPage(
                            openerUrl,
                            "NEW_WINDOW decision=block reason=user-cancelled");
                    }
                }

                if (!popupAllowed)
                {
                    AddSiteDiagnosticEventForPage(openerUrl, "NEW_WINDOW decision=block reason=popup-policy");
                    UpdateSecurityStatus("Popup blocked", true);
                    return;
                }

                try
                {
                    AddSiteDiagnosticEventForPage(
                        openerUrl,
                        allowedByTemporaryUserChoice
                            ? "NEW_WINDOW decision=allow-in-pane reason=allow-once"
                            : "NEW_WINDOW decision=allow-in-pane reason=popup-policy");

                    wv.CoreWebView2.Navigate(popupUrl);

                    UpdateSecurityStatus(
                        allowedByTemporaryUserChoice
                            ? "Requested page opened once"
                            : "Popup opened safely",
                        false);
                }
                catch
                {
                    NavigateTo(popupUrl);
                }
            };

            wv.CoreWebView2.NavigationCompleted += async (_, __) =>
            {
                Dispatcher.Invoke(UpdateSecureSiteVisual);

                try
                {
                    await wv.ExecuteScriptAsync(@"
        (function() {
        const host = location.hostname.toLowerCase();
        let css = '';
" + (_cleanSearchEnabled ? @"
        if (true) {
" : @"
        if (false) {
") + @"
            if (host.includes('google.')) {
                css += `
                [data-text-ad],
                [data-text-ad-preview],
                [aria-label='Ads'],
                [aria-label='Sponsored'],
                a[href*='aclk?'],
                .commercial-unit-desktop-top,
                .commercial-unit-desktop-rhs,
                .uEierd,
                .pla-unit,
                .cu-container {
                    display: none !important;
                    visibility: hidden !important;
                    height: 0 !important;
                    min-height: 0 !important;
                    margin: 0 !important;
                    padding: 0 !important;
                }
                `;
            }

            if (host.includes('bing.')) {
                css += `
                .b_ad,
                .ads_cont,
                .ad_sc,
                [aria-label='Sponsored results'],
                a[href*='clk?'] {
                    display: none !important;
                    visibility: hidden !important;
                    height: 0 !important;
                    min-height: 0 !important;
                    margin: 0 !important;
                    padding: 0 !important;
                }
                `;
            }

            if (host.includes('duckduckgo.')) {
                css += `
                [data-testid='ad'],
                .results--ads,
                .result--ad,
                .badge--ad {
                    display: none !important;
                    visibility: hidden !important;
                    height: 0 !important;
                    min-height: 0 !important;
                    margin: 0 !important;
                    padding: 0 !important;
                }
                `;
            }
        }

                            if (host.includes('google.'))
{
    css += `
    [aria-label='Choose Chrome'],
    [aria-label*='Choose Chrome'],
    [aria-label*='Chrome'],
    [data-promo],
    [data-testid*='promo'],
    [id*='promo'],
    [class*='promo'],
    [class*='upsell'],
    [class*='install'],
    [class*='browser-upgrade'],
    [class*='choose-browser'],
    a[href*='chrome'],
    a[href*='google.com/chrome'],
    a[href*='chrome/browser'],
    div[role='dialog'],
    div[aria-modal='true'] {
        display: none !important;
        visibility: hidden !important;
        opacity: 0 !important;
        pointer-events: none !important;
    }

    body {
        overflow: auto !important;
    }
    `;
}


                                if (!css)
                                return;

                                const style = document.createElement('style');
                                style.textContent = css;
                                document.head.appendChild(style);
                            })();
                       ");

                    // Stage 4C: catch Google sponsored blocks that are inserted
                    // dynamically after the initial search page has rendered.
                    await InjectGoogleSponsoredSearchCleanupAsync(wv);
                }
                catch { }
            };

        }

        // ============================================
        // Stage 4C - Google Sponsored Search Cleanup
        // ============================================
        // Clean Search already removes known search-ad selectors. Google can also
        // render sponsored blocks dynamically after NavigationCompleted, so this
        // adds a conservative DOM pass plus a lightweight MutationObserver.
        //
        // Safety rules:
        // - Google Search result pages only (never Gemini, Accounts, Maps, etc.).
        // - Only clearly labelled Ad / Ads / Sponsored content is considered.
        // - Never remove the search form, main results container, or whole page.
        // - Hide the smallest plausible sponsored result container instead of
        //   deleting arbitrary content that merely contains the word "ad".
        private async Task InjectGoogleSponsoredSearchCleanupAsync(WebView2? wv)
        {
            if (!_cleanSearchEnabled || wv?.CoreWebView2 == null)
                return;

            try
            {
                string source = wv.CoreWebView2.Source ?? "";

                if (!Uri.TryCreate(source, UriKind.Absolute, out Uri? uri))
                    return;

                string host = (uri.Host ?? "").Trim().ToLowerInvariant();
                string path = uri.AbsolutePath ?? "";

                bool googleSearchHost =
                    host.Equals("google.com", StringComparison.OrdinalIgnoreCase) ||
                    host.StartsWith("google.", StringComparison.OrdinalIgnoreCase) ||
                    host.StartsWith("www.google.", StringComparison.OrdinalIgnoreCase);

                if (!googleSearchHost ||
                    !path.StartsWith("/search", StringComparison.OrdinalIgnoreCase))
                {
                    return;
                }

                await wv.ExecuteScriptAsync(@"
(function () {
    try {
        const host = (location.hostname || '').toLowerCase();
        const path = location.pathname || '';

        const isGoogleSearch =
            (host === 'google.com' || host.startsWith('google.') || host.startsWith('www.google.')) &&
            path.startsWith('/search');

        if (!isGoogleSearch)
            return 0;

        const hiddenAttr = 'data-wpp-clean-search-hidden';
        const exactAdLabels = new Set(['sponsored', 'ad', 'ads']);

        function isVisible(el) {
            try {
                if (!el || !el.getBoundingClientRect)
                    return false;

                const style = window.getComputedStyle(el);
                const rect = el.getBoundingClientRect();

                return style.display !== 'none' &&
                       style.visibility !== 'hidden' &&
                       rect.width > 0 &&
                       rect.height > 0;
            } catch {
                return false;
            }
        }

        function exactLabel(el) {
            try {
                const aria = (el.getAttribute && el.getAttribute('aria-label') || '')
                    .trim().toLowerCase();

                if (exactAdLabels.has(aria))
                    return aria;

                // Only use compact elements for text fallback. This prevents a
                // large result wrapper whose combined text happens to include
                // ""Sponsored"" from being treated as the label itself.
                if ((el.children?.length || 0) > 4)
                    return '';

                const text = (el.textContent || '')
                    .replace(/\s+/g, ' ')
                    .trim().toLowerCase();

                return exactAdLabels.has(text) ? text : '';
            } catch {
                return '';
            }
        }

        function isProtectedPageContainer(el) {
            try {
                if (!el)
                    return true;

                if (el === document.body || el === document.documentElement)
                    return true;

                const tag = (el.tagName || '').toLowerCase();
                if (tag === 'main')
                    return true;

                if (el.id === 'search' || el.id === 'rcnt' || el.id === 'center_col')
                    return true;

                if (el.getAttribute?.('role') === 'main')
                    return true;

                // The search box must never be swallowed by an ad cleanup rule.
                if (el.querySelector?.(""input[name='q'], textarea[name='q']""))
                    return true;
            } catch { }

            return false;
        }

        function hasStrongAdMarker(el) {
            try {
                return !!(
                    el.matches?.('[data-text-ad], [data-text-ad-preview], .uEierd, .commercial-unit-desktop-top, .commercial-unit-desktop-rhs, .pla-unit') ||
                    el.querySelector?.('[data-text-ad], [data-text-ad-preview], .uEierd, a[href*=""/aclk?""], a[href*=""googleadservices.com""]')
                );
            } catch {
                return false;
            }
        }

        function plausibleSponsoredContainer(el) {
            try {
                if (!el || isProtectedPageContainer(el) || !isVisible(el))
                    return false;

                const rect = el.getBoundingClientRect();
                const vh = window.innerHeight || 900;

                if (rect.width < 160 || rect.height < 45)
                    return false;

                if (rect.height > Math.min(900, vh * 0.82))
                    return false;

                const links = el.querySelectorAll?.('a[href]')?.length || 0;
                if (links < 1 || links > 40)
                    return false;

                return true;
            } catch {
                return false;
            }
        }

        function findSponsoredContainer(labelEl) {
            try {
                // Prefer Google's explicit ad containers when available.
                const explicit = labelEl.closest?.(
                    '[data-text-ad], [data-text-ad-preview], .uEierd, .commercial-unit-desktop-top, .commercial-unit-desktop-rhs, .pla-unit'
                );

                if (explicit && !isProtectedPageContainer(explicit))
                    return explicit;

                let current = labelEl;
                let fallback = null;

                for (let depth = 0; depth < 8 && current; depth++) {
                    current = current.parentElement;
                    if (!current || isProtectedPageContainer(current))
                        break;

                    if (!plausibleSponsoredContainer(current))
                        continue;

                    if (hasStrongAdMarker(current))
                        return current;

                    // An exact Google-rendered Sponsored / Ad / Ads label is
                    // strong evidence, but keep the smallest plausible ancestor
                    // as fallback so normal result groups remain untouched.
                    if (!fallback)
                        fallback = current;
                }

                return fallback;
            } catch {
                return null;
            }
        }

        function hideSponsoredContainer(el) {
            try {
                if (!el || isProtectedPageContainer(el))
                    return false;

                if (el.getAttribute?.(hiddenAttr) === 'google-sponsored')
                    return false;

                el.setAttribute(hiddenAttr, 'google-sponsored');
                el.style.setProperty('display', 'none', 'important');
                el.style.setProperty('visibility', 'hidden', 'important');
                el.style.setProperty('opacity', '0', 'important');
                el.style.setProperty('pointer-events', 'none', 'important');
                el.style.setProperty('height', '0', 'important');
                el.style.setProperty('min-height', '0', 'important');
                el.style.setProperty('margin', '0', 'important');
                el.style.setProperty('padding', '0', 'important');
                el.style.setProperty('overflow', 'hidden', 'important');
                return true;
            } catch {
                return false;
            }
        }

        function inspectElement(el) {
            try {
                if (!el || el.nodeType !== 1)
                    return 0;

                let hidden = 0;

                // Explicit markers first. These are high confidence and cheap.
                const explicit = [];
                if (el.matches?.('[data-text-ad], [data-text-ad-preview], .uEierd, .commercial-unit-desktop-top, .commercial-unit-desktop-rhs, .pla-unit'))
                    explicit.push(el);

                el.querySelectorAll?.('[data-text-ad], [data-text-ad-preview], .uEierd, .commercial-unit-desktop-top, .commercial-unit-desktop-rhs, .pla-unit')
                    .forEach(x => explicit.push(x));

                for (const candidate of explicit) {
                    if (!isProtectedPageContainer(candidate) && hideSponsoredContainer(candidate))
                        hidden++;
                }

                // Fallback for Google's newer markup: only exact visible labels.
                const labelled = [];

                if (exactLabel(el))
                    labelled.push(el);

                el.querySelectorAll?.('[aria-label=""Sponsored""], [aria-label=""Ads""], [aria-label=""Ad""], span, div')
                    .forEach(x => {
                        if (exactLabel(x))
                            labelled.push(x);
                    });

                for (const label of labelled) {
                    if (!isVisible(label))
                        continue;

                    const container = findSponsoredContainer(label);
                    if (container && hideSponsoredContainer(container))
                        hidden++;
                }

                return hidden;
            } catch {
                return 0;
            }
        }

        function cleanDocument() {
            try {
                return inspectElement(document.body || document.documentElement);
            } catch {
                return 0;
            }
        }

        window.__wppGoogleSponsoredCleanupRun = cleanDocument;

        let initialHidden = cleanDocument();

        // Google often adds sponsored modules after the first paint.
        [350, 900, 1800, 3200].forEach(delay => {
            setTimeout(() => {
                try { cleanDocument(); } catch { }
            }, delay);
        });

        if (!window.__wppGoogleSponsoredObserver) {
            window.__wppGoogleSponsoredObserver = new MutationObserver(mutations => {
                try {
                    for (const mutation of mutations) {
                        for (const node of mutation.addedNodes || []) {
                            if (node && node.nodeType === 1)
                                inspectElement(node);
                        }
                    }
                } catch { }
            });

            window.__wppGoogleSponsoredObserver.observe(
                document.documentElement || document.body,
                { childList: true, subtree: true }
            );
        }

        return initialHidden;
    } catch {
        return 0;
    }
})();
");
            }
            catch
            {
                // Clean Search must never interfere with normal page loading.
            }
        }

        private void HookHistory(WebView2? wv)
        {
            if (wv?.CoreWebView2 == null) return;

            wv.CoreWebView2.NavigationCompleted += (_, __) =>
            {
                try
                {
                    var url = wv.CoreWebView2.Source ?? "";
                    if (string.IsNullOrWhiteSpace(url)) return;

                    if (url.Equals("about:blank", StringComparison.OrdinalIgnoreCase) ||
                        url.Equals("lexwhite://newtab", StringComparison.OrdinalIgnoreCase))
                    {
                        return;
                    }

                    _history.Add(url);

                    if (_history.Count > 5000)
                        _history.RemoveRange(0, _history.Count - 5000);

                    ScheduleHistorySave();
                }
                catch { }
            };
        }

        private bool IsInsideOverlayPanel(DependencyObject element)
        {
            try
            {
                DependencyObject current = element;

                while (current != null)
                {
                    if (current is FrameworkElement frameworkElement)
                    {
                        string name = frameworkElement.Name ?? "";

                        if (name.Contains("Settings", StringComparison.OrdinalIgnoreCase) ||
                            name.Contains("Guide", StringComparison.OrdinalIgnoreCase) ||
                            name.Contains("PrivacyOverlay", StringComparison.OrdinalIgnoreCase) ||
                            name.Contains("Popup", StringComparison.OrdinalIgnoreCase) ||
                            name.Contains("Card", StringComparison.OrdinalIgnoreCase))
                        {
                            return true;
                        }
                    }

                    current = VisualTreeHelper.GetParent(current);
                }
            }
            catch
            {
                return false;
            }

            return false;
        }

        private static IEnumerable<T> FindVisualChildren<T>(DependencyObject dependencyObject)
    where T : DependencyObject
        {
            if (dependencyObject == null)
                yield break;

            int childCount = VisualTreeHelper.GetChildrenCount(dependencyObject);

            for (int i = 0; i < childCount; i++)
            {
                DependencyObject child = VisualTreeHelper.GetChild(dependencyObject, i);

                if (child is T typedChild)
                    yield return typedChild;

                foreach (T childOfChild in FindVisualChildren<T>(child))
                    yield return childOfChild;
            }
        }

        // ============================================
        // Active Web Page Helpers
        // ============================================

        private bool PaneLiveUrlMatchesTracked(int index)
        {
            if (index < 0 || index > 3)
                return false;

            string tracked =
                (_pageUrls[index] ?? "").Trim();

            if (IsStartupPlaceholderUrl(tracked))
                return false;

            string live = "";

            try
            {
                var wv = GetWebView(index);

                live =
                    wv?.CoreWebView2?.Source?.Trim()
                    ?? "";
            }
            catch
            {
                live = "";
            }

            if (string.IsNullOrWhiteSpace(live))
                return false;

            return string.Equals(
                live,
                tracked,
                StringComparison.OrdinalIgnoreCase);
        }

        private void EnsurePanesUpTo(int maxIndex)
        {
            if (maxIndex < 0)
                maxIndex = 0;

            if (maxIndex > 3)
                maxIndex = 3;

            var previousPaneState =
                (PaneLifeState[])_paneState.Clone();

            // Show Page 1 through the selected page.
            for (int i = 0; i <= maxIndex; i++)
                _paneState[i] = PaneLifeState.Normal;

            // Hide pages above it.
            for (int i = maxIndex + 1; i < 4; i++)
                _paneState[i] = PaneLifeState.Minimized;

            _layoutPageCount = maxIndex + 1;

            ApplyLayout();
            UpdatePageModeButtonVisuals();
            UpdatePageHostBorders();

            for (int pageIndex = 0;
                 pageIndex <= maxIndex;
                 pageIndex++)
            {
                bool wasClosed =
                    previousPaneState[pageIndex] ==
                    PaneLifeState.Closed;

                string trackedUrl =
                    (_pageUrls[pageIndex] ?? "").Trim();

                // Only a genuinely new / closed / blank pane
                // receives its default Quick URL.
                if (wasClosed ||
                    IsStartupPlaceholderUrl(trackedUrl))
                {
                    LoadQuickUrlForTabPage(
                        _activeWorkspaceTabIndex,
                        pageIndex,
                        force: true);

                    continue;
                }

                // Existing real pages are preserved.
                //
                // If this physical WebView currently contains
                // stale content from another workspace, restore
                // THIS workspace's tracked URL instead.
                if (!_webViewPaneInitDone[pageIndex] ||
                    !PaneLiveUrlMatchesTracked(pageIndex))
                {
                    _ = NavigatePaneWhenReadyAsync(
                        pageIndex,
                        trackedUrl);
                }
            }
        }

        private WebView2? GetWebView(int index) => index switch
        {
            0 => Web,   // <-- change these names to your actual XAML WebView2 names
            1 => Web2,
            2 => Web3,
            3 => Web4,
            _ => null
        };

        private WebView2? GetActiveWebView() => GetWebView(_activePageIndex);

        private Border? GetLockOverlay(int index) => index switch
        {
            0 => LockOverlay1,
            1 => LockOverlay2,
            2 => LockOverlay3,
            3 => LockOverlay4,
            _ => null
        };

        private Border? GetPageHost(int index) => index switch
        {
            0 => PageHost1,
            1 => PageHost2,
            2 => PageHost3,
            3 => PageHost4,
            _ => null
        };

        private Button? GetPageModeButton(int index) => index switch
        {
            0 => Page1Button,
            1 => Page2Button,
            2 => Page3Button,
            3 => Page4Button,
            _ => null
        };

        private void HookPaneActivation(WebView2 web, int paneIndex)
        {
            if (web == null) return;

            void Activate()
            {
                // Always hop to UI thread, avoids weirdness if called during init.
                Dispatcher.Invoke(() => ActivatePane(paneIndex));
            }

            // Focus-based activation is the most reliable for WPF WebView2 (HWND-hosted)
            web.GotFocus += (_, __) => Activate();
            web.GotKeyboardFocus += (_, __) => Activate();

            // Keep this too — sometimes it fires even when the focus events don't
            web.PreviewMouseDown += (_, __) => Activate();
        }

        private void QueueLexDeskManagedWindowReflow(
            string reason)
        {
            try
            {
                Dispatcher.BeginInvoke(
                    new Action(
                        () =>
                        {
                            try
                            {
                                ReflowLexDeskManagedWindows(
                                    reason);
                            }
                            catch
                            {
                                // Layout reflow must never affect LexDesk.
                            }
                        }),
                    DispatcherPriority.ContextIdle);
            }
            catch
            {
                // Layout reflow must never affect LexDesk.
            }
        }

        private void ReflowLexDeskManagedWindows(
            string reason)
        {
            try
            {
                CleanupLexDeskManagedWindowRegistrations();

                WriteLexDeskManagedWindowDebug(
                    $"MANAGED REFLOW BEGIN | reason={reason}");

                foreach (var panePair in
                         _lexDeskManagedPaneOwners
                             .OrderBy(pair => pair.Key)
                             .ToList())
                {
                    int pageIndex =
                        panePair.Key;

                    string key =
                        panePair.Value;

                    if (pageIndex < 0 ||
                        pageIndex > 3 ||
                        _paneState[pageIndex] != PaneLifeState.Normal ||
                        !LexDeskManagedSessionHasLiveWindow(key))
                    {
                        continue;
                    }

                    IntPtr mainHwnd =
                        _lexDeskManagedWindows.TryGetValue(
                            key,
                            out IntPtr savedMain)
                            ? savedMain
                            : IntPtr.Zero;

                    if (mainHwnd != IntPtr.Zero &&
                        IsWindow(mainHwnd) &&
                        !IsIconic(mainHwnd))
                    {
                        PositionLexDeskManagedWindow(
                            mainHwnd,
                            pageIndex);
                    }

                    if (_lexDeskManagedWindowFamilies.TryGetValue(
                            key,
                            out HashSet<IntPtr>? family))
                    {
                        foreach (IntPtr hWnd in
                                 family.ToList())
                        {
                            if (hWnd == IntPtr.Zero ||
                                hWnd == mainHwnd ||
                                !IsWindow(hWnd) ||
                                IsIconic(hWnd))
                            {
                                continue;
                            }

                            PositionLexDeskManagedSecondaryWindow(
                                hWnd,
                                pageIndex);
                        }
                    }
                }

                WriteLexDeskManagedWindowDebug(
                    $"MANAGED REFLOW END | reason={reason}");

                QueueLexDeskManagedSessionStateDump(
                    $"after managed reflow: {reason}");
            }
            catch
            {
                // Managed app resizing must never affect normal browsing.
            }
        }

        // ============================================
        // Layout
        // ============================================

        private void ApplyLayout()
        {
            if (PagesHost == null) return;

            WriteLexDeskManagedWindowDebug(
                $"APPLYLAYOUT BEGIN | visible=[{string.Join(",", VisiblePanes().Select(i => i + 1))}] | " +
                $"active={_activePageIndex + 1} | maxMode={_isPaneMaximizedMode}");

            DumpLexDeskManagedSessionState(
                "before ApplyLayout");

            // Reset all hosts to collapsed and clear spans
            for (int i = 0; i < 4; i++)
            {
                var host = GetPageHost(i);
                if (host == null) continue;
                host.Visibility = Visibility.Collapsed;

                Grid.SetRow(host, 0);
                Grid.SetColumn(host, 0);
                Grid.SetRowSpan(host, 1);
                Grid.SetColumnSpan(host, 1);
                host.Margin = new Thickness(0);
            }

            PagesHost.RowDefinitions.Clear();
            PagesHost.ColumnDefinitions.Clear();

            // If maximized mode: show ONLY that web page (if it’s still visible)
            if (_isPaneMaximizedMode && _maximizedPane >= 0 && _maximizedPane <= 3
                && _paneState[_maximizedPane] == PaneLifeState.Normal)
            {
                PagesHost.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
                PagesHost.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

                var host = GetPageHost(_maximizedPane);
                if (host != null)
                {
                    host.Visibility = Visibility.Visible;
                    Grid.SetRow(host, 0);
                    Grid.SetColumn(host, 0);
                }

                WriteLexDeskManagedWindowDebug(
                    "APPLYLAYOUT END | mode=maximised");

                QueueLexDeskManagedSessionStateDump(
                    "after ApplyLayout maximised");

                QueueLexDeskManagedWindowReflow(
                    "ApplyLayout maximised");

                return;
            }

            _isPaneMaximizedMode = false;
            _maximizedPane = -1;

            var visible = VisiblePanes();

            // Nothing visible? show web page 0 as a fallback newtab
            if (visible.Count == 0)
            {
                _paneState[0] = PaneLifeState.Normal;
                visible = VisiblePanes();
                _activePageIndex = 0;
            }

            int count = visible.Count;
            _layoutPageCount = count;

            // Build grid based on visible count
            if (count == 1)
            {
                PagesHost.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
                PagesHost.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

                Place(visible[0], 0, 0);

                WriteLexDeskManagedWindowDebug(
                    "APPLYLAYOUT END | count=1");

                QueueLexDeskManagedSessionStateDump(
                    "after ApplyLayout count=1");

                QueueLexDeskManagedWindowReflow(
                    "ApplyLayout count=1");

                return;
            }

            if (count == 2)
            {
                PagesHost.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
                PagesHost.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                PagesHost.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

                Place(visible[0], 0, 0);
                Place(visible[1], 0, 1);

                // Edge-style split: a small neutral divider between pages,
                // with no outer gutter around the browsing area.
                GetPageHost(visible[0])!.Margin = new Thickness(0, 0, 2, 0);
                GetPageHost(visible[1])!.Margin = new Thickness(2, 0, 0, 0);

                WriteLexDeskManagedWindowDebug(
                    "APPLYLAYOUT END | count=2");

                QueueLexDeskManagedSessionStateDump(
                    "after ApplyLayout count=2");

                QueueLexDeskManagedWindowReflow(
                    "ApplyLayout count=2");

                return;
            }

            if (count == 3)
            {
                PagesHost.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
                PagesHost.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });

                PagesHost.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                PagesHost.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

                // left tall + right split
                Place(visible[0], 0, 0, rowSpan: 2);
                Place(visible[1], 0, 1);
                Place(visible[2], 1, 1);

                GetPageHost(visible[0])!.Margin = new Thickness(0, 0, 2, 0);
                GetPageHost(visible[1])!.Margin = new Thickness(2, 0, 0, 2);
                GetPageHost(visible[2])!.Margin = new Thickness(2, 2, 0, 0);

                WriteLexDeskManagedWindowDebug(
                    "APPLYLAYOUT END | count=3");

                QueueLexDeskManagedSessionStateDump(
                    "after ApplyLayout count=3");

                QueueLexDeskManagedWindowReflow(
                    "ApplyLayout count=3");

                return;
            }

            // 4 web pages: 2x2
            PagesHost.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            PagesHost.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });

            PagesHost.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            PagesHost.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            Place(visible[0], 0, 0);
            Place(visible[1], 0, 1);
            Place(visible[2], 1, 0); // web page 3 bottom-left
            Place(visible[3], 1, 1); // web page 4 bottom-right

            GetPageHost(visible[0])!.Margin = new Thickness(0, 0, 2, 2);
            GetPageHost(visible[1])!.Margin = new Thickness(2, 0, 0, 2);
            GetPageHost(visible[2])!.Margin = new Thickness(0, 2, 2, 0);
            GetPageHost(visible[3])!.Margin = new Thickness(2, 2, 0, 0);

            WriteLexDeskManagedWindowDebug(
                "APPLYLAYOUT END | count=4");

            QueueLexDeskManagedSessionStateDump(
                "after ApplyLayout count=4");

            QueueLexDeskManagedWindowReflow(
                "ApplyLayout count=4");

            void Place(int paneIndex, int row, int col, int rowSpan = 1, int colSpan = 1)
            {
                var host = GetPageHost(paneIndex);
                if (host == null) return;

                host.Visibility = Visibility.Visible;
                Grid.SetRow(host, row);
                Grid.SetColumn(host, col);
                Grid.SetRowSpan(host, rowSpan);
                Grid.SetColumnSpan(host, colSpan);
            }
            RefreshHomeOverlay1();
        }

        // ============================================
        // Page mode buttons (1-4)
        // ============================================

        private void HandlePageModeButtonClick(int index)
        {
            WriteLexDeskManagedWindowDebug(
                $"PAGE BUTTON CLICK | page={index + 1} | " +
                $"state={(index >= 0 && index <= 3 ? _paneState[index].ToString() : "invalid")}");

            if (index < 0 || index > 3)
                return;

            // Clicking the active Web Page button toggles lock.
            if (_activePageIndex == index)
            {
                SetPageLocked(index, !_pageLocked[index]);
                return;
            }

            SaveSnapshot();

            // If one Web Page is currently maximised, clicking a Page button
            // means the user wants the normal split-page layout again.
            _isPaneMaximizedMode = false;
            _maximizedPane = -1;

            EnsurePanesUpTo(index);

            _activePageIndex = index;

            // EnsurePanesUpTo() has already loaded anything that genuinely
            // needed loading. Existing pages must not be navigated again.
            ApplyLayout();
            RefreshActivePaneStatusVisual();
            UpdatePageModeButtonVisuals();
            UpdatePageHostBorders();
            UpdateSecureSiteVisual();
            SaveCurrentWorkspace();
        }

        private void OpenOnlyPageInCurrentTab(int index)
        {
            if (index < 0 || index > 3)
                return;

            SaveSnapshot();

            bool wasClosed =
                _paneState[index] ==
                PaneLifeState.Closed;

            string trackedUrl =
                (_pageUrls[index] ?? "").Trim();

            _isPaneMaximizedMode = false;
            _maximizedPane = -1;

            for (int paneIndex = 0;
                 paneIndex < 4;
                 paneIndex++)
            {
                _paneState[paneIndex] =
                    paneIndex == index
                        ? PaneLifeState.Normal
                        : PaneLifeState.Minimized;
            }

            _activePageIndex = index;
            _layoutPageCount = 1;

            // New/closed/blank page:
            // load its assigned Quick URL.
            if (wasClosed ||
                IsStartupPlaceholderUrl(trackedUrl))
            {
                LoadQuickUrlForTabPage(
                    _activeWorkspaceTabIndex,
                    index,
                    force: true);
            }
            // Existing page:
            // preserve exactly what the user had open.
            else if (!_webViewPaneInitDone[index] ||
                     !PaneLiveUrlMatchesTracked(index))
            {
                _ = NavigatePaneWhenReadyAsync(
                    index,
                    trackedUrl);
            }

            ApplyLayout();
            RefreshActivePaneStatusVisual();
            UpdatePageModeButtonVisuals();
            UpdatePageHostBorders();
            UpdateSecureSiteVisual();

            SaveCurrentWorkspace();

            UpdateSecurityStatus(
                $"Web Page {index + 1} opened by itself",
                false);
        }

        private void UpdatePageHostBorders()
        {
            try
            {
                var visibleHosts = new List<(int Index, Border Host)>();

                for (int i = 0; i < 4; i++)
                {
                    Border? host = GetPageHost(i);
                    if (host != null && host.Visibility == Visibility.Visible)
                        visibleHosts.Add((i, host));
                }

                int visibleCount = visibleHosts.Count;

                Brush active =
                    TryFindResource("SelectedButtonBorder") as Brush
                    ?? new SolidColorBrush(Color.FromRgb(59, 130, 246));

                Brush locked = new SolidColorBrush(Color.FromRgb(255, 23, 68));

                for (int i = 0; i < 4; i++)
                {
                    Border? host = GetPageHost(i);
                    if (host == null)
                        continue;

                    host.BorderBrush = Brushes.Transparent;
                    host.BorderThickness = new Thickness(0);

                    if (host.Visibility != Visibility.Visible)
                        continue;

                    // A single normal page should look like a normal browser window,
                    // not a framed dashboard. Keep only the lock warning if needed.
                    if (visibleCount <= 1)
                    {
                        if (_pageLocked[i])
                        {
                            host.BorderBrush = locked;
                            host.BorderThickness = new Thickness(2.4);
                        }

                        continue;
                    }

                    // With split pages, the divider provides separation.
                    // Only the selected page gets an active outline.
                    if (_pageLocked[i])
                    {
                        host.BorderBrush = locked;
                        host.BorderThickness = new Thickness(2.4);
                    }
                    else if (i == _activePageIndex)
                    {
                        host.BorderBrush = active;
                        host.BorderThickness = new Thickness(2.0);
                    }
                }
            }
            catch
            {
                // Page-border styling must never affect browsing.
            }
        }

        private void UpdatePageModeButtonVisuals()
        {
            try
            {
                Brush normalBorder =
                    TryFindResource("ButtonBorder") as Brush
                    ?? Brushes.Gray;

                Brush activeBorder =
                    TryFindResource("IconBrushMuted") as Brush
                    ?? Brushes.DarkGray;

                Brush normalBg =
                    Brushes.Transparent;

                Brush activeBg =
                    TryFindResource("ButtonPressedBg") as Brush
                    ?? Brushes.Transparent;

                Brush normalText =
                    TryFindResource("IconBrush") as Brush
                    ?? Brushes.Gray;

                Brush activeText =
                    TryFindResource("TextPrimary") as Brush
                    ?? normalText;

                Brush lockedBorder =
                    new SolidColorBrush(
                        Color.FromRgb(255, 23, 68));

                Brush lockedBg =
                    new SolidColorBrush(
                        Color.FromArgb(35, 255, 23, 68));

                Brush lockedText =
                    TryFindResource("TextPrimary") as Brush
                    ?? Brushes.White;

                for (int i = 0; i < 4; i++)
                {
                    Button? btn =
                        GetPageModeButton(i);

                    if (btn == null)
                        continue;

                    if (_pageLocked[i])
                    {
                        btn.BorderBrush =
                            lockedBorder;

                        btn.BorderThickness =
                            new Thickness(2.0);

                        btn.Background =
                            lockedBg;

                        btn.Foreground =
                            lockedText;
                    }
                    else if (_activePageIndex == i)
                    {
                        btn.BorderBrush =
                            activeBorder;

                        btn.BorderThickness =
                            new Thickness(1.8);

                        btn.Background =
                            activeBg;

                        btn.Foreground =
                            activeText;
                    }
                    else
                    {
                        btn.BorderBrush =
                            normalBorder;

                        btn.BorderThickness =
                            new Thickness(1.0);

                        btn.Background =
                            normalBg;

                        btn.Foreground =
                            normalText;
                    }
                }
            }
            catch
            {
                // Page-button styling must never affect browsing.
            }
        }

        private bool TryGetLexDeskManagedOwnerForPage(
            int pageIndex,
            out string key)
        {
            key = "";

            try
            {
                CleanupLexDeskManagedWindowRegistrations();

                if (pageIndex < 0 ||
                    pageIndex > 3 ||
                    !_lexDeskManagedPaneOwners.TryGetValue(
                        pageIndex,
                        out string? ownerKey) ||
                    string.IsNullOrWhiteSpace(ownerKey) ||
                    !LexDeskManagedSessionHasLiveWindow(ownerKey))
                {
                    return false;
                }

                key = ownerKey;
                return true;
            }
            catch
            {
                return false;
            }
        }

        private void MinimizeLexDeskManagedSessionForPage(
            int pageIndex)
        {
            try
            {
                if (!TryGetLexDeskManagedOwnerForPage(
                        pageIndex,
                        out string key))
                {
                    return;
                }

                if (!_lexDeskManagedWindowFamilies.TryGetValue(
                        key,
                        out HashSet<IntPtr>? family))
                {
                    family =
                        new HashSet<IntPtr>();
                }

                if (_lexDeskManagedWindows.TryGetValue(
                        key,
                        out IntPtr mainHwnd) &&
                    mainHwnd != IntPtr.Zero)
                {
                    family.Add(mainHwnd);
                }

                foreach (IntPtr hWnd in
                         family.ToList())
                {
                    if (hWnd == IntPtr.Zero ||
                        !IsWindow(hWnd))
                    {
                        continue;
                    }

                    WriteLexDeskManagedWindowDebug(
                        $"SESSION MINIMISE | app={key} | page={pageIndex + 1} | " +
                        $"{DescribeLexDeskManagedWindowForDebug(hWnd)}");

                    ShowWindow(
                        hWnd,
                        LexDeskSwMinimizeWindow);
                }

                // The browser page stays Normal underneath. Minimising the overlay
                // therefore reveals the underlying page while keeping this pane
                // reserved for the app so Restore returns it to the same place.
                _activePageIndex =
                    pageIndex;

                IntPtr lexDeskHwnd =
                    new WindowInteropHelper(this).Handle;

                if (lexDeskHwnd != IntPtr.Zero)
                {
                    SetForegroundWindow(
                        lexDeskHwnd);
                }

                UpdatePageHostBorders();
                UpdatePageModeButtonVisuals();
                UpdateSecureSiteVisual();

                QueueLexDeskManagedSessionStateDump(
                    $"managed app minimised: {key}");
            }
            catch
            {
                // Managed-app minimise must never affect normal browsing.
            }
        }

        private static bool IsLexDeskProtectedSharedProcessName(
            string processName)
        {
            processName =
                (processName ?? "").Trim();

            return
                processName.Equals(
                    "explorer",
                    StringComparison.OrdinalIgnoreCase) ||
                processName.Equals(
                    "ApplicationFrameHost",
                    StringComparison.OrdinalIgnoreCase) ||
                processName.Equals(
                    "SystemSettings",
                    StringComparison.OrdinalIgnoreCase) ||
                processName.Equals(
                    "SecHealthUI",
                    StringComparison.OrdinalIgnoreCase);
        }

        private async Task<bool> CloseLexDeskManagedSessionForPageAsync(
            int pageIndex)
        {
            if (!TryGetLexDeskManagedOwnerForPage(
                    pageIndex,
                    out string key))
            {
                return false;
            }

            uint trackedProcessId = 0;
            string trackedProcessName = "";

            if (_lexDeskManagedWindowIdentities.TryGetValue(
                    key,
                    out LexDeskManagedWindowIdentity? identity))
            {
                trackedProcessId =
                    identity.MainProcessId;

                trackedProcessName =
                    identity.MainProcessName ?? "";
            }

            var closeTargets =
                new HashSet<IntPtr>();

            if (_lexDeskManagedWindowFamilies.TryGetValue(
                    key,
                    out HashSet<IntPtr>? family))
            {
                foreach (IntPtr hWnd in family)
                {
                    if (hWnd != IntPtr.Zero &&
                        IsWindow(hWnd))
                    {
                        closeTargets.Add(hWnd);
                    }
                }
            }

            if (_lexDeskManagedWindows.TryGetValue(
                    key,
                    out IntPtr mainHwnd) &&
                mainHwnd != IntPtr.Zero &&
                IsWindow(mainHwnd))
            {
                closeTargets.Add(mainHwnd);
            }

            WriteLexDeskManagedWindowDebug(
                $"SESSION CLOSE REQUEST | app={key} | page={pageIndex + 1} | " +
                $"windows={closeTargets.Count} | PID={trackedProcessId} | " +
                $"process={trackedProcessName}");

            // Ask the app to close normally first. This preserves Save / Don't Save /
            // Cancel prompts in Notepad, Office and similar programs.
            foreach (IntPtr hWnd in closeTargets)
            {
                try
                {
                    PostMessage(
                        hWnd,
                        LexDeskWmClose,
                        IntPtr.Zero,
                        IntPtr.Zero);
                }
                catch { }
            }

            // Give normal close prompts / replacement HWNDs time to settle.
            for (int attempt = 0;
                 attempt < 14;
                 attempt++)
            {
                await Task.Delay(250);

                DiscoverLexDeskManagedSessionWindows();

                if (LexDeskManagedSessionHasLiveWindow(key))
                    continue;

                break;
            }

            // A visible window or save prompt is still alive. Do not bulldoze it.
            if (LexDeskManagedSessionHasLiveWindow(key))
            {
                WriteLexDeskManagedWindowDebug(
                    $"SESSION CLOSE PAUSED | app={key} | visible window remains");

                UpdateSecurityStatus(
                    $"{key} is waiting for you to finish a close or save prompt",
                    false);

                return true;
            }

            // If the main app window has gone but its tracked root process remains
            // in the background, finish that process only for ordinary apps.
            // Never kill Explorer, ApplicationFrameHost, Settings or Security.
            if (trackedProcessId != 0 &&
                !IsLexDeskProtectedSharedProcessName(
                    trackedProcessName))
            {
                try
                {
                    using Process process =
                        Process.GetProcessById(
                            (int)trackedProcessId);

                    if (!process.HasExited)
                    {
                        WriteLexDeskManagedWindowDebug(
                            $"SESSION BACKGROUND PROCESS END | app={key} | " +
                            $"PID={trackedProcessId} | process={trackedProcessName}");

                        process.Kill(
                            entireProcessTree: true);

                        await Task.Run(
                            () =>
                            {
                                try
                                {
                                    process.WaitForExit(
                                        3000);
                                }
                                catch { }
                            });
                    }
                }
                catch
                {
                    // The process may already have ended naturally.
                }
            }

            ReleaseLexDeskManagedSession(key);

            _activePageIndex =
                pageIndex;

            UpdatePageHostBorders();
            UpdatePageModeButtonVisuals();
            UpdateSecureSiteVisual();

            QueueLexDeskManagedSessionStateDump(
                $"managed app closed from pane: {key}");

            return true;
        }

        private void MinimizeActivePane()
        {
            WriteLexDeskManagedWindowDebug(
                $"PANE MINIMISE REQUEST | page={_activePageIndex + 1}");

            DumpLexDeskManagedSessionState(
                "before pane minimise");

            if (_pageLocked[_activePageIndex])
            {
                UpdateSecurityStatus("Page Locked", true);
                return;
            }

            // If an external app overlays this pane, the pane's minus button means
            // "minimise the overlay", not "remove the browser pane underneath".
            if (TryGetLexDeskManagedOwnerForPage(
                    _activePageIndex,
                    out _))
            {
                MinimizeLexDeskManagedSessionForPage(
                    _activePageIndex);

                return;
            }

            if (_paneState[_activePageIndex] != PaneLifeState.Normal)
                return;

            SaveSnapshot();

            _paneState[_activePageIndex] = PaneLifeState.Minimized;

            // pick next visible pane as active (or stay if none)
            var visible = VisiblePanes();
            if (visible.Count > 0)
                _activePageIndex = visible[0];

            ApplyLayout();
            UpdatePageModeButtonVisuals();
            UpdatePageHostBorders();
            UpdateSecureSiteVisual();
        }

        private void MaximizeActivePane()
        {

            if (_pageLocked[_activePageIndex])
            {
                UpdateSecurityStatus("Page Locked", true);
                return;
            }

            // If already in maximize-mode, SnapBack should restore instead (but user wants SnapBack button)
            if (_paneState[_activePageIndex] != PaneLifeState.Normal)
                return;

            SaveSnapshot();

            _isPaneMaximizedMode = true;
            _maximizedPane = _activePageIndex;

            ApplyLayout();
            UpdatePageModeButtonVisuals();
            UpdatePageHostBorders();
            UpdateSecureSiteVisual();
        }

        private async void CloseActivePane()
        {
            WriteLexDeskManagedWindowDebug(
                $"PANE CLOSE REQUEST | page={_activePageIndex + 1}");

            DumpLexDeskManagedSessionState(
                "before pane close");

            if (_pageLocked[_activePageIndex])
            {
                UpdateSecurityStatus("Page Locked", true);
                return;
            }

            if (_activePageIndex < 0 || _activePageIndex > 3)
                return;

            // If a managed external app overlays this pane, the pane X closes that
            // app session first and leaves the browser page intact underneath.
            if (TryGetLexDeskManagedOwnerForPage(
                    _activePageIndex,
                    out _))
            {
                await CloseLexDeskManagedSessionForPageAsync(
                    _activePageIndex);

                return;
            }

            if (_pageLocked[_activePageIndex])
            {
                ShowLexDeskMessageBox(
    "This Web Page is locked.",
    "Web Page Locked",
    MessageBoxButton.OK,
    MessageBoxImage.Information);
                return;
            }

            if (_paneState[_activePageIndex] == PaneLifeState.Closed)
                return;

            RememberRecentlyClosedPage(_activePageIndex);
            SaveSnapshot();

            // blank it out so it’s “closed”
            try
            {
                var wv = GetWebView(_activePageIndex);
                wv?.CoreWebView2?.Navigate("about:blank");
            }
            catch { }

            _pageUrls[_activePageIndex] = "about:blank";
            _paneState[_activePageIndex] = PaneLifeState.Closed;

            var visible = VisiblePanes();
            if (visible.Count > 0)
                _activePageIndex = visible[0];

            // if we just closed the maximized pane, exit maximize mode
            if (_isPaneMaximizedMode && _maximizedPane == _activePageIndex)
            {
                _isPaneMaximizedMode = false;
                _maximizedPane = -1;
            }

            ApplyLayout();
            UpdatePageModeButtonVisuals();
            UpdatePageHostBorders();
            UpdateSecureSiteVisual();
        }

        private void SetPageLocked(int index, bool locked)
        {
            if (index < 0 || index > 3) return;

            _pageLocked[index] = locked;

            var wv = GetWebView(index);
            if (wv != null) wv.IsEnabled = !locked;

            var overlay = GetLockOverlay(index);
            if (overlay != null)
                overlay.Visibility = locked ? Visibility.Visible : Visibility.Collapsed;

            var host = GetPageHost(index);
            if (host != null)
            {
                host.BorderThickness = locked ? new Thickness(4) : new Thickness(2.0);
            }

            UpdatePageModeButtonVisuals();
            UpdatePageHostBorders();

            if (locked)
            {
                UpdateSecurityStatus(
                    $"Web Page {index + 1} locked - click {index + 1} again to unlock",
                    true);
            }
            else
            {
                UpdateSecurityStatus($"Web Page {index + 1} unlocked", false);
            }
        }

