        private void RefreshLexDeskPage2ContentVisual()
        {
            try
            {
                switch (_lexDeskPageContentModes[1])
                {
                    case LexDeskPageContentMode.Browser:

                        LexDeskPageCard2.Visibility =
                            Visibility.Collapsed;

                        if (Web2 != null)
                            Web2.Visibility =
                                Visibility.Visible;

                        break;

                    case LexDeskPageContentMode.WindowsApp:

                        if (Web2 != null)
                            Web2.Visibility =
                                Visibility.Collapsed;

                        LexDeskPageCard2Title.Text =
                            "Windows App";

                        LexDeskPageCard2Subtitle.Text =
                            "Choose a Windows app for Page 2.";

                        LexDeskPageCard2.Visibility =
                            Visibility.Visible;

                        break;

                    case LexDeskPageContentMode.WindowsTool:

                        if (Web2 != null)
                            Web2.Visibility =
                                Visibility.Collapsed;

                        LexDeskPageCard2Title.Text =
                            "Windows Tool";

                        LexDeskPageCard2Subtitle.Text =
                            "Choose a Windows tool for Page 2.";

                        LexDeskPageCard2.Visibility =
                            Visibility.Visible;

                        break;

                    case LexDeskPageContentMode.Empty:

                        if (Web2 != null)
                            Web2.Visibility =
                                Visibility.Collapsed;

                        LexDeskPageCard2Title.Text =
                            "Page 2 is empty";

                        LexDeskPageCard2Subtitle.Text =
                            "Choose Web Browser, Windows App or Windows Tool when you want to use this page.";

                        LexDeskPageCard2.Visibility =
                            Visibility.Visible;

                        break;
                }
            }
            catch
            {
                // Page content switching must never affect LexDesk.
            }
        }

        private void RestoreLexDeskPage2BrowserIfManagedToolClosed()
        {
            try
            {
                if (_lexDeskPageContentModes[1] !=
                    LexDeskPageContentMode.WindowsTool)
                {
                    return;
                }

                string managedKey =
                    (_lexDeskPageContentTitles[1] ?? "").Trim();

                if (string.IsNullOrWhiteSpace(managedKey))
                    return;

                if (!_lexDeskManagedWindows.TryGetValue(
                        managedKey,
                        out IntPtr hWnd))
                {
                    return;
                }

                if (hWnd != IntPtr.Zero &&
                    IsWindow(hWnd))
                {
                    return;
                }

                _lexDeskManagedWindows.Remove(
                    managedKey);

                _lexDeskPageContentModes[1] =
                    LexDeskPageContentMode.Browser;

                _lexDeskPageContentTargets[1] = "";
                _lexDeskPageContentTitles[1] = "";

                if (LexDeskPageCard2 != null)
                    LexDeskPageCard2.Visibility =
                        Visibility.Collapsed;

                if (LexDeskWindowsToolCard2 != null)
                    LexDeskWindowsToolCard2.Visibility =
                        Visibility.Collapsed;

                if (LexDeskAdvancedToolCard2 != null)
                    LexDeskAdvancedToolCard2.Visibility =
                        Visibility.Collapsed;

                SetPaneWebViewVisible(
    1,
    true);

                RefreshLexDeskPage2ContentVisual();
            }
            catch
            {
                // Closing a managed tool must never affect normal browsing.
            }
        }

