        private sealed class LexDeskFirewallProfileInfo
        {
            public string Name { get; set; } = "";

            public bool Enabled { get; set; }

            public string DefaultInboundAction { get; set; } = "";

            public string DefaultOutboundAction { get; set; } = "";

            public string AllowInboundRules { get; set; } = "";
        }

        private sealed class LexDeskFirewallPublicLockdownSnapshot
        {
            public bool Enabled { get; set; } = true;

            public string DefaultInboundAction { get; set; } = "Block";

            public string DefaultOutboundAction { get; set; } = "Allow";

            public string AllowInboundRules { get; set; } = "True";

            public string SavedUtc { get; set; } = "";
        }

        private readonly string _lexDeskFirewallPublicLockdownSnapshotPath =
            AppDataPath("firewall_public_lockdown_snapshot.json");

        // null = status could not be confirmed, true = recommended settings active,
        // false = one or more core firewall defaults need attention.
        private bool? _lexDeskFirewallRecommendedActive;

        // null = status unavailable, true = Public profile is in Windows Shields-Up mode,
        // false = Public profile is using normal inbound firewall rules.
        private bool? _lexDeskFirewallPublicLockdownActive;

        private LexDeskFirewallProfileInfo? _lexDeskFirewallPublicProfile;

        // LexDesk-owned outbound program blocks are tracked locally so we never
        // have to guess which firewall rules belong to LexDesk.
        private sealed class LexDeskFirewallBlockedProgramInfo
        {
            public string RuleName { get; set; } = "";
            public string ProgramPath { get; set; } = "";
            public string ProgramName { get; set; } = "";
            public string CreatedUtc { get; set; } = "";
        }

        private sealed class LexDeskFirewallLastChangeInfo
        {
            public string ActionType { get; set; } = "";
            public string RuleName { get; set; } = "";
            public string ProgramPath { get; set; } = "";
            public string ProgramName { get; set; } = "";
            public string SavedUtc { get; set; } = "";
        }

        private readonly string _lexDeskFirewallBlockedProgramsPath =
            AppDataPath("firewall_blocked_programs.json");

        private readonly string _lexDeskFirewallLastChangePath =
            AppDataPath("firewall_last_change.json");

        // TEMP DEBUG: program-block diagnostics. Remove once the Brave test is solved.
        private readonly string _lexDeskFirewallProgramDebugPath =
            AppDataPath("Debug", "firewall_program_debug.log");

        // When Windows Security registers a third-party firewall provider,
        // Windows Firewall rules may exist in the policy store but remain inactive.
        // Keep the provider name so LexDesk can avoid pretending those rules are enforced.
        private string _lexDeskThirdPartyFirewallNames = "";

        private sealed class LexDeskFirewallProgramListItem
        {
            public string Name { get; set; } = "";
            public string ProgramPath { get; set; } = "";
            public string RuleName { get; set; } = "";
            public string Status { get; set; } = "Allowed normally";
            public bool IsBlockedByLexDesk { get; set; }
            public bool IsBlockedByOtherRule { get; set; }
        }

        private List<LexDeskFirewallProgramListItem>
            _lexDeskFirewallProgramItems = new();


        private async Task<string> GetLexDeskRegisteredThirdPartyFirewallNamesAsync()
        {
            try
            {
                string command =
                    "$ErrorActionPreference='SilentlyContinue'; " +
                    "Get-CimInstance -Namespace root/SecurityCenter2 -ClassName FirewallProduct -ErrorAction SilentlyContinue | " +
                    "ForEach-Object { [string]$_.displayName }";

                var psi = new ProcessStartInfo
                {
                    FileName = "powershell.exe",
                    UseShellExecute = false,
                    CreateNoWindow = true,
                    RedirectStandardOutput = true,
                    RedirectStandardError = true
                };

                psi.ArgumentList.Add("-NoProfile");
                psi.ArgumentList.Add("-NonInteractive");
                psi.ArgumentList.Add("-Command");
                psi.ArgumentList.Add(command);

                using Process? process = Process.Start(psi);

                if (process == null)
                    return "";

                string output =
                    await process.StandardOutput.ReadToEndAsync();

                _ =
                    await process.StandardError.ReadToEndAsync();

                await process.WaitForExitAsync();

                if (process.ExitCode != 0 ||
                    string.IsNullOrWhiteSpace(output))
                {
                    return "";
                }

                string[] names =
                    output
                        .Split(
                            new[] { '\r', '\n' },
                            StringSplitOptions.RemoveEmptyEntries)
                        .Select(name => name.Trim())
                        .Where(name => !string.IsNullOrWhiteSpace(name))
                        .Where(name =>
                            name.IndexOf(
                                "Microsoft",
                                StringComparison.OrdinalIgnoreCase) < 0 &&
                            name.IndexOf(
                                "Windows Defender",
                                StringComparison.OrdinalIgnoreCase) < 0 &&
                            name.IndexOf(
                                "Windows Firewall",
                                StringComparison.OrdinalIgnoreCase) < 0)
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .ToArray();

                return string.Join(", ", names);
            }
            catch
            {
                return "";
            }
        }


        private string GetLexDeskThirdPartyFirewallGuidance(
            string programName,
            string programPath)
        {
            string provider =
                string.IsNullOrWhiteSpace(_lexDeskThirdPartyFirewallNames)
                    ? "A third-party firewall"
                    : _lexDeskThirdPartyFirewallNames;

            string guidance =
                $"Windows Security reports {provider} as a registered firewall provider on this PC.\n\n" +
                "LexDesk will not create a Windows Firewall program block while another firewall provider is registered, because Windows can keep that rule inactive even though it appears enabled.\n\n" +
                $"To block {programName}, use {provider}'s Firewall / Application Rules and deny network access for:\n{programPath}";

            if (provider.IndexOf(
                    "Bitdefender",
                    StringComparison.OrdinalIgnoreCase) >= 0)
            {
                guidance +=
                    "\n\nIn Bitdefender, open Firewall and use its Rules or Application Access section to add/edit the app rule and set access to Deny.";
            }

            return guidance;
        }


        private async Task RefreshLexDeskFirewallStatusAsync()
        {
            _lexDeskFirewallRecommendedActive = null;
            _lexDeskFirewallPublicLockdownActive = null;
            _lexDeskFirewallPublicProfile = null;

            UpdateLexDeskFirewallPublicLockdownButton();
            UpdateLexDeskFirewallUndoButton();

            LexDeskFirewallStatusTitle2.Text =
                "Checking firewall...";

            LexDeskFirewallStatusText2.Text =
                "LexDesk is checking your Windows Firewall protection.";

            try
            {
                _lexDeskThirdPartyFirewallNames =
                    await GetLexDeskRegisteredThirdPartyFirewallNamesAsync();

                if (!string.IsNullOrWhiteSpace(
                        _lexDeskThirdPartyFirewallNames))
                {
                    LexDeskFirewallStatusTitle2.Text =
                        $"Firewall provider: {_lexDeskThirdPartyFirewallNames}";

                    LexDeskFirewallStatusText2.Text =
                        $"Windows Security reports {_lexDeskThirdPartyFirewallNames} as a registered firewall provider. " +
                        "LexDesk will not change Windows Firewall rules while a third-party firewall is registered, because Windows may keep those rules inactive. " +
                        "Use the firewall provider's own rules for program blocking.";

                    return;
                }
                string command =
                    "$profiles = Get-NetFirewallProfile -PolicyStore ActiveStore | " +
                    "ForEach-Object { [PSCustomObject]@{" +
                    "Name=[string]$_.Name;" +
                    "Enabled=[bool]$_.Enabled;" +
                    "DefaultInboundAction=[string]$_.DefaultInboundAction;" +
                    "DefaultOutboundAction=[string]$_.DefaultOutboundAction;" +
                    "AllowInboundRules=[string]$_.AllowInboundRules" +
                    "} }; " +
                    "ConvertTo-Json -InputObject @($profiles) -Compress";

                ProcessStartInfo psi =
                    new ProcessStartInfo
                    {
                        FileName =
                            "powershell.exe",

                        UseShellExecute =
                            false,

                        CreateNoWindow =
                            true,

                        RedirectStandardOutput =
                            true,

                        RedirectStandardError =
                            true
                    };

                psi.ArgumentList.Add(
                    "-NoProfile");

                psi.ArgumentList.Add(
                    "-NonInteractive");

                psi.ArgumentList.Add(
                    "-Command");

                psi.ArgumentList.Add(
                    command);

                using Process process =
                    new Process
                    {
                        StartInfo = psi
                    };

                process.Start();

                string output =
                    await process.StandardOutput.ReadToEndAsync();

                string error =
                    await process.StandardError.ReadToEndAsync();

                await process.WaitForExitAsync();

                if (process.ExitCode != 0 ||
                    string.IsNullOrWhiteSpace(output))
                {
                    LexDeskFirewallStatusTitle2.Text =
                        "Firewall status unavailable";

                    LexDeskFirewallStatusText2.Text =
                        "LexDesk could not read the Windows Firewall configuration.";

                    return;
                }

                List<LexDeskFirewallProfileInfo>? profiles =
                    JsonSerializer.Deserialize<
                        List<LexDeskFirewallProfileInfo>>(
                            output,
                            JsonCaseInsensitiveOptions);

                if (profiles == null ||
                    profiles.Count == 0)
                {
                    LexDeskFirewallStatusTitle2.Text =
                        "Firewall status unavailable";

                    LexDeskFirewallStatusText2.Text =
                        "Windows did not return any firewall profile information.";

                    return;
                }

                _lexDeskFirewallPublicProfile =
                    profiles.FirstOrDefault(
                        profile =>
                            string.Equals(
                                profile.Name,
                                "Public",
                                StringComparison.OrdinalIgnoreCase));

                if (_lexDeskFirewallPublicProfile != null)
                {
                    bool publicInboundBlock =
                        string.Equals(
                            _lexDeskFirewallPublicProfile.DefaultInboundAction,
                            "Block",
                            StringComparison.OrdinalIgnoreCase);

                    bool publicInboundRulesIgnored =
                        string.Equals(
                            _lexDeskFirewallPublicProfile.AllowInboundRules,
                            "False",
                            StringComparison.OrdinalIgnoreCase);

                    _lexDeskFirewallPublicLockdownActive =
                        _lexDeskFirewallPublicProfile.Enabled &&
                        publicInboundBlock &&
                        publicInboundRulesIgnored;
                }

                UpdateLexDeskFirewallPublicLockdownButton();

                bool allEnabled =
                    profiles.All(
                        profile =>
                            profile.Enabled);

                bool inboundSafe =
                    profiles.All(
                        profile =>
                            string.Equals(
                                profile.DefaultInboundAction,
                                "Block",
                                StringComparison.OrdinalIgnoreCase) ||
                            string.Equals(
                                profile.DefaultInboundAction,
                                "NotConfigured",
                                StringComparison.OrdinalIgnoreCase));

                bool outboundNormal =
                    profiles.All(
                        profile =>
                            string.Equals(
                                profile.DefaultOutboundAction,
                                "Allow",
                                StringComparison.OrdinalIgnoreCase) ||
                            string.Equals(
                                profile.DefaultOutboundAction,
                                "NotConfigured",
                                StringComparison.OrdinalIgnoreCase));

                if (allEnabled &&
                    inboundSafe &&
                    outboundNormal)
                {
                    _lexDeskFirewallRecommendedActive = true;

                    if (_lexDeskFirewallPublicLockdownActive == true)
                    {
                        LexDeskFirewallStatusTitle2.Text =
                            "✓ Public Wi-Fi Lockdown is active";

                        LexDeskFirewallStatusText2.Text =
                            "The Windows Public-network profile is in extra protection mode. Inbound exceptions are temporarily ignored whenever Windows classifies a network as Public. Normal outgoing connections are still allowed.";
                    }
                    else
                    {
                        LexDeskFirewallStatusTitle2.Text =
                            "✓ Recommended protection is active";

                        LexDeskFirewallStatusText2.Text =
                            "Windows Firewall is on. Incoming connections use safe Windows protection and normal outgoing connections are allowed.";
                    }

                    return;
                }

                _lexDeskFirewallRecommendedActive = false;

                List<string> issues =
                    new List<string>();

                if (!allEnabled)
                {
                    issues.Add(
                        "one or more firewall profiles are turned off");
                }

                if (!inboundSafe)
                {
                    issues.Add(
                        "incoming connections are not using the normal safe setting");
                }

                if (!outboundNormal)
                {
                    issues.Add(
                        "outgoing connections are using a restrictive setting");
                }

                LexDeskFirewallStatusTitle2.Text =
                    "⚠ Firewall settings need attention";

                LexDeskFirewallStatusText2.Text =
                    "LexDesk found that " +
                    string.Join(
                        ", ",
                        issues) +
                    ".";
            }
            catch
            {
                LexDeskFirewallStatusTitle2.Text =
                    "Firewall status unavailable";

                LexDeskFirewallStatusText2.Text =
                    "LexDesk could not check Windows Firewall.";
            }
        }


        private async void LexDeskFirewallRecommended_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            Button? button =
                sender as Button;

            if (button != null)
                button.IsEnabled = false;

            try
            {
                await RefreshLexDeskFirewallStatusAsync();

                if (!string.IsNullOrWhiteSpace(
                        _lexDeskThirdPartyFirewallNames))
                {
                    ShowLexDeskMessageBox(
                        $"Windows Security reports {_lexDeskThirdPartyFirewallNames} as this PC's registered firewall provider.\n\n" +
                        "LexDesk will not change the Windows Firewall defaults while another firewall provider is registered. This avoids creating settings or rules that Windows may leave inactive.",
                        "Firewall Provider Detected",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);

                    return;
                }

                if (_lexDeskFirewallRecommendedActive == true)
                {
                    string extra =
                        _lexDeskFirewallPublicLockdownActive == true
                            ? "\n\nPublic Wi-Fi Lockdown is also active. Use Return to Normal Public Protection when you want to leave lockdown mode."
                            : "";

                    ShowLexDeskMessageBox(
                        "Recommended firewall protection is already active.\n\nNothing needs changing." +
                        extra,
                        "Firewall Protection",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);

                    return;
                }

                MessageBoxResult decision =
                    ShowLexDeskMessageBox(
                        "LexDesk can restore the normal safe Windows Firewall defaults.\n\n" +
                        "This will:\n" +
                        "• Turn Windows Firewall ON for Domain, Private and Public networks.\n" +
                        "• Block unsolicited incoming connections by default.\n" +
                        "• Allow normal outgoing connections.\n\n" +
                        "Existing firewall rules are NOT deleted.\n\n" +
                        "Windows may ask for Administrator permission. Continue?",
                        "Use Recommended Protection",
                        MessageBoxButton.YesNo,
                        MessageBoxImage.Information);

                if (decision != MessageBoxResult.Yes)
                    return;

                LexDeskFirewallStatusTitle2.Text =
                    "Applying recommended protection...";

                LexDeskFirewallStatusText2.Text =
                    "Windows may ask for Administrator permission. LexDesk will only change the core firewall defaults and will not delete existing rules.";

                string netsh =
                    Path.Combine(
                        Environment.SystemDirectory,
                        "netsh.exe");

                var commands =
                    new List<LexDeskMaintenanceCommand>
                    {
                        new()
                        {
                            Key = "FIREWALLSTATE",
                            StatusText = "Turning Windows Firewall protection on...",
                            FileName = netsh,
                            Arguments = "advfirewall set allprofiles state on",
                            StopOnFailure = true
                        },
                        new()
                        {
                            Key = "FIREWALLPOLICY",
                            StatusText = "Restoring safe Windows Firewall connection defaults...",
                            FileName = netsh,
                            Arguments = "advfirewall set allprofiles firewallpolicy blockinbound,allowoutbound",
                            StopOnFailure = true
                        }
                    };

                LexDeskMaintenanceBatchResult result =
                    await RunElevatedMaintenanceBatchAsync(
                        "firewall_recommended",
                        commands);

                if (result.Cancelled)
                {
                    await RefreshLexDeskFirewallStatusAsync();

                    ShowLexDeskMessageBox(
                        "Administrator permission was cancelled. LexDesk did not apply the recommended firewall settings.",
                        "Firewall Protection",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);

                    return;
                }

                bool gotStateExit =
                    TryGetLexDeskMaintenanceExitCode(
                        result.Output,
                        "FIREWALLSTATE",
                        out int stateExit);

                bool gotPolicyExit =
                    TryGetLexDeskMaintenanceExitCode(
                        result.Output,
                        "FIREWALLPOLICY",
                        out int policyExit);

                bool commandsSucceeded =
                    result.Started &&
                    gotStateExit &&
                    gotPolicyExit &&
                    IsLexDeskMaintenanceSuccessExit(stateExit) &&
                    IsLexDeskMaintenanceSuccessExit(policyExit);

                await Task.Delay(500);
                await RefreshLexDeskFirewallStatusAsync();

                if (commandsSucceeded &&
                    _lexDeskFirewallRecommendedActive == true)
                {
                    ShowLexDeskMessageBox(
                        "Recommended firewall protection is now active.\n\nYour existing firewall rules were kept.",
                        "Firewall Protection",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);

                    UpdateSecurityStatus(
                        "Recommended Windows Firewall protection active",
                        false);

                    return;
                }

                ShowLexDeskMessageBox(
                    "Windows did not confirm all recommended firewall settings. No firewall rules were deleted.\n\nUse Open Advanced Firewall if you need to inspect the Windows configuration.",
                    "Firewall Protection",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);

                UpdateSecurityStatus(
                    "Windows Firewall settings need attention",
                    true);
            }
            catch
            {
                await RefreshLexDeskFirewallStatusAsync();

                ShowLexDeskMessageBox(
                    "LexDesk could not finish the firewall change. No firewall rules were intentionally removed.",
                    "Firewall Protection",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                if (button != null)
                    button.IsEnabled = true;
            }
        }


        private void UpdateLexDeskFirewallPublicLockdownButton()
        {
            if (LexDeskFirewallPublicLockdownButton2 == null)
                return;

            LexDeskFirewallPublicLockdownButton2.Content =
                _lexDeskFirewallPublicLockdownActive == true
                    ? "Return to Normal Public Protection"
                    : "Public Wi-Fi Lockdown";
        }


        private bool SaveLexDeskFirewallPublicLockdownSnapshot(
            LexDeskFirewallProfileInfo publicProfile)
        {
            try
            {
                if (publicProfile == null)
                    return false;

                var snapshot =
                    new LexDeskFirewallPublicLockdownSnapshot
                    {
                        Enabled = publicProfile.Enabled,
                        DefaultInboundAction =
                            (publicProfile.DefaultInboundAction ?? "").Trim(),
                        DefaultOutboundAction =
                            (publicProfile.DefaultOutboundAction ?? "").Trim(),
                        AllowInboundRules =
                            (publicProfile.AllowInboundRules ?? "").Trim(),
                        SavedUtc = DateTime.UtcNow.ToString("O")
                    };

                string? folder =
                    Path.GetDirectoryName(
                        _lexDeskFirewallPublicLockdownSnapshotPath);

                if (!string.IsNullOrWhiteSpace(folder))
                    Directory.CreateDirectory(folder);

                File.WriteAllText(
                    _lexDeskFirewallPublicLockdownSnapshotPath,
                    JsonSerializer.Serialize(
                        snapshot,
                        JsonIndentedOptions));

                return true;
            }
            catch
            {
                return false;
            }
        }


        private bool TryLoadLexDeskFirewallPublicLockdownSnapshot(
            out LexDeskFirewallPublicLockdownSnapshot snapshot)
        {
            snapshot =
                new LexDeskFirewallPublicLockdownSnapshot();

            try
            {
                if (!File.Exists(
                        _lexDeskFirewallPublicLockdownSnapshotPath))
                {
                    return false;
                }

                string json =
                    File.ReadAllText(
                        _lexDeskFirewallPublicLockdownSnapshotPath);

                LexDeskFirewallPublicLockdownSnapshot? loaded =
                    JsonSerializer.Deserialize<
                        LexDeskFirewallPublicLockdownSnapshot>(
                            json,
                            JsonCaseInsensitiveOptions);

                if (loaded == null)
                    return false;

                snapshot = loaded;
                return true;
            }
            catch
            {
                return false;
            }
        }


        private void DeleteLexDeskFirewallPublicLockdownSnapshot()
        {
            try
            {
                if (File.Exists(
                        _lexDeskFirewallPublicLockdownSnapshotPath))
                {
                    File.Delete(
                        _lexDeskFirewallPublicLockdownSnapshotPath);
                }
            }
            catch
            {
                // A stale rollback file is harmless. Never let cleanup affect LexDesk.
            }
        }


        private static string GetLexDeskFirewallRestoreInboundPolicy(
            LexDeskFirewallPublicLockdownSnapshot snapshot)
        {
            bool previousShieldsUp =
                string.Equals(
                    snapshot.AllowInboundRules,
                    "False",
                    StringComparison.OrdinalIgnoreCase) &&
                string.Equals(
                    snapshot.DefaultInboundAction,
                    "Block",
                    StringComparison.OrdinalIgnoreCase);

            if (previousShieldsUp)
                return "blockinboundalways";

            if (string.Equals(
                    snapshot.DefaultInboundAction,
                    "Allow",
                    StringComparison.OrdinalIgnoreCase))
            {
                return "allowinbound";
            }

            // Block is the normal Windows default. ActiveStore can also report
            // NotConfigured when the effective value still resolves to Block.
            return "blockinbound";
        }


        private static string GetLexDeskFirewallRestoreOutboundPolicy(
            LexDeskFirewallPublicLockdownSnapshot snapshot)
        {
            return string.Equals(
                       snapshot.DefaultOutboundAction,
                       "Block",
                       StringComparison.OrdinalIgnoreCase)
                ? "blockoutbound"
                : "allowoutbound";
        }


        private async void LexDeskFirewallPublicLockdown_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            Button? button =
                sender as Button;

            if (button != null)
                button.IsEnabled = false;

            try
            {
                await RefreshLexDeskFirewallStatusAsync();

                if (!string.IsNullOrWhiteSpace(
                        _lexDeskThirdPartyFirewallNames))
                {
                    ShowLexDeskMessageBox(
                        $"Windows Security reports {_lexDeskThirdPartyFirewallNames} as this PC's registered firewall provider.\n\n" +
                        "Public Wi-Fi Lockdown uses Windows Firewall policy, so LexDesk will not apply it while another firewall provider is registered. Use that provider's public-network/firewall protection instead.",
                        "Firewall Provider Detected",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);

                    return;
                }

                // ----------------------------------------------------
                // RETURN TO NORMAL PUBLIC PROTECTION
                // ----------------------------------------------------
                if (_lexDeskFirewallPublicLockdownActive == true)
                {
                    bool haveSnapshot =
                        TryLoadLexDeskFirewallPublicLockdownSnapshot(
                            out LexDeskFirewallPublicLockdownSnapshot snapshot);

                    MessageBoxResult restoreDecision =
                        ShowLexDeskMessageBox(
                            haveSnapshot
                                ? "LexDesk can return the Public firewall profile to the settings it saved before Lockdown was enabled.\n\n" +
                                  "Normal inbound firewall exceptions will work again.\n\n" +
                                  "Windows may ask for Administrator permission. Continue?"
                                : "LexDesk could not find the saved pre-lockdown settings.\n\n" +
                                  "It can still return the Public firewall profile to normal recommended protection:\n" +
                                  "• Firewall ON\n" +
                                  "• Unsolicited incoming connections blocked\n" +
                                  "• Normal inbound firewall exceptions allowed again\n" +
                                  "• Normal outgoing connections allowed\n\n" +
                                  "Windows may ask for Administrator permission. Continue?",
                            "Return to Normal Public Protection",
                            MessageBoxButton.YesNo,
                            MessageBoxImage.Information);

                    if (restoreDecision != MessageBoxResult.Yes)
                        return;

                    LexDeskFirewallStatusTitle2.Text =
                        "Returning to normal public protection...";

                    LexDeskFirewallStatusText2.Text =
                        "LexDesk is restoring the Public firewall profile. Existing firewall rules are not being deleted.";

                    string netsh =
                        Path.Combine(
                            Environment.SystemDirectory,
                            "netsh.exe");

                    string inboundPolicy =
                        haveSnapshot
                            ? GetLexDeskFirewallRestoreInboundPolicy(snapshot)
                            : "blockinbound";

                    string outboundPolicy =
                        haveSnapshot
                            ? GetLexDeskFirewallRestoreOutboundPolicy(snapshot)
                            : "allowoutbound";

                    // LexDesk never turns Windows Firewall off during a safety restore.
                    // Even if it was off before Lockdown, returning to normal protection
                    // keeps the Public firewall profile enabled.
                    bool restoreEnabled = true;

                    var restoreCommands =
                        new List<LexDeskMaintenanceCommand>
                        {
                            new()
                            {
                                Key = "PUBLICPOLICYRESTORE",
                                StatusText = "Restoring normal Public firewall connection rules...",
                                FileName = netsh,
                                Arguments =
                                    $"advfirewall set publicprofile firewallpolicy {inboundPolicy},{outboundPolicy}",
                                StopOnFailure = true
                            },
                            new()
                            {
                                Key = "PUBLICSTATERESTORE",
                                StatusText = "Restoring the saved Public firewall state...",
                                FileName = netsh,
                                Arguments =
                                    restoreEnabled
                                        ? "advfirewall set publicprofile state on"
                                        : "advfirewall set publicprofile state off",
                                StopOnFailure = true
                            }
                        };

                    LexDeskMaintenanceBatchResult restoreResult =
                        await RunElevatedMaintenanceBatchAsync(
                            "firewall_public_lockdown_restore",
                            restoreCommands);

                    if (restoreResult.Cancelled)
                    {
                        await RefreshLexDeskFirewallStatusAsync();

                        ShowLexDeskMessageBox(
                            "Administrator permission was cancelled. Public Wi-Fi Lockdown was left unchanged.",
                            "Firewall Protection",
                            MessageBoxButton.OK,
                            MessageBoxImage.Information);

                        return;
                    }

                    bool gotPolicyRestoreExit =
                        TryGetLexDeskMaintenanceExitCode(
                            restoreResult.Output,
                            "PUBLICPOLICYRESTORE",
                            out int policyRestoreExit);

                    bool gotStateRestoreExit =
                        TryGetLexDeskMaintenanceExitCode(
                            restoreResult.Output,
                            "PUBLICSTATERESTORE",
                            out int stateRestoreExit);

                    bool restoreSucceeded =
                        restoreResult.Started &&
                        gotPolicyRestoreExit &&
                        gotStateRestoreExit &&
                        IsLexDeskMaintenanceSuccessExit(policyRestoreExit) &&
                        IsLexDeskMaintenanceSuccessExit(stateRestoreExit);

                    await Task.Delay(500);
                    await RefreshLexDeskFirewallStatusAsync();

                    if (restoreSucceeded &&
                        _lexDeskFirewallPublicLockdownActive != true)
                    {
                        DeleteLexDeskFirewallPublicLockdownSnapshot();

                        ShowLexDeskMessageBox(
                            haveSnapshot
                                ? "Public Wi-Fi Lockdown is off.\n\nYour saved Public firewall connection policy was restored and Windows Firewall remains on."
                                : "Public Wi-Fi Lockdown is off.\n\nThe Public profile is back on normal recommended protection.",
                            "Firewall Protection",
                            MessageBoxButton.OK,
                            MessageBoxImage.Information);

                        UpdateSecurityStatus(
                            "Public Wi-Fi Lockdown off",
                            false);

                        return;
                    }

                    ShowLexDeskMessageBox(
                        "Windows did not confirm that Public Wi-Fi Lockdown was fully removed.\n\nLexDesk kept the saved rollback settings. Use Open Advanced Firewall if you need to inspect the Public profile.",
                        "Firewall Protection",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);

                    UpdateSecurityStatus(
                        "Public firewall settings need attention",
                        true);

                    return;
                }

                // ----------------------------------------------------
                // TURN ON PUBLIC WI-FI LOCKDOWN
                // ----------------------------------------------------
                if (_lexDeskFirewallPublicProfile == null)
                {
                    ShowLexDeskMessageBox(
                        "LexDesk could not read the Windows Public firewall profile, so nothing was changed.",
                        "Firewall Protection",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);

                    return;
                }

                MessageBoxResult decision =
                    ShowLexDeskMessageBox(
                        "Public Wi-Fi Lockdown gives extra protection on untrusted Public networks such as hotels, airports and cafés.\n\n" +
                        "While it is on:\n" +
                        "• ALL unsolicited incoming connections on the Public profile are blocked.\n" +
                        "• Even normally allowed inbound app exceptions are temporarily ignored.\n" +
                        "• Normal outgoing internet connections stay allowed.\n\n" +
                        "Network printers, file sharing, Remote Desktop or similar inbound features may stop working on Public networks until Lockdown is turned off.\n\n" +
                        "LexDesk will save your current Public firewall settings first so they can be restored.\n\n" +
                        "Windows may ask for Administrator permission. Continue?",
                        "Public Wi-Fi Lockdown",
                        MessageBoxButton.YesNo,
                        MessageBoxImage.Information);

                if (decision != MessageBoxResult.Yes)
                    return;

                if (!SaveLexDeskFirewallPublicLockdownSnapshot(
                        _lexDeskFirewallPublicProfile))
                {
                    ShowLexDeskMessageBox(
                        "LexDesk could not save the current Public firewall settings, so Lockdown was not enabled.\n\nThis safety copy is required before LexDesk changes the profile.",
                        "Firewall Protection",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);

                    return;
                }

                LexDeskFirewallStatusTitle2.Text =
                    "Turning on Public Wi-Fi Lockdown...";

                LexDeskFirewallStatusText2.Text =
                    "LexDesk saved the current Public firewall settings and is enabling stronger inbound protection.";

                string lockdownNetsh =
                    Path.Combine(
                        Environment.SystemDirectory,
                        "netsh.exe");

                var lockdownCommands =
                    new List<LexDeskMaintenanceCommand>
                    {
                        new()
                        {
                            Key = "PUBLICSTATEON",
                            StatusText = "Turning the Public firewall profile on...",
                            FileName = lockdownNetsh,
                            Arguments = "advfirewall set publicprofile state on",
                            StopOnFailure = true
                        },
                        new()
                        {
                            Key = "PUBLICLOCKDOWN",
                            StatusText = "Blocking all unsolicited inbound Public-network connections...",
                            FileName = lockdownNetsh,
                            Arguments = "advfirewall set publicprofile firewallpolicy blockinboundalways,allowoutbound",
                            StopOnFailure = true
                        }
                    };

                LexDeskMaintenanceBatchResult result =
                    await RunElevatedMaintenanceBatchAsync(
                        "firewall_public_lockdown",
                        lockdownCommands);

                if (result.Cancelled)
                {
                    DeleteLexDeskFirewallPublicLockdownSnapshot();
                    await RefreshLexDeskFirewallStatusAsync();

                    ShowLexDeskMessageBox(
                        "Administrator permission was cancelled. Public Wi-Fi Lockdown was not enabled.",
                        "Firewall Protection",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);

                    return;
                }

                bool gotStateExit =
                    TryGetLexDeskMaintenanceExitCode(
                        result.Output,
                        "PUBLICSTATEON",
                        out int stateExit);

                bool gotLockdownExit =
                    TryGetLexDeskMaintenanceExitCode(
                        result.Output,
                        "PUBLICLOCKDOWN",
                        out int lockdownExit);

                bool commandsSucceeded =
                    result.Started &&
                    gotStateExit &&
                    gotLockdownExit &&
                    IsLexDeskMaintenanceSuccessExit(stateExit) &&
                    IsLexDeskMaintenanceSuccessExit(lockdownExit);

                await Task.Delay(500);
                await RefreshLexDeskFirewallStatusAsync();

                if (commandsSucceeded &&
                    _lexDeskFirewallPublicLockdownActive == true)
                {
                    ShowLexDeskMessageBox(
                        "Public Wi-Fi Lockdown is active.\n\nThe Public firewall profile is blocking all unsolicited incoming connections, including normally allowed inbound exceptions. Normal outgoing internet connections remain allowed.\n\nUse Return to Normal Public Protection when you leave the untrusted network.",
                        "Firewall Protection",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);

                    UpdateSecurityStatus(
                        "Public Wi-Fi Lockdown active",
                        false);

                    return;
                }

                ShowLexDeskMessageBox(
                    "Windows did not confirm Public Wi-Fi Lockdown.\n\nLexDesk kept the saved pre-lockdown settings so they are available for recovery. No firewall rules were deleted.",
                    "Firewall Protection",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);

                UpdateSecurityStatus(
                    "Public Wi-Fi Lockdown needs attention",
                    true);
            }
            catch
            {
                await RefreshLexDeskFirewallStatusAsync();

                ShowLexDeskMessageBox(
                    "LexDesk could not finish the Public Wi-Fi Lockdown change. The saved rollback settings were kept if they were created.",
                    "Firewall Protection",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                if (button != null)
                    button.IsEnabled = true;

                UpdateLexDeskFirewallPublicLockdownButton();
            }
        }


        private static string GetLexDeskFirewallProgramRuleName(
            string programPath)
        {
            string fullPath =
                Path.GetFullPath(programPath ?? "")
                    .Trim();

            // Windows paths are case-insensitive. Hash the canonical upper-case
            // path so the same executable always receives the same LexDesk rule.
            string canonicalPath =
                fullPath.ToUpperInvariant();

            byte[] hash =
                System.Security.Cryptography.SHA256.HashData(
                    Encoding.UTF8.GetBytes(canonicalPath));

            string fingerprint =
                Convert.ToHexString(
                    hash.AsSpan(0, 6));

            string rawName =
                Path.GetFileNameWithoutExtension(fullPath);

            var safeName =
                new StringBuilder();

            foreach (char c in rawName)
            {
                if (char.IsLetterOrDigit(c) ||
                    c == ' ' ||
                    c == '-' ||
                    c == '_')
                {
                    safeName.Append(c);
                }
            }

            string displayName =
                safeName.ToString().Trim();

            if (string.IsNullOrWhiteSpace(displayName))
                displayName = "Program";

            if (displayName.Length > 42)
            {
                displayName =
                    displayName.Substring(0, 42).Trim();
            }

            return
                $"LexDesk Block Internet - {displayName} - {fingerprint}";
        }


        private bool IsLexDeskFirewallProgramBlockTargetAllowed(
            string programPath,
            out string reason)
        {
            reason = "";

            try
            {
                if (string.IsNullOrWhiteSpace(programPath) ||
                    !File.Exists(programPath))
                {
                    reason =
                        "LexDesk could not find that program file.";

                    return false;
                }

                string fullPath =
                    Path.GetFullPath(programPath);

                if (!string.Equals(
                        Path.GetExtension(fullPath),
                        ".exe",
                        StringComparison.OrdinalIgnoreCase))
                {
                    reason =
                        "Choose a Windows program file ending in .exe.";

                    return false;
                }

                string currentExe =
                    (Environment.ProcessPath ?? "").Trim();

                if (!string.IsNullOrWhiteSpace(currentExe) &&
                    string.Equals(
                        Path.GetFullPath(currentExe),
                        fullPath,
                        StringComparison.OrdinalIgnoreCase))
                {
                    reason =
                        "LexDesk will not block its own internet access.";

                    return false;
                }

                string windowsFolder =
                    Environment.GetFolderPath(
                        Environment.SpecialFolder.Windows);

                if (!string.IsNullOrWhiteSpace(windowsFolder))
                {
                    string windowsRoot =
                        Path.GetFullPath(windowsFolder)
                            .TrimEnd(
                                Path.DirectorySeparatorChar,
                                Path.AltDirectorySeparatorChar) +
                        Path.DirectorySeparatorChar;

                    if (fullPath.StartsWith(
                            windowsRoot,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        reason =
                            "For safety, LexDesk will not create internet blocks for core Windows files. " +
                            "Choose a normal installed application instead.";

                        return false;
                    }
                }

                return true;
            }
            catch
            {
                reason =
                    "LexDesk could not safely validate that program file.";

                return false;
            }
        }


        private List<LexDeskFirewallBlockedProgramInfo>
            LoadLexDeskFirewallBlockedPrograms()
        {
            try
            {
                if (!File.Exists(
                        _lexDeskFirewallBlockedProgramsPath))
                {
                    return new List<LexDeskFirewallBlockedProgramInfo>();
                }

                string json =
                    File.ReadAllText(
                        _lexDeskFirewallBlockedProgramsPath);

                List<LexDeskFirewallBlockedProgramInfo>? items =
                    JsonSerializer.Deserialize<
                        List<LexDeskFirewallBlockedProgramInfo>>(
                            json,
                            JsonCaseInsensitiveOptions);

                return items ??
                    new List<LexDeskFirewallBlockedProgramInfo>();
            }
            catch
            {
                return new List<LexDeskFirewallBlockedProgramInfo>();
            }
        }


        private bool SaveLexDeskFirewallBlockedPrograms(
