        private bool TryLoadLexDeskFirewallLastChange(
            out LexDeskFirewallLastChangeInfo change)
        {
            change =
                new LexDeskFirewallLastChangeInfo();

            try
            {
                if (!File.Exists(
                        _lexDeskFirewallLastChangePath))
                {
                    return false;
                }

                string json =
                    File.ReadAllText(
                        _lexDeskFirewallLastChangePath);

                LexDeskFirewallLastChangeInfo? loaded =
                    JsonSerializer.Deserialize<
                        LexDeskFirewallLastChangeInfo>(
                            json,
                            JsonCaseInsensitiveOptions);

                if (loaded == null ||
                    string.IsNullOrWhiteSpace(loaded.ActionType))
                {
                    return false;
                }

                change = loaded;
