            }
        }


        private void UpdateLexDeskFirewallUndoButton()
        {
            if (LexDeskFirewallUndoButton2 == null)
                return;

            bool haveUndo =
                TryLoadLexDeskFirewallLastChange(
                    out LexDeskFirewallLastChangeInfo change);

            LexDeskFirewallUndoButton2.IsEnabled =
                haveUndo;

            if (!haveUndo)
            {
                LexDeskFirewallUndoButton2.ToolTip =
                    "There is no recent LexDesk program internet-access change to undo.";

                return;
            }

            string programName =
                string.IsNullOrWhiteSpace(change.ProgramName)
                    ? "the selected program"
                    : change.ProgramName.Trim();

            if (string.Equals(
                    change.ActionType,
                    "BlockProgram",
                    StringComparison.OrdinalIgnoreCase))
            {
                LexDeskFirewallUndoButton2.ToolTip =
                    $"Undo the last LexDesk change by allowing {programName} to access the internet again.";

                return;
            }

            if (string.Equals(
                    change.ActionType,
                    "AllowProgram",
                    StringComparison.OrdinalIgnoreCase))
            {
                LexDeskFirewallUndoButton2.ToolTip =
                    $"Undo the last LexDesk change by restoring the internet block for {programName}.";

                return;
            }

            LexDeskFirewallUndoButton2.ToolTip =
                "The saved firewall change cannot be safely undone automatically.";
        }


        private async Task<(bool Started, bool Cancelled, int ExitCode)>
            RunLexDeskElevatedNetshAsync(
                params string[] arguments)
        {
            try
            {
                string netsh =
                    Path.Combine(
                        Environment.SystemDirectory,
                        "netsh.exe");

                var psi =
                    new ProcessStartInfo
                    {
                        FileName = netsh,
                        UseShellExecute = true,
                        WorkingDirectory = Environment.SystemDirectory,
                        WindowStyle = ProcessWindowStyle.Hidden
                    };

                if (!IsRunningAsAdmin())
                    psi.Verb = "runas";

                foreach (string argument in arguments)
                {
                    psi.ArgumentList.Add(
                        argument ?? "");
                }

                using Process? process =
                    Process.Start(psi);

                if (process == null)
                    return (false, false, -1);

                await process.WaitForExitAsync();

                return (
                    true,
                    false,
                    process.ExitCode);
            }
            catch (System.ComponentModel.Win32Exception ex)
                when (ex.NativeErrorCode == 1223)
            {
                // ERROR_CANCELLED: the user declined the UAC prompt.
                return (false, true, -1);
            }
            catch
            {
                return (false, false, -1);
            }
        }


        private void WriteLexDeskFirewallProgramDebug(string message)
        {
            try
            {
                string? folder =
                    Path.GetDirectoryName(_lexDeskFirewallProgramDebugPath);

                if (!string.IsNullOrWhiteSpace(folder))
                    Directory.CreateDirectory(folder);

                File.AppendAllText(
                    _lexDeskFirewallProgramDebugPath,
                    $"[{DateTime.Now:yyyy-MM-dd HH:mm:ss.fff}] {message}{Environment.NewLine}");
            }
            catch
            {
                // Diagnostics must never affect normal firewall behaviour.
            }
        }


        private async Task<string> RunLexDeskFirewallDebugPowerShellAsync(
            string command)
        {
            try
            {
                var psi =
                    new ProcessStartInfo
                    {
                        FileName = "powershell.exe",
                        UseShellExecute = false,
                        CreateNoWindow = true,
                        RedirectStandardOutput = true,
                        RedirectStandardError = true
                    };

                psi.ArgumentList.Add("-NoProfile");
                psi.ArgumentList.Add("-NonInteractive");
                psi.ArgumentList.Add("-Command");
                psi.ArgumentList.Add(command);

                using Process? process =
                    Process.Start(psi);

                if (process == null)
                    return "PowerShell did not start.";

                string output =
                    await process.StandardOutput.ReadToEndAsync();

                string error =
                    await process.StandardError.ReadToEndAsync();

                await process.WaitForExitAsync();

                return
                    $"EXIT={process.ExitCode}{Environment.NewLine}" +
                    (!string.IsNullOrWhiteSpace(output)
                        ? output.TrimEnd() + Environment.NewLine
                        : "") +
                    (!string.IsNullOrWhiteSpace(error)
                        ? "STDERR:" + Environment.NewLine + error.TrimEnd() + Environment.NewLine
                        : "");
            }
            catch (Exception ex)
            {
                return "PowerShell exception: " + ex.Message;
            }
        }


        private async Task CaptureLexDeskFirewallProgramDebugAsync(
            string stage,
            string ruleName,
            string programPath)
        {
            try
            {
                programPath =
                    NormalizeLexDeskFirewallProgramPath(programPath);

                string safeRule =
                    (ruleName ?? "").Replace("'", "''");

                string safePath =
                    (programPath ?? "").Replace("'", "''");

                string safeDirectory = "";

                try
                {
                    safeDirectory =
                        (Path.GetDirectoryName(programPath) ?? "")
                            .Replace("'", "''");
                }
                catch { }

                WriteLexDeskFirewallProgramDebug(
                    "============================================================");
                WriteLexDeskFirewallProgramDebug(
                    $"STAGE={stage}");
                WriteLexDeskFirewallProgramDebug(
                    $"RULE={ruleName}");
                WriteLexDeskFirewallProgramDebug(
                    $"PROGRAM={programPath}");
                WriteLexDeskFirewallProgramDebug(
                    $"FILE_EXISTS={File.Exists(programPath)}");

                string command =
                    "$ErrorActionPreference='SilentlyContinue'; " +
                    "$ruleName='" + safeRule + "'; " +
                    "$target='" + safePath + "'; " +
                    "$targetDir='" + safeDirectory + "'; " +
                    "Write-Output '--- FIREWALL SERVICES ---'; " +
                    "Get-Service MpsSvc,BFE | Select-Object Name,Status,StartType | Format-List | Out-String | Write-Output; " +
                    "Write-Output '--- WINDOWS SECURITY FIREWALL PRODUCTS ---'; " +
                    "Get-CimInstance -Namespace root/SecurityCenter2 -ClassName FirewallProduct -ErrorAction SilentlyContinue | Select-Object displayName,productState,pathToSignedProductExe,pathToSignedReportingExe | ForEach-Object { $_ | Add-Member -NotePropertyName productStateHex -NotePropertyValue ('0x{0:X6}' -f [int]$_.productState) -PassThru } | Format-List | Out-String | Write-Output; " +
                    "Write-Output '--- CONNECTION PROFILES ---'; " +
                    "Get-NetConnectionProfile | Select-Object Name,InterfaceAlias,NetworkCategory,IPv4Connectivity,IPv6Connectivity | Format-List | Out-String | Write-Output; " +
                    "Write-Output '--- FIREWALL PROFILES ---'; " +
                    "Get-NetFirewallProfile -PolicyStore ActiveStore | Select-Object Name,Enabled,DefaultInboundAction,DefaultOutboundAction,AllowInboundRules,AllowLocalFirewallRules | Format-List | Out-String | Write-Output; " +
                    "Write-Output '--- LEXDESK RULE ---'; " +
                    "$r=Get-NetFirewallRule -DisplayName $ruleName -PolicyStore ActiveStore; " +
                    "if($r){$r | Select-Object Name,DisplayName,Enabled,Profile,Direction,Action,PrimaryStatus,Status,StatusCode,PolicyStoreSourceType,PolicyStoreSource | Format-List | Out-String | Write-Output; " +
                    "Write-Output '--- APPLICATION FILTER ---'; $r | Get-NetFirewallApplicationFilter | Select-Object Program,Package | Format-List | Out-String | Write-Output; " +
                    "Write-Output '--- SERVICE FILTER ---'; $r | Get-NetFirewallServiceFilter | Select-Object Service | Format-List | Out-String | Write-Output; " +
                    "Write-Output '--- PORT FILTER ---'; $r | Get-NetFirewallPortFilter | Select-Object Protocol,LocalPort,RemotePort,IcmpType | Format-List | Out-String | Write-Output} else {Write-Output 'RULE NOT FOUND'}; " +
                    "Write-Output '--- ALL EFFECTIVE RULES FOR EXACT PROGRAM ---'; " +
                    "Get-NetFirewallRule -PolicyStore ActiveStore | ForEach-Object { $rr=$_; $af=$rr | Get-NetFirewallApplicationFilter; if($af -and $af.Program -and ([Environment]::ExpandEnvironmentVariables([string]$af.Program) -ieq $target)){[PSCustomObject]@{DisplayName=$rr.DisplayName;Enabled=$rr.Enabled;Profile=$rr.Profile;Direction=$rr.Direction;Action=$rr.Action;PrimaryStatus=$rr.PrimaryStatus;Status=$rr.Status;StatusCode=$rr.StatusCode;Program=$af.Program;SourceType=$rr.PolicyStoreSourceType}} } | Format-List | Out-String | Write-Output; " +
                    "Write-Output '--- RELATED PROCESSES ---'; " +
                    "$procs=Get-CimInstance Win32_Process | Where-Object { $_.ExecutablePath -and ( $_.ExecutablePath -ieq $target -or ($targetDir -and $_.ExecutablePath.StartsWith($targetDir,[StringComparison]::OrdinalIgnoreCase)) ) }; " +
                    "$procs | Select-Object ProcessId,ParentProcessId,Name,ExecutablePath,CommandLine | Format-List | Out-String | Write-Output; " +
                    "Write-Output '--- TCP CONNECTIONS OWNED BY RELATED PROCESSES ---'; " +
                    "$ids=@($procs | ForEach-Object {[int]$_.ProcessId}); if($ids.Count -gt 0){Get-NetTCPConnection | Where-Object {$ids -contains [int]$_.OwningProcess} | Select-Object OwningProcess,State,LocalAddress,LocalPort,RemoteAddress,RemotePort | Sort-Object OwningProcess,State | Format-Table -AutoSize | Out-String | Write-Output}else{Write-Output 'NO RELATED PROCESSES'}; ";

                string result =
                    await RunLexDeskFirewallDebugPowerShellAsync(command);

                try
                {
                    File.AppendAllText(
                        _lexDeskFirewallProgramDebugPath,
                        result + Environment.NewLine);
                }
                catch { }
            }
            catch (Exception ex)
            {
                WriteLexDeskFirewallProgramDebug(
                    "CAPTURE EXCEPTION: " + ex.Message);
            }
        }


