        private async Task<bool> VerifyLexDeskFirewallProgramBlockAsync(
            string ruleName,
            string programPath)
        {
            try
            {
                string safeRuleName =
                    (ruleName ?? "").Replace("'", "''");

                string safeProgramPath =
                    (programPath ?? "").Replace("'", "''");

                string command =
                    "$rule = Get-NetFirewallRule -DisplayName '" +
                    safeRuleName +
                    "' -PolicyStore ActiveStore -ErrorAction SilentlyContinue | " +
                    "Where-Object { $_.Enabled -eq 'True' -and $_.Direction -eq 'Outbound' -and $_.Action -eq 'Block' -and ([string]$_.PrimaryStatus) -eq 'OK' } | " +
                    "Select-Object -First 1; " +
                    "if ($null -eq $rule) { exit 3 }; " +
                    "$filter = $rule | Get-NetFirewallApplicationFilter -ErrorAction SilentlyContinue; " +
                    "if ($null -eq $filter) { exit 4 }; " +
                    "$actual = [Environment]::ExpandEnvironmentVariables([string]$filter.Program); " +
                    "$expected = [Environment]::ExpandEnvironmentVariables('" +
                    safeProgramPath +
                    "'); " +
                    "try { $actual = [IO.Path]::GetFullPath($actual); $expected = [IO.Path]::GetFullPath($expected) } catch { exit 5 }; " +
                    "if ([string]::Equals($actual, $expected, [StringComparison]::OrdinalIgnoreCase)) { exit 0 } else { exit 6 }";

                var psi =
                    new ProcessStartInfo
                    {
                        FileName = "powershell.exe",
                        UseShellExecute = false,
                        CreateNoWindow = true
                    };

                psi.ArgumentList.Add("-NoProfile");
                psi.ArgumentList.Add("-NonInteractive");
                psi.ArgumentList.Add("-Command");
                psi.ArgumentList.Add(command);

                using Process? process =
                    Process.Start(psi);

                if (process == null)
                    return false;

                await process.WaitForExitAsync();
                return process.ExitCode == 0;
            }
            catch
            {
                return false;
            }
        }


        private static List<int> GetLexDeskFirewallProgramProcessIds(
            string programPath)
        {
            var processIds = new List<int>();

            try
            {
                string fullPath =
                    Path.GetFullPath(programPath ?? "");

                string processName =
                    Path.GetFileNameWithoutExtension(fullPath);

                if (string.IsNullOrWhiteSpace(processName))
                    return processIds;

                foreach (Process process in
                         Process.GetProcessesByName(processName))
                {
                    try
                    {
                        string runningPath =
                            process.MainModule?.FileName ?? "";

                        if (!string.IsNullOrWhiteSpace(runningPath) &&
                            string.Equals(
                                Path.GetFullPath(runningPath),
                                fullPath,
                                StringComparison.OrdinalIgnoreCase))
                        {
                            processIds.Add(process.Id);
                        }
                    }
                    catch
                    {
                        // Protected/system-owned processes may hide MainModule.
                        // Never guess that they belong to the selected program.
                    }
                    finally
                    {
                        process.Dispose();
                    }
                }
            }
            catch
            {
            }

            return processIds.Distinct().ToList();
        }


        private static bool LexDeskFirewallProcessHasVisibleWindow(int processId)
        {
            try
            {
                using Process process =
                    Process.GetProcessById(processId);

                return process.MainWindowHandle != IntPtr.Zero;
            }
            catch
            {
                return false;
            }
        }


        private async Task<bool> CloseLexDeskFirewallProgramInstancesAsync(
            string programPath,
            string programName)
        {
            List<int> processIds =
                GetLexDeskFirewallProgramProcessIds(programPath);

            if (processIds.Count == 0)
                return true;

            // First ask every normal app window to close cleanly. This preserves
            // native Save / Don't Save / Cancel prompts for Office and similar apps.
            foreach (int processId in processIds)
            {
                try
                {
                    using Process process =
                        Process.GetProcessById(processId);

                    if (process.MainWindowHandle != IntPtr.Zero)
                        process.CloseMainWindow();
                }
                catch
                {
                }
            }

            // Give normal close/save prompts a reasonable chance to finish.
            for (int attempt = 0; attempt < 20; attempt++)
            {
                await Task.Delay(250);

                if (GetLexDeskFirewallProgramProcessIds(programPath).Count == 0)
                    return true;
            }

            List<int> remaining =
                GetLexDeskFirewallProgramProcessIds(programPath);

            if (remaining.Count == 0)
                return true;

            // If a visible window remains, the user may be looking at a save or
            // confirmation prompt. Never bulldoze through it.
            if (remaining.Any(LexDeskFirewallProcessHasVisibleWindow))
            {
                ShowLexDeskMessageBox(
                    $"{programName} is still open.\n\n" +
                    "Finish any Save / Don't Save / Cancel prompts, then close the app completely before testing the firewall block.\n\n" +
                    "LexDesk will not force-close a visible app window because that could lose unsaved work.",
                    "Program Still Open",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);

                return false;
            }

            MessageBoxResult forceDecision =
                ShowLexDeskMessageBox(
                    $"{programName} still has {remaining.Count} background process" +
                    (remaining.Count == 1 ? "" : "es") +
                    " running even though its windows are closed.\n\n" +
                    "Those background processes can keep old network connections alive and make a new firewall block look as though it is not working.\n\n" +
                    "End those background instances now?",
                    "Finish Applying Internet Block",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Information);

            if (forceDecision != MessageBoxResult.Yes)
                return false;

            // At this point only background instances with no visible window remain.
            // End only processes whose executable path exactly matches the chosen app.
            foreach (int processId in remaining)
            {
                try
                {
                    using Process process =
                        Process.GetProcessById(processId);

                    string runningPath =
                        process.MainModule?.FileName ?? "";

                    if (string.IsNullOrWhiteSpace(runningPath) ||
                        !string.Equals(
                            Path.GetFullPath(runningPath),
                            Path.GetFullPath(programPath),
                            StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    process.Kill(entireProcessTree: true);
                }
                catch
                {
                }
            }

            for (int attempt = 0; attempt < 12; attempt++)
            {
                await Task.Delay(250);

                if (GetLexDeskFirewallProgramProcessIds(programPath).Count == 0)
                    return true;
            }

            ShowLexDeskMessageBox(
                $"Windows kept part of {programName} running.\n\n" +
                "The firewall rule is active, but fully exit the app before testing it again.",
                "Program Still Running",
                MessageBoxButton.OK,
                MessageBoxImage.Warning);

            return false;
        }


        private static bool IsLexDeskFirewallProgramRunning(
            string programPath)
        {
            try
            {
                string fullPath =
                    Path.GetFullPath(programPath ?? "");

                string processName =
                    Path.GetFileNameWithoutExtension(fullPath);

                if (string.IsNullOrWhiteSpace(processName))
                    return false;

                foreach (Process process in
                         Process.GetProcessesByName(processName))
                {
                    try
                    {
                        string runningPath =
                            process.MainModule?.FileName ?? "";

                        if (!string.IsNullOrWhiteSpace(runningPath) &&
                            string.Equals(
                                Path.GetFullPath(runningPath),
                                fullPath,
                                StringComparison.OrdinalIgnoreCase))
                        {
                            return true;
                        }
                    }
                    catch
                    {
                        // Some protected processes do not expose MainModule.
                    }
                    finally
                    {
                        process.Dispose();
                    }
                }
            }
            catch
            {
            }

            return false;
        }


        private static string NormalizeLexDeskFirewallProgramPath(
            string value)
        {
            try
            {
                string path =
                    Environment.ExpandEnvironmentVariables(
                        (value ?? "").Trim().Trim('"'));

                if (string.IsNullOrWhiteSpace(path))
                    return "";

                return Path.GetFullPath(path);
            }
            catch
            {
                return "";
            }
        }


        private Task<List<LexDeskFirewallProgramListItem>>
            ResolveLexDeskFirewallProgramsStaAsync(
                IReadOnlyList<LexDeskInstalledApp> apps)
        {
            var completion =
                new TaskCompletionSource<
                    List<LexDeskFirewallProgramListItem>>(
                        TaskCreationOptions.RunContinuationsAsynchronously);

            var thread =
                new System.Threading.Thread(() =>
                {
                    try
                    {
                        var byPath =
                            new Dictionary<string, LexDeskFirewallProgramListItem>(
                                StringComparer.OrdinalIgnoreCase);

                        foreach (LexDeskInstalledApp app in
                                 apps ?? Array.Empty<LexDeskInstalledApp>())
                        {
                            if (app == null ||
                                string.IsNullOrWhiteSpace(app.Name))
                            {
                                continue;
                            }

                            string programPath = "";

                            if (TryGetLexDeskForcedLaunchOverride(
                                    app,
                                    out string forcedExe,
                                    out _,
                                    out _,
                                    out _,
                                    out _) &&
                                File.Exists(forcedExe))
                            {
                                programPath = forcedExe;
                            }
                            else if (app.LaunchType == LexDeskLaunchType.Exe &&
                                     File.Exists(app.Target))
                            {
                                programPath = app.Target;
                            }
                            else if (app.LaunchType == LexDeskLaunchType.Shortcut)
                            {
                                string shortcutPath =
                                    !string.IsNullOrWhiteSpace(app.ShortcutPath)
                                        ? app.ShortcutPath
                                        : app.Target;

                                if (TryResolveLexDeskShortcutViaWScript(
                                        shortcutPath,
                                        out string exe,
                                        out _,
                                        out _) &&
                                    File.Exists(exe))
                                {
                                    programPath = exe;
                                }
                            }
                            else if (!string.IsNullOrWhiteSpace(app.Target) &&
                                     app.Target.EndsWith(
                                         ".exe",
                                         StringComparison.OrdinalIgnoreCase) &&
                                     File.Exists(app.Target))
                            {
                                programPath = app.Target;
                            }

                            programPath =
                                NormalizeLexDeskFirewallProgramPath(
                                    programPath);

                            if (string.IsNullOrWhiteSpace(programPath))
                                continue;

                            if (!IsLexDeskFirewallProgramBlockTargetAllowed(
                                    programPath,
                                    out _))
                            {
                                continue;
                            }

                            if (byPath.ContainsKey(programPath))
                                continue;

                            byPath[programPath] =
                                new LexDeskFirewallProgramListItem
                                {
                                    Name = app.Name.Trim(),
                                    ProgramPath = programPath
                                };
                        }

                        completion.TrySetResult(
                            byPath.Values
                                .OrderBy(
                                    item => item.Name,
                                    StringComparer.OrdinalIgnoreCase)
                                .ToList());
                    }
                    catch (Exception ex)
                    {
                        completion.TrySetException(ex);
                    }
                });

            thread.IsBackground = true;
            thread.SetApartmentState(
                System.Threading.ApartmentState.STA);
            thread.Start();

            return completion.Task;
        }


        private async Task<HashSet<string>>
            GetLexDeskOtherOutboundBlockedProgramPathsAsync()
        {
            var paths =
                new HashSet<string>(
                    StringComparer.OrdinalIgnoreCase);

            try
            {
                string command =
                    "$items = Get-NetFirewallRule -PolicyStore ActiveStore " +
                    "-Enabled True -Direction Outbound -Action Block -ErrorAction SilentlyContinue | " +
                    "Get-NetFirewallApplicationFilter -ErrorAction SilentlyContinue | " +
                    "Where-Object { $_.Program -and $_.Program -ne 'Any' } | " +
                    "ForEach-Object { [Environment]::ExpandEnvironmentVariables([string]$_.Program) } | " +
                    "Sort-Object -Unique; " +
                    "ConvertTo-Json -InputObject @($items) -Compress";

                var psi =
                    new ProcessStartInfo
                    {
                        FileName = "powershell.exe",
                        UseShellExecute = false,
                        CreateNoWindow = true,
                        RedirectStandardOutput = true,
                        RedirectStandardError = true
                    };

                psi.ArgumentList.Add("-NoProfile");
                psi.ArgumentList.Add("-NonInteractive");
                psi.ArgumentList.Add("-Command");
                psi.ArgumentList.Add(command);

                using var process =
                    new Process
                    {
                        StartInfo = psi
                    };

                process.Start();

                string output =
                    await process.StandardOutput.ReadToEndAsync();

                await process.StandardError.ReadToEndAsync();
                await process.WaitForExitAsync();

                if (process.ExitCode != 0 ||
                    string.IsNullOrWhiteSpace(output))
                {
                    return paths;
                }

                List<string>? returned =
                    JsonSerializer.Deserialize<List<string>>(
                        output,
                        JsonCaseInsensitiveOptions);

                if (returned == null)
                    return paths;

                foreach (string item in returned)
                {
                    string path =
                        NormalizeLexDeskFirewallProgramPath(item);

                    if (!string.IsNullOrWhiteSpace(path))
                        paths.Add(path);
                }
            }
            catch
            {
                // A third-party firewall-rule check is informative only.
                // Failure must never stop the Program Internet Access manager.
            }

            return paths;
        }


        private async Task ShowLexDeskFirewallProgramManagerAsync(
            bool forceRefresh = false)
        {
            LexDeskFirewallProtectionCard2.Visibility =
                Visibility.Collapsed;

            LexDeskFirewallProgramManagerCard2.Visibility =
                Visibility.Visible;

            if (LexDeskFirewallProgramSearchBox2 != null &&
                forceRefresh)
            {
                LexDeskFirewallProgramSearchBox2.Text = "";
            }

            await RefreshLexDeskFirewallProgramManagerAsync(
                forceRefresh);
        }


        private async Task RefreshLexDeskFirewallProgramManagerAsync(
            bool forceRefresh = false)
        {
            try
            {
                LexDeskFirewallProgramManagerStatusText2.Text =
                    "Loading installed programs...";

                _lexDeskThirdPartyFirewallNames =
                    await GetLexDeskRegisteredThirdPartyFirewallNamesAsync();

                LexDeskFirewallProgramSelectionText2.Text =
                    "Select a program to see its internet-access status.";

                LexDeskFirewallProgramBlockButton2.IsEnabled = false;
                LexDeskFirewallProgramAllowButton2.IsEnabled = false;

                List<LexDeskInstalledApp> apps =
                    await GetLexDeskInstalledAppsCachedAsync(
                        forceRefresh);

                List<LexDeskFirewallProgramListItem> resolved =
                    await ResolveLexDeskFirewallProgramsStaAsync(
                        apps);

                List<LexDeskFirewallBlockedProgramInfo> lexDeskBlocks =
                    LoadLexDeskFirewallBlockedPrograms();

                HashSet<string> otherBlockedPaths =
                    await GetLexDeskOtherOutboundBlockedProgramPathsAsync();

                var byPath =
                    new Dictionary<string, LexDeskFirewallProgramListItem>(
                        StringComparer.OrdinalIgnoreCase);

                foreach (LexDeskFirewallProgramListItem item in resolved)
                {
                    string path =
                        NormalizeLexDeskFirewallProgramPath(
                            item.ProgramPath);

                    if (string.IsNullOrWhiteSpace(path))
                        continue;

                    item.ProgramPath = path;
                    byPath[path] = item;
                }

                // Keep LexDesk-owned blocks visible even if the app was portable,
                // removed from the Start menu, or is not in the current app cache.
                foreach (LexDeskFirewallBlockedProgramInfo blocked in lexDeskBlocks)
                {
                    string path =
                        NormalizeLexDeskFirewallProgramPath(
                            blocked.ProgramPath);

                    if (string.IsNullOrWhiteSpace(path))
                        continue;

                    if (!byPath.TryGetValue(
                            path,
                            out LexDeskFirewallProgramListItem? item))
                    {
                        item =
                            new LexDeskFirewallProgramListItem
                            {
                                Name =
                                    string.IsNullOrWhiteSpace(blocked.ProgramName)
                                        ? Path.GetFileName(path)
                                        : blocked.ProgramName,
                                ProgramPath = path
                            };

                        byPath[path] = item;
                    }

                    item.IsBlockedByLexDesk = true;
                    item.RuleName = blocked.RuleName ?? "";
                    item.Status = "Blocked by LexDesk";
                }

                foreach (LexDeskFirewallProgramListItem item in byPath.Values)
                {
                    if (item.IsBlockedByLexDesk)
                        continue;

                    if (otherBlockedPaths.Contains(item.ProgramPath))
                    {
                        item.IsBlockedByOtherRule = true;
                        item.Status = "Other firewall block detected";
                    }
                    else
                    {
                        item.Status = "Allowed normally";
                    }
                }

                _lexDeskFirewallProgramItems =
                    byPath.Values
                        .OrderByDescending(
                            item => item.IsBlockedByLexDesk)
                        .ThenByDescending(
                            item => item.IsBlockedByOtherRule)
                        .ThenBy(
                            item => item.Name,
                            StringComparer.OrdinalIgnoreCase)
                        .ToList();

                int blockedCount =
                    _lexDeskFirewallProgramItems.Count(
                        item => item.IsBlockedByLexDesk);

                LexDeskFirewallBlockedProgramCountText2.Text =
                    blockedCount == 1
                        ? "1 blocked"
                        : $"{blockedCount} blocked";

                LexDeskFirewallProgramManagerStatusText2.Text =
                    !string.IsNullOrWhiteSpace(_lexDeskThirdPartyFirewallNames)
                        ? $"{_lexDeskThirdPartyFirewallNames} controls app firewall rules on this PC"
                        : _lexDeskFirewallProgramItems.Count == 0
                            ? "No normal desktop programs were found. Use Choose another program for a portable app."
                            : $"{_lexDeskFirewallProgramItems.Count} programs available";

                ApplyLexDeskFirewallProgramFilter();
            }
            catch
            {
                _lexDeskFirewallProgramItems = new();
                LexDeskFirewallProgramList2.ItemsSource = null;
                LexDeskFirewallBlockedProgramCountText2.Text = "0 blocked";
                LexDeskFirewallProgramManagerStatusText2.Text =
                    "LexDesk could not build the installed-program list. Use Choose another program instead.";
            }
        }


        private void ApplyLexDeskFirewallProgramFilter()
        {
            string search =
                LexDeskFirewallProgramSearchBox2?.Text?.Trim() ?? "";

            IEnumerable<LexDeskFirewallProgramListItem> filtered =
                _lexDeskFirewallProgramItems;

            if (!string.IsNullOrWhiteSpace(search))
            {
                filtered =
                    filtered.Where(item =>
                        item.Name.Contains(
                            search,
                            StringComparison.OrdinalIgnoreCase) ||
                        item.ProgramPath.Contains(
                            search,
                            StringComparison.OrdinalIgnoreCase) ||
                        item.Status.Contains(
                            search,
                            StringComparison.OrdinalIgnoreCase));
            }

            LexDeskFirewallProgramList2.ItemsSource =
                filtered.ToList();

            LexDeskFirewallProgramList2.SelectedItem = null;
            UpdateLexDeskFirewallProgramSelection();
        }


        private void UpdateLexDeskFirewallProgramSelection()
        {
            LexDeskFirewallProgramListItem? selected =
                LexDeskFirewallProgramList2.SelectedItem as
                    LexDeskFirewallProgramListItem;

            if (selected == null)
            {
                LexDeskFirewallProgramBlockButton2.IsEnabled = false;
                LexDeskFirewallProgramAllowButton2.IsEnabled = false;
                LexDeskFirewallProgramSelectionText2.Text =
                    "Select a program to see its internet-access status.";
                return;
            }

            if (selected.IsBlockedByLexDesk)
            {
                LexDeskFirewallProgramBlockButton2.IsEnabled = false;
                LexDeskFirewallProgramAllowButton2.IsEnabled = true;
                LexDeskFirewallProgramSelectionText2.Text =
                    $"{selected.Name} is blocked by a LexDesk-owned firewall rule. " +
                    "Allow Internet Access removes only that LexDesk rule.";
                return;
            }

            if (selected.IsBlockedByOtherRule)
            {
                LexDeskFirewallProgramBlockButton2.IsEnabled = false;
                LexDeskFirewallProgramAllowButton2.IsEnabled = false;
                LexDeskFirewallProgramSelectionText2.Text =
                    $"Windows reports another outbound firewall block for {selected.Name}. " +
                    "LexDesk did not create that rule, so it will not remove or replace it.";
                return;
            }

            if (!string.IsNullOrWhiteSpace(
                    _lexDeskThirdPartyFirewallNames))
            {
                LexDeskFirewallProgramBlockButton2.IsEnabled = false;
                LexDeskFirewallProgramAllowButton2.IsEnabled = false;
                LexDeskFirewallProgramSelectionText2.Text =
                    $"{_lexDeskThirdPartyFirewallNames} is registered as the firewall provider. " +
                    "Use its Firewall / Application Rules to block this program; LexDesk will not create a Windows rule that may remain inactive.";
                return;
            }

            LexDeskFirewallProgramBlockButton2.IsEnabled = true;
            LexDeskFirewallProgramAllowButton2.IsEnabled = false;
            LexDeskFirewallProgramSelectionText2.Text =
                $"{selected.Name} is not blocked by LexDesk. " +
                "Block Internet Access will create one outbound Windows Firewall rule for this executable.";
        }


