        private async Task<bool> ApplyLexDeskFirewallProgramBlockAsync(
            string programPath,
            string programName)
        {
            programPath =
                NormalizeLexDeskFirewallProgramPath(
                    programPath);

            if (!IsLexDeskFirewallProgramBlockTargetAllowed(
                    programPath,
                    out string reason))
            {
                ShowLexDeskMessageBox(
                    reason,
                    "Block a Program",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);

                return false;
            }

            if (string.IsNullOrWhiteSpace(programName))
                programName = Path.GetFileName(programPath);

            _lexDeskThirdPartyFirewallNames =
                await GetLexDeskRegisteredThirdPartyFirewallNamesAsync();

            if (!string.IsNullOrWhiteSpace(
                    _lexDeskThirdPartyFirewallNames))
            {
                ShowLexDeskMessageBox(
                    GetLexDeskThirdPartyFirewallGuidance(
                        programName,
                        programPath),
                    "Firewall Provider Controls This PC",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);

                return false;
            }

            string ruleName =
                GetLexDeskFirewallProgramRuleName(
                    programPath);

            List<LexDeskFirewallBlockedProgramInfo> existing =
                LoadLexDeskFirewallBlockedPrograms();

            if (existing.Any(item =>
                    string.Equals(
                        NormalizeLexDeskFirewallProgramPath(item.ProgramPath),
                        programPath,
                        StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(
                        item.RuleName,
                        ruleName,
                        StringComparison.OrdinalIgnoreCase)))
            {
                ShowLexDeskMessageBox(
                    $"{programName} is already blocked by LexDesk.\n\nNo duplicate firewall rule was added.",
                    "Program Internet Access",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);

                return false;
            }

            MessageBoxResult decision =
                ShowLexDeskMessageBox(
                    $"Block {programName} from accessing the internet?\n\n" +
                    "LexDesk will create one outbound Windows Firewall rule for this program on all network types.\n\n" +
                    "This does NOT uninstall, delete or modify the program. It only blocks outgoing network connections from this executable.\n\n" +
                    "If the program is already running, close and reopen it after the block is applied.\n\n" +
                    "Windows may ask for Administrator permission. Continue?",
                    "Block Internet Access",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Information);

            if (decision != MessageBoxResult.Yes)
                return false;

            LexDeskFirewallProgramManagerStatusText2.Text =
                $"Blocking internet access for {programName}...";

            (bool started, bool cancelled, int exitCode) =
                await RunLexDeskElevatedNetshAsync(
                    "advfirewall",
                    "firewall",
                    "add",
                    "rule",
                    $"name={ruleName}",
                    "dir=out",
                    "action=block",
                    $"program={programPath}",
                    "enable=yes",
                    "profile=any");

            if (cancelled)
            {
                ShowLexDeskMessageBox(
                    "Administrator permission was cancelled. No program block was added.",
                    "Program Internet Access",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return false;
            }

            if (!started || exitCode != 0)
            {
                ShowLexDeskMessageBox(
                    "Windows Firewall did not confirm the program block. Nothing was added to LexDesk's blocked-program list.",
                    "Program Internet Access",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
                return false;
            }

            bool ruleVerified =
                await VerifyLexDeskFirewallProgramBlockAsync(
                    ruleName,
                    programPath);

            if (!ruleVerified)
            {
                // Capture why Windows does not consider the rule fully usable
                // before LexDesk removes its own unverified rule.
                await CaptureLexDeskFirewallProgramDebugAsync(
                    "RULE VERIFICATION FAILED",
                    ruleName,
                    programPath);

                // The rule name belongs to LexDesk, so clean up only that rule
                // if Windows did not bind/enforce it as expected.
                await RunLexDeskElevatedNetshAsync(
                    "advfirewall",
                    "firewall",
                    "delete",
                    "rule",
                    $"name={ruleName}");

                _lexDeskThirdPartyFirewallNames =
                    await GetLexDeskRegisteredThirdPartyFirewallNamesAsync();

                string verificationMessage =
                    "Windows reported that the firewall rule was added, but LexDesk could not verify that Windows considers it active and attached to the exact program file.\n\n" +
                    "For safety, LexDesk removed that unverified rule and did not mark the program as blocked.";

                if (!string.IsNullOrWhiteSpace(
                        _lexDeskThirdPartyFirewallNames))
                {
                    verificationMessage +=
                        $"\n\nWindows Security reports {_lexDeskThirdPartyFirewallNames} as the registered firewall provider. Use that provider's Firewall / Application Rules to control program internet access.";
                }

                ShowLexDeskMessageBox(
                    verificationMessage,
                    "Program Internet Access",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);

                return false;
            }

            await CaptureLexDeskFirewallProgramDebugAsync(
                "AFTER RULE VERIFIED",
                ruleName,
                programPath);

            bool programStillRunning =
                IsLexDeskFirewallProgramRunning(
                    programPath);

            var record =
                new LexDeskFirewallBlockedProgramInfo
                {
                    RuleName = ruleName,
                    ProgramPath = programPath,
                    ProgramName = programName,
                    CreatedUtc = DateTime.UtcNow.ToString("O")
                };

            existing.RemoveAll(item =>
                string.Equals(
                    item.RuleName,
                    ruleName,
                    StringComparison.OrdinalIgnoreCase));
            existing.Add(record);

            bool trackingSaved =
                SaveLexDeskFirewallBlockedPrograms(existing);

            bool lastChangeSaved =
                SaveLexDeskFirewallLastChange(
                    new LexDeskFirewallLastChangeInfo
                    {
                        ActionType = "BlockProgram",
                        RuleName = ruleName,
                        ProgramPath = programPath,
                        ProgramName = programName,
                        SavedUtc = DateTime.UtcNow.ToString("O")
                    });

            UpdateSecurityStatus(
                $"Internet access blocked for {programName}",
                false);

            if (!trackingSaved || !lastChangeSaved)
            {
                ShowLexDeskMessageBox(
                    $"Windows Firewall blocked {programName}, but LexDesk could not save all local tracking information.\n\n" +
                    "The firewall rule is active. Open Advanced Firewall can still remove it if needed.",
                    "Program Block Added",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            else
            {
                if (programStillRunning)
                {
                    MessageBoxResult closeDecision =
                        ShowLexDeskMessageBox(
                            $"The Windows Firewall rule for {programName} is active and verified.\n\n" +
                            $"Blocked executable:\n{programPath}\n\n" +
                            "The program is still running. Existing browser/app connections can remain alive and make the new block look ineffective.\n\n" +
                            "Close all running instances now so the next launch is a clean firewall test?\n\n" +
                            "Apps with unsaved work will receive their normal Save / Don't Save / Cancel prompt.",
                            "Finish Applying Internet Block",
                            MessageBoxButton.YesNo,
                            MessageBoxImage.Information);

                    if (closeDecision == MessageBoxResult.Yes)
                    {
                        bool fullyClosed =
                            await CloseLexDeskFirewallProgramInstancesAsync(
                                programPath,
                                programName);

                        if (fullyClosed)
                        {
                            ShowLexDeskMessageBox(
                                $"{programName} is fully closed and its verified outbound firewall block is active.\n\n" +
                                "Reopen the program and try a NEW website or online action. It should no longer be able to make outgoing internet connections.",
                                "Program Block Ready to Test",
                                MessageBoxButton.OK,
                                MessageBoxImage.Information);
                        }
                        else
                        {
                            ShowLexDeskMessageBox(
                                $"The firewall block for {programName} is active and verified.\n\n" +
                                "One or more app processes are still running, so finish closing the app before judging the block.",
                                "Firewall Block Active",
                                MessageBoxButton.OK,
                                MessageBoxImage.Information);
                        }
                    }
                    else
                    {
                        ShowLexDeskMessageBox(
                            $"The outbound firewall block for {programName} is active and verified.\n\n" +
                            "Fully close the app before testing. Background processes or already-established connections may continue until the app exits completely.",
                            "Firewall Block Active",
                            MessageBoxButton.OK,
                            MessageBoxImage.Information);
                    }
                }
                else
                {
                    ShowLexDeskMessageBox(
                        $"{programName} is now blocked from making outgoing internet connections.\n\n" +
                        $"Blocked executable:\n{programPath}\n\n" +
                        "Reopen the program and try a new online connection to test the block.",
                        "Program Block Added",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                }
            }

            return true;
        }


        private async Task<bool> RemoveLexDeskFirewallProgramBlockAsync(
            LexDeskFirewallProgramListItem item)
        {
            if (item == null ||
                !item.IsBlockedByLexDesk ||
                string.IsNullOrWhiteSpace(item.RuleName) ||
                !item.RuleName.StartsWith(
                    "LexDesk Block Internet - ",
                    StringComparison.Ordinal))
            {
                return false;
            }

            MessageBoxResult decision =
                ShowLexDeskMessageBox(
                    $"Allow {item.Name} to access the internet again?\n\n" +
                    "LexDesk will remove only the outbound firewall rule that LexDesk created for this program.\n\n" +
                    "Other Windows or third-party firewall rules will not be changed.\n\n" +
                    "Windows may ask for Administrator permission. Continue?",
                    "Allow Internet Access",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Information);

            if (decision != MessageBoxResult.Yes)
                return false;

            LexDeskFirewallProgramManagerStatusText2.Text =
                $"Restoring normal internet access for {item.Name}...";

            (bool started, bool cancelled, int exitCode) =
                await RunLexDeskElevatedNetshAsync(
                    "advfirewall",
                    "firewall",
                    "delete",
                    "rule",
                    $"name={item.RuleName}");

            if (cancelled)
            {
                ShowLexDeskMessageBox(
                    "Administrator permission was cancelled. The LexDesk firewall block was left unchanged.",
                    "Program Internet Access",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return false;
            }

            if (!started || exitCode != 0)
            {
                ShowLexDeskMessageBox(
                    "Windows Firewall did not confirm removal of the LexDesk program block.",
                    "Program Internet Access",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
                return false;
            }

            List<LexDeskFirewallBlockedProgramInfo> existing =
                LoadLexDeskFirewallBlockedPrograms();

            existing.RemoveAll(record =>
                string.Equals(
                    record.RuleName,
                    item.RuleName,
                    StringComparison.OrdinalIgnoreCase) ||
                string.Equals(
                    NormalizeLexDeskFirewallProgramPath(record.ProgramPath),
                    item.ProgramPath,
                    StringComparison.OrdinalIgnoreCase));

            SaveLexDeskFirewallBlockedPrograms(existing);

            SaveLexDeskFirewallLastChange(
                new LexDeskFirewallLastChangeInfo
                {
                    ActionType = "AllowProgram",
                    RuleName = item.RuleName,
                    ProgramPath = item.ProgramPath,
                    ProgramName = item.Name,
                    SavedUtc = DateTime.UtcNow.ToString("O")
                });

            UpdateSecurityStatus(
                $"Normal internet access restored for {item.Name}",
                false);

            ShowLexDeskMessageBox(
                $"LexDesk removed its firewall block for {item.Name}.\n\n" +
                "If another firewall rule also applies to the program, Windows may still restrict its network access.",
                "Internet Access Restored",
                MessageBoxButton.OK,
                MessageBoxImage.Information);

            return true;
        }


