        private async void LexDeskFirewallProgramBlockSelected_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            LexDeskFirewallProgramListItem? selected =
                LexDeskFirewallProgramList2.SelectedItem as
                    LexDeskFirewallProgramListItem;

            if (selected == null ||
                selected.IsBlockedByLexDesk ||
                selected.IsBlockedByOtherRule)
            {
                return;
            }

            LexDeskFirewallProgramBlockButton2.IsEnabled = false;
            LexDeskFirewallProgramAllowButton2.IsEnabled = false;

            try
            {
                bool changed =
                    await ApplyLexDeskFirewallProgramBlockAsync(
                        selected.ProgramPath,
                        selected.Name);

                if (changed)
                    await RefreshLexDeskFirewallProgramManagerAsync();
            }
            finally
            {
                UpdateLexDeskFirewallProgramSelection();
            }
        }


