        private async void LexDeskFirewallProgramChooseOther_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            var picker =
                new OpenFileDialog
                {
                    Title = "Choose a program",
                    Filter = "Windows programs (*.exe)|*.exe",
                    CheckFileExists = true,
                    CheckPathExists = true,
                    Multiselect = false
                };

            bool? picked =
                picker.ShowDialog(this);

            if (picked != true)
                return;

            string path =
                NormalizeLexDeskFirewallProgramPath(
                    picker.FileName ?? "");

            string name =
                Path.GetFileNameWithoutExtension(path);

            bool changed =
                await ApplyLexDeskFirewallProgramBlockAsync(
                    path,
                    name);

            if (changed)
                await RefreshLexDeskFirewallProgramManagerAsync();
        }


