        private async void LexDeskFirewallUndo_Click(
            object sender,
            RoutedEventArgs e)
        {
            e.Handled = true;

            Button? button =
                sender as Button;

            if (button != null)
                button.IsEnabled = false;

            try
            {
                if (!TryLoadLexDeskFirewallLastChange(
                        out LexDeskFirewallLastChangeInfo change))
                {
                    ShowLexDeskMessageBox(
                        "There is no recent LexDesk program internet-access change to undo.",
                        "Undo Firewall Change",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);

                    return;
                }

                string actionType =
                    (change.ActionType ?? "").Trim();

                string programPath =
                    NormalizeLexDeskFirewallProgramPath(
                        change.ProgramPath ?? "");

                string programName =
                    string.IsNullOrWhiteSpace(change.ProgramName)
                        ? (!string.IsNullOrWhiteSpace(programPath)
                            ? Path.GetFileNameWithoutExtension(programPath)
                            : "the selected program")
                        : change.ProgramName.Trim();

                string ruleName =
                    (change.RuleName ?? "").Trim();

                // The undo file is local data, but still validate it before using
                // it for an elevated firewall operation. Only exact LexDesk-owned
                // deterministic rule names are accepted.
                bool validLexDeskRule =
                    !string.IsNullOrWhiteSpace(programPath) &&
                    !string.IsNullOrWhiteSpace(ruleName) &&
                    ruleName.StartsWith(
                        "LexDesk Block Internet - ",
                        StringComparison.Ordinal) &&
                    string.Equals(
                        ruleName,
                        GetLexDeskFirewallProgramRuleName(programPath),
                        StringComparison.OrdinalIgnoreCase);

                if (!validLexDeskRule)
                {
                    DeleteLexDeskFirewallLastChange();

                    ShowLexDeskMessageBox(
                        "LexDesk found an invalid or incomplete undo record.\n\nNothing in Windows Firewall was changed. The unusable undo record was cleared.",
                        "Undo Firewall Change",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);

                    return;
                }

                // ----------------------------------------------------
                // UNDO BLOCK PROGRAM
                // Last action blocked the program, so remove only the
                // exact outbound rule that LexDesk created.
                // ----------------------------------------------------
                if (string.Equals(
                        actionType,
                        "BlockProgram",
                        StringComparison.OrdinalIgnoreCase))
                {
                    MessageBoxResult decision =
                        ShowLexDeskMessageBox(
                            $"Undo the last firewall change?\n\n" +
                            $"LexDesk will allow {programName} to access the internet again by removing only this LexDesk-created outbound rule.\n\n" +
                            "Other Windows or third-party firewall rules will not be changed.\n\n" +
                            "Windows may ask for Administrator permission. Continue?",
                            "Undo Program Block",
                            MessageBoxButton.YesNo,
                            MessageBoxImage.Information);

                    if (decision != MessageBoxResult.Yes)
                        return;

                    (bool started, bool cancelled, int exitCode) =
                        await RunLexDeskElevatedNetshAsync(
                            "advfirewall",
                            "firewall",
                            "delete",
                            "rule",
                            $"name={ruleName}");

                    if (cancelled)
                    {
                        ShowLexDeskMessageBox(
                            "Administrator permission was cancelled. The program block was left unchanged.",
                            "Undo Firewall Change",
                            MessageBoxButton.OK,
                            MessageBoxImage.Information);

                        return;
                    }

                    if (!started ||
                        exitCode != 0)
                    {
                        ShowLexDeskMessageBox(
                            "Windows Firewall did not confirm removal of the LexDesk program block.\n\nNothing else was changed.",
                            "Undo Firewall Change",
                            MessageBoxButton.OK,
                            MessageBoxImage.Warning);

                        return;
                    }

                    List<LexDeskFirewallBlockedProgramInfo> existing =
                        LoadLexDeskFirewallBlockedPrograms();

                    existing.RemoveAll(record =>
                        string.Equals(
                            record.RuleName,
                            ruleName,
                            StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(
                            NormalizeLexDeskFirewallProgramPath(record.ProgramPath),
                            programPath,
                            StringComparison.OrdinalIgnoreCase));

                    bool trackingSaved =
                        SaveLexDeskFirewallBlockedPrograms(existing);

                    DeleteLexDeskFirewallLastChange();

                    UpdateSecurityStatus(
                        $"Last firewall change undone for {programName}",
                        false);

                    ShowLexDeskMessageBox(
                        trackingSaved
                            ? $"The last LexDesk firewall change was undone.\n\n{programName} can make outgoing internet connections again unless another firewall rule also blocks it."
                            : $"The Windows Firewall change was undone and {programName} can make outgoing connections again.\n\nLexDesk could not update its local blocked-program list, so refresh Program Internet Access before making another change.",
                        "Firewall Change Undone",
                        MessageBoxButton.OK,
                        trackingSaved
                            ? MessageBoxImage.Information
                            : MessageBoxImage.Warning);

                    return;
                }

                // ----------------------------------------------------
                // UNDO ALLOW PROGRAM
                // Last action removed a LexDesk block, so recreate that
                // same exact outbound rule and restore local tracking.
                // ----------------------------------------------------
                if (string.Equals(
                        actionType,
                        "AllowProgram",
                        StringComparison.OrdinalIgnoreCase))
                {
                    if (!IsLexDeskFirewallProgramBlockTargetAllowed(
                            programPath,
                            out string reason))
                    {
                        ShowLexDeskMessageBox(
                            "LexDesk cannot restore the previous program block.\n\n" +
                            reason +
                            "\n\nNothing in Windows Firewall was changed.",
                            "Undo Firewall Change",
                            MessageBoxButton.OK,
                            MessageBoxImage.Warning);

                        return;
                    }

                    List<LexDeskFirewallBlockedProgramInfo> existing =
                        LoadLexDeskFirewallBlockedPrograms();

                    bool alreadyTracked =
                        existing.Any(record =>
                            string.Equals(
                                record.RuleName,
                                ruleName,
                                StringComparison.OrdinalIgnoreCase) ||
                            string.Equals(
                                NormalizeLexDeskFirewallProgramPath(record.ProgramPath),
                                programPath,
                                StringComparison.OrdinalIgnoreCase));

                    if (alreadyTracked)
                    {
                        DeleteLexDeskFirewallLastChange();

                        ShowLexDeskMessageBox(
                            $"{programName} is already recorded as blocked by LexDesk.\n\nThe undo record has been cleared because there is nothing else to restore.",
                            "Undo Firewall Change",
                            MessageBoxButton.OK,
                            MessageBoxImage.Information);

                        return;
                    }

                    MessageBoxResult decision =
                        ShowLexDeskMessageBox(
                            $"Undo the last firewall change?\n\n" +
                            $"LexDesk will restore the outbound internet block for {programName}.\n\n" +
                            "Only the same LexDesk-owned rule will be recreated. Other firewall rules will not be changed.\n\n" +
                            "Windows may ask for Administrator permission. Continue?",
                            "Undo Allow Internet Access",
                            MessageBoxButton.YesNo,
                            MessageBoxImage.Information);

                    if (decision != MessageBoxResult.Yes)
                        return;

                    (bool started, bool cancelled, int exitCode) =
                        await RunLexDeskElevatedNetshAsync(
                            "advfirewall",
                            "firewall",
                            "add",
                            "rule",
                            $"name={ruleName}",
                            "dir=out",
                            "action=block",
                            $"program={programPath}",
                            "enable=yes",
                            "profile=any");

                    if (cancelled)
                    {
                        ShowLexDeskMessageBox(
                            "Administrator permission was cancelled. Internet access was left unchanged.",
                            "Undo Firewall Change",
                            MessageBoxButton.OK,
                            MessageBoxImage.Information);

                        return;
                    }

                    if (!started ||
                        exitCode != 0)
                    {
                        ShowLexDeskMessageBox(
                            "Windows Firewall did not confirm restoration of the LexDesk program block.\n\nNothing was added to LexDesk's blocked-program list.",
                            "Undo Firewall Change",
                            MessageBoxButton.OK,
                            MessageBoxImage.Warning);

                        return;
                    }

                    existing.Add(
                        new LexDeskFirewallBlockedProgramInfo
                        {
                            RuleName = ruleName,
                            ProgramPath = programPath,
                            ProgramName = programName,
                            CreatedUtc = DateTime.UtcNow.ToString("O")
                        });

                    bool trackingSaved =
                        SaveLexDeskFirewallBlockedPrograms(existing);

                    DeleteLexDeskFirewallLastChange();

                    UpdateSecurityStatus(
                        $"Last firewall change undone for {programName}",
                        false);

                    ShowLexDeskMessageBox(
                        trackingSaved
                            ? $"The last LexDesk firewall change was undone.\n\nThe internet block for {programName} has been restored."
                            : $"The Windows Firewall block for {programName} was restored, but LexDesk could not update its local blocked-program list.\n\nUse Program Internet Access → Refresh before making another change.",
                        "Firewall Change Undone",
                        MessageBoxButton.OK,
                        trackingSaved
                            ? MessageBoxImage.Information
                            : MessageBoxImage.Warning);

                    return;
                }

                DeleteLexDeskFirewallLastChange();

                ShowLexDeskMessageBox(
                    "The saved firewall change is not one LexDesk can safely undo automatically.\n\nNothing in Windows Firewall was changed, and the unusable undo record was cleared.",
                    "Undo Firewall Change",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
            catch
            {
                ShowLexDeskMessageBox(
                    "LexDesk could not complete the undo operation.\n\nThe current Windows Firewall configuration was left as-is wherever possible.",
                    "Undo Firewall Change",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                UpdateLexDeskFirewallUndoButton();

                if (button != null &&
                    TryLoadLexDeskFirewallLastChange(
                        out _))
                {
                    button.IsEnabled = true;
                }
            }
        }


