                activeWeb.CoreWebView2.Reload();
            }
            catch { }
        }

        private void NavigateToNewTab()
        {
            _pageUrls[_activePageIndex] = "lexwhite://newtab";

            if (AddressBox != null)
            {
                AddressBox.Text = "lexwhite://newtab";
                NormalizeAddressBoxView();
            }

            _ = NavigatePaneWhenReadyAsync(_activePageIndex, "about:blank");
        }

        private void NavigateTo(string inputRaw)
        {
            CloseSettingsOverlayForNavigation();

            if (GuardLocked()) return;
            if (string.IsNullOrWhiteSpace(inputRaw)) return;

            if (IsDangerousUriScheme(inputRaw, out string dangerousReason))
            {
                UpdateSecurityStatus("Dangerous link blocked", true);

                ShowProtectionPopup(
                    "LexDesk Pro - Link Shield",
                    "Dangerous link blocked",
                    $"{dangerousReason}\n\n" +
                    $"Address:\n{inputRaw}\n\n" +
                    "This type of link can be abused by scam pages, browser hijackers, or malicious scripts.",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);

                return;
            }

            string input = inputRaw.Trim();

            if (IsDangerousNavigation(input, out string blockedReason))
            {
                UpdateSecurityStatus("Unsafe navigation blocked", true);

                ShowProtectionPopup(
    "LexDesk Pro - Site Shield",
    "Unsafe website action blocked",
    $"Reason: {blockedReason}\n\n" +
    $"Address:\n{inputRaw}\n\n" +
    "This type of link can be used by scam pages, browser hijackers, or malicious scripts.",
    MessageBoxButton.OK,
    MessageBoxImage.Warning);

                return;
            }

            if (input.Equals("lexwhite://newtab", StringComparison.OrdinalIgnoreCase))
            {
                NavigateToNewTab();
                _pageUrls[_activePageIndex] = "lexwhite://newtab";
                RefreshCompatibilityUiForCurrentSite();
                return;
            }

            _lastUserInput = inputRaw.Trim();
            _lastNavigationWasSearch = false;

            Uri? uri;

            if (input.Contains("://"))
            {
                if (!Uri.TryCreate(input, UriKind.Absolute, out uri))
                {
                    uri = BuildSearchUri(inputRaw);
                    _lastNavigationWasSearch = true;
                }
            }
            else
            {
                if (LooksLikeDomain(input))
                {
                    uri = new Uri("https://" + input);
                }
                else if (TryBuildKnownSiteShortcut(input, out uri))
                {
                    _lastNavigationWasSearch = false;
                }
                else
                {
                    uri = BuildSearchUri(inputRaw);
                    _lastNavigationWasSearch = true;
                }
            }

            uri ??= BuildSearchUri(inputRaw);

            string destinationHost = NormalizeManualBlockedSite(uri.ToString());

            if (IsManualBlockedSite(destinationHost, out string blockedHost))
            {
                UpdateSecurityStatus("Website blocked", true);

                ShowProtectionPopup(
                    "LexDesk Pro - Blocked Site List",
                    "Website blocked",
                    $"LexDesk Pro blocked this website.\n\n" +
                    $"This site is on your Blocked Site List.\n\n" +
                    $"Website:\n{blockedHost}",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);

                return;
            }

            try
            {
                int targetPane = _activePageIndex;
                string targetUrl = uri.ToString();

                // Speed Recovery:
                // Initialize the active WebView only when it is actually needed.
                _ = NavigatePaneWhenReadyAsync(targetPane, targetUrl);
            }
            catch
            {
                // Silent by design. Navigation should never crash the app.
            }

            _pageUrls[_activePageIndex] = uri.ToString();

            if (AddressBox != null)
            {
                AddressBox.Text = _lastNavigationWasSearch ? _lastUserInput : FormatUrlForDisplay(uri.ToString());
                NormalizeAddressBoxView();
            }

            RefreshCompatibilityUiForCurrentSite();
        }

        private void ResetActivePaneStatus()
        {
            _blockedTrackerCounts[_activePageIndex] = 0;
            _blockedAdCounts[_activePageIndex] = 0;
            _statusMessages[_activePageIndex] = "Secure";
            _statusWarnings[_activePageIndex] = false;
            _compatibilityModeActive[_activePageIndex] = false;
            _compatibilityModeLabels[_activePageIndex] = "";
            UpdateSecurityStatus("Secure", false);
            RefreshCompatibilityButtonVisual();
        }

        private void RefreshActivePaneStatusVisual()
        {
            if (StatusIndicator == null || StatusIndicatorHost == null)
                return;

            var trackersBlocked = _blockedTrackerCounts[_activePageIndex];
            var adsBlocked = _blockedAdCounts[_activePageIndex];
            var message = string.IsNullOrWhiteSpace(_statusMessages[_activePageIndex])
                ? "Secure"
                : _statusMessages[_activePageIndex];
            var warning = _statusWarnings[_activePageIndex];
            var compatibility = _compatibilityModeActive[_activePageIndex];

            var currentUrl = GetActivePaneRealUrl();
            bool isHttps = false;

            if (!string.IsNullOrWhiteSpace(currentUrl) &&
                Uri.TryCreate(currentUrl, UriKind.Absolute, out var uri))
            {
                isHttps = uri.Scheme.Equals("https", StringComparison.OrdinalIgnoreCase);
            }

            string summary;
            string dotColor;
            string reasonText;

            string shieldText =
                "LexDesk Pro Shield Active\n" +
                "✓ Download Guard\n" +
                "✓ Site Shield\n" +
                "✓ Permission Shield\n" +
                "✓ Scam Shield\n" +
                "✓ Trust Lists\n" +
                "✓ Popup protection\n" +
                "✓ Tracker / ad blocking\n" +
                "✓ DNS protection";

            if (warning)
            {
                summary = "Warning";
                dotColor = "#FFFF5A5A";
                reasonText = "Warning: this page may not be safe";
            }
            else if (!_isLatestUpdate)
            {
                summary = "Update Available";
                dotColor = "#FF4696FF";
                reasonText = "An app update is available";
            }
            else if (!isHttps)
            {
                summary = "Not Secure";
                dotColor = "#FFFFB347";
                reasonText = "This page is not using a secure connection";
            }
            else if (trackersBlocked >= 6 || adsBlocked >= 2)
            {
                summary = "Protected";
                dotColor = "#FFFFB347";
                reasonText = "Protected: higher tracker/ad activity was blocked";
            }
            else if (trackersBlocked > 0 || adsBlocked > 0)
            {
                summary = "Safe";
                dotColor = "#FF57D657";
                reasonText = "Safe: normal protection is working";
            }
            else
            {
                summary = "Safe";
                dotColor = "#FF57D657";
                reasonText = "Secure connection";
            }

            var brush = new SolidColorBrush((Color)ColorConverter.ConvertFromString(dotColor));
            StatusIndicator.Fill = brush;

            if (StatusIndicator.Effect is DropShadowEffect glow)
                glow.Color = brush.Color;

            var host = GetHost(currentUrl);
            if (string.IsNullOrWhiteSpace(host))
                host = "Current page";

            StatusIndicatorHost.ToolTip =
                $"Status: {summary}\n" +
                $"Connection: {message}\n" +
                $"Trackers blocked: {trackersBlocked}\n" +
                $"Ads blocked: {adsBlocked}\n" +
                $"Privacy: {GetPrivacyModeLabel()}\n" +
                $"Page: {host}\n" +
                $"Update: {(_isLatestUpdate ? "Up to date" : "Available")}";

            if (StatusPopupSummaryText != null)
            {
                StatusPopupSummaryText.Text = warning
                    ? "Warning detected on this page"
                    : !_isLatestUpdate
                        ? "A newer version of LexDesk Pro is available"
                        : summary == "Protected"
                            ? "Protection is active"
                            : summary == "Not Secure"
                                ? "Browsing is not secure"
                                : "Browsing is protected";
            }


            if (StatusPopupStateText != null)
                StatusPopupStateText.Text = summary;

            if (StatusPopupConnectionText != null)
                StatusPopupConnectionText.Text = message;

            if (StatusPopupReasonText != null)
                StatusPopupReasonText.Text = reasonText + "\n\n" + shieldText;

            if (StatusPopupTrackersText != null)
                StatusPopupTrackersText.Text = trackersBlocked.ToString();

            if (StatusPopupAdsText != null)
                StatusPopupAdsText.Text = adsBlocked.ToString();

            if (StatusPopupPrivacyText != null)
                StatusPopupPrivacyText.Text = GetPrivacyModeLabel();

            if (StatusPopupPageText != null)
                StatusPopupPageText.Text = host;

            if (StatusPopupCompatibilityText != null)
            {
                if (compatibility)
                {
                    var label = string.IsNullOrWhiteSpace(_compatibilityModeLabels[_activePageIndex])
                        ? "On"
                        : $"On ({_compatibilityModeLabels[_activePageIndex]})";

                    StatusPopupCompatibilityText.Text = label;
                    StatusPopupCompatibilityText.Visibility = Visibility.Visible;
                }
                else
                {
                    StatusPopupCompatibilityText.Text = "Off";
                    StatusPopupCompatibilityText.Visibility = Visibility.Visible;
                }
            }

            if (StatusPopupUpdateText != null)
                StatusPopupUpdateText.Text = _isLatestUpdate ? "Up to date" : "Available";
        }

        private void HookAddressUpdates(WebView2 web)
        {
            if (web?.CoreWebView2 == null) return;

            web.CoreWebView2.NavigationCompleted += (_, __) =>
            {
                Dispatcher.Invoke(() =>
                {
                    if (_suppressAddressUpdates) return;

                    var src = web.CoreWebView2.Source;
                    if (string.IsNullOrWhiteSpace(src)) return;

                    // While launching from the Startup Screen, ignore temporary blank WebView2 updates.
                    // Otherwise about:blank can overwrite _pageUrls[0] and make the Startup Screen flash back.
                    if (_startupOverlayLaunchInProgress && ReferenceEquals(web, Web))
                    {
                        if (src.Equals("about:blank", StringComparison.OrdinalIgnoreCase) ||
                            src.Equals("lexwhite://newtab", StringComparison.OrdinalIgnoreCase))
                        {
                            return;
                        }

                        _startupOverlayLaunchInProgress = false;
                    }

                    // Keep web page URL state updated
                    if (ReferenceEquals(web, Web)) _pageUrls[0] = src;
                    else if (ReferenceEquals(web, Web2)) _pageUrls[1] = src;
                    else if (ReferenceEquals(web, Web3)) _pageUrls[2] = src;
                    else if (ReferenceEquals(web, Web4)) _pageUrls[3] = src;

                    if (AddressBox != null)
                    {
                        if (_lastNavigationWasSearch && !string.IsNullOrWhiteSpace(_lastUserInput))
                            SetAddressBoxTextSafe(_lastUserInput);
                        else
                            SetAddressBoxTextSafe(FormatUrlForAddressBar(src));
                    }

                    RefreshHomeOverlay1();
                });
            };
        }

        // ============================================
        // Address Bar - Right Click Quick Actions
        // ============================================

        private void AddressBox_PreviewMouseRightButtonDown(object sender, MouseButtonEventArgs e)
        {
            // Rebuild the menu immediately before every right-click so the
            // current site, Allow List state and Quick URL labels are always fresh.
            BuildAddressBarContextMenu();
        }

        private void BuildAddressBarContextMenu()
        {
            try
            {
                if (AddressBox == null)
                    return;

                var menu = new ContextMenu();
                ApplyWebPrivacyContextMenuTheme(menu);

                var cutItem = new MenuItem
                {
                    Header = "Cut",
                    Command = ApplicationCommands.Cut,
                    CommandTarget = AddressBox
                };

                var copyItem = new MenuItem
                {
                    Header = "Copy",
                    Command = ApplicationCommands.Copy,
                    CommandTarget = AddressBox
                };

                var pasteItem = new MenuItem
                {
                    Header = "Paste",
                    Command = ApplicationCommands.Paste,
                    CommandTarget = AddressBox
                };

                var selectAllItem = new MenuItem
                {
                    Header = "Select All",
                    Command = ApplicationCommands.SelectAll,
                    CommandTarget = AddressBox
                };

                menu.Items.Add(cutItem);
                menu.Items.Add(copyItem);
                menu.Items.Add(pasteItem);
                menu.Items.Add(selectAllItem);
                menu.Items.Add(new Separator());

                // ------------------------------------------------------------
                // Current-site permissions
                // ------------------------------------------------------------
                string currentUrl = GetSafeCurrentPageUrlForUserAction();
                string currentHost = GetHostFromUrl(currentUrl);
                bool hasCurrentSite = !string.IsNullOrWhiteSpace(currentHost);

                string allowListMatch = FindMatchingHostEntry(_adBlockWhitelist, currentHost);
                string popupListMatch = FindMatchingHostEntry(_popupWhitelist, currentHost);

                var sitePermissionsMenu = new MenuItem
                {
                    Header = "Site permissions"
                };

                var allowSiteItem = new MenuItem
                {
                    Header = string.IsNullOrWhiteSpace(allowListMatch)
                        ? "Allow this site (lighter protection)"
                        : "Remove this site from Allow List",
                    IsEnabled = hasCurrentSite
                };
                allowSiteItem.Click += (_, __) =>
                {
                    ToggleCurrentSiteAllowListFromAddressBar();
                };
                sitePermissionsMenu.Items.Add(allowSiteItem);

                var allowPopupsItem = new MenuItem
                {
                    Header = string.IsNullOrWhiteSpace(popupListMatch)
                        ? "Allow popups from this site"
                        : "Remove this site from Popup Allow List",
                    IsEnabled = hasCurrentSite && HasFullUnlock()
                };
                allowPopupsItem.Click += (_, __) =>
                {
                    ToggleCurrentSitePopupAllowListFromAddressBar();
                };
                sitePermissionsMenu.Items.Add(allowPopupsItem);

                var smartCompatibilityItem = new MenuItem
                {
                    Header = "Smart Compatibility for this site",
                    IsEnabled = hasCurrentSite
                };
                smartCompatibilityItem.Click += (_, __) =>
                {
                    CompatibilityForSite_Click(AddressBox, new RoutedEventArgs());
                };
                sitePermissionsMenu.Items.Add(smartCompatibilityItem);

                var detailedPermissionsItem = new MenuItem
                {
                    Header = "Camera / microphone / location permissions...",
                    IsEnabled = hasCurrentSite
                };
                detailedPermissionsItem.Click += (_, __) => ShowSitePermissionsWindow();
                sitePermissionsMenu.Items.Add(detailedPermissionsItem);

                menu.Items.Add(sitePermissionsMenu);
                menu.Items.Add(new Separator());

                // ------------------------------------------------------------
                // Favourites
                // ------------------------------------------------------------
                var addFavouriteItem = new MenuItem
                {
                    Header = "Add this page to Favourites",
                    IsEnabled = !string.IsNullOrWhiteSpace(currentUrl)
                };

                addFavouriteItem.Click += (_, __) =>
                {
                    WebAction_Bookmark_Click(
                        AddressBox,
                        new RoutedEventArgs());
                };

                menu.Items.Add(addFavouriteItem);
                menu.Items.Add(new Separator());

                // ------------------------------------------------------------
                // Quick URLs
                // ------------------------------------------------------------
                var saveQuickUrlItem = new MenuItem
                {
                    Header = "Save this page to next Quick URL",
                    IsEnabled = !string.IsNullOrWhiteSpace(currentUrl)
                };
                saveQuickUrlItem.Click += (_, __) =>
                {
                    SaveCurrentPageToNextAvailableQuickUrl();
                };
                menu.Items.Add(saveQuickUrlItem);

                var saveToSpecificQuickUrlMenu = new MenuItem
                {
                    Header = "Save this page to Quick URL...",
                    IsEnabled = !string.IsNullOrWhiteSpace(currentUrl)
                };

                for (int workspace = 0; workspace < 5; workspace++)
                {
                    var workspaceMenu = new MenuItem
                    {
                        Header = $"Workspace {workspace + 1}  (Quick URLs {workspace * 4 + 1}-{workspace * 4 + 4})"
                    };

                    for (int page = 0; page < 4; page++)
                    {
                        int slot = workspace * 4 + page;
                        int capturedSlot = slot;
                        string existing = slot >= 0 && slot < _presetUrls.Length
                            ? (_presetUrls[slot] ?? "").Trim()
                            : "";

                        string label = string.IsNullOrWhiteSpace(existing)
                            ? $"Quick URL {slot + 1} - empty"
                            : $"Quick URL {slot + 1} - {GetQuickUrlMenuLabel(slot)}";

                        var slotItem = new MenuItem
                        {
                            Header = label,
                            IsEnabled = HasFullUnlock() || slot < 6
                        };
                        slotItem.Click += (_, __) => SaveCurrentPageToQuickUrlSlot(capturedSlot);
                        workspaceMenu.Items.Add(slotItem);
                    }

                    saveToSpecificQuickUrlMenu.Items.Add(workspaceMenu);
                }

                menu.Items.Add(saveToSpecificQuickUrlMenu);
                menu.Items.Add(new Separator());

                var copyCurrentLinkItem = new MenuItem
                {
                    Header = "Copy current page link"
                };
                copyCurrentLinkItem.Click += (_, __) =>
                {
                    string url = GetSafeCurrentPageUrlForUserAction();

                    if (!string.IsNullOrWhiteSpace(url))
                    {
                        Clipboard.SetText(url);
                        UpdateSecurityStatus("Link copied", false);
                    }
                };
                menu.Items.Add(copyCurrentLinkItem);

                var copyTitleLinkItem = new MenuItem
                {
                    Header = "Copy title + link"
                };
                copyTitleLinkItem.Click += (_, __) =>
                {
                    ShareCopyTitleLink_Click(AddressBox, new RoutedEventArgs());
                };
                menu.Items.Add(copyTitleLinkItem);

                var shareEmailItem = new MenuItem
                {
                    Header = "Share by Email"
                };
                shareEmailItem.Click += (_, __) =>
                {
                    ShareEmail_Click(AddressBox, new RoutedEventArgs());
                };
                menu.Items.Add(shareEmailItem);

                var shareMenuItem = new MenuItem
                {
                    Header = "Share this page..."
                };
                shareMenuItem.Click += (_, __) =>
                {
                    ShareCurrentPageMenu();
                };
                menu.Items.Add(shareMenuItem);

                menu.Items.Add(new Separator());

                var clearSiteCookiesItem = new MenuItem
                {
                    Header = "Clear data for this site"
                };
                clearSiteCookiesItem.Click += (_, __) =>
                {
                    ClearCurrentSiteCookies_Click(AddressBox, new RoutedEventArgs());
                };
                menu.Items.Add(clearSiteCookiesItem);

                var clearAllCookiesItem = new MenuItem
                {
                    Header = "Clear all cookies"
                };
                clearAllCookiesItem.Click += (_, __) =>
                {
                    ClearAllCookies_Click(AddressBox, new RoutedEventArgs());
                };
                menu.Items.Add(clearAllCookiesItem);

                AddressBox.ContextMenu = menu;
            }
            catch
            {
                // Address-bar menu must never affect browsing.
            }
        }

        private static string FindMatchingHostEntry(HashSet<string> entries, string host)
        {
            if (entries == null || string.IsNullOrWhiteSpace(host))
                return "";

            host = host.Trim().Trim('.');

            if (entries.Contains(host))
                return host;

            var parts = host.Split('.');
            for (int i = 1; i < parts.Length - 1; i++)
            {
                string suffix = string.Join(".", parts.Skip(i));
                if (entries.Contains(suffix))
                    return suffix;
            }

            return "";
        }

        private void ToggleCurrentSiteAllowListFromAddressBar()
        {
            try
            {
                string url = GetSafeCurrentPageUrlForUserAction();
                string host = GetHostFromUrl(url);

                if (string.IsNullOrWhiteSpace(host))
                {
                    ShowLexDeskMessageBox(
                        "No active site was detected.",
                        "Allow List",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                    return;
                }

                string existingEntry = FindMatchingHostEntry(_adBlockWhitelist, host);

                if (!string.IsNullOrWhiteSpace(existingEntry))
                {
                    _adBlockWhitelist.Remove(existingEntry);
                    SaveWhitelist();
                    UpdateSecurityStatus($"{existingEntry} removed from Allow List", false);

                    ShowLexDeskMessageBox(
                        $"{existingEntry} removed from the Allow List.\n\nNormal protection will be used again.",
                        "Allow List",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                }
                else
                {
                    _adBlockWhitelist.Add(host);
                    SaveWhitelist();
                    UpdateSecurityStatus($"{host} added to Allow List", false);

                    ShowLexDeskMessageBox(
                        $"{host} added to the Allow List.\n\nLighter protection will be used here to help the site work properly.",
                        "Allow List",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                }

                if (WhitelistEditor != null)
                    WhitelistEditor.Text = string.Join(Environment.NewLine, _adBlockWhitelist.OrderBy(x => x));

                GetActiveWebView()?.CoreWebView2?.Reload();
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    $"Could not update the Allow List:\n{SanitizeExceptionMessage(ex)}",
                    "Allow List",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
        }

        private void ToggleCurrentSitePopupAllowListFromAddressBar()
        {
            if (!HasFullUnlock())
            {
                ShowLexDeskMessageBox(
                    "Popup controls require activation.",
                    "Activation Required",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            try
            {
                string url = GetSafeCurrentPageUrlForUserAction();
                string host = GetHostFromUrl(url);

                if (string.IsNullOrWhiteSpace(host))
                {
                    ShowLexDeskMessageBox(
                        "No active site was detected.",
                        "Popup Allow List",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                    return;
                }

                string existingEntry = FindMatchingHostEntry(_popupWhitelist, host);

                if (!string.IsNullOrWhiteSpace(existingEntry))
                {
                    _popupWhitelist.Remove(existingEntry);
                    SavePopupWhitelist();
                    UpdateSecurityStatus($"Popup permission removed for {existingEntry}", false);

                    ShowLexDeskMessageBox(
                        $"{existingEntry} removed from the Popup Allow List.",
                        "Popup Allow List",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                }
                else
                {
                    _popupWhitelist.Add(host);
                    SavePopupWhitelist();
                    UpdateSecurityStatus($"Popups allowed for {host}", false);

                    ShowLexDeskMessageBox(
                        $"{host} added to the Popup Allow List.\n\nYou can now try the blocked button or link again.",
                        "Popup Allow List",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                }
            }
            catch (Exception ex)
            {
                ShowLexDeskMessageBox(
                    $"Could not update the Popup Allow List:\n{SanitizeExceptionMessage(ex)}",
                    "Popup Allow List",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
        }

        private void SaveCurrentPageToQuickUrlSlot(int slot)
        {
            if (!CanUseQuickUrlSlot(slot, "Saving"))
                return;

            string url = GetSafeCurrentPageUrlForUserAction();

            if (string.IsNullOrWhiteSpace(url))
            {
                ShowLexDeskMessageBox(
                    "This page cannot be saved as a Quick URL.",
                    "Quick URL",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            string existing = _presetUrls[slot] ?? "";
            if (!string.IsNullOrWhiteSpace(existing) &&
                !string.Equals(existing, url, StringComparison.OrdinalIgnoreCase))
            {
                var overwrite = ShowLexDeskMessageBox(
                    $"Quick URL {slot + 1} already contains:\n\n{existing}\n\nReplace it with the current page?",
                    "Replace Quick URL",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Question);

                if (overwrite != MessageBoxResult.Yes)
                    return;
            }

            _presetUrls[slot] = url;
            SavePresetUrls();
            RefreshPresetButtonsUI();
            SyncQuickUrlSlotToWorkspace(slot);

            UpdateSecurityStatus($"Saved to Quick URL {slot + 1}", false);

            ShowLexDeskMessageBox(
                $"Current page saved to Quick URL {slot + 1}.",
                "Quick URL",
                MessageBoxButton.OK,
                MessageBoxImage.Information);
        }

        private string GetSafeCurrentPageUrlForUserAction()
        {
            string url = (GetActivePaneRealUrl() ?? "").Trim();

            if (string.IsNullOrWhiteSpace(url))
                return "";

            if (url.StartsWith("about:", StringComparison.OrdinalIgnoreCase))
                return "";

            if (url.StartsWith("lexwhite:", StringComparison.OrdinalIgnoreCase))
                return "";

            if (url.StartsWith("file:", StringComparison.OrdinalIgnoreCase))
                return "";

            if (url.StartsWith("javascript:", StringComparison.OrdinalIgnoreCase))
                return "";

            if (url.StartsWith("data:", StringComparison.OrdinalIgnoreCase))
                return "";

            try
            {
                url = NormalizeWorkspaceUrl(url);

                if (!Uri.TryCreate(url, UriKind.Absolute, out var uri))
                    return "";

                if (uri.Scheme != Uri.UriSchemeHttp && uri.Scheme != Uri.UriSchemeHttps)
                    return "";

                return uri.ToString();
            }
            catch
            {
                return "";
            }
        }

        private void SaveCurrentPageToNextAvailableQuickUrl()
        {
            string url = GetSafeCurrentPageUrlForUserAction();

            if (string.IsNullOrWhiteSpace(url))
            {
                ShowLexDeskMessageBox(
                    "This page cannot be saved as a Quick URL.",
                    "Quick URL",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            int slot = Array.FindIndex(_presetUrls, string.IsNullOrWhiteSpace);

            if (slot < 0)
            {
                ShowLexDeskMessageBox(
                    "Quick URL list is full.\n\nOpen Settings and clear a Quick URL first.",
                    "Quick URL",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            _presetUrls[slot] = url;

            SavePresetUrls();
            RefreshPresetButtonsUI();
            SyncQuickUrlSlotToWorkspace(slot);

            UpdateSecurityStatus($"Saved to Quick URL {slot + 1}", false);

            ShowLexDeskMessageBox(
                $"Saved this page to Quick URL {slot + 1}.",
                "Quick URL",
                MessageBoxButton.OK,
                MessageBoxImage.Information);
        }

        // ============================================
        // Cookies / Site Data
        // ============================================

        private async void ClearCurrentSiteCookies_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var wv = GetActiveWebView();

                if (wv?.CoreWebView2 == null)
                {
                    ShowWebPrivacyMessage(
                        "Clear Site Data",
                        "No active page is open.",
                        500,
                        240);

                    return;
                }

                string url = GetSafeCurrentPageUrlForUserAction();

                if (!Uri.TryCreate(url, UriKind.Absolute, out var uri) ||
                    string.IsNullOrWhiteSpace(uri.Host))
                {
                    ShowWebPrivacyMessage(
                        "Clear Site Data",
                        "No normal website is open to clear site data from.",
                        520,
                        250);

                    return;
                }

                string host = uri.Host
                    .Replace(
                        "www.",
                        "",
                        StringComparison.OrdinalIgnoreCase)
                    .Trim();

                bool confirmed = ShowWebPrivacyConfirmation(
                    "Clear Site Data",
                    $"Clear site data for:\n\n{host}\n\n" +
                    "This may sign you out and reset this website's local preferences.",
                    "Clear Data",
                    "Cancel",
                    550,
                    300);

                if (!confirmed)
                    return;

                var cookieManager =
                    wv.CoreWebView2.CookieManager;

                string siteRoot =
                    uri.GetLeftPart(UriPartial.Authority);

                var cookies =
                    await cookieManager.GetCookiesAsync(siteRoot);

                foreach (var cookie in cookies)
                {
                    try
                    {
                        cookieManager.DeleteCookie(cookie);
                    }
                    catch
                    {
                        // Keep clearing the rest.
                    }
                }

                // Clear common browser storage for the current site/page as well.
                // This helps remove cookie-banner saved choices and local session state.
                try
                {
                    await wv.CoreWebView2.ExecuteScriptAsync(@"
(async () => {
    try { localStorage.clear(); } catch { }
    try { sessionStorage.clear(); } catch { }

    try {
        if (window.caches) {
            const keys = await caches.keys();

            for (const key of keys)
                await caches.delete(key);
        }
    } catch { }

    try {
        if (indexedDB && indexedDB.databases) {
            const dbs = await indexedDB.databases();

            for (const db of dbs)
                if (db && db.name)
                    indexedDB.deleteDatabase(db.name);
        }
    } catch { }

    try {
        if (navigator.serviceWorker &&
            navigator.serviceWorker.getRegistrations) {

            const regs =
                await navigator.serviceWorker.getRegistrations();

            for (const reg of regs)
                await reg.unregister();
        }
    } catch { }

    return true;
})();
");
                }
                catch
                {
                    // Some pages may block storage script access.
                    // Cookies may still have been cleared.
                }

                UpdateSecurityStatus(
                    "Site data cleared",
                    false);

                ShowWebPrivacyMessage(
                    "Clear Site Data",
                    $"Site data for {host} has been cleared.\n\n" +
                    "Cookies and local website data were removed. " +
                    "The page will now reload.",
                    550,
                    290);

                try
                {
                    wv.CoreWebView2.Reload();
                }
                catch
                {
                }
            }
            catch (Exception ex)
            {
                ShowWebPrivacyMessage(
                    "Clear Site Data",
                    $"Site data could not be cleared.\n\n" +
                    $"{SanitizeExceptionMessage(ex)}",
                    560,
                    300);
            }
        }

        private void ClearAllCookies_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var wv = GetActiveWebView();

                if (wv?.CoreWebView2 == null)
                {
                    ShowWebPrivacyMessage(
                        "Clear All Cookies",
                        "No browser page is ready yet.",
                        500,
                        240);

                    return;
                }

                bool confirmed = ShowWebPrivacyConfirmation(
                    "Clear All Cookies",
                    "Clear all cookies?\n\n" +
                    "This may sign you out of websites in LexDesk Pro.",
                    "Clear Cookies",
                    "Cancel",
                    520,
                    280);

                if (!confirmed)
                    return;

                wv.CoreWebView2.CookieManager.DeleteAllCookies();

                UpdateSecurityStatus(
                    "All cookies cleared",
                    false);

                ShowWebPrivacyMessage(
                    "Clear All Cookies",
                    "All cookies were cleared.",
                    500,
                    240);
            }
            catch (Exception ex)
            {
                ShowWebPrivacyMessage(
                    "Clear All Cookies",
                    $"Cookies could not be cleared.\n\n" +
                    $"{SanitizeExceptionMessage(ex)}",
                    560,
                    300);
            }
        }

