        private void InitAddressBarTimers()
        {
            _addressEditTimer.Interval = TimeSpan.FromMilliseconds(600);
            _addressEditTimer.Tick += (_, __) =>
            {
                _addressEditTimer.Stop();
                _suppressAddressUpdates = false;
            };
        }

        private void AddressBox_TextChanged(object sender, TextChangedEventArgs e)
        {
            if (_isProgrammaticAddressUpdate)
                return;

            _suppressAddressUpdates = true;
            _addressEditTimer.Stop();
            _addressEditTimer.Start();
        }

        private void AddressBox_LostKeyboardFocus(object sender, KeyboardFocusChangedEventArgs e)
        {
            _suppressAddressUpdates = false;
            _addressEditTimer.Stop();
        }

        private void AddressBox_PreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs e)
        {
            if (sender is TextBox tb && !tb.IsKeyboardFocusWithin)
            {
                e.Handled = true;
                tb.Focus();
                tb.SelectAll();
                tb.ScrollToHome();
                tb.Dispatcher.BeginInvoke(new Action(() =>
                {
                    tb.SelectAll();
                    tb.ScrollToHome();
                }), DispatcherPriority.Input);
            }
        }

        private void AddressBox_GotKeyboardFocus(object sender, KeyboardFocusChangedEventArgs e)
        {
            if (sender is TextBox tb)
            {
                var full = GetActivePaneRealUrl();
                if (!string.IsNullOrWhiteSpace(full))
                    tb.Text = full;

                tb.SelectAll();
                tb.ScrollToHome();
                tb.Dispatcher.BeginInvoke(new Action(() =>
                {
                    tb.SelectAll();
                    tb.ScrollToHome();
                }), DispatcherPriority.Input);
            }
        }

        private void SetAddressBoxTextSafe(string text)
        {
            if (AddressBox == null) return;

            try
            {
                _isProgrammaticAddressUpdate = true;
                _addressEditTimer.Stop();
                _suppressAddressUpdates = false;

                AddressBox.Text = text ?? "";
                NormalizeAddressBoxView();
            }
            finally
            {
                _isProgrammaticAddressUpdate = false;
                _suppressAddressUpdates = false;
            }
        }

        private void RefreshAddressBarFromActivePane()
        {
            if (AddressBox == null) return;
            if (AddressBox.IsKeyboardFocusWithin) return;

            string url = GetActivePaneRealUrl();

            if (string.IsNullOrWhiteSpace(url))
            {
                try
                {
                    url = GetActiveWebView()?.CoreWebView2?.Source ?? "";
                }
                catch { }
            }

            if (string.IsNullOrWhiteSpace(url) ||
                url.Equals("about:blank", StringComparison.OrdinalIgnoreCase) ||
                url.Equals("lexwhite://newtab", StringComparison.OrdinalIgnoreCase))
            {
                SetAddressBoxTextSafe("");
                return;
            }

            SetAddressBoxTextSafe(FormatUrlForDisplay(url));
        }

        private string FormatUrlForAddressBar(string url)
        {
            if (string.IsNullOrWhiteSpace(url))
                return "";

            url = url.Trim();

            if (url.Equals("about:blank", StringComparison.OrdinalIgnoreCase) ||
                url.Equals("lexwhite://newtab", StringComparison.OrdinalIgnoreCase))
                return "";

            try
            {
                var uri = new Uri(url);

                string host = uri.Host.Replace("www.", "");

                if (string.IsNullOrWhiteSpace(host))
                    return url;

                return host + "/";
            }
            catch
            {
                return url;
            }
        }




        private void NormalizeAddressBoxView()
        {
            if (AddressBox == null) return;
            if (AddressBox.IsKeyboardFocusWithin) return;

            AddressBox.CaretIndex = 0;
            AddressBox.Select(0, 0);
            AddressBox.ScrollToHome();

            AddressBox.Dispatcher.BeginInvoke(new Action(() =>
            {
                AddressBox.CaretIndex = 0;
                AddressBox.Select(0, 0);
                AddressBox.ScrollToHome();
            }), DispatcherPriority.Background);
        }

        // ============================================
        // Secure / Not secure badge
        // ============================================

        private void UpdateSecureSiteVisual()
        {
            string? src = null;

            try
            {
                var wv = GetActiveWebView();
                src = wv?.CoreWebView2?.Source;
            }
            catch { }

            // Fallback if WebView2.Source isn't ready yet
            if (string.IsNullOrWhiteSpace(src))
                src = GetActivePaneRealUrl();

            bool isHttps = false;

            if (!string.IsNullOrWhiteSpace(src) &&
                Uri.TryCreate(src, UriKind.Absolute, out var u))
            {
                isHttps = u.Scheme.Equals("https", StringComparison.OrdinalIgnoreCase);
            }

            UpdateSecurityStatus(isHttps ? "Secure" : "Not Secure", !isHttps);
        }

        private void UpdateSecurityStatus(string message, bool warning)
        {
#if DEBUG
            var st = new System.Diagnostics.StackTrace(1, false);
            var caller = st.GetFrame(0)?.GetMethod()?.Name ?? "unknown";
            string safeStatusMessage = SanitizeLogValue(message);
            string safeCaller = SanitizeLogValue(caller);

            System.Diagnostics.Debug.WriteLine(
                $"[STATUS] pane={_activePageIndex} text='{safeStatusMessage}' flag={warning} caller={safeCaller}"
            );
#endif

            _statusMessages[_activePageIndex] = message;
            _statusWarnings[_activePageIndex] = warning;

            RefreshActivePaneStatusVisual();
        }


        // ============================================
        // Quick URLs: load/save + context menus
        // ============================================


        private void LoadPresetUrls()
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_presetUrlsPath)!);

                if (!File.Exists(_presetUrlsPath))
                {
                    // First install default.
                    // Keep only Quick URL 1 pre-filled; customer can change or clear it.
                    for (int i = 0; i < _presetUrls.Length; i++)
                        _presetUrls[i] = "";

                    _presetUrls[0] = "https://google.com/";

                    SavePresetUrls();
                    return;
                }

                var json = File.ReadAllText(_presetUrlsPath);
                var loaded = JsonSerializer.Deserialize<string[]>(json);

                for (int i = 0; i < _presetUrls.Length; i++)
                {
                    if (loaded != null && i < loaded.Length)
                        _presetUrls[i] = loaded[i] ?? "";
                    else
                        _presetUrls[i] = "";
                }

                SavePresetUrls(); // normalize to 20 slots
            }
            catch { }
        }

        private void SavePresetUrls()
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_presetUrlsPath)!);
                var json = JsonSerializer.Serialize(_presetUrls);
                File.WriteAllText(_presetUrlsPath, json);
            }
            catch { }
        }

        private void BuildPresetButtonMenus()
        {
            for (int i = 1; i <= 20; i++)
            {
                var btn = FindName($"PresetBtn{i}") as Button;
                if (btn == null) continue;

                int sourceIndex = i - 1;

                var menu = new ContextMenu
                {
                    PlacementTarget = btn
                };

                ApplyWebPrivacyContextMenuTheme(menu);
                menu.SetResourceReference(Control.BackgroundProperty, "CardBg");
                menu.SetResourceReference(Control.ForegroundProperty, "TextPrimary");
                menu.SetResourceReference(Control.BorderBrushProperty, "CardBorder");
                menu.BorderThickness = new Thickness(1);

                var setItem = new MenuItem { Header = "Set or replace URL..." };
                setItem.Click += PresetSetUrl_Click;

                var moveItem = new MenuItem { Header = "Move to Quick URL..." };

                for (int target = 0; target < 20; target++)
                {
                    int capturedTarget = target;
                    var targetItem = new MenuItem
                    {
                        Header = $"Quick URL {target + 1}",
                        IsEnabled = target != sourceIndex
                    };

                    targetItem.Click += (_, __) =>
                    {
                        if (sourceIndex < 0 || sourceIndex >= _presetUrls.Length)
                            return;

                        if (string.IsNullOrWhiteSpace(_presetUrls[sourceIndex]))
                        {
                            ShowLexDeskMessageBox(
                                $"Quick URL {sourceIndex + 1} is empty.",
                                "Move Quick URL",
                                MessageBoxButton.OK,
                                MessageBoxImage.Information);
                            return;
                        }

                        if (!CanMoveQuickUrlToSlot(
                                sourceIndex,
                                capturedTarget,
                                showActivationMessage: true))
                            return;

                        MoveQuickUrlSlot(sourceIndex, capturedTarget);
                    };

                    moveItem.Items.Add(targetItem);
                }

                var clearItem = new MenuItem { Header = "Clear" };
                clearItem.Click += PresetClear_Click;

                menu.Items.Add(setItem);
                menu.Items.Add(moveItem);
                menu.Items.Add(new Separator());
                menu.Items.Add(clearItem);

                btn.ContextMenu = menu;

                // Browsing shortcuts can also be dragged into a new position.
                // Unhook first so this remains safe if Settings UI is ever rebuilt.
                btn.AllowDrop = true;

                btn.PreviewMouseLeftButtonDown -= PresetButton_PreviewMouseLeftButtonDown;
                btn.PreviewMouseMove -= PresetButton_PreviewMouseMove;
                btn.DragEnter -= PresetButton_DragEnter;
                btn.DragOver -= PresetButton_DragOver;
                btn.DragLeave -= PresetButton_DragLeave;
                btn.Drop -= PresetButton_Drop;

                btn.PreviewMouseLeftButtonDown += PresetButton_PreviewMouseLeftButtonDown;
                btn.PreviewMouseMove += PresetButton_PreviewMouseMove;
                btn.DragEnter += PresetButton_DragEnter;
                btn.DragOver += PresetButton_DragOver;
                btn.DragLeave += PresetButton_DragLeave;
                btn.Drop += PresetButton_Drop;
            }
        }

        private void PresetButton_PreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs e)
        {
            _quickUrlDragSourceIndex = -1;

            if (sender is not Button btn)
                return;

            if (!int.TryParse(btn.Tag?.ToString(), out int idx))
                return;

            if (idx < 0 || idx >= _presetUrls.Length)
                return;

            _quickUrlDragStartPoint = e.GetPosition(this);
            _quickUrlDragSourceIndex = idx;
        }

        private void PresetButton_PreviewMouseMove(object sender, MouseEventArgs e)
        {
            if (e.LeftButton != MouseButtonState.Pressed)
                return;

            if (sender is not Button btn)
                return;

            if (!int.TryParse(btn.Tag?.ToString(), out int idx))
                return;

            if (idx != _quickUrlDragSourceIndex)
                return;

            if (idx < 0 || idx >= _presetUrls.Length)
                return;

            // Empty slots do not need to be dragged.
            if (string.IsNullOrWhiteSpace(_presetUrls[idx]))
                return;

            Point current = e.GetPosition(this);

            bool movedFarEnough =
                Math.Abs(current.X - _quickUrlDragStartPoint.X) >= SystemParameters.MinimumHorizontalDragDistance ||
                Math.Abs(current.Y - _quickUrlDragStartPoint.Y) >= SystemParameters.MinimumVerticalDragDistance;

            if (!movedFarEnough)
                return;

            // Free mode only owns Quick URLs 1-6.
            if (!HasFullUnlock() && idx >= 6)
                return;

            var data = new DataObject();
            data.SetData(QuickUrlDragDataFormat, idx);

            // A WPF Button captures the mouse while it is pressed. That capture can
            // prevent neighbouring buttons from receiving DragOver/Drop reliably.
            // Release it before starting the real drag operation.
            if (Mouse.Captured == btn)
                Mouse.Capture(null);

            // Suppress the normal Click if the gesture was clearly a drag, even if
            // the user later cancels the drop.
            _lastQuickUrlDragCompletedUtc = DateTime.UtcNow;

            try
            {
                DragDrop.DoDragDrop(btn, data, DragDropEffects.Move);
            }
            finally
            {
                _quickUrlDragSourceIndex = -1;
            }
        }

        private bool TryGetQuickUrlDragSource(DragEventArgs e, out int sourceIndex)
        {
            sourceIndex = -1;

            try
            {
                if (!e.Data.GetDataPresent(QuickUrlDragDataFormat))
                    return false;

                object? value = e.Data.GetData(QuickUrlDragDataFormat);

                if (value is int idx)
                {
                    sourceIndex = idx;
                    return idx >= 0 && idx < _presetUrls.Length;
                }
            }
            catch
            {
                // Drag visual feedback must never affect Settings.
            }

            return false;
        }

        private bool CanMoveQuickUrlToSlot(int sourceIndex, int targetIndex, bool showActivationMessage)
        {
            if (sourceIndex < 0 || sourceIndex >= _presetUrls.Length)
                return false;

            if (targetIndex < 0 || targetIndex >= _presetUrls.Length)
                return false;

            if (HasFullUnlock())
                return true;

            bool allowed = sourceIndex < 6 && targetIndex < 6;

            if (!allowed && showActivationMessage)
            {
                ShowLexDeskMessageBox(
                    "Please activate LexDesk Pro to rearrange Quick URLs 7–20.",
                    "Activation Required",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }

            return allowed;
        }

        private void SetQuickUrlDropHighlight(Button? btn, bool highlighted)
        {
            if (btn == null)
                return;

            try
            {
                if (highlighted)
                {
                    btn.BorderBrush = (Brush)(TryFindResource("InputBorder") ?? Brushes.DodgerBlue);
                    btn.BorderThickness = new Thickness(1.6);
                }
                else
                {
                    // Remove only our local drag highlight and fall back to the normal style.
                    btn.ClearValue(Control.BorderBrushProperty);
                    btn.ClearValue(Control.BorderThicknessProperty);
                }
            }
            catch
            {
                // Visual feedback must never block drag-and-drop.
            }
        }

        private void PresetButton_DragEnter(object sender, DragEventArgs e)
        {
            if (sender is not Button btn ||
                !int.TryParse(btn.Tag?.ToString(), out int targetIndex) ||
                !TryGetQuickUrlDragSource(e, out int sourceIndex) ||
                !CanMoveQuickUrlToSlot(sourceIndex, targetIndex, showActivationMessage: false))
            {
                e.Effects = DragDropEffects.None;
                return;
            }

            SetQuickUrlDropHighlight(btn, true);
            e.Effects = DragDropEffects.Move;
            e.Handled = true;
        }

        private void PresetButton_DragOver(object sender, DragEventArgs e)
        {
            if (sender is not Button btn ||
                !int.TryParse(btn.Tag?.ToString(), out int targetIndex) ||
                !TryGetQuickUrlDragSource(e, out int sourceIndex) ||
                !CanMoveQuickUrlToSlot(sourceIndex, targetIndex, showActivationMessage: false))
            {
                e.Effects = DragDropEffects.None;
                return;
            }

            e.Effects = DragDropEffects.Move;
            e.Handled = true;
        }

        private void PresetButton_DragLeave(object sender, DragEventArgs e)
        {
            if (sender is Button btn)
                SetQuickUrlDropHighlight(btn, false);
        }

        private void PresetButton_Drop(object sender, DragEventArgs e)
        {
            if (sender is not Button targetButton)
                return;

            SetQuickUrlDropHighlight(targetButton, false);

            if (!int.TryParse(targetButton.Tag?.ToString(), out int targetIndex))
                return;

            if (!TryGetQuickUrlDragSource(e, out int sourceIndex))
                return;

            if (!CanMoveQuickUrlToSlot(sourceIndex, targetIndex, showActivationMessage: true))
                return;

            // A drag gesture should never also open the shortcut on mouse release.
            _lastQuickUrlDragCompletedUtc = DateTime.UtcNow;

            if (sourceIndex == targetIndex)
            {
                e.Handled = true;
                return;
            }

            MoveQuickUrlSlot(sourceIndex, targetIndex);

            e.Effects = DragDropEffects.Move;
            e.Handled = true;
        }

        private void MoveQuickUrlSlot(int sourceIndex, int targetIndex)
        {
            if (sourceIndex < 0 || sourceIndex >= _presetUrls.Length)
                return;

            if (targetIndex < 0 || targetIndex >= _presetUrls.Length)
                return;

            if (sourceIndex == targetIndex)
                return;

            string movedUrl = _presetUrls[sourceIndex];

            if (string.IsNullOrWhiteSpace(movedUrl))
                return;

            int firstChanged = Math.Min(sourceIndex, targetIndex);
            int lastChanged = Math.Max(sourceIndex, targetIndex);

            if (sourceIndex < targetIndex)
            {
                for (int i = sourceIndex; i < targetIndex; i++)
                    _presetUrls[i] = _presetUrls[i + 1];
            }
            else
            {
                for (int i = sourceIndex; i > targetIndex; i--)
                    _presetUrls[i] = _presetUrls[i - 1];
            }

            _presetUrls[targetIndex] = movedUrl;

            SavePresetUrls();
            RefreshPresetButtonsUI();

            // Keep the fixed 4-URL-per-workspace mapping in sync with the new order.
            // This uses the same safe mapping update already used by Set/Clear.
            for (int slot = firstChanged; slot <= lastChanged; slot++)
                SyncQuickUrlSlotToWorkspace(slot);

            UpdateSecurityStatus(
                $"Quick URL {sourceIndex + 1} moved to {targetIndex + 1}",
                false);
        }

        private void UpdatePresetButtonText(Button btn)
        {
            if (btn == null) return;
            if (!int.TryParse(btn.Tag?.ToString(), out int index)) return;
            if (index < 0 || index >= _presetUrls.Length) return;

            string url = _presetUrls[index];

            if (string.IsNullOrWhiteSpace(url))
            {
                btn.Content = "(empty)";
                return;
            }

            try
            {
                var uri = new Uri(url);
                string host = uri.Host.Replace("www.", "");

                string name = host
                    .Replace(".com.au", "", StringComparison.OrdinalIgnoreCase)
                    .Replace(".com", "", StringComparison.OrdinalIgnoreCase)
                    .Replace(".net", "", StringComparison.OrdinalIgnoreCase)
                    .Replace(".org", "", StringComparison.OrdinalIgnoreCase)
                    .Replace(".co.uk", "", StringComparison.OrdinalIgnoreCase);

                if (!string.IsNullOrWhiteSpace(name))
                    name = char.ToUpper(name[0]) + name.Substring(1);

                btn.Content = string.IsNullOrWhiteSpace(name) ? host : name;
            }
            catch
            {
                btn.Content = url;
            }
        }

        private void PresetButton_Click(object sender, RoutedEventArgs e)
        {
            if ((DateTime.UtcNow - _lastQuickUrlDragCompletedUtc).TotalMilliseconds < 600)
                return;

            if (sender is not Button btn) return;
            if (!int.TryParse(btn.Tag?.ToString(), out int idx)) return;
            if (idx < 0 || idx >= _presetUrls.Length) return;

            if (!HasFullUnlock() && idx >= 6)
            {
                ShowLexDeskMessageBox(
    "Please activate LexDesk Pro to use Quick URLs 7–20.",
    "Activation Required",
    MessageBoxButton.OK,
    MessageBoxImage.Information);
                return;
            }

            var url = _presetUrls[idx];
            if (string.IsNullOrWhiteSpace(url))
            {
                ShowLexDeskMessageBox("No URL set for this button.\n\nRight-click it and choose 'Set URL...'.",
                                "Quick URL",
                                MessageBoxButton.OK,
                                MessageBoxImage.Information);
                return;
            }

            NavigateTo(GetSavedNavigationUrl(url));

            if (SettingsDropdown != null)
                SettingsDropdown.IsOpen = false;
            UpdatePresetButtonText((Button)sender);
        }

        private void PresetSetUrl_Click(object sender, RoutedEventArgs e)
        {
            var btn = GetPresetButtonFromContextMenuSender(sender);
            if (btn == null) return;

            if (!int.TryParse(btn.Tag?.ToString(), out int idx)) return;
            if (idx < 0 || idx >= _presetUrls.Length) return;

            if (!HasFullUnlock() && idx >= 6)
            {
                ShowLexDeskMessageBox(
    "Please activate LexDesk Pro to edit Quick URLs 7–20.",
    "Activation Required",
    MessageBoxButton.OK,
    MessageBoxImage.Information);
                return;
            }

            string defaultUrl = _presetUrls[idx];
            if (string.IsNullOrWhiteSpace(defaultUrl))
                defaultUrl = GetActivePaneRealUrl();

            string url = ShowQuickUrlInputDialog(
    $"Quick URL {idx + 1}",
    defaultUrl ?? "");

            url = (url ?? "").Trim();
            if (string.IsNullOrWhiteSpace(url))
                return;

            if (!url.Contains("://") && url.Contains("."))
                url = "https://" + url;

            _presetUrls[idx] = url;
            SavePresetUrls();
            RefreshPresetButtonsUI();
        }

        private void PresetClear_Click(object sender, RoutedEventArgs e)
        {
            var btn = GetPresetButtonFromContextMenuSender(sender);
            if (btn == null) return;

            if (!int.TryParse(btn.Tag?.ToString(), out int idx)) return;
            if (idx < 0 || idx >= _presetUrls.Length) return;

            if (!HasFullUnlock() && idx >= 6)
            {
                ShowLexDeskMessageBox(
    "Please activate LexDesk Pro to clear Quick URLs 7–20.",
    "Activation Required",
    MessageBoxButton.OK,
    MessageBoxImage.Information);
                return;
            }

            _presetUrls[idx] = "";
            SavePresetUrls();
            RefreshPresetButtonsUI();
        }

        private Button? GetPresetButtonFromContextMenuSender(object sender)
        {
            if (sender is not MenuItem mi) return null;
            if (mi.Parent is not ContextMenu cm) return null;
            return cm.PlacementTarget as Button;
        }

        private void LoadQuickUrlSlotIntoActivePane(int presetIndex)
        {
            if (presetIndex < 0 || presetIndex >= _presetUrls.Length) return;

            // IMPORTANT: do NOT auto-expand web pages here.
            // Web Page expansion is controlled by the Page 1-4 buttons / EnsureWebPagesUpTo().
            int pane = _activePageIndex;

            var paneWebView = GetWebView(pane);
            if (paneWebView != null)
                paneWebView.Visibility = Visibility.Visible;

            // No ApplyLayout() here either — caller decides layout.
            // Only keep visuals in sync:
            UpdatePageModeButtonVisuals();
            UpdatePageHostBorders();
            RefreshCompatibilityUiForCurrentSite();

            if (_pageLocked[_activePageIndex])
            {
                UpdateSecurityStatus("Page Locked", true);
                return;
            }

            var url = _presetUrls[presetIndex];

            if (string.IsNullOrWhiteSpace(url))

            {
                NavigateTo("lexwhite://newtab");
                return;
            }

            _studioSlotIndex[pane] = presetIndex;

            ResetActivePaneStatus();
            ClearWebResourceDecisionCache();
            RefreshActivePaneStatusVisual();

            NavigateTo(GetSavedNavigationUrl(url));

            if (SettingsDropdown != null)
                SettingsDropdown.IsOpen = false;
        }

        private int GetQuickUrlSlotForTabPage(int tabIndex, int paneIndex)
        {
            tabIndex = Math.Clamp(tabIndex, 0, MaxWorkspaceTabs - 1);
            paneIndex = Math.Clamp(paneIndex, 0, 3);

            return (tabIndex * 4) + paneIndex;
        }

        private string GetQuickUrlForTabPage(int tabIndex, int paneIndex)
        {
            int slot = GetQuickUrlSlotForTabPage(tabIndex, paneIndex);

            if (slot < 0 || slot >= _presetUrls.Length)
                return "about:blank";

            string url = NormalizeWorkspaceUrl(_presetUrls[slot]);

            if (string.IsNullOrWhiteSpace(url))
                return "lexwhite://newtab";

            return GetSavedNavigationUrl(url);
        }

        private void LoadQuickUrlForTabPage(int tabIndex, int paneIndex, bool force)
        {
            if (paneIndex < 0 || paneIndex > 3)
                return;

            int slot = GetQuickUrlSlotForTabPage(tabIndex, paneIndex);

            if (slot < 0 || slot >= _presetUrls.Length)
                return;

            if (!force && PaneHasLoadedContent(paneIndex))
                return;

            string targetUrl = GetQuickUrlForTabPage(tabIndex, paneIndex);

            _pageUrls[paneIndex] = targetUrl;
            _studioSlotIndex[paneIndex] = slot;

            ResetActivePaneStatus();
            ClearWebResourceDecisionCache();
            RefreshActivePaneStatusVisual();

            _ = NavigatePaneWhenReadyAsync(paneIndex, targetUrl);
        }

        private void LoadQuickUrlForActiveTabPane(int paneIndex)
        {
            LoadQuickUrlForTabPage(_activeWorkspaceTabIndex, paneIndex, force: true);
        }

        private void RepairLiveQuickUrlSlotsForTab(
    int tabIndex)
        {
            tabIndex = Math.Clamp(
                tabIndex,
                0,
                MaxWorkspaceTabs - 1);

            for (int paneIndex = 0;
                 paneIndex < 4;
                 paneIndex++)
            {
                // A real page belongs to the user.
                // Never replace it merely because the
                // last Quick URL slot differs.
                if (!IsStartupPlaceholderUrl(
                        _pageUrls[paneIndex]))
                {
                    continue;
                }

                int expectedSlot =
                    GetQuickUrlSlotForTabPage(
                        tabIndex,
                        paneIndex);

                _studioSlotIndex[paneIndex] =
                    expectedSlot;

                _pageUrls[paneIndex] =
                    GetQuickUrlForTabPage(
                        tabIndex,
                        paneIndex);
            }
        }

        private void RepairWorkspaceQuickUrlSlots(
    BrowserWorkspace ws,
    int tabIndex)
        {
            if (ws == null)
                return;

            tabIndex = Math.Clamp(
                tabIndex,
                0,
                MaxWorkspaceTabs - 1);

            for (int paneIndex = 0;
                 paneIndex < 4;
                 paneIndex++)
            {
                // Preserve any real page the user has
                // already browsed to in this workspace.
                if (!IsStartupPlaceholderUrl(
                        ws.PageUrls[paneIndex]))
                {
                    continue;
                }

                int expectedSlot =
                    GetQuickUrlSlotForTabPage(
                        tabIndex,
                        paneIndex);

                ws.StudioSlotIndex[paneIndex] =
                    expectedSlot;

                ws.PageUrls[paneIndex] =
                    GetQuickUrlForTabPage(
                        tabIndex,
                        paneIndex);
            }
        }

        private static string GetSiteDisplayName(string url)
        {
            if (Uri.TryCreate(url, UriKind.Absolute, out var u))
            {
                var host = u.Host;
                if (host.StartsWith("www.", StringComparison.OrdinalIgnoreCase))
                    host = host.Substring(4);

                var first = host.Split('.').FirstOrDefault() ?? host;
                if (first.Length == 0) return host;

                return char.ToUpper(first[0]) + first.Substring(1);
            }

            return url;
        }

