        private void PrivacyNotes_Click(object sender, RoutedEventArgs e)
        {
            string message =
                "Privacy Level controls how strongly LexDesk Pro blocks ads and tracking while you browse.\n\n" +

                "Recommended is best for most people. It gives good privacy while keeping most websites working normally.\n\n" +

                "Compatibility uses lighter protection. Try this when a website you trust does not load, sign in, play video, pay, search or work properly.\n\n" +

                "Maximum gives the strongest privacy protection. Some complicated websites may need Compatibility to work properly.\n\n" +

                "Off turns this privacy blocking off. Use it only as a last test if Compatibility does not fix a trusted website.\n\n" +

                "This setting only affects websites inside LexDesk Pro. It does not change other programs or games on your computer.\n\n" +

                "Not sure what to choose? Leave it on Recommended.";

            ShowWebPrivacyMessage(
                "Help me choose a Privacy Level",
                message,
                760,
                760);
        }

        private string GetSelectedPrivacyRelayLocation()
        {
            try
            {
                if (_privacyLocations == null || _privacyLocations.Length == 0)
                    return "Australia";

                if (_privacyLocationIndex < 0 || _privacyLocationIndex >= _privacyLocations.Length)
                    _privacyLocationIndex = 0;

                return _privacyLocations[_privacyLocationIndex];
            }
            catch
            {
                return "Australia";
            }
        }

        private PrivacyRelayEndpointConfig GetSelectedPrivacyRelayEndpoint()
        {
            try
            {
                string selectedLocation = GetSelectedPrivacyRelayLocation();

                if (_privacyRelayEndpointConfigs.TryGetValue(selectedLocation, out PrivacyRelayEndpointConfig? endpoint) &&
                    endpoint != null)
                {
                    return endpoint;
                }

                return new PrivacyRelayEndpointConfig
                {
                    Location = selectedLocation,
                    RegionCode = "UNKNOWN",
                    DisplayName = selectedLocation,
                    ProxyHost = "",
                    ProxyPort = 0,
                    IsEnabled = false
                };
            }
            catch
            {
                return new PrivacyRelayEndpointConfig
                {
                    Location = "Australia",
                    RegionCode = "AU",
                    DisplayName = "Australia",
                    ProxyHost = "",
                    ProxyPort = 0,
                    IsEnabled = false
                };
            }
        }

        private PrivacyRelayApiRequest BuildPrivacyRelayApiRequest(PrivacyRelayEndpointConfig endpoint)
        {
            string savedLicenseHash = LoadSavedLicenseHash() ?? "";

            string appVersion = "0.0.0.0";

            try
            {
                appVersion = Assembly.GetExecutingAssembly()
                    .GetName()
                    .Version?
                    .ToString() ?? "0.0.0.0";
            }
            catch
            {
                appVersion = "0.0.0.0";
            }

            return new PrivacyRelayApiRequest
            {
                // Never send or store the raw licence key here.
                LicenseHash = savedLicenseHash,
                DeviceFingerprint = GetDeviceFingerprint(),
                DeviceLabel = GetPrivacySafeDeviceLabel(),
                RequestedLocation = endpoint.DisplayName,
                RequestedRegionCode = endpoint.RegionCode,
                AppVersion = appVersion
            };
        }

        private async Task<PrivacyRelayApiResponse> RequestPrivacyRelayEndpointAsync(PrivacyRelayEndpointConfig endpoint)
        {
            try
            {
                PrivacyRelayApiRequest request = BuildPrivacyRelayApiRequest(endpoint);

                if (string.IsNullOrWhiteSpace(request.LicenseHash))
                {
                    return new PrivacyRelayApiResponse
                    {
                        Allowed = false,
                        Status = "not_activated",
                        Message = "No saved activation was found. Please activate LexDesk Pro before using Privacy Relay.",
                        Location = endpoint.DisplayName,
                        RegionCode = endpoint.RegionCode,
                        ProxyHost = "",
                        ProxyPort = 0,
                        RelaySessionToken = "",
                        ExpiresInSeconds = 0
                    };
                }

                if (string.IsNullOrWhiteSpace(request.DeviceFingerprint))
                {
                    return new PrivacyRelayApiResponse
                    {
                        Allowed = false,
                        Status = "device_check_failed",
                        Message = "LexDesk Pro could not prepare the device check for Privacy Relay.",
                        Location = endpoint.DisplayName,
                        RegionCode = endpoint.RegionCode,
                        ProxyHost = "",
                        ProxyPort = 0,
                        RelaySessionToken = "",
                        ExpiresInSeconds = 0
                    };
                }

                if (string.IsNullOrWhiteSpace(request.RequestedRegionCode))
                {
                    return new PrivacyRelayApiResponse
                    {
                        Allowed = false,
                        Status = "relay_region_missing",
                        Message = "Privacy Relay region information is missing.",
                        Location = endpoint.DisplayName,
                        RegionCode = endpoint.RegionCode,
                        ProxyHost = "",
                        ProxyPort = 0,
                        RelaySessionToken = "",
                        ExpiresInSeconds = 0
                    };
                }

                string json = JsonSerializer.Serialize(request);

                using var content = new StringContent(
                    json,
                    Encoding.UTF8,
                    "application/json");

                using var response = await _licenseHttpClient.PostAsync(
                    PrivacyRelayRequestApiUrl,
                    content);

                string responseJson = await response.Content.ReadAsStringAsync();

                if (!response.IsSuccessStatusCode)
                {
                    return new PrivacyRelayApiResponse
                    {
                        Allowed = false,
                        Status = "relay_api_http_error",
                        Message = $"Privacy Relay server returned HTTP {(int)response.StatusCode}.",
                        Location = endpoint.DisplayName,
                        RegionCode = endpoint.RegionCode,
                        ProxyHost = "",
                        ProxyPort = 0,
                        RelaySessionToken = "",
                        ExpiresInSeconds = 0
                    };
                }

                var apiResult = JsonSerializer.Deserialize<PrivacyRelayApiResponse>(
                    responseJson,
                    JsonCaseInsensitiveOptions);

                if (apiResult == null)
                {
                    return new PrivacyRelayApiResponse
                    {
                        Allowed = false,
                        Status = "relay_api_invalid_response",
                        Message = "Privacy Relay server returned an invalid response.",
                        Location = endpoint.DisplayName,
                        RegionCode = endpoint.RegionCode,
                        ProxyHost = "",
                        ProxyPort = 0,
                        RelaySessionToken = "",
                        ExpiresInSeconds = 0
                    };
                }

                string resultLocation = string.IsNullOrWhiteSpace(apiResult.Location)
                    ? endpoint.DisplayName
                    : apiResult.Location;

                string resultRegionCode = string.IsNullOrWhiteSpace(apiResult.RegionCode)
                    ? endpoint.RegionCode
                    : apiResult.RegionCode;

                // Safety gate:
                // Even if a future backend accidentally says Allowed=true,
                // the app refuses to continue unless a full relay package exists.
                if (apiResult.Allowed &&
                    (string.IsNullOrWhiteSpace(apiResult.ProxyHost) ||
                     apiResult.ProxyPort <= 0 ||
                     string.IsNullOrWhiteSpace(apiResult.RelaySessionToken)))
                {
                    return new PrivacyRelayApiResponse
                    {
                        Allowed = false,
                        Status = "relay_api_incomplete_response",
                        Message = "Privacy Relay server did not return a complete relay connection.",
                        Location = resultLocation,
                        RegionCode = resultRegionCode,
                        ProxyHost = "",
                        ProxyPort = 0,
                        RelaySessionToken = "",
                        ExpiresInSeconds = 0
                    };
                }

                return new PrivacyRelayApiResponse
                {
                    Allowed = apiResult.Allowed,
                    Status = string.IsNullOrWhiteSpace(apiResult.Status)
                        ? "relay_api_no_status"
                        : apiResult.Status,
                    Message = string.IsNullOrWhiteSpace(apiResult.Message)
                        ? "Privacy Relay response received."
                        : apiResult.Message,
                    Location = resultLocation,
                    RegionCode = resultRegionCode,
                    ProxyHost = apiResult.ProxyHost ?? "",
                    ProxyPort = apiResult.ProxyPort,
                    RelaySessionToken = apiResult.RelaySessionToken ?? "",
                    ExpiresInSeconds = apiResult.ExpiresInSeconds
                };
            }
            catch (TaskCanceledException)
            {
                return new PrivacyRelayApiResponse
                {
                    Allowed = false,
                    Status = "relay_api_timeout",
                    Message = "Privacy Relay server did not respond in time.",
                    Location = endpoint.DisplayName,
                    RegionCode = endpoint.RegionCode,
                    ProxyHost = "",
                    ProxyPort = 0,
                    RelaySessionToken = "",
                    ExpiresInSeconds = 0
                };
            }
            catch
            {
                return new PrivacyRelayApiResponse
                {
                    Allowed = false,
                    Status = "relay_api_error",
                    Message = "Privacy Relay API request could not be completed.",
                    Location = endpoint.DisplayName,
                    RegionCode = endpoint.RegionCode,
                    ProxyHost = "",
                    ProxyPort = 0,
                    RelaySessionToken = "",
                    ExpiresInSeconds = 0
                };
            }
        }

        private async Task<PrivacyRelayCheckApiResponse> RequestPrivacyRelayCheckAsync(PrivacyRelayStartupConfig config)
        {
            try
            {
                PrivacyRelayCheckApiRequest request = BuildPrivacyRelayCheckApiRequest(config);

                if (string.IsNullOrWhiteSpace(request.LicenseHash))
                {
                    return new PrivacyRelayCheckApiResponse
                    {
                        Confirmed = false,
                        Status = "not_activated",
                        Message = "No saved activation was found. Please activate LexDesk Pro before using Privacy Relay.",
                        PublicIp = "",
                        Location = request.ExpectedLocation,
                        RegionCode = request.ExpectedRegionCode
                    };
                }

                if (string.IsNullOrWhiteSpace(request.DeviceFingerprint))
                {
                    return new PrivacyRelayCheckApiResponse
                    {
                        Confirmed = false,
                        Status = "device_check_failed",
                        Message = "LexDesk Pro could not prepare the device check for Privacy Relay.",
                        PublicIp = "",
                        Location = request.ExpectedLocation,
                        RegionCode = request.ExpectedRegionCode
                    };
                }

                if (string.IsNullOrWhiteSpace(request.ExpectedRegionCode))
                {
                    return new PrivacyRelayCheckApiResponse
                    {
                        Confirmed = false,
                        Status = "relay_region_missing",
                        Message = "Privacy Relay region information is missing.",
                        PublicIp = "",
                        Location = request.ExpectedLocation,
                        RegionCode = request.ExpectedRegionCode
                    };
                }

                string json = JsonSerializer.Serialize(request);

                using var content = new StringContent(
                    json,
                    Encoding.UTF8,
                    "application/json");

                using var response = await _licenseHttpClient.PostAsync(
                    PrivacyRelayCheckApiUrl,
                    content);

                string responseJson = await response.Content.ReadAsStringAsync();

                if (!response.IsSuccessStatusCode)
                {
                    return new PrivacyRelayCheckApiResponse
                    {
                        Confirmed = false,
                        Status = "relay_check_http_error",
                        Message = $"Privacy Relay check server returned HTTP {(int)response.StatusCode}.",
                        PublicIp = "",
                        Location = request.ExpectedLocation,
                        RegionCode = request.ExpectedRegionCode
                    };
                }

                var apiResult = JsonSerializer.Deserialize<PrivacyRelayCheckApiResponse>(
                    responseJson,
                    JsonCaseInsensitiveOptions);

                if (apiResult == null)
                {
                    return new PrivacyRelayCheckApiResponse
                    {
                        Confirmed = false,
                        Status = "relay_check_invalid_response",
                        Message = "Privacy Relay check server returned an invalid response.",
                        PublicIp = "",
                        Location = request.ExpectedLocation,
                        RegionCode = request.ExpectedRegionCode
                    };
                }

                string resultLocation = string.IsNullOrWhiteSpace(apiResult.Location)
                    ? request.ExpectedLocation
                    : apiResult.Location;

                string resultRegionCode = string.IsNullOrWhiteSpace(apiResult.RegionCode)
                    ? request.ExpectedRegionCode
                    : apiResult.RegionCode;

                // Safety gate:
                // Never allow Protected if the backend confirms without a public IP.
                if (apiResult.Confirmed && string.IsNullOrWhiteSpace(apiResult.PublicIp))
                {
                    return new PrivacyRelayCheckApiResponse
                    {
                        Confirmed = false,
                        Status = "relay_check_incomplete_response",
                        Message = "Privacy Relay check did not return a confirmed public IP.",
                        PublicIp = "",
                        Location = resultLocation,
                        RegionCode = resultRegionCode
                    };
                }

                // Safety gate:
                // Never allow Protected if the confirmed region does not match the expected region.
                if (apiResult.Confirmed &&
                    !string.Equals(resultRegionCode, request.ExpectedRegionCode, StringComparison.OrdinalIgnoreCase))
                {
                    return new PrivacyRelayCheckApiResponse
                    {
                        Confirmed = false,
                        Status = "relay_check_region_mismatch",
                        Message = "Privacy Relay check returned a different region than expected.",
                        PublicIp = "",
                        Location = resultLocation,
                        RegionCode = resultRegionCode
                    };
                }

                return new PrivacyRelayCheckApiResponse
                {
                    Confirmed = apiResult.Confirmed,
                    Status = string.IsNullOrWhiteSpace(apiResult.Status)
                        ? "relay_check_no_status"
                        : apiResult.Status,
                    Message = string.IsNullOrWhiteSpace(apiResult.Message)
                        ? "Privacy Relay check response received."
                        : apiResult.Message,
                    PublicIp = apiResult.PublicIp ?? "",
                    Location = resultLocation,
                    RegionCode = resultRegionCode
                };
            }
            catch (TaskCanceledException)
            {
                return new PrivacyRelayCheckApiResponse
                {
                    Confirmed = false,
                    Status = "relay_check_timeout",
                    Message = "Privacy Relay check server did not respond in time.",
                    PublicIp = "",
                    Location = config?.Location ?? "",
                    RegionCode = config?.RegionCode ?? ""
                };
            }
            catch
            {
                return new PrivacyRelayCheckApiResponse
                {
                    Confirmed = false,
                    Status = "relay_check_api_error",
                    Message = "Privacy Relay check request could not be completed.",
                    PublicIp = "",
                    Location = config?.Location ?? "",
                    RegionCode = config?.RegionCode ?? ""
                };
            }
        }

        private async Task<bool> ApplyPrivacyRelayProxyAsync(PrivacyRelayApiResponse relayResponse)
        {
            try
            {
                await Task.Delay(250);

                // Stage 4A safety:
                // Real app-only WebView2 proxy application is not connected yet.
                //
                // Future Stage 4B:
                // - Apply app-only proxy settings using relayResponse.ProxyHost and relayResponse.ProxyPort.
                // - Recreate/restart WebView2 cleanly if required.
                // - Never mark Protected until IP confirmation passes.

                return false;
            }
            catch
            {
                return false;
            }
        }

        private void RemovePrivacyRelayProxy()
        {
            try
            {
                // Stage 4B-2:
                // Clear any pending restart relay config.
                // No live WebView2 proxy is removed yet because V2 relay applies at startup.

                ClearPrivacyRelayStartupConfig();
                _hideIpEnabled = false;
            }
            catch
            {
                _hideIpEnabled = false;
            }
        }

        private async Task<bool> ConfirmPrivacyRelayIpChangedAsync(PrivacyRelayApiResponse relayResponse)
        {
            try
            {
                if (relayResponse == null)
                    return false;

                var config = new PrivacyRelayStartupConfig
                {
                    Enabled = true,
                    Location = relayResponse.Location ?? "",
                    RegionCode = relayResponse.RegionCode ?? "",
                    ProxyHost = relayResponse.ProxyHost ?? "",
                    ProxyPort = relayResponse.ProxyPort,
                    SavedUtc = DateTime.UtcNow.ToString("O")
                };

                PrivacyRelayIpCheckResult result =
                    await ConfirmPrivacyRelayStartupAsync(config);

                return result.Confirmed;
            }
            catch
            {
                return false;
            }
        }

        private void LoadPrivacyRelayLocation()
        {
            try
            {
                if (!File.Exists(_privacyLocationPath))
                    return;

                string saved = (File.ReadAllText(_privacyLocationPath) ?? "").Trim();

                if (string.IsNullOrWhiteSpace(saved))
                    return;

                for (int i = 0; i < _privacyLocations.Length; i++)
                {
                    if (string.Equals(_privacyLocations[i], saved, StringComparison.OrdinalIgnoreCase))
                    {
                        _privacyLocationIndex = i;
                        return;
                    }
                }

                _privacyLocationIndex = 0;
            }
            catch
            {
                _privacyLocationIndex = 0;
            }
        }

        private void SavePrivacyRelayLocation()
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_privacyLocationPath)!);
                File.WriteAllText(_privacyLocationPath, GetSelectedPrivacyRelayLocation());
            }
            catch
            {
                // Privacy Relay location save must never affect browsing.
            }
        }

        private async Task ConnectPrivacyRelayAsync()
        {
            try
            {
                if (PrivacyRelayPublicComingSoonOnly)
                {
                    ClearPrivacyRelayStartupConfig();
                    RemovePrivacyRelayProxy();

                    _privacyRelayState = PrivacyRelayState.NotConnected;
                    _hideIpEnabled = false;
                    RefreshPrivacyNetworkVisuals();

                    return;
                }

                PrivacyRelayEndpointConfig endpoint = GetSelectedPrivacyRelayEndpoint();

                _privacyRelayState = PrivacyRelayState.Connecting;
                RefreshPrivacyNetworkVisuals();

                PrivacyRelayApiResponse relayResponse =
                    await RequestPrivacyRelayEndpointAsync(endpoint);

                bool hasUsableRelay =
                    relayResponse.Allowed &&
                    !string.IsNullOrWhiteSpace(relayResponse.ProxyHost) &&
                    relayResponse.ProxyPort > 0 &&
                    !string.IsNullOrWhiteSpace(relayResponse.RelaySessionToken);

                if (!hasUsableRelay)
                {
                    RemovePrivacyRelayProxy();

                    _privacyRelayState = PrivacyRelayState.Failed;
                    RefreshPrivacyNetworkVisuals();

                    ShowProtectionPopup(
                        "LexDesk Pro - Privacy Relay",
                        "Privacy Relay backend not connected",
                        "Privacy Relay API contract is ready for LexDesk Pro V2.\n\n" +
                        $"Selected relay location: {relayResponse.Location}\n" +
                        $"Region code: {relayResponse.RegionCode}\n" +
                        $"Status: {relayResponse.Status}\n\n" +
                        relayResponse.Message + "\n\n" +
                        "Your browsing is still using your normal internet connection.",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);

                    return;
                }

                bool savedForRestart = SavePrivacyRelayStartupConfig(relayResponse);

                if (!savedForRestart)
                {
                    RemovePrivacyRelayProxy();

                    _privacyRelayState = PrivacyRelayState.Failed;
                    RefreshPrivacyNetworkVisuals();

                    ShowProtectionPopup(
                        "LexDesk Pro - Privacy Relay",
                        "Privacy Relay could not be prepared",
                        "LexDesk Pro could not save the Privacy Relay startup configuration.\n\n" +
                        "No proxy has been applied.\n\n" +
                        "Your browsing is still using your normal internet connection.",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);

                    return;
                }

                _privacyRelayState = PrivacyRelayState.RestartRequired;
                RefreshPrivacyNetworkVisuals();

                ShowProtectionPopup(
                    "LexDesk Pro - Privacy Relay",
                    "Restart required",
                    "Privacy Relay is prepared for LexDesk Pro V2.\n\n" +
                    $"Relay location: {relayResponse.Location}\n" +
                    $"Region code: {relayResponse.RegionCode}\n\n" +
                    "Restart LexDesk Pro to apply the app-only relay connection.\n\n" +
                    "Until restart, your browsing is still using your normal internet connection.",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
            catch (Exception ex)
            {
                RemovePrivacyRelayProxy();

                _privacyRelayState = PrivacyRelayState.Failed;
                RefreshPrivacyNetworkVisuals();

                ShowProtectionPopup(
                    "LexDesk Pro - Privacy Relay",
                    "Privacy Relay failed",
                    "LexDesk Pro could not start Privacy Relay.\n\n" +
                    SanitizeExceptionMessage(ex),
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
        }

        private void DisconnectPrivacyRelay()
        {
            RemovePrivacyRelayProxy();

            _privacyRelayState = PrivacyRelayState.NotConnected;
            _hideIpEnabled = false;
            RefreshPrivacyNetworkVisuals();

            ShowProtectionPopup(
                "LexDesk Pro - Privacy Relay",
                "Privacy Relay disconnected",
                "Privacy Relay is off.\n\nYour browsing is using your normal internet connection.",
                MessageBoxButton.OK,
                MessageBoxImage.Information);
        }

        private async void HideIpButton_Click(object sender, RoutedEventArgs e)
        {
            if (PrivacyRelayPublicComingSoonOnly)
            {
                PrivacyRelayComingSoonButton_Click(sender, e);
                return;
            }

            if (!HasFullUnlock())
            {
                ShowProtectionPopup(
                    "LexDesk Pro - Privacy Relay",
                    "Activation required",
                    "Please activate LexDesk Pro to use Privacy Relay features.",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }


            switch (_privacyRelayState)
            {
                case PrivacyRelayState.NotConnected:
                case PrivacyRelayState.Failed:
                    {
                        await ConnectPrivacyRelayAsync();
                        break;
                    }

                case PrivacyRelayState.Connecting:
                    {
                        ShowProtectionPopup(
                            "LexDesk Pro - Privacy Relay",
                            "Privacy Relay is connecting",
                            "LexDesk Pro is already trying to connect Privacy Relay.",
                            MessageBoxButton.OK,
                            MessageBoxImage.Information);
                        break;
                    }

                case PrivacyRelayState.RestartRequired:
                    {
                        var restartRelayDecision = ShowProtectionPopup(
                            "LexDesk Pro - Privacy Relay",
                            "Privacy Relay restart required",
                            "Privacy Relay is prepared and will apply after LexDesk Pro restarts.\n\n" +
                            "Do you want to cancel the pending Privacy Relay connection?",
                            MessageBoxButton.YesNo,
                            MessageBoxImage.Question);

                        if (restartRelayDecision == MessageBoxResult.Yes)
                            DisconnectPrivacyRelay();

                        break;
                    }

                case PrivacyRelayState.Checking:
                    {
                        var checkingRelayDecision = ShowProtectionPopup(
                            "LexDesk Pro - Privacy Relay",
                            "Privacy Relay is checking",
                            "Privacy Relay startup settings were found and LexDesk Pro is checking the connection.\n\n" +
                            "Protection has not been confirmed yet.\n\n" +
                            "Do you want to cancel Privacy Relay and return to your normal internet connection?",
                            MessageBoxButton.YesNo,
                            MessageBoxImage.Question);

                        if (checkingRelayDecision == MessageBoxResult.Yes)
                            DisconnectPrivacyRelay();

                        break;
                    }

                case PrivacyRelayState.Protected:
                    {
                        DisconnectPrivacyRelay();
                        break;
                    }
            }
        }

