        private void LoadPrivacyMode()
        {
            try
            {
                if (!File.Exists(_privacyPath)) return;

                var txt = (File.ReadAllText(_privacyPath) ?? "").Trim();
                if (Enum.TryParse(txt, out PrivacyMode mode))
                    _privacyMode = mode;
            }
            catch { }
        }

