        private BitmapImage? LoadDefaultStartupLogo()
        {
            try
            {
                var bmp = new BitmapImage();
                bmp.BeginInit();
                bmp.CacheOption = BitmapCacheOption.OnLoad;
                bmp.UriSource = new Uri("pack://application:,,,/Assets/web-protect-pro-logo.png", UriKind.Absolute);
                bmp.EndInit();
                bmp.Freeze();
                return bmp;
            }
            catch
            {
                return null;
            }
        }

        private void RefreshHomeOverlayImage1()
        {
            if (HomeOverlayImage1 == null || HomeOverlayImagePlaceholder1 == null || HomeOverlayShade1 == null)
                return;

            try
            {
                if (!string.IsNullOrWhiteSpace(_homeOverlayImagePath) &&
                    File.Exists(_homeOverlayImagePath))
                {
                    var bmp = new BitmapImage();
                    bmp.BeginInit();
                    bmp.CacheOption = BitmapCacheOption.OnLoad;
                    bmp.UriSource = new Uri(_homeOverlayImagePath);
                    bmp.EndInit();

                    HomeOverlayImage1.Source = bmp;
                    HomeOverlayImage1.Visibility = Visibility.Visible;
                    HomeOverlayShade1.Visibility = Visibility.Visible;
                    HomeOverlayImagePlaceholder1.Visibility = Visibility.Collapsed;
                }
                else
                {
                    var defaultLogo = LoadDefaultStartupLogo();

                    if (defaultLogo != null)
                    {
                        HomeOverlayImage1.Source = defaultLogo;
                        HomeOverlayImage1.Visibility = Visibility.Visible;
                        HomeOverlayShade1.Visibility = Visibility.Visible;
                        HomeOverlayImagePlaceholder1.Visibility = Visibility.Collapsed;
                    }
                    else
                    {
                        HomeOverlayImage1.Source = null;
                        HomeOverlayImage1.Visibility = Visibility.Collapsed;
                        HomeOverlayShade1.Visibility = Visibility.Collapsed;
                        HomeOverlayImagePlaceholder1.Visibility = Visibility.Visible;
                    }
                }
            }
            catch
            {
                HomeOverlayImage1.Source = null;
                HomeOverlayImage1.Visibility = Visibility.Collapsed;
                HomeOverlayShade1.Visibility = Visibility.Collapsed;
                HomeOverlayImagePlaceholder1.Visibility = Visibility.Visible;
            }
        }

        private void RefreshStartupScreenOverlayImage()
        {
            if (StartupScreenOverlayImage == null ||
                StartupScreenOverlayPlaceholder == null ||
                StartupScreenOverlayShade == null)
                return;

            try
            {
                bool hasImage =
                    !string.IsNullOrWhiteSpace(_homeOverlayImagePath) &&
                    File.Exists(_homeOverlayImagePath);

                BitmapImage? bitmap = null;

                if (hasImage)
                {
                    bitmap = new BitmapImage();
                    bitmap.BeginInit();
                    bitmap.CacheOption = BitmapCacheOption.OnLoad;
                    bitmap.UriSource = new Uri(_homeOverlayImagePath, UriKind.Absolute);
                    bitmap.EndInit();
                    bitmap.Freeze();
                }
                else
                {
                    bitmap = LoadDefaultStartupLogo();
                }

                if (bitmap == null)
                {
                    StartupScreenOverlayImage.Source = null;
                    StartupScreenOverlayImage.Visibility = Visibility.Collapsed;
                    StartupScreenOverlayShade.Visibility = Visibility.Collapsed;
                    StartupScreenOverlayPlaceholder.Visibility = Visibility.Visible;
                    return;
                }

                StartupScreenOverlayImage.Source = bitmap;
                StartupScreenOverlayImage.Visibility = Visibility.Visible;
                StartupScreenOverlayShade.Visibility = Visibility.Visible;
                StartupScreenOverlayPlaceholder.Visibility = Visibility.Collapsed;
            }
            catch
            {
                StartupScreenOverlayImage.Source = null;
                StartupScreenOverlayImage.Visibility = Visibility.Collapsed;
                StartupScreenOverlayShade.Visibility = Visibility.Collapsed;
                StartupScreenOverlayPlaceholder.Visibility = Visibility.Visible;
            }
        }

