        private Task EnsureAdBlockListAsync()
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_adBlockListPath)!);

                // If user already has a blocklist, just load it.
                if (File.Exists(_adBlockListPath))
                {
                    LoadAdBlockHosts();
                    return Task.CompletedTask;
                }

                // First run: copy starter list shipped with the app (FAST, offline).
                var starterPath = Path.Combine(
                    AppDomain.CurrentDomain.BaseDirectory,
                    "Assets",
                    "adblock_hosts_starter.txt");

                if (File.Exists(starterPath))
                {
                    File.Copy(starterPath, _adBlockListPath, overwrite: true);
                }
                else
                {
                    // Absolute fallback (still fast)
                    File.WriteAllLines(_adBlockListPath, new[]
                    {
                "doubleclick.net",
                "googlesyndication.com",
                "googleadservices.com",
                "googletagmanager.com",
                "taboola.com",
                "outbrain.com"
            });
                }

                LoadAdBlockHosts();
            }
            catch
            {
                // If anything goes wrong, don’t block startup.
                try { LoadAdBlockHosts(); } catch { }
            }

            return Task.CompletedTask;
        }

        // Shared hosting, CDN, streaming and platform roots that must never be
        // treated as globally bad by LexDesk Pro's lightweight host blocker.
        //
        // Important:
        // Specific bad subdomains can still be blocked.
        // Example: bad-ad-server.cloudfront.net can still be blocked,
        // but cloudfront.net itself must never block every CloudFront customer.
        private static readonly HashSet<string> ProtectedHostListEntries =
            new(StringComparer.OrdinalIgnoreCase)
            {
        // Akamai / shared CDN infrastructure
        "akamaized.net",
        "akamaihd.net",
        "akamaiedge.net",
        "edgekey.net",
        "edgesuite.net",

        // Amazon / CloudFront
        "cloudfront.net",
        "amazonaws.com",
        "s3.amazonaws.com",
        "amazon.com",

        // Microsoft / Azure CDN
        "azureedge.net",

        // Shared web-hosting platforms
        "workers.dev",
        "netlify.app",
        "github.io",
        "raw.githubusercontent.com",
        "onrender.com",
        "wp.com",

        // Google functional / video infrastructure
        "googleapis.com",
        "storage.googleapis.com",
        "googlevideo.com",
        "youtube.com",

        // Shared JavaScript / CDN infrastructure
        "jsdelivr.net",
        "unpkg.com",
        "b-cdn.net",
        "cdn77.org",

        // Streaming / video players
        "jwplayer.com",
        "jwplatform.com",
        "brightcove.net",
        "players.brightcove.net",
        "boltdns.net",
        "manifest.prod.boltdns.net",

        // Payment infrastructure
        "paypalobjects.com"
            };

        private static bool IsProtectedHostListEntry(string? host)
        {
            if (string.IsNullOrWhiteSpace(host))
                return false;

            host = host.Trim().TrimEnd('.').ToLowerInvariant();

            return ProtectedHostListEntries.Contains(host);
        }

        private void LoadAdBlockHosts()
        {
            _blockedHosts.Clear();

            if (!File.Exists(_adBlockListPath))
                return;

            foreach (var line in File.ReadAllLines(_adBlockListPath))
            {
                var host = line.Trim().TrimEnd('.').ToLowerInvariant();

                if (string.IsNullOrWhiteSpace(host))
                    continue;

                // Ignore malformed/wildcard entries in old protection files.
                if (host.Contains('*') ||
                    Uri.CheckHostName(host) == UriHostNameType.Unknown)
                {
                    continue;
                }

                // Never activate a blanket block against known shared infrastructure.
                if (IsProtectedHostListEntry(host))
                    continue;

                _blockedHosts.Add(host);
            }
        }

        private void LoadWhitelist()
        {
            _adBlockWhitelist.Clear();
            if (!File.Exists(_whitelistPath)) return;

            foreach (var line in File.ReadAllLines(_whitelistPath))
            {
                var host = line.Trim();
                if (!string.IsNullOrWhiteSpace(host))
                    _adBlockWhitelist.Add(host);

                if (WhitelistEditor != null)
                    WhitelistEditor.Text = string.Join(Environment.NewLine, _adBlockWhitelist);
            }
        }

        private void SaveWhitelist()
        {
            Directory.CreateDirectory(Path.GetDirectoryName(_whitelistPath)!);
            File.WriteAllLines(_whitelistPath, _adBlockWhitelist);
        }

        private async void UpdateBlocklist_Click(object sender, RoutedEventArgs e)
        {
            if (UpdateBlocklistButton != null) UpdateBlocklistButton.IsEnabled = false;
            if (PrivacyStatusText != null) PrivacyStatusText.Text = "Updating Block List...";

            try
            {
                if (File.Exists(_adBlockListPath))
                    File.Delete(_adBlockListPath);

                // Download EasyList ONLY when user clicks update
                using var client = new HttpClient();
                var raw = await client.GetStringAsync("https://easylist.to/easylist/easylist.txt");
                var hosts = ExtractHostsFromEasyList(raw);
                File.WriteAllLines(_adBlockListPath, hosts);

                LoadAdBlockHosts();

                if (PrivacyStatusText != null)
                    PrivacyStatusText.Text = "Protection list updated.";

                ShowLexDeskMessageBox(
                    "Protection list updated.\n\nLexDesk Pro has refreshed its list of known ads, trackers, and unwanted web content.",
                    "Protection List",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
            catch
            {
                if (PrivacyStatusText != null)
                    PrivacyStatusText.Text = "Protection list update failed.";

                ShowLexDeskMessageBox(
                    "LexDesk Pro could not update the protection list.\n\nPlease check your internet connection and try again.",
                    "Protection List",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
            finally
            {
                if (UpdateBlocklistButton != null) UpdateBlocklistButton.IsEnabled = true;
            }
            if (WhitelistEditor != null)
            {
                var lines = WhitelistEditor.Text
                    .Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries)
                    .Select(x => x.Trim())
                    .Where(x => !string.IsNullOrWhiteSpace(x))
                    .Distinct(StringComparer.OrdinalIgnoreCase);

                _adBlockWhitelist.Clear();
                foreach (var l in lines)
                    _adBlockWhitelist.Add(l);
            }
        }

        private static IEnumerable<string> ExtractHostsFromEasyList(string raw)
        {
            var list = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            foreach (var line in raw.Split('\n'))
            {
                var trimmed = line.Trim();

                if (string.IsNullOrWhiteSpace(trimmed)) continue;
                if (trimmed.StartsWith("!")) continue;
                if (trimmed.StartsWith("[")) continue;

                // LexDesk Pro stores a HOST list, not the full EasyList rule language.
                // Only import rules that truly target a whole host. Path-specific EasyList
                // rules such as ||example.com/some-ad-path must NOT be collapsed to
                // example.com, otherwise ordinary site functionality can be blocked.
                if (!trimmed.StartsWith("||", StringComparison.Ordinal))
                    continue;

                var rule = trimmed.Substring(2);

                int optionsIndex = rule.IndexOf('$');
                if (optionsIndex >= 0)
                    rule = rule.Substring(0, optionsIndex);

                rule = rule.Trim();

                // Host-only rules may end with ^. Anything containing a path, query,
                // wildcard or other rule syntax is deliberately skipped because this
                // lightweight engine cannot represent that narrower EasyList condition.
                if (rule.Contains('/') ||
                    rule.Contains('?') ||
                    rule.Contains('*') ||
                    rule.Contains('='))
                {
                    continue;
                }

                int separatorIndex = rule.IndexOf('^');
                if (separatorIndex >= 0)
                {
                    // A separator in the middle of extra rule text is not a pure host rule.
                    if (separatorIndex != rule.Length - 1)
                        continue;

                    rule = rule.Substring(0, separatorIndex);
                }

                rule = rule.Trim().TrimEnd('.');

                if (string.IsNullOrWhiteSpace(rule) ||
                    rule.Contains('|') ||
                    !rule.Contains('.'))
                {
                    continue;
                }
                if (Uri.CheckHostName(rule) == UriHostNameType.Unknown)
                    continue;

                rule = rule.ToLowerInvariant();

                // Never write blanket shared-infrastructure blocks into the protection list.
                // Specific bad subdomains are still allowed through and can be blocked normally.
                if (IsProtectedHostListEntry(rule))
                    continue;

                list.Add(rule);
            }

            return list;
        }


        private static string GetHost(string? uri)
        {
            if (string.IsNullOrWhiteSpace(uri)) return "";
            return Uri.TryCreate(uri, UriKind.Absolute, out var u) ? (u.Host ?? "") : "";
        }

        // Stage 2N.7:
        // Some public filter lists contain path-specific rules on shared infrastructure.
        // LexDesk Pro intentionally uses a lightweight host blocker, so these common
        // functional hosts must never be treated as globally bad merely because a narrow
        // EasyList rule happened to mention them.
        private static bool IsSharedFunctionalInfrastructureHost(string? host)
        {
            if (string.IsNullOrWhiteSpace(host))
                return false;

            host = host.Trim().TrimEnd('.').ToLowerInvariant();

            if (host == "accounts.google.com" ||
                host == "maps.googleapis.com" ||
                host == "maps.gstatic.com" ||
                host == "fonts.googleapis.com" ||
                host == "fonts.gstatic.com" ||
                host == "cdn.jsdelivr.net" ||
                host.EndsWith(".cdn.jsdelivr.net") ||
                host == "unpkg.com" ||
                host.EndsWith(".unpkg.com") ||
                host == "cdnjs.cloudflare.com" ||
                host.EndsWith(".cdnjs.cloudflare.com") ||
                host == "appleid.cdn-apple.com" ||
                host == "login.microsoftonline.com" ||
                host == "login.live.com" ||
                host == "aadcdn.msauth.net" ||
                host.EndsWith(".aadcdn.msauth.net") ||
                host == "aadcdn.msftauth.net" ||
                host.EndsWith(".aadcdn.msftauth.net"))
            {
                return true;
            }

            return false;
        }

        // Allows narrowly identified third-party infrastructure that is commonly required
        // for sign-in, CAPTCHA, maps/location selectors, fonts and shared script/style CDNs.
        // This runs before ordinary host-list blocking, but does NOT exempt advertising,
        // analytics or generic Google domains.
        private static bool IsEssentialThirdPartyInfrastructureRequest(
            string requestUrl,
            string requestHost,
            CoreWebView2WebResourceContext context)
        {
            if (string.IsNullOrWhiteSpace(requestHost))
                return false;

            string host = requestHost.Trim().TrimEnd('.').ToLowerInvariant();

            if (host == "accounts.google.com" ||
                host == "appleid.cdn-apple.com" ||
                host == "login.microsoftonline.com" ||
                host == "login.live.com" ||
                host == "aadcdn.msauth.net" ||
                host.EndsWith(".aadcdn.msauth.net") ||
                host == "aadcdn.msftauth.net" ||
                host.EndsWith(".aadcdn.msftauth.net"))
            {
                return true;
            }

            if (host == "maps.googleapis.com" ||
                host == "maps.gstatic.com")
            {
                return true;
            }

            if (host == "fonts.googleapis.com")
                return context == CoreWebView2WebResourceContext.Stylesheet;

            if (host == "fonts.gstatic.com")
                return context == CoreWebView2WebResourceContext.Font ||
                       context == CoreWebView2WebResourceContext.Image;

            if (host == "cdn.jsdelivr.net" ||
                host.EndsWith(".cdn.jsdelivr.net") ||
                host == "unpkg.com" ||
                host.EndsWith(".unpkg.com") ||
                host == "cdnjs.cloudflare.com" ||
                host.EndsWith(".cdnjs.cloudflare.com"))
            {
                return context == CoreWebView2WebResourceContext.Script ||
                       context == CoreWebView2WebResourceContext.Stylesheet ||
                       context == CoreWebView2WebResourceContext.Font ||
                       context == CoreWebView2WebResourceContext.Other;
            }

            if (!Uri.TryCreate(requestUrl, UriKind.Absolute, out var uri))
                return false;

            string path = (uri.AbsolutePath ?? "").ToLowerInvariant();

            bool googleRecaptcha =
                (host == "www.google.com" || host == "google.com") &&
                path.Contains("/recaptcha/");

            bool recaptchaNet =
                (host == "www.recaptcha.net" ||
                 host == "recaptcha.net" ||
                 host.EndsWith(".recaptcha.net")) &&
                path.Contains("/recaptcha/");

            bool gstaticRecaptcha =
                (host == "www.gstatic.com" || host == "gstatic.com") &&
                path.Contains("/recaptcha/");

            return googleRecaptcha || recaptchaNet || gstaticRecaptcha;
        }

        private static readonly HashSet<string> MultiLabelPublicSuffixes = new(StringComparer.OrdinalIgnoreCase)
        {
            "com.au", "net.au", "org.au", "edu.au", "gov.au", "asn.au", "id.au",
            "co.nz", "net.nz", "org.nz", "govt.nz", "ac.nz", "school.nz", "iwi.nz", "maori.nz",
            "co.uk", "org.uk", "me.uk", "ac.uk", "gov.uk", "sch.uk", "ltd.uk", "plc.uk", "net.uk",
            "co.jp", "ne.jp", "or.jp", "ac.jp", "go.jp",
            "co.kr", "or.kr", "ne.kr",
            "co.in", "firm.in", "net.in", "org.in", "gen.in", "ind.in",
            "co.za", "org.za", "net.za",
            "com.sg", "com.hk", "com.cn", "com.tw",
            "com.br", "com.mx", "com.tr"
        };

        private static string RegistrableDomain(string host)
        {
            if (string.IsNullOrWhiteSpace(host))
                return "";

            host = host.Trim().TrimEnd('.').ToLowerInvariant();

            // IP addresses and single-label/local host names do not use public suffix rules.
            if (System.Net.IPAddress.TryParse(host, out _) || !host.Contains('.'))
                return host;

            var parts = host.Split('.', StringSplitOptions.RemoveEmptyEntries);
            if (parts.Length <= 2)
                return host;

            // Common multi-label public suffixes used by sites our customers are likely to visit.
            // This avoids treating unrelated domains such as bikesales.com.au and example.com.au
            // as if they belonged to the same first party.
            string lastTwo = parts[^2] + "." + parts[^1];

            if (MultiLabelPublicSuffixes.Contains(lastTwo) && parts.Length >= 3)
                return parts[^3] + "." + lastTwo;

            return lastTwo;
        }

        private static bool IsYouTubeHost(string? host)
        {
            if (string.IsNullOrWhiteSpace(host)) return false;

            host = host.ToLowerInvariant();

            return host == "youtube.com"
                || host == "www.youtube.com"
                || host == "m.youtube.com"
                || host.EndsWith(".youtube.com")
                || host == "youtubei.googleapis.com"
                || host.EndsWith(".googlevideo.com")
                || host.EndsWith(".ytimg.com")
                || host.EndsWith(".ggpht.com");
        }

        private static bool IsYouTubePage(string? url)
        {
            var host = GetHost(url);
            return IsYouTubeHost(host);
        }

        private static bool IsYouTubeEssentialRequest(string? pageUrl, string? requestUrl)
        {
            if (!IsYouTubePage(pageUrl)) return false;

            var reqHost = GetHost(requestUrl);
            return IsYouTubeHost(reqHost);
        }

        private static bool HostMatches(string? host, params string[] suffixes)
        {
            if (string.IsNullOrWhiteSpace(host)) return false;

            host = host.ToLowerInvariant();

            foreach (var suffix in suffixes)
            {
                var s = suffix.ToLowerInvariant();
                if (host == s || host.EndsWith("." + s))
                    return true;
            }

            return false;
        }

        private static bool IsBankingSite(string? url)
        {
            var host = GetHost(url);
            return HostMatches(host,
                "anz.com.au",
                "anz.com",
                "westpac.com.au",
                "stgeorge.com.au",
                "nab.com.au",
                "commbank.com.au",
                "bankwest.com.au",
                "suncorpbank.com.au",
                "macquarie.com.au");
        }

        private static bool IsGovernmentSite(string? url)
        {
            var host = GetHost(url);
            return HostMatches(host,
                "gov.au",
                "my.gov.au",
                "ato.gov.au",
                "service.nsw.gov.au",
                "vic.gov.au",
                "qld.gov.au");
        }

        private static bool IsAuthOrPaymentSite(string? url)
        {
            var host = GetHost(url);
            return HostMatches(host,
                "paypal.com",
                "stripe.com",
                "checkout.com",
                "afterpay.com",
                "zip.co");
        }

        private static bool IsKnownAuthLoginHost(string? host)
        {
            if (string.IsNullOrWhiteSpace(host))
                return false;

            host = host.Replace("www.", "").ToLowerInvariant();

            return HostMatches(host,
                // Australian government / tax / identity
                "my.gov.au",
                "login.my.gov.au",
                "mygovid.gov.au",
                "identity.gov.au",
                "accessmanager.gov.au",
                "ato.gov.au",
                "onlineservices.ato.gov.au",

                // Microsoft account / Store / Partner Center sign-in
                "login.microsoftonline.com",
                "login.live.com",
                "account.microsoft.com",
                "accounts.microsoft.com",
                "partner.microsoft.com",

                // Common trusted identity/payment flows
                "accounts.google.com",
                "appleid.apple.com",
                "paypal.com",
                "stripe.com",
                "checkout.com");
        }

        private static bool IsTrustedLoginFlowUrl(string? url)
        {
            if (string.IsNullOrWhiteSpace(url))
                return false;

            if (!Uri.TryCreate(url, UriKind.Absolute, out var uri))
                return false;

            bool isWeb =
                uri.Scheme.Equals("http", StringComparison.OrdinalIgnoreCase) ||
                uri.Scheme.Equals("https", StringComparison.OrdinalIgnoreCase);

            if (!isWeb)
                return false;

            string host = uri.Host?.Replace("www.", "").ToLowerInvariant() ?? "";

            if (string.IsNullOrWhiteSpace(host))
                return false;

            return IsGovernmentSite(url)
                || IsBankingSite(url)
                || IsAuthOrPaymentSite(url)
                || IsKnownAuthLoginHost(host);
        }

        private static bool IsTrustedLoginFlowPair(string? openerUrl, string? targetUrl)
        {
            if (!IsTrustedLoginFlowUrl(targetUrl))
                return false;

            // If both sides are trusted auth/government/payment/banking, allow the handoff.
            if (IsTrustedLoginFlowUrl(openerUrl))
                return true;

            string targetHost = GetHost(targetUrl);

            // Allow trusted login targets even when the opener is a normal page.
            return IsKnownAuthLoginHost(targetHost);
        }

        private static bool IsBlankOrScriptOwnedPopupUrl(string? popupUrl)
        {
            string value = (popupUrl ?? "").Trim();

            if (string.IsNullOrWhiteSpace(value))
                return true;

            return value.Equals("about:blank", StringComparison.OrdinalIgnoreCase)
                || value.Equals("about:srcdoc", StringComparison.OrdinalIgnoreCase);
        }

        private static bool ShouldLetTrustedSiteOpenRealWindow(
            string? openerUrl,
            string? popupUrl,
            bool isUserInitiated)
        {
            // Some trusted sites open a blank window first, then write printable content into it.
            // Example: ATO Print Friendly Version.
            if (IsBlankOrScriptOwnedPopupUrl(popupUrl) && IsTrustedLoginFlowUrl(openerUrl))
                return true;

            // If a government site deliberately opens another government page from a user click,
            // let WebView2 create the real browser popup window.
            if (isUserInitiated && IsGovernmentSite(openerUrl) && IsGovernmentSite(popupUrl))
                return true;

            return false;
        }

        private static bool IsSensitiveLoginUrl(string? url)
        {
            if (string.IsNullOrWhiteSpace(url)) return false;

            if (!Uri.TryCreate(url, UriKind.Absolute, out var uri))
                return false;

            if (!(IsBankingSite(url) || IsGovernmentSite(url) || IsAuthOrPaymentSite(url)))
                return false;

            string host = uri.Host?.ToLowerInvariant() ?? "";
            string path = uri.AbsolutePath?.ToLowerInvariant() ?? "";
            string query = uri.Query?.ToLowerInvariant() ?? "";

            // Common signs of fragile / temporary auth links
            // Strong detection for banking/auth session-style URLs
            return
                host.Contains("login.") ||

                // Explicit banking login paths
                path.Contains("internetbanking") ||
                path.Contains("login") ||
                path.Contains("signin") ||
                path.Contains("authenticate") ||
                path.Contains("auth") ||

                // Query-based session markers (VERY important)
                query.Contains("session") ||
                query.Contains("token") ||
                query.Contains("code=") ||
                query.Contains("state=") ||
                query.Contains("mboxid=") ||
                query.Contains("returnurl=") ||
                query.Contains("redirect=") ||

                // Catch-all for ANZ-style login hosts specifically
                host.Contains("anz.com") && path.Contains("internetbanking");
        }

        private static string GetCleanSensitiveSiteEntryUrl(string? url)
        {
            if (string.IsNullOrWhiteSpace(url))
                return "";

            if (!Uri.TryCreate(url, UriKind.Absolute, out var uri))
                return url ?? "";

            string host = uri.Host.ToLowerInvariant();

            // ANZ
            if (host.Contains("anz.com.au") || host.Contains("anz.com"))
                return "https://www.anz.com.au/";

            // Westpac / St George / Bank of Melbourne / BankSA family
            if (host.Contains("westpac.com.au") || host.Contains("stgeorge.com.au"))
                return $"https://{uri.Host}/";

            // NAB
            if (host.Contains("nab.com.au"))
                return "https://www.nab.com.au/";

            // Commonwealth Bank
            if (host.Contains("commbank.com.au"))
                return "https://www.commbank.com.au/";

            // Bankwest
            if (host.Contains("bankwest.com.au"))
                return "https://www.bankwest.com.au/";

            // Suncorp
            if (host.Contains("suncorpbank.com.au"))
                return "https://www.suncorpbank.com.au/";

            // Macquarie
            if (host.Contains("macquarie.com.au"))
                return "https://www.macquarie.com.au/";

            // Generic safe fallback: host root only
            return $"{uri.Scheme}://{uri.Host}/";
        }

        private static string NormalizeSensitiveNavigationTarget(string? url)
        {
            if (string.IsNullOrWhiteSpace(url))
                return "";

            return IsSensitiveLoginUrl(url)
                ? GetCleanSensitiveSiteEntryUrl(url)
                : url ?? "";
        }

        private static string GetCompatibilityProfileLabel(string? url)
        {
            if (IsYouTubePage(url)) return "YouTube";
            if (IsBankingSite(url)) return "Banking";
            if (IsGovernmentSite(url)) return "Government";
            if (IsAuthOrPaymentSite(url)) return "Payments / Login";
            return "";
        }

        private static bool IsCompatibilitySensitiveSite(string? url)
        {
            return IsYouTubePage(url)
                || IsBankingSite(url)
                || IsGovernmentSite(url)
                || IsAuthOrPaymentSite(url);
        }

        private static bool IsCompatibilityEssentialRequest(
            string requestUrl,
            CoreWebView2WebResourceContext context)
        {
            if (context == CoreWebView2WebResourceContext.Media)
                return true;

            string lower = (requestUrl ?? "").ToLowerInvariant();

            bool looksLikeLoginOrSession =
                lower.Contains("/login") ||
                lower.Contains("/signin") ||
                lower.Contains("/sign-in") ||
                lower.Contains("/auth") ||
                lower.Contains("/oauth") ||
                lower.Contains("/sso") ||
                lower.Contains("/session") ||
                lower.Contains("/token") ||
                lower.Contains("/identity") ||
                lower.Contains("/account") ||
                lower.Contains("authorize") ||
                lower.Contains("authentication");

            if (!looksLikeLoginOrSession)
                return false;

            return context == CoreWebView2WebResourceContext.Script ||
                   context == CoreWebView2WebResourceContext.XmlHttpRequest ||
                   context == CoreWebView2WebResourceContext.Fetch ||
                   context == CoreWebView2WebResourceContext.Other;
        }

        // ============================================
        // Stage 2J - Smart Compatibility playback helpers
        // ============================================
        // Modern streaming players frequently fetch manifests, DRM/licence data,
        // and media segments through Fetch/XHR/Other rather than the Media context.
        // Smart Compatibility must allow that playback plumbing without turning off
        // ad/tracker filtering for the whole site.
        private static bool IsStreamingPlaybackEssentialRequest(
            string requestUrl,
            CoreWebView2WebResourceContext context)
        {
            if (context == CoreWebView2WebResourceContext.Media)
                return true;

            if (string.IsNullOrWhiteSpace(requestUrl))
                return false;

            bool supportedContext =
                context == CoreWebView2WebResourceContext.Script ||
                context == CoreWebView2WebResourceContext.XmlHttpRequest ||
                context == CoreWebView2WebResourceContext.Fetch ||
                context == CoreWebView2WebResourceContext.Other;

            if (!supportedContext)
                return false;

            if (!Uri.TryCreate(requestUrl, UriKind.Absolute, out var uri))
                return false;

            string path = (uri.AbsolutePath ?? "").ToLowerInvariant();
            string query = (uri.Query ?? "").ToLowerInvariant();

            bool streamingFile =
                path.EndsWith(".m3u8") ||
                path.EndsWith(".mpd") ||
                path.EndsWith(".m4s") ||
                path.EndsWith(".m4f") ||
                path.EndsWith(".ts") ||
                path.EndsWith(".mp4") ||
                path.EndsWith(".webm") ||
                path.EndsWith(".aac") ||
                path.EndsWith(".m4a");

            bool playbackEndpoint =
                path.Contains("/manifest/") ||
                path.Contains("/license/") ||
                path.Contains("/playback") ||
                path.Contains("/drm/") ||
                path.Contains("/widevine") ||
                path.Contains("/playready") ||
                path.Contains("/segment") ||
                path.Contains("/chunk") ||
                path.Contains("/init.");

            // Common streaming APIs identify the requested programme in the query
            // even when the endpoint itself has no useful file extension.
            bool playbackQuery =
                query.Contains("videotype=") &&
                (query.Contains("accountid=") ||
                 query.Contains("referenceid=") ||
                 query.Contains("contentid="));

            return streamingFile || playbackEndpoint || playbackQuery;
        }

        private static bool IsSevenPlusPage(string? pageUrl)
        {
            string host = GetHost(pageUrl ?? "").Trim().TrimEnd('.').ToLowerInvariant();

            return host == "7plus.com.au" ||
                   host.EndsWith(".7plus.com.au", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsSevenPlusAdMediaRequest(
            string pageUrl,
            string requestHost,
            CoreWebView2WebResourceContext context)
        {
            if (!IsSevenPlusPage(pageUrl))
                return false;

            // The 7plus diagnostic run showed programme/auth/playback plumbing on
            // Seven, SWM Digital, Brightcove/BoltDNS and Akamai, while ad video media
            // was delivered from Google 2mdn hosts. Block only the ad-media host here
            // and leave the real programme pipeline alone.
            if (context != CoreWebView2WebResourceContext.Media &&
                context != CoreWebView2WebResourceContext.Image)
            {
                return false;
            }

            string host = (requestHost ?? "").Trim().TrimEnd('.').ToLowerInvariant();

            return host == "2mdn.net" ||
                   host.EndsWith(".2mdn.net", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsObviousAdOrTrackerHost(string? host)
        {
            if (string.IsNullOrWhiteSpace(host)) return false;

            host = host.ToLowerInvariant();

            return host == "doubleclick.net"
                || host.EndsWith(".doubleclick.net")
                || host == "pagead2.googlesyndication.com"
                || host.EndsWith(".googlesyndication.com")
                || host == "googleadservices.com"
                || host.EndsWith(".googleadservices.com")
                || host == "adservice.google.com"
                || host.EndsWith(".adservice.google.com")
                || host == "amazon-adsystem.com"
                || host.EndsWith(".amazon-adsystem.com")
                || host == "taboola.com"
                || host.EndsWith(".taboola.com")
                || host == "outbrain.com"
                || host.EndsWith(".outbrain.com")
                || host == "tremorhub.com"
                || host.EndsWith(".tremorhub.com")
                || host == "adsafeprotected.com"
                || host.EndsWith(".adsafeprotected.com")
                || host == "imrworldwide.com"
                || host.EndsWith(".imrworldwide.com")
                || host == "google-analytics.com"
                || host.EndsWith(".google-analytics.com")
                || host == "googletagmanager.com"
                || host.EndsWith(".googletagmanager.com")
                || host == "facebook.net"
                || host.EndsWith(".facebook.net")
                || host == "connect.facebook.net"
                || host == "hotjar.com"
                || host.EndsWith(".hotjar.com");
        }

        private static bool IsHighConfidenceAdvertisingRequest(string requestUrl, string requestHost)
        {
            if (IsObviousAdOrTrackerHost(requestHost))
                return true;

            string lower = (requestUrl ?? "").ToLowerInvariant();

            // Keep this deliberately narrow. Do not match generic words such as
            // "advert" because legitimate streaming APIs often carry parameters
            // such as advertId=null while requesting the real programme.
            return lower.Contains("/gampad/ads") ||
                   lower.Contains("/pagead/") ||
                   lower.Contains("/adserver/") ||
                   lower.Contains("/adserver?") ||
                   lower.Contains("/vast/") ||
                   lower.Contains("/vast?") ||
                   lower.Contains("pubads.");
        }

        private static bool IsThirdParty(string pageUrl, string requestUrl)
        {
            var pageHost = GetHost(pageUrl);
            var reqHost = GetHost(requestUrl);

            if (string.IsNullOrWhiteSpace(pageHost) || string.IsNullOrWhiteSpace(reqHost))
                return false;

            return !RegistrableDomain(pageHost).Equals(RegistrableDomain(reqHost), StringComparison.OrdinalIgnoreCase);
        }


        private bool IsWhitelisted(string host)
        {
            if (string.IsNullOrWhiteSpace(host)) return false;
            if (_adBlockWhitelist.Contains(host)) return true;

            var parts = host.Split('.');
            for (int i = 1; i < parts.Length - 1; i++)
            {
                var suffix = string.Join(".", parts.Skip(i));
                if (_adBlockWhitelist.Contains(suffix)) return true;
            }

            return false;
        }

        private bool IsPopupWhitelisted(string host)
        {
            if (string.IsNullOrWhiteSpace(host)) return false;
            if (_popupWhitelist.Contains(host)) return true;

            var parts = host.Split('.');
            for (int i = 1; i < parts.Length - 1; i++)
            {
                var suffix = string.Join(".", parts.Skip(i));
                if (_popupWhitelist.Contains(suffix)) return true;
            }

            return false;
        }

        private static string GetHostFromUrl(string? url)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(url)) return "";
                return new Uri(url).Host ?? "";
            }
            catch
            {
                return "";
            }
        }

        private bool IsPopupStorm(string openerUrl, string popupUrl)
        {
            // Trusted login/payment/government popups can open quickly during sign-in.
            // Let them pass before applying scam-style popup storm checks.
            if (IsTrustedLoginFlowPair(openerUrl, popupUrl))
                return false;

            string openerHost = GetHostFromUrl(openerUrl).Replace("www.", "").ToLowerInvariant();
            string popupHost = GetHostFromUrl(popupUrl).Replace("www.", "").ToLowerInvariant();

            string key = string.IsNullOrWhiteSpace(openerHost)
                ? popupHost
                : openerHost;

            if (string.IsNullOrWhiteSpace(key))
                return false;

            DateTime now = DateTime.UtcNow;

            if (!_popupStormTracker.TryGetValue(key, out var times))
            {
                times = new List<DateTime>();
                _popupStormTracker[key] = times;
            }

            // Keep only popup attempts in the last 6 seconds.
            times.RemoveAll(t => (now - t).TotalSeconds > 6);
            times.Add(now);

            // 3 popup attempts in 6 seconds = popup storm.
            return times.Count >= 3;
        }

        private bool IsRedirectStorm(string targetUrl)
        {
            // Government, banking, Microsoft, PayPal, Stripe and identity-login flows
            // can legitimately bounce through several trusted URLs quickly.
            // Do not treat those as scam-style redirect storms.
            if (IsTrustedLoginFlowUrl(targetUrl))
                return false;

            string host = GetHostFromUrl(targetUrl).Replace("www.", "").ToLowerInvariant();

            if (string.IsNullOrWhiteSpace(host))
                return false;

            DateTime now = DateTime.UtcNow;

            if (!_redirectStormTracker.TryGetValue(host, out var times))
            {
                times = new List<DateTime>();
                _redirectStormTracker[host] = times;
            }

            // Keep only navigation attempts in the last 8 seconds.
            times.RemoveAll(t => (now - t).TotalSeconds > 8);
            times.Add(now);

            // 6 navigations to same host in 8 seconds = suspicious redirect behaviour.
            return times.Count >= 6;
        }

        private bool ShouldAllowPopup(string popupUrl, string openerUrl, bool isUserInitiated = false)
        {
            string popupHost = GetHostFromUrl(popupUrl).Replace("www.", "").ToLowerInvariant();
            string openerHost = GetHostFromUrl(openerUrl).Replace("www.", "").ToLowerInvariant();

            if (string.IsNullOrWhiteSpace(popupHost))
                return false;

            // Manual whitelist always wins.
            if (IsPopupWhitelisted(popupHost))
                return true;

            if (!string.IsNullOrWhiteSpace(openerHost) && IsPopupWhitelisted(openerHost))
                return true;

            // Trusted login/payment/government handoffs should be allowed.
            // Examples: MyGov -> ATO, Microsoft sign-in, PayPal checkout.
            if (IsTrustedLoginFlowPair(openerUrl, popupUrl))
                return true;

            // Stage 4C.2 - Smart Compatibility / Popup Control bridge.
            // If the customer has deliberately enabled Smart Compatibility for
            // the opener site, allow only user-initiated new-window requests even
            // when global Popup Control is set to Block All. Automatic popups are
            // still blocked. Built-in AI compatibility gets the same treatment so
            // deliberate sign-in/account buttons can work without weakening other sites.
            bool compatibilityPopup =
                isUserInitiated &&
                (IsTemporaryCompatibilityHost(openerUrl) ||
                 IsBuiltInAiCompatibilityHost(openerUrl));

            if (compatibilityPopup)
                return true;

            switch (_popupMode)
            {
                case PopupMode.AllowAll:
                    return true;

                case PopupMode.BlockAll:
                    return false;

                case PopupMode.Smart:
                default:
                    // Block obvious ad/tracker popup destinations.
                    if (IsObviousAdOrTrackerHost(popupHost))
                        return false;

                    // Same-site popups are often login, checkout, auth, or account flows.
                    if (!string.IsNullOrWhiteSpace(openerHost) &&
                        string.Equals(popupHost, openerHost, StringComparison.OrdinalIgnoreCase))
                        return true;

                    // Same parent-domain flows, e.g. accounts.google.com from google.com.
                    if (!string.IsNullOrWhiteSpace(openerHost) &&
                        (popupHost.EndsWith("." + openerHost, StringComparison.OrdinalIgnoreCase) ||
                         openerHost.EndsWith("." + popupHost, StringComparison.OrdinalIgnoreCase)))
                        return true;

                    // Allow common login/payment/auth flows.
                    if (popupHost.Contains("accounts.google.") ||
                        popupHost.Contains("login.microsoftonline.") ||
                        popupHost.Contains("login.live.") ||
                        popupHost.Contains("appleid.apple.") ||
                        popupHost.Contains("paypal.") ||
                        popupHost.Contains("stripe.") ||
                        popupHost.Contains("checkout.") ||
                        popupHost.Contains("auth.") ||
                        popupHost.Contains("signin.") ||
                        popupHost.Contains("login."))
                        return true;

                    // If the user clicked something, allow non-tracker popups.
                    // This keeps normal websites working without allowing automatic junk popups.
                    if (isUserInitiated)
                        return true;

                    // Search engines often open clicked results through redirects.
                    bool openerIsSearch =
                        openerHost.Contains("startpage") ||
                        openerHost.Contains("google.") ||
                        openerHost.Contains("bing.") ||
                        openerHost.Contains("yahoo.") ||
                        openerHost.Contains("duckduckgo.") ||
                        openerHost.Contains("brave.") ||
                        openerHost.Contains("qwant.");

                    if (openerIsSearch)
                        return true;

                    // Anything automatic and cross-site gets blocked in Smart Mode.
                    return false;
            }
        }

        private bool IsTemporaryCompatibilityHost(string pageUrl)
        {
            var host = GetHost(pageUrl);
            if (string.IsNullOrWhiteSpace(host))
                return false;

            host = host.Replace("www.", "").ToLowerInvariant();

            return _temporaryCompatibilityHosts.Contains(host);
        }

        // ============================================================
        // STAGE 4B.1 - BUILT-IN AI COMPATIBILITY
        // ============================================================
        // Claude and Gemini were confirmed to render correctly when the customer
        // manually enabled Smart Compatibility. Apply that same conservative
        // compatibility path automatically only while one of those AI pages is
        // active. This does NOT add the site to the customer's saved Compatibility
        // List and does NOT weaken protection for unrelated websites.
        private bool IsBuiltInAiCompatibilityHost(string pageUrl)
        {
            var host = NormalizeHostForCompatibility(GetHost(pageUrl));

            if (string.IsNullOrWhiteSpace(host))
                return false;

            return host.Equals("claude.ai", StringComparison.OrdinalIgnoreCase) ||
                   host.EndsWith(".claude.ai", StringComparison.OrdinalIgnoreCase) ||
                   host.Equals("gemini.google.com", StringComparison.OrdinalIgnoreCase);
        }

        private bool IsBlockedHost(string host)
        {
            if (string.IsNullOrWhiteSpace(host)) return false;

            host = host.Trim().TrimEnd('.').ToLowerInvariant();

            // Stage 2N.7:
            // Do not let a coarse host-only protection list globally disable shared
            // authentication, maps/location, font or CDN infrastructure.
            if (IsSharedFunctionalInfrastructureHost(host))
                return false;

            if (_blockedHosts.Contains(host)) return true;

            var parts = host.Split('.');
            for (int i = 1; i < parts.Length - 1; i++)
            {
                var suffix = string.Join(".", parts.Skip(i));
                if (_blockedHosts.Contains(suffix))
                {
                    // A parent-domain entry must not accidentally override a known
                    // functional subdomain carve-out.
                    if (IsSharedFunctionalInfrastructureHost(host))
                        return false;

                    return true;
                }
            }

            return false;
        }

        private string BuildWebResourceDecisionCacheKey(
    PrivacyMode mode,
    string pageHost,
    string reqHost,
    CoreWebView2WebResourceContext ctx)
        {
            string page = (pageHost ?? "").Replace("www.", "").ToLowerInvariant();
            string request = (reqHost ?? "").Replace("www.", "").ToLowerInvariant();

            return $"{mode}|{page}|{request}|{ctx}";
        }

        private bool TryGetCachedWebResourceBlockDecision(string key, out bool shouldBlock)
        {
            shouldBlock = false;

            if (string.IsNullOrWhiteSpace(key))
                return false;

            return _webResourceBlockDecisionCache.TryGetValue(key, out shouldBlock);
        }

        private void SetCachedWebResourceBlockDecision(string key, bool shouldBlock)
        {
            if (string.IsNullOrWhiteSpace(key))
                return;

            if (_webResourceBlockDecisionCache.Count > MaxWebResourceBlockDecisionCacheSize)
                _webResourceBlockDecisionCache.Clear();

            _webResourceBlockDecisionCache[key] = shouldBlock;
        }

        private void ClearWebResourceDecisionCache()
        {
            try
            {
                _webResourceBlockDecisionCache.Clear();
            }
            catch { }
        }

        private bool ShouldRunPageHelpers(CoreWebView2 core)
        {
            try
            {
                string url = core?.Source ?? "";

                if (string.IsNullOrWhiteSpace(url))
                    return false;

                if (url.Equals("about:blank", StringComparison.OrdinalIgnoreCase) ||
                    url.Equals("lexwhite://newtab", StringComparison.OrdinalIgnoreCase))
                    return false;

                // Ignore URL fragments so scrolling within the same page does not retrigger helpers.
                int hashIndex = url.IndexOf('#');
                if (hashIndex >= 0)
                    url = url.Substring(0, hashIndex);

                var now = DateTime.UtcNow;

                if (_pageHelperLastRunUtc.TryGetValue(url, out DateTime lastRun) &&
                    now - lastRun < PageHelperCooldown)
                {
                    return false;
                }

                if (_pageHelperLastRunUtc.Count > 300)
                    _pageHelperLastRunUtc.Clear();

                _pageHelperLastRunUtc[url] = now;
                return true;
            }
            catch
            {
                return true;
            }
        }

        private void ResetProtectionCountsForPage(int pageIndex)
        {
            try
            {
                if (pageIndex < 0 || pageIndex >= 4)
                    return;

                _blockedTrackerCounts[pageIndex] = 0;
                _blockedAdCounts[pageIndex] = 0;
                _statusWarnings[pageIndex] = false;
                _statusMessages[pageIndex] = "Secure";
            }
            catch { }
        }

        private void EnableAdBlockOn(WebView2 wv)
        {
            if (wv?.CoreWebView2 == null) return;

            // Speed Recovery:
            // Do not hook CoreWebView2WebResourceContext.All.
            // That makes LexDesk Pro inspect almost every page resource.
            // These contexts still cover the useful ad/tracker cases without
            // dragging every single request through our code.
            CoreWebView2WebResourceContext[] filteredContexts =
            {
        CoreWebView2WebResourceContext.Script,
        CoreWebView2WebResourceContext.XmlHttpRequest,
        CoreWebView2WebResourceContext.Fetch,
        CoreWebView2WebResourceContext.Image,
        CoreWebView2WebResourceContext.Media,
        CoreWebView2WebResourceContext.Stylesheet,
        CoreWebView2WebResourceContext.Font,
        CoreWebView2WebResourceContext.Other
    };

            foreach (var ctx in filteredContexts)
            {
                try
                {
                    wv.CoreWebView2.AddWebResourceRequestedFilter("*", ctx);
                }
                catch
                {
                    // Ignore duplicate/unsupported filter registration.
                }
            }

            wv.CoreWebView2.WebResourceRequested += (s, e) =>
            {
                var reqUrl = e.Request?.Uri;
                if (string.IsNullOrWhiteSpace(reqUrl)) return;

                var pageUrl = "";
                try { pageUrl = wv.CoreWebView2.Source ?? ""; } catch { }

                RecordSiteDiagnosticRequest(pageUrl, reqUrl, e.ResourceContext);

                if (!_adBlockEnabled) return;
                if (_privacyMode == PrivacyMode.Off) return;

                var pageHost = GetHost(pageUrl);
                var reqHost = GetHost(reqUrl);

                bool manualCompatibility = IsTemporaryCompatibilityHost(pageUrl);
                bool builtInAiCompatibility = IsBuiltInAiCompatibilityHost(pageUrl);
                bool smartCompatibility = manualCompatibility || builtInAiCompatibility;

                if (smartCompatibility)
                {
                    _compatibilityModeActive[_activePageIndex] = true;
                    _compatibilityModeLabels[_activePageIndex] = builtInAiCompatibility
                        ? "AI Compatibility"
                        : "Smart Compatibility";
                }

                if (string.IsNullOrWhiteSpace(reqHost)) return;

                // A full-site whitelist is an explicit customer instruction to stop
                // filtering this site's network traffic. Keep this above Smart
                // Compatibility so Whitelist really means Whitelist.
                if (!string.IsNullOrWhiteSpace(pageHost) && IsWhitelisted(pageHost))
                    return;

                var ctx = e.ResourceContext;

                // Never block the main page document itself
                if (ctx == CoreWebView2WebResourceContext.Document)
                    return;

                // Compatibility-sensitive site handling follows below.
                // Smart Compatibility is handled generically before the normal privacy-mode cache.

                bool thirdParty = IsThirdParty(pageUrl, reqUrl);

                // Speed Recovery:
                // First-party resources are normally required for the page to work.
                // Let them through before host-list, tracker-context, and compatibility checks.
                if (!thirdParty)
                    return;

                // Stage 2N.7 - functional infrastructure safeguard.
                // The diagnostic run showed legitimate dealer/location and sign-in support
                // being caught by coarse host-level rules on shared services. Allow only
                // narrowly identified functional infrastructure here; ad/analytics hosts
                // such as DoubleClick and Google Analytics are not part of this exception.
                if (IsEssentialThirdPartyInfrastructureRequest(reqUrl, reqHost, ctx))
                    return;

                // Stage 7.1 - 7plus ad-media separation.
                // Do not blanket-block Seven/Akamai/Brightcove playback infrastructure.
                // The diagnostic run identified Google 2mdn Media/Image requests as
                // the advertising media path, so return an empty success response only
                // for those ad assets and let the programme continue.
                if (IsSevenPlusAdMediaRequest(pageUrl, reqHost, ctx))
                {
                    BlockAdMediaWithNoContent(wv, e, "7plus-2mdn-ad-media");
                    return;
                }

                // Generic Smart Compatibility - Stage 2J:
                // 1. Stop high-confidence advertising/tracker requests first.
                // 2. Allow login/session requests and modern streaming playback plumbing.
                // 3. Keep blocking known tracker-style requests where doing so is unlikely
                //    to damage the site's essential functionality.
                if (smartCompatibility)
                {
                    bool compatibilityKnownBad = IsBlockedHost(reqHost);
                    bool compatibilityTrackerContext =
                        IsLikelyTrackerContext(ctx) ||
                        ctx == CoreWebView2WebResourceContext.Fetch ||
                        ctx == CoreWebView2WebResourceContext.Other;

                    // Important: advertising is checked BEFORE the blanket Media allowance.
                    // Otherwise a video ad served in the Media context would sail straight through.
                    if (IsHighConfidenceAdvertisingRequest(reqUrl, reqHost))
                    {
                        BlockRequest(wv, e, "smart-compat-high-confidence-ad");
                        return;
                    }

                    if (IsCompatibilityEssentialRequest(reqUrl, ctx) ||
                        IsStreamingPlaybackEssentialRequest(reqUrl, ctx))
                    {
                        return;
                    }

                    // Known bad hosts can also serve display ads/images. Block those in
                    // Smart Compatibility, but leave styles/fonts and ordinary site resources alone.
                    bool compatibilityBlockableContext =
                        compatibilityTrackerContext ||
                        ctx == CoreWebView2WebResourceContext.Image;

                    if (compatibilityKnownBad && compatibilityBlockableContext)
                    {
                        BlockRequest(wv, e, "smart-compat-known-bad");
                        return;
                    }

                    return;
                }

                string cacheKey = BuildWebResourceDecisionCacheKey(_privacyMode, pageHost ?? "", reqHost ?? "", ctx);

                if (TryGetCachedWebResourceBlockDecision(cacheKey, out bool cachedShouldBlock))
                {
                    if (cachedShouldBlock)
                        BlockRequest(wv, e, "cached-block-decision");

                    return;
                }

                bool knownBad = IsBlockedHost(reqHost ?? "");
                bool trackerContext = IsLikelyTrackerContext(ctx);
                bool safeMedia = IsSafeMediaContext(ctx);

                bool compatibilitySensitive = IsCompatibilitySensitiveSite(pageUrl);
                string compatibilityLabel = GetCompatibilityProfileLabel(pageUrl);

                if (compatibilitySensitive)
                {
                    _compatibilityModeActive[_activePageIndex] = true;
                    _compatibilityModeLabels[_activePageIndex] = compatibilityLabel;

                    // YouTube: allow essential playback infrastructure,
                    // but still block obvious ad/tracker hosts.
                    if (compatibilityLabel == "YouTube")
                    {
                        if (IsYouTubeEssentialRequest(pageUrl, reqUrl))
                            return;

                        if (thirdParty && IsObviousAdOrTrackerHost(reqHost))
                        {
                            BlockRequest(wv, e, "youtube-obvious-ad-or-tracker");
                            return;
                        }

                        return;
                    }

                    // Banking / Government / Payments:
                    // use gentle filtering instead of full bypass.
                    // Only block known bad third-party tracker-style requests.
                    if (thirdParty && knownBad && trackerContext && !safeMedia)
                    {
                        BlockRequest(wv, e, "compatibility-sensitive-known-bad");
                        return;
                    }

                    return;
                }

                // Lightweight tracker URL heuristics
                string lowerUrl = reqUrl.ToLowerInvariant();
                bool suspiciousTrackerUrl =
                    lowerUrl.Contains("/collect") ||
                    lowerUrl.Contains("/analytics") ||
                    lowerUrl.Contains("/tracking") ||
                    lowerUrl.Contains("/tracker") ||
                    lowerUrl.Contains("/telemetry") ||
                    lowerUrl.Contains("/metrics") ||
                    lowerUrl.Contains("/pixel") ||
                    lowerUrl.Contains("utm_") ||
                    lowerUrl.Contains("fbclid=") ||
                    lowerUrl.Contains("gclid=");

                switch (_privacyMode)
                {
                    case PrivacyMode.Balanced:
                        // Balanced / Recommended:
                        // Stop high-confidence advertising first, then the protection
                        // host list. Unknown third-party functionality is still allowed.
                        if (IsHighConfidenceAdvertisingRequest(reqUrl, reqHost ?? ""))
                        {
                            SetCachedWebResourceBlockDecision(cacheKey, true);
                            BlockRequest(wv, e, "balanced-high-confidence-ad");
                            return;
                        }

                        if (knownBad)
                        {
                            SetCachedWebResourceBlockDecision(cacheKey, true);
                            BlockRequest(wv, e, "balanced-known-bad");
                            return;
                        }

                        SetCachedWebResourceBlockDecision(cacheKey, false);
                        return;

                    case PrivacyMode.TrackingOnly:
                        // Tracking Only:
                        // Focus on third-party tracking behavior, but avoid breaking media-rich pages.
                        if ((knownBad || suspiciousTrackerUrl) && trackerContext && !safeMedia)
                        {
                            SetCachedWebResourceBlockDecision(cacheKey, true);
                            BlockRequest(wv, e, "tracking-only-known-or-suspicious");
                            return;
                        }

                        SetCachedWebResourceBlockDecision(cacheKey, false);
                        return;

                    case PrivacyMode.Strict:
                        // Stage 4C.5 - Strict Compatibility Recovery.
                        //
                        // Older Strict logic treated every unknown third-party Script/XHR
                        // as tracking purely because of its resource context. Modern sites
                        // commonly load legitimate APIs, configurators, sign-in plumbing,
                        // product data and feature scripts from a different registrable
                        // domain. Blocking those unknown functional requests caused long
                        // retries and broken pages on complex sites.
                        //
                        // Strict remains aggressive against evidence-based tracking:
                        //   1. high-confidence advertising/tracker destinations;
                        //   2. hosts in the protection block list;
                        //   3. URLs carrying explicit tracker/telemetry patterns.
                        //
                        // An unknown third-party Script/XHR is no longer blocked merely
                        // because it is third-party.
                        if (IsHighConfidenceAdvertisingRequest(reqUrl, reqHost ?? ""))
                        {
                            SetCachedWebResourceBlockDecision(cacheKey, true);
                            BlockRequest(wv, e, "strict-high-confidence-ad");
                            return;
                        }

                        if (knownBad && !safeMedia)
                        {
                            SetCachedWebResourceBlockDecision(cacheKey, true);
                            BlockRequest(wv, e, "strict-known-bad-host");
                            return;
                        }

                        if (suspiciousTrackerUrl && trackerContext && !safeMedia)
                        {
                            SetCachedWebResourceBlockDecision(cacheKey, true);
                            BlockRequest(wv, e, "strict-suspicious-tracker-url");
                            return;
                        }

                        SetCachedWebResourceBlockDecision(cacheKey, false);
                        return;

                    default:
                        SetCachedWebResourceBlockDecision(cacheKey, false);
                        return;
                }
            };
        }

        private void BlockAdMediaWithNoContent(
            WebView2 wv,
            CoreWebView2WebResourceRequestedEventArgs e,
            string reason)
        {
            try
            {
                var reqUrl = e.Request?.Uri ?? "";
                string pageUrl = "";
                try { pageUrl = wv.CoreWebView2.Source ?? ""; } catch { }

                RecordSiteDiagnosticBlock(pageUrl, reqUrl, e.ResourceContext);

                if (_siteDiagnosticMode)
                {
                    AddSiteDiagnosticEventForPage(
                        pageUrl,
                        $"BLOCK request={GetSiteDiagnosticHost(reqUrl)} context={e.ResourceContext} reason={reason} response=204");
                }

                _blockedAdCounts[_activePageIndex]++;

                var env = wv.CoreWebView2.Environment;
                e.Response = env.CreateWebResourceResponse(
                    null, 204, "No Content", "Content-Type: text/plain");

                _statusMessages[_activePageIndex] = "Tracking / ad activity blocked";
                _statusWarnings[_activePageIndex] = false;
            }
            catch { }
        }

        private void BlockRequest(
            WebView2 wv,
            CoreWebView2WebResourceRequestedEventArgs e,
            string reason = "unspecified")
        {
            try
            {
                var reqUrl = e.Request?.Uri ?? "";
                var reqHost = GetHost(reqUrl)?.ToLowerInvariant() ?? "";
                var lowerUrl = reqUrl.ToLowerInvariant();

                string pageUrl = "";
                try { pageUrl = wv.CoreWebView2.Source ?? ""; } catch { }

                RecordSiteDiagnosticBlock(pageUrl, reqUrl, e.ResourceContext);

                if (_siteDiagnosticMode)
                {
                    AddSiteDiagnosticEventForPage(
                        pageUrl,
                        $"BLOCK request={GetSiteDiagnosticHost(reqUrl)} context={e.ResourceContext} reason={reason}");
                }

                bool looksLikeAd =
                    reqHost.Contains("doubleclick") ||
                    reqHost.Contains("googlesyndication") ||
                    reqHost.Contains("adservice") ||
                    lowerUrl.Contains("/ads") ||
                    lowerUrl.Contains("adformat=") ||
                    lowerUrl.Contains("advert");

                bool looksLikeTracker =
                    reqHost.Contains("analytics") ||
                    reqHost.Contains("googletagmanager") ||
                    reqHost.Contains("facebook") ||
                    reqHost.Contains("hotjar") ||
                    lowerUrl.Contains("/collect") ||
                    lowerUrl.Contains("/tracking") ||
                    lowerUrl.Contains("/tracker") ||
                    lowerUrl.Contains("/telemetry") ||
                    lowerUrl.Contains("/metrics") ||
                    lowerUrl.Contains("/pixel") ||
                    lowerUrl.Contains("utm_") ||
                    lowerUrl.Contains("fbclid=") ||
                    lowerUrl.Contains("gclid=");

                if (looksLikeAd && !looksLikeTracker)
                    _blockedAdCounts[_activePageIndex]++;
                else
                    _blockedTrackerCounts[_activePageIndex]++;

                var env = wv.CoreWebView2.Environment;

                e.Response = env.CreateWebResourceResponse(
                    null, 403, "Blocked", "Content-Type: text/plain");

                // Speed Recovery:
                // Do not refresh the status dot for every single blocked request.
                // Counts are still updated above. The status popup will show the totals.
                // Constant UI refresh during noisy page loads can slow browsing.
                _statusMessages[_activePageIndex] = "Tracking / ad activity blocked";
                _statusWarnings[_activePageIndex] = false;
            }
            catch { }
        }

        private string GetFirstRunFlagPath()
        {
            Directory.CreateDirectory(AppDataFolder);
            return AppDataPath("firstrun.flag");
        }

        private bool IsFirstRun()
        {
            return !File.Exists(GetFirstRunFlagPath());
        }

        private void MarkFirstRunComplete()
        {
            try
            {
                File.WriteAllText(GetFirstRunFlagPath(), "shown");
            }
            catch
            {
                // Ignore file write errors so the app never crashes over onboarding.
            }
        }

