        private void ApplySafeStartupWindowSize()
        {
            var workArea = SystemParameters.WorkArea;

            Width = Math.Min(1400, workArea.Width * 0.92);
            Height = Math.Min(900, workArea.Height * 0.92);

            Left = workArea.Left + (workArea.Width - Width) / 2;
            Top = workArea.Top + (workArea.Height - Height) / 2;

            MinWidth = Math.Min(1100, workArea.Width * 0.95);
            MinHeight = Math.Min(700, workArea.Height * 0.95);
        }

        private void MainWindow_Loaded(object sender, RoutedEventArgs e)
        {
            RefreshUpdateVisuals();
            _ = CheckForUpdatesAsync(false);

            if (IsFirstRun())
            {
                MarkFirstRunComplete();
                ShowWelcomeGuide();
            }
        }

