        private string GetAppVersion()
        {
            try
            {
                var packageVersion = Windows.ApplicationModel.Package.Current.Id.Version;

                return $"{packageVersion.Major}." +
                       $"{packageVersion.Minor}." +
                       $"{packageVersion.Build}." +
                       $"{packageVersion.Revision}";
            }
            catch
            {
                var assemblyVersion =
                    Assembly.GetExecutingAssembly().GetName().Version;

                return assemblyVersion?.ToString() ?? "0.0.0.0";
            }
        }

        private void RefreshUpdateVisuals(string? status = null)
        {
            try
            {
                string installedVersion = GetAppVersion();

                if (AppVersionText != null)
                {
                    AppVersionText.Text = installedVersion;
                    AppVersionText.Visibility = Visibility.Visible;
                }

                string effectiveStatus =
                    !string.IsNullOrWhiteSpace(status)
                        ? status
                        : !LexDeskUpdatesEnabled
                            ? "Update channel not connected yet"
                            : _isLatestUpdate
                                ? "You are up to date"
                                : "An update is available";

                if (UpdateStatusText != null)
                {
                    UpdateStatusText.Text = effectiveStatus;
                    UpdateStatusText.Visibility = Visibility.Visible;
                }

                if (UpdateAppButton != null)
                {
                    if (!LexDeskUpdatesEnabled)
                    {
                        UpdateAppButton.IsEnabled = false;
                        UpdateAppButton.Content = "Update App";
                    }
                    else
                    {
                        UpdateAppButton.IsEnabled = !_isLatestUpdate;
                        UpdateAppButton.Content =
                            _isLatestUpdate
                                ? "Up to Date"
                                : "Update App";
                    }
                }

                // Easy-update controls.
                // Only show these when a newer version is actually available.
                if (ToolbarUpdateButton != null)
                {
                    ToolbarUpdateButton.Visibility =
                        _isLatestUpdate
                            ? Visibility.Collapsed
                            : Visibility.Visible;

                    ToolbarUpdateButton.IsEnabled = !_isLatestUpdate;
                }

                if (StatusPopupUpdateButton != null)
                {
                    StatusPopupUpdateButton.Visibility =
                        _isLatestUpdate
                            ? Visibility.Collapsed
                            : Visibility.Visible;

                    StatusPopupUpdateButton.IsEnabled = !_isLatestUpdate;
                }
            }
            catch
            {
                // Update information must never affect the rest of the app.
            }
        }

        private async Task CheckForUpdatesAsync(bool showResultMessage = false)
        {
            if (!LexDeskUpdatesEnabled)
            {
                _isLatestUpdate = true;
                _latestDownloadUrl = "";

                RefreshUpdateVisuals("Update channel not connected yet");

                if (UpdateAppButton != null)
                    UpdateAppButton.IsEnabled = false;

                if (showResultMessage)
                {
                    ShowLexDeskMessageBox(
                        "LexDesk Pro updates are not available yet.\n\n" +
                        "This early LexDesk Pro build does not use a public update channel yet.",
                        "LexDesk Pro Updates",
                        MessageBoxButton.OK,
                        MessageBoxImage.Information);
                }

                UpdateSecurityStatus("LexDesk Pro updates are not available yet", false);
                return;
            }

            try
            {
                RefreshUpdateVisuals("Checking for updates...");

                using var http = new HttpClient();
                http.Timeout = TimeSpan.FromSeconds(10);

                var json = await http.GetStringAsync(UpdateManifestUrl);
                var manifest = System.Text.Json.JsonSerializer.Deserialize<UpdateManifest>(
                    json,
                    JsonCaseInsensitiveOptions);

                if (manifest == null || string.IsNullOrWhiteSpace(manifest.version))
                {
                    _isLatestUpdate = true;
                    RefreshUpdateVisuals("Could not read update information");

                    if (showResultMessage)
                    {
                        ShowLexDeskMessageBox(
                            "Could not read update information.",
                            "App Updates",
                            MessageBoxButton.OK,
                            MessageBoxImage.Warning);
                    }

                    return;
                }

                var localRaw = GetAppVersion();
                var remoteRaw = manifest.version.Trim();

                var localClean = localRaw.StartsWith("v", StringComparison.OrdinalIgnoreCase) ? localRaw[1..] : localRaw;
                var remoteClean = remoteRaw.StartsWith("v", StringComparison.OrdinalIgnoreCase) ? remoteRaw[1..] : remoteRaw;

                if (!Version.TryParse(localClean, out var localVersion))
                    localVersion = new Version(0, 0, 0);

                if (!Version.TryParse(remoteClean, out var remoteVersion))
                    remoteVersion = localVersion;

                _latestDownloadUrl = string.IsNullOrWhiteSpace(manifest.downloadUrl)
                    ? "https://github.com/mickwhite1973/LexDesk-Pro/releases/latest"
                    : manifest.downloadUrl;

                _isLatestUpdate = remoteVersion <= localVersion;

                if (_isLatestUpdate)
                {
                    RefreshUpdateVisuals($"You are up to date ({localVersion})");

                    if (StatusPopupUpdateText != null)
                        StatusPopupUpdateText.Text = "Up to date";

                    if (UpdateAppButton != null)
                    {
                        UpdateAppButton.IsEnabled = false;
                        UpdateAppButton.Visibility = Visibility.Hidden;
                    }

                    if (showResultMessage)
                    {
                        ShowLexDeskMessageBox(
                            $"LexDesk Pro is up to date.\n\nInstalled version: {localVersion}",
                            "App Updates",
                            MessageBoxButton.OK,
                            MessageBoxImage.Information);
                    }
                }
                else
                {
                    RefreshUpdateVisuals($"Update available: {remoteVersion}");

                    if (StatusPopupUpdateText != null)
                        StatusPopupUpdateText.Text = $"Available: {remoteVersion}";

                    if (UpdateAppButton != null)
                    {
                        UpdateAppButton.IsEnabled = true;
                        UpdateAppButton.Visibility = Visibility.Visible;
                    }

                    if (showResultMessage)
                    {
                        ShowLexDeskMessageBox(
                            $"Update available.\n\nInstalled version: {localVersion}\nLatest version: {remoteVersion}",
                            "App Updates",
                            MessageBoxButton.OK,
                            MessageBoxImage.Information);
                    }
                }
            }
            catch (Exception ex)
            {
                _isLatestUpdate = true;
                RefreshUpdateVisuals("Update check failed");

                if (StatusPopupUpdateText != null)
                    StatusPopupUpdateText.Text = "Check failed";

                if (showResultMessage)
                {
                    ShowLexDeskMessageBox(
    "Could not check for updates.\n\n" + SanitizeExceptionMessage(ex),
    "App Updates",
    MessageBoxButton.OK,
    MessageBoxImage.Warning);
                }
            }
        }

        private void ApplyPrivacyRelayControlVisibility()
        {
            // v1.0.20.0:
            // Privacy Relay / Hide IP backend is being prepared, but the customer UI is hidden
            // until the service is live. This keeps the Privacy popup clean on small screens.
            if (PrivacyNetworkSection != null)
                PrivacyNetworkSection.Visibility = Visibility.Collapsed;

            if (HideIpButton != null)
            {
                HideIpButton.Visibility = Visibility.Collapsed;
                HideIpButton.IsEnabled = false;
            }

            if (ChangeLocationButton != null)
            {
                ChangeLocationButton.Visibility = Visibility.Collapsed;
                ChangeLocationButton.IsEnabled = false;
            }

            if (PrivacyRelayComingSoonButton != null)
            {
                PrivacyRelayComingSoonButton.Visibility = Visibility.Collapsed;
                PrivacyRelayComingSoonButton.IsEnabled = false;
            }

            if (ActivationNotesButton != null)
            {
                ActivationNotesButton.Visibility = Visibility.Collapsed;
                ActivationNotesButton.IsEnabled = false;
            }
        }

        private void RefreshPrivacyNetworkVisuals()
        {
            if (PrivacyRelayPublicComingSoonOnly)
            {
                if (HideIpButton != null)
                {
                    HideIpButton.Visibility = PrivacyRelayDeveloperMode ? Visibility.Visible : Visibility.Collapsed;
                    HideIpButton.IsEnabled = PrivacyRelayDeveloperMode;
                }

                if (ChangeLocationButton != null)
                {
                    ChangeLocationButton.Visibility = PrivacyRelayDeveloperMode ? Visibility.Visible : Visibility.Collapsed;
                    ChangeLocationButton.IsEnabled = PrivacyRelayDeveloperMode;
                }

                if (PrivacyRelayPublicComingSoonOnly)
                {
                    if (PrivacyRelayComingSoonButton != null)
                    {
                        PrivacyRelayComingSoonButton.Content = "Privacy Relay: Coming Soon";
                        PrivacyRelayComingSoonButton.ToolTip =
                            "Privacy Relay is being prepared for a future update.";
                    }

                    ApplyPrivacyRelayControlVisibility();

                    if (PrivacyNetworkStatusText != null)
                    {
                        PrivacyNetworkStatusText.Text =
                            "Privacy Relay is being prepared for a future update. It is not active in this version.";
                    }

                    return;
                }


            }

            // V2 relay safety:
            // Only the Protected state is allowed to set Hide IP / Privacy Relay as active.
            // Checking, RestartRequired, Failed, and NotConnected must all remain honest.
            _hideIpEnabled = _privacyRelayState == PrivacyRelayState.Protected;

            string selectedLocation = GetSelectedPrivacyRelayLocation();

            string activeRelayLocation = selectedLocation;

            if (_privacyRelayActiveStartupConfig != null &&
                !string.IsNullOrWhiteSpace(_privacyRelayActiveStartupConfig.Location))
            {
                activeRelayLocation = _privacyRelayActiveStartupConfig.Location;
            }

            string confirmedIpLine = string.IsNullOrWhiteSpace(_privacyRelayLastConfirmedIp)
                ? ""
                : $"\nConfirmed public IP: {_privacyRelayLastConfirmedIp}";

            string lastCheckStatusLine = string.IsNullOrWhiteSpace(_privacyRelayLastCheckStatus)
                ? ""
                : $"\nLast check status: {_privacyRelayLastCheckStatus}";

            string relayButtonText;
            string relayToolTip;
            string statusText;

            switch (_privacyRelayState)
            {
                case PrivacyRelayState.Connecting:
                    {
                        relayButtonText = "Privacy Relay: Connecting";
                        relayToolTip =
                            "LexDesk Pro is preparing the Privacy Relay connection.\n" +
                            "Protection is not active yet.";
                        statusText =
                            "Privacy Relay is connecting.\n" +
                            $"Selected relay location: {selectedLocation}\n" +
                            "Your browsing is still using your normal internet connection until protection is confirmed.";
                        break;
                    }

                case PrivacyRelayState.RestartRequired:
                    {
                        relayButtonText = "Privacy Relay: Restart Required";
                        relayToolTip =
                            "Privacy Relay has been prepared.\n" +
                            "Restart LexDesk Pro to apply the app-only relay connection.";
                        statusText =
                            "Privacy Relay is prepared but not active yet.\n" +
                            $"Relay location: {selectedLocation}\n" +
                            "Restart LexDesk Pro to apply the relay connection.\n" +
                            "Until restart, your browsing is still using your normal internet connection.";
                        break;
                    }

                case PrivacyRelayState.Checking:
                    {
                        relayButtonText = "Privacy Relay: Checking";
                        relayToolTip =
                            "Privacy Relay startup settings were found.\n" +
                            "LexDesk Pro is checking whether the app-only relay is active.\n" +
                            "Protection is not confirmed yet.";
                        statusText =
                            "Privacy Relay is checking.\n" +
                            $"Relay location: {activeRelayLocation}\n" +
                            "Protection will not be shown until the public IP check passes." +
                            lastCheckStatusLine;
                        break;
                    }

                case PrivacyRelayState.Protected:
                    {
                        relayButtonText = "Privacy Relay: Protected";
                        relayToolTip =
                            "Privacy Relay has been confirmed.\n" +
                            "Browsing inside LexDesk Pro is using the selected relay connection.";
                        statusText =
                            "Privacy Relay is protected.\n" +
                            $"Relay location: {activeRelayLocation}" +
                            confirmedIpLine + "\n" +
                            "Browsing inside LexDesk Pro is using Privacy Relay.";
                        break;
                    }

                case PrivacyRelayState.Failed:
                    {
                        relayButtonText = "Privacy Relay: Failed";
                        relayToolTip =
                            "Privacy Relay could not be confirmed.\n" +
                            "Your browsing is using your normal internet connection.";
                        statusText =
                            "Privacy Relay could not be confirmed.\n" +
                            $"Selected relay location: {selectedLocation}" +
                            lastCheckStatusLine + "\n" +
                            "Your browsing is currently using your normal internet connection.";
                        break;
                    }

                case PrivacyRelayState.NotConnected:
                default:
                    {
                        relayButtonText = "Privacy Relay: Not Connected";
                        relayToolTip =
                            "Privacy Relay is off.\n" +
                            "Browsing is using your normal internet connection.";
                        statusText =
                            "Privacy Relay is not connected.\n" +
                            $"Selected relay location: {selectedLocation}\n" +
                            "Your browsing is currently using your normal internet connection.";
                        break;
                    }
            }

            if (HideIpButton != null)
            {
                HideIpButton.Content = relayButtonText;
                HideIpButton.ToolTip = relayToolTip;
            }

            if (ChangeLocationButton != null)
            {
                ChangeLocationButton.Content = $"Relay Location: {selectedLocation}";

                if (_privacyRelayState == PrivacyRelayState.Protected)
                {
                    ChangeLocationButton.ToolTip =
                        "Privacy Relay is currently protected.\n" +
                        "Disconnect Privacy Relay before changing the active relay location.";
                }
                else if (_privacyRelayState == PrivacyRelayState.Checking)
                {
                    ChangeLocationButton.ToolTip =
                        "Privacy Relay is currently checking.\n" +
                        "Cancel or wait for the check to finish before changing relay location.";
                }
                else
                {
                    ChangeLocationButton.ToolTip =
                        "Selected Privacy Relay location.\n" +
                        "Changing this location does not protect browsing until Privacy Relay is connected and confirmed.";
                }
            }

            if (PrivacyNetworkStatusText != null)
            {
                PrivacyNetworkStatusText.Text = statusText;
            }

            ApplyPrivacyRelayControlVisibility();
        }

