        private static bool IsLikelyTrackerContext(CoreWebView2WebResourceContext ctx) =>
            ctx == CoreWebView2WebResourceContext.Script ||
            ctx == CoreWebView2WebResourceContext.XmlHttpRequest;

        private static bool IsSafeMediaContext(CoreWebView2WebResourceContext ctx) =>
            ctx == CoreWebView2WebResourceContext.Image ||
            ctx == CoreWebView2WebResourceContext.Media ||
            ctx == CoreWebView2WebResourceContext.Stylesheet ||
            ctx == CoreWebView2WebResourceContext.Font;

        private void ActivatePane(int paneIndex)
        {
            if (paneIndex < 0 || paneIndex > 3) return;

            if (_paneState[paneIndex] != PaneLifeState.Normal)
                return;

            _paneLastActiveUtc[paneIndex] = DateTime.UtcNow;
            ResumePaneFromMemorySaver(paneIndex);

            // Prevent re-entrant focus events causing jitter / repeated activation
            if (_isActivatingPane) return;

            _isActivatingPane = true;
            try
            {
                if (_activePageIndex != paneIndex)
                {
                    _activePageIndex = paneIndex;
                    UpdatePageHostBorders();
                    UpdatePageModeButtonVisuals();
                    UpdateSecureSiteVisual();
                }

                // Focus the active web page (only if it doesn't already have focus)
                var web = GetWebView(paneIndex);
                if (web != null && !web.IsKeyboardFocusWithin)
                {
                    Dispatcher.BeginInvoke(new Action(() =>
                    {
                        try
                        {
                            web.Focus();
                            System.Windows.Input.Keyboard.Focus(web);
                        }
                        catch { }
                    }), System.Windows.Threading.DispatcherPriority.Input);
                }
            }
            finally
            {
                // Drop the guard after the current UI input cycle
                Dispatcher.BeginInvoke(new Action(() => _isActivatingPane = false),
                    System.Windows.Threading.DispatcherPriority.Background);
            }
        }


        private void SaveSessionState()
        {
            try
            {
                var state = new AppSessionState(
                    _pageUrls,
                    _activePageIndex,
                    _layoutPageCount
                );

                Directory.CreateDirectory(Path.GetDirectoryName(_sessionPath)!);

                var json = JsonSerializer.Serialize(state, JsonIndentedOptions);

                File.WriteAllText(_sessionPath, json);
            }
            catch { }
        }

        private bool LoadSessionState()
        {
            try
            {
                if (!File.Exists(_sessionPath))
                    return false;

                var json = File.ReadAllText(_sessionPath);
                var state = JsonSerializer.Deserialize<AppSessionState>(json);
                if (state == null)
                    return false;

                if (state.PageUrls != null)
                {
                    for (int i = 0; i < _pageUrls.Length && i < state.PageUrls.Length; i++)
                    {
                        _pageUrls[i] = state.PageUrls[i] ?? "";
                    }
                }

                _activePageIndex = state.ActivePageIndex;
                EnsurePanesUpTo(state.LayoutPageCount - 1);

                // Restore URLs into panes
                for (int i = 0; i < _layoutPageCount; i++)
                {
                    // Pane 1 should start on the Home overlay, not restore last page
                    if (i == 0)
                    {
                        _pageUrls[0] = "lexwhite://newtab";
                        continue;
                    }

                    var url = GetSnapBackRestoreUrl(i);
                    if (string.IsNullOrWhiteSpace(url)) continue;

                    int prev = _activePageIndex;
                    _activePageIndex = i;
                    NavigateTo(url);
                    _activePageIndex = prev;
                }

                return true; // session restored
            }
            catch
            {
                return false;
            }
        }

        private sealed class WindowsDnsBackup
        {
            public string AdapterCaption { get; }
            public string[]? DnsServers { get; }

            public WindowsDnsBackup(string adapterCaption, string[]? dnsServers)
            {
                AdapterCaption = adapterCaption;
                DnsServers = dnsServers;
            }
        }

        private readonly string _windowsDnsBackupPath =
            AppDataPath("windows_dns_backup.json");

        private readonly string _dnsHelperResultPath =
            AppDataPath("dns_helper_result.txt");

        private void SaveWindowsDnsBackup(List<WindowsDnsBackup> backup)
        {
            try
            {
                if (backup == null || backup.Count == 0)
                    return;

                Directory.CreateDirectory(Path.GetDirectoryName(_windowsDnsBackupPath)!);

                // One backup represents the DNS state BEFORE LexDesk Pro first
                // took control. Switching between providers must never overwrite it.
                if (File.Exists(_windowsDnsBackupPath))
                    return;

                var json = JsonSerializer.Serialize(
                    backup,
                    JsonIndentedOptions);

                File.WriteAllText(_windowsDnsBackupPath, json);
            }
            catch
            {
                // The caller verifies that the backup file actually exists before
                // allowing a Windows DNS change to continue.
            }
        }

        private List<WindowsDnsBackup> LoadWindowsDnsBackup()
        {
            try
            {
                if (!File.Exists(_windowsDnsBackupPath))
                    return new List<WindowsDnsBackup>();

                var json = File.ReadAllText(_windowsDnsBackupPath);
                return JsonSerializer.Deserialize<List<WindowsDnsBackup>>(json)
                    ?? new List<WindowsDnsBackup>();
            }
            catch
            {
                return new List<WindowsDnsBackup>();
            }
        }

        private bool EnsureOriginalWindowsDnsBackup(out bool createdThisAttempt)
        {
            createdThisAttempt = false;

            try
            {
                if (File.Exists(_windowsDnsBackupPath))
                    return LoadWindowsDnsBackup().Count > 0;

                var backup = CaptureActiveAdaptersDns();
                if (backup.Count == 0)
                    return false;

                SaveWindowsDnsBackup(backup);

                createdThisAttempt = File.Exists(_windowsDnsBackupPath)
                    && LoadWindowsDnsBackup().Count > 0;

                return createdThisAttempt;
            }
            catch
            {
                return false;
            }
        }

        private void DeleteWindowsDnsBackupSafe()
        {
            try
            {
                if (File.Exists(_windowsDnsBackupPath))
                    File.Delete(_windowsDnsBackupPath);
            }
            catch
            {
                // DNS has already been restored; leftover cleanup can be retried later.
            }
        }

        private static List<WindowsDnsBackup> CaptureActiveAdaptersDns()
        {
            var result = new List<WindowsDnsBackup>();

            using var searcher = new ManagementObjectSearcher(
                "SELECT * FROM Win32_NetworkAdapterConfiguration WHERE IPEnabled=TRUE");

            foreach (ManagementBaseObject mo in searcher.Get())
            {
                var gateways = mo["DefaultIPGateway"] as string[];
                if (gateways == null || gateways.Length == 0)
                    continue;

                var caption = (mo["Caption"] as string) ?? "Unknown Adapter";
                var dns = mo["DNSServerSearchOrder"] as string[];

                result.Add(new WindowsDnsBackup(
                    caption,
                    dns == null ? null : dns.ToArray()));
            }

            return result;
        }

        private static void InvokeSetDnsOrThrow(ManagementObject adapter, string[]? dnsServers)
        {
            var input = adapter.GetMethodParameters("SetDNSServerSearchOrder");
            input["DNSServerSearchOrder"] = dnsServers;

            using var output = adapter.InvokeMethod(
                "SetDNSServerSearchOrder",
                input,
                null);

            uint returnValue = 0;

            try
            {
                if (output?["ReturnValue"] != null)
                    returnValue = Convert.ToUInt32(output["ReturnValue"]);
            }
            catch
            {
                returnValue = 0;
            }

            // WMI: 0 = success, 1 = success/reboot required. Anything else is failure.
            if (returnValue != 0 && returnValue != 1)
                throw new InvalidOperationException($"Windows returned DNS error code {returnValue}.");
        }

        private static void SetWindowsIpv4DnsOnActiveAdapters(DnsPreset preset)
        {
            var (dns, dhcp) = GetIpv4DnsForPreset(preset);
            int appliedCount = 0;

            using var searcher = new ManagementObjectSearcher(
                "SELECT * FROM Win32_NetworkAdapterConfiguration WHERE IPEnabled=TRUE");

            foreach (ManagementObject mo in searcher.Get().Cast<ManagementObject>())
            {
                var gateways = mo["DefaultIPGateway"] as string[];
                if (gateways == null || gateways.Length == 0)
                    continue;

                InvokeSetDnsOrThrow(mo, dhcp ? null : dns);
                appliedCount++;
            }

            if (appliedCount == 0)
                throw new InvalidOperationException("No active Windows network adapter was found.");
        }

        private static void RestoreWindowsIpv4DnsFromBackup(List<WindowsDnsBackup> backup)
        {
            if (backup == null || backup.Count == 0)
                throw new InvalidOperationException("The saved Windows DNS backup is empty.");

            int restoredCount = 0;

            using var searcher = new ManagementObjectSearcher(
                "SELECT * FROM Win32_NetworkAdapterConfiguration WHERE IPEnabled=TRUE");

            foreach (ManagementObject mo in searcher.Get().Cast<ManagementObject>())
            {
                var gateways = mo["DefaultIPGateway"] as string[];
                if (gateways == null || gateways.Length == 0)
                    continue;

                var caption = (mo["Caption"] as string) ?? "";
                var match = backup.FirstOrDefault(b =>
                    caption.Equals(b.AdapterCaption, StringComparison.OrdinalIgnoreCase) ||
                    caption.Contains(b.AdapterCaption, StringComparison.OrdinalIgnoreCase) ||
                    b.AdapterCaption.Contains(caption, StringComparison.OrdinalIgnoreCase));

                if (match == null)
                    continue;

                InvokeSetDnsOrThrow(mo, match.DnsServers);
                restoredCount++;
            }

            if (restoredCount == 0)
                throw new InvalidOperationException("The saved DNS adapter could not be matched to the current Windows network adapter.");
        }

        private static (string[]? dns, bool dhcp) GetIpv4DnsForPreset(DnsPreset preset) => preset switch
        {
            DnsPreset.Cloudflare => (new[] { "1.1.1.2", "1.0.0.2" }, false),
            DnsPreset.CloudflareFamily => (new[] { "1.1.1.3", "1.0.0.3" }, false),
            DnsPreset.Quad9 => (new[] { "9.9.9.9", "149.112.112.112" }, false),
            DnsPreset.Google => (new[] { "8.8.8.8", "8.8.4.4" }, false),
            DnsPreset.OpenDNS => (new[] { "208.67.222.222", "208.67.220.220" }, false),
            DnsPreset.AdGuard => (new[] { "94.140.14.14", "94.140.15.15" }, false),
            DnsPreset.CleanBrowsing => (new[] { "185.228.168.9", "185.228.169.9" }, false),
            DnsPreset.ControlD => (new[] { "76.76.2.1", "76.76.10.1" }, false),
            DnsPreset.VerisignPublic => (new[] { "156.154.70.2", "156.154.71.2" }, false),
            DnsPreset.SystemDefault => ((string[]?)null, true),
            _ => ((string[]?)null, true)
        };

        private static void FlushWindowsDnsCache()
        {
            try
            {
                using var process = Process.Start(new ProcessStartInfo
                {
                    FileName = "ipconfig.exe",
                    Arguments = "/flushdns",
                    UseShellExecute = false,
                    CreateNoWindow = true,
                    WindowStyle = ProcessWindowStyle.Hidden
                });

                process?.WaitForExit(5000);
            }
            catch
            {
                // A failed cache flush does not undo a successful DNS setting change.
            }
        }

        private void WriteDnsHelperResult(string text)
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(_dnsHelperResultPath)!);
                File.WriteAllText(_dnsHelperResultPath, text ?? "ERROR|Unknown DNS helper result");
            }
            catch { }
        }

        private bool TryRunElevatedDnsHelperFromCommandLine()
        {
            string[] args = Environment.GetCommandLineArgs();
            int helperIndex = Array.FindIndex(args, a =>
                string.Equals(a, "--dns-helper", StringComparison.OrdinalIgnoreCase));

            if (helperIndex < 0)
                return false;

            try
            {
                if (!IsRunningAsAdmin())
                {
                    WriteDnsHelperResult("ERROR|Windows administrator permission was not granted.");
                    return true;
                }

                string action = helperIndex + 1 < args.Length
                    ? args[helperIndex + 1]
                    : "";

                if (action.Equals("apply", StringComparison.OrdinalIgnoreCase))
                {
                    string presetText = helperIndex + 2 < args.Length
                        ? args[helperIndex + 2]
                        : "";

                    if (!Enum.TryParse(presetText, out DnsPreset preset))
                        throw new InvalidOperationException("The requested DNS provider was not recognised.");

                    SetWindowsIpv4DnsOnActiveAdapters(preset);
                    FlushWindowsDnsCache();
                    WriteDnsHelperResult("OK");
                    return true;
                }

                if (action.Equals("restore", StringComparison.OrdinalIgnoreCase))
                {
                    var backup = LoadWindowsDnsBackup();
                    if (backup.Count == 0)
                        throw new InvalidOperationException("The saved Windows DNS backup could not be found.");

                    RestoreWindowsIpv4DnsFromBackup(backup);
                    FlushWindowsDnsCache();
                    WriteDnsHelperResult("OK");
                    return true;
                }

                throw new InvalidOperationException("The DNS helper action was not recognised.");
            }
            catch (Exception ex)
            {
                string safeMessage = (ex.Message ?? "DNS helper failed")
                    .Replace("\r", " ")
                    .Replace("\n", " ")
                    .Trim();

                WriteDnsHelperResult("ERROR|" + safeMessage);
                return true;
            }
        }

        private bool RunElevatedDnsHelper(string action, DnsPreset? preset, out string error)
        {
            error = "";

            try
            {
                try
                {
                    if (File.Exists(_dnsHelperResultPath))
                        File.Delete(_dnsHelperResultPath);
                }
                catch { }

                string exePath = Process.GetCurrentProcess().MainModule?.FileName ?? "";
                if (string.IsNullOrWhiteSpace(exePath))
                {
                    error = "LexDesk Pro could not locate its own program file.";
                    return false;
                }

                string arguments = preset.HasValue
                    ? $"--dns-helper {action} {preset.Value}"
                    : $"--dns-helper {action}";

                var psi = new ProcessStartInfo
                {
                    FileName = exePath,
                    Arguments = arguments,
                    UseShellExecute = true,
                    Verb = "runas"
                };

                using var helper = Process.Start(psi);
                if (helper == null)
                {
                    error = "Windows did not start the permission helper.";
                    return false;
                }

                helper.WaitForExit();

                if (!File.Exists(_dnsHelperResultPath))
                {
                    error = "Windows permission was cancelled or the DNS helper did not complete.";
                    return false;
                }

                string result = (File.ReadAllText(_dnsHelperResultPath) ?? "").Trim();

                try { File.Delete(_dnsHelperResultPath); } catch { }

                if (result.Equals("OK", StringComparison.OrdinalIgnoreCase))
                    return true;

                if (result.StartsWith("ERROR|", StringComparison.OrdinalIgnoreCase))
                    error = result.Substring("ERROR|".Length).Trim();
                else
                    error = "Windows DNS could not be changed.";

                return false;
            }
            catch (System.ComponentModel.Win32Exception)
            {
                error = "Windows administrator permission was cancelled.";
                return false;
            }
            catch (Exception ex)
            {
                error = SanitizeExceptionMessage(ex);
                return false;
            }
        }

        private bool ApplyDnsPresetWithPermission(DnsPreset preset, out string error)
        {
            error = "";

            try
            {
                if (IsRunningAsAdmin())
                {
                    SetWindowsIpv4DnsOnActiveAdapters(preset);
                    FlushWindowsDnsCache();
                    return true;
                }

                return RunElevatedDnsHelper("apply", preset, out error);
            }
            catch (Exception ex)
            {
                error = SanitizeExceptionMessage(ex);
                return false;
            }
        }

        private bool RestoreWindowsDnsWithPermission(out string error)
        {
            error = "";

            try
            {
                if (IsRunningAsAdmin())
                {
                    var backup = LoadWindowsDnsBackup();
                    if (backup.Count == 0)
                    {
                        error = "The saved Windows DNS backup could not be found.";
                        return false;
                    }

                    RestoreWindowsIpv4DnsFromBackup(backup);
                    FlushWindowsDnsCache();
                    return true;
                }

                return RunElevatedDnsHelper("restore", null, out error);
            }
            catch (Exception ex)
            {
                error = SanitizeExceptionMessage(ex);
                return false;
            }
        }

        private string BuildWebView2EnvironmentArguments()
        {
            try
            {
                var args = new List<string>();

                // App-only Secure DNS.
                if (_dnsMode == DnsApplyMode.AppOnlySecureDns)
                {
                    string dnsArgs = BuildWebView2ArgumentsForDns(_dnsPreset);

                    if (!string.IsNullOrWhiteSpace(dnsArgs))
                        args.Add(dnsArgs);
                }

                // Future Stage 4B:
                // App-only Privacy Relay proxy arguments will be added here.
                //
                // Important:
                // WebView2 environment arguments are applied when the shared environment is created.
                // A real Privacy Relay proxy change may require WebView2/app restart.

                string privacyRelayProxyArgs = BuildPrivacyRelayWebView2ProxyArgumentsForStartup();

                if (!string.IsNullOrWhiteSpace(privacyRelayProxyArgs))
                    args.Add(privacyRelayProxyArgs);

                return string.Join(" ", args.Where(a => !string.IsNullOrWhiteSpace(a)));
            }
            catch
            {
                return "";
            }
        }

        private string BuildPrivacyRelayWebView2ProxyArgumentsForStartup()
        {
            try
            {
                if (!TryLoadPrivacyRelayStartupConfig(out PrivacyRelayStartupConfig config))
                    return "";

                // Developer test configs are for checking the startup state flow only.
                // They must NOT apply a fake proxy to WebView2, otherwise normal browsing
                // could appear broken until the app is restarted again.
                if (config.DeveloperTestOnly)
                    return "";

                string proxyArg = BuildPrivacyRelayProxyArgument(config.ProxyHost, config.ProxyPort);

                return proxyArg;
            }
            catch
            {
                return "";
            }
        }

        private bool TryLoadPrivacyRelayStartupConfig(out PrivacyRelayStartupConfig config)
        {
            config = new PrivacyRelayStartupConfig();

            try
            {
                if (!File.Exists(_privacyRelayStartupConfigPath))
                    return false;

                string json = File.ReadAllText(_privacyRelayStartupConfigPath);

                PrivacyRelayStartupConfig? loaded =
                    JsonSerializer.Deserialize<PrivacyRelayStartupConfig>(json);

                if (loaded == null)
                {
                    ClearPrivacyRelayStartupConfig();
                    return false;
                }

                if (!loaded.Enabled)
                {
                    ClearPrivacyRelayStartupConfig();
                    return false;
                }

                if (string.IsNullOrWhiteSpace(loaded.ProxyHost) || loaded.ProxyPort <= 0)
                {
                    ClearPrivacyRelayStartupConfig();
                    return false;
                }

                string proxyArg = BuildPrivacyRelayProxyArgument(loaded.ProxyHost, loaded.ProxyPort);

                if (string.IsNullOrWhiteSpace(proxyArg))
                {
                    ClearPrivacyRelayStartupConfig();
                    return false;
                }

                if (string.IsNullOrWhiteSpace(loaded.Location) ||
                    string.IsNullOrWhiteSpace(loaded.RegionCode))
                {
                    ClearPrivacyRelayStartupConfig();
                    return false;
                }

                if (string.IsNullOrWhiteSpace(loaded.SavedUtc))
                {
                    ClearPrivacyRelayStartupConfig();
                    return false;
                }

                if (!DateTimeOffset.TryParse(loaded.SavedUtc, out DateTimeOffset savedUtc))
                {
                    ClearPrivacyRelayStartupConfig();
                    return false;
                }

                DateTimeOffset nowUtc = DateTimeOffset.UtcNow;

                // Guard against stale relay startup config.
                // If the user does not restart soon after preparing Privacy Relay,
                // clear the saved proxy config and fall back to normal browsing.
                if (nowUtc - savedUtc.ToUniversalTime() > PrivacyRelayStartupConfigMaxAge)
                {
                    ClearPrivacyRelayStartupConfig();
                    return false;
                }

                // Guard against a badly wrong future timestamp.
                if (savedUtc.ToUniversalTime() > nowUtc.AddMinutes(5))
                {
                    ClearPrivacyRelayStartupConfig();
                    return false;
                }

                config = loaded;
                return true;
            }
            catch
            {
                ClearPrivacyRelayStartupConfig();
                config = new PrivacyRelayStartupConfig();
                return false;
            }
        }

        private string BuildPrivacyRelayProxyArgument(string proxyHost, int proxyPort)
        {
            try
            {
                string host = (proxyHost ?? "").Trim();

                if (string.IsNullOrWhiteSpace(host) || proxyPort <= 0)
                    return "";

                host = host
                    .Replace("https://", "", StringComparison.OrdinalIgnoreCase)
                    .Replace("http://", "", StringComparison.OrdinalIgnoreCase)
                    .Trim()
                    .Trim('/');

                if (string.IsNullOrWhiteSpace(host) ||
                    host.Contains(" ") ||
                    host.Contains("\"") ||
                    host.Contains("/"))
                {
                    return "";
                }

                return $"--proxy-server=http://{host}:{proxyPort}";
            }
            catch
            {
                return "";
            }
        }

        private bool SavePrivacyRelayStartupConfig(PrivacyRelayApiResponse relayResponse)
        {
            try
            {
                if (relayResponse == null)
                    return false;

                if (!relayResponse.Allowed ||
                    string.IsNullOrWhiteSpace(relayResponse.ProxyHost) ||
                    relayResponse.ProxyPort <= 0)
                {
                    return false;
                }

                string proxyArg = BuildPrivacyRelayProxyArgument(
                    relayResponse.ProxyHost,
                    relayResponse.ProxyPort);

                if (string.IsNullOrWhiteSpace(proxyArg))
                    return false;

                if (string.IsNullOrWhiteSpace(relayResponse.Location) ||
                    string.IsNullOrWhiteSpace(relayResponse.RegionCode))
                {
                    return false;
                }

                var config = new PrivacyRelayStartupConfig
                {
                    Enabled = true,
                    Location = relayResponse.Location ?? "",
                    RegionCode = relayResponse.RegionCode ?? "",
                    ProxyHost = relayResponse.ProxyHost ?? "",
                    ProxyPort = relayResponse.ProxyPort,
                    SavedUtc = DateTimeOffset.UtcNow.ToString("O")
                };

                Directory.CreateDirectory(Path.GetDirectoryName(_privacyRelayStartupConfigPath)!);

                string json = JsonSerializer.Serialize(
                    config,
                    JsonIndentedOptions);

                File.WriteAllText(_privacyRelayStartupConfigPath, json);


                _privacyRelayStartupCheckPending = false;
                _privacyRelayActiveStartupConfig = null;
                _privacyRelayLastConfirmedIp = "";
                _privacyRelayLastCheckStatus = "";

                return true;
            }
            catch
            {
                return false;
            }
        }

