                Directory.CreateDirectory(Path.GetDirectoryName(_privacyRelayStartupConfigPath)!);

                string json = JsonSerializer.Serialize(
                    config,
                    JsonIndentedOptions);

                File.WriteAllText(_privacyRelayStartupConfigPath, json);


                _privacyRelayStartupCheckPending = false;
                _privacyRelayActiveStartupConfig = null;
                _privacyRelayLastConfirmedIp = "";
                _privacyRelayLastCheckStatus = "";

                return true;
            }
            catch
            {
