            }
        }

        private void PreparePrivacyRelayDeveloperStartupTest()
        {
            if (!HasFullUnlock())
            {
                ShowProtectionPopup(
                    "LexDesk Pro - Privacy Relay",
                    "Activation required",
                    "Please activate LexDesk Pro before testing Privacy Relay startup flow.",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            bool saved = SavePrivacyRelayDeveloperStartupTestConfig();

            if (!saved)
            {
                ShowProtectionPopup(
                    "LexDesk Pro - Privacy Relay",
                    "Developer test could not be prepared",
                    "LexDesk Pro could not save the developer Privacy Relay startup test config.",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
                return;
            }

            _privacyRelayState = PrivacyRelayState.RestartRequired;
            RefreshPrivacyNetworkVisuals();

            ShowProtectionPopup(
                "LexDesk Pro - Privacy Relay",
                "Developer relay startup test prepared",
                "A safe developer-only Privacy Relay startup test has been prepared.\n\n" +
                "No real proxy has been applied.\n\n" +
                "Restart LexDesk Pro to test this flow:\n\n" +
                "Restart Required → Checking → Failed / relay_check_api_not_connected",
                MessageBoxButton.OK,
                MessageBoxImage.Information);
        }

        private void ClearPrivacyRelayStartupConfig()
        {
            try
            {
                if (File.Exists(_privacyRelayStartupConfigPath))
                    File.Delete(_privacyRelayStartupConfigPath);
            }
            catch
            {
                // Clearing relay startup state must never affect browsing.
            }


            _privacyRelayStartupCheckPending = false;
            _privacyRelayActiveStartupConfig = null;
        }

        private void LoadPrivacyRelayStartupAwareness()
        {
            try
            {
                if (TryLoadPrivacyRelayStartupConfig(out PrivacyRelayStartupConfig config))
                {
                    _privacyRelayActiveStartupConfig = config;
                    _privacyRelayStartupCheckPending = true;


                    // Important:
                    // A saved startup config only means the relay proxy argument was prepared.
                    // It does NOT mean Privacy Relay is protected yet.
                    // Stage 4C will confirm the public IP before Protected is allowed.
                    _privacyRelayState = PrivacyRelayState.Checking;
                    _hideIpEnabled = false;

                    return;
                }

                _privacyRelayActiveStartupConfig = null;
                _privacyRelayStartupCheckPending = false;
            }
            catch
            {
                _privacyRelayActiveStartupConfig = null;
                _privacyRelayStartupCheckPending = false;
                _privacyRelayState = PrivacyRelayState.NotConnected;
                _hideIpEnabled = false;
            }
        }

        private async Task RunPrivacyRelayStartupConfirmationIfNeededAsync()
        {
            try
            {
                if (PrivacyRelayPublicComingSoonOnly)
                {
                    ClearPrivacyRelayStartupConfig();
                    RemovePrivacyRelayProxy();

                    _privacyRelayActiveStartupConfig = null;
                    _privacyRelayStartupCheckPending = false;
                    _privacyRelayState = PrivacyRelayState.NotConnected;
                    _hideIpEnabled = false;
                    _privacyRelayLastConfirmedIp = "";
                    _privacyRelayLastCheckStatus = "";

                    RefreshPrivacyNetworkVisuals();
                    return;
                }

                if (!_privacyRelayStartupCheckPending)
                    return;

                if (_privacyRelayActiveStartupConfig == null)
                    return;

                _privacyRelayState = PrivacyRelayState.Checking;
                _hideIpEnabled = false;
                RefreshPrivacyNetworkVisuals();

                PrivacyRelayIpCheckResult checkResult =
                    await ConfirmPrivacyRelayStartupAsync(_privacyRelayActiveStartupConfig);

                _privacyRelayLastCheckStatus = checkResult.Status ?? "";
                _privacyRelayLastConfirmedIp = checkResult.PublicIp ?? "";

                if (!checkResult.Confirmed)
                {
                    ClearPrivacyRelayStartupConfig();

                    _privacyRelayState = PrivacyRelayState.Failed;
                    _hideIpEnabled = false;
                    RefreshPrivacyNetworkVisuals();

                    ShowProtectionPopup(
                        "LexDesk Pro - Privacy Relay",
                        "Privacy Relay could not be confirmed",
                        "LexDesk Pro found Privacy Relay startup settings, but protection could not be confirmed.\n\n" +
                        $"Relay location: {checkResult.Location}\n" +
                        $"Region code: {checkResult.RegionCode}\n" +
                        $"Status: {checkResult.Status}\n\n" +
                        checkResult.Message + "\n\n" +
                        "LexDesk Pro has returned browsing to your normal internet connection.",
                        MessageBoxButton.OK,
                        MessageBoxImage.Warning);

                    return;
                }

                _privacyRelayStartupCheckPending = false;


                _privacyRelayState = PrivacyRelayState.Protected;
                _hideIpEnabled = true;
                RefreshPrivacyNetworkVisuals();

                ShowProtectionPopup(
                    "LexDesk Pro - Privacy Relay",
                    "Privacy Relay protected",
                    "Privacy Relay has been confirmed.\n\n" +
                    $"Relay location: {checkResult.Location}\n" +
                    $"Region code: {checkResult.RegionCode}\n" +
                    $"Public IP: {checkResult.PublicIp}",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
            }
            catch (Exception ex)
            {
                ClearPrivacyRelayStartupConfig();

                _privacyRelayState = PrivacyRelayState.Failed;
                _hideIpEnabled = false;
                RefreshPrivacyNetworkVisuals();

                ShowProtectionPopup(
                    "LexDesk Pro - Privacy Relay",
                    "Privacy Relay confirmation failed",
                    "LexDesk Pro could not confirm Privacy Relay protection.\n\n" +
                    SanitizeExceptionMessage(ex) + "\n\n" +
                    "Your browsing is using your normal internet connection.",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
            }
        }

        private PrivacyRelayCheckApiRequest BuildPrivacyRelayCheckApiRequest(PrivacyRelayStartupConfig config)
        {
            string appVersion = "0.0.0.0";

            try
            {
                appVersion = Assembly.GetExecutingAssembly()
                    .GetName()
                    .Version?
                    .ToString() ?? "0.0.0.0";
            }
            catch
            {
                appVersion = "0.0.0.0";
            }

            return new PrivacyRelayCheckApiRequest
            {
                // Never send or store the raw licence key here.
                LicenseHash = LoadSavedLicenseHash() ?? "",
                DeviceFingerprint = GetDeviceFingerprint(),
                DeviceLabel = GetPrivacySafeDeviceLabel(),
                ExpectedLocation = config?.Location ?? "",
                ExpectedRegionCode = config?.RegionCode ?? "",
                AppVersion = appVersion
            };
        }


        private async Task<PrivacyRelayIpCheckResult> ConfirmPrivacyRelayStartupAsync(PrivacyRelayStartupConfig config)
        {
            try
            {
                PrivacyRelayCheckApiResponse relayCheck =
                    await RequestPrivacyRelayCheckAsync(config);

                return new PrivacyRelayIpCheckResult
                {
                    Confirmed = relayCheck.Confirmed,
                    Status = relayCheck.Status ?? "",
                    Message = relayCheck.Message ?? "",
                    PublicIp = relayCheck.PublicIp ?? "",
                    Location = relayCheck.Location ?? config?.Location ?? "",
                    RegionCode = relayCheck.RegionCode ?? config?.RegionCode ?? ""
                };
            }
            catch
            {
                return new PrivacyRelayIpCheckResult
                {
                    Confirmed = false,
                    Status = "ip_check_error",
                    Message = "Privacy Relay public IP confirmation could not run.",
                    PublicIp = "",
                    Location = config?.Location ?? "",
                    RegionCode = config?.RegionCode ?? ""
                };
            }
        }

        private static string BuildWebView2ArgumentsForDns(DnsPreset preset)
        {
            if (preset == DnsPreset.SystemDefault)
                return "";

            var doh = preset switch
            {
                DnsPreset.Cloudflare => "https://security.cloudflare-dns.com/dns-query",
                DnsPreset.Quad9 => "https://dns.quad9.net/dns-query",
                DnsPreset.Google => "https://dns.google/dns-query",
                DnsPreset.OpenDNS => "https://doh.opendns.com/dns-query",
                DnsPreset.AdGuard => "https://dns.adguard-dns.com/dns-query",
                DnsPreset.CleanBrowsing => "https://doh.cleanbrowsing.org/doh/security-filter/",
                DnsPreset.ControlD => "https://freedns.controld.com/p1",

                // I would leave Verisign blank for app-only mode until an official public DoH endpoint is confirmed
                DnsPreset.VerisignPublic => "",

                _ => ""
            };

            if (string.IsNullOrWhiteSpace(doh))
                return "";

            return $"--dns-over-https-mode=secure --dns-over-https-servers=\"{doh}\"";
        }
        private bool HasAnyPrintersInstalled()
        {
            try
            {
                var server = new System.Printing.LocalPrintServer();
                var queues = server.GetPrintQueues();
                return queues != null && queues.Any();
            }
            catch
            {
                return false;
            }
        }

        private string GetActivePaneRealUrl()
        {
            try
            {
                var wv = GetActiveWebView();
                var src = wv?.CoreWebView2?.Source;
                if (!string.IsNullOrWhiteSpace(src))
                    return src;
            }
            catch { }

            var tracked = _pageUrls[_activePageIndex];
            return string.IsNullOrWhiteSpace(tracked) ? "" : tracked;
        }

        private bool PaneHasLoadedContent(int index)
        {
            if (index < 0 || index > 3) return false;
            if (_paneState[index] == PaneLifeState.Closed) return false;

            string trackedUrl = _pageUrls[index] ?? "";
            string liveUrl = "";

            try
            {
                var wv = GetWebView(index);
                liveUrl = wv?.CoreWebView2?.Source ?? "";
            }
            catch
            {
                liveUrl = "";
            }

            // Trust explicit parked/blank tracked state over stale WebView source
            string url =
                trackedUrl.Equals("lexwhite://newtab", StringComparison.OrdinalIgnoreCase) ||
                trackedUrl.Equals("about:blank", StringComparison.OrdinalIgnoreCase)
                    ? trackedUrl
                    : (!string.IsNullOrWhiteSpace(liveUrl) ? liveUrl : trackedUrl);

            if (string.IsNullOrWhiteSpace(url)) return false;
            if (url.Equals("about:blank", StringComparison.OrdinalIgnoreCase)) return false;
            if (url.Equals("lexwhite://newtab", StringComparison.OrdinalIgnoreCase)) return false;

            return true;
        }

        private bool IsTrackedPaneBlank(int index)
        {
            if (index < 0 || index > 3)
                return true;

            string url = (_pageUrls[index] ?? "").Trim();

            return string.IsNullOrWhiteSpace(url) ||
                   url.Equals("about:blank", StringComparison.OrdinalIgnoreCase) ||
                   url.Equals("lexwhite://newtab", StringComparison.OrdinalIgnoreCase);
        }

        private bool IsStartupPlaceholderUrl(string url)
        {
            url = (url ?? "").Trim();

            return string.IsNullOrWhiteSpace(url) ||
                   url.Equals("about:blank", StringComparison.OrdinalIgnoreCase) ||
                   url.Equals("lexwhite://newtab", StringComparison.OrdinalIgnoreCase);
        }

        private string GetSnapBackRestoreUrl(int paneIndex)
        {
            string url = "";

            if (paneIndex >= 0 && paneIndex < _pageUrls.Length)
                url = _pageUrls[paneIndex] ?? "";

            if (string.IsNullOrWhiteSpace(url) ||
                url.Equals("about:blank", StringComparison.OrdinalIgnoreCase) ||
                url.Equals("lexwhite://newtab", StringComparison.OrdinalIgnoreCase))
            {
                if (paneIndex >= 0 &&
                    paneIndex < _presetUrls.Length &&
                    !string.IsNullOrWhiteSpace(_presetUrls[paneIndex]))
                {
                    url = _presetUrls[paneIndex];
                }
                else
                {
                    url = _homeUrl;
                }
            }


            // Snap Back should not restore fragile login/auth/session URLs.
            if (IsSensitiveLoginUrl(url))
            {
                var safe = GetCleanSensitiveSiteEntryUrl(url);
                if (!string.IsNullOrWhiteSpace(safe))
                    url = safe;
                else
                    url = _homeUrl;
            }

            return url;
        }

        private string GetSavedNavigationUrl(string? url)
        {
            if (string.IsNullOrWhiteSpace(url))
                return _homeUrl;

            string resolved = url;

            if (IsSensitiveLoginUrl(resolved))
            {
                var safe = GetCleanSensitiveSiteEntryUrl(resolved);
                if (!string.IsNullOrWhiteSpace(safe))
                    resolved = safe;
                else
                    resolved = _homeUrl;
            }

            return resolved;
        }

        private static string FormatUrlForDisplay(string? url)
        {
            if (string.IsNullOrWhiteSpace(url)) return "";
            url = url.Trim();

            if (url.StartsWith("lexwhite://", StringComparison.OrdinalIgnoreCase)) return url;
            if (url.StartsWith("about:", StringComparison.OrdinalIgnoreCase)) return url;

            if (Uri.TryCreate(url, UriKind.Absolute, out var u))
            {
                if (u.Scheme.Equals("https", StringComparison.OrdinalIgnoreCase) ||
                    u.Scheme.Equals("http", StringComparison.OrdinalIgnoreCase))
                {
                    var host = u.Host;
                    if (host.StartsWith("www.", StringComparison.OrdinalIgnoreCase))
                        host = host.Substring(4);

                    var display = host + u.PathAndQuery + u.Fragment;
                    return string.IsNullOrWhiteSpace(display) ? url : display;
                }
            }

            return url;
        }


        private static bool LooksLikeDomain(string input)
        {
            if (string.IsNullOrWhiteSpace(input)) return false;
            input = input.Trim();

            if (input.Equals("localhost", StringComparison.OrdinalIgnoreCase))
                return true;

            if (System.Net.IPAddress.TryParse(input, out _))
                return true;

            if (input.Contains('.') && !input.Any(char.IsWhiteSpace))
                return true;

            return false;
        }

        private bool TryBuildKnownSiteShortcut(string input, out Uri? uri)
        {
            uri = null;

            string value = (input ?? "").Trim().ToLowerInvariant();

            if (string.IsNullOrWhiteSpace(value))
                return false;

            // Only treat simple one-word entries as direct site shortcuts.
            // Multi-word input should still behave like a normal search.
            if (value.Contains(" ") || value.Contains(".") || value.Contains("/") || value.Contains(":"))
                return false;

            string? directUrl = value switch
            {
                "youtube" => "https://www.youtube.com/",
                "google" => "https://www.google.com/",
                "bing" => "https://www.bing.com/",
                "facebook" => "https://www.facebook.com/",
                "instagram" => "https://www.instagram.com/",
                "x" => "https://x.com/",
                "twitter" => "https://x.com/",
                "reddit" => "https://www.reddit.com/",
                "amazon" => "https://www.amazon.com/",
                "ebay" => "https://www.ebay.com/",
                "realestate" => "https://www.realestate.com.au/",
                "realestatecomau" => "https://www.realestate.com.au/",
                "trademe" => "https://www.trademe.co.nz/",
                _ => null
            };

            if (string.IsNullOrWhiteSpace(directUrl))
                return false;

            uri = new Uri(directUrl);
            return true;
        }

        private string GetSearchRegionQueryHint(SearchRegion region)
        {
            return region switch
            {
                SearchRegion.Australia => "Australia",
                SearchRegion.NewZealand => "New Zealand",
                SearchRegion.UnitedKingdom => "United Kingdom",
                SearchRegion.UnitedStates => "United States",
                SearchRegion.Canada => "Canada",
                _ => ""
            };
        }

        private string GetDuckDuckGoRegionCode(SearchRegion region)
        {
            return region switch
            {
                SearchRegion.Australia => "au-en",
                SearchRegion.NewZealand => "nz-en",
                SearchRegion.UnitedKingdom => "uk-en",
                SearchRegion.UnitedStates => "us-en",
                SearchRegion.Canada => "ca-en",
                _ => ""
            };
        }

        private Uri BuildSearchUri(string query)
        {
            string cleanQuery = (query ?? "").Trim();
            string regionHint = GetSearchRegionQueryHint(_searchRegion);

            // DuckDuckGo publishes a region URL parameter, so keep the user's
            // actual search words untouched there. For the other providers we
            // use a conservative country-name hint rather than depending on
            // undocumented provider parameters that can change without notice.
            bool duckHasNativeRegion =
                _searchEngine == SearchEngine.DuckDuckGo &&
                _searchRegion != SearchRegion.Automatic;

            string effectiveQuery =
                _searchRegion == SearchRegion.Automatic || duckHasNativeRegion
                    ? cleanQuery
                    : $"{cleanQuery} {regionHint}".Trim();

            var q = Uri.EscapeDataString(effectiveQuery);
            string duckRegion = GetDuckDuckGoRegionCode(_searchRegion);
            string duckRegionPart = string.IsNullOrWhiteSpace(duckRegion)
                ? ""
                : $"&kl={Uri.EscapeDataString(duckRegion)}";

            var url = _searchEngine switch
            {
                SearchEngine.Bing => $"https://www.bing.com/search?q={q}",
                SearchEngine.DuckDuckGo => $"https://duckduckgo.com/?q={q}{duckRegionPart}",
                SearchEngine.PerplexityAI => $"https://www.perplexity.ai/search?q={q}",
                SearchEngine.Startpage => $"https://www.startpage.com/sp/search?q={q}",
                SearchEngine.Brave => $"https://search.brave.com/search?q={q}",
                SearchEngine.Ecosia => $"https://www.ecosia.org/search?q={q}",
                SearchEngine.Qwant => $"https://www.qwant.com/?q={q}",
                SearchEngine.Yahoo => $"https://search.yahoo.com/search?p={q}",
                SearchEngine.Google => $"https://www.google.com/search?q={q}",
                _ => $"https://www.google.com/search?q={q}"
            };

            return new Uri(url);
        }

