        private void ApplyTheme(AppTheme theme)
        {
            void SetBrush(string key, string hex)
            {
                var color = (Color)ColorConverter.ConvertFromString(hex);

                if (Resources.Contains(key))
                    Resources[key] = new SolidColorBrush(color);
            }

            if (theme == AppTheme.Light)
            {
                // Polished monochrome light palette shared with Web Privacy Pro.
                // Cool white surfaces, charcoal text/icons and restrained blue accents.
                SetBrush("AppBg", "#FFF7F8FA");
                SetBrush("TopBarBg", "#FFF7F8FA");

                SetBrush("ButtonBg", "#FFFFFFFF");
                SetBrush("ButtonBorder", "#FFC1CBD8");
                SetBrush("ButtonHoverBg", "#FFE7EDF3");
